import { useState, useEffect, useCallback, useRef } from 'react';
import {
  apiClient,
  ApiError,
  setToken,
  removeToken,
} from './client';
import {
  authApi,
  accountApi,
  tradingApi,
  marketApi,
  notificationsApi,
  economicCalendarApi,
  LoginCredentials,
  CreateOrderRequest,
  User,
  AccountSummary,
  Transaction,
  EquityHistoryPoint,
  Position,
  Order,
  Symbol,
  Quote,
  Notification,
  EconomicEvent,
} from './endpoints';

// ====================
// Generic Types
// ====================

interface UseApiState<T> {
  data: T | null;
  loading: boolean;
  error: ApiError | null;
}

interface UseApiReturn<T> extends UseApiState<T> {
  refetch: () => Promise<void>;
  reset: () => void;
}

// ====================
// Generic Hook Factory
// ====================

function createUseApiHook<T>(fetchFn: () => Promise<T>, deps: unknown[] = []) {
  return function useApiHook(): UseApiReturn<T> {
    const [state, setState] = useState<UseApiState<T>>({
      data: null,
      loading: true,
      error: null,
    });

    const fetchData = useCallback(async () => {
      setState(prev => ({ ...prev, loading: true, error: null }));
      try {
        const data = await fetchFn();
        setState({ data, loading: false, error: null });
      } catch (error) {
        setState({
          data: null,
          loading: false,
          error: error instanceof ApiError ? error : new ApiError(0, 'Unknown error'),
        });
      }
    }, []);

    const reset = useCallback(() => {
      setState({ data: null, loading: false, error: null });
    }, []);

    useEffect(() => {
      fetchData();
    }, deps);

    return { ...state, refetch: fetchData, reset };
  };
}

// ====================
// Auth Hooks
// ====================

export const useLogin = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<ApiError | null>(null);

  const login = useCallback(async (credentials: LoginCredentials) => {
    setLoading(true);
    setError(null);
    try {
      const response = await authApi.login(credentials);
      setToken(response.access_token);
      return response;
    } catch (err) {
      const apiError = err instanceof ApiError ? err : new ApiError(0, 'Login failed');
      setError(apiError);
      throw apiError;
    } finally {
      setLoading(false);
    }
  }, []);

  return { login, loading, error };
};

export const useLogout = () => {
  const [loading, setLoading] = useState(false);

  const logout = useCallback(async () => {
    setLoading(true);
    try {
      await authApi.logout();
    } finally {
      removeToken();
      setLoading(false);
    }
  }, []);

  return { logout, loading };
};

// export const useCurrentUser = () => {
//   return createUseApiHook<User>(() => authApi.me(), [])();
// };

// ====================
// Account Hooks
// ====================

export const useAccount = () => {
  return createUseApiHook<AccountSummary>(() => accountApi.getSummary(), [])();
};

interface UseTransactionsParams {
  startDate?: string;
  endDate?: string;
  type?: string;
  limit?: number;
  offset?: number;
}

export const useTransactions = (params?: UseTransactionsParams) => {
  const [state, setState] = useState<UseApiState<{ transactions: Transaction[]; total: number }>>({
    data: null,
    loading: true,
    error: null,
  });

  const fetchTransactions = useCallback(async () => {
    setState(prev => ({ ...prev, loading: true, error: null }));
    try {
      const data = await accountApi.getTransactions(params);
      setState({ data: { transactions: data, total: data.length }, loading: false, error: null });
    } catch (error) {
      setState({
        data: null,
        loading: false,
        error: error instanceof ApiError ? error : new ApiError(0, 'Failed to fetch transactions'),
      });
    }
  }, [params?.startDate, params?.endDate, params?.type, params?.limit, params?.offset]);

  useEffect(() => {
    fetchTransactions();
  }, [fetchTransactions]);

  return { ...state, refetch: fetchTransactions };
};

interface UseEquityHistoryParams {
  period?: '1d' | '7d' | '30d' | '90d' | '1y';
}

export const useEquityHistory = (params?: UseEquityHistoryParams) => {
  const [state, setState] = useState<UseApiState<EquityHistoryPoint[]>>({
    data: null,
    loading: true,
    error: null,
  });

  const fetchHistory = useCallback(async () => {
    setState(prev => ({ ...prev, loading: true, error: null }));
    try {
      const data = await accountApi.getEquityHistory(params);
      setState({ data, loading: false, error: null });
    } catch (error) {
      setState({
        data: null,
        loading: false,
        error: error instanceof ApiError ? error : new ApiError(0, 'Failed to fetch equity history'),
      });
    }
  }, [params?.period]);

  useEffect(() => {
    fetchHistory();
  }, [fetchHistory]);

  return { ...state, refetch: fetchHistory };
};

// ====================
// Trading Hooks
// ====================

export const usePositions = () => {
  return createUseApiHook<{ positions: Position[]; count: number }>(() => tradingApi.getPositions(), [])();
};

interface UseOrdersParams {
