    } catch (err) {
      const apiError = err instanceof ApiError ? err : new ApiError(0, 'Failed to mark all notifications as read');
      setError(apiError);
      throw apiError;
    } finally {
      setLoading(false);
    }
  }, []);

  return { markAllAsRead, loading, error };
