/**
 * Account Management Panel
 * Comprehensive account management sidebar for traders
 */

import { Icon } from './ui/Icon';
import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useAppStore } from '../store/useAppStore';
import { API_ENDPOINTS } from '../config/api';

interface AccountPanelProps {
  onClose: () => void;
  wsConnection: WebSocket | null;
}

interface Transaction {
  id: string;
  date: string;
  type: 'deposit' | 'withdrawal';
  amount: number;
  status: 'pending' | 'completed' | 'failed';
  method?: string;
}

export const AccountPanel: React.FC<AccountPanelProps> = ({ onClose, wsConnection }) => {
  const { account } = useAppStore();
  const [showDepositModal, setShowDepositModal] = useState(false);
  const [showWithdrawModal, setShowWithdrawModal] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [isLoadingTransactions, setIsLoadingTransactions] = useState(false);
  const [leverage, setLeverage] = useState<number>(100);
  const [oneClickTrading, setOneClickTrading] = useState(false);
  const [accountInfo, setAccountInfo] = useState({
    accountNumber: '...',
    accountType: '...',
    leverage: leverage,
  });

  // Fetch real account details
  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const response = await fetch(API_ENDPOINTS.account.summary, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('auth_token')}`
          }
        });
        if (response.ok) {
          const data = await response.json();
          setAccountInfo({
            accountNumber: data.id ? `RTX-${data.id.toString().padStart(6, '0')}` : 'RTX-000000',
            accountType: data.type || 'Standard',
            leverage: data.leverage || 100,
          });
          setLeverage(data.leverage || 100);
        }
      } catch (err) {
        console.error('Failed to fetch account profile:', err);
      }
    };
    fetchProfile();
  }, []);

  // Fetch transaction history
  useEffect(() => {
    const fetchTransactions = async () => {
      setIsLoadingTransactions(true);
      try {
        const response = await fetch(API_ENDPOINTS.payments.history, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('auth_token')}`
          }
        });
        if (response.ok) {
          const data = await response.json();
          setTransactions(data.slice(0, 10)); // Last 10 transactions
        } else {
          setTransactions([]);
        }
      } catch (error) {
        console.error('Failed to fetch transactions:', error);
        setTransactions([]);
      } finally {
        setIsLoadingTransactions(false);
      }
    };

    fetchTransactions();
  }, []);

  // Handle leverage change
  const handleLeverageChange = async (newLeverage: number) => {
    try {
      const response = await fetch(API_ENDPOINTS.account.settings, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('auth_token')}`
        },
        body: JSON.stringify({ leverage: newLeverage }),
      });

      if (response.ok) {
        setLeverage(newLeverage);
      }
    } catch (error) {
      console.error('Failed to update leverage:', error);
    }
  };

  // Handle one-click trading toggle
  const handleOneClickToggle = async (enabled: boolean) => {
    try {
      const response = await fetch(API_ENDPOINTS.account.settings, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('auth_token')}`
        },
        body: JSON.stringify({ oneClickTrading: enabled }),
      });

      if (response.ok) {
        setOneClickTrading(enabled);
      }
    } catch (error) {
      console.error('Failed to update one-click trading:', error);
    }
  };

  return (
    <>
      <div className="w-80 h-full bg-[#131316] border-l border-zinc-800 flex flex-col overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-zinc-800 bg-[#252525]">
          <div className="flex items-center gap-2">
            <Icon name="credit-card" size="sm" className="w-4 h-4 text-blue-400" />
            <h2 className="text-sm font-bold text-zinc-200">Account Management</h2>
          </div>
          <button
            onClick={onClose}
            className="text-zinc-500 hover:text-zinc-300 transition-colors"
          >
            <Icon name="x-close" size="sm" className="w-4 h-4" />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {/* Section 1: Account Summary */}
          <div className="p-4 border-b border-zinc-800">
            <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-3">Account Summary</h3>

            {/* Account Info */}
            <div className="bg-[#252525] rounded-lg p-3 mb-3 border border-zinc-800">
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] text-zinc-500">Account</span>
                <span className="text-xs font-mono text-zinc-300 font-bold">{accountInfo.accountNumber}</span>
              </div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] text-zinc-500">Type</span>
                <span className="text-xs text-blue-400 font-medium">{accountInfo.accountType}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-[10px] text-zinc-500">Leverage</span>
                <span className="text-xs text-zinc-300 font-bold">1:{accountInfo.leverage}</span>
              </div>
            </div>

            {/* Balance Info */}
            <div className="space-y-2">
              <BalanceRow label="Balance" value={account?.balance || 0} currency={account?.currency || 'USD'} />
              <BalanceRow label="Equity" value={account?.equity || 0} currency={account?.currency || 'USD'} valueColor="text-emerald-400" />
              <BalanceRow label="Free Margin" value={account?.freeMargin || 0} currency={account?.currency || 'USD'} />
              <BalanceRow
                label="Margin Level"
                value={account?.marginLevel || 0}
                suffix="%"
                valueColor={getMarginLevelColor(account?.marginLevel || 0)}
              />
            </div>
          </div>

          {/* Section 2: Deposit/Withdraw Buttons */}
          <div className="p-4 border-b border-zinc-800">
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => setShowDepositModal(true)}
                className="flex items-center justify-center gap-2 px-4 py-2.5 bg-emerald-500/10 hover:bg-emerald-500/20 border border-emerald-500/30 rounded-lg text-emerald-400 text-sm font-medium transition-colors"
              >
                <Icon name="trending-up" size="sm" className="w-4 h-4" />
                Deposit
              </button>
              <button
                onClick={() => setShowWithdrawModal(true)}
                className="flex items-center justify-center gap-2 px-4 py-2.5 bg-rose-500/10 hover:bg-rose-500/20 border border-rose-500/30 rounded-lg text-rose-400 text-sm font-medium transition-colors"
              >
                <Icon name="trending-up" size="sm" className="w-4 h-4 rotate-180" />
                Withdraw
              </button>
            </div>
          </div>

          {/* Section 3: Transaction History */}
          <div className="p-4 border-b border-zinc-800">
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider">Transaction History</h3>
              <button className="text-[10px] text-blue-400 hover:text-zinc-300 transition-colors font-medium">
                View All
              </button>
            </div>

            {isLoadingTransactions ? (
              <div className="text-center py-6 text-zinc-600 text-xs">
                Loading transactions...
              </div>
            ) : transactions.length === 0 ? (
              <div className="text-center py-6 text-zinc-600 text-xs">
                No transactions yet
              </div>
            ) : (
              <div className="space-y-2">
                {transactions.map((transaction) => (
                  <TransactionRow key={transaction.id} transaction={transaction} />
                ))}
              </div>
            )}
          </div>

          {/* Section 4: Account Settings */}
          <div className="p-4">
            <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-3">Account Settings</h3>

            <div className="space-y-3">
              {/* Leverage Selector */}
              <div className="flex items-center justify-between py-2">
                <span className="text-xs text-zinc-400">Leverage</span>
                <select
                  value={leverage}
                  onChange={(e) => handleLeverageChange(Number(e.target.value))}
                  className="bg-[#252525] border border-zinc-700 rounded px-2 py-1 text-xs text-zinc-300 focus:outline-none focus:border-zinc-600"
                >
                  <option value={50}>1:50</option>
                  <option value={100}>1:100</option>
                  <option value={200}>1:200</option>
                  <option value={500}>1:500</option>
                </select>
              </div>

              {/* Change Password Button */}
              <button
                onClick={() => setShowPasswordModal(true)}
                className="w-full flex items-center justify-between px-3 py-2 bg-[#252525] hover:bg-zinc-800 border border-zinc-700 rounded-lg text-xs text-zinc-300 transition-colors"
              >
                <div className="flex items-center gap-2">
                  <Icon name="lock" size="sm" className="w-3.5 h-3.5 text-zinc-500" />
                  <span>Change Password</span>
                </div>
                <Icon name="chevron-right" size="sm" className="w-3.5 h-3.5 text-zinc-600" />
              </button>

              {/* One-Click Trading Toggle */}
              <div className="flex items-center justify-between py-2">
                <span className="text-xs text-zinc-400">One-Click Trading</span>
                <button
                  onClick={() => handleOneClickToggle(!oneClickTrading)}
                  className={`relative w-10 h-5 rounded-full transition-colors ${oneClickTrading ? 'bg-emerald-500' : 'bg-zinc-700'
                    }`}
                >
                  <div
                    className={`absolute top-0.5 left-0.5 w-4 h-4 bg-white rounded-full transition-transform ${oneClickTrading ? 'translate-x-5' : 'translate-x-0'
                      }`}
                  />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Modals */}
      {showDepositModal && (
        <PaymentModal
          type="deposit"
          onClose={() => setShowDepositModal(false)}
        />
      )}
      {showWithdrawModal && (
        <PaymentModal
          type="withdrawal"
          onClose={() => setShowWithdrawModal(false)}
        />
      )}
      {showPasswordModal && (
        <PasswordModal onClose={() => setShowPasswordModal(false)} />
      )}
    </>
  );
};

/**
 * Balance Row Component
 */
interface BalanceRowProps {
  label: string;
  value: number;
  currency?: string;
  suffix?: string;
  valueColor?: string;
}

const BalanceRow: React.FC<BalanceRowProps> = ({ label, value, currency, suffix, valueColor = 'text-zinc-200' }) => {
  const prevRef = useRef(value);
  const [color, setColor] = useState(valueColor);

  useEffect(() => {
    if (value > prevRef.current) {
      setColor(`bg-emerald-500/40 text-emerald-400 transition-none`);
      setTimeout(() => setColor(`${valueColor} transition-colors duration-500`), 50);
    } else if (value < prevRef.current) {
      setColor(`bg-red-500/40 text-red-400 transition-none`);
      setTimeout(() => setColor(`${valueColor} transition-colors duration-500`), 50);
    }
    prevRef.current = value;
  }, [value, valueColor]);

  return (
    <div className="flex items-center justify-between py-1.5 border-b border-zinc-800/50">
      <span className="text-xs text-zinc-500">{label}</span>
      <span className={`text-sm font-bold font-mono px-0.5 rounded-sm inline-block ${color}`}>
        {currency && `${currency} `}
        {value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
        {suffix}
      </span>
    </div>
  );
};

/**
 * Transaction Row Component
 */
interface TransactionRowProps {
  transaction: Transaction;
}

const TransactionRow: React.FC<TransactionRowProps> = ({ transaction }) => {
  const typeColor = transaction.type === 'deposit' ? 'text-emerald-400' : 'text-rose-400';
  const statusConfig = {
    pending: { color: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30', label: 'Pending' },
    completed: { color: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30', label: 'Completed' },
    failed: { color: 'bg-rose-500/20 text-rose-400 border-rose-500/30', label: 'Failed' },
  };

  const status = statusConfig[transaction.status];

  return (
    <div className="flex items-center justify-between p-2 bg-[#252525] rounded border border-zinc-800 hover:bg-zinc-800/30 transition-colors">
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 mb-1">
          <span className={`text-xs font-bold ${typeColor} capitalize`}>{transaction.type}</span>
          <span className={`text-[9px] px-1.5 py-0.5 rounded border ${status.color} font-medium`}>
            {status.label}
          </span>
        </div>
        <div className="text-[10px] text-zinc-600">{new Date(transaction.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</div>
      </div>
      <div className={`text-sm font-bold font-mono ${typeColor}`}>
        {transaction.type === 'deposit' ? '+' : '-'}${transaction.amount.toLocaleString('en-US', { minimumFractionDigits: 2 })}
      </div>
    </div>
  );
};

/**
 * Payment Modal (Deposit/Withdrawal)
 */
interface PaymentModalProps {
  type: 'deposit' | 'withdrawal';
  onClose: () => void;
}

const PaymentModal: React.FC<PaymentModalProps> = ({ type, onClose }) => {
  const [amount, setAmount] = useState('');
  const [method, setMethod] = useState('card');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const endpoint = type === 'deposit' ? API_ENDPOINTS.payments.deposit : API_ENDPOINTS.payments.withdrawal;
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('auth_token')}`
        },
        body: JSON.stringify({
          amount: parseFloat(amount),
          method,
        }),
      });

      if (!response.ok) {
        throw new Error('Payment request failed');
      }

      setSuccess(true);
      setTimeout(() => {
        onClose();
      }, 2000);
    } catch (err: any) {
      setError(err.message || 'Payment failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const title = type === 'deposit' ? 'Deposit Funds' : 'Withdraw Funds';
  const buttonColor = type === 'deposit' ? 'bg-emerald-500 hover:bg-emerald-600' : 'bg-rose-500 hover:bg-rose-600';

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[9999]" onClick={onClose}>
      <div className="bg-[#131316] border border-zinc-800 rounded-lg shadow-2xl w-96 p-6" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-bold text-zinc-200">{title}</h3>
          <button onClick={onClose} className="text-zinc-500 hover:text-zinc-300 transition-colors">
            <Icon name="x-close" size="sm" className="w-5 h-5" />
          </button>
        </div>

        {success ? (
          <div className="py-8 text-center">
            <div className="w-16 h-16 bg-emerald-500/20 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg className="w-8 h-8 text-emerald-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <p className="text-sm text-zinc-300 font-medium">
              {type === 'deposit' ? 'Deposit' : 'Withdrawal'} request submitted successfully!
            </p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Amount Input */}
            <div>
              <label className="block text-xs text-zinc-500 mb-1.5">Amount (USD)</label>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0.00"
                step="0.01"
                min="0"
                required
                className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-300 focus:outline-none focus:border-zinc-600"
              />
            </div>

            {/* Payment Method */}
            <div>
              <label className="block text-xs text-zinc-500 mb-1.5">Payment Method</label>
              <select
                value={method}
                onChange={(e) => setMethod(e.target.value)}
                className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-300 focus:outline-none focus:border-zinc-600"
              >
                <option value="card">Credit/Debit Card</option>
                <option value="bank">Bank Transfer</option>
                <option value="crypto">Cryptocurrency</option>
              </select>
            </div>

            {/* Error Message */}
            {error && (
              <div className="p-3 bg-rose-500/10 border border-rose-500/30 rounded text-xs text-rose-400">
                {error}
              </div>
            )}

            {/* Submit Button */}
            <button
              type="submit"
              disabled={loading || !amount}
              className={`w-full py-2.5 ${buttonColor} text-white text-sm font-medium rounded transition-colors disabled:opacity-50 disabled:cursor-not-allowed`}
            >
              {loading ? 'Processing...' : `Submit ${type === 'deposit' ? 'Deposit' : 'Withdrawal'}`}
            </button>
          </form>
        )}
      </div>
    </div>
  );
};

/**
 * Password Change Modal
 */
interface PasswordModalProps {
  onClose: () => void;
}

const PasswordModal: React.FC<PasswordModalProps> = ({ onClose }) => {
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (newPassword !== confirmPassword) {
      setError('New passwords do not match');
      return;
    }

    if (newPassword.length < 8) {
      setError('Password must be at least 8 characters');
      return;
    }

    setLoading(true);

    try {
      const response = await fetch(API_ENDPOINTS.account.password, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('auth_token')}`
        },
        body: JSON.stringify({
          currentPassword,
          newPassword,
        }),
      });

      if (!response.ok) {
        throw new Error('Password change failed');
      }

      setSuccess(true);
      setTimeout(() => {
        onClose();
      }, 2000);
    } catch (err: any) {
      setError(err.message || 'Failed to change password');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[9999]" onClick={onClose}>
      <div className="bg-[#131316] border border-zinc-800 rounded-lg shadow-2xl w-96 p-6" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-bold text-zinc-200">Change Password</h3>
          <button onClick={onClose} className="text-zinc-500 hover:text-zinc-300 transition-colors">
            <Icon name="x-close" size="sm" className="w-5 h-5" />
          </button>
        </div>

        {success ? (
          <div className="py-8 text-center">
            <div className="w-16 h-16 bg-emerald-500/20 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg className="w-8 h-8 text-emerald-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <p className="text-sm text-zinc-300 font-medium">Password changed successfully!</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-xs text-zinc-500 mb-1.5">Current Password</label>
              <input
                type="password"
                value={currentPassword}
                onChange={(e) => setCurrentPassword(e.target.value)}
                required
                className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-300 focus:outline-none focus:border-zinc-600"
              />
            </div>

            <div>
              <label className="block text-xs text-zinc-500 mb-1.5">New Password</label>
              <input
                type="password"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                required
                className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-300 focus:outline-none focus:border-zinc-600"
              />
            </div>

            <div>
              <label className="block text-xs text-zinc-500 mb-1.5">Confirm New Password</label>
              <input
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                required
                className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-300 focus:outline-none focus:border-zinc-600"
              />
            </div>

            {error && (
              <div className="p-3 bg-rose-500/10 border border-rose-500/30 rounded text-xs text-rose-400">
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full py-2.5 bg-zinc-700 hover:bg-zinc-600 text-white text-sm font-medium rounded transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? 'Updating...' : 'Change Password'}
            </button>
          </form>
        )}
      </div>
    </div>
  );
};

/**
 * Utility Functions
 */

function getMarginLevelColor(marginLevel: number): string {
  if (marginLevel < 50) return 'text-rose-400';
  if (marginLevel < 100) return 'text-yellow-400';
  return 'text-emerald-400';
}

/**
 * Admin Panel Component
 * Controls for routing mode, symbol management, LP configuration
 */

import { Icon } from './ui/Icon';
import { useState, useEffect } from 'react';
import { RoutingRulesPanel } from './RoutingRulesPanel';
import { API_ENDPOINTS, buildAdminUrl } from '../config/api';
import { Settings, Server, TrendingUp, GitMerge } from 'lucide-react';

type ExecutionMode = 'ABOOK' | 'BBOOK';

type BrokerConfig = {
  brokerName: string;
  brokerDisplayName: string;
  priceFeedLP: string;
  priceFeedName: string;
  executionMode: ExecutionMode;
  defaultLeverage: number;
  defaultBalance: number;
  marginMode: string;
  maxTicksPerSymbol: number;
  disabledSymbols?: Record<string, boolean>;
};

type LiquidityProvider = {
  name: string;
  status: 'ACTIVE' | 'INACTIVE' | 'ERROR';
  latency: number;
  uptime: number;
  symbols: string[];
};

type SymbolConfig = {
  symbol: string;
  enabled: boolean;
  routingMode: string;
  spread: number;
  commission: number;
  leverage: number;
  minVolume: number;
  maxVolume: number;
};

export const AdminPanel = () => {
  const [config, setConfig] = useState<BrokerConfig | null>(null);
  const [liquidityProviders, setLiquidityProviders] = useState<LiquidityProvider[]>([]);
  const [symbols, setSymbols] = useState<SymbolConfig[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(
    null
  );
  const [activeTab, setActiveTab] = useState<'config' | 'lp' | 'symbols' | 'routing'>('config');

  // Fetch current configuration
  useEffect(() => {
    fetchConfig();
    fetchLiquidityProviders();
    fetchSymbols();
  }, []);

  const fetchConfig = async () => {
    setLoading(true);
    try {
      const response = await fetch(API_ENDPOINTS.admin.config);
      if (!response.ok) {
        if (response.status === 404) {
          showMessage('error', 'Config endpoint not found (404)');
        } else {
          showMessage('error', `Failed to load configuration: ${response.status}`);
        }
      } else {
        const data = await response.json();
        setConfig(data);
      }
    } catch (error) {
      console.error('Failed to fetch config:', error);
      showMessage('error', 'Failed to load configuration - server unreachable');
    } finally {
      setLoading(false);
    }
  };

  const fetchLiquidityProviders = async () => {
    try {
      const response = await fetch(API_ENDPOINTS.admin.lp);
      if (!response.ok) {
        console.error('Failed to fetch LPs:', response.status);
      } else {
        const data = await response.json();
        setLiquidityProviders(data || []);
      }
    } catch (error) {
      console.error('Failed to fetch LPs:', error);
    }
  };

  const fetchSymbols = async () => {
    try {
      const response = await fetch(API_ENDPOINTS.admin.symbols);
      if (!response.ok) {
        console.error('Failed to fetch symbols:', response.status);
      } else {
        const data = await response.json();
        setSymbols(data || []);
      }
    } catch (error) {
      console.error('Failed to fetch symbols:', error);
    }
  };

  const saveConfig = async () => {
    if (!config) return;

    setSaving(true);
    try {
      const response = await fetch(API_ENDPOINTS.admin.config, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(config),
      });

      if (!response.ok) {
        if (response.status === 404) {
          showMessage('error', 'Config endpoint not found (404)');
        } else {
          const error = await response.text();
          showMessage('error', `Failed to save: ${response.status} - ${error}`);
        }
      } else {
        showMessage('success', 'Configuration saved successfully');
        await fetchConfig();
      }
    } catch (error) {
      showMessage('error', 'Failed to save configuration - server unreachable');
      console.error('Save error:', error);
    } finally {
      setSaving(false);
    }
  };

  const toggleLP = async (lpName: string) => {
    try {
      const response = await fetch(buildAdminUrl(`/admin/lps/${lpName}/toggle`), {
        method: 'POST',
      });

      if (!response.ok) {
        if (response.status === 404) {
          showMessage('error', `LP endpoint not found (404)`);
        } else {
          showMessage('error', `Failed to toggle LP: ${response.status}`);
        }
      } else {
        showMessage('success', `LP ${lpName} toggled`);
        await fetchLiquidityProviders();
      }
    } catch (error) {
      console.error('Toggle LP error:', error);
      showMessage('error', 'Failed to toggle LP - server unreachable');
    }
  };

  const updateSymbol = async (symbol: string, updates: Partial<SymbolConfig>) => {
    try {
      const response = await fetch(buildAdminUrl(`/admin/symbols/${symbol}`), {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updates),
      });

      if (!response.ok) {
        if (response.status === 404) {
          showMessage('error', `Symbol endpoint not found (404)`);
        } else {
          showMessage('error', `Failed to update symbol: ${response.status}`);
        }
      } else {
        showMessage('success', `Symbol ${symbol} updated`);
        await fetchSymbols();
      }
    } catch (error) {
      console.error('Update symbol error:', error);
      showMessage('error', 'Failed to update symbol - server unreachable');
    }
  };

  const showMessage = (type: 'success' | 'error', text: string) => {
    setMessage({ type, text });
    setTimeout(() => setMessage(null), 3000);
  };

  if (loading && !config) {
    return (
      <div className="flex items-center justify-center h-full text-zinc-500">
        <Icon name="refresh" size="sm" className="w-6 h-6 animate-spin mr-2" />
        Loading admin panel...
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-zinc-900">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-zinc-800">
        <div className="flex items-center gap-3">
          <Icon name="settings" size="sm" className="w-5 h-5 text-emerald-400" />
          <div>
            <h2 className="text-lg font-semibold text-white">Admin Panel</h2>
            <p className="text-xs text-zinc-500">Broker Configuration & Management</p>
          </div>
        </div>
        <button
          onClick={saveConfig}
          disabled={saving || !config}
          className="flex items-center gap-2 px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-black rounded font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <Icon name="save" size="sm" className="w-4 h-4" />
          {saving ? 'Saving...' : 'Save Changes'}
        </button>
      </div>

      {/* Message Toast */}
      {message && (
        <div
          className={`mx-4 mt-4 p-3 rounded border flex items-center gap-2 ${
            message.type === 'success'
              ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400'
              : 'bg-red-500/10 border-red-500/20 text-red-400'
          }`}
        >
          {message.type === 'success' ? (
            <Icon name="check-circle" size="sm" className="w-4 h-4" />
          ) : (
            <Icon name="error" size="sm" className="w-4 h-4" />
          )}
          <span className="text-sm">{message.text}</span>
        </div>
      )}

      {/* Tabs */}
      <div className="flex items-center gap-2 px-4 py-3 border-b border-zinc-800">
        <TabButton
          active={activeTab === 'config'}
          onClick={() => setActiveTab('config')}
          icon={Settings}
          label="Broker Config"
        />
        <TabButton
          active={activeTab === 'lp'}
          onClick={() => setActiveTab('lp')}
          icon={Server}
          label="Liquidity Providers"
        />
        <TabButton
          active={activeTab === 'symbols'}
          onClick={() => setActiveTab('symbols')}
          icon={TrendingUp}
          label="Symbols"
        />
        <TabButton
          active={activeTab === 'routing'}
          onClick={() => setActiveTab('routing')}
          icon={GitMerge}
          label="Routing Rules"
        />
      </div>

      {/* Content */}
      <div className="flex-1 overflow-auto p-4">
        {activeTab === 'config' && config && (
          <ConfigTab config={config} setConfig={setConfig} />
        )}
        {activeTab === 'lp' && (
          <LiquidityProvidersTab providers={liquidityProviders} onToggle={toggleLP} />
        )}
        {activeTab === 'symbols' && <SymbolsTab symbols={symbols} onUpdate={updateSymbol} />}
        {activeTab === 'routing' && <RoutingRulesPanel />}
      </div>
    </div>
  );
};

// Tab Button Component
const TabButton = ({
  active,
  onClick,
  icon: Icon,
  label,
}: {
  active: boolean;
  onClick: () => void;
  icon: typeof Settings;
  label: string;
}) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
      active
        ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30'
        : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-800/50'
    }`}
  >
    <Icon className="w-4 h-4" />
    {label}
  </button>
);

// Config Tab Component
const ConfigTab = ({
  config,
  setConfig,
}: {
  config: BrokerConfig;
  setConfig: (config: BrokerConfig) => void;
}) => (
  <div className="space-y-6 max-w-4xl">
