          <input
            type="number"
            value={scaledOrder.totalVolume}
            onChange={(e) => setScaledOrder({ totalVolume: parseFloat(e.target.value) })}
            step="0.1"
            className="w-full bg-[#25272E] border border-[#383A42] rounded px-2 py-1.5 text-xs text-[#E4E4E7]"
          />
        </div>
      </div>

      {/* Side & Number of Orders */}
      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="text-xs text-[#888] mb-1 block">Side</label>
          <select
            value={scaledOrder.side}
            onChange={(e) => setScaledOrder({ side: e.target.value as any })}
            className="w-full bg-[#25272E] border border-[#383A42] rounded px-2 py-1.5 text-xs text-[#E4E4E7]"
          >
            <option value="BUY">Buy</option>
            <option value="SELL">Sell</option>
          </select>
        </div>
        <div>
          <label className="text-xs text-[#888] mb-1 block">Number of Orders</label>
          <input
            type="number"
            value={scaledOrder.numberOfOrders}
            onChange={(e) => setScaledOrder({ numberOfOrders: parseInt(e.target.value) })}
            min="2"
            max="20"
            className="w-full bg-[#25272E] border border-[#383A42] rounded px-2 py-1.5 text-xs text-[#E4E4E7]"
          />
        </div>
      </div>

      {/* Price Range */}
      <div className="grid grid-cols-3 gap-3">
        <div>
          <label className="text-xs text-[#888] mb-1 block">Start Price</label>
          <input
            type="number"
            value={scaledOrder.startPrice}
            onChange={(e) => setScaledOrder({ startPrice: parseFloat(e.target.value) })}
            step="0.0001"
            className="w-full bg-[#25272E] border border-[#383A42] rounded px-2 py-1.5 text-xs text-[#E4E4E7]"
          />
        </div>
        <div>
          <label className="text-xs text-[#888] mb-1 block">End Price</label>
          <input
            type="number"
            value={scaledOrder.endPrice}
            onChange={(e) => setScaledOrder({ endPrice: parseFloat(e.target.value) })}
            step="0.0001"
            className="w-full bg-[#25272E] border border-[#383A42] rounded px-2 py-1.5 text-xs text-[#E4E4E7]"
          />
        </div>
        <div>
          <label className="text-xs text-[#888] mb-1 block">Price Increment</label>
          <input
            type="number"
            value={scaledOrder.priceIncrement}
            onChange={(e) => setScaledOrder({ priceIncrement: parseFloat(e.target.value) })}
            step="0.0001"
            className="w-full bg-[#25272E] border border-[#383A42] rounded px-2 py-1.5 text-xs text-[#E4E4E7]"
          />
        </div>
      </div>

      {/* Preview Table */}
      <div className="bg-[#25272E] border border-[#383A42] rounded overflow-hidden">
        <div className="px-3 py-2 bg-[#1C1E24] border-b border-[#383A42]">
          <div className="text-xs font-bold text-[#F5C542]">Order Preview ({preview.length} orders)</div>
        </div>
        <div className="max-h-64 overflow-y-auto">
          <table className="w-full text-xs">
            <thead className="bg-[#1C1E24] sticky top-0">
              <tr>
                <th className="text-left px-3 py-2 text-[#888] font-bold">#</th>
                <th className="text-right px-3 py-2 text-[#888] font-bold">Price</th>
                <th className="text-right px-3 py-2 text-[#888] font-bold">Volume</th>
                <th className="text-right px-3 py-2 text-[#888] font-bold">Side</th>
              </tr>
            </thead>
            <tbody>
              {preview.map((order) => (
                <tr
                  key={order.orderNumber}
                  className="border-t border-[#383A42] hover:bg-[#1C1E24] transition-colors"
                >
                  <td className="px-3 py-2 text-[#888]">{order.orderNumber}</td>
                  <td className="px-3 py-2 text-right text-[#E4E4E7]">{order.price.toFixed(4)}</td>
                  <td className="px-3 py-2 text-right text-[#E4E4E7]">{order.volume.toFixed(2)}</td>
                  <td className="px-3 py-2 text-right">
                    <span className={scaledOrder.side === 'BUY' ? 'text-[#10b981]' : 'text-[#ef4444]'}>
                      {scaledOrder.side}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Summary */}
      <div className="bg-[#25272E] border border-[#383A42] rounded p-3">
        <div className="text-xs font-bold text-[#F5C542] mb-2">Order Summary</div>
        <div className="text-xs text-[#888] space-y-1">
          <div>
            Symbol: <span className="text-[#E4E4E7]">{scaledOrder.symbol}</span>
          </div>
          <div>
            Total Volume: <span className="text-[#E4E4E7]">{scaledOrder.totalVolume} lots</span> split into{' '}
            <span className="text-[#E4E4E7]">{scaledOrder.numberOfOrders} orders</span>
          </div>
          <div>
            Price Range: <span className="text-[#E4E4E7]">{scaledOrder.startPrice.toFixed(4)}</span> to{' '}
            <span className="text-[#E4E4E7]">{scaledOrder.endPrice.toFixed(4)}</span>
          </div>
          <div>
            Volume per order:{' '}
            <span className="text-[#E4E4E7]">
              {(scaledOrder.totalVolume / scaledOrder.numberOfOrders).toFixed(2)} lots
            </span>
          </div>
        </div>
      </div>

      {/* Submit */}
      <button
        onClick={submitScaledOrder}
        className="w-full bg-[#8a8a8f] hover:bg-[#2563EB] text-white font-bold py-2 px-4 rounded text-xs transition-colors"
      >
        Submit Scaled Order ({preview.length} orders)
      </button>
    </div>
  );
}

/**
 * Alert Card Component
 * Individual alert display with severity indicator and actions
 */

import { Icon } from './ui/Icon';
import { useState } from 'react';
import { Info, AlertCircle, AlertTriangle } from 'lucide-react';
export type AlertSeverity = 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';

export type Alert = {
  id: string;
  severity: AlertSeverity;
  message: string;
  timestamp: number;
  acknowledged?: boolean;
  snoozedUntil?: number;
};

type AlertCardProps = {
  alert: Alert;
  onAcknowledge: (id: string) => void;
  onSnooze: (id: string, minutes: number) => void;
  onDismiss: (id: string) => void;
};

const SEVERITY_CONFIG = {
  LOW: {
    icon: Info,
    bgColor: 'bg-zinc-700/20',
    borderColor: 'border-zinc-600/30',
    textColor: 'text-blue-400',
    dotColor: 'bg-zinc-600',
  },
  MEDIUM: {
    icon: AlertCircle,
    bgColor: 'bg-yellow-500/10',
    borderColor: 'border-yellow-500/30',
    textColor: 'text-yellow-400',
    dotColor: 'bg-yellow-500',
  },
  HIGH: {
    icon: AlertTriangle,
    bgColor: 'bg-orange-500/10',
    borderColor: 'border-orange-500/30',
    textColor: 'text-orange-400',
    dotColor: 'bg-orange-500',
  },
  CRITICAL: {
    icon: AlertTriangle,
    bgColor: 'bg-red-500/10',
    borderColor: 'border-red-500/30',
    textColor: 'text-red-400',
    dotColor: 'bg-red-500',
  },
};

export function AlertCard({ alert, onAcknowledge, onSnooze, onDismiss }: AlertCardProps) {
  const [showSnoozeMenu, setShowSnoozeMenu] = useState(false);
  const config = SEVERITY_CONFIG[alert.severity];
  const Icon = config.icon;

  const formatTimestamp = (timestamp: number) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  };

  const handleSnooze = (minutes: number) => {
    onSnooze(alert.id, minutes);
    setShowSnoozeMenu(false);
  };

  return (
    <div
      className={`${config.bgColor} ${config.borderColor} border rounded-lg p-3 shadow-lg backdrop-blur-sm animate-slide-in`}
      style={{
        minWidth: '320px',
        maxWidth: '400px',
      }}
    >
      {/* Header */}
      <div className="flex items-start gap-2 mb-2">
        <div className={`${config.dotColor} w-2 h-2 rounded-full mt-1.5 animate-pulse`} />
        <Icon className={`${config.textColor} w-4 h-4 mt-0.5`} />
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className={`${config.textColor} text-xs font-bold uppercase tracking-wide`}>
              {alert.severity}
            </span>
            <span className="text-[10px] text-zinc-500">
              {formatTimestamp(alert.timestamp)}
            </span>
          </div>
          <p className="text-sm text-zinc-200 leading-snug break-words">
            {alert.message}
          </p>
        </div>
        <button
          onClick={() => onDismiss(alert.id)}
          className="text-zinc-500 hover:text-zinc-300 transition-colors p-0.5"
          title="Dismiss"
        >
          <Icon name="x-close" size="sm" className="w-4 h-4" />
        </button>
      </div>

      {/* Actions */}
      <div className="flex items-center gap-2 mt-3 pt-2 border-t border-zinc-800/50">
        <button
          onClick={() => onAcknowledge(alert.id)}
          className="flex items-center gap-1.5 px-2.5 py-1 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 rounded text-xs font-medium transition-colors border border-emerald-500/20"
        >
          <Icon name="check-circle" size="sm" className="w-3 h-3" />
          Acknowledge
        </button>

        <div className="relative">
          <button
            onClick={() => setShowSnoozeMenu(!showSnoozeMenu)}
            className="flex items-center gap-1.5 px-2.5 py-1 bg-zinc-800/50 hover:bg-zinc-800 text-zinc-400 rounded text-xs font-medium transition-colors border border-zinc-700/50"
          >
            <Icon name="clock" size="sm" className="w-3 h-3" />
            Snooze
          </button>

          {showSnoozeMenu && (
            <div className="absolute bottom-full left-0 mb-1 bg-zinc-900 border border-zinc-800 rounded shadow-lg overflow-hidden z-10">
              <button
                onClick={() => handleSnooze(5)}
                className="block w-full px-3 py-1.5 text-left text-xs text-zinc-300 hover:bg-zinc-800 transition-colors whitespace-nowrap"
              >
                5 minutes
              </button>
              <button
                onClick={() => handleSnooze(15)}
                className="block w-full px-3 py-1.5 text-left text-xs text-zinc-300 hover:bg-zinc-800 transition-colors whitespace-nowrap"
              >
                15 minutes
              </button>
              <button
                onClick={() => handleSnooze(60)}
                className="block w-full px-3 py-1.5 text-left text-xs text-zinc-300 hover:bg-zinc-800 transition-colors whitespace-nowrap"
              >
                1 hour
              </button>
            </div>
          )}
        </div>
      </div>

      <style>
        {`
          @keyframes slide-in {
            from {
              transform: translateX(100%);
              opacity: 0;
            }
            to {
              transform: translateX(0);
              opacity: 1;
            }
          }
          .animate-slide-in {
            animation: slide-in 0.3s ease-out;
          }
        `}
      </style>
    </div>
  );
}

/**
 * Alert Manager Component
 * Manage price alerts with table view and creation modal
 */

import { Icon } from './ui/Icon';
import React, { useState, useMemo, useEffect } from 'react';
import {
  useAlertStore,
  formatCondition,
  formatExpiration,
  type Alert,
  type AlertCondition,
  type NotifyMethod,
} from '../store/useAlertStore';

type SortColumn = 'symbol' | 'condition' | 'price' | 'status' | 'createdAt';
type SortDirection = 'asc' | 'desc';

export const AlertManager: React.FC = () => {
  const { alerts, removeAlert, toggleAlert } = useAlertStore();
  const [showNewAlertModal, setShowNewAlertModal] = useState(false);
  const [editingAlert, setEditingAlert] = useState<Alert | null>(null);
  const [sortColumn, setSortColumn] = useState<SortColumn>('createdAt');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');

  // Count active alerts
  const activeCount = alerts.filter((a) => a.status === 'active' && a.enabled).length;

  // Sort alerts
  const sortedAlerts = useMemo(() => {
    const sorted = [...alerts].sort((a, b) => {
      let aVal: any = a[sortColumn];
      let bVal: any = b[sortColumn];

      if (sortColumn === 'condition') {
        aVal = formatCondition(a.condition);
        bVal = formatCondition(b.condition);
      }

      if (typeof aVal === 'string' && typeof bVal === 'string') {
        return sortDirection === 'asc' ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal);
      }

      return sortDirection === 'asc' ? aVal - bVal : bVal - aVal;
    });

    return sorted;
  }, [alerts, sortColumn, sortDirection]);

  const handleSort = (column: SortColumn) => {
    if (sortColumn === column) {
      setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortColumn(column);
      setSortDirection('asc');
    }
  };

  const handleEdit = (alert: Alert) => {
    setEditingAlert(alert);
    setShowNewAlertModal(true);
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to delete this alert?')) {
      removeAlert(id);
    }
  };

  const handleCloseModal = () => {
    setShowNewAlertModal(false);
    setEditingAlert(null);
  };

  return (
    <div className="flex flex-col h-full bg-[#131316] text-zinc-300">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2 border-b border-zinc-800 bg-[#252525]">
        <div className="flex items-center gap-2">
          <Icon name="bell" size="sm" className="w-4 h-4 text-blue-400" />
          <h3 className="text-sm font-bold text-zinc-200">Alerts</h3>
          {activeCount > 0 && (
            <span className="px-2 py-0.5 bg-emerald-500/20 text-emerald-400 text-[10px] font-bold rounded-full border border-emerald-500/30">
              {activeCount} Active
            </span>
          )}
        </div>
        <button
          onClick={() => setShowNewAlertModal(true)}
          className="flex items-center gap-1.5 px-3 py-1.5 bg-zinc-700 hover:bg-zinc-600 text-white text-xs font-medium rounded transition-colors"
        >
          <Icon name="plus" size="sm" className="w-3.5 h-3.5" />
          New Alert
        </button>
      </div>

      {/* Alerts Table */}
      <div className="flex-1 overflow-auto custom-scrollbar">
        {alerts.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-zinc-600">
            <Icon name="bell" size="sm" className="w-12 h-12 mb-3 opacity-30" />
            <p className="text-sm">No alerts created yet</p>
            <p className="text-xs mt-1">Click "New Alert" to create your first price alert</p>
          </div>
        ) : (
          <table className="w-full text-xs">
            <thead className="sticky top-0 bg-[#252525] border-b border-zinc-800 z-10">
              <tr>
                <TableHeader label="Symbol" column="symbol" sortColumn={sortColumn} sortDirection={sortDirection} onSort={handleSort} />
                <TableHeader label="Condition" column="condition" sortColumn={sortColumn} sortDirection={sortDirection} onSort={handleSort} />
                <TableHeader label="Price" column="price" sortColumn={sortColumn} sortDirection={sortDirection} onSort={handleSort} />
                <TableHeader label="Status" column="status" sortColumn={sortColumn} sortDirection={sortDirection} onSort={handleSort} />
                <TableHeader label="Created" column="createdAt" sortColumn={sortColumn} sortDirection={sortDirection} onSort={handleSort} />
                <th className="text-left py-2 px-3 text-zinc-500 font-medium">Actions</th>
              </tr>
            </thead>
            <tbody>
              {sortedAlerts.map((alert) => (
                <AlertRow
                  key={alert.id}
                  alert={alert}
                  onEdit={() => handleEdit(alert)}
                  onDelete={() => handleDelete(alert.id)}
                  onToggle={() => toggleAlert(alert.id)}
                />
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* New/Edit Alert Modal */}
      {showNewAlertModal && (
        <NewAlertModal
          onClose={handleCloseModal}
          editingAlert={editingAlert}
        />
      )}
    </div>
  );
};

/**
 * Table Header Component
 */
interface TableHeaderProps {
  label: string;
  column: SortColumn;
  sortColumn: SortColumn;
  sortDirection: SortDirection;
  onSort: (column: SortColumn) => void;
}

const TableHeader: React.FC<TableHeaderProps> = ({ label, column, sortColumn, sortDirection, onSort }) => {
  const isActive = sortColumn === column;

  return (
    <th
      className="text-left py-2 px-3 text-zinc-500 font-medium cursor-pointer hover:text-zinc-300 transition-colors select-none"
      onClick={() => onSort(column)}
    >
      <div className="flex items-center gap-1">
        {label}
        {isActive && (
          sortDirection === 'asc' ? <Icon name="chevron-up" size="sm" className="w-3 h-3" /> : <Icon name="chevron-down" size="sm" className="w-3 h-3" />
        )}
      </div>
    </th>
  );
};

/**
 * Alert Row Component
 */
interface AlertRowProps {
  alert: Alert;
  onEdit: () => void;
  onDelete: () => void;
  onToggle: () => void;
}

const AlertRow: React.FC<AlertRowProps> = ({ alert, onEdit, onDelete, onToggle }) => {
  const statusConfig = {
    active: { color: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30', label: 'Active' },
    triggered: { color: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30', label: 'Triggered' },
    expired: { color: 'bg-zinc-500/20 text-zinc-500 border-zinc-500/30', label: 'Expired' },
    disabled: { color: 'bg-zinc-700/20 text-zinc-600 border-zinc-700/30', label: 'Disabled' },
  };

  const status = statusConfig[alert.status];
  const createdDate = new Date(alert.createdAt).toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });

  return (
    <tr className="border-b border-zinc-800/50 hover:bg-zinc-800/30 transition-colors">
      <td className="py-2 px-3">
        <span className="font-bold text-zinc-200">{alert.symbol}</span>
      </td>
      <td className="py-2 px-3 text-zinc-400">{formatCondition(alert.condition)}</td>
      <td className="py-2 px-3">
        <span className="font-mono font-bold text-zinc-200">{alert.price.toFixed(5)}</span>
      </td>
      <td className="py-2 px-3">
        <span className={`inline-block px-2 py-0.5 rounded text-[10px] font-medium border ${status.color}`}>
          {status.label}
        </span>
      </td>
      <td className="py-2 px-3 text-zinc-500">{createdDate}</td>
      <td className="py-2 px-3">
        <div className="flex items-center gap-1">
          <button
            onClick={onToggle}
            className="p-1 hover:bg-zinc-700 rounded transition-colors"
            title={alert.enabled ? 'Disable' : 'Enable'}
          >
            {alert.enabled ? (
              <Icon name="bell" size="sm" className="w-3.5 h-3.5 text-emerald-400" />
            ) : (
              <Icon name="bell" size="sm" className="w-3.5 h-3.5 text-zinc-600" />
            )}
          </button>
          <button
            onClick={onEdit}
            className="p-1 hover:bg-zinc-700 rounded transition-colors"
            title="Edit"
          >
            <Icon name="edit" size="sm" className="w-3.5 h-3.5 text-blue-400" />
          </button>
          <button
            onClick={onDelete}
            className="p-1 hover:bg-zinc-700 rounded transition-colors"
            title="Delete"
          >
            <Icon name="trash" size="sm" className="w-3.5 h-3.5 text-rose-400" />
          </button>
        </div>
      </td>
    </tr>
  );
};

/**
 * New Alert Modal Component
 */
interface NewAlertModalProps {
  onClose: () => void;
  editingAlert?: Alert | null;
}

const NewAlertModal: React.FC<NewAlertModalProps> = ({ onClose, editingAlert }) => {
  const { addAlert, updateAlert } = useAlertStore();
  const [symbol, setSymbol] = useState(editingAlert?.symbol || '');
  const [condition, setCondition] = useState<AlertCondition>(editingAlert?.condition || 'price_above');
  const [price, setPrice] = useState(editingAlert?.price.toString() || '');
  const [expiration, setExpiration] = useState<string>('none');
  const [notifyMethod, setNotifyMethod] = useState<NotifyMethod>(editingAlert?.notifyMethod || 'both');
  const [message, setMessage] = useState(editingAlert?.message || '');
  const [error, setError] = useState('');

  // Available symbols - fetched from API
  const [availableSymbols, setAvailableSymbols] = useState<string[]>([]);
  const [isLoadingSymbols, setIsLoadingSymbols] = useState(false);

  // Fetch available symbols on mount
  useEffect(() => {
    const fetchSymbols = async () => {
      setIsLoadingSymbols(true);
      try {
        // Placeholder: Replace with actual API call
        // const response = await fetch(API_ENDPOINTS.market.symbols);
        // if (response.ok) {
        //   const data = await response.json();
        //   setAvailableSymbols(data.symbols || []);
        // }

        // Empty until API is implemented
        setAvailableSymbols([]);
      } catch (error) {
        console.error('[AlertManager] Failed to fetch symbols:', error);
        setAvailableSymbols([]);
      } finally {
        setIsLoadingSymbols(false);
      }
    };

    fetchSymbols();
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!symbol) {
      setError('Please select a symbol');
      return;
    }

    if (!price || isNaN(parseFloat(price))) {
      setError('Please enter a valid price');
      return;
    }

    // Calculate expiration timestamp
    let expirationTime: number | null = null;
    const now = Date.now();
    switch (expiration) {
      case '1h':
        expirationTime = now + 60 * 60 * 1000;
        break;
      case '4h':
        expirationTime = now + 4 * 60 * 60 * 1000;
        break;
      case '1d':
        expirationTime = now + 24 * 60 * 60 * 1000;
        break;
      case '1w':
        expirationTime = now + 7 * 24 * 60 * 60 * 1000;
        break;
    }

    if (editingAlert) {
      // Update existing alert
      updateAlert(editingAlert.id, {
        symbol,
        condition,
        price: parseFloat(price),
        expiration: expirationTime,
        notifyMethod,
        message: message || undefined,
      });
    } else {
      // Create new alert
      addAlert({
        symbol,
        condition,
        price: parseFloat(price),
        expiration: expirationTime,
        notifyMethod,
        message: message || undefined,
      });
    }

    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[9999]" onClick={onClose}>
      <div className="bg-[#131316] border border-zinc-800 rounded-lg shadow-2xl w-[480px] max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-zinc-800 bg-[#252525] sticky top-0 z-10">
          <h3 className="text-lg font-bold text-zinc-200">
            {editingAlert ? 'Edit Alert' : 'New Price Alert'}
          </h3>
          <button onClick={onClose} className="text-zinc-500 hover:text-zinc-300 transition-colors">
            <Icon name="x-close" size="sm" className="w-5 h-5" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          {/* Symbol */}
          <div>
            <label className="block text-xs text-zinc-500 mb-1.5 font-medium">Symbol *</label>
            {isLoadingSymbols ? (
              <div className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-500">
                Loading symbols...
              </div>
            ) : availableSymbols.length === 0 ? (
              <input
                type="text"
                value={symbol}
                onChange={(e) => setSymbol(e.target.value.toUpperCase())}
                placeholder="Enter symbol (e.g., EURUSD)"
                required
                className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-300 focus:outline-none focus:border-zinc-600"
              />
            ) : (
              <select
                value={symbol}
                onChange={(e) => setSymbol(e.target.value)}
                required
                className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-300 focus:outline-none focus:border-zinc-600"
              >
                <option value="">Select symbol...</option>
                {availableSymbols.map((sym) => (
                  <option key={sym} value={sym}>
                    {sym}
                  </option>
                ))}
              </select>
            )}
          </div>

          {/* Condition */}
          <div>
            <label className="block text-xs text-zinc-500 mb-1.5 font-medium">Condition *</label>
            <select
              value={condition}
              onChange={(e) => setCondition(e.target.value as AlertCondition)}
              required
              className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-300 focus:outline-none focus:border-zinc-600"
            >
              <option value="price_above">Price Above</option>
              <option value="price_below">Price Below</option>
              <option value="bid_above">Bid Above</option>
              <option value="bid_below">Bid Below</option>
              <option value="ask_above">Ask Above</option>
              <option value="ask_below">Ask Below</option>
            </select>
          </div>

          {/* Price */}
          <div>
            <label className="block text-xs text-zinc-500 mb-1.5 font-medium">Price *</label>
            <input
              type="number"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
              placeholder="0.00000"
              step="0.00001"
              required
              className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-300 font-mono focus:outline-none focus:border-zinc-600"
            />
          </div>

          {/* Expiration */}
          <div>
            <label className="block text-xs text-zinc-500 mb-1.5 font-medium">Expiration</label>
            <select
              value={expiration}
              onChange={(e) => setExpiration(e.target.value)}
              className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-300 focus:outline-none focus:border-zinc-600"
            >
              <option value="none">Never</option>
              <option value="1h">1 Hour</option>
              <option value="4h">4 Hours</option>
              <option value="1d">1 Day</option>
              <option value="1w">1 Week</option>
            </select>
          </div>

          {/* Notification Method */}
          <div>
            <label className="block text-xs text-zinc-500 mb-1.5 font-medium">Notification Method</label>
            <div className="flex gap-2">
              <label className="flex-1 flex items-center gap-2 px-3 py-2 bg-[#252525] border border-zinc-700 rounded cursor-pointer hover:bg-zinc-800 transition-colors">
                <input
                  type="radio"
                  name="notifyMethod"
                  value="sound"
                  checked={notifyMethod === 'sound'}
                  onChange={(e) => setNotifyMethod(e.target.value as NotifyMethod)}
                  className="text-blue-500"
                />
                <span className="text-sm text-zinc-300">Sound</span>
              </label>
              <label className="flex-1 flex items-center gap-2 px-3 py-2 bg-[#252525] border border-zinc-700 rounded cursor-pointer hover:bg-zinc-800 transition-colors">
                <input
                  type="radio"
                  name="notifyMethod"
                  value="push"
                  checked={notifyMethod === 'push'}
                  onChange={(e) => setNotifyMethod(e.target.value as NotifyMethod)}
                  className="text-blue-500"
                />
                <span className="text-sm text-zinc-300">Push</span>
              </label>
              <label className="flex-1 flex items-center gap-2 px-3 py-2 bg-[#252525] border border-zinc-700 rounded cursor-pointer hover:bg-zinc-800 transition-colors">
                <input
                  type="radio"
                  name="notifyMethod"
                  value="both"
                  checked={notifyMethod === 'both'}
                  onChange={(e) => setNotifyMethod(e.target.value as NotifyMethod)}
                  className="text-blue-500"
                />
                <span className="text-sm text-zinc-300">Both</span>
              </label>
            </div>
          </div>

          {/* Message */}
          <div>
            <label className="block text-xs text-zinc-500 mb-1.5 font-medium">Custom Message (Optional)</label>
            <textarea
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              placeholder="Enter custom alert message..."
              rows={3}
              className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-sm text-zinc-300 resize-none focus:outline-none focus:border-zinc-600"
            />
          </div>

          {/* Error Message */}
          {error && (
            <div className="p-3 bg-rose-500/10 border border-rose-500/30 rounded text-xs text-rose-400">
              {error}
            </div>
          )}

          {/* Submit Button */}
          <button
            type="submit"
            className="w-full py-2.5 bg-zinc-700 hover:bg-zinc-600 text-white text-sm font-medium rounded transition-colors"
          >
            {editingAlert ? 'Update Alert' : 'Create Alert'}
          </button>
        </form>
      </div>
    </div>
  );
};

