import { useState, FormEvent } from 'react';
import { api } from '../services/api';

interface ChangePasswordDialogProps {
    isOpen: boolean;
    onClose: () => void;
    accountLogin?: string;
}

export function ChangePasswordDialog({ isOpen, onClose, accountLogin }: ChangePasswordDialogProps) {
    const [oldPassword, setOldPassword] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [type, setType] = useState<'master' | 'investor'>('master');

    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    if (!isOpen || !accountLogin) return null;

    const handleSubmit = async (e: FormEvent) => {
        e.preventDefault();
        if (!oldPassword || !newPassword || !confirmPassword) {
            setError('Please fill in all fields');
            return;
        }

        if (newPassword !== confirmPassword) {
            setError('New passwords do not match');
            return;
        }

        setIsLoading(true);
        setError('');
        setSuccess('');

        try {
            const loginNum = parseInt(accountLogin, 10);
            const res = await api.mt5.changePassword(loginNum, oldPassword, newPassword, type);

            if (res.success) {
                setSuccess(res.message || 'Password changed successfully');
                // Clear form
                setOldPassword('');
                setNewPassword('');
                setConfirmPassword('');

                // Auto-close after success
                setTimeout(() => {
                    onClose();
                    setSuccess('');
                }, 2000);
            } else {
                setError(res.message || 'Failed to change password');
            }
        } catch (err: any) {
            setError(err.response?.data?.message || err.message || 'An error occurred while changing password');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm" onClick={onClose}>
            <div
                className="bg-[#131316] border border-zinc-700 rounded-lg shadow-2xl w-[400px] overflow-hidden"
                onClick={e => e.stopPropagation()}
            >
                <div className="flex items-center justify-between px-4 py-3 border-b border-zinc-800 bg-[#191a1e]">
                    <h2 className="text-zinc-200 font-medium">Change Password - {accountLogin}</h2>
                    <button onClick={onClose} className="text-zinc-400 hover:text-white transition-colors">
                        Γ£ò
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-4 space-y-4">
                    <div className="space-y-1">
                        <label className="text-xs text-zinc-400">Password Type</label>
                        <select
                            value={type}
                            onChange={(e) => setType(e.target.value as 'master' | 'investor')}
                            className="w-full bg-[#0d0d11] border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-200 focus:outline-none focus:border-zinc-600"
                        >
                            <option value="master">Master Password</option>
                            <option value="investor">Investor Password (Read-only)</option>
                        </select>
                    </div>

                    <div className="space-y-1">
                        <label className="text-xs text-zinc-400">Current Password</label>
                        <input
                            type="password"
                            value={oldPassword}
                            onChange={(e) => setOldPassword(e.target.value)}
                            className="w-full bg-[#0d0d11] border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-200 focus:outline-none focus:border-zinc-600"
                            placeholder="Enter current password"
                        />
                    </div>

                    <div className="space-y-1">
                        <label className="text-xs text-zinc-400">New Password</label>
                        <input
                            type="password"
                            value={newPassword}
                            onChange={(e) => setNewPassword(e.target.value)}
                            className="w-full bg-[#0d0d11] border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-200 focus:outline-none focus:border-zinc-600"
                            placeholder="Enter new password"
                        />
                    </div>

                    <div className="space-y-1">
                        <label className="text-xs text-zinc-400">Confirm New Password</label>
                        <input
                            type="password"
                            value={confirmPassword}
                            onChange={(e) => setConfirmPassword(e.target.value)}
                            className="w-full bg-[#0d0d11] border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-200 focus:outline-none focus:border-zinc-600"
                            placeholder="Confirm new password"
                        />
                    </div>

                    {error && (
                        <div className="p-2 bg-red-500/10 border border-red-500/20 text-red-500 text-xs rounded">
                            {error}
                        </div>
                    )}

                    {success && (
                        <div className="p-2 bg-green-500/10 border border-green-500/20 text-green-500 text-xs rounded">
                            {success}
                        </div>
                    )}

                    <div className="pt-2">
                        <button
                            type="submit"
                            disabled={isLoading}
                            className="w-full bg-zinc-700 hover:bg-zinc-600 text-white font-medium py-2 rounded transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            {isLoading ? 'Changing...' : 'Change Password'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

import { Icon } from './ui/Icon';
import React, { useState } from 'react';
import type { ChartType, Timeframe } from './TradingChart';
import { indicatorManager } from '../services/indicatorManager';
import { useTemplates } from '../store/useTemplateStore';
import { ChartTemplateDialog } from './ChartTemplateDialog';
import type { ChartTemplate } from '../store/useTemplateStore';

interface ChartContextMenuProps {
    visible: boolean;
    x: number;
    y: number;
    currentChartType: ChartType;
    currentTimeframe: Timeframe;
    onChangeChartType: (type: ChartType) => void;
    onChangeTimeframe: (tf: Timeframe) => void;
    onToggleOneClickTrading: () => void;
    onToggleGrid: () => void;
    onToggleVolumes: () => void;
    onOpenProperties: () => void;
    onSaveAsPicture: () => void;
    onPrintChart: () => void;
    onClose: () => void;
    oneClickTrading?: boolean;
    showGrid?: boolean;
    showVolumes?: boolean;
    onLoadTemplate?: (template: ChartTemplate) => void;
    currentIndicators?: any[];
    currentDrawingTools?: any[];
}

export const ChartContextMenu: React.FC<ChartContextMenuProps> = ({
    visible,
    x,
    y,
    currentChartType,
    currentTimeframe,
    onChangeChartType,
    onChangeTimeframe,
    onToggleOneClickTrading,
    onToggleGrid,
    onToggleVolumes,
    onOpenProperties,
    onSaveAsPicture,
    onPrintChart,
    onClose,
    oneClickTrading = false,
    showGrid = true,
    showVolumes = true,
    onLoadTemplate,
    currentIndicators = [],
    currentDrawingTools = []
}) => {
    const templates = useTemplates();
    const [templateDialogOpen, setTemplateDialogOpen] = useState(false);
    const [templateDialogMode, setTemplateDialogMode] = useState<'save' | 'load'>('load');

    if (!visible) return null;

    const timeframes: Timeframe[] = ['M1', 'M5', 'M15', 'M30', 'H1', 'H4', 'D1', 'W1', 'MN'];

    const chartTypes: { value: ChartType; label: string; icon: React.ReactNode }[] = [
        { value: 'candlestick', label: 'Candlestick', icon: <Icon name="bar-chart-2" size="sm" /> },
        { value: 'bar', label: 'Bar Chart', icon: <Icon name="bar-chart-2" size="sm" /> },
        { value: 'line', label: 'Line Chart', icon: <Icon name="line-chart" size="sm" /> },
        { value: 'area', label: 'Area Chart', icon: <Icon name="activity" size="sm" /> },
        { value: 'heikinAshi' as any, label: 'Heikin-Ashi', icon: <Icon name="trending-up" size="sm" /> }
    ];

    const indicators = [
        { name: 'Moving Average', type: 'sma' },
        { name: 'Exponential MA', type: 'ema' },
        { name: 'Bollinger Bands', type: 'bb' },
        { name: 'RSI', type: 'rsi' },
        { name: 'MACD', type: 'macd' },
        { name: 'Stochastic', type: 'stochastic' },
        { name: 'CCI', type: 'cci' },
        { name: 'Momentum', type: 'momentum' }
    ];

    const drawingTools = [
        { name: 'Trendline', tool: 'trendline' },
        { name: 'Horizontal Line', tool: 'hline' },
        { name: 'Vertical Line', tool: 'vline' },
        { name: 'Fibonacci Retracement', tool: 'fibonacci' },
        { name: 'Trend Channel', tool: 'channel' },
        { name: 'Text/Annotation', tool: 'text' },
        { name: 'Shapes', tool: 'shapes' }
    ];

    const handleAddIndicator = (type: string) => {
        const id = `${type}-${Date.now()}`;
        indicatorManager.addIndicator({
            id,
            name: type.toUpperCase(),
            type,
            parameters: {},
            visible: true
        });
        onClose();
    };

    const handleSelectDrawingTool = async (tool: string) => {
        try {
            const commandBusModule = await import('../services/commandBus');
            const commandBus = commandBusModule.commandBus;
            if (commandBus && typeof commandBus.subscribe === 'function') {
                // Trigger tool selection - the command bus may not have a publish method
                // Use a custom event instead
                window.dispatchEvent(new CustomEvent('drawing:select-tool', {
                    detail: { tool }
                }));
            }
            onClose();
        } catch (error) {
            console.log('Command bus not available');
        }
    };

    const handleOpenSaveTemplateDialog = () => {
        setTemplateDialogMode('save');
        setTemplateDialogOpen(true);
        onClose();
    };

    const handleOpenLoadTemplateDialog = () => {
        setTemplateDialogMode('load');
        setTemplateDialogOpen(true);
        onClose();
    };

    const handleTemplateLoad = (template: ChartTemplate) => {
        if (onLoadTemplate) {
            onLoadTemplate(template);
        }
        setTemplateDialogOpen(false);
    };

    const currentConfig = {
        chartType: currentChartType,
        timeframe: currentTimeframe,
        showGrid,
        showVolumes,
        indicators: currentIndicators,
        drawingTools: currentDrawingTools,
        colors: {
            background: '#000000',
            grid: '#2b2b2b',
            candle: { up: '#26a69a', down: '#ef5350', border: '#378658' },
            volume: { up: '#26a69a', down: '#ef5350' },
        },
    };

    return (
        <div
            className="fixed z-[1000] bg-[#131316] border border-zinc-800 rounded shadow-2xl py-1 w-56 animate-in fade-in zoom-in-95 duration-100"
            style={{ left: x, top: y }}
            onMouseLeave={onClose}
            onClick={(e) => e.stopPropagation()}
        >
            {/* Timeframe Submenu */}
            <div className="group/submenu relative">
                <ContextMenuItem
                    icon={<Icon name="clock" size="sm" />}
                    label="Timeframe"
                    hasSubmenu
                />
                <div className="absolute left-full top-0 ml-1 hidden group-hover/submenu:block bg-[#131316] border border-zinc-800 rounded shadow-2xl py-1 w-32 animate-in fade-in slide-in-from-left-2 duration-100">
                    {timeframes.map((tf) => (
                        <ContextMenuItem
                            key={tf}
                            label={tf}
                            onClick={() => {
                                onChangeTimeframe(tf);
                                onClose();
                            }}
                            active={currentTimeframe === tf}
                            icon={null}
                        />
                    ))}
                </div>
            </div>

            {/* Chart Type Submenu */}
            <div className="group/submenu relative">
                <ContextMenuItem
                    icon={<Icon name="bar-chart-2" size="sm" />}
                    label="Chart Type"
                    hasSubmenu
                />
                <div className="absolute left-full top-0 ml-1 hidden group-hover/submenu:block bg-[#131316] border border-zinc-800 rounded shadow-2xl py-1 w-48 animate-in fade-in slide-in-from-left-2 duration-100">
                    {chartTypes.map((ct) => (
                        <ContextMenuItem
                            key={ct.value}
                            icon={ct.icon}
                            label={ct.label}
                            onClick={() => {
                                onChangeChartType(ct.value);
                                onClose();
                            }}
                            active={currentChartType === ct.value}
                        />
                    ))}
                </div>
            </div>

            {/* Indicators Submenu */}
            <div className="group/submenu relative">
                <ContextMenuItem
                    icon={<Icon name="trending-up" size="sm" />}
                    label="Indicators"
                    hasSubmenu
                />
                <div className="absolute left-full top-0 ml-1 hidden group-hover/submenu:block bg-[#131316] border border-zinc-800 rounded shadow-2xl py-1 w-48 animate-in fade-in slide-in-from-left-2 duration-100 max-h-80 overflow-y-auto">
                    {indicators.map((ind) => (
                        <ContextMenuItem
                            key={ind.type}
                            label={ind.name}
                            onClick={() => handleAddIndicator(ind.type)}
                            icon={null}
                        />
                    ))}
                </div>
            </div>

            {/* Drawing Tools Submenu */}
            <div className="group/submenu relative">
                <ContextMenuItem
                    icon={<Icon name="activity" size="sm" />}
                    label="Drawing Tools"
                    hasSubmenu
                />
                <div className="absolute left-full top-0 ml-1 hidden group-hover/submenu:block bg-[#131316] border border-zinc-800 rounded shadow-2xl py-1 w-48 animate-in fade-in slide-in-from-left-2 duration-100">
                    {drawingTools.map((tool) => (
                        <ContextMenuItem
                            key={tool.tool}
                            label={tool.name}
                            onClick={() => handleSelectDrawingTool(tool.tool)}
                            icon={null}
                        />
                    ))}
                </div>
            </div>

            {/* Templates Submenu */}
            <div className="group/submenu relative">
                <ContextMenuItem
                    icon={<Icon name="layers" size="sm" />}
                    label="Templates"
                    hasSubmenu
                />
                <div className="absolute left-full top-0 ml-1 hidden group-hover/submenu:block bg-[#131316] border border-zinc-800 rounded shadow-2xl py-1 w-56 animate-in fade-in slide-in-from-left-2 duration-100 max-h-96 overflow-y-auto">
                    {/* Quick actions */}
                    <ContextMenuItem
                        icon={<Icon name="save" size="sm" />}
                        label="Save Template..."
                        onClick={handleOpenSaveTemplateDialog}
                    />
                    <ContextMenuItem
                        icon={<Icon name="folder-open" size="sm" />}
                        label="Manage Templates..."
                        onClick={handleOpenLoadTemplateDialog}
                    />

                    {templates.length > 0 && (
                        <>
                            <div className="h-[1px] bg-zinc-800 my-1 mx-2" />
                            <div className="px-3 py-1 text-[10px] text-zinc-600 uppercase tracking-wide">
                                Quick Load
                            </div>
                            {templates.slice(0, 8).map((template) => (
                                <ContextMenuItem
                                    key={template.id}
                                    label={template.name}
                                    onClick={() => {
                                        handleTemplateLoad(template);
                                        onClose();
                                    }}
                                    icon={null}
                                />
                            ))}
                        </>
                    )}
                </div>
            </div>

            <div className="h-[1px] bg-zinc-800 my-1 mx-2" />

            {/* Toggle Options */}
            <ContextMenuItem
                icon={<Icon name="activity" size="sm" />}
                label="One-Click Trading"
                onClick={() => {
                    onToggleOneClickTrading();
                    onClose();
                }}
                active={oneClickTrading}
            />
            <ContextMenuItem
                icon={<Icon name="grid-3x3" size="sm" />}
                label="Show Grid"
                onClick={() => {
                    onToggleGrid();
                    onClose();
                }}
                active={showGrid}
            />
            <ContextMenuItem
                icon={<Icon name="volume" size="sm" />}
                label="Show Volumes"
                onClick={() => {
                    onToggleVolumes();
                    onClose();
                }}
                active={showVolumes}
            />

            <div className="h-[1px] bg-zinc-800 my-1 mx-2" />

            {/* Actions */}
            <ContextMenuItem
                icon={<Icon name="settings" size="sm" />}
                label="Properties"
                onClick={() => {
                    onOpenProperties();
                    onClose();
                }}
            />
            <ContextMenuItem
                icon={<Icon name="image" size="sm" />}
                label="Save As Picture"
                onClick={() => {
                    onSaveAsPicture();
                    onClose();
                }}
            />
            <ContextMenuItem
                icon={<Icon name="print" size="sm" />}
                label="Print Chart"
                onClick={() => {
                    onPrintChart();
                    onClose();
                }}
            />

            {/* Template Dialog */}
            <ChartTemplateDialog
                isOpen={templateDialogOpen}
                onClose={() => setTemplateDialogOpen(false)}
                mode={templateDialogMode}
                currentConfig={currentConfig}
                onLoadTemplate={handleTemplateLoad}
            />
        </div>
    );
};

interface ContextMenuItemProps {
    icon: React.ReactNode;
    label: string;
    onClick?: () => void;
    hasSubmenu?: boolean;
    active?: boolean;
}

const ContextMenuItem: React.FC<ContextMenuItemProps> = ({
    icon,
    label,
    onClick,
    hasSubmenu,
    active
}) => (
    <div
        className={`flex items-center justify-between px-3 py-2 text-[12px] text-zinc-300 hover:bg-[#2d2d2d] hover:text-white cursor-pointer transition-colors ${active ? 'bg-[#2d2d2d] text-white' : ''
            }`}
        onClick={(e) => {
            e.stopPropagation();
            if (onClick) onClick();
        }}
    >
        <div className="flex items-center gap-3">
            {icon && <span className="text-zinc-500">{icon}</span>}
