);

import React, { useState, useCallback } from 'react';
import './ChartImageUpload.css';
import { API_ENDPOINTS } from '../config/api';

interface UploadResponse {
    status: string;
    detected_pairs: string[];
    confidence: number;
    analysis_id: string;
    timestamp: string;
    message?: string;
}

interface ChartImageUploadProps {
    onPairsDetected: (pairs: string[]) => void;
}

export const ChartImageUpload: React.FC<ChartImageUploadProps> = ({ onPairsDetected }) => {
    const [dragActive, setDragActive] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [detectedPairs, setDetectedPairs] = useState<string[]>([]);
    const [confidence, setConfidence] = useState<number>(0);
    const [previewImage, setPreviewImage] = useState<string | null>(null);

    const handleDrag = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === "dragenter" || e.type === "dragover") {
            setDragActive(true);
        } else if (e.type === "dragleave") {
            setDragActive(false);
        }
    }, []);

    const handleDrop = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setDragActive(false);

        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            handleFile(e.dataTransfer.files[0]);
        }
    }, []);

    const handleChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
        e.preventDefault();
        if (e.target.files && e.target.files[0]) {
            handleFile(e.target.files[0]);
        }
    }, []);

    const handleFile = async (file: File) => {
        // Validate file type
        if (!file.type.match(/image\/(png|jpeg|jpg)/)) {
            setError('Please upload a PNG or JPEG image');
            return;
        }

        // Validate file size (max 10MB)
        if (file.size > 10 * 1024 * 1024) {
            setError('Image size must be less than 10MB');
            return;
        }

        // Show preview
        const reader = new FileReader();
        reader.onload = (e) => {
            setPreviewImage(e.target?.result as string);
        };
        reader.readAsDataURL(file);

        // Upload to backend
        try {
            setUploading(true);
            setError(null);
            setDetectedPairs([]);

            const formData = new FormData();
            formData.append('image', file);

            const response = await fetch(API_ENDPOINTS.chartAnalysis.upload, {
                method: 'POST',
                body: formData,
            });

            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.message || 'Failed to analyze image');
            }

            const result: UploadResponse = await response.json();

            console.log('[ChartUpload] AI detected:', result.detected_pairs);
            console.log('[ChartUpload] Confidence:', result.confidence);

            if (result.detected_pairs.length === 0) {
                setError('No forex symbols detected in this image. Please upload an image showing a market watch or trading chart.');
                return;
            }

            setDetectedPairs(result.detected_pairs);
            setConfidence(result.confidence);
            onPairsDetected(result.detected_pairs);

        } catch (err) {
            console.error('[ChartUpload] Error:', err);
            setError(err instanceof Error ? err.message : 'Failed to analyze image');
        } finally {
            setUploading(false);
        }
    };

    const clearUpload = () => {
        setPreviewImage(null);
        setDetectedPairs([]);
        setConfidence(0);
        setError(null);
    };

    return (
        <div className="chart-image-upload">
            <div className="upload-header">
                <h2>≡ƒô╕ AI Chart Analysis</h2>
                <p>Upload your market watch image to detect symbols</p>
            </div>

            {!previewImage ? (
                <form
                    className={`upload-form ${dragActive ? 'drag-active' : ''}`}
                    onDragEnter={handleDrag}
                    onDragLeave={handleDrag}
                    onDragOver={handleDrag}
                    onDrop={handleDrop}
                    onSubmit={(e) => e.preventDefault()}
                >
                    <input
                        type="file"
                        id="image-upload"
                        accept="image/png,image/jpeg,image/jpg"
                        onChange={handleChange}
                        style={{ display: 'none' }}
                    />
                    <label htmlFor="image-upload" className="upload-label">
                        <div className="upload-icon">≡ƒôü</div>
                        <p className="upload-text">
                            {dragActive ? 'Drop image here' : 'Drag & drop or click to upload'}
                        </p>
                        <p className="upload-hint">PNG or JPEG ΓÇó Max 10MB</p>
                    </label>
                </form>
            ) : (
                <div className="upload-results">
                    <div className="preview-section">
                        <img src={previewImage} alt="Uploaded chart" className="preview-image" />
                        <button className="clear-btn" onClick={clearUpload}>
                            Γ£ò Clear
                        </button>
                    </div>

                    {uploading && (
                        <div className="analyzing-state">
                            <div className="spinner"></div>
                            <p>≡ƒñû AI is analyzing your image...</p>
                        </div>
                    )}

                    {error && (
                        <div className="error-box">
                            <p>ΓÜá∩╕Å {error}</p>
                        </div>
                    )}

                    {detectedPairs.length > 0 && (
                        <div className="detected-pairs">
                            <div className="detected-header">
                                <h3>Γ£à Detected Symbols ({detectedPairs.length})</h3>
                                <span className="confidence-badge">
                                    {(confidence * 100).toFixed(0)}% confidence
                                </span>
                            </div>
                            <div className="pairs-grid">
                                {detectedPairs.map((pair) => (
                                    <div key={pair} className="pair-card">
                                        <span className="pair-symbol">{pair}</span>
                                    </div>
                                ))}
                            </div>
                            <p className="strict-notice">
                                Γä╣∩╕Å <strong>Strict Mode:</strong> Showing ONLY symbols visible in your image
                            </p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default ChartImageUpload;

/**
 * Chart Template Management Dialog
 * Allows users to save, load, and delete chart templates
 * MT5-inspired UI for template management
 */

import { Icon } from './ui/Icon';
import React, { useState } from 'react';
import { useTemplateStore, type ChartTemplate } from '../store/useTemplateStore';
import type { ChartType, Timeframe } from './TradingChart';

interface ChartTemplateDialogProps {
  isOpen: boolean;
  onClose: () => void;
  mode: 'save' | 'load';
  currentConfig?: {
    chartType: ChartType;
    timeframe: Timeframe;
    showGrid: boolean;
    showVolumes: boolean;
    indicators: any[];
    drawingTools: any[];
    colors: any;
  };
  onLoadTemplate?: (template: ChartTemplate) => void;
}

export const ChartTemplateDialog: React.FC<ChartTemplateDialogProps> = ({
  isOpen,
  onClose,
  mode,
  currentConfig,
  onLoadTemplate,
}) => {
  const { templates, saveTemplate, deleteTemplate, loadTemplate } = useTemplateStore();
  const [templateName, setTemplateName] = useState('');
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);
  const [showSaveInput, setShowSaveInput] = useState(mode === 'save');

  if (!isOpen) return null;

  const handleSaveTemplate = () => {
    if (!templateName.trim()) {
      alert('Please enter a template name');
      return;
    }

    if (!currentConfig) {
      alert('No chart configuration available');
      return;
    }

    const newTemplate = saveTemplate({
      name: templateName,
      chartType: currentConfig.chartType,
      timeframe: currentConfig.timeframe,
      showGrid: currentConfig.showGrid,
      showVolumes: currentConfig.showVolumes,
      indicators: currentConfig.indicators || [],
      drawingTools: currentConfig.drawingTools || [],
      colors: currentConfig.colors || {
        background: '#000000',
        grid: '#2b2b2b',
        candle: { up: '#26a69a', down: '#ef5350', border: '#378658' },
        volume: { up: '#26a69a', down: '#ef5350' },
      },
    });

    console.log('[ChartTemplateDialog] Saved template:', newTemplate);
    setTemplateName('');
    setShowSaveInput(false);
  };

  const handleLoadTemplate = (templateId: string) => {
    const template = loadTemplate(templateId);
    if (template && onLoadTemplate) {
      onLoadTemplate(template);
      onClose();
    }
  };

  const handleDeleteTemplate = (templateId: string) => {
    const template = templates.find((t) => t.id === templateId);
    if (template?.isDefault) {
      alert('Cannot delete default templates');
      return;
    }

    if (confirm(`Delete template "${template?.name}"?`)) {
      deleteTemplate(templateId);
      if (selectedTemplate === templateId) {
        setSelectedTemplate(null);
      }
    }
  };

  const defaultTemplates = templates.filter((t) => t.isDefault);
  const customTemplates = templates.filter((t) => !t.isDefault);

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-[#131316] border border-zinc-700 rounded-lg shadow-2xl w-[600px] max-h-[80vh] flex flex-col animate-in zoom-in-95 duration-200">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-zinc-700">
          <div className="flex items-center gap-2">
            {mode === 'save' ? (
              <Icon name="save" size="lg" className="text-emerald-500" />
            ) : (
              <Icon name="download" size="lg" className="text-blue-500" />
            )}
            <h2 className="text-base font-semibold text-zinc-200">
              {mode === 'save' ? 'Save Chart Template' : 'Load Chart Template'}
            </h2>
          </div>
          <button
            onClick={onClose}
            className="text-zinc-400 hover:text-white transition-colors p-1 hover:bg-zinc-700/50 rounded"
          >
            <Icon name="x-close" size="lg" />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {/* Save Input */}
          {mode === 'save' && showSaveInput && (
            <div className="bg-[#252526] border border-zinc-700 rounded-lg p-4">
              <label className="block text-xs text-zinc-400 mb-2 font-medium">
                Template Name
              </label>
              <div className="flex gap-2">
                <input
                  type="text"
                  value={templateName}
                  onChange={(e) => setTemplateName(e.target.value)}
                  placeholder="My Custom Template"
                  className="flex-1 bg-[#131316] border border-zinc-600 rounded px-3 py-2 text-sm text-white placeholder-zinc-500 focus:outline-none focus:border-emerald-500"
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      handleSaveTemplate();
                    }
                  }}
                  autoFocus
                />
                <button
                  onClick={handleSaveTemplate}
                  className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-sm rounded font-medium transition-colors"
                >
                  Save
                </button>
              </div>
              {currentConfig && (
                <div className="mt-3 text-xs text-zinc-500 space-y-1">
                  <div className="flex justify-between">
                    <span>Chart Type:</span>
                    <span className="text-zinc-400 font-mono">{currentConfig.chartType}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Timeframe:</span>
                    <span className="text-zinc-400 font-mono">{currentConfig.timeframe}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Indicators:</span>
                    <span className="text-zinc-400">{currentConfig.indicators?.length || 0}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Grid:</span>
                    <span className="text-zinc-400">{currentConfig.showGrid ? 'On' : 'Off'}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Volumes:</span>
                    <span className="text-zinc-400">{currentConfig.showVolumes ? 'On' : 'Off'}</span>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Default Templates */}
          {defaultTemplates.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-2">
                <Icon name="check-circle" size="sm" className="text-yellow-500" />
                <h3 className="text-xs font-semibold text-zinc-400 uppercase tracking-wide">
                  Default Templates
                </h3>
              </div>
              <div className="space-y-2">
                {defaultTemplates.map((template) => (
                  <TemplateCard
                    key={template.id}
                    template={template}
                    isSelected={selectedTemplate === template.id}
                    onSelect={() => setSelectedTemplate(template.id)}
                    onLoad={() => handleLoadTemplate(template.id)}
                    onDelete={null} // Cannot delete defaults
                    mode={mode}
                  />
                ))}
              </div>
            </div>
          )}

          {/* Custom Templates */}
          {customTemplates.length > 0 && (
            <div>
              <h3 className="text-xs font-semibold text-zinc-400 uppercase tracking-wide mb-2">
                Custom Templates
              </h3>
              <div className="space-y-2">
                {customTemplates.map((template) => (
                  <TemplateCard
                    key={template.id}
                    template={template}
                    isSelected={selectedTemplate === template.id}
                    onSelect={() => setSelectedTemplate(template.id)}
                    onLoad={() => handleLoadTemplate(template.id)}
                    onDelete={() => handleDeleteTemplate(template.id)}
                    mode={mode}
                  />
                ))}
              </div>
            </div>
          )}

          {customTemplates.length === 0 && mode === 'load' && !showSaveInput && (
            <div className="text-center py-12 text-zinc-500 text-sm">
              <Icon name="plus" size="xl" className="mx-auto mb-3 opacity-50" />
              <p>No custom templates saved yet.</p>
              <p className="text-xs mt-1">Right-click on chart and select "Templates" to save one.</p>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-2 px-4 py-3 border-t border-zinc-700 bg-[#252526]">
          <button
            onClick={onClose}
            className="px-4 py-2 bg-zinc-700 hover:bg-zinc-600 text-white text-sm rounded font-medium transition-colors"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

interface TemplateCardProps {
  template: ChartTemplate;
  isSelected: boolean;
  onSelect: () => void;
  onLoad: () => void;
  onDelete: (() => void) | null;
  mode: 'save' | 'load';
}

const TemplateCard: React.FC<TemplateCardProps> = ({
  template,
  isSelected,
  onSelect,
  onLoad,
  onDelete,
  mode,
}) => {
  return (
    <div
      className={`bg-[#252526] border rounded-lg p-3 cursor-pointer transition-all ${
        isSelected
          ? 'border-zinc-600 shadow-lg shadow-blue-500/20'
          : 'border-zinc-700 hover:border-zinc-600'
      }`}
      onClick={onSelect}
    >
      <div className="flex items-start justify-between mb-2">
        <div className="flex-1">
          <div className="flex items-center gap-2">
            <h4 className="text-sm font-semibold text-zinc-200">{template.name}</h4>
            {template.isDefault && (
              <span className="text-[10px] bg-yellow-500/20 text-yellow-400 px-1.5 py-0.5 rounded border border-yellow-500/30">
                Default
              </span>
            )}
          </div>
          <p className="text-xs text-zinc-500 mt-1">
            {new Date(template.createdAt).toLocaleDateString()}
          </p>
        </div>
        <div className="flex gap-1">
          {mode === 'load' && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                onLoad();
              }}
              className="p-1.5 bg-zinc-700 hover:bg-zinc-600 text-white rounded transition-colors"
              title="Load template"
            >
              <Icon name="download" size="sm" />
            </button>
          )}
          {onDelete && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                onDelete();
              }}
              className="p-1.5 bg-red-600 hover:bg-red-700 text-white rounded transition-colors"
              title="Delete template"
            >
              <Icon name="trash" size="sm" />
            </button>
          )}
        </div>
      </div>

      {/* Template Preview */}
      <div className="grid grid-cols-2 gap-x-4 gap-y-1 text-xs">
        <div className="flex justify-between">
          <span className="text-zinc-500">Type:</span>
          <span className="text-zinc-400 font-mono">{template.chartType}</span>
        </div>
        <div className="flex justify-between">
          <span className="text-zinc-500">Timeframe:</span>
          <span className="text-zinc-400 font-mono">{template.timeframe}</span>
        </div>
        <div className="flex justify-between">
          <span className="text-zinc-500">Indicators:</span>
          <span className="text-zinc-400">{template.indicators.length}</span>
        </div>
        <div className="flex justify-between">
          <span className="text-zinc-500">Grid:</span>
          <span className={template.showGrid ? 'text-emerald-400' : 'text-zinc-600'}>
            {template.showGrid ? 'On' : 'Off'}
          </span>
        </div>
      </div>
    </div>
  );
};

/**
 * Chart Template Manager
 * Dropdown + Modal UI for saving/loading/managing chart templates
 */

import { Icon } from './ui/Icon';
import { useState, useRef } from 'react';
import { useChartTemplateStore, type ChartTemplate } from '../store/useChartTemplateStore';

interface ChartTemplateManagerProps {
  currentSymbol: string;
  currentTimeframe: 'M1' | 'M5' | 'M15' | 'M30' | 'H1' | 'H4' | 'D1' | 'W1' | 'MN';
  currentChartType: 'candlestick' | 'heikinAshi' | 'bar' | 'line' | 'area';
  currentShowVolume: boolean;
  currentShowGrid: boolean;
  currentIndicators: any[];
  currentDrawingTools: any[];
  onLoadTemplate: (template: ChartTemplate) => void;
}

export const ChartTemplateManager = ({
  currentSymbol,
  currentTimeframe,
  currentChartType,
  currentShowVolume,
  currentShowGrid,
  currentIndicators,
  currentDrawingTools,
  onLoadTemplate,
}: ChartTemplateManagerProps) => {
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [managerOpen, setManagerOpen] = useState(false);
  const [saveDialogOpen, setSaveDialogOpen] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState<ChartTemplate | null>(null);
  const [newTemplateName, setNewTemplateName] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const {
    templates,
    saveTemplate,
    deleteTemplate,
    renameTemplate,
    duplicateTemplate,
    importTemplates,
    exportTemplates,
  } = useChartTemplateStore();

  const handleSaveTemplate = (name: string) => {
    const template = saveTemplate({
      name,
      symbol: currentSymbol,
      timeframe: currentTimeframe,
      chartType: currentChartType,
      showVolume: currentShowVolume,
      showGrid: currentShowGrid,
      indicators: currentIndicators || [],
      drawingTools: currentDrawingTools || [],
    });

    setSaveDialogOpen(false);
    setNewTemplateName('');
    console.log('[ChartTemplateManager] Template saved:', template);
  };

  const handleQuickSave = () => {
    const name = `${currentSymbol} ${currentTimeframe} (${new Date().toLocaleString()})`;
    handleSaveTemplate(name);
    setDropdownOpen(false);
  };

  const handleLoadTemplate = (template: ChartTemplate) => {
    onLoadTemplate(template);
    setDropdownOpen(false);
    console.log('[ChartTemplateManager] Template loaded:', template);
  };

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Delete this template?')) {
      deleteTemplate(id);
    }
  };

  const handleRename = (template: ChartTemplate) => {
    const newName = prompt('Enter new template name:', template.name);
    if (newName && newName.trim()) {
      renameTemplate(template.id, newName.trim());
      setEditingTemplate(null);
    }
  };

  const handleDuplicate = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    duplicateTemplate(id);
  };

  const handleExport = () => {
    const data = exportTemplates();
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `chart-templates-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.version && data.templates && Array.isArray(data.templates)) {
          importTemplates(data.templates);
          alert(`Imported ${data.templates.length} template(s)`);
        } else {
          alert('Invalid template file format');
        }
      } catch (err) {
        console.error('Import error:', err);
        alert('Failed to import templates');
      }
    };
    reader.readAsText(file);

    // Reset input for re-import
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  return (
    <div className="relative">
      {/* Dropdown Button */}
      <button
        onClick={() => setDropdownOpen(!dropdownOpen)}
        className="flex items-center gap-2 px-3 py-1.5 text-xs font-medium bg-zinc-800 text-zinc-300 hover:bg-zinc-700 rounded border border-zinc-700 transition-colors"
      >
        <Icon name="save" size="sm" className="w-3.5 h-3.5" />
        Templates
        <Icon name="chevron-down" size="sm" className={`w-3.5 h-3.5 transition-transform ${dropdownOpen ? 'rotate-180' : ''}`} />
      </button>

      {/* Dropdown Menu */}
      {dropdownOpen && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setDropdownOpen(false)} />
          <div className="absolute top-full left-0 mt-1 w-72 bg-zinc-900 border border-zinc-800 rounded shadow-xl z-50 max-h-96 overflow-y-auto">
            {/* Quick Actions */}
            <div className="border-b border-zinc-800 p-2">
              <button
                onClick={handleQuickSave}
                className="w-full flex items-center gap-2 px-3 py-2 text-xs text-zinc-300 hover:bg-zinc-800 rounded transition-colors"
              >
                <Icon name="save" size="sm" className="w-3.5 h-3.5 text-emerald-500" />
                Save Current
              </button>
              <button
                onClick={() => {
                  setSaveDialogOpen(true);
                  setDropdownOpen(false);
                }}
                className="w-full flex items-center gap-2 px-3 py-2 text-xs text-zinc-300 hover:bg-zinc-800 rounded transition-colors"
              >
                <Icon name="plus" size="sm" className="w-3.5 h-3.5 text-blue-500" />
                Save As...
              </button>
            </div>

            {/* Template List */}
            <div className="py-1">
              {templates.length === 0 ? (
                <div className="px-4 py-6 text-center text-xs text-zinc-500">
                  No saved templates
                </div>
              ) : (
                templates.map((template) => (
                  <div
                    key={template.id}
                    className="group flex items-center gap-2 px-3 py-2 text-xs text-zinc-300 hover:bg-zinc-800 cursor-pointer transition-colors"
                    onClick={() => handleLoadTemplate(template)}
                  >
                    <div className="flex-1 min-w-0">
                      <div className="font-medium truncate">{template.name}</div>
                      <div className="text-[10px] text-zinc-500">
                        {template.symbol} ┬╖ {template.timeframe} ┬╖ {template.chartType}
                      </div>
                    </div>
                    <button
                      onClick={(e) => handleDelete(template.id, e)}
                      className="opacity-0 group-hover:opacity-100 p-1 hover:bg-zinc-700 rounded transition-opacity"
                      title="Delete"
                    >
                      <Icon name="trash" size="sm" className="w-3 h-3 text-red-400" />
                    </button>
                  </div>
                ))
              )}
            </div>

            {/* Manage Link */}
            <div className="border-t border-zinc-800 p-2">
              <button
                onClick={() => {
                  setManagerOpen(true);
                  setDropdownOpen(false);
                }}
                className="w-full px-3 py-2 text-xs text-blue-400 hover:bg-zinc-800 rounded transition-colors text-left"
              >
                Manage Templates...
              </button>
            </div>
          </div>
        </>
      )}

      {/* Save Dialog */}
      {saveDialogOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-zinc-900 border border-zinc-800 rounded-lg shadow-xl w-full max-w-md p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-zinc-100">Save Template</h3>
              <button
                onClick={() => {
                  setSaveDialogOpen(false);
                  setNewTemplateName('');
                }}
                className="p-1 hover:bg-zinc-800 rounded transition-colors"
              >
                <Icon name="x-close" size="sm" className="w-5 h-5 text-zinc-400" />
              </button>
            </div>

            <input
              type="text"
              value={newTemplateName}
              onChange={(e) => setNewTemplateName(e.target.value)}
              placeholder="Template name"
              className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded text-sm text-zinc-100 placeholder-zinc-500 focus:outline-none focus:border-zinc-600"
              autoFocus
              onKeyDown={(e) => {
                if (e.key === 'Enter' && newTemplateName.trim()) {
                  handleSaveTemplate(newTemplateName.trim());
                }
              }}
            />

            <div className="flex gap-2 mt-4">
              <button
                onClick={() => {
                  setSaveDialogOpen(false);
                  setNewTemplateName('');
                }}
                className="flex-1 px-4 py-2 text-sm font-medium bg-zinc-800 text-zinc-300 hover:bg-zinc-700 rounded transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={() => newTemplateName.trim() && handleSaveTemplate(newTemplateName.trim())}
                disabled={!newTemplateName.trim()}
                className="flex-1 px-4 py-2 text-sm font-medium bg-blue-600 text-white hover:bg-blue-700 rounded transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Save
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Template Manager Modal */}
      {managerOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-lg shadow-xl w-full max-w-4xl max-h-[80vh] flex flex-col">
            {/* Header */}
            <div className="flex items-center justify-between p-6 border-b border-zinc-800">
              <h2 className="text-xl font-semibold text-zinc-100">Manage Templates</h2>
              <button
                onClick={() => setManagerOpen(false)}
                className="p-2 hover:bg-zinc-800 rounded transition-colors"
              >
                <Icon name="x-close" size="sm" className="w-5 h-5 text-zinc-400" />
              </button>
            </div>

            {/* Import/Export Toolbar */}
            <div className="flex items-center gap-2 px-6 py-3 border-b border-zinc-800 bg-zinc-900/50">
              <button
                onClick={handleExport}
                className="flex items-center gap-2 px-3 py-1.5 text-xs font-medium bg-zinc-800 text-zinc-300 hover:bg-zinc-700 rounded transition-colors"
              >
                <Icon name="download" size="sm" className="w-3.5 h-3.5" />
                Export All
              </button>
              <button
                onClick={() => fileInputRef.current?.click()}
                className="flex items-center gap-2 px-3 py-1.5 text-xs font-medium bg-zinc-800 text-zinc-300 hover:bg-zinc-700 rounded transition-colors"
              >
                <Icon name="upload" size="sm" className="w-3.5 h-3.5" />
                Import
              </button>
              <input
                ref={fileInputRef}
                type="file"
                accept=".json"
                onChange={handleImport}
                className="hidden"
              />
              <div className="flex-1" />
              <div className="text-xs text-zinc-500">
                {templates.length} template{templates.length !== 1 ? 's' : ''}
              </div>
            </div>

            {/* Table */}
            <div className="flex-1 overflow-y-auto">
              {templates.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full text-zinc-500">
                  <Icon name="save" size="sm" className="w-12 h-12 mb-4 opacity-50" />
                  <p className="text-sm">No templates saved yet</p>
                  <p className="text-xs mt-2">Click "Save Current" to create your first template</p>
                </div>
              ) : (
                <table className="w-full text-sm">
                  <thead className="sticky top-0 bg-zinc-900 border-b border-zinc-800">
                    <tr className="text-left text-xs text-zinc-400 uppercase tracking-wide">
                      <th className="px-6 py-3 font-medium">Name</th>
                      <th className="px-6 py-3 font-medium">Symbol</th>
                      <th className="px-6 py-3 font-medium">Timeframe</th>
                      <th className="px-6 py-3 font-medium">Created</th>
                      <th className="px-6 py-3 font-medium text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-zinc-800">
                    {templates.map((template) => (
                      <tr key={template.id} className="hover:bg-zinc-800/50 transition-colors">
                        <td className="px-6 py-3">
                          <div className="font-medium text-zinc-200">{template.name}</div>
                          <div className="text-xs text-zinc-500">{template.chartType}</div>
                        </td>
                        <td className="px-6 py-3 text-zinc-300">{template.symbol}</td>
                        <td className="px-6 py-3 text-zinc-300">{template.timeframe}</td>
                        <td className="px-6 py-3 text-zinc-400 text-xs">
                          {new Date(template.createdAt).toLocaleDateString()}
                        </td>
                        <td className="px-6 py-3">
                          <div className="flex items-center justify-end gap-1">
                            <button
                              onClick={() => handleRename(template)}
                              className="p-1.5 hover:bg-zinc-700 rounded transition-colors"
                              title="Rename"
                            >
                              <Icon name="edit" size="sm" className="w-3.5 h-3.5 text-blue-400" />
                            </button>
                            <button
                              onClick={(e) => handleDuplicate(template.id, e)}
                              className="p-1.5 hover:bg-zinc-700 rounded transition-colors"
                              title="Duplicate"
                            >
                              <Icon name="copy" size="sm" className="w-3.5 h-3.5 text-emerald-400" />
                            </button>
                            <button
                              onClick={(e) => handleDelete(template.id, e)}
                              className="p-1.5 hover:bg-zinc-700 rounded transition-colors"
                              title="Delete"
                            >
                              <Icon name="trash" size="sm" className="w-3.5 h-3.5 text-red-400" />
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>

            {/* Footer */}
            <div className="flex items-center justify-end gap-2 p-6 border-t border-zinc-800">
              <button
                onClick={() => setManagerOpen(false)}
                className="px-4 py-2 text-sm font-medium bg-zinc-800 text-zinc-300 hover:bg-zinc-700 rounded transition-colors"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

