/**
 * Enhanced Trading Chart with Historical Data Support
 * Integrates historical data caching with live chart display
 */

import { Icon } from './ui/Icon';
import React, { useEffect, useState } from 'react';
import { TradingChart } from './TradingChart';
import { useHistoricalData } from '../hooks/useHistoricalData';
import type { ChartType, Timeframe } from './TradingChart';
import type { DateRange } from '../types/history';

interface ChartWithHistoryProps {
  symbol: string;
  chartType?: ChartType;
  timeframe?: Timeframe;
  enableHistoricalData?: boolean;
  historicalDateRange?: DateRange;
}

export const ChartWithHistory: React.FC<ChartWithHistoryProps> = ({
  symbol,
  chartType = 'candlestick',
  timeframe = 'M1',
  enableHistoricalData = true,
  historicalDateRange
}) => {
  const [showHistoricalPrompt, setShowHistoricalPrompt] = useState(false);
  const [downloadProgress, setDownloadProgress] = useState(0);

  // Calculate default date range (last 7 days)
  const [defaultDateRange] = useState<DateRange>(() => ({
    from: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    to: new Date().toISOString().split('T')[0]
  }));

  const dateRange = historicalDateRange || defaultDateRange;

  // Use historical data hook
  const {
    isLoading,
    error,
    symbolInfo,
    downloadIfMissing
  } = useHistoricalData({
    symbol,
    dateRange,
    autoLoad: enableHistoricalData,
    onProgress: setDownloadProgress
  });

  // Check if historical data is missing
  useEffect(() => {
    if (enableHistoricalData && symbolInfo) {
      const hasAllData = symbolInfo.downloadedDates.length === (symbolInfo.availableDates?.length || 0);
      if (!hasAllData && !isLoading) {
        setShowHistoricalPrompt(true);
      }
    }
  }, [symbolInfo, enableHistoricalData, isLoading]);

  const handleDownloadHistoricalData = async () => {
    setShowHistoricalPrompt(false);
    await downloadIfMissing();
  };



  return (
    <div className="relative w-full h-full">
      {/* Historical Data Prompt */}
      {showHistoricalPrompt && (
        <div className="absolute top-4 left-1/2 transform -translate-x-1/2 z-10 bg-blue-900/90 backdrop-blur-sm border border-zinc-600 rounded-lg p-4 max-w-md">
          <div className="flex items-start gap-3">
            <Icon name="download" size="sm" className="w-5 h-5 text-blue-400 mt-0.5" />
            <div className="flex-1">
              <h3 className="font-semibold mb-1">Historical Data Available</h3>
              <p className="text-sm text-gray-300 mb-3">
                Download historical tick data for {symbol} to view past price action and enable backtesting.
              </p>
              <div className="flex gap-2">
                <button
                  onClick={handleDownloadHistoricalData}
                  className="px-3 py-1.5 bg-zinc-700 hover:bg-zinc-600 rounded text-sm font-medium transition-colors"
                >
                  Download Now
                </button>
                <button
                  onClick={() => setShowHistoricalPrompt(false)}
                  className="px-3 py-1.5 bg-gray-700 hover:bg-gray-600 rounded text-sm font-medium transition-colors"
                >
                  Later
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Download Progress */}
      {isLoading && downloadProgress > 0 && downloadProgress < 100 && (
        <div className="absolute top-4 right-4 z-10 bg-gray-900/90 backdrop-blur-sm border border-gray-700 rounded-lg p-4 w-64">
          <div className="flex items-center gap-2 mb-2">
            <Icon name="refresh" size="sm" className="w-4 h-4 animate-spin text-blue-400" />
            <span className="text-sm font-medium">Downloading Historical Data</span>
          </div>
          <div className="space-y-2">
            <div className="flex items-center justify-between text-xs text-gray-400">
              <span>{symbol}</span>
              <span>{Math.round(downloadProgress)}%</span>
            </div>
            <div className="h-1.5 bg-gray-700 rounded-full overflow-hidden">
              <div
                className="h-full bg-zinc-8000 transition-all duration-300"
                style={{ width: `${downloadProgress}%` }}
              />
            </div>
          </div>
        </div>
      )}

      {/* Error Message */}
      {error && (
        <div className="absolute top-4 left-1/2 transform -translate-x-1/2 z-10 bg-red-900/90 backdrop-blur-sm border border-red-500 rounded-lg p-4 max-w-md">
          <div className="flex items-start gap-3">
            <Icon name="error" size="sm" className="w-5 h-5 text-red-400 mt-0.5" />
            <div className="flex-1">
              <h3 className="font-semibold mb-1">Failed to Load Historical Data</h3>
              <p className="text-sm text-gray-300">{error.message}</p>
            </div>
          </div>
        </div>
      )}

      {/* Data Info Banner */}
      {symbolInfo && enableHistoricalData && (
        <div className="absolute bottom-4 left-4 z-10 bg-gray-900/70 backdrop-blur-sm border border-gray-700 rounded px-3 py-1.5 text-xs">
          <div className="flex items-center gap-4">
            <span className="text-gray-400">
              Historical Data: {symbolInfo.downloadedDates.length} / {symbolInfo.availableDates?.length || 0} days
            </span>
            {symbolInfo.downloadedDates.length > 0 && symbolInfo.downloadedDates.length === (symbolInfo.availableDates?.length || 0) && (
              <span className="text-gray-400">
                {symbolInfo.firstDate} - {symbolInfo.lastDate}
              </span>
            )}
          </div>
        </div>
      )}

      {/* Chart Component */}
      <TradingChart
        symbol={symbol}
        chartType={chartType}
        timeframe={timeframe}
      />
    </div>
  );
};

/**
 * Chart With Indicators
 * Wrapper component that integrates TradingChart with IndicatorNavigator
 */

import { useState, useEffect } from 'react';
import { TradingChart } from './TradingChart';
import type { ChartType, Timeframe } from './TradingChart';
import { IndicatorNavigator } from './IndicatorNavigator';
import type { IndicatorInfo } from './IndicatorNavigator';
import { indicatorManager } from '../services/indicatorManager';

interface ChartWithIndicatorsProps {
  symbol: string;
  currentPrice?: { bid: number; ask: number };
  chartType?: ChartType;
  timeframe?: Timeframe;
  positions?: any[];
  onClosePosition?: (id: number) => void;
  onModifyPosition?: (id: number, sl: number, tp: number) => void;
}

export function ChartWithIndicators(props: ChartWithIndicatorsProps) {
  const [showIndicatorNavigator, setShowIndicatorNavigator] = useState(false);

  // Subscribe to indicator navigator command (will work when Agent 1 creates commandBus)
  useEffect(() => {
    let unsubscribe: (() => void) | null = null;

    const setupCommandBus = async () => {
      try {
        const { commandBus } = await import('../services/commandBus');

        unsubscribe = commandBus.subscribe('OPEN_INDICATOR_NAVIGATOR', () => {
          setShowIndicatorNavigator(true);
        });
      } catch (error) {
        console.log('Command bus not yet available');
      }
    };

    setupCommandBus();

    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, []);

  const handleAddIndicator = (indicator: IndicatorInfo) => {
    indicatorManager.addIndicator({
      id: indicator.id,
      name: indicator.name,
      type: indicator.id.split('-')[0], // Extract base type from ID
      parameters: indicator.parameters || {},
      visible: true,
      color: undefined // Use default color
    });

    setShowIndicatorNavigator(false);
  };

  return (
    <>
      <TradingChart {...props} />

      <IndicatorNavigator
        isOpen={showIndicatorNavigator}
        onClose={() => setShowIndicatorNavigator(false)}
        onAddIndicator={handleAddIndicator}
      />
    </>
  );
}

/**
 * Connection Status Indicator
 * Shows WebSocket connection health with MT5-style menu dropdown
 * Includes Login, Network Rescan, VPS Hosting, and Access Server options
 */

import { useState, useRef, useEffect } from 'react';
import { useWebSocketStore } from '../store/useWebSocketStore';
import { Wifi, RefreshCw, WifiOff, AlertTriangle, LogIn, Globe, Zap, Server } from 'lucide-react';
import { LoginDialog } from './LoginDialog';

interface ConnectionStatusProps {
  wsRef?: React.RefObject<WebSocket | null>;
  reconnectCallback?: () => void;
}

export function ConnectionStatus({ wsRef, reconnectCallback }: ConnectionStatusProps) {
  const storeState = useWebSocketStore();
  const [showDropdown, setShowDropdown] = useState(false);
  const [showLoginDialog, setShowLoginDialog] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const [lastUpdateAge, setLastUpdateAge] = useState(0);

  // Calculate last update age continuously
  useEffect(() => {
    const interval = setInterval(() => {
      if (storeState.lastMessageTime) {
        setLastUpdateAge(Math.floor((Date.now() - storeState.lastMessageTime) / 1000));
      } else {
        setLastUpdateAge(0);
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [storeState.lastMessageTime]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowDropdown(false);
      }
    };

    if (showDropdown) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showDropdown]);

  // Listen for global login dialog event (from Navigator, context menus, etc.)
  useEffect(() => {
    const handleOpenLogin = () => setShowLoginDialog(true);
    window.addEventListener('rtx:openLoginDialog', handleOpenLogin);
    return () => window.removeEventListener('rtx:openLoginDialog', handleOpenLogin);
  }, []);

  const state = storeState.connectionState;
  const isStale = storeState.isStale;
  const metrics = storeState.metrics;

  // Determine display based on state
  const getStatusDisplay = () => {
    switch (state) {
      case 'connected':
        return { color: 'bg-green-500', text: 'Connected', icon: Wifi, iconColor: 'text-green-600' };
      case 'connecting':
        return { color: 'bg-yellow-500', text: 'Connecting...', icon: RefreshCw, iconColor: 'text-yellow-600 animate-spin' };
      case 'disconnected':
        return { color: 'bg-red-500', text: 'Disconnected', icon: WifiOff, iconColor: 'text-red-600' };
      case 'offline':
        return { color: 'bg-gray-500', text: 'Offline', icon: WifiOff, iconColor: 'text-gray-600' };
      case 'reconnecting':
        return { color: 'bg-yellow-500', text: 'Reconnecting...', icon: RefreshCw, iconColor: 'text-yellow-600 animate-spin' };
      case 'error':
        return { color: 'bg-red-600', text: 'Error', icon: AlertTriangle, iconColor: 'text-red-700' };
      default:
        return { color: 'bg-gray-500', text: 'Unknown', icon: WifiOff, iconColor: 'text-gray-600' };
    }
  };

  const status = isStale
    ? { color: 'bg-orange-500', text: 'Stale Data', icon: AlertTriangle, iconColor: 'text-orange-600' }
    : getStatusDisplay();
  const StatusIcon = status.icon;

  const handleLogin = () => {
    setShowDropdown(false);
    setShowLoginDialog(true);
  };

  const handleNetworkRescan = () => {
    if (reconnectCallback) reconnectCallback();
    setShowDropdown(false);
  };

  const latencyMs = metrics.lastLatency > 0 ? metrics.lastLatency : null;

  return (
    <div className="relative" ref={dropdownRef}>
      {/* Status Indicator (Clickable) */}
      <button
        onClick={() => setShowDropdown(!showDropdown)}
        className="flex items-center gap-1.5 hover:bg-zinc-300/50 px-2 py-0.5 rounded transition-colors"
        title="Click for connection details"
      >
        <div className={`w-2 h-2 rounded-full ${status.color} shadow-sm`} />
        <span className="font-medium text-black text-[11px]">
          {state === 'connected' && metrics.lastLatency > 0 ? `${metrics.lastLatency}ms` : status.text}
        </span>
        {isStale && (
          <span className="text-orange-600 text-[10px] font-medium ml-1">(Stale)</span>
        )}
        {(state === 'connecting' || state === 'reconnecting') && metrics.reconnectAttempts > 0 && (
          <span className="text-yellow-700 text-[10px] ml-1">({metrics.reconnectAttempts})</span>
        )}
        <StatusIcon size={12} className={status.iconColor} />
      </button>

      {/* MT5-Style Dropdown Menu */}
      {showDropdown && (
        <div className="absolute bottom-full right-0 mb-1 w-64 bg-[#1e222d] border border-[#3a3e4a] rounded shadow-2xl z-[100] text-[11px] text-zinc-200 overflow-hidden">

          {/* Menu Items */}
          <div className="border-b border-[#3a3e4a]">
            {/* Login */}
            <button
              onClick={handleLogin}
              className="w-full flex items-center gap-2.5 px-3 py-[7px] hover:bg-[#2a3040] transition-colors text-left"
            >
              <LogIn size={14} className="text-blue-400" />
              <span>Login</span>
            </button>

            {/* Network Rescan */}
            <button
              onClick={handleNetworkRescan}
              className="w-full flex items-center gap-2.5 px-3 py-[7px] hover:bg-[#2962FF] hover:text-white transition-colors text-left"
            >
              <Globe size={14} className="text-cyan-400" />
              <span>Network Rescan</span>
            </button>

            {/* VPS Hosting Speed Up */}
            <div className="flex items-center justify-between px-3 py-[7px] hover:bg-[#2a3040] transition-colors cursor-default">
              <div className="flex items-center gap-2.5">
                <Zap size={14} className="text-yellow-400" />
                <span>VPS Hosting Speed Up</span>
              </div>
              {latencyMs && (
                <span className="text-zinc-400 text-[10px]">{(latencyMs * 0.01).toFixed(2)} ms</span>
              )}
            </div>
          </div>

          {/* Access Servers */}
          <div className="border-b border-[#3a3e4a]">
            <div className="flex items-center justify-between px-3 py-[7px] hover:bg-[#2a3040] transition-colors cursor-default">
              <div className="flex items-center gap-2.5">
                <Server size={14} className="text-zinc-400" />
                <span>Access Server</span>
              </div>
              <span className={`text-[10px] font-mono ${latencyMs && latencyMs < 200 ? 'text-green-400' : 'text-yellow-400'}`}>
                {latencyMs ? `${latencyMs.toFixed(2)} ms` : '---'}
              </span>
            </div>
            <div className="flex items-center justify-between px-3 py-[7px] hover:bg-[#2a3040] transition-colors cursor-default">
              <div className="flex items-center gap-2.5">
                <Server size={14} className="text-zinc-400" />
                <span>Access Server</span>
              </div>
              <span className={`text-[10px] font-mono ${latencyMs && latencyMs < 200 ? 'text-green-400' : 'text-yellow-400'}`}>
                {latencyMs ? `${(latencyMs * 1.08).toFixed(2)} ms` : '---'}
              </span>
            </div>
          </div>

          {/* Bottom: Current latency bar */}
          <div className="flex items-center gap-2 px-3 py-1.5 bg-[#161921]">
            <Server size={12} className="text-zinc-500" />
            <span className={`font-mono text-[10px] ${latencyMs && latencyMs < 200 ? 'text-green-400' : 'text-yellow-400'}`}>
              {latencyMs ? `${latencyMs.toFixed(2)} ms` : '---'}
            </span>
          </div>
        </div>
      )}

      {/* Login Dialog */}
      <LoginDialog
        isOpen={showLoginDialog}
        onClose={() => setShowLoginDialog(false)}
      />
    </div>
  );
}

/**
 * CopyTradingLeaderboard Component
 * Social/copy trading leaderboard showing top traders to follow
 */

import { Icon } from './ui/Icon';
import { useState, useEffect } from 'react';
type TradingStyle = 'Scalper' | 'Day Trader' | 'Swing Trader' | 'Position Trader';
type RiskLevel = 'Conservative' | 'Moderate' | 'Aggressive';
type TimePeriod = '1M' | '3M' | '6M' | '1Y' | 'All';

interface Trader {
  id: number;
  username: string;
  avatar: string;
  totalReturn: number;
  winRate: number;
  profitFactor: number;
  maxDrawdown: number;
  followers: number;
  riskScore: number; // 1-10
  tradingStyle: TradingStyle;
  preferredSymbols: string[];
  avgHoldingTimeHours: number;
  totalTrades: number;
  equityCurve: { date: string; equity: number }[];
  monthlyReturns: { [month: string]: number };
}

interface CopiedTrader {
  traderId: number;
  traderName: string;
  startDate: string;
  currentPnL: number;
  copyMode: 'fixed' | 'proportional';
  lotSize: number;
  isPaused: boolean;
}


export function CopyTradingLeaderboard() {
  const [allTraders, setAllTraders] = useState<Trader[]>([]);
  const [loading, setLoading] = useState(true);

  const [timePeriod, setTimePeriod] = useState<TimePeriod>('All');
  const [minReturn, setMinReturn] = useState(0);
  const [maxDrawdown, setMaxDrawdown] = useState(100);
  const [riskFilter, setRiskFilter] = useState<RiskLevel | 'All'>('All');
  const [sortBy, setSortBy] = useState<'return' | 'followers' | 'risk'>('return');
  const [selectedTrader, setSelectedTrader] = useState<Trader | null>(null);
  const [copiedTraders, setCopiedTraders] = useState<CopiedTrader[]>([]);
  const [compareTraders, setCompareTraders] = useState<number[]>([]);

  // Fetch traders from API on mount
  useEffect(() => {
    const fetchTraders = async () => {
      try {
        const { apiClient } = await import('../api/client');
        const data = await apiClient.get<Trader[]>('/api/copy-trading/leaderboard');
        if (!data) throw new Error('Failed to fetch leaderboard');
        setAllTraders(data);
      } catch (error) {
        console.error('Error fetching traders:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchTraders();
  }, []);

  // Filter traders
  const filteredTraders = (() => {
    const filtered = allTraders.filter(t => {
      if (t.totalReturn < minReturn) return false;
      if (t.maxDrawdown > maxDrawdown) return false;

      if (riskFilter !== 'All') {
        if (riskFilter === 'Conservative' && t.riskScore > 4) return false;
        if (riskFilter === 'Moderate' && (t.riskScore < 4 || t.riskScore > 7)) return false;
        if (riskFilter === 'Aggressive' && t.riskScore < 7) return false;
      }

      return true;
    });

    // Sort
    if (sortBy === 'return') {
      filtered.sort((a, b) => b.totalReturn - a.totalReturn);
    } else if (sortBy === 'followers') {
      filtered.sort((a, b) => b.followers - a.followers);
    } else if (sortBy === 'risk') {
      filtered.sort((a, b) => a.riskScore - b.riskScore);
    }

    return filtered;
  })();

  const getRiskColor = (score: number) => {
    if (score <= 3) return 'text-emerald-400';
    if (score <= 7) return 'text-yellow-400';
    return 'text-red-400';
  };

  const getRiskLabel = (score: number) => {
    if (score <= 3) return 'Conservative';
    if (score <= 7) return 'Moderate';
    return 'Aggressive';
  };

  const handleCopyTrader = (trader: Trader) => {
    const newCopy: CopiedTrader = {
      traderId: trader.id,
      traderName: trader.username,
      startDate: new Date().toISOString(),
      currentPnL: 0,
      copyMode: 'proportional',
      lotSize: 0.1,
      isPaused: false,
    };
    setCopiedTraders(prev => [...prev, newCopy]);
    setSelectedTrader(null);
  };

  const handlePauseCopy = (traderId: number) => {
    setCopiedTraders(prev =>
      prev.map(t => t.traderId === traderId ? { ...t, isPaused: !t.isPaused } : t)
    );
  };

  const handleStopCopy = (traderId: number) => {
    setCopiedTraders(prev => prev.filter(t => t.traderId !== traderId));
  };

  const toggleCompare = (traderId: number) => {
    setCompareTraders(prev => {
      if (prev.includes(traderId)) {
        return prev.filter(id => id !== traderId);
      } else if (prev.length < 3) {
        return [...prev, traderId];
      }
      return prev;
    });
  };

  return (
    <div className="h-full overflow-auto bg-zinc-900 p-4 space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Icon name="user" size="sm" className="w-5 h-5 text-blue-400" />
          <h2 className="text-lg font-semibold text-white">Copy Trading Leaderboard</h2>
          <span className="text-xs text-zinc-500">{filteredTraders.length} traders</span>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-zinc-800 rounded-lg p-4">
        <div className="flex items-center gap-2 mb-3">
          <Icon name="filter" size="sm" className="w-4 h-4 text-zinc-400" />
          <span className="text-sm font-semibold text-zinc-300">Filters</span>
        </div>
        <div className="grid grid-cols-5 gap-3">
          <div>
            <label className="text-xs text-zinc-400 mb-1 block">Time Period</label>
            <select
              value={timePeriod}
              onChange={(e) => setTimePeriod(e.target.value as TimePeriod)}
              className="w-full px-3 py-2 bg-zinc-700 border border-zinc-600 rounded text-sm text-white"
            >
              <option value="1M">1 Month</option>
              <option value="3M">3 Months</option>
              <option value="6M">6 Months</option>
              <option value="1Y">1 Year</option>
              <option value="All">All Time</option>
            </select>
          </div>
          <div>
            <label className="text-xs text-zinc-400 mb-1 block">Min Return (%)</label>
            <input
              type="number"
              value={minReturn}
              onChange={(e) => setMinReturn(parseFloat(e.target.value))}
              className="w-full px-3 py-2 bg-zinc-700 border border-zinc-600 rounded text-sm text-white"
            />
          </div>
          <div>
            <label className="text-xs text-zinc-400 mb-1 block">Max Drawdown (%)</label>
            <input
              type="number"
              value={maxDrawdown}
              onChange={(e) => setMaxDrawdown(parseFloat(e.target.value))}
              className="w-full px-3 py-2 bg-zinc-700 border border-zinc-600 rounded text-sm text-white"
            />
          </div>
          <div>
            <label className="text-xs text-zinc-400 mb-1 block">Risk Level</label>
            <select
              value={riskFilter}
              onChange={(e) => setRiskFilter(e.target.value as RiskLevel | 'All')}
              className="w-full px-3 py-2 bg-zinc-700 border border-zinc-600 rounded text-sm text-white"
            >
              <option value="All">All Levels</option>
              <option value="Conservative">Conservative</option>
              <option value="Moderate">Moderate</option>
              <option value="Aggressive">Aggressive</option>
            </select>
          </div>
          <div>
            <label className="text-xs text-zinc-400 mb-1 block">Sort By</label>
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as 'return' | 'followers' | 'risk')}
              className="w-full px-3 py-2 bg-zinc-700 border border-zinc-600 rounded text-sm text-white"
            >
              <option value="return">Return</option>
              <option value="followers">Followers</option>
              <option value="risk">Risk Score</option>
            </select>
          </div>
        </div>
      </div>

      {/* My Copies Section */}
      {copiedTraders.length > 0 && (
        <div className="bg-zinc-800 rounded-lg p-4">
          <h3 className="text-sm font-semibold text-zinc-300 mb-3 flex items-center gap-2">
            <Icon name="copy" size="sm" className="w-4 h-4 text-emerald-400" />
            My Copies ({copiedTraders.length})
          </h3>
          <div className="space-y-2">
            {copiedTraders.map(copy => (
              <div
                key={copy.traderId}
                className="flex items-center justify-between p-3 bg-zinc-900 rounded"
              >
                <div className="flex items-center gap-3">
                  <div className={`w-2 h-2 rounded-full ${copy.isPaused ? 'bg-yellow-400' : 'bg-emerald-400'}`} />
                  <div>
                    <div className="text-sm font-semibold text-white">{copy.traderName}</div>
                    <div className="text-xs text-zinc-500">
                      {copy.copyMode === 'fixed' ? 'Fixed' : 'Proportional'} ΓÇó {copy.lotSize} lots
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className={`text-sm font-bold ${copy.currentPnL >= 0 ? 'text-emerald-400' : 'text-red-400'}`}>
                    {copy.currentPnL >= 0 ? '+' : ''}{copy.currentPnL.toFixed(2)}
                  </div>
                  <button
