/**
 * Correlation Matrix Panel
 * Shows correlation coefficients between currency pairs
 * Heatmap visualization with color coding: red (negative) ΓåÆ white (neutral) ΓåÆ green (positive)
 */

import { Icon } from './ui/Icon';
import { useState, useEffect, useMemo } from 'react';
// Default major currency pairs
const DEFAULT_SYMBOLS = [
    'EURUSD',
    'GBPUSD',
    'USDJPY',
    'USDCHF',
    'AUDUSD',
    'USDCAD',
    'NZDUSD',
    'EURGBP'
];

interface PriceData {
    symbol: string;
    returns: number[]; // Daily returns
}

// TODO: Replace with API call to /api/market/returns?symbol={symbol}&days={days}
async function fetchPriceReturns(_symbol: string, _days: number = 30): Promise<number[]> {
    // Placeholder: Returns empty array until backend API is implemented
    return [];
}

// Calculate Pearson correlation coefficient
function calculateCorrelation(returns1: number[], returns2: number[]): number {
    const n = Math.min(returns1.length, returns2.length);
    if (n === 0) return 0;

    const mean1 = returns1.slice(0, n).reduce((a, b) => a + b, 0) / n;
    const mean2 = returns2.slice(0, n).reduce((a, b) => a + b, 0) / n;

    let numerator = 0;
    let sumSq1 = 0;
    let sumSq2 = 0;

    for (let i = 0; i < n; i++) {
        const diff1 = returns1[i] - mean1;
        const diff2 = returns2[i] - mean2;
        numerator += diff1 * diff2;
        sumSq1 += diff1 * diff1;
        sumSq2 += diff2 * diff2;
    }

    const denominator = Math.sqrt(sumSq1 * sumSq2);
    if (denominator === 0) return 0;

    return numerator / denominator;
}

// Get color for correlation value (-1 to +1)
function getCorrelationColor(correlation: number): string {
    // -1 (red) ΓåÆ 0 (white) ΓåÆ +1 (green)
    if (correlation < 0) {
        // Red gradient
        const intensity = Math.abs(correlation);
        const r = Math.round(239 * intensity + 30 * (1 - intensity)); // 239 (red) to 30 (dark)
        const g = Math.round(68 * intensity + 30 * (1 - intensity));
        const b = Math.round(68 * intensity + 30 * (1 - intensity));
        return `rgb(${r}, ${g}, ${b})`;
    } else if (correlation > 0) {
        // Green gradient
        const intensity = correlation;
        const r = Math.round(16 * intensity + 30 * (1 - intensity));
        const g = Math.round(185 * intensity + 30 * (1 - intensity)); // 185 (green) to 30 (dark)
        const b = Math.round(129 * intensity + 30 * (1 - intensity));
        return `rgb(${r}, ${g}, ${b})`;
    } else {
        // Neutral (white-ish)
        return 'rgb(60, 60, 60)';
    }
}

// Get text color for readability
function getTextColor(correlation: number): string {
    return Math.abs(correlation) > 0.5 ? '#ffffff' : '#d4d4d8';
}

export function CorrelationMatrix() {
    const [selectedSymbols, setSelectedSymbols] = useState<string[]>(DEFAULT_SYMBOLS);
    const [hoveredCell, setHoveredCell] = useState<{ row: string; col: string } | null>(null);
    const [showSettings, setShowSettings] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [priceData, setPriceData] = useState<PriceData[]>([]);
    const [availableSymbols] = useState<string[]>([
        ...DEFAULT_SYMBOLS,
        'EURJPY',
        'GBPJPY',
        'AUDJPY',
        'NZDJPY',
        'EURCHF',
        'GBPCHF',
        'AUDCAD',
        'AUDNZD'
    ]);

    // Fetch price data for selected symbols
    useEffect(() => {
        const loadPriceData = async () => {
            setIsLoading(true);
            const data: PriceData[] = [];
            for (const symbol of selectedSymbols) {
                const returns = await fetchPriceReturns(symbol, 30);
                data.push({ symbol, returns });
            }
            setPriceData(data);
            setIsLoading(false);
        };

        loadPriceData();
    }, [selectedSymbols]);

    // Calculate correlation matrix
    const correlationMatrix = useMemo(() => {
        const matrix: { [key: string]: { [key: string]: number } } = {};

        selectedSymbols.forEach(symbol1 => {
            matrix[symbol1] = {};
            selectedSymbols.forEach(symbol2 => {
                if (symbol1 === symbol2) {
                    matrix[symbol1][symbol2] = 1.0; // Perfect correlation with itself
                } else {
                    const data1 = priceData.find(d => d.symbol === symbol1);
                    const data2 = priceData.find(d => d.symbol === symbol2);
                    if (data1 && data2) {
                        matrix[symbol1][symbol2] = calculateCorrelation(data1.returns, data2.returns);
                    } else {
                        matrix[symbol1][symbol2] = 0;
                    }
                }
            });
        });

        return matrix;
    }, [selectedSymbols, priceData]);

    const handleCellClick = (symbol1: string, symbol2: string) => {
        if (symbol1 === symbol2) return;

        // Dispatch custom event to highlight both symbols on chart
        const event = new CustomEvent('highlightSymbolPair', {
            detail: { symbol1, symbol2 }
        });
        window.dispatchEvent(event);

        console.log(`[CorrelationMatrix] Highlighting pair: ${symbol1} <-> ${symbol2}`);
    };

    const toggleSymbol = (symbol: string) => {
        if (selectedSymbols.includes(symbol)) {
            if (selectedSymbols.length > 2) {
                setSelectedSymbols(selectedSymbols.filter(s => s !== symbol));
            }
        } else {
            setSelectedSymbols([...selectedSymbols, symbol]);
        }
    };

    return (
        <div className="h-full flex flex-col bg-[#131316] text-zinc-300 overflow-hidden">
            {/* Header */}
            <div className="bg-[#191a1e] border-b border-zinc-700 px-4 py-2 flex items-center justify-between flex-shrink-0">
                <div className="flex items-center gap-2">
                    <Icon name="trending-up" size="sm" className="w-4 h-4 text-blue-400" />
                    <span className="text-sm font-semibold text-zinc-100">Correlation Matrix</span>
                    <span className="text-[10px] text-zinc-500 font-mono">(30-day)</span>
                </div>
                <button
                    onClick={() => setShowSettings(!showSettings)}
                    className={`p-1.5 rounded transition-colors ${showSettings ? 'bg-zinc-700/20 text-zinc-300' : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-700'
                        }`}
                    title="Symbol Settings"
                >
                    <Icon name="settings" size="sm" className="w-4 h-4" />
                </button>
            </div>

            {/* Settings Panel */}
            {showSettings && (
                <div className="bg-[#191a1e] border-b border-zinc-700 p-3 flex-shrink-0">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-xs font-semibold text-zinc-400">Select Symbols</span>
                        <button
                            onClick={() => setShowSettings(false)}
                            className="text-zinc-500 hover:text-zinc-300"
                        >
                            <Icon name="x-close" size="sm" className="w-3 h-3" />
                        </button>
                    </div>
                    <div className="flex flex-wrap gap-1.5">
                        {availableSymbols.map(symbol => {
                            const isSelected = selectedSymbols.includes(symbol);
                            return (
                                <button
                                    key={symbol}
                                    onClick={() => toggleSymbol(symbol)}
                                    className={`px-2 py-1 rounded text-[10px] font-mono font-medium transition-colors ${isSelected
                                        ? 'bg-zinc-8000 text-white'
                                        : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
                                        }`}
                                    disabled={isSelected && selectedSymbols.length <= 2}
                                >
                                    {symbol}
                                </button>
                            );
                        })}
                    </div>
                    <p className="text-[9px] text-zinc-600 mt-2">
                        {selectedSymbols.length} symbols selected (minimum 2)
                    </p>
                </div>
            )}

            {/* Matrix Display */}
            <div className="flex-1 overflow-auto scrollbar-thin scrollbar-thumb-zinc-700 p-4">
                {isLoading ? (
                    <div className="flex items-center justify-center h-full text-zinc-500">
                        <div className="flex items-center gap-2">
                            <div className="w-4 h-4 border-2 border-zinc-600 border-t-transparent rounded-full animate-spin" />
                            Loading correlation data...
                        </div>
                    </div>
                ) : priceData.length === 0 ? (
                    <div className="flex items-center justify-center h-full text-zinc-500">
                        <div className="text-center">
                            <Icon name="trending-up" size="sm" className="w-12 h-12 mx-auto mb-3 opacity-30" />
                            <p>No correlation data available</p>
                            <p className="text-xs mt-1">Select symbols to view correlations</p>
                        </div>
                    </div>
                ) : (
                <div className="inline-block min-w-full">
                    <table className="border-collapse">
                        <thead>
                            <tr>
                                <th className="sticky left-0 top-0 z-20 bg-[#191a1e] border-r border-b border-zinc-700 p-2"></th>
                                {selectedSymbols.map(symbol => (
                                    <th
                                        key={symbol}
                                        className="sticky top-0 z-10 bg-[#191a1e] border-b border-zinc-700 p-2 text-[10px] font-mono font-bold text-zinc-300 min-w-[60px]"
                                    >
                                        <div className="transform -rotate-45 origin-center whitespace-nowrap">
                                            {symbol}
                                        </div>
                                    </th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {selectedSymbols.map((rowSymbol, rowIdx) => (
                                <tr key={rowSymbol}>
                                    <td className="sticky left-0 z-10 bg-[#191a1e] border-r border-zinc-700 p-2 text-[10px] font-mono font-bold text-zinc-300 whitespace-nowrap">
                                        {rowSymbol}
                                    </td>
                                    {selectedSymbols.map((colSymbol, colIdx) => {
                                        const correlation = correlationMatrix[rowSymbol]?.[colSymbol] ?? 0;
                                        const bgColor = getCorrelationColor(correlation);
                                        const textColor = getTextColor(correlation);
                                        const isHovered =
                                            hoveredCell?.row === rowSymbol && hoveredCell?.col === colSymbol;
                                        const isDiagonal = rowSymbol === colSymbol;

                                        return (
                                            <td
                                                key={colSymbol}
                                                className={`border border-zinc-800 p-2 text-center text-[11px] font-mono font-bold transition-all duration-150 ${isDiagonal ? 'opacity-30' : 'cursor-pointer hover:ring-2 hover:ring-blue-400 hover:z-30'
                                                    } ${isHovered ? 'ring-2 ring-white z-30' : ''}`}
                                                style={{
                                                    backgroundColor: bgColor,
                                                    color: textColor
                                                }}
                                                onMouseEnter={() =>
                                                    setHoveredCell({ row: rowSymbol, col: colSymbol })
                                                }
                                                onMouseLeave={() => setHoveredCell(null)}
                                                onClick={() => handleCellClick(rowSymbol, colSymbol)}
                                                title={`${rowSymbol} vs ${colSymbol}: ${correlation.toFixed(3)}`}
                                            >
                                                {correlation.toFixed(2)}
                                            </td>
                                        );
                                    })}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
                )}

                {/* Legend */}
                <div className="mt-6 bg-zinc-900 border border-zinc-800 rounded p-3 max-w-md">
                    <h4 className="text-xs font-semibold text-zinc-400 mb-2">Correlation Scale</h4>
                    <div className="flex items-center gap-2 mb-2">
                        <div
                            className="w-8 h-4 rounded"
                            style={{ backgroundColor: getCorrelationColor(-1) }}
                        />
                        <span className="text-[10px] text-zinc-500 flex-1">-1.0 (Perfect Negative)</span>
                    </div>
                    <div className="flex items-center gap-2 mb-2">
                        <div
                            className="w-8 h-4 rounded"
                            style={{ backgroundColor: getCorrelationColor(0) }}
                        />
                        <span className="text-[10px] text-zinc-500 flex-1">0.0 (No Correlation)</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <div
                            className="w-8 h-4 rounded"
                            style={{ backgroundColor: getCorrelationColor(1) }}
                        />
                        <span className="text-[10px] text-zinc-500 flex-1">+1.0 (Perfect Positive)</span>
                    </div>
                    <p className="text-[9px] text-zinc-600 mt-3">
                        Click a cell to highlight the symbol pair on the chart. Hover for exact values.
                    </p>
                </div>
            </div>
        </div>
    );
}

/**
 * Currency Converter / Cross-Rate Calculator
 * Multi-currency converter with live rates and cross-rate matrix
 */

import { Icon } from './ui/Icon';
import React, { useState, useEffect, useMemo } from 'react';
import { useCurrencyStore } from '../store/useCurrencyStore';
import { ArrowLeftRight, Calculator } from 'lucide-react';

const CURRENCIES = [
  'USD', 'EUR', 'GBP', 'JPY', 'CHF', 'AUD', 'CAD', 'NZD',
  'SEK', 'NOK', 'DKK', 'PLN', 'CZK', 'HUF', 'RON', 'BGN',
  'TRY', 'ZAR', 'MXN', 'BRL', 'CNY', 'HKD', 'SGD', 'INR',
  'THB', 'MYR', 'IDR', 'PHP', 'KRW', 'TWD', 'RUB', 'ILS',
];

const MAJOR_CURRENCIES = ['USD', 'EUR', 'GBP', 'JPY', 'CHF', 'AUD', 'CAD', 'NZD'];

interface ExchangeRate {
  pair: string;
  bid: number;
  ask: number;
  change: number; // % change since last update
  history: number[]; // Last 24 hours
}

/**
 * Fetch exchange rates from API
 * TODO: Implement actual API endpoint when backend is ready
 */
async function fetchExchangeRates(): Promise<Map<string, ExchangeRate>> {
  const rates = new Map<string, ExchangeRate>();

  try {
    // Placeholder: Replace with actual API call
    // const response = await fetch(API_ENDPOINTS.market.exchangeRates);
    // if (!response.ok) throw new Error('Failed to fetch exchange rates');
    // const data = await response.json();
    // data.forEach((rate: ExchangeRate) => rates.set(rate.pair, rate));
    // return rates;

    // Return empty map until API is implemented
    return rates;
  } catch (error) {
    console.error('[CurrencyConverter] Failed to fetch exchange rates:', error);
    return rates;
  }
}

export const CurrencyConverter: React.FC = () => {
  const {
    favorites,
    addFavorite,
    removeFavorite,
    isFavorite,
    addToLastUsed,
    multiConvertCurrencies,
    toggleMultiConvertCurrency,
  } = useCurrencyStore();

  const [amount, setAmount] = useState<number>(1000);
  const [fromCurrency, setFromCurrency] = useState<string>('USD');
  const [toCurrency, setToCurrency] = useState<string>('EUR');
  const [showMultiConvert, setShowMultiConvert] = useState<boolean>(false);

  // Pip value calculator
  const [lotSize, setLotSize] = useState<number>(1);
  const [pipPair, setPipPair] = useState<string>('EURUSD');
  const [accountCurrency, setAccountCurrency] = useState<string>('USD');

  // Exchange rates state
  const [exchangeRates, setExchangeRates] = useState<Map<string, ExchangeRate>>(new Map());
  const [isLoading, setIsLoading] = useState(false);

  // Fetch exchange rates on mount
  useEffect(() => {
    const loadRates = async () => {
      setIsLoading(true);
      const rates = await fetchExchangeRates();
      setExchangeRates(rates);
      setIsLoading(false);
    };

    loadRates();
  }, []);

  // Get current conversion rate
  const currentRate = useMemo(() => {
    return exchangeRates.get(`${fromCurrency}${toCurrency}`);
  }, [fromCurrency, toCurrency, exchangeRates]);

  // Calculate converted amount
  const convertedAmount = useMemo(() => {
    if (!currentRate) return 0;
    return amount * currentRate.bid;
  }, [amount, currentRate]);

  // Handle reverse currencies
  const handleReverse = () => {
    setFromCurrency(toCurrency);
    setToCurrency(fromCurrency);
  };

  // Toggle favorite
  const handleToggleFavorite = () => {
    const pair = { from: fromCurrency, to: toCurrency };
    if (isFavorite(pair)) {
      removeFavorite(pair);
    } else {
      addFavorite(pair);
      addToLastUsed(pair);
    }
  };

  // Multi-convert results
  const multiConvertResults = useMemo(() => {
    return multiConvertCurrencies.map((currency) => {
      const rate = exchangeRates.get(`${fromCurrency}${currency}`);
      return {
        currency,
        rate: rate?.bid || 0,
        amount: amount * (rate?.bid || 0),
      };
    });
  }, [fromCurrency, multiConvertCurrencies, amount, exchangeRates]);

  // Calculate pip value
  const pipValue = useMemo(() => {
    const pair = pipPair.replace('/', '');
    const baseCurrency = pair.substring(0, 3);
    const quoteCurrency = pair.substring(3, 6);

    // Pip size
    const pipSize = quoteCurrency === 'JPY' ? 0.01 : 0.0001;

    // Standard lot size (100,000 units)
    const standardLot = 100000;
    const units = lotSize * standardLot;

    // Pip value in quote currency
    let pipValueInQuote = units * pipSize;

    // Convert to account currency if needed
    if (quoteCurrency !== accountCurrency) {
      const conversionRate = exchangeRates.get(`${quoteCurrency}${accountCurrency}`);
      if (conversionRate) {
        pipValueInQuote *= conversionRate.bid;
      }
    }

    return pipValueInQuote;
  }, [lotSize, pipPair, accountCurrency, exchangeRates]);

  return (
    <div className="flex flex-col h-full bg-zinc-900 text-zinc-100">
      {/* Header */}
      <div className="flex items-center gap-2 px-4 py-2 bg-zinc-800 border-b border-zinc-700">
        <Icon name="credit-card" size="sm" className="w-4 h-4 text-emerald-400" />
        <span className="font-semibold text-sm">Currency Converter</span>
      </div>

      <div className="flex-1 overflow-auto p-4">
        {isLoading ? (
          <div className="flex items-center justify-center h-full text-zinc-500">
            <div className="flex items-center gap-2">
              <div className="w-5 h-5 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin" />
              Loading exchange rates...
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-3 gap-4">
            {/* Left Column - Converter */}
            <div className="col-span-2 space-y-4">
              {/* Main Converter */}
              <div className="bg-zinc-800 border border-zinc-700 rounded p-4">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-semibold text-zinc-300">Convert Currency</h3>
                  <button
                    onClick={handleToggleFavorite}
                    className={`p-1 rounded transition-colors ${isFavorite({ from: fromCurrency, to: toCurrency })
                        ? 'text-yellow-400'
                        : 'text-zinc-500 hover:text-yellow-400'
                      }`}
                  >
                    <Icon name="check-circle" size="sm" className="w-4 h-4" />
                  </button>
                </div>

                {/* Amount Input */}
                <div className="mb-4">
                  <label className="text-xs text-zinc-400 block mb-1">Amount</label>
                  <input
                    type="number"
                    value={amount}
                    onChange={(e) => setAmount(Number(e.target.value))}
                    className="w-full bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-lg text-zinc-100"
                    min="0"
                    step="10"
                  />
                </div>

                {/* From/To Selectors */}
                <div className="grid grid-cols-[1fr,auto,1fr] gap-2 mb-4">
                  <div>
                    <label className="text-xs text-zinc-400 block mb-1">From</label>
                    <select
                      value={fromCurrency}
                      onChange={(e) => {
                        setFromCurrency(e.target.value);
                        addToLastUsed({ from: e.target.value, to: toCurrency });
                      }}
                      className="w-full bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-100"
                    >
                      {CURRENCIES.map((curr) => (
                        <option key={curr} value={curr}>{curr}</option>
                      ))}
                    </select>
                  </div>

                  <button
                    onClick={handleReverse}
                    className="self-end p-2 hover:bg-zinc-700 rounded transition-colors"
                    title="Reverse currencies"
                  >
                    <ArrowLeftRight className="w-4 h-4 text-zinc-400" />
                  </button>

                  <div>
                    <label className="text-xs text-zinc-400 block mb-1">To</label>
                    <select
                      value={toCurrency}
                      onChange={(e) => {
                        setToCurrency(e.target.value);
                        addToLastUsed({ from: fromCurrency, to: e.target.value });
                      }}
                      className="w-full bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-100"
                    >
                      {CURRENCIES.map((curr) => (
                        <option key={curr} value={curr}>{curr}</option>
                      ))}
                    </select>
                  </div>
                </div>

                {/* Conversion Result */}
                {currentRate && (
                  <div className="bg-zinc-900 border border-zinc-700 rounded p-4">
                    <div className="text-xs text-zinc-400 mb-1">Converted Amount</div>
                    <div className="text-2xl font-bold text-emerald-400 mb-2">
                      {convertedAmount.toFixed(2)} {toCurrency}
                    </div>
                    <div className="flex items-center gap-4 text-xs text-zinc-500">
                      <div>Bid: {currentRate.bid.toFixed(6)}</div>
                      <div>Ask: {currentRate.ask.toFixed(6)}</div>
                      <div className={currentRate.change >= 0 ? 'text-emerald-400' : 'text-red-400'}>
                        {currentRate.change >= 0 ? '+' : ''}{currentRate.change.toFixed(2)}%
                      </div>
                    </div>
                  </div>
                )}
              </div>

              {/* Multi-Convert */}
              <div className="bg-zinc-800 border border-zinc-700 rounded p-4">
                <button
                  onClick={() => setShowMultiConvert(!showMultiConvert)}
                  className="w-full flex items-center justify-between mb-3"
                >
                  <h3 className="text-sm font-semibold text-zinc-300">Multi-Currency Conversion</h3>
                  {showMultiConvert ? <Icon name="chevron-up" size="sm" className="w-4 h-4" /> : <Icon name="chevron-down" size="sm" className="w-4 h-4" />}
                </button>

                {showMultiConvert && (
                  <div className="space-y-2">
                    {/* Currency selector */}
                    <div className="flex flex-wrap gap-2 mb-3">
                      {CURRENCIES.filter(c => c !== fromCurrency).map((currency) => (
                        <button
                          key={currency}
                          onClick={() => toggleMultiConvertCurrency(currency)}
                          className={`px-2 py-1 rounded text-xs transition-colors ${multiConvertCurrencies.includes(currency)
                              ? 'bg-emerald-600 text-white'
                              : 'bg-zinc-700 text-zinc-300 hover:bg-zinc-600'
                            }`}
                        >
                          {currency}
                        </button>
                      ))}
                    </div>

                    {/* Results */}
                    <div className="space-y-2">
                      {multiConvertResults.map((result) => (
                        <div key={result.currency} className="flex items-center justify-between bg-zinc-900 p-2 rounded">
                          <span className="text-sm font-medium text-zinc-300">{result.currency}</span>
                          <div className="text-right">
                            <div className="text-sm font-bold text-zinc-100">{result.amount.toFixed(2)}</div>
                            <div className="text-xs text-zinc-500">@ {result.rate.toFixed(6)}</div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Cross-Rate Matrix */}
              <div className="bg-zinc-800 border border-zinc-700 rounded p-4">
                <h3 className="text-sm font-semibold text-zinc-300 mb-3 flex items-center gap-2">
                  <Icon name="trending-up" size="sm" className="w-4 h-4" />
                  Cross-Rate Matrix
                </h3>
                <CrossRateMatrix rates={exchangeRates} />
              </div>

              {/* Favorites */}
              {favorites.length > 0 && (
                <div className="bg-zinc-800 border border-zinc-700 rounded p-4">
                  <h3 className="text-sm font-semibold text-zinc-300 mb-3 flex items-center gap-2">
                    <Icon name="check-circle" size="sm" className="w-4 h-4 text-yellow-400" />
                    Favorite Pairs
                  </h3>
                  <div className="grid grid-cols-3 gap-2">
                    {favorites.map((fav, i) => {
                      const rate = exchangeRates.get(`${fav.from}${fav.to}`);
                      return (
                        <button
                          key={i}
                          onClick={() => {
                            setFromCurrency(fav.from);
                            setToCurrency(fav.to);
                          }}
                          className="bg-zinc-900 border border-zinc-700 rounded p-2 hover:border-emerald-600 transition-colors text-left"
                        >
                          <div className="text-xs font-medium text-zinc-300">{fav.from}/{fav.to}</div>
                          {rate && (
                            <div className="text-xs text-zinc-500">{rate.bid.toFixed(6)}</div>
                          )}
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>

            {/* Right Column - Pip Calculator */}
            <div className="space-y-4">
              <div className="bg-zinc-800 border border-zinc-700 rounded p-4">
                <h3 className="text-sm font-semibold text-zinc-300 mb-3 flex items-center gap-2">
                  <Calculator className="w-4 h-4" />
                  Pip Value Calculator
                </h3>

                <div className="space-y-3">
                  <div>
                    <label className="text-xs text-zinc-400 block mb-1">Pair</label>
                    <select
                      value={pipPair}
                      onChange={(e) => setPipPair(e.target.value)}
                      className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-sm text-zinc-100"
                    >
                      {['EURUSD', 'GBPUSD', 'USDJPY', 'AUDUSD', 'USDCAD', 'USDCHF', 'NZDUSD', 'EURJPY', 'GBPJPY', 'EURGBP'].map((pair) => (
                        <option key={pair} value={pair}>{pair}</option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="text-xs text-zinc-400 block mb-1">Lot Size</label>
                    <input
                      type="number"
                      value={lotSize}
                      onChange={(e) => setLotSize(Number(e.target.value))}
                      className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-sm text-zinc-100"
                      min="0.01"
                      step="0.01"
                    />
                  </div>

                  <div>
                    <label className="text-xs text-zinc-400 block mb-1">Account Currency</label>
                    <select
                      value={accountCurrency}
                      onChange={(e) => setAccountCurrency(e.target.value)}
                      className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-sm text-zinc-100"
                    >
                      {MAJOR_CURRENCIES.map((curr) => (
                        <option key={curr} value={curr}>{curr}</option>
                      ))}
                    </select>
                  </div>

                  <div className="bg-zinc-900 border border-zinc-700 rounded p-3 mt-3">
                    <div className="text-xs text-zinc-400 mb-1">Pip Value</div>
                    <div className="text-xl font-bold text-emerald-400">
                      {pipValue.toFixed(2)} {accountCurrency}
                    </div>
                    <div className="text-xs text-zinc-500 mt-1">per pip movement</div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

// Cross-Rate Matrix Component
interface CrossRateMatrixProps {
  rates: Map<string, ExchangeRate>;
}

const CrossRateMatrix: React.FC<CrossRateMatrixProps> = ({ rates }) => {
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-xs">
        <thead>
          <tr>
            <th className="p-2 text-left text-zinc-400 border border-zinc-700"></th>
            {MAJOR_CURRENCIES.map((currency) => (
              <th key={currency} className="p-2 text-center text-zinc-400 border border-zinc-700 font-medium">
                {currency}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {MAJOR_CURRENCIES.map((fromCurr) => (
            <tr key={fromCurr}>
              <td className="p-2 text-zinc-400 border border-zinc-700 font-medium">{fromCurr}</td>
              {MAJOR_CURRENCIES.map((toCurr) => {
                if (fromCurr === toCurr) {
                  return (
                    <td key={toCurr} className="p-2 text-center border border-zinc-700 bg-zinc-900">
                      <span className="text-zinc-600">ΓÇö</span>
                    </td>
                  );
                }

                const rate = rates.get(`${fromCurr}${toCurr}`);
                if (!rate) return <td key={toCurr} className="p-2 border border-zinc-700"></td>;

                const changeColor = rate.change >= 0 ? 'text-emerald-400' : 'text-red-400';
                const bgColor = rate.change >= 0 ? 'bg-emerald-900/10' : 'bg-red-900/10';

                return (
                  <td key={toCurr} className={`p-2 text-center border border-zinc-700 ${bgColor}`}>
                    <div className={`font-medium ${changeColor}`}>
                      {rate.bid.toFixed(fromCurr === 'JPY' || toCurr === 'JPY' ? 3 : 5)}
                    </div>
                    <div className="flex items-center justify-center gap-1 mt-1">
                      <Sparkline data={rate.history} width={40} height={12} />
                    </div>
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

// Sparkline Chart Component
interface SparklineProps {
  data: number[];
  width: number;
  height: number;
}

const Sparkline: React.FC<SparklineProps> = ({ data, width, height }) => {
  if (data.length < 2) return null;

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min;

  const points = data.map((value, index) => {
    const x = (index / (data.length - 1)) * width;
    const y = height - ((value - min) / range) * height;
    return `${x},${y}`;
  }).join(' ');

  const isUp = data[data.length - 1] > data[0];
  const color = isUp ? '#10b981' : '#ef4444';

  return (
    <svg width={width} height={height} className="inline-block">
      <polyline
        points={points}
        fill="none"
        stroke={color}
        strokeWidth="1"
      />
    </svg>
  );
};

