const EquityCurveChart: React.FC<EquityCurveChartProps> = ({
  data,
  drawdowns,
  startBalance,
  hoveredIndex,
  onHover,
}) => {
  const width = 800;
  const height = 300;
  const padding = { top: 20, right: 60, bottom: 40, left: 60 };

  const minBalance = Math.min(...data.map(d => Math.min(d.balance, d.equity, d.freeMargin)));
  const maxBalance = Math.max(...data.map(d => Math.max(d.balance, d.equity, d.freeMargin)));
  const balanceRange = maxBalance - minBalance;

  const xScale = (index: number) => padding.left + (index / (data.length - 1)) * (width - padding.left - padding.right);
  const yScale = (value: number) => height - padding.bottom - ((value - minBalance) / balanceRange) * (height - padding.top - padding.bottom);

  // Benchmark line (5% annual = ~0.0137% daily)
  const benchmarkData = data.map((_, i) => {
    return startBalance * Math.pow(1.05, i / 365);
  });

  // Find peak for drawdown shading
  let peak = data[0].balance;
  const peakPoints: { x: number; y: number }[] = [];
  const currentPoints: { x: number; y: number }[] = [];

  data.forEach((snapshot, i) => {
    if (snapshot.balance > peak) {
      peak = snapshot.balance;
    }
    peakPoints.push({ x: xScale(i), y: yScale(peak) });
    currentPoints.push({ x: xScale(i), y: yScale(snapshot.balance) });
  });

  return (
    <div className="relative">
      <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-64 bg-zinc-900 rounded">
        {/* Grid lines */}
        {[0, 0.25, 0.5, 0.75, 1].map((ratio) => {
          const y = height - padding.bottom - ratio * (height - padding.top - padding.bottom);
          const value = minBalance + ratio * balanceRange;
          return (
            <g key={ratio}>
              <line
                x1={padding.left}
                y1={y}
                x2={width - padding.right}
                y2={y}
                stroke="#3f3f46"
                strokeWidth="1"
                strokeDasharray="2,2"
              />
              <text x={padding.left - 10} y={y + 4} fill="#71717a" fontSize="10" textAnchor="end">
                ${value.toFixed(0)}
              </text>
            </g>
          );
        })}

        {/* Drawdown shading (red when below peak) */}
        {drawdowns.some(dd => dd < 0) && (
          <polygon
            points={[
              ...peakPoints.map((p, i) => `${p.x},${p.y}`),
              ...currentPoints.reverse().map((p) => `${p.x},${p.y}`),
            ].join(' ')}
            fill="#ef4444"
            opacity="0.1"
          />
        )}

        {/* Benchmark line */}
        <polyline
          points={benchmarkData.map((value, i) => `${xScale(i)},${yScale(value)}`).join(' ')}
          fill="none"
          stroke="#eab308"
          strokeWidth="1.5"
          strokeDasharray="5,5"
          opacity="0.5"
        />

        {/* Free Margin line (gray dashed) */}
        <polyline
          points={data.map((d, i) => `${xScale(i)},${yScale(d.freeMargin)}`).join(' ')}
          fill="none"
          stroke="#71717a"
          strokeWidth="1.5"
          strokeDasharray="3,3"
        />

        {/* Equity line (green) */}
        <polyline
          points={data.map((d, i) => `${xScale(i)},${yScale(d.equity)}`).join(' ')}
          fill="none"
          stroke="#10b981"
          strokeWidth="2"
        />

        {/* Balance line (blue) */}
        <polyline
          points={data.map((d, i) => `${xScale(i)},${yScale(d.balance)}`).join(' ')}
          fill="none"
          stroke="#8a8a8f"
          strokeWidth="2.5"
        />

        {/* Deposit/Withdrawal markers */}
        {data.map((snapshot, i) => {
          if (snapshot.deposit) {
            return (
              <polygon
                key={`deposit-${i}`}
                points={`${xScale(i)},${yScale(snapshot.balance) - 10} ${xScale(i) - 5},${yScale(snapshot.balance)} ${xScale(i) + 5},${yScale(snapshot.balance)}`}
                fill="#10b981"
              />
            );
          }
          if (snapshot.withdrawal) {
            return (
              <polygon
                key={`withdrawal-${i}`}
                points={`${xScale(i)},${yScale(snapshot.balance) + 10} ${xScale(i) - 5},${yScale(snapshot.balance)} ${xScale(i) + 5},${yScale(snapshot.balance)}`}
                fill="#ef4444"
              />
            );
          }
          return null;
        })}

        {/* Hover area */}
        <rect
          x={padding.left}
          y={padding.top}
          width={width - padding.left - padding.right}
          height={height - padding.top - padding.bottom}
          fill="transparent"
          onMouseMove={(e) => {
            const rect = e.currentTarget.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const index = Math.round(((x - padding.left) / (width - padding.left - padding.right)) * (data.length - 1));
            onHover(Math.max(0, Math.min(data.length - 1, index)));
          }}
          onMouseLeave={() => onHover(null)}
        />

        {/* Hover tooltip */}
        {hoveredIndex !== null && (
          <>
            <line
              x1={xScale(hoveredIndex)}
              y1={padding.top}
              x2={xScale(hoveredIndex)}
              y2={height - padding.bottom}
              stroke="#60a5fa"
              strokeWidth="1"
              strokeDasharray="2,2"
            />
            <circle cx={xScale(hoveredIndex)} cy={yScale(data[hoveredIndex].balance)} r="4" fill="#8a8a8f" />
          </>
        )}

        {/* X-axis labels */}
        {[0, Math.floor(data.length / 2), data.length - 1].map((i) => (
          <text
            key={i}
            x={xScale(i)}
            y={height - padding.bottom + 20}
            fill="#71717a"
            fontSize="10"
            textAnchor="middle"
          >
            {data[i].date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
          </text>
        ))}

        {/* Legend */}
        <g transform={`translate(${width - padding.right - 150}, 10)`}>
          <line x1="0" y1="0" x2="20" y2="0" stroke="#8a8a8f" strokeWidth="2.5" />
          <text x="25" y="4" fill="#71717a" fontSize="10">Balance</text>

          <line x1="0" y1="15" x2="20" y2="15" stroke="#10b981" strokeWidth="2" />
          <text x="25" y="19" fill="#71717a" fontSize="10">Equity</text>

          <line x1="0" y1="30" x2="20" y2="30" stroke="#71717a" strokeWidth="1.5" strokeDasharray="3,3" />
          <text x="25" y="34" fill="#71717a" fontSize="10">Free Margin</text>
        </g>
      </svg>

      {/* Tooltip */}
      {hoveredIndex !== null && (
        <div className="absolute top-0 right-0 bg-zinc-800 border border-zinc-700 rounded p-2 text-xs">
          <div className="text-zinc-400">{data[hoveredIndex].date.toLocaleDateString()}</div>
          <div className="text-zinc-100">Balance: ${data[hoveredIndex].balance.toFixed(2)}</div>
          <div className="text-emerald-400">Equity: ${data[hoveredIndex].equity.toFixed(2)}</div>
          <div className={data[hoveredIndex].dailyPnL >= 0 ? 'text-emerald-400' : 'text-red-400'}>
            Daily P&L: {data[hoveredIndex].dailyPnL >= 0 ? '+' : ''}${data[hoveredIndex].dailyPnL.toFixed(2)}
          </div>
        </div>
      )}
    </div>
  );
};

// Drawdown Chart Component
interface DrawdownChartProps {
  data: DailySnapshot[];
  drawdowns: number[];
}

const DrawdownChart: React.FC<DrawdownChartProps> = ({ data, drawdowns }) => {
  const width = 800;
  const height = 150;
  const padding = { top: 10, right: 60, bottom: 30, left: 60 };

  const minDrawdown = Math.min(...drawdowns, 0);
  const maxDrawdown = 0;

  const xScale = (index: number) => padding.left + (index / (data.length - 1)) * (width - padding.left - padding.right);
  const yScale = (value: number) => padding.top + ((maxDrawdown - value) / (maxDrawdown - minDrawdown)) * (height - padding.top - padding.bottom);

  const maxDrawdownIndex = drawdowns.indexOf(Math.min(...drawdowns));

  return (
    <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-32 bg-zinc-900 rounded">
      {/* Zero line */}
      <line
        x1={padding.left}
        y1={yScale(0)}
        x2={width - padding.right}
        y2={yScale(0)}
        stroke="#71717a"
        strokeWidth="1"
      />

      {/* Drawdown area */}
      <polygon
        points={[
          `${padding.left},${yScale(0)}`,
          ...drawdowns.map((dd, i) => `${xScale(i)},${yScale(dd)}`),
          `${xScale(data.length - 1)},${yScale(0)}`,
        ].join(' ')}
        fill="#ef4444"
        opacity="0.3"
      />

      {/* Drawdown line */}
      <polyline
        points={drawdowns.map((dd, i) => `${xScale(i)},${yScale(dd)}`).join(' ')}
        fill="none"
        stroke="#ef4444"
        strokeWidth="2"
      />

      {/* Max drawdown marker */}
      <circle cx={xScale(maxDrawdownIndex)} cy={yScale(drawdowns[maxDrawdownIndex])} r="4" fill="#ef4444" />
      <text
        x={xScale(maxDrawdownIndex)}
        y={yScale(drawdowns[maxDrawdownIndex]) + 15}
        fill="#ef4444"
        fontSize="10"
        textAnchor="middle"
      >
        Max DD: {drawdowns[maxDrawdownIndex].toFixed(2)}%
      </text>

      {/* Y-axis labels */}
      <text x={padding.left - 10} y={yScale(0) + 4} fill="#71717a" fontSize="10" textAnchor="end">0%</text>
      <text x={padding.left - 10} y={yScale(minDrawdown) + 4} fill="#71717a" fontSize="10" textAnchor="end">
        {minDrawdown.toFixed(1)}%
      </text>
    </svg>
  );
};

// Monthly Performance Grid Component
interface MonthlyGridProps {
  performance: MonthlyPerformance[];
}

const MonthlyGrid: React.FC<MonthlyGridProps> = ({ performance }) => {
  const maxAbsPnL = Math.max(...performance.map(p => Math.abs(p.pnl)));

  const getColorIntensity = (pnl: number) => {
    const intensity = Math.abs(pnl) / maxAbsPnL;
    if (pnl > 0) {
      return `rgba(16, 185, 129, ${0.2 + intensity * 0.6})`; // emerald with varying opacity
    } else if (pnl < 0) {
      return `rgba(239, 68, 68, ${0.2 + intensity * 0.6})`; // red with varying opacity
    }
    return '#222226'; // zinc-800
  };

  return (
    <div className="grid grid-cols-6 gap-2">
      {performance.map((month) => (
        <div
          key={`${month.year}-${month.month}`}
          className="border border-zinc-700 rounded p-2 text-center"
          style={{ backgroundColor: getColorIntensity(month.pnl) }}
        >
          <div className="text-xs text-zinc-300 font-medium">{month.month} {month.year}</div>
          <div className={`text-sm font-bold ${month.pnl >= 0 ? 'text-emerald-100' : 'text-red-100'}`}>
            {month.pnl >= 0 ? '+' : ''}${month.pnl.toFixed(0)}
          </div>
          <div className="text-xs text-zinc-400">
            {month.return >= 0 ? '+' : ''}{month.return.toFixed(1)}%
          </div>
        </div>
      ))}
    </div>
  );
};

import { Icon } from './ui/Icon';
import { useState } from 'react';
import Papa from 'papaparse';
import type { Trade } from '../store/useAppStore';

interface ExportDialogProps {
  accountId: string;
  onClose: () => void;
}

type ExportFormat = 'csv' | 'pdf' | 'json';
type ExportDataType = 'trades' | 'positions' | 'performance';

import { API_BASE_URL } from '../config/api';
import { FileSpreadsheet, FileJson } from 'lucide-react';

export const ExportDialog = ({ accountId, onClose }: ExportDialogProps) => {
  const [format, setFormat] = useState<ExportFormat>('csv');
  const [dataType, setDataType] = useState<ExportDataType>('trades');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedColumns, setSelectedColumns] = useState<Set<string>>(
    new Set(['symbol', 'side', 'volume', 'profit', 'openTime', 'closeTime'])
  );
  const [csvDelimiter, setCsvDelimiter] = useState<',' | ';' | '\t'>(',');

  // Available columns for selection
  const allColumns = {
    trades: [
      { key: 'id', label: 'Trade ID' },
      { key: 'symbol', label: 'Symbol' },
      { key: 'side', label: 'Side' },
      { key: 'volume', label: 'Volume' },
      { key: 'openPrice', label: 'Open Price' },
      { key: 'closePrice', label: 'Close Price' },
      { key: 'profit', label: 'Profit' },
      { key: 'commission', label: 'Commission' },
      { key: 'swap', label: 'Swap' },
      { key: 'openTime', label: 'Open Time' },
      { key: 'closeTime', label: 'Close Time' },
    ],
    positions: [
      { key: 'id', label: 'Position ID' },
      { key: 'symbol', label: 'Symbol' },
      { key: 'side', label: 'Side' },
      { key: 'volume', label: 'Volume' },
      { key: 'openPrice', label: 'Open Price' },
      { key: 'currentPrice', label: 'Current Price' },
      { key: 'unrealizedPnL', label: 'Unrealized P&L' },
      { key: 'sl', label: 'Stop Loss' },
      { key: 'tp', label: 'Take Profit' },
    ],
  };

  const toggleColumn = (column: string) => {
    setSelectedColumns((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(column)) {
        newSet.delete(column);
      } else {
        newSet.add(column);
      }
      return newSet;
    });
  };

  const handleExport = async () => {
    if (!startDate || !endDate) {
      alert('Please select both start and end dates');
      return;
    }

    setIsLoading(true);
    try {
      if (format === 'csv') {
        await exportCSV();
      } else if (format === 'pdf') {
        await exportPDF();
      } else if (format === 'json') {
        await exportJSON();
      }
      onClose();
    } catch (error) {
      console.error('Export error:', error);
      alert(`Failed to export data: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setIsLoading(false);
    }
  };

  const exportCSV = async () => {
    // Fetch data from API
    const data = await fetchData();

    // Filter columns based on selection
    const filteredData = data.map((item: any) => {
      const filtered: any = {};
      selectedColumns.forEach((col) => {
        filtered[col] = item[col];
      });
      return filtered;
    });

    // Generate CSV using papaparse
    const csv = Papa.unparse(filteredData, {
      delimiter: csvDelimiter,
      header: true,
    });

    // Download CSV file
    downloadFile(csv, `${dataType}_${Date.now()}.csv`, 'text/csv');
  };

  const exportPDF = async () => {
    // Call backend API for PDF generation
    const queryParams = new URLSearchParams({
      start: startDate,
      end: endDate,
      accountId,
    });

    const response = await fetch(
      `${API_BASE_URL}/api/analytics/export/pdf?${queryParams}`,
      {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      }
    );

    if (!response.ok) {
      throw new Error(`PDF export failed: ${response.statusText}`);
    }

    const blob = await response.blob();
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `report_${Date.now()}.pdf`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const exportJSON = async () => {
    const data = await fetchData();

    // Filter columns
    const filteredData = data.map((item: any) => {
      const filtered: any = {};
      selectedColumns.forEach((col) => {
        filtered[col] = item[col];
      });
      return filtered;
    });

    const json = JSON.stringify(filteredData, null, 2);
    downloadFile(json, `${dataType}_${Date.now()}.json`, 'application/json');
  };

  const fetchData = async () => {
    const endpoint =
      dataType === 'trades'
        ? `/api/trades?accountId=${accountId}`
        : dataType === 'positions'
          ? `/api/positions?accountId=${accountId}`
          : `/api/performance?accountId=${accountId}`;

    const response = await fetch(`${API_BASE_URL}${endpoint}`);

    if (!response.ok) {
      throw new Error(`Failed to fetch ${dataType}`);
    }

    const data = await response.json();

    // Filter by date range if applicable
    if (dataType === 'trades' && Array.isArray(data)) {
      const start = new Date(startDate).getTime();
      const end = new Date(endDate).getTime();
      return data.filter((item: Trade) => {
        const closeTime = item.closeTime ? new Date(item.closeTime).getTime() : 0;
        return closeTime >= start && closeTime <= end;
      });
    }

    return data || [];
  };

  const downloadFile = (content: string, filename: string, mimeType: string) => {
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const currentColumns =
    dataType === 'trades' ? allColumns.trades : allColumns.positions;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-zinc-900 border border-zinc-800 rounded-lg w-full max-w-2xl max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-zinc-800">
          <div className="flex items-center gap-2">
            <Icon name="download" size="sm" className="w-5 h-5 text-emerald-400" />
            <h2 className="text-lg font-bold text-white">Export Data</h2>
          </div>
          <button
            onClick={onClose}
            className="p-1 hover:bg-zinc-800 rounded transition-colors"
          >
            <Icon name="x-close" size="sm" className="w-5 h-5" />
          </button>
        </div>

        <div className="p-4 space-y-4">
          {/* Data Type Selection */}
          <div>
            <label className="block text-sm font-medium text-zinc-400 mb-2">
              Data Type
            </label>
            <div className="grid grid-cols-3 gap-2">
              {(['trades', 'positions', 'performance'] as const).map((type) => (
                <button
                  key={type}
                  onClick={() => setDataType(type)}
                  className={`p-2 rounded border text-sm font-medium transition-colors ${dataType === type
                      ? 'bg-emerald-600 border-emerald-500 text-white'
                      : 'bg-zinc-800 border-zinc-700 text-zinc-300 hover:bg-zinc-700'
                    }`}
                >
                  {type.charAt(0).toUpperCase() + type.slice(1)}
                </button>
              ))}
            </div>
          </div>

          {/* Format Selection */}
          <div>
            <label className="block text-sm font-medium text-zinc-400 mb-2">
              Export Format
            </label>
            <div className="grid grid-cols-3 gap-2">
              <button
                onClick={() => setFormat('csv')}
                className={`flex items-center justify-center gap-2 p-3 rounded border transition-colors ${format === 'csv'
                    ? 'bg-blue-600 border-zinc-600 text-white'
                    : 'bg-zinc-800 border-zinc-700 text-zinc-300 hover:bg-zinc-700'
                  }`}
              >
                <FileSpreadsheet className="w-4 h-4" />
                <span className="text-sm font-medium">CSV</span>
              </button>
              <button
                onClick={() => setFormat('pdf')}
                className={`flex items-center justify-center gap-2 p-3 rounded border transition-colors ${format === 'pdf'
                    ? 'bg-blue-600 border-zinc-600 text-white'
                    : 'bg-zinc-800 border-zinc-700 text-zinc-300 hover:bg-zinc-700'
                  }`}
              >
                <Icon name="file-text" size="sm" className="w-4 h-4" />
                <span className="text-sm font-medium">PDF</span>
              </button>
              <button
                onClick={() => setFormat('json')}
                className={`flex items-center justify-center gap-2 p-3 rounded border transition-colors ${format === 'json'
                    ? 'bg-blue-600 border-zinc-600 text-white'
                    : 'bg-zinc-800 border-zinc-700 text-zinc-300 hover:bg-zinc-700'
                  }`}
              >
                <FileJson className="w-4 h-4" />
                <span className="text-sm font-medium">JSON</span>
              </button>
            </div>
          </div>

          {/* Date Range */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-sm font-medium text-zinc-400 mb-2">
                <Icon name="calendar" size="sm" className="inline w-3 h-3 mr-1" />
                Start Date
              </label>
              <input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="w-full bg-zinc-800 border border-zinc-700 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-emerald-500"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-zinc-400 mb-2">
                <Icon name="calendar" size="sm" className="inline w-3 h-3 mr-1" />
                End Date
              </label>
              <input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="w-full bg-zinc-800 border border-zinc-700 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-emerald-500"
              />
            </div>
          </div>

          {/* CSV Options */}
          {format === 'csv' && (
            <div>
              <label className="block text-sm font-medium text-zinc-400 mb-2">
                CSV Delimiter
              </label>
              <select
                value={csvDelimiter}
                onChange={(e) => setCsvDelimiter(e.target.value as ',' | ';' | '\t')}
                className="w-full bg-zinc-800 border border-zinc-700 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-emerald-500"
              >
                <option value=",">Comma (,)</option>
                <option value=";">Semicolon (;)</option>
                <option value="\t">Tab (\t)</option>
              </select>
            </div>
          )}

          {/* Column Selection (for CSV and JSON) */}
          {(format === 'csv' || format === 'json') && dataType !== 'performance' && (
            <div>
              <label className="block text-sm font-medium text-zinc-400 mb-2">
                Select Columns
              </label>
              <div className="grid grid-cols-2 gap-2 max-h-48 overflow-y-auto bg-zinc-800 border border-zinc-700 rounded p-3">
                {currentColumns.map((col) => (
                  <label
                    key={col.key}
                    className="flex items-center gap-2 text-sm cursor-pointer hover:bg-zinc-700 p-1 rounded"
                  >
                    <input
                      type="checkbox"
                      checked={selectedColumns.has(col.key)}
                      onChange={() => toggleColumn(col.key)}
                      className="w-4 h-4 text-emerald-600 bg-zinc-700 border-zinc-600 rounded focus:ring-emerald-500"
                    />
                    <span className="text-zinc-300">{col.label}</span>
                  </label>
                ))}
              </div>
            </div>
          )}

          {/* Actions */}
          <div className="flex gap-3 pt-2">
            <button
              onClick={onClose}
              className="flex-1 px-4 py-2 bg-zinc-800 border border-zinc-700 rounded text-white hover:bg-zinc-700 transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={handleExport}
              disabled={isLoading || !startDate || !endDate || selectedColumns.size === 0}
              className="flex-1 px-4 py-2 bg-emerald-600 border border-emerald-500 rounded text-white hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 transition-colors"
            >
              {isLoading ? (
                <>
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                  <span>Exporting...</span>
                </>
              ) : (
                <>
                  <Icon name="download" size="sm" className="w-4 h-4" />
                  <span>Export</span>
                </>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

/**
 * Exposure Heatmap Component
 * Canvas-based real-time visualization of position exposure across symbols and time
 * Optimized for 60 FPS with batched updates and requestAnimationFrame
 */

import { useEffect, useRef, useState, useCallback } from 'react';
import { getWebSocketService } from '../services/websocket';
import { WS_ENDPOINTS } from '../config/api';

// ============================================
// Types
// ============================================

type TimeInterval = '15m' | '1h' | '4h' | '1d';

interface ExposureCell {
  symbol: string;
  time: number;
  exposure: number; // -100 to 100 (negative = short, positive = long)
  volume: number;
  netPnL: number;
}

interface ExposureData {
  cells: ExposureCell[];
  symbols: string[];
  timeRange: { start: number; end: number };
}

interface TooltipData {
  x: number;
  y: number;
  cell: ExposureCell;
}

// ============================================
// Color Calculation
// ============================================

/**
 * Convert exposure value (-100 to 100) to HSL color
 * Green (low) ΓåÆ Yellow ΓåÆ Red (high)
 */
const exposureToColor = (exposure: number): string => {
  const absExposure = Math.abs(exposure);
  const normalized = Math.min(absExposure / 100, 1);

  // HSL color space: 120 (green) ΓåÆ 60 (yellow) ΓåÆ 0 (red)
  const hue = 120 - normalized * 120;
  const saturation = 70 + normalized * 30; // 70-100%
  const lightness = 50 - normalized * 20; // 50-30%

  return `hsl(${hue}, ${saturation}%, ${lightness}%)`;
};

/**
 * Get text color based on background brightness
 */
const getTextColor = (exposure: number): string => {
  const absExposure = Math.abs(exposure);
  return absExposure > 50 ? '#ffffff' : '#1a1a1a';
};

// ============================================
// Canvas Rendering
// ============================================

interface RenderConfig {
  canvas: HTMLCanvasElement;
  data: ExposureData;
  interval: TimeInterval;
  viewport: { offsetX: number; offsetY: number; zoom: number };
  hoveredCell: ExposureCell | null;
}

const CELL_WIDTH = 80;
const CELL_HEIGHT = 40;
const HEADER_HEIGHT = 30;
const SYMBOL_WIDTH = 100;

/**
 * Render heatmap to canvas using RAF for smooth 60 FPS
 */
const renderHeatmap = (config: RenderConfig): void => {
  const { canvas, data, viewport, hoveredCell } = config;
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  const { symbols, cells } = data;
  const { offsetX, offsetY, zoom } = viewport;

  // Clear canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Calculate visible range
  const cellWidth = CELL_WIDTH * zoom;
  const cellHeight = CELL_HEIGHT * zoom;

  const visibleStartX = Math.max(0, Math.floor(-offsetX / cellWidth));
  const visibleEndX = Math.min(
    Math.ceil((canvas.width - SYMBOL_WIDTH - offsetX) / cellWidth) + visibleStartX,
    cells.length
  );

  const visibleStartY = Math.max(0, Math.floor(-offsetY / cellHeight));
  const visibleEndY = Math.min(
    Math.ceil((canvas.height - HEADER_HEIGHT - offsetY) / cellHeight) + visibleStartY,
    symbols.length
  );

  // Group cells by symbol and time for efficient lookup
  const cellMap = new Map<string, ExposureCell>();
  cells.forEach(cell => {
    const key = `${cell.symbol}-${cell.time}`;
    cellMap.set(key, cell);
  });

  // Render cells (only visible ones)
  for (let row = visibleStartY; row < visibleEndY; row++) {
    const symbol = symbols[row];

    for (let col = visibleStartX; col < visibleEndX; col++) {
      const timeIndex = col;
      const cell = cellMap.get(`${symbol}-${timeIndex}`);

      if (!cell) continue;

      const x = SYMBOL_WIDTH + col * cellWidth + offsetX;
      const y = HEADER_HEIGHT + row * cellHeight + offsetY;

      // Skip if outside visible area
      if (x + cellWidth < SYMBOL_WIDTH || x > canvas.width ||
        y + cellHeight < HEADER_HEIGHT || y > canvas.height) {
        continue;
      }

      // Draw cell background
      ctx.fillStyle = exposureToColor(cell.exposure);
      ctx.fillRect(x, y, cellWidth, cellHeight);

      // Draw border
      ctx.strokeStyle = cell === hoveredCell ? '#ffffff' : 'rgba(255, 255, 255, 0.1)';
      ctx.lineWidth = cell === hoveredCell ? 2 : 1;
      ctx.strokeRect(x, y, cellWidth, cellHeight);

      // Draw exposure value (only if cell is large enough)
      if (cellWidth > 50 && cellHeight > 25) {
        ctx.fillStyle = getTextColor(cell.exposure);
        ctx.font = `${Math.min(12 * zoom, 12)}px sans-serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(
          `${cell.exposure.toFixed(0)}%`,
          x + cellWidth / 2,
          y + cellHeight / 2
        );
      }
    }
  }

  // Render symbol labels (fixed on left)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(0, HEADER_HEIGHT, SYMBOL_WIDTH, canvas.height - HEADER_HEIGHT);

  for (let row = visibleStartY; row < visibleEndY; row++) {
    const symbol = symbols[row];
    const y = HEADER_HEIGHT + row * cellHeight + offsetY;

    if (y + cellHeight < HEADER_HEIGHT || y > canvas.height) continue;

    // Background
    ctx.fillStyle = row % 2 === 0 ? '#2a2a2a' : '#1a1a1a';
    ctx.fillRect(0, y, SYMBOL_WIDTH, cellHeight);

    // Symbol text
    ctx.fillStyle = '#ffffff';
    ctx.font = `${Math.min(11 * zoom, 11)}px sans-serif`;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(symbol, 8, y + cellHeight / 2);
  }

  // Render time labels (fixed on top)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(SYMBOL_WIDTH, 0, canvas.width - SYMBOL_WIDTH, HEADER_HEIGHT);

  for (let col = visibleStartX; col < visibleEndX; col++) {
    const x = SYMBOL_WIDTH + col * cellWidth + offsetX;

    if (x + cellWidth < SYMBOL_WIDTH || x > canvas.width) continue;

    // Background
    ctx.fillStyle = col % 2 === 0 ? '#2a2a2a' : '#1a1a1a';
    ctx.fillRect(x, 0, cellWidth, HEADER_HEIGHT);

    // Time label (only if cell is large enough)
    if (cellWidth > 40) {
      const timeLabel = new Date(col * 1000).toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit'
      });

      ctx.fillStyle = '#ffffff';
      ctx.font = `${Math.min(10 * zoom, 10)}px sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(timeLabel, x + cellWidth / 2, HEADER_HEIGHT / 2);
    }
  }

  // Render corner (top-left fixed area)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(0, 0, SYMBOL_WIDTH, HEADER_HEIGHT);
  ctx.fillStyle = '#888888';
  ctx.font = '10px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Symbol', SYMBOL_WIDTH / 2, HEADER_HEIGHT / 2);
};

// ============================================
// Component
// ============================================

export const ExposureHeatmap = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const animationFrameRef = useRef<number | undefined>(undefined);
  const updateBatchRef = useRef<ExposureCell[]>([]);
  const lastRenderTime = useRef<number>(0);

  // State
  const [timeInterval, setTimeInterval] = useState<TimeInterval>('1h');
  const [data, setData] = useState<ExposureData>({
    cells: [],
    symbols: [],
    timeRange: { start: Date.now() - 24 * 60 * 60 * 1000, end: Date.now() }
  });
  const [viewport, setViewport] = useState({ offsetX: 0, offsetY: 0, zoom: 1 });
  const [tooltip, setTooltip] = useState<TooltipData | null>(null);
  const [hoveredCell, setHoveredCell] = useState<ExposureCell | null>(null);
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  // ============================================
  // Data Fetching
  // ============================================

  const fetchExposureData = useCallback(async () => {
    try {
      // TODO: Replace with actual API endpoint
      const response = await fetch(
        `${import.meta.env.VITE_API_URL}/api/analytics/exposure/heatmap?interval=${timeInterval}`
      );

      if (!response.ok) throw new Error('Failed to fetch exposure data');

      const result = await response.json();
      setData(result);
    } catch (error) {
      console.error('[ExposureHeatmap] Failed to fetch data:', error);

      // Mock data for development
      const symbols = ['EURUSD', 'GBPUSD', 'USDJPY', 'AUDUSD', 'USDCAD'];
      const cells: ExposureCell[] = [];
      const now = Date.now();

      for (let i = 0; i < 24; i++) {
        symbols.forEach(symbol => {
          cells.push({
            symbol,
            time: now - i * 60 * 60 * 1000,
            exposure: Math.random() * 200 - 100, // -100 to 100
            volume: Math.random() * 10,
            netPnL: Math.random() * 1000 - 500
          });
        });
      }

      setData({
        cells,
        symbols,
        timeRange: { start: now - 24 * 60 * 60 * 1000, end: now }
      });
    }
  }, [timeInterval]);

  useEffect(() => {
    fetchExposureData();
    const refreshInterval = setInterval(fetchExposureData, 60000); // Refresh every minute

    return () => clearInterval(refreshInterval);
  }, [fetchExposureData]);

  // ============================================
  // WebSocket Updates
  // ============================================

  useEffect(() => {
    const ws = getWebSocketService();

    const unsubscribe = ws.subscribe('exposure-updates', (update: ExposureCell) => {
      // Batch updates for 60 FPS
      updateBatchRef.current.push(update);
    });

    return () => {
      unsubscribe();
    };
  }, []);

  // ============================================
  // Rendering Loop (60 FPS)
  // ============================================

  const render = useCallback(() => {
    const now = performance.now();
    const elapsed = now - lastRenderTime.current;

    // Target 60 FPS (16.67ms per frame)
    if (elapsed < 16) {
      animationFrameRef.current = requestAnimationFrame(render);
      return;
    }

    // Process batched updates
    if (updateBatchRef.current.length > 0) {
      setData(prevData => {
        const updatedCells = [...prevData.cells];
        const cellMap = new Map(updatedCells.map((c, i) => [`${c.symbol}-${c.time}`, i]));

        // Batch process up to 50 updates per frame (prevents frame drops)
        const batch = updateBatchRef.current.splice(0, 50);

        batch.forEach(update => {
          const key = `${update.symbol}-${update.time}`;
          const index = cellMap.get(key);

          if (index !== undefined) {
            updatedCells[index] = update;
          } else {
            updatedCells.push(update);
          }
        });

        return { ...prevData, cells: updatedCells };
      });
    }

    // Render to canvas
    if (canvasRef.current) {
      renderHeatmap({
        canvas: canvasRef.current,
        data,
        interval: timeInterval,
        viewport,
        hoveredCell
      });
    }

    lastRenderTime.current = now;
    animationFrameRef.current = requestAnimationFrame(render);
  }, [data, timeInterval, viewport, hoveredCell]);

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [render]);

  // ============================================
  // Canvas Resize
  // ============================================

  useEffect(() => {
    const handleResize = () => {
      if (canvasRef.current && containerRef.current) {
        const { width, height } = containerRef.current.getBoundingClientRect();
        canvasRef.current.width = width;
        canvasRef.current.height = height;
      }
    };

    handleResize();
    window.addEventListener('resize', handleResize);

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // ============================================
  // Mouse Interactions
  // ============================================

  const handleMouseMove = useCallback((e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    // Handle panning
    if (isPanning) {
      const deltaX = x - lastMousePos.x;
      const deltaY = y - lastMousePos.y;

      setViewport(prev => ({
        ...prev,
        offsetX: prev.offsetX + deltaX,
        offsetY: prev.offsetY + deltaY
      }));

      setLastMousePos({ x, y });
      return;
    }

    // Calculate hovered cell
    const cellWidth = CELL_WIDTH * viewport.zoom;
    const cellHeight = CELL_HEIGHT * viewport.zoom;

    const col = Math.floor((x - SYMBOL_WIDTH - viewport.offsetX) / cellWidth);
    const row = Math.floor((y - HEADER_HEIGHT - viewport.offsetY) / cellHeight);

    if (col >= 0 && row >= 0 && row < data.symbols.length) {
      const symbol = data.symbols[row];
      const cell = data.cells.find(c => c.symbol === symbol && c.time === col);

      if (cell) {
        setHoveredCell(cell);
        setTooltip({ x: e.clientX, y: e.clientY, cell });
        return;
      }
    }

    setHoveredCell(null);
    setTooltip(null);
  }, [isPanning, lastMousePos, viewport, data]);

  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLCanvasElement>) => {
    setIsPanning(true);
    setLastMousePos({ x: e.clientX - (containerRef.current?.getBoundingClientRect().left || 0), y: e.clientY - (containerRef.current?.getBoundingClientRect().top || 0) });
  }, []);

  const handleMouseUp = useCallback(() => {
    setIsPanning(false);
  }, []);

  const handleWheel = useCallback((e: React.WheelEvent<HTMLCanvasElement>) => {
    e.preventDefault();

    const zoomDelta = e.deltaY > 0 ? 0.9 : 1.1;
    setViewport(prev => ({
      ...prev,
      zoom: Math.max(0.5, Math.min(3, prev.zoom * zoomDelta))
    }));
  }, []);

  // ============================================
  // Render
  // ============================================

  return (
    <div className="flex flex-col h-full bg-zinc-950">
      {/* Controls */}
      <div className="flex items-center justify-between p-3 border-b border-zinc-800">
        <h3 className="text-sm font-semibold text-white">Exposure Heatmap</h3>

        <div className="flex items-center gap-2">
          <span className="text-xs text-zinc-500">Interval:</span>
          {(['15m', '1h', '4h', '1d'] as TimeInterval[]).map(int => (
            <button
              key={int}
              onClick={() => setTimeInterval(int)}
              className={`px-3 py-1 text-xs rounded ${timeInterval === int
                ? 'bg-blue-600 text-white'
                : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
                }`}
            >
              {int}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setViewport({ offsetX: 0, offsetY: 0, zoom: 1 })}
            className="px-3 py-1 text-xs bg-zinc-800 text-zinc-400 rounded hover:bg-zinc-700"
          >
            Reset View
          </button>
        </div>
      </div>

      {/* Canvas Container */}
      <div
        ref={containerRef}
        className="flex-1 relative overflow-hidden"
      >
        <canvas
          ref={canvasRef}
          onMouseMove={handleMouseMove}
          onMouseDown={handleMouseDown}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          onWheel={handleWheel}
          className="cursor-grab active:cursor-grabbing"
        />

        {/* Tooltip */}
        {tooltip && (
          <div
            className="absolute pointer-events-none z-50 bg-zinc-900 border border-zinc-700 rounded-lg p-3 shadow-xl"
            style={{
              left: tooltip.x + 10,
              top: tooltip.y + 10,
            }}
          >
            <div className="text-xs space-y-1">
              <div className="font-semibold text-white">{tooltip.cell.symbol}</div>
              <div className="text-zinc-400">
                {new Date(tooltip.cell.time).toLocaleString()}
              </div>
              <div className="pt-1 border-t border-zinc-800 space-y-1">
                <div className="flex justify-between gap-4">
                  <span className="text-zinc-500">Exposure:</span>
                  <span
                    className={tooltip.cell.exposure >= 0 ? 'text-green-400' : 'text-red-400'}
                  >
                    {tooltip.cell.exposure.toFixed(1)}%
                  </span>
                </div>
                <div className="flex justify-between gap-4">
                  <span className="text-zinc-500">Volume:</span>
                  <span className="text-white">{tooltip.cell.volume.toFixed(2)} lots</span>
                </div>
                <div className="flex justify-between gap-4">
                  <span className="text-zinc-500">Net P&L:</span>
                  <span
                    className={tooltip.cell.netPnL >= 0 ? 'text-green-400' : 'text-red-400'}
                  >
                    ${tooltip.cell.netPnL.toFixed(2)}
                  </span>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Legend */}
      <div className="flex items-center justify-center gap-4 p-2 border-t border-zinc-800 bg-zinc-900">
        <span className="text-xs text-zinc-500">Exposure:</span>
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded" style={{ backgroundColor: exposureToColor(-100) }} />
          <span className="text-xs text-zinc-400">Short (-100%)</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded" style={{ backgroundColor: exposureToColor(0) }} />
          <span className="text-xs text-zinc-400">Neutral (0%)</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded" style={{ backgroundColor: exposureToColor(100) }} />
          <span className="text-xs text-zinc-400">Long (+100%)</span>
        </div>
      </div>
    </div>
  );
};

import { useState, useRef, useEffect, memo } from 'react';
import { CandlestickChart, CandlestickChartRef } from './charts/CandlestickChart';
import { useFixMarketData, CandleData } from '../hooks/useFixMarketData';

interface FixApiChartProps {
    symbol: string;
    timeframe?: string;
}

function FixApiChartComponent({ symbol, timeframe = 'M1' }: FixApiChartProps) {
    const chartRef = useRef<CandlestickChartRef>(null);

    const handleCandleUpdate = (candle: CandleData) => {
        chartRef.current?.updateCandle(candle);
    };

    const {
        status,
        isConnected,
        tickCount,
        lastPrice,
        historicalData,
        availableSymbols,
    } = useFixMarketData({
        symbol,
        timeframe,
        onCandleUpdate: handleCandleUpdate
    });

    // Update chart data whenever historicalData changes
    useEffect(() => {
        if (historicalData.length > 0) {
            chartRef.current?.setData(historicalData);
        }
    }, [historicalData]);

    return (
        <div style={{ width: '100%', height: '100%', position: 'relative', display: 'flex', flexDirection: 'column' }}>
            <div style={{ flex: 1, background: '#0d0d11', position: 'relative' }}>
                <CandlestickChart
                    ref={chartRef}
                    symbol={symbol}
                    timeframe={timeframe}
                    data={historicalData}
                />
            </div>

            {/* Bottom Panel Overlay */}
            <div
                style={{
                    position: 'absolute',
                    bottom: 0,
                    left: 0,
                    right: 0,
                    height: '50px',
                    background: 'rgba(24, 24, 27, 0.9)',
                    borderTop: '1px solid #222226',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    padding: '0 12px',
                    zIndex: 10,
                    pointerEvents: 'none' // Let clicks pass through if needed
                }}
            >
                <div
                    style={{
                        background: 'rgba(16, 185, 129, 0.1)',
                        border: '1px solid rgba(16, 185, 129, 0.3)',
                        padding: '6px 12px',
                        borderRadius: '6px',
                    }}
                >
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                        <span
                            style={{
                                width: '6px',
                                height: '6px',
                                background: isConnected ? '#34d399' : '#ef4444',
                                borderRadius: '50%',
                                animation: isConnected ? 'pulse 1s infinite' : 'none',
                                boxShadow: isConnected ? '0 0 8px #10b981' : 'none',
                            }}
                        />
                        <span style={{ color: isConnected ? '#34d399' : '#ef4444', fontSize: '11px', fontWeight: 'bold' }}>
