                            style={{
                                color: '#34d399',
                                fontSize: '18px',
                                fontFamily: 'monospace',
                                fontWeight: 'bold',
                            }}
                        >
                            {lastPrice.toFixed(5)}
                        </div>
                        <div style={{ color: '#71717a', fontSize: '9px' }}>{symbol}</div>
                    </div>
                )}
            </div>

            <style>{`
                @keyframes pulse {
                    0%, 100% { opacity: 1; }
                    50% { opacity: 0.5; }
                }
            `}</style>
        </div>
    );
}

