export function IndicatorNavigator({ isOpen, onClose, onAddIndicator }: IndicatorNavigatorProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  if (!isOpen) return null;

  const filteredCategories = Object.entries(INDICATOR_CATEGORIES).map(([category, data]) => {
    const filtered = data.indicators.filter(ind =>
      ind.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      ind.description.toLowerCase().includes(searchTerm.toLowerCase())
    );
    return { category, data, indicators: filtered };
  }).filter(cat => cat.indicators.length > 0);

  const handleAddIndicator = (category: string, indicator: any) => {
    onAddIndicator({
      id: `${indicator.id}-${Date.now()}`,
      name: indicator.name,
      category,
      description: indicator.description,
      parameters: indicator.parameters
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="bg-zinc-900 rounded-lg shadow-2xl w-full max-w-3xl max-h-[80vh] flex flex-col border border-zinc-800">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-zinc-800">
          <h2 className="text-lg font-semibold text-zinc-100">Indicators</h2>
          <button
            onClick={onClose}
            className="p-1.5 hover:bg-zinc-800 rounded transition-colors text-zinc-400 hover:text-zinc-100"
          >
            <Icon name="x-close" size="lg" />
          </button>
        </div>

        {/* Search */}
        <div className="p-4 border-b border-zinc-800">
          <div className="relative">
            <Icon name="search" size="sm" className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
            <input
              type="text"
              placeholder="Search indicators..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-zinc-800 border border-zinc-700 rounded-lg text-zinc-100 placeholder-zinc-500 focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
            />
          </div>
        </div>

        {/* Category Tabs */}
        <div className="flex gap-2 px-4 py-2 border-b border-zinc-800 overflow-x-auto">
          <button
            onClick={() => setSelectedCategory(null)}
            className={`px-3 py-1.5 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${selectedCategory === null
                ? 'bg-emerald-500/20 text-emerald-400'
                : 'text-zinc-400 hover:text-zinc-100 hover:bg-zinc-800'
              }`}
          >
            All
          </button>
          {Object.keys(INDICATOR_CATEGORIES).map(category => (
            <button
              key={category}
              onClick={() => setSelectedCategory(category)}
              className={`px-3 py-1.5 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${selectedCategory === category
                  ? 'bg-emerald-500/20 text-emerald-400'
                  : 'text-zinc-400 hover:text-zinc-100 hover:bg-zinc-800'
                }`}
            >
              {category}
            </button>
          ))}
        </div>

        {/* Indicators List */}
        <div className="flex-1 overflow-y-auto p-4">
          {filteredCategories
            .filter(cat => selectedCategory === null || cat.category === selectedCategory)
            .map(({ category, data, indicators }) => (
              <div key={category} className="mb-6 last:mb-0">
                <div className="flex items-center gap-2 mb-3">
                  {(() => {
                    const Icon = data.icon;
                    return <Icon size={18} className="text-emerald-400" />;
                  })()}
                  <h3 className="text-sm font-semibold text-zinc-300 uppercase tracking-wide">
                    {category}
                  </h3>
                </div>

                <div className="grid grid-cols-1 gap-2">
                  {indicators.map(indicator => (
                    <div
                      key={indicator.id}
                      onDoubleClick={() => handleAddIndicator(category, indicator)}
                      className="p-3 bg-zinc-800/50 hover:bg-zinc-800 rounded-lg border border-zinc-700/50 hover:border-emerald-500/50 cursor-pointer transition-all group"
                    >
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <h4 className="text-sm font-medium text-zinc-100 group-hover:text-emerald-400 transition-colors">
                            {indicator.name}
                          </h4>
                          <p className="text-xs text-zinc-500 mt-1">
                            {indicator.description}
                          </p>
                          {indicator.parameters && Object.keys(indicator.parameters).length > 0 && (
                            <div className="flex gap-2 mt-2 flex-wrap">
                              {Object.entries(indicator.parameters).map(([key, value]) => (
                                <span
                                  key={key}
                                  className="text-[10px] px-2 py-0.5 bg-zinc-700/50 text-zinc-400 rounded"
                                >
                                  {key}: {String(value)}
                                </span>
                              ))}
                            </div>
                          )}
                        </div>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleAddIndicator(category, indicator);
                          }}
                          className="ml-2 px-3 py-1 bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-400 text-xs rounded transition-colors"
                        >
                          Add
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}

          {filteredCategories.length === 0 && (
            <div className="text-center py-12 text-zinc-500">
              <Icon name="activity" size="xl" className="mx-auto mb-4 opacity-50" />
              <p>No indicators found matching "{searchTerm}"</p>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-zinc-800 bg-zinc-900/50">
          <p className="text-xs text-zinc-500 text-center">
            Double-click or press "Add" to insert an indicator
          </p>
        </div>
      </div>
    </div>
  );
}

/**
 * LP Comparison Dashboard Component
 * Real-time LP performance comparison with interactive charts and ranking
 */

import { Icon } from './ui/Icon';
import { useState, useEffect, useRef, useMemo } from 'react';
import { useWebSocket } from '../hooks/useWebSocket';
import {
  createChart,
  ColorType,
  CrosshairMode,
} from 'lightweight-charts';
import type { IChartApi, ISeriesApi, Time } from 'lightweight-charts';
// ============================================
// Types
// ============================================

type MetricType = 'latency' | 'fillRate' | 'slippage';

type SortDirection = 'asc' | 'desc';

interface LPMetrics {
  lpName: string;
  latency: {
    p50: number;
    p95: number;
    p99: number;
    avg: number;
  };
  fillRate: number;
  slippage: {
    avg: number;
    max: number;
  };
  totalOrders: number;
  lastUpdate: number;
}

interface TimeSeriesDataPoint {
  time: Time;
  value: number;
}

interface LPTimeSeriesData {
  lpName: string;
  data: TimeSeriesDataPoint[];
}

interface SortConfig {
  key: string;
  direction: SortDirection;
}

// ============================================
// LP Color Mapping
// ============================================

const LP_COLORS: Record<string, string> = {
  'LP-1': '#10b981', // emerald
  'LP-2': '#8a8a8f', // blue
  'LP-3': '#f59e0b', // amber
  'LP-4': '#ef4444', // red
  'LP-5': '#8b5cf6', // violet
  'LP-6': '#ec4899', // pink
  'Default': '#71717a', // zinc
};

const getLPColor = (lpName: string): string => {
  return LP_COLORS[lpName] || LP_COLORS['Default'];
};

// ============================================
// API Configuration
// ============================================

import { API_BASE_URL, WS_ENDPOINTS } from '../config/api';

// ============================================
// Main Component
// ============================================

export const LPComparisonDashboard = () => {
  const [lpMetrics, setLpMetrics] = useState<LPMetrics[]>([]);
  const [selectedMetric, setSelectedMetric] = useState<MetricType>('latency');
  const [selectedSymbol, setSelectedSymbol] = useState<string>('ALL');
  const [availableSymbols, setAvailableSymbols] = useState<string[]>(['ALL']);
  const [sortConfig, setSortConfig] = useState<SortConfig>({
    key: 'latency.avg',
    direction: 'asc',
  });
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [timeSeriesData, setTimeSeriesData] = useState<LPTimeSeriesData[]>([]);

  const wsRef = useRef<WebSocket | null>(null);

  // ============================================
  // Fetch Initial Data
  // ============================================

  useEffect(() => {
    const fetchInitialData = async () => {
      try {
        setIsLoading(true);
        setError(null);

        // Fetch LP metrics
        const metricsRes = await fetch(
          `${API_BASE_URL}/api/analytics/lp/metrics${selectedSymbol !== 'ALL' ? `?symbol=${selectedSymbol}` : ''}`
        );

        if (!metricsRes.ok) {
          throw new Error(`Failed to fetch LP metrics: ${metricsRes.statusText}`);
        }

        const metricsData = await metricsRes.json();
        setLpMetrics(Array.isArray(metricsData) ? metricsData : []);

        // Fetch available symbols
        const symbolsRes = await fetch(`${API_BASE_URL}/api/symbols`);
        if (symbolsRes.ok) {
          const symbols = await symbolsRes.json();
          const symbolNames = Array.isArray(symbols)
            ? symbols.map((s: any) => s.symbol || s)
            : [];
          setAvailableSymbols(['ALL', ...symbolNames]);
        }

        setIsLoading(false);
      } catch (err: any) {
        console.error('Failed to fetch LP data:', err);
        setError(err.message || 'Failed to load LP comparison data');
        setIsLoading(false);
      }
    };

    fetchInitialData();
  }, [selectedSymbol]);

  // ============================================
  // WebSocket Connection for Real-Time Updates
  // ============================================

  useEffect(() => {
    const ws: WebSocket | null = null;
    const reconnectTimeout: ReturnType<typeof setTimeout> | null = null;
    const isUnmounting = false;

    // Use centralized WebSocket with auto-reconnection
    const { subscribe, sendMessage } = useWebSocket({
      url: WS_ENDPOINTS.admin,
      autoConnect: true,
    });

    // Subscribe to lp-metrics-update messages
    const unsubscribe = subscribe('*', (message: any) => {
      try {
        const data = message;

        if (data.type === 'lp-metrics-update') {
          // Update metrics
          setLpMetrics(prev => {
            const existing = prev.find(lp => lp.lpName === data.lpName);
            if (existing) {
              return prev.map(lp =>
                lp.lpName === data.lpName ? { ...lp, ...data.metrics } : lp
              );
            }
            return [...prev, { lpName: data.lpName, ...data.metrics }];
          });

          // Update time series data
          setTimeSeriesData(prev => {
            const lpData = prev.find(lp => lp.lpName === data.lpName);
            const newPoint: TimeSeriesDataPoint = {
              time: Math.floor(Date.now() / 1000) as Time,
              value: getMetricValue(data.metrics, selectedMetric),
            };

            if (lpData) {
              return prev.map(lp =>
                lp.lpName === data.lpName
                  ? { ...lp, data: [...lp.data.slice(-100), newPoint] }
                  : lp
              );
            }
            return [...prev, { lpName: data.lpName, data: [newPoint] }];
          });
        }
      } catch (err) {
        console.error('[LP Dashboard] WebSocket message error:', err);
      }
    });

    // Send subscription message on connect
    sendMessage({
      type: 'subscribe',
      channel: 'lp-performance',
      symbol: selectedSymbol,
    });

    return () => {
      unsubscribe();
    };
  }, [selectedSymbol, selectedMetric]);

  // ============================================
  // Helper Functions
  // ============================================

  const getMetricValue = (metrics: LPMetrics, type: MetricType): number => {
    switch (type) {
      case 'latency':
        return metrics.latency.avg;
      case 'fillRate':
        return metrics.fillRate;
      case 'slippage':
        return metrics.slippage.avg;
      default:
        return 0;
    }
  };

  // ============================================
  // Sorting Logic
  // ============================================

  const handleSort = (key: string) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc',
    }));
  };

  const sortedMetrics = useMemo(() => {
    const sorted = [...lpMetrics];

    sorted.sort((a, b) => {
      let aValue: number;
      let bValue: number;

      if (sortConfig.key.includes('.')) {
        const keys = sortConfig.key.split('.');
        aValue = (a as any)[keys[0]][keys[1]];
        bValue = (b as any)[keys[0]][keys[1]];
      } else {
        aValue = (a as any)[sortConfig.key];
        bValue = (b as any)[sortConfig.key];
      }

      if (sortConfig.direction === 'asc') {
        return aValue - bValue;
      }
      return bValue - aValue;
    });

    return sorted;
  }, [lpMetrics, sortConfig]);

  // ============================================
  // Ranking Logic
  // ============================================

  const rankings = useMemo(() => {
    const getScore = (lp: LPMetrics): number => {
      // Lower latency = better, higher fill rate = better, lower slippage = better
      const latencyScore = 1000 / (lp.latency.avg + 1);
      const fillRateScore = lp.fillRate * 1000;
      const slippageScore = 100 / (lp.slippage.avg + 1);
      return latencyScore + fillRateScore + slippageScore;
    };

    return [...lpMetrics]
      .map(lp => ({ ...lp, score: getScore(lp) }))
      .sort((a, b) => b.score - a.score);
  }, [lpMetrics]);

  // ============================================
  // Loading & Error States
  // ============================================

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96 bg-zinc-900 rounded-lg border border-zinc-800">
        <div className="text-center">
          <Icon name="refresh" size="sm" className="w-8 h-8 text-emerald-500 animate-spin mx-auto mb-3" />
          <p className="text-sm text-zinc-400">Loading LP comparison data...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-96 bg-red-900/20 rounded-lg border border-red-700/50">
        <div className="text-center">
          <p className="text-sm text-red-400">{error}</p>
        </div>
      </div>
    );
  }

  // ============================================
  // Render
  // ============================================

  return (
    <div className="space-y-4 p-4 bg-zinc-900 rounded-lg border border-zinc-800">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-white">LP Performance Comparison</h2>
          <p className="text-xs text-zinc-500 mt-1">
            Real-time comparison of liquidity provider performance
          </p>
        </div>

        <div className="flex items-center gap-3">
          {/* Symbol Filter */}
          <div className="flex items-center gap-2">
            <Icon name="filter" size="sm" className="w-4 h-4 text-zinc-500" />
            <select
              value={selectedSymbol}
              onChange={(e) => setSelectedSymbol(e.target.value)}
              className="bg-zinc-800 border border-zinc-700 rounded px-3 py-1.5 text-sm text-white focus:outline-none focus:border-emerald-500"
            >
              {availableSymbols.map(symbol => (
                <option key={symbol} value={symbol}>
                  {symbol}
                </option>
              ))}
            </select>
          </div>

          {/* Metric Selector */}
          <div className="flex gap-2 bg-zinc-800 rounded-lg p-1">
            <MetricButton
              active={selectedMetric === 'latency'}
              onClick={() => setSelectedMetric('latency')}
              icon={<Icon name="clock" size="sm" className="w-4 h-4" />}
              label="Latency"
            />
            <MetricButton
              active={selectedMetric === 'fillRate'}
              onClick={() => setSelectedMetric('fillRate')}
              icon={<Icon name="crosshair" size="sm" className="w-4 h-4" />}
              label="Fill Rate"
            />
            <MetricButton
              active={selectedMetric === 'slippage'}
              onClick={() => setSelectedMetric('slippage')}
              icon={<Icon name="zap" size="sm" className="w-4 h-4" />}
              label="Slippage"
            />
          </div>
        </div>
      </div>

      {/* Performance Chart */}
      <PerformanceChart
        data={timeSeriesData}
        metricType={selectedMetric}
      />

      {/* Comparison Table */}
      <ComparisonTable
        metrics={sortedMetrics}
        sortConfig={sortConfig}
        onSort={handleSort}
      />

      {/* Rankings */}
      <RankingView rankings={rankings} />
    </div>
  );
};

// ============================================
// Metric Button Component
// ============================================

const MetricButton = ({
  active,
  onClick,
  icon,
  label,
}: {
  active: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: string;
}) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${active
      ? 'bg-emerald-500 text-black'
      : 'text-zinc-400 hover:text-white hover:bg-zinc-700'
      }`}
  >
    {icon}
    <span>{label}</span>
  </button>
);

// ============================================
// Performance Chart Component
// ============================================

const PerformanceChart = ({
  data,
  metricType,
}: {
  data: LPTimeSeriesData[];
  metricType: MetricType;
}) => {
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const seriesMapRef = useRef<Map<string, ISeriesApi<'Line'>>>(new Map());

  useEffect(() => {
    if (!chartContainerRef.current) return;

    const chart = createChart(chartContainerRef.current, {
      layout: {
        background: { type: ColorType.Solid, color: '#131316' },
        textColor: '#71717a',
      },
      grid: {
        vertLines: { color: '#222226' },
        horzLines: { color: '#222226' },
      },
      crosshair: {
        mode: CrosshairMode.Normal,
      },
      rightPriceScale: {
        borderColor: '#222226',
      },
      timeScale: {
        borderColor: '#222226',
        timeVisible: true,
        secondsVisible: false,
      },
      width: chartContainerRef.current.clientWidth,
      height: 300,
    });

    chartRef.current = chart;

    const handleResize = () => {
      if (chartContainerRef.current && chartRef.current) {
        chartRef.current.applyOptions({
          width: chartContainerRef.current.clientWidth,
        });
      }
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      chart.remove();
    };
  }, []);

  useEffect(() => {
    if (!chartRef.current) return;

    // Clear existing series
    seriesMapRef.current.forEach(series => {
      chartRef.current?.removeSeries(series);
    });
    seriesMapRef.current.clear();

    // Create series for each LP
    data.forEach(lpData => {
      const series = (chartRef.current! as any).addLineSeries({
        color: getLPColor(lpData.lpName),
        lineWidth: 2,
        title: lpData.lpName,
      });

      series.setData(lpData.data);
      seriesMapRef.current.set(lpData.lpName, series);
    });

    // Fit content
    chartRef.current.timeScale().fitContent();
  }, [data]);

  const getMetricLabel = (): string => {
    switch (metricType) {
      case 'latency':
        return 'Latency (ms)';
      case 'fillRate':
        return 'Fill Rate (%)';
      case 'slippage':
        return 'Slippage (pips)';
    }
  };

  return (
    <div className="bg-zinc-800/50 rounded-lg border border-zinc-700 p-4">
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-medium text-white">Performance Over Time</h3>
        <span className="text-xs text-zinc-500">{getMetricLabel()}</span>
      </div>
      <div ref={chartContainerRef} />

      {/* Legend */}
      <div className="flex flex-wrap gap-3 mt-3">
        {data.map(lpData => (
          <div key={lpData.lpName} className="flex items-center gap-2">
            <div
              className="w-3 h-3 rounded-full"
              style={{ backgroundColor: getLPColor(lpData.lpName) }}
            />
            <span className="text-xs text-zinc-400">{lpData.lpName}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

// ============================================
// Comparison Table Component
// ============================================

const ComparisonTable = ({
  metrics,
  sortConfig,
  onSort,
}: {
  metrics: LPMetrics[];
  sortConfig: SortConfig;
  onSort: (key: string) => void;
}) => {
  const SortIcon = ({ column }: { column: string }) => {
    if (sortConfig.key !== column) {
      return <Icon name="chevron-up" size="sm" className="w-3 h-3 text-zinc-600" />;
    }
    return sortConfig.direction === 'asc' ? (
      <Icon name="chevron-up" size="sm" className="w-3 h-3 text-emerald-400" />
    ) : (
      <Icon name="chevron-down" size="sm" className="w-3 h-3 text-emerald-400" />
    );
  };

  const TableHeader = ({ column, label }: { column: string; label: string }) => (
    <th
      onClick={() => onSort(column)}
      className="px-4 py-3 text-left text-xs font-medium text-zinc-400 uppercase tracking-wider cursor-pointer hover:text-white transition-colors"
    >
      <div className="flex items-center gap-1">
        {label}
        <SortIcon column={column} />
      </div>
    </th>
  );

  return (
    <div className="bg-zinc-800/50 rounded-lg border border-zinc-700 overflow-hidden">
      <table className="w-full">
        <thead className="bg-zinc-900/50">
          <tr>
            <TableHeader column="lpName" label="LP Name" />
            <TableHeader column="latency.avg" label="Avg Latency" />
            <TableHeader column="latency.p95" label="P95 Latency" />
            <TableHeader column="latency.p99" label="P99 Latency" />
            <TableHeader column="fillRate" label="Fill Rate" />
            <TableHeader column="slippage.avg" label="Avg Slippage" />
            <TableHeader column="slippage.max" label="Max Slippage" />
            <TableHeader column="totalOrders" label="Orders" />
          </tr>
        </thead>
        <tbody className="divide-y divide-zinc-700">
          {metrics.map((lp, index) => (
            <tr
              key={lp.lpName}
              className={`hover:bg-zinc-800/50 transition-colors ${index === 0 ? 'bg-emerald-900/10' : ''
                }`}
            >
              <td className="px-4 py-3">
                <div className="flex items-center gap-2">
                  <div
                    className="w-2 h-2 rounded-full"
                    style={{ backgroundColor: getLPColor(lp.lpName) }}
                  />
                  <span className="text-sm font-medium text-white">{lp.lpName}</span>
                </div>
              </td>
              <td className="px-4 py-3 text-sm text-zinc-300">
                {lp.latency.avg.toFixed(2)}ms
              </td>
              <td className="px-4 py-3 text-sm text-zinc-300">
                {lp.latency.p95.toFixed(2)}ms
              </td>
              <td className="px-4 py-3 text-sm text-zinc-300">
                {lp.latency.p99.toFixed(2)}ms
              </td>
              <td className="px-4 py-3">
                <div className="flex items-center gap-2">
                  <span className="text-sm text-zinc-300">
                    {(lp.fillRate * 100).toFixed(2)}%
                  </span>
                  {lp.fillRate >= 0.95 && (
                    <Icon name="trending-up" size="sm" className="w-4 h-4 text-emerald-400" />
                  )}
                  {lp.fillRate < 0.8 && (
                    <Icon name="trending-down" size="sm" className="w-4 h-4 text-red-400" />
                  )}
                </div>
              </td>
              <td className="px-4 py-3 text-sm text-zinc-300">
                {lp.slippage.avg.toFixed(2)} pips
              </td>
              <td className="px-4 py-3 text-sm text-zinc-300">
                {lp.slippage.max.toFixed(2)} pips
              </td>
              <td className="px-4 py-3 text-sm text-zinc-300">
                {lp.totalOrders.toLocaleString()}
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {metrics.length === 0 && (
        <div className="p-8 text-center text-sm text-zinc-500">
          No LP data available
        </div>
      )}
    </div>
  );
};

// ============================================
// Ranking View Component
// ============================================

const RankingView = ({ rankings }: { rankings: Array<LPMetrics & { score: number }> }) => {
  return (
    <div className="bg-zinc-800/50 rounded-lg border border-zinc-700 p-4">
      <h3 className="text-sm font-medium text-white mb-3">Overall Rankings</h3>
      <div className="space-y-2">
        {rankings.slice(0, 5).map((lp, index) => (
          <div
            key={lp.lpName}
            className="flex items-center gap-3 p-3 bg-zinc-900/50 rounded-lg"
          >
            <div
              className={`flex items-center justify-center w-8 h-8 rounded-full font-bold ${index === 0
                ? 'bg-yellow-500/20 text-yellow-400'
                : index === 1
                  ? 'bg-zinc-400/20 text-zinc-400'
                  : index === 2
                    ? 'bg-orange-700/20 text-orange-400'
                    : 'bg-zinc-700/20 text-zinc-500'
                }`}
            >
              {index + 1}
            </div>
            <div
              className="w-3 h-3 rounded-full"
              style={{ backgroundColor: getLPColor(lp.lpName) }}
            />
            <div className="flex-1">
              <div className="text-sm font-medium text-white">{lp.lpName}</div>
              <div className="text-xs text-zinc-500">
                Score: {lp.score.toFixed(2)} ΓÇó {lp.totalOrders.toLocaleString()} orders
              </div>
            </div>
            <div className="flex items-center gap-4 text-xs text-zinc-400">
              <div className="flex items-center gap-1">
                <Icon name="clock" size="sm" className="w-3 h-3" />
                {lp.latency.avg.toFixed(1)}ms
              </div>
              <div className="flex items-center gap-1">
                <Icon name="crosshair" size="sm" className="w-3 h-3" />
                {(lp.fillRate * 100).toFixed(1)}%
              </div>
              <div className="flex items-center gap-1">
                <Icon name="zap" size="sm" className="w-3 h-3" />
                {lp.slippage.avg.toFixed(2)}p
              </div>
            </div>
          </div>
        ))}
      </div>

      {rankings.length === 0 && (
        <div className="text-center text-sm text-zinc-500 py-4">
          No ranking data available
        </div>
      )}
    </div>
  );
};

/**
 * Last Symbol Trading Panel
 * Floating panel that always trades the last used symbol.
 * Prevents wrong-symbol mistakes when multiple charts are open.
 * 
 * Features:
 * - Live BID/ASK display for last traded symbol
 * - One-click BUY LAST / SELL LAST 
 * - Close all positions on last symbol
 * - Volume control with risk-based sizing option
 * - Auto SL/TP (fixed pips)
 * - Keyboard shortcuts: Shift+B (Buy), Shift+S (Sell), Shift+X (Close)
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { Icon } from './ui/Icon';
import { useLastSymbolStore } from '../store/useLastSymbolStore';
import { useAppStore } from '../store/useAppStore';
import { api } from '../services/api';

export function LastSymbolPanel() {
    const {
        lastSymbol,
        lastTradeSide,
        lastTradeTime,
        volume,
        useRiskSizing,
        riskPercent,
        autoSLTP,
        slPips,
        tpPips,
        setLastSymbol,
        setPanelVisible,
        setVolume,
        setUseRiskSizing,
        setRiskPercent,
        setAutoSLTP,
        setSLPips,
        setTPPips,
    } = useLastSymbolStore();

    const ticks = useAppStore((s) => s.ticks);
    const account = useAppStore((s) => s.account);
    const positions = useAppStore((s) => s.positions);
    const accountId = useAppStore((s) => s.accountId);

    const [isPlacing, setIsPlacing] = useState(false);
    const [isClosing, setIsClosing] = useState(false);
    const [statusMessage, setStatusMessage] = useState('');
    const [statusType, setStatusType] = useState<'success' | 'error' | 'info'>('info');
    const [showSettings, setShowSettings] = useState(false);
    const [isDragging, setIsDragging] = useState(false);
    const [position, setPosition] = useState(() => {
        const saved = localStorage.getItem('lst_panel_pos');
        if (saved) {
            try { return JSON.parse(saved); } catch { /* ignore */ }
        }
        return { x: window.innerWidth - 280, y: 120 };
    });
    const dragRef = useRef<{ startX: number; startY: number; origX: number; origY: number } | null>(null);
    const panelRef = useRef<HTMLDivElement>(null);

    // Get live tick for last symbol
    const tick = lastSymbol ? ticks[lastSymbol] || ticks[lastSymbol.toUpperCase()] : null;
    const bid = tick?.bid ?? 0;
    const ask = tick?.ask ?? 0;
    const spread = ask - bid;
    const isJPY = lastSymbol.includes('JPY');
    const pipSize = isJPY ? 0.01 : 0.0001;
    const spreadPips = pipSize > 0 ? spread / pipSize : 0;
    const digits = tick?.digits || (isJPY ? 3 : 5);

    // Positions on last symbol
    const lastSymbolPositions = positions.filter(
        (p) => p.symbol.toUpperCase() === lastSymbol.toUpperCase()
    );
    const totalPnL = lastSymbolPositions.reduce((sum, p) => sum + (p.unrealizedPnL || 0), 0);

    // Calculate risk-based lot
    const calculateRiskLot = useCallback(() => {
        if (!useRiskSizing || !account) return volume;
        const balance = account.balance || 0;
        const riskAmount = (balance * riskPercent) / 100;
        const slDistance = slPips * pipSize;
        if (slDistance <= 0) return volume;

        // Approximate pip value (simplified ΓÇö real calculation needs contract size)
        const pipValue = isJPY ? 1000 : 10; // Per standard lot
        const lot = riskAmount / (slPips * pipValue);
        return Math.max(0.01, Math.round(lot * 100) / 100);
    }, [useRiskSizing, account, volume, riskPercent, slPips, pipSize, isJPY]);

    const effectiveLot = useRiskSizing ? calculateRiskLot() : volume;

    // Flash status message
    const flash = useCallback((msg: string, type: 'success' | 'error' | 'info' = 'info') => {
        setStatusMessage(msg);
        setStatusType(type);
        setTimeout(() => setStatusMessage(''), 4000);
    }, []);

    // Place order via MT5 Sync API
    const placeOrder = useCallback(
        async (side: 'BUY' | 'SELL') => {
            if (isPlacing || !lastSymbol) {
                if (!lastSymbol) flash('No last symbol ΓÇö place a trade first', 'error');
                return;
            }

            setIsPlacing(true);
            try {
                const orderData: any = {
                    symbol: lastSymbol,
                    action: side.toLowerCase(),
                    volume: effectiveLot,
                    login: Number(accountId) || 0,
                    comment: 'RTX sync trade',
                    client_request_id: `rtx-${Date.now()}`,
                };

                // Auto SL/TP
                if (autoSLTP && slPips > 0) {
                    const basePrice = side === 'BUY' ? ask : bid;
                    if (basePrice > 0) {
                        orderData.sl =
                            side === 'BUY'
                                ? basePrice - slPips * pipSize
                                : basePrice + slPips * pipSize;
                        if (tpPips > 0) {
                            orderData.tp =
                                side === 'BUY'
                                    ? basePrice + tpPips * pipSize
                                    : basePrice - tpPips * pipSize;
                        }
                    }
                }

                await api.mt5.submitOrder(orderData);
                setLastSymbol(lastSymbol, side);
                flash(`${side} ${effectiveLot} ${lastSymbol} Γ£ô`, 'success');
            } catch (err: any) {
                console.error('LastSymbolPanel order failed:', err);
                flash(err.message || 'Order failed', 'error');
            } finally {
                setIsPlacing(false);
            }
        },
        [isPlacing, lastSymbol, effectiveLot, autoSLTP, slPips, tpPips, pipSize, bid, ask, accountId, setLastSymbol, flash]
    );

    // Close positions on last symbol via MT5 Sync API
    const closeLastPositions = useCallback(async () => {
        if (isClosing || !lastSymbol || lastSymbolPositions.length === 0) {
            if (lastSymbolPositions.length === 0) flash('No positions on ' + lastSymbol, 'info');
            return;
        }

        setIsClosing(true);
        try {
            const login = Number(accountId) || 0;
            let closed = 0;
            for (const pos of lastSymbolPositions) {
                try {
                    await api.mt5.closePosition(pos.id, undefined, login);
                    closed++;
                } catch (e) {
                    console.error('Failed to close position', pos.id, e);
                }
            }
            flash(`Closed ${closed} position(s) on ${lastSymbol} Γ£ô`, 'success');
        } catch (err: any) {
            flash(err.message || 'Close failed', 'error');
        } finally {
            setIsClosing(false);
        }
    }, [isClosing, lastSymbol, lastSymbolPositions, accountId, flash]);

    // Keyboard shortcuts
    useEffect(() => {
        const handleKey = (e: KeyboardEvent) => {
            // Only when panel is visible and Shift is held
            if (!e.shiftKey) return;
            // Don't trigger in input fields
            const tag = (e.target as HTMLElement)?.tagName;
            if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;

            if (e.key === 'B' || e.key === 'b') {
                e.preventDefault();
                placeOrder('BUY');
            } else if (e.key === 'S' || e.key === 's') {
                e.preventDefault();
                placeOrder('SELL');
            } else if (e.key === 'X' || e.key === 'x') {
                e.preventDefault();
                closeLastPositions();
            }
        };

        window.addEventListener('keydown', handleKey);
        return () => window.removeEventListener('keydown', handleKey);
    }, [placeOrder, closeLastPositions]);

    // Dragging
    const onMouseDown = useCallback((e: React.MouseEvent) => {
        if ((e.target as HTMLElement).closest('button, input, select')) return;
        setIsDragging(true);
        dragRef.current = { startX: e.clientX, startY: e.clientY, origX: position.x, origY: position.y };
    }, [position]);

    useEffect(() => {
        if (!isDragging) return;
        const onMove = (e: MouseEvent) => {
            if (!dragRef.current) return;
            const dx = e.clientX - dragRef.current.startX;
            const dy = e.clientY - dragRef.current.startY;
            const newPos = {
                x: Math.max(0, Math.min(window.innerWidth - 260, dragRef.current.origX + dx)),
                y: Math.max(0, Math.min(window.innerHeight - 100, dragRef.current.origY + dy)),
            };
            setPosition(newPos);
        };
        const onUp = () => {
            setIsDragging(false);
            localStorage.setItem('lst_panel_pos', JSON.stringify(position));
        };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
        return () => {
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', onUp);
        };
    }, [isDragging, position]);

    // Time since last trade
    const timeSince = lastTradeTime
        ? (() => {
            const diff = Math.floor((Date.now() - lastTradeTime) / 1000);
            if (diff < 60) return `${diff}s ago`;
            if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
            return `${Math.floor(diff / 3600)}h ago`;
        })()
        : '';

    return (
        <div
            ref={panelRef}
            className="fixed z-[9999] select-none"
            style={{ left: position.x, top: position.y }}
        >
            <div
                className="w-[252px] bg-[#1a1a22] border border-[#2a2e39] rounded-lg shadow-2xl overflow-hidden"
                style={{ boxShadow: '0 8px 32px rgba(0,0,0,0.5)' }}
            >
                {/* Header ΓÇö draggable */}
                <div
                    className="flex items-center justify-between px-3 py-2 bg-[#22222d] border-b border-[#2a2e39] cursor-move"
                    onMouseDown={onMouseDown}
                >
                    <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-amber-400 animate-pulse" />
                        <span className="text-[11px] font-bold text-amber-400 tracking-wide">
                            LAST SYMBOL TRADER
                        </span>
                    </div>
                    <div className="flex items-center gap-1">
                        <button
                            onClick={() => setShowSettings(!showSettings)}
                            className="w-5 h-5 flex items-center justify-center rounded hover:bg-white/10 text-zinc-500 hover:text-zinc-300 transition-colors"
                            title="Settings"
                        >
                            <Icon name="settings" size="xs" />
                        </button>
                        <button
                            onClick={() => setPanelVisible(false)}
                            className="w-5 h-5 flex items-center justify-center rounded hover:bg-red-500/20 text-zinc-500 hover:text-red-400 transition-colors"
                            title="Close Panel"
                        >
                            <Icon name="x-close" size="xs" />
                        </button>
                    </div>
                </div>

                {/* Symbol Display */}
                <div className="px-3 py-2 border-b border-[#2a2e39]/50">
                    <div className="flex items-center justify-between">
                        <div>
                            <div className="text-[10px] text-zinc-500 uppercase tracking-wider">Last Traded</div>
                            <div className="text-[18px] font-bold text-amber-400 font-mono leading-tight">
                                {lastSymbol || 'NONE'}
                            </div>
                        </div>
                        {lastTradeSide && (
                            <div className="flex flex-col items-end">
                                <span
                                    className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${lastTradeSide === 'BUY'
                                        ? 'bg-teal-500/20 text-teal-400'
                                        : 'bg-red-500/20 text-red-400'
                                        }`}
                                >
                                    {lastTradeSide}
                                </span>
                                <span className="text-[9px] text-zinc-600 mt-0.5">{timeSince}</span>
                            </div>
                        )}
                    </div>
                </div>

                {/* BID / ASK */}
                {lastSymbol && (
                    <div className="grid grid-cols-2 gap-0 border-b border-[#2a2e39]/50">
                        <div className="px-3 py-1.5 border-r border-[#2a2e39]/50">
                            <div className="text-[9px] text-zinc-500">BID</div>
                            <div className="text-[13px] font-mono font-bold text-red-400">
                                {bid > 0 ? bid.toFixed(digits) : '---'}
                            </div>
                        </div>
                        <div className="px-3 py-1.5">
                            <div className="text-[9px] text-zinc-500">ASK</div>
                            <div className="text-[13px] font-mono font-bold text-teal-400">
                                {ask > 0 ? ask.toFixed(digits) : '---'}
                            </div>
                        </div>
                    </div>
                )}

                {/* Spread & Info Row */}
                {lastSymbol && (
                    <div className="px-3 py-1.5 border-b border-[#2a2e39]/50 flex items-center justify-between text-[10px]">
                        <span className="text-zinc-500">
                            Spread: <span className="text-zinc-300 font-mono">{spreadPips.toFixed(1)}</span> pips
                        </span>
                        <span className="text-zinc-500">
                            Lot: <span className="text-zinc-300 font-mono">{effectiveLot.toFixed(2)}</span>
                            {useRiskSizing && (
                                <span className="text-amber-500/70 ml-1">({riskPercent}%)</span>
                            )}
                        </span>
                    </div>
                )}

                {/* Volume Control */}
                <div className="px-3 py-2 border-b border-[#2a2e39]/50">
                    <div className="flex items-center gap-1.5">
                        <button
                            onClick={() => setVolume(volume - 0.01)}
                            disabled={volume <= 0.01 || isPlacing || useRiskSizing}
                            className="w-6 h-6 flex items-center justify-center bg-[#2a2e39] hover:bg-[#353a47] disabled:opacity-30 disabled:cursor-not-allowed text-zinc-300 rounded text-xs transition-colors"
                        >
                            ΓêÆ
                        </button>
                        <input
                            type="number"
                            step={0.01}
                            min={0.01}
                            value={useRiskSizing ? effectiveLot : volume}
                            onChange={(e) => {
                                const val = parseFloat(e.target.value);
                                if (!isNaN(val) && val >= 0.01) setVolume(val);
                            }}
                            disabled={isPlacing || useRiskSizing}
                            className="flex-1 px-2 py-1 bg-[#0d0d11] border border-[#2a2e39] rounded text-center text-[11px] font-mono text-zinc-200 focus:outline-none focus:border-amber-500/50 disabled:opacity-50 w-0"
                        />
                        <button
                            onClick={() => setVolume(volume + 0.01)}
                            disabled={isPlacing || useRiskSizing}
                            className="w-6 h-6 flex items-center justify-center bg-[#2a2e39] hover:bg-[#353a47] disabled:opacity-30 disabled:cursor-not-allowed text-zinc-300 rounded text-xs transition-colors"
                        >
                            +
                        </button>
                    </div>
                    {/* Lot presets */}
                    <div className="flex gap-1 mt-1.5">
                        {[0.01, 0.05, 0.1, 0.5, 1.0].map((preset) => (
                            <button
                                key={preset}
                                onClick={() => setVolume(preset)}
                                disabled={useRiskSizing}
                                className={`flex-1 text-[9px] py-0.5 rounded border transition-colors ${Math.abs(volume - preset) < 0.001
                                    ? 'bg-amber-500/20 border-amber-500/40 text-amber-400'
                                    : 'bg-[#2a2e39] border-[#2a2e39] text-zinc-400 hover:text-zinc-200 hover:border-zinc-600'
                                    } disabled:opacity-30`}
                            >
                                {preset}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Auto SL/TP indicators */}
                {autoSLTP && (
                    <div className="px-3 py-1 border-b border-[#2a2e39]/50 flex items-center justify-between text-[9px]">
                        <span className="text-red-400/70">SL: {slPips} pips</span>
                        <span className="text-teal-400/70">TP: {tpPips} pips</span>
                    </div>
                )}

                {/* Buy / Sell Buttons */}
                <div className="grid grid-cols-2 gap-2 p-3">
                    <button
                        onClick={() => placeOrder('BUY')}
                        disabled={isPlacing || !lastSymbol || bid === 0}
                        className="flex flex-col items-center justify-center py-2.5 rounded-md bg-teal-600/20 hover:bg-teal-600/35 border border-teal-500/30 hover:border-teal-500/60 disabled:opacity-30 disabled:cursor-not-allowed text-white transition-all group active:scale-95"
                    >
                        <span className="text-[10px] font-bold tracking-wide">Γû▓ BUY LAST</span>
                        <span className="text-[11px] font-mono mt-0.5 text-teal-300/80 group-hover:text-teal-200">
                            {ask > 0 ? ask.toFixed(digits) : '---'}
                        </span>
                    </button>

                    <button
                        onClick={() => placeOrder('SELL')}
                        disabled={isPlacing || !lastSymbol || bid === 0}
                        className="flex flex-col items-center justify-center py-2.5 rounded-md bg-red-600/20 hover:bg-red-600/35 border border-red-500/30 hover:border-red-500/60 disabled:opacity-30 disabled:cursor-not-allowed text-white transition-all group active:scale-95"
                    >
                        <span className="text-[10px] font-bold tracking-wide">Γû╝ SELL LAST</span>
                        <span className="text-[11px] font-mono mt-0.5 text-red-300/80 group-hover:text-red-200">
                            {bid > 0 ? bid.toFixed(digits) : '---'}
                        </span>
                    </button>
                </div>

                {/* Close & Positions */}
                <div className="px-3 pb-2">
                    <button
                        onClick={closeLastPositions}
                        disabled={isClosing || lastSymbolPositions.length === 0}
                        className="w-full py-1.5 rounded bg-[#2a2e39] hover:bg-[#353a47] border border-[#3a3f4c] disabled:opacity-30 disabled:cursor-not-allowed text-[10px] font-semibold text-zinc-300 transition-colors"
                    >
                        CLOSE {lastSymbol} ({lastSymbolPositions.length}) ΓÇó{' '}
                        <span className={totalPnL >= 0 ? 'text-teal-400' : 'text-red-400'}>
                            {totalPnL >= 0 ? '+' : ''}{totalPnL.toFixed(2)}
                        </span>
                    </button>
                </div>

                {/* Account Summary */}
                {account && (
                    <div className="px-3 py-1.5 border-t border-[#2a2e39]/50 flex items-center justify-between text-[9px] text-zinc-500">
                        <span>Bal: ${account.balance?.toFixed(2)}</span>
                        <span>Eq: ${account.equity?.toFixed(2)}</span>
                    </div>
                )}

                {/* Status Message */}
                {statusMessage && (
                    <div
                        className={`px-3 py-1.5 text-[10px] font-medium text-center transition-all ${statusType === 'success'
                            ? 'bg-teal-500/10 text-teal-400'
                            : statusType === 'error'
                                ? 'bg-red-500/10 text-red-400'
                                : 'bg-zinc-700/20 text-blue-400'
                            }`}
                    >
                        {statusMessage}
                    </div>
                )}

                {/* Hotkey Hint */}
                <div className="px-3 py-1 border-t border-[#2a2e39]/30 text-[8px] text-zinc-600 text-center">
                    Shift+B Buy ΓÇó Shift+S Sell ΓÇó Shift+X Close
                </div>

                {/* Settings Panel */}
                {showSettings && (
                    <div className="border-t border-[#2a2e39] bg-[#16161e] px-3 py-2 space-y-2">
                        <div className="text-[10px] text-zinc-400 font-bold uppercase tracking-wider">Settings</div>

                        {/* Risk-based sizing */}
                        <label className="flex items-center justify-between text-[10px] text-zinc-300 cursor-pointer">
                            <span>Risk-based lots</span>
                            <input
                                type="checkbox"
                                checked={useRiskSizing}
                                onChange={(e) => setUseRiskSizing(e.target.checked)}
                                className="accent-amber-500"
                            />
                        </label>
                        {useRiskSizing && (
                            <div className="flex items-center gap-2">
                                <span className="text-[9px] text-zinc-500 w-12">Risk %</span>
                                <input
                                    type="number"
                                    step={0.1}
                                    min={0.1}
                                    max={100}
                                    value={riskPercent}
                                    onChange={(e) => setRiskPercent(parseFloat(e.target.value) || 1)}
                                    className="flex-1 px-1.5 py-0.5 bg-[#0d0d11] border border-[#2a2e39] rounded text-[10px] font-mono text-zinc-200 focus:outline-none focus:border-amber-500/50"
                                />
                            </div>
                        )}

                        {/* Auto SL/TP */}
                        <label className="flex items-center justify-between text-[10px] text-zinc-300 cursor-pointer">
