import React, { useEffect, useState, useRef } from 'react';
import { createChart, ColorType } from 'lightweight-charts';
import type { IChartApi, ISeriesApi, Time } from 'lightweight-charts';
import './LiveForexChart.css';
import { API_BASE_URL as API_BASE, WS_ENDPOINTS } from '../config/api';
import { useWebSocket } from '../hooks/useWebSocket';

interface OHLCCandle {
    time: number; // UNIX timestamp
    open: number;
    high: number;
    low: number;
    close: number;
    volume: number;
}

const AVAILABLE_SYMBOLS = [
    'EURUSD', 'GBPUSD', 'USDJPY', 'AUDUSD', 'USDCAD', 'USDCHF',
    'NZDUSD', 'EURGBP', 'EURJPY', 'GBPJPY', 'BTCUSD', 'ETHUSD',
    'XAUUSD', 'XAGUSD'
];

const TIMEFRAMES = [
    { label: '1m', value: '1m' },
    { label: '5m', value: '5m' },
    { label: '15m', value: '15m' },
    { label: '1h', value: '1h' },
    { label: '4h', value: '4h' },
    { label: '1D', value: '1d' }
];

// API_BASE imported from config

interface LiveForexChartProps {
    initialSymbol?: string;
    availableSymbols?: string[];
}

export const LiveForexChart: React.FC<LiveForexChartProps> = ({
    initialSymbol = 'EURUSD',
    availableSymbols
}) => {
    const symbols = availableSymbols || AVAILABLE_SYMBOLS;
    const [selectedSymbol, setSelectedSymbol] = useState(initialSymbol);
    const [selectedTimeframe, setSelectedTimeframe] = useState('5m');
    const [currentPrice, setCurrentPrice] = useState({ bid: 0, ask: 0, spread: 0 });
    const [ohlc, setOhlc] = useState({ open: 0, high: 0, low: 0, close: 0 });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const chartContainerRef = useRef<HTMLDivElement>(null);
    const chartRef = useRef<IChartApi | null>(null);
    const candleSeriesRef = useRef<ISeriesApi<'Candlestick'> | null>(null);
    const wsRef = useRef<WebSocket | null>(null);

    // Initialize chart
    useEffect(() => {
        if (!chartContainerRef.current) return;

        const chart = createChart(chartContainerRef.current, {
            width: chartContainerRef.current.clientWidth,
            height: 500,
            layout: {
                background: { type: ColorType.Solid, color: '#1a1a1a' },
                textColor: '#d1d4dc',
            },
            grid: {
                vertLines: { color: '#2a2e39' },
                horzLines: { color: '#2a2e39' },
            },
            timeScale: {
                timeVisible: true,
                secondsVisible: false,
            },
        });

        const candleSeries = (chart as any).addCandlestickSeries({
            upColor: '#26a69a',
            downColor: '#ef5350',
            borderVisible: false,
            wickUpColor: '#26a69a',
            wickDownColor: '#ef5350',
        });

        chartRef.current = chart;
        candleSeriesRef.current = candleSeries;

        // Handle resize
        const handleResize = () => {
            if (chartContainerRef.current && chartRef.current) {
                chartRef.current.applyOptions({
                    width: chartContainerRef.current.clientWidth,
                });
            }
        };

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            chart.remove();
        };
    }, []);

    // Fetch OHLC data when symbol or timeframe changes
    useEffect(() => {
        fetchOHLCData();
    }, [selectedSymbol, selectedTimeframe]);

    // WebSocket connection handled by useWebSocket hook and subscribe useEffect above

    const fetchOHLCData = async () => {
        try {
            setLoading(true);
            setError(null);

            const response = await fetch(
                `${API_BASE}/api/history/ohlc?symbol=${selectedSymbol}&timeframe=${selectedTimeframe}&limit=200`
            );

            if (!response.ok) {
                throw new Error(`Failed to fetch OHLC data: ${response.statusText}`);
            }

            const candles: OHLCCandle[] = await response.json();

            if (candles.length === 0) {
                setError(`No historical data available for ${selectedSymbol}`);
                return;
            }

            // Convert to Lightweight Charts format
            const chartData = candles.map(candle => ({
                time: candle.time as Time,
                open: candle.open,
                high: candle.high,
                low: candle.low,
                close: candle.close,
            }));

            // Update chart
            if (candleSeriesRef.current) {
                candleSeriesRef.current.setData(chartData);
            }

            // Update current OHLC display
            const lastCandle = candles[candles.length - 1];
            setOhlc({
                open: lastCandle.open,
                high: lastCandle.high,
                low: lastCandle.low,
                close: lastCandle.close,
            });

            setLoading(false);
        } catch (err) {
            console.error('Error fetching OHLC data:', err);
            setError(err instanceof Error ? err.message : 'Failed to fetch data');
            setLoading(false);
        }
    };

    // Use centralized WebSocket with auto-reconnection
    const { subscribe } = useWebSocket({
        url: WS_ENDPOINTS.general,
        autoConnect: true,
    });

    // Subscribe to tick messages for selected symbol
    useEffect(() => {
        const unsubscribe = subscribe('*', (message: any) => {
            try {
                const data = message;

                if (data.type === 'tick' && data.symbol === selectedSymbol) {
                    setCurrentPrice({
                        bid: data.bid,
                        ask: data.ask,
                        spread: data.spread || (data.ask - data.bid),
                    });

                    // Update latest candle close price
                    setOhlc(prev => ({
                        ...prev,
                        close: (data.bid + data.ask) / 2,
                        high: Math.max(prev.high, (data.bid + data.ask) / 2),
                        low: Math.min(prev.low, (data.bid + data.ask) / 2),
                    }));
                }
            } catch (err) {
                console.error('Error parsing WebSocket message:', err);
            }
        });

        return () => {
            unsubscribe();
        };
    }, [selectedSymbol, subscribe]);

    const handleSymbolChange = (symbol: string) => {
        setSelectedSymbol(symbol);
    };

    const handleTimeframeChange = (tf: string) => {
        setSelectedTimeframe(tf);
    };

    return (
        <div className="live-forex-chart">
            <div className="chart-header">
                <div className="symbol-selector">
                    <label>Symbol:</label>
                    <select value={selectedSymbol} onChange={(e) => handleSymbolChange(e.target.value)}>
                        {symbols.map(symbol => (
                            <option key={symbol} value={symbol}>{symbol}</option>
                        ))}
                    </select>
                </div>

                <div className="price-display">
                    <div className="price-item">
                        <span className="label">Bid:</span>
                        <span className="value bid">{currentPrice.bid.toFixed(5)}</span>
                    </div>
                    <div className="price-item">
                        <span className="label">Ask:</span>
                        <span className="value ask">{currentPrice.ask.toFixed(5)}</span>
                    </div>
                    <div className="price-item">
                        <span className="label">Spread:</span>
                        <span className="value spread">{(currentPrice.spread * 10000).toFixed(1)} pips</span>
                    </div>
                </div>

                <div className="timeframe-selector">
                    {TIMEFRAMES.map(tf => (
                        <button
                            key={tf.value}
                            className={`tf-btn ${selectedTimeframe === tf.value ? 'active' : ''}`}
                            onClick={() => handleTimeframeChange(tf.value)}
                        >
                            {tf.label}
                        </button>
                    ))}
                </div>
            </div>

            {loading && (
                <div className="loading-overlay">
                    <div className="spinner"></div>
                    <p>Loading chart data...</p>
                </div>
            )}

            {error && (
                <div className="error-message">
                    <p>ΓÜá∩╕Å {error}</p>
                    <button onClick={fetchOHLCData}>Retry</button>
                </div>
            )}

            <div className="chart-container" ref={chartContainerRef}></div>

            <div className="ohlc-display">
                <div className="ohlc-item">
                    <span className="label">O:</span>
                    <span className="value">{ohlc.open.toFixed(5)}</span>
                </div>
                <div className="ohlc-item">
                    <span className="label">H:</span>
                    <span className="value">{ohlc.high.toFixed(5)}</span>
                </div>
                <div className="ohlc-item">
                    <span className="label">L:</span>
                    <span className="value">{ohlc.low.toFixed(5)}</span>
                </div>
                <div className="ohlc-item">
                    <span className="label">C:</span>
                    <span className="value">{ohlc.close.toFixed(5)}</span>
                </div>
            </div>
        </div>
    );
};

export default LiveForexChart;

import { Icon } from './ui/Icon';
import React, { useState } from 'react';
import { useAppStore } from '../store/useAppStore';
import { api } from '../services/api';
import { API_BASE_URL } from '../config/api';
import '../styles/login.css';

interface LoginProps {
    onLogin: (accountId: string) => void;
}

export function Login({ onLogin }: LoginProps) {
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Form fields
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [server, setServer] = useState(
        import.meta.env.DEV
            ? 'rtxbackend.tradecopier.org'
            : API_BASE_URL.replace('http://', '').replace('https://', '')
    );
    const [rememberMe, setRememberMe] = useState(false);

    // Initial load for remembered credentials
    React.useEffect(() => {
        const savedUsername = localStorage.getItem('rtx_saved_username');
        const savedPassword = localStorage.getItem('rtx_saved_password');
        if (savedUsername && savedPassword) {
            setUsername(savedUsername);
            try {
                // Basic decoding - not true encryption but better than plain text in storage
                setPassword(atob(savedPassword));
            } catch (e) {
                // Fallback if decoding fails
            }
            setRememberMe(true);
        }
    }, []);

    const setAuthenticated = useAppStore(state => state.setAuthenticated);
    const setAuthToken = useAppStore(state => state.setAuthToken);
    const addSavedAccount = useAppStore(state => state.addSavedAccount);
    const setActiveAccount = useAppStore(state => state.setActiveAccount);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError(null);

        // Always call the backend directly
        const BACKEND_URL = 'https://rtxbackend.tradecopier.org';

        try {
            // Make login request using the direct backend URL
            const data = await api.auth.login(username, password, BACKEND_URL);

            console.log('[Login] Full login response user:', data.user);
            const token = data.access_token;
            if (!token) {
                throw new Error('No authentication token received');
            }

            // Extract true account ID from user data, fallback to username if not present
            const accountId = data.user?.id || username;

            // Persist last successful login for session restore even without Remember Me
            localStorage.setItem('rtx_last_login', String(accountId));

            // Always save credentials for session restore / auto re-login
            localStorage.setItem('rtx_saved_username', username);
            try {
                localStorage.setItem('rtx_saved_password', btoa(password));
            } catch (e) {
                // Ignore encoding errors
            }

            // Persist the base URL and tokens for all subsequent requests
            import('../api/client').then(({ setBaseUrl, setToken, setRefreshToken }) => {
                setBaseUrl(BACKEND_URL);
                setToken(token);
                if (data.refresh_token) {
                    setRefreshToken(data.refresh_token);
                }
                if (data.expires_at) {
                    localStorage.setItem('token_expires_at', data.expires_at);
                }
            });

            onLogin(accountId);

            // Save into savedAccounts for multi-account switching persistence
            const loginNum = parseInt(username, 10);
            if (!isNaN(loginNum)) {
                addSavedAccount({
                    login: loginNum,
                    name: data.user?.username || '',
                    server: 'FlexyMarkets-Server',
                    isLive: true,
                    lastUsed: Date.now(),
                    password: btoa(password),
                });
                setActiveAccount(loginNum);
            }
        } catch (err: any) {
            console.error('Auth error:', err);
            setError(err.message || 'Authentication failed');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="login-page-container">
            {/* Background Layers */}
            <img
                src="file:///C:/Users/ADMIN/.gemini/antigravity/brain/23cdb6e2-d121-4948-83d4-5877c4d33bb6/login_branding_visual_1771853546436.png"
                className="login-background-visual"
                alt=""
            />
            <div className="login-background-overlay" />

            {/* Login Card */}
            <div className="login-card">
                <div className="login-header">
                    <div className="login-logo-container">
                        <Icon name="shield" size="xl" className="text-white" />
                    </div>
                    <h1 className="login-title">RTX Terminal</h1>
                    {/* <p className="login-subtitle">Institutional Trading Environment</p> */}
                </div>

                {error && (
                    <div className="mb-6 p-3 rounded-lg bg-red-500/10 border border-red-500/20 text-red-500 text-sm text-center">
                        {error}
                    </div>
                )}

                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label className="block text-[10px] font-bold text-[#4a5568] uppercase tracking-[0.2em] mb-3 ml-1">
                            Credential
                        </label>
                        <div className="login-input-group">
                            <Icon name="user" size="lg" className="input-icon" />
                            <input
                                type="text"
                                className="login-input"
                                placeholder="Account ID"
                                required
                                value={username}
                                onChange={(e) => setUsername(e.target.value)}
                            />
                        </div>

                        <div className="login-input-group">
                            <Icon name="lock" size="lg" className="input-icon" />
                            <input
                                type="password"
                                className="login-input"
                                placeholder="Password"
                                required
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                            />
                        </div>
                    </div>
                    {/* 
                    <div className="mb-6">
                        <label className="block text-[10px] font-bold text-[#4a5568] uppercase tracking-[0.2em] mb-3 ml-1">
                            Server Connection
                        </label>
                        <div className="login-input-group">
                            <Icon name="server" size="lg" className="input-icon" />
                            <input
                                type="text"
                                className="login-input"
                                placeholder="Server Address"
                                required
                                value={server}
                                onChange={(e) => setServer(e.target.value)}
                            />
                        </div>
                    </div> */}

                    <div className="mb-6 flex items-center">
                        <input
                            type="checkbox"
                            id="rememberMe"
                            className="w-4 h-4 bg-[#131316] border-zinc-700 rounded text-emerald-500 focus:ring-emerald-500 focus:ring-offset-zinc-900"
                            checked={rememberMe}
                            onChange={(e) => setRememberMe(e.target.checked)}
                        />
                        <label htmlFor="rememberMe" className="ml-2 text-sm text-zinc-400 font-medium cursor-pointer">
                            Remember credentials
                        </label>
                    </div>

                    <button
                        type="submit"
                        className="login-submit-btn"
                        disabled={loading}
                    >
                        {loading ? (
                            <Icon name="refresh" size="sm" className="animate-spin" />
                        ) : (
                            <>
                                Login <Icon name="arrow-right" size="lg" />
                            </>
                        )}
                    </button>
                </form>

                <div className="server-info-badge">
                    <div className="status-dot" />
                    <span>System Operational</span>
                </div>

                <p className="login-footer-text">
                    Need help?
                    <a href="#" className="footer-link">Support Center</a>
                </p>
            </div>
        </div>
    );
}

/**
 * MT5-Style Login Dialog
 * Modal dialog for switching accounts / logging in
 * Matches the Flexy Market MT5 Login dialog styling
 */

import React, { useState, useEffect, useRef } from 'react';
import ReactDOM from 'react-dom';
import { useAppStore } from '../store/useAppStore';
import { api } from '../services/api';
import { User, X, HelpCircle } from 'lucide-react';

interface LoginDialogProps {
    isOpen: boolean;
    onClose: () => void;
    onLoginSuccess?: (accountId: string) => void;
    initialLogin?: string;
}

export function LoginDialog({ isOpen, onClose, onLoginSuccess, initialLogin = '' }: LoginDialogProps) {
    const [login, setLogin] = useState('');
    const [password, setPassword] = useState('');
    const [server, setServer] = useState('FlexyMarkets-Server');
    const [savePassword, setSavePassword] = useState(true);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const loginInputRef = useRef<HTMLInputElement>(null);

    // Pre-fill with current account or provided initial login
    useEffect(() => {
        if (isOpen) {
            const accountId = initialLogin || useAppStore.getState().accountId || '';
            setLogin(accountId);
            setPassword('');
            setError(null);
            setTimeout(() => loginInputRef.current?.select(), 100);
        }
    }, [isOpen, initialLogin]);

    // Handle ESC key
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
        };
        if (isOpen) {
            document.addEventListener('keydown', handleKeyDown);
        }
        return () => document.removeEventListener('keydown', handleKeyDown);
    }, [isOpen, onClose]);

    const handleSubmit = async (e?: React.FormEvent) => {
        if (e) e.preventDefault();
        if (!login.trim() || !password.trim()) {
            setError('Login and password are required');
            return;
        }

        setLoading(true);
        setError(null);

        try {
            // Logout current session (fire-and-forget)
            fetch('https://rtxbackend.tradecopier.org/api/logout', {
                method: 'POST',
                headers: { 'accept': '*/*', 'Authorization': `Bearer ${localStorage.getItem('auth_token') || ''}` },
            }).catch(() => { });

            // Login with new credentials
            const data = await api.auth.login(login.trim(), password);

            const token = data.access_token;
            if (!token) {
                throw new Error('No authentication token received');
            }

            const accountId = data.user?.id || login.trim();

            // Save credentials
            localStorage.setItem('rtx_last_login', String(accountId));
            localStorage.setItem('rtx_saved_username', login.trim());
            if (savePassword) {
                try { localStorage.setItem('rtx_saved_password', btoa(password)); } catch { }
            }

            // Set tokens
            const { setToken, setRefreshToken } = await import('../api/client');
            setToken(token);
            if (data.refresh_token) setRefreshToken(data.refresh_token);
            if (data.expires_at) localStorage.setItem('token_expires_at', data.expires_at);

            // Update store
            const expiresAt = data.expires_at ? new Date(data.expires_at).getTime() : undefined;
            useAppStore.getState().setAuthTokens(token, data.refresh_token, expiresAt);
            useAppStore.getState().setAuthenticated(true, String(accountId), token, data.refresh_token, expiresAt);

            // Save to saved accounts for Navigator panel
            const loginNum = parseInt(login.trim(), 10);
            if (!isNaN(loginNum)) {
                useAppStore.getState().addSavedAccount({
                    login: loginNum,
                    name: data.user?.username || '',
                    server: 'FlexyMarkets-Server',
                    isLive: true,
                    lastUsed: Date.now(),
                    password: savePassword ? btoa(password) : undefined,
                });
                useAppStore.getState().setActiveAccount(loginNum);
            }

            onClose();
            if (onLoginSuccess) {
                onLoginSuccess(String(accountId));
            } else {
                window.location.reload();
            }
        } catch (err: any) {
            console.error('[LoginDialog] Auth error:', err);
            setError(err.message || 'Authentication failed');
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return ReactDOM.createPortal(
        <div className="fixed inset-0 z-[10000] flex items-center justify-center">
            {/* Backdrop */}
            <div className="absolute inset-0 bg-black/60" onClick={onClose} />

            {/* Dialog */}
            <div
                className="relative w-[420px] bg-[#2b2e3b] border border-[#555] rounded-lg shadow-2xl overflow-hidden"
                onClick={(e) => e.stopPropagation()}
            >
                {/* Title Bar */}
                <div className="flex items-center justify-between bg-[#353847] px-3 py-2 border-b border-[#555]">
                    <div className="flex items-center gap-2">
                        <User size={16} className="text-blue-400" />
                        <span className="text-[13px] text-zinc-200 font-medium">Login</span>
                    </div>
                    <div className="flex items-center gap-1">
                        <button className="p-1 hover:bg-white/10 rounded transition-colors" title="Help">
                            <HelpCircle size={14} className="text-zinc-400" />
                        </button>
                        <button onClick={onClose} className="p-1 hover:bg-red-500/80 rounded transition-colors" title="Close">
                            <X size={14} className="text-zinc-400 hover:text-white" />
                        </button>
                    </div>
                </div>

                {/* Content */}
                <form onSubmit={handleSubmit} className="px-5 py-4">
                    {/* Authorization Info */}
                    <div className="flex items-center gap-3 mb-5">
                        <div className="w-10 h-10 rounded-full bg-zinc-700/30 flex items-center justify-center flex-shrink-0">
                            <User size={22} className="text-blue-400" />
                        </div>
                        <p className="text-[11px] text-zinc-400 leading-relaxed">
                            Authorization allows to get access to the trade account
                        </p>
                    </div>

                    {/* Login Field */}
                    <div className="flex items-center gap-3 mb-3">
                        <label className="text-[12px] text-zinc-400 w-20 text-right flex-shrink-0">Login:</label>
                        <input
                            ref={loginInputRef}
                            type="text"
                            value={login}
                            onChange={(e) => setLogin(e.target.value)}
                            className="flex-1 h-[28px] px-2 bg-[#1a1c26] border border-zinc-600/60 rounded text-[12px] text-zinc-100 font-mono outline-none focus:border-zinc-600 transition-colors"
                            placeholder="Account ID"
                            autoFocus
                        />
                    </div>

                    {/* Password Field */}
                    <div className="flex items-center gap-3 mb-3">
                        <label className="text-[12px] text-zinc-400 w-20 text-right flex-shrink-0">Password:</label>
                        <div className="flex-1 flex items-center gap-2">
                            <input
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="flex-1 h-[28px] px-2 bg-[#1a1c26] border border-[#555] rounded text-[12px] text-zinc-100 font-mono outline-none focus:border-zinc-600 transition-colors"
                                placeholder="Password"
                                onKeyDown={(e) => { if (e.key === 'Enter') handleSubmit(); }}
                            />
                            <label className="flex items-center gap-1.5 cursor-pointer flex-shrink-0">
                                <input
                                    type="checkbox"
                                    checked={savePassword}
                                    onChange={(e) => setSavePassword(e.target.checked)}
                                    className="w-3.5 h-3.5 rounded border-zinc-500 bg-[#1a1c26] accent-blue-500"
                                />
                                <span className="text-[10px] text-zinc-400 whitespace-nowrap leading-tight">Save<br />password</span>
                            </label>
                        </div>
                    </div>

                    {/* Server Field */}
                    <div className="flex items-center gap-3 mb-4">
                        <label className="text-[12px] text-zinc-400 w-20 text-right flex-shrink-0">Server:</label>
                        <select
                            value={server}
                            onChange={(e) => setServer(e.target.value)}
                            className="flex-1 h-[28px] px-2 bg-[#1a1c26] border border-[#555] rounded text-[12px] text-zinc-100 outline-none focus:border-zinc-600 transition-colors cursor-pointer appearance-none"
                            style={{
                                backgroundImage: `url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3e%3cpath stroke='%236b7280' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='M6 8l4 4 4-4'/%3e%3c/svg%3e")`,
                                backgroundPosition: 'right 4px center',
                                backgroundRepeat: 'no-repeat',
                                backgroundSize: '20px',
                                paddingRight: '28px',
                            }}
                        >
                            <option value="FlexyMarkets-Server">FlexyMarkets-Server</option>
                        </select>
                    </div>

                    {/* Error */}
                    {error && (
                        <div className="mb-3 px-2 py-1.5 bg-red-500/15 border border-red-500/30 rounded text-[11px] text-red-400">
                            {error}
