        </div>

        {/* Summary Cards */}
        <div className="grid grid-cols-4 gap-3 mb-4">
          <SummaryCard
            icon={<Icon name="credit-card" size="lg" />}
            label="Total Balance"
            value={`$${summaryTotals.totalBalance.toFixed(2)}`}
            color="text-blue-400"
          />
          <SummaryCard
            icon={<Icon name="trending-up" size="lg" />}
            label="Total Equity"
            value={`$${summaryTotals.totalEquity.toFixed(2)}`}
