/**
 * OHLC Data Window
 * MT5-style Data Window showing detailed OHLC info
 * Displays current candle data with color-coded changes
 */

import React, { useEffect, useState, useCallback } from 'react';
import { candleAggregationService, CandleData, Timeframe } from '../services/candleAggregationService';

interface OHLCDataWindowProps {
  symbol: string;
  timeframe?: Timeframe;
  showTicks?: boolean;
  className?: string;
}

interface TickData {
  price: number;
  volume: number;
  time: number;
  side: 'bid' | 'ask';
}

export const OHLCDataWindow: React.FC<OHLCDataWindowProps> = ({
  symbol,
  timeframe = 'M1',
  showTicks = true,
  className = ''
}) => {
  const [currentCandle, setCurrentCandle] = useState<CandleData | null>(null);
  const [previousCandle, setPreviousCandle] = useState<CandleData | null>(null);
  const [ticks, setTicks] = useState<TickData[]>([]);
  const [lastUpdate, setLastUpdate] = useState<Date>(new Date());

  const formatPrice = (price: number): string => {
    return price.toFixed(5);
  };

  const formatTime = (timestamp: number): string => {
    const date = new Date(timestamp * 1000);
    return date.toLocaleTimeString('en-US', {
      hour12: false,
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  };

  const updateData = useCallback(() => {
    const candles = candleAggregationService.getCandles(symbol, timeframe, true);

    if (candles.length > 0) {
      setCurrentCandle(candles[candles.length - 1]);
      setPreviousCandle(candles.length > 1 ? candles[candles.length - 2] : null);
    }

    setLastUpdate(new Date());
  }, [symbol, timeframe]);

  useEffect(() => {
    updateData();
    const interval = setInterval(updateData, 250);
    return () => clearInterval(interval);
  }, [updateData]);

  const getChange = (current: number, previous: number): { value: number; percent: number; direction: 'up' | 'down' | 'flat' } => {
    const change = current - previous;
    const percent = previous !== 0 ? (change / previous) * 100 : 0;

    return {
      value: change,
      percent,
      direction: change > 0.00001 ? 'up' : change < -0.00001 ? 'down' : 'flat'
    };
  };

  const getDirectionColor = (direction: 'up' | 'down' | 'flat') => {
    switch (direction) {
      case 'up': return 'text-green-400';
      case 'down': return 'text-red-400';
      default: return 'text-gray-400';
    }
  };

  const getChangeSymbol = (direction: 'up' | 'down' | 'flat') => {
    switch (direction) {
      case 'up': return 'Γû▓';
      case 'down': return 'Γû╝';
      default: return 'ΓùÅ';
    }
  };

  const renderRow = (label: string, value: string | number, change?: { value: number; percent: number; direction: 'up' | 'down' | 'flat' }) => (
    <div className="flex justify-between items-center py-1 px-2 hover:bg-zinc-800/50">
      <span className="text-zinc-500 text-xs">{label}</span>
      <div className="flex items-center gap-2">
        <span className="text-zinc-200 font-mono text-xs">{value}</span>
        {change && (
          <span className={`text-xs ${getDirectionColor(change.direction)}`}>
            {getChangeSymbol(change.direction)} {change.value > 0 ? '+' : ''}{change.percent.toFixed(2)}%
          </span>
        )}
      </div>
    </div>
  );

  if (!currentCandle) {
    return (
      <div className={`bg-zinc-900 border border-zinc-700 rounded ${className}`}>
        <div className="p-4 text-center text-zinc-500 text-sm">
          Waiting for data...
        </div>
      </div>
    );
  }

  const closeChange = previousCandle ? getChange(currentCandle.close, previousCandle.close) : null;
  const highChange = previousCandle ? getChange(currentCandle.high, previousCandle.high) : null;
  const lowChange = previousCandle ? getChange(currentCandle.low, previousCandle.low) : null;
  const openChange = previousCandle ? getChange(currentCandle.open, previousCandle.open) : null;

  return (
    <div className={`bg-zinc-900 border border-zinc-700 rounded ${className}`}>
      {/* Header */}
      <div className="bg-zinc-800 px-3 py-2 border-b border-zinc-700">
        <div className="flex justify-between items-center">
          <div>
            <span className="font-bold text-white">{symbol}</span>
            <span className="text-zinc-400 text-xs ml-2">{timeframe}</span>
          </div>
          <div className="flex items-center gap-2">
            <span className={`inline-block w-2 h-2 rounded-full ${currentCandle.isComplete ? 'bg-green-500' : 'bg-yellow-500 animate-pulse'}`} />
            <span className="text-zinc-500 text-xs">{formatTime(currentCandle.time)}</span>
          </div>
        </div>
      </div>

      {/* OHLC Values */}
      <div className="py-1">
        {renderRow('Close', formatPrice(currentCandle.close), closeChange || undefined)}
        {renderRow('Open', formatPrice(currentCandle.open), openChange || undefined)}
        {renderRow('High', formatPrice(currentCandle.high), highChange || undefined)}
        {renderRow('Low', formatPrice(currentCandle.low), lowChange || undefined)}

        <div className="border-t border-zinc-800 my-1" />

        {renderRow('Volume', currentCandle.volume.toLocaleString())}

        {/* Range */}
        <div className="flex justify-between items-center py-1 px-2 hover:bg-zinc-800/50">
          <span className="text-zinc-500 text-xs">Range</span>
          <span className="text-zinc-200 font-mono text-xs">
            {(currentCandle.high - currentCandle.low).toFixed(5)}
          </span>
        </div>

        {/* Body */}
        <div className="flex justify-between items-center py-1 px-2 hover:bg-zinc-800/50">
          <span className="text-zinc-500 text-xs">Body</span>
          <span className={`font-mono text-xs ${currentCandle.close >= currentCandle.open ? 'text-green-400' : 'text-red-400'}`}>
            {Math.abs(currentCandle.close - currentCandle.open).toFixed(5)}
          </span>
        </div>

        {/* Shadow (Upper) */}
        <div className="flex justify-between items-center py-1 px-2 hover:bg-zinc-800/50">
          <span className="text-zinc-500 text-xs">Upper Shadow</span>
          <span className="text-zinc-200 font-mono text-xs">
            {(currentCandle.high - Math.max(currentCandle.open, currentCandle.close)).toFixed(5)}
          </span>
        </div>

        {/* Shadow (Lower) */}
        <div className="flex justify-between items-center py-1 px-2 hover:bg-zinc-800/50">
          <span className="text-zinc-500 text-xs">Lower Shadow</span>
          <span className="text-zinc-200 font-mono text-xs">
            {(Math.min(currentCandle.open, currentCandle.close) - currentCandle.low).toFixed(5)}
          </span>
        </div>
      </div>

      {/* Footer */}
      <div className="bg-zinc-800 px-3 py-1.5 border-t border-zinc-700 text-xs text-zinc-500 text-center">
        Last update: {lastUpdate.toLocaleTimeString()}
      </div>
    </div>
  );
};

export default OHLCDataWindow;

/**
 * OHLC Terminal View
 * Trading terminal style display of OHLC data
 * Similar to MT5 Market Watch / Data Window
 */

import React, { useEffect, useState, useCallback } from 'react';
import { candleAggregationService, CandleData, Timeframe } from '../services/candleAggregationService';

interface OHLCTerminalViewProps {
  symbol: string;
  timeframe?: Timeframe;
  showMultipleTimeframes?: boolean;
  className?: string;
}

interface OHLCRow {
  timeframe: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  change: number;
  changePercent: number;
  direction: 'up' | 'down' | 'flat';
  isComplete: boolean;
}

const TIMEFRAMES: Timeframe[] = ['M1', 'M5', 'M15', 'M30', 'H1', 'H4', 'D1'];

export const OHLCTerminalView: React.FC<OHLCTerminalViewProps> = ({
  symbol,
  timeframe = 'M1',
  showMultipleTimeframes = true,
  className = ''
}) => {
  const [rows, setRows] = useState<OHLCRow[]>([]);
  const [lastUpdate, setLastUpdate] = useState<Date>(new Date());
  const [selectedTf, setSelectedTf] = useState<Timeframe>(timeframe);

  const formatPrice = (price: number, digits: number = 5): string => {
    return price.toFixed(digits);
  };

  const formatVolume = (vol: number): string => {
    if (vol >= 1000000) return (vol / 1000000).toFixed(2) + 'M';
    if (vol >= 1000) return (vol / 1000).toFixed(1) + 'K';
    return vol.toString();
  };

  const getDirection = (change: number): 'up' | 'down' | 'flat' => {
    if (change > 0.00001) return 'up';
    if (change < -0.00001) return 'down';
    return 'flat';
  };

  const updateRows = useCallback(() => {
    const timeframesToShow = showMultipleTimeframes ? TIMEFRAMES : [selectedTf];

    const newRows: OHLCRow[] = timeframesToShow.map(tf => {
      const candles = candleAggregationService.getCandles(symbol, tf, true);
      const lastCandle = candles[candles.length - 1];
      const prevCandle = candles.length > 1 ? candles[candles.length - 2] : null;

      if (!lastCandle) {
        return {
          timeframe: tf,
          open: 0, high: 0, low: 0, close: 0, volume: 0,
          change: 0, changePercent: 0, direction: 'flat', isComplete: false
        };
      }

      const change = prevCandle ? lastCandle.close - prevCandle.close : 0;
      const changePercent = prevCandle ? (change / prevCandle.close) * 100 : 0;

      return {
        timeframe: tf,
        open: lastCandle.open,
        high: lastCandle.high,
        low: lastCandle.low,
        close: lastCandle.close,
        volume: lastCandle.volume,
        change,
        changePercent,
        direction: getDirection(change),
        isComplete: lastCandle.isComplete || false
      };
    });

    setRows(newRows);
    setLastUpdate(new Date());
  }, [symbol, selectedTf, showMultipleTimeframes]);

  // Subscribe to updates
  useEffect(() => {
    updateRows();

    const interval = setInterval(updateRows, 500); // Update every 500ms
    return () => clearInterval(interval);
  }, [updateRows]);

  const getDirectionColor = (direction: 'up' | 'down' | 'flat') => {
    switch (direction) {
      case 'up': return 'text-green-400';
      case 'down': return 'text-red-400';
      default: return 'text-gray-400';
    }
  };

  const getChangeSymbol = (direction: 'up' | 'down' | 'flat') => {
    switch (direction) {
      case 'up': return 'Γû▓';
      case 'down': return 'Γû╝';
      default: return 'ΓêÆ';
    }
  };

  return (
    <div className={`bg-zinc-900 border border-zinc-700 rounded ${className}`}>
      {/* Header */}
      <div className="bg-zinc-800 px-3 py-2 border-b border-zinc-700 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <span className="font-bold text-white">{symbol}</span>
          {!showMultipleTimeframes && (
            <select
              value={selectedTf}
              onChange={(e) => setSelectedTf(e.target.value as Timeframe)}
              className="bg-zinc-700 text-white text-xs px-2 py-1 rounded border border-zinc-600"
            >
              {TIMEFRAMES.map(tf => (
                <option key={tf} value={tf}>{tf}</option>
              ))}
            </select>
          )}
        </div>
        <div className="text-xs text-zinc-500">
          {lastUpdate.toLocaleTimeString()}
        </div>
      </div>

      {/* OHLC Grid */}
      <div className="overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="bg-zinc-800 text-zinc-400">
              <th className="px-2 py-1.5 text-left font-medium">TF</th>
              <th className="px-2 py-1.5 text-right font-medium">Open</th>
              <th className="px-2 py-1.5 text-right font-medium">High</th>
              <th className="px-2 py-1.5 text-right font-medium">Low</th>
              <th className="px-2 py-1.5 text-right font-medium">Close</th>
              <th className="px-2 py-1.5 text-right font-medium">Volume</th>
              <th className="px-2 py-1.5 text-right font-medium">Change</th>
              <th className="px-2 py-1.5 text-center font-medium">Status</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row, idx) => (
              <tr
                key={row.timeframe}
                className={`border-t border-zinc-800 hover:bg-zinc-800/50 transition-colors ${
                  row.timeframe === selectedTf ? 'bg-zinc-800/30' : ''
                }`}
              >
                <td className="px-2 py-1.5 text-zinc-300 font-medium">
                  {row.timeframe}
                </td>
                <td className="px-2 py-1.5 text-right text-zinc-300">
                  {formatPrice(row.open)}
                </td>
                <td className="px-2 py-1.5 text-right text-zinc-300">
                  {formatPrice(row.high)}
                </td>
                <td className="px-2 py-1.5 text-right text-zinc-300">
                  {formatPrice(row.low)}
                </td>
                <td className={`px-2 py-1.5 text-right font-medium ${getDirectionColor(row.direction)}`}>
                  {formatPrice(row.close)}
                </td>
                <td className="px-2 py-1.5 text-right text-zinc-500">
                  {formatVolume(row.volume)}
                </td>
                <td className={`px-2 py-1.5 text-right ${getDirectionColor(row.direction)}`}>
                  <span className="mr-1">{getChangeSymbol(row.direction)}</span>
                  {row.change >= 0 ? '+' : ''}{formatPrice(row.change)}
                  <span className="text-zinc-500 ml-1">
                    ({row.changePercent >= 0 ? '+' : ''}{row.changePercent.toFixed(2)}%)
                  </span>
                </td>
                <td className="px-2 py-1.5 text-center">
                  <span className={`inline-block w-2 h-2 rounded-full ${
                    row.isComplete ? 'bg-green-500' : 'bg-yellow-500 animate-pulse'
                  }`} title={row.isComplete ? 'Complete' : 'Forming...'} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Summary Bar */}
      {rows.length > 0 && (
        <div className="bg-zinc-800 px-3 py-2 border-t border-zinc-700 text-xs">
          <div className="flex justify-between items-center">
            <div className="text-zinc-400">
              Spread: <span className="text-zinc-200">
                {formatPrice(Math.max(...rows.map(r => r.high)) - Math.min(...rows.map(r => r.low)))}
              </span>
            </div>
            <div className="text-zinc-400">
              Range: <span className="text-zinc-200">
                {formatPrice(Math.min(...rows.map(r => r.low)))} - {formatPrice(Math.max(...rows.map(r => r.high)))}
              </span>
            </div>
            <div className="text-zinc-500">
              {rows.filter(r => !r.isComplete).length} forming
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default OHLCTerminalView;

/**
 * One-Click Trading Panel
 * Compact overlay for instant market order execution
 * Shows bid/ask prices with quick buy/sell buttons
 */

import { Icon } from './ui/Icon';
import { useState, useEffect, useCallback } from 'react';
import { api } from '../services/api';
import { useTradeSettings } from '../store/useSettingsStore';
import { useLastSymbolStore } from '../store/useLastSymbolStore';

interface OneClickPanelProps {
  symbol: string;
  currentBid: number;
  currentAsk: number;
  accountId: number;
  onClose: () => void;
  onOrderPlaced?: () => void;
}

const DISCLAIMER_KEY = 'oneClickTradingAccepted';

export function OneClickPanel({
  symbol,
  currentBid,
  currentAsk,
  accountId,
  onClose,
  onOrderPlaced,
}: OneClickPanelProps) {
  const tradeSettings = useTradeSettings();
  const [volume, setVolume] = useState(tradeSettings.defaultVolume);
  const [isPlacing, setIsPlacing] = useState(false);
  const [showDisclaimer, setShowDisclaimer] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Check if user has accepted disclaimer
  useEffect(() => {
    const accepted = localStorage.getItem(DISCLAIMER_KEY);
    if (!accepted) {
      setShowDisclaimer(true);
    }
  }, []);

  const handleAcceptDisclaimer = () => {
    localStorage.setItem(DISCLAIMER_KEY, 'true');
    setShowDisclaimer(false);
  };

  const handleDeclineDisclaimer = () => {
    onClose();
  };

  const incrementVolume = () => {
    setVolume((prev) => {
      const newVol = prev + 0.01;
      return Math.round(newVol * 100) / 100; // Round to 2 decimals
    });
  };

  const decrementVolume = () => {
    setVolume((prev) => {
      const newVol = Math.max(0.01, prev - 0.01);
      return Math.round(newVol * 100) / 100;
    });
  };

  const placeOrder = useCallback(
    async (side: 'BUY' | 'SELL') => {
      if (isPlacing || volume <= 0) return;

      setError(null);
      setIsPlacing(true);

      try {
        // Get default SL/TP from user settings if configured
        const defaultSL = localStorage.getItem('defaultStopLoss');
        const defaultTP = localStorage.getItem('defaultTakeProfit');

        const orderData: any = {
          accountId,
          symbol,
          side,
          volume,
        };

        // Apply default SL/TP if configured
        if (defaultSL) {
          const slPips = parseFloat(defaultSL);
          if (!isNaN(slPips) && slPips > 0) {
            const pipSize = symbol.includes('JPY') ? 0.01 : 0.0001;
            orderData.sl = side === 'BUY'
              ? currentBid - (slPips * pipSize)
              : currentAsk + (slPips * pipSize);
          }
        }

        if (defaultTP) {
          const tpPips = parseFloat(defaultTP);
          if (!isNaN(tpPips) && tpPips > 0) {
            const pipSize = symbol.includes('JPY') ? 0.01 : 0.0001;
            orderData.tp = side === 'BUY'
              ? currentAsk + (tpPips * pipSize)
              : currentBid - (tpPips * pipSize);
          }
        }

        await api.orders.placeMarketOrder(orderData);

        // Track last traded symbol
        useLastSymbolStore.getState().setLastSymbol(symbol, side);

        // Notify parent
        onOrderPlaced?.();
      } catch (err: any) {
        console.error('One-click order failed:', err);
        setError(err.message || 'Order failed');
        // Clear error after 3 seconds
        setTimeout(() => setError(null), 3000);
      } finally {
        setIsPlacing(false);
      }
    },
    [accountId, symbol, volume, currentBid, currentAsk, onOrderPlaced, isPlacing]
  );

  const spread = currentAsk - currentBid;
  const spreadPips = symbol.includes('JPY') ? spread * 100 : spread * 10000;

  // Disclaimer modal
  if (showDisclaimer) {
    return (
      <div className="absolute top-16 left-4 z-50 w-80 bg-zinc-900/95 backdrop-blur-sm border border-red-500/30 rounded-lg shadow-2xl p-4">
        <div className="flex items-start gap-3 mb-4">
          <Icon name="alert-triangle" size="sm" className="w-6 h-6 text-red-500 flex-shrink-0 mt-0.5" />
          <div>
            <h3 className="text-sm font-bold text-red-400 mb-2">One-Click Trading Warning</h3>
            <p className="text-xs text-zinc-300 leading-relaxed">
              One-Click Trading executes orders <span className="font-bold text-red-400">immediately without confirmation</span>.
              Orders will be placed at market price as soon as you click BUY or SELL.
            </p>
            <p className="text-xs text-zinc-400 mt-2">
              This feature is for experienced traders only. Ensure you understand the risks before enabling.
            </p>
          </div>
        </div>

        <div className="flex gap-2">
          <button
            onClick={handleDeclineDisclaimer}
            className="flex-1 px-3 py-2 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 text-xs font-medium rounded transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={handleAcceptDisclaimer}
            className="flex-1 px-3 py-2 bg-red-600 hover:bg-red-700 text-white text-xs font-bold rounded transition-colors"
          >
            I Understand, Enable
          </button>
        </div>
      </div>
    );
  }

  // Main panel
  return (
    <div className="absolute top-16 left-4 z-40 w-52 bg-zinc-900/90 backdrop-blur-sm border border-zinc-700 rounded-lg shadow-xl pointer-events-auto">
      {/* Header */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-zinc-800">
        <span className="text-xs font-bold text-zinc-300">One-Click</span>
        <button
          onClick={onClose}
          className="text-zinc-500 hover:text-zinc-300 transition-colors"
          title="Close (Ctrl+Shift+T)"
        >
          <Icon name="x-close" size="sm" />
        </button>
      </div>

      {/* Error Display */}
      {error && (
        <div className="mx-3 mt-2 px-2 py-1.5 bg-red-500/10 border border-red-500/20 rounded text-xs text-red-400 flex items-center gap-1">
          <Icon name="alert-triangle" size="xs" />
          <span>{error}</span>
        </div>
      )}

      {/* Price Display */}
      <div className="px-3 py-2 space-y-1">
        <div className="flex items-center justify-between text-xs">
          <span className="text-zinc-500">Symbol:</span>
          <span className="font-mono font-bold text-zinc-200">{symbol}</span>
        </div>
        <div className="flex items-center justify-between text-xs">
          <span className="text-zinc-500">Spread:</span>
          <span className="font-mono text-zinc-400">{spreadPips.toFixed(1)} pips</span>
        </div>
      </div>

      {/* Volume Controls */}
      <div className="px-3 pb-2">
        <div className="flex items-center gap-2">
          <button
            onClick={decrementVolume}
            disabled={volume <= 0.01 || isPlacing}
            className="w-7 h-7 flex items-center justify-center bg-zinc-800 hover:bg-zinc-700 disabled:bg-zinc-800/50 disabled:cursor-not-allowed text-zinc-300 rounded transition-colors"
          >
            <Icon name="minus" size="sm" />
          </button>
          <input
            type="number"
            step={0.01}
            min={0.01}
            value={volume}
            onChange={(e) => {
              const val = parseFloat(e.target.value);
              if (!isNaN(val) && val >= 0.01) {
                setVolume(Math.round(val * 100) / 100);
              }
            }}
            disabled={isPlacing}
            className="flex-1 px-2 py-1 bg-zinc-800 border border-zinc-700 rounded text-center text-xs font-mono text-zinc-200 focus:outline-none focus:border-emerald-500/50 disabled:opacity-50"
          />
          <button
            onClick={incrementVolume}
            disabled={isPlacing}
            className="w-7 h-7 flex items-center justify-center bg-zinc-800 hover:bg-zinc-700 disabled:bg-zinc-800/50 disabled:cursor-not-allowed text-zinc-300 rounded transition-colors"
          >
            <Icon name="plus" size="sm" />
          </button>
        </div>
        <div className="text-xs text-zinc-500 text-center mt-1">Lots</div>
      </div>

      {/* Order Buttons */}
      <div className="grid grid-cols-2 gap-2 px-3 pb-3">
        {/* SELL Button */}
        <button
          onClick={() => placeOrder('SELL')}
          disabled={isPlacing || volume <= 0}
          className="flex flex-col items-center justify-center px-2 py-2 bg-red-600/20 hover:bg-red-600/30 border border-red-500/30 hover:border-red-500/50 disabled:bg-red-600/10 disabled:border-red-500/20 disabled:cursor-not-allowed text-white rounded transition-all group"
        >
          <Icon name="trending-down" size="sm" className="mb-0.5 group-hover:scale-110 transition-transform" />
          <span className="text-xs font-bold">SELL</span>
          <span className="text-xs font-mono mt-0.5 opacity-90">{currentBid.toFixed(5)}</span>
        </button>

        {/* BUY Button */}
        <button
          onClick={() => placeOrder('BUY')}
          disabled={isPlacing || volume <= 0}
          className="flex flex-col items-center justify-center px-2 py-2 bg-blue-600/20 hover:bg-blue-600/30 border border-zinc-600/30 hover:border-zinc-600/50 disabled:bg-blue-600/10 disabled:border-zinc-600/20 disabled:cursor-not-allowed text-white rounded transition-all group"
        >
          <Icon name="trending-up" size="sm" className="mb-0.5 group-hover:scale-110 transition-transform" />
          <span className="text-xs font-bold">BUY</span>
          <span className="text-xs font-mono mt-0.5 opacity-90">{currentAsk.toFixed(5)}</span>
        </button>
      </div>

      {/* Status Indicator */}
      {isPlacing && (
        <div className="px-3 pb-2 text-center">
          <div className="text-xs text-emerald-400 font-medium animate-pulse">
            Placing order...
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * MT5-Style One-Click Trading Panel
 * Premium compact overlay ΓÇö exact MT5 replica with Red SELL / Blue BUY
 * Toggled by Alt+T, sits on top-left of chart
 */

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { useAppStore } from '../store/useAppStore';
import { useMT5Store } from '../store/useMT5Store';
import { useLastSymbolStore } from '../store/useLastSymbolStore';

interface OneClickTradingProps {
    symbol: string;
    visible: boolean;
    timeframe: string;
}

export const OneClickTrading: React.FC<OneClickTradingProps> = ({ symbol, visible, timeframe }) => {
    const [volume, setVolume] = useState(0.01);
    const [isPlacing, setIsPlacing] = useState(false);
    const [flashSide, setFlashSide] = useState<'buy' | 'sell' | null>(null);
    const prevBidRef = useRef<number>(0);
    const prevAskRef = useRef<number>(0);

    // Subscribe to live tick data for this symbol
    const tick = useAppStore((s) => s.ticks[symbol]);
    const bid = tick?.bid || 0;
    const ask = tick?.ask || 0;

    // Track price direction for color flash
    const [bidFlash, setBidFlash] = useState<'up' | 'down' | ''>('');
    const [askFlash, setAskFlash] = useState<'up' | 'down' | ''>('');

    useEffect(() => {
        if (prevBidRef.current && bid !== prevBidRef.current) {
            setBidFlash(bid > prevBidRef.current ? 'up' : 'down');
            const t = setTimeout(() => setBidFlash(''), 350);
            prevBidRef.current = bid;
            return () => clearTimeout(t);
        }
        prevBidRef.current = bid;
    }, [bid]);

    useEffect(() => {
        if (prevAskRef.current && ask !== prevAskRef.current) {
            setAskFlash(ask > prevAskRef.current ? 'up' : 'down');
            const t = setTimeout(() => setAskFlash(''), 350);
            prevAskRef.current = ask;
            return () => clearTimeout(t);
        }
        prevAskRef.current = ask;
    }, [ask]);

    // Determine decimal digits
    const getDigits = useCallback((sym: string): number => {
        if (sym.includes('JPY')) return 3;
        if (sym.includes('XAU') || sym.includes('XAG')) return 2;
        if (sym.includes('BTC') || sym.includes('ETH') || sym.includes('SOL') || sym.includes('LTC') || sym.includes('XRP')) return 2;
        return 5;
    }, []);

    const digits = getDigits(symbol);

    // Format price: split into small prefix, LARGE last-2-decimal digits, no superscript pipette
    const formatPrice = useCallback((price: number, d: number) => {
        if (price <= 0) return { small: '0', big: '00', pip: '' };
        const full = price.toFixed(d);
        if (d <= 2) {
            // Crypto/metals: integer small, last 2 decimal digits big
            const [int, dec] = full.split('.');
            return { small: int, big: (dec || '00').slice(-2).padStart(2, '0'), pip: '' };
        }
        // Forex: e.g. 1.33601 ΓåÆ small="1.336", big="01" (last 2 decimals), pip=""
        const [intPart, decPart] = full.split('.');
        const dec = decPart || '00000';
        const small = intPart + '.' + dec.slice(0, -2);
        const big = dec.slice(-2);   // last 2 decimal digits together
        const pip = '';
        return { small, big, pip };
    }, []);

    const getAccountLogin = useCallback((): number => {
        const saved = localStorage.getItem('rtx_saved_username') || localStorage.getItem('rtx_last_login');
        return saved ? parseInt(saved, 10) || 0 : 0;
    }, []);

    const isVolumeValid = volume > 0;

    const placeOrder = useCallback(async (side: 'buy' | 'sell') => {
        if (isPlacing || !isVolumeValid || bid <= 0) return;
        setIsPlacing(true);
        setFlashSide(side);

        try {
            const login = getAccountLogin();
            await useMT5Store.getState().submitOrder({
                action: side.toUpperCase() as 'BUY' | 'SELL',
                symbol,
                volume,
                login,
            });
            useLastSymbolStore.getState().setLastSymbol(symbol, side.toUpperCase() as 'BUY' | 'SELL');
        } catch (err: any) {
            console.error('[OneClick] Trade failed:', err);
        } finally {
            setIsPlacing(false);
            setTimeout(() => setFlashSide(null), 500);
        }
    }, [isPlacing, isVolumeValid, volume, bid, symbol, getAccountLogin]);

    if (!visible || !symbol) return null;

    const bidPrice = formatPrice(bid, digits);
    const askPrice = formatPrice(ask, digits);

    // Symbol description for header
    const descriptions: Record<string, string> = {
        'BTCUSD': 'Bitcoin vs US Dollar',
        'ETHUSD': 'Ethereum vs US Dollar',
        'XAUUSD': 'Gold vs US Dollar',
        'EURUSD': 'Euro vs US Dollar',
        'GBPUSD': 'Pound vs US Dollar',
        'USDJPY': 'Dollar vs Japanese Yen',
        'AUDUSD': 'Australian Dollar vs USD',
        'NZDUSD': 'New Zealand Dollar vs USD',
        'USDCAD': 'US Dollar vs Canadian Dollar',
        'USDCHF': 'US Dollar vs Swiss Franc',
        'XAGUSD': 'Silver vs US Dollar',
        'SOLUSD': 'Solana vs US Dollar',
        'LTCUSD': 'Litecoin vs US Dollar',
        'XRPUSD': 'Ripple vs US Dollar',
    };
    const desc = descriptions[symbol] || symbol;

    return (
        <div
            className="absolute top-[6px] left-[6px] z-30 select-none"
            style={{ pointerEvents: 'auto', fontFamily: "'Segoe UI', Tahoma, sans-serif", display: 'inline-block', width: 'fit-content' }}
        >
            {/* ΓöÇΓöÇΓöÇ Header: Symbol + Timeframe ΓöÇΓöÇΓöÇ */}
            <div
                style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px',
                    padding: '3px 10px',
                    background: 'rgba(20, 24, 33, 0.92)',
                    backdropFilter: 'blur(8px)',
                    borderRadius: '4px 4px 0 0',
                    border: '1px solid rgba(255,255,255,0.07)',
                    borderBottom: 'none',
                    borderLeft: '3px solid #8a8a8f',
                }}
            >
                <span style={{ fontSize: 11, fontWeight: 700, color: '#e2e2e8', letterSpacing: '0.4px' }}>
                    {symbol}, {timeframe}:
                </span>
                <span style={{ fontSize: 10, color: '#8a8a8f', maxWidth: 130, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {desc}
                </span>
            </div>

            {/* ΓöÇΓöÇΓöÇ Main Body: SELL | Volume | BUY ΓöÇΓöÇΓöÇ */}
            <div
                style={{
                    display: 'flex',
                    border: '1px solid rgba(255,255,255,0.07)',
                    borderRadius: '0 0 4px 4px',
                    overflow: 'hidden',
                    boxShadow: '0 8px 32px rgba(0,0,0,0.6), 0 0 0 1px rgba(59,130,246,0.08)',
                }}
            >
                {/* ΓöÇΓöÇ BUY Button ΓöÇΓöÇ */}
                <button
                    onClick={() => placeOrder('buy')}
                    disabled={isPlacing || !isVolumeValid}
                    style={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'center',
                        padding: '4px 6px',
                        width: 80,
                        flex: 1,
                        alignSelf: 'stretch',
                        border: 'none',
                        cursor: isPlacing || !isVolumeValid ? 'not-allowed' : 'pointer',
                        position: 'relative',
                        opacity: !isVolumeValid ? 0.5 : 1,
                        background: flashSide === 'buy'
                            ? 'linear-gradient(180deg, #1e3a5f 0%, #1e3a8a 100%)'
                            : 'linear-gradient(180deg, #2563eb 0%, #1d4ed8 50%, #1e40af 100%)',
                        transition: 'background 0.2s, opacity 0.2s',
                    }}
                    onMouseEnter={(e) => { if (!flashSide) e.currentTarget.style.background = 'linear-gradient(180deg, #2a6fd4 0%, #1e54a8 50%, #1a448a 100%)'; }}
                    onMouseLeave={(e) => { if (!flashSide) e.currentTarget.style.background = 'linear-gradient(180deg, #2563eb 0%, #1d4ed8 50%, #1e40af 100%)'; }}
                >
                    <span style={{ fontSize: 10, fontWeight: 800, color: 'rgba(255,255,255,0.7)', letterSpacing: '1px', textTransform: 'uppercase' }}>
                        BUY
                    </span>
                    <div style={{ display: 'flex', alignItems: 'baseline', lineHeight: 1, marginTop: 1 }}>
                        <span style={{
                            fontSize: 12, fontFamily: 'monospace', fontWeight: 500, color: '#fff',
                            textShadow: askFlash === 'up' ? '0 0 8px #6b9fff' : askFlash === 'down' ? '0 0 8px #ff6b6b' : 'none',
                        }}>
                            {askPrice.small}
                        </span>
                        <span style={{
                            fontSize: 28, fontFamily: 'monospace', fontWeight: 900, color: '#fff', lineHeight: 0.85,
                            textShadow: askFlash === 'up' ? '0 0 12px #6b9fff' : askFlash === 'down' ? '0 0 12px #ff6b6b' : '0 1px 3px rgba(0,0,0,0.5)',
                        }}>
                            {askPrice.big}
                        </span>
                        {askPrice.pip && (
                            <span style={{
                                fontSize: 14, fontFamily: 'monospace', fontWeight: 700, color: '#fff',
                                position: 'relative', top: -8,
                                textShadow: askFlash === 'up' ? '0 0 8px #6b9fff' : askFlash === 'down' ? '0 0 8px #ff6b6b' : 'none',
                            }}>
                                {askPrice.pip}
                            </span>
                        )}
                    </div>
                </button>

                {/* ΓöÇΓöÇ Volume Control (Center) ΓöÇΓöÇ */}
                <div
                    style={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'center',
                        padding: '3px 4px',
                        minWidth: 48,
                        background: 'linear-gradient(180deg, #1f2937 0%, #111827 100%)',
                        borderLeft: '1px solid #374151',
                        borderRight: '1px solid #374151',
                    }}
                >
                    <button
                        onClick={() => setVolume(v => Math.round((v + 0.01) * 100) / 100)}
                        style={{
                            background: 'none', border: 'none', color: '#8a8a8f', cursor: 'pointer',
                            fontSize: 9, lineHeight: 1, padding: '1px 0',
                        }}
                        onMouseEnter={(e) => e.currentTarget.style.color = '#d1d5db'}
                        onMouseLeave={(e) => e.currentTarget.style.color = '#8a8a8f'}
                    >
                        Γû▓
                    </button>
                    <input
                        type="number"
                        step={0.01}
                        min={0.01}
                        value={volume}
                        onChange={(e) => {
                            const val = parseFloat(e.target.value);
                            if (!isNaN(val) && val >= 0) setVolume(Math.round(val * 100) / 100);
                        }}
                        style={{
                            width: 42, height: 20,
                            background: '#0f172a',
                            border: '1px solid #374151',
                            borderRadius: 2,
                            color: '#fff',
                            fontSize: 11,
                            fontFamily: 'monospace',
                            fontWeight: 700,
                            textAlign: 'center',
                            outline: 'none',
                            padding: 0,
                        }}
                    />
                    <button
                        onClick={() => setVolume(v => Math.max(0.01, Math.round((v - 0.01) * 100) / 100))}
                        style={{
                            background: 'none', border: 'none', color: '#8a8a8f', cursor: 'pointer',
                            fontSize: 9, lineHeight: 1, padding: '1px 0',
                        }}
                        onMouseEnter={(e) => e.currentTarget.style.color = '#d1d5db'}
                        onMouseLeave={(e) => e.currentTarget.style.color = '#8a8a8f'}
                    >
                        Γû╝
                    </button>
                </div>

                {/* ΓöÇΓöÇ SELL Button ΓöÇΓöÇ */}
                <button
                    onClick={() => placeOrder('sell')}
                    disabled={isPlacing || !isVolumeValid}
                    style={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'center',
                        padding: '4px 6px',
                        width: 80,
                        flex: 1,
                        alignSelf: 'stretch',
                        border: 'none',
                        cursor: isPlacing || !isVolumeValid ? 'not-allowed' : 'pointer',
                        position: 'relative',
                        opacity: !isVolumeValid ? 0.5 : 1,
                        background: flashSide === 'sell'
                            ? 'linear-gradient(180deg, #991b1b 0%, #7f1d1d 100%)'
                            : 'linear-gradient(180deg, #dc2626 0%, #b91c1c 50%, #991b1b 100%)',
                        transition: 'background 0.2s, opacity 0.2s',
                    }}
                    onMouseEnter={(e) => { if (!flashSide) e.currentTarget.style.background = 'linear-gradient(180deg, #ef4444 0%, #dc2626 50%, #b91c1c 100%)'; }}
                    onMouseLeave={(e) => { if (!flashSide) e.currentTarget.style.background = 'linear-gradient(180deg, #dc2626 0%, #b91c1c 50%, #991b1b 100%)'; }}
                >
                    <span style={{ fontSize: 10, fontWeight: 800, color: 'rgba(255,255,255,0.7)', letterSpacing: '1px', textTransform: 'uppercase' }}>
                        SELL
                    </span>
                    <div style={{ display: 'flex', alignItems: 'baseline', lineHeight: 1, marginTop: 1 }}>
                        <span style={{
                            fontSize: 12, fontFamily: 'monospace', fontWeight: 500, color: '#fff',
                            textShadow: bidFlash === 'down' ? '0 0 8px #ff6b6b' : bidFlash === 'up' ? '0 0 8px #6bff6b' : 'none',
                        }}>
                            {bidPrice.small}
                        </span>
                        <span style={{
                            fontSize: 28, fontFamily: 'monospace', fontWeight: 900, color: '#fff', lineHeight: 0.85,
                            textShadow: bidFlash === 'down' ? '0 0 12px #ff6b6b' : bidFlash === 'up' ? '0 0 12px #6bff6b' : '0 1px 3px rgba(0,0,0,0.5)',
                        }}>
                            {bidPrice.big}
                        </span>
                        {bidPrice.pip && (
                            <span style={{
                                fontSize: 14, fontFamily: 'monospace', fontWeight: 700, color: '#fff',
                                position: 'relative', top: -8,
                                textShadow: bidFlash === 'down' ? '0 0 8px #ff6b6b' : bidFlash === 'up' ? '0 0 8px #6bff6b' : 'none',
                            }}>
                                {bidPrice.pip}
                            </span>
                        )}
                    </div>
                </button>
            </div>

            {/* Invalid volume warning */}
            {!isVolumeValid && (
                <div style={{
                    fontSize: 10,
                    color: '#f87171',
                    textAlign: 'center',
                    padding: '3px 8px',
                    background: 'rgba(127, 29, 29, 0.6)',
                    borderRadius: '0 0 3px 3px',
                    border: '1px solid #7f1d1d',
                    borderTop: 'none',
                }}>
                    ΓÜá Invalid volume (min 0.01)
                </div>
            )}
        </div>
    );
};

/**
 * Live Order Book Component
 * Displays real-time bid/ask depth with aggregation levels
 */

import { Icon } from './ui/Icon';
import { useState, useEffect, useMemo } from 'react';
import { buildApiUrl } from '../config/api';

type OrderBookEntry = {
  price: number;
  volume: number;
  total: number;
};

type OrderBookData = {
  symbol: string;
  bids: OrderBookEntry[];
  asks: OrderBookEntry[];
  spread: number;
  spreadPips: number;
  timestamp: number;
};

type OrderBookProps = {
  symbol: string;
  currentBid?: number;
  currentAsk?: number;
};

export const OrderBook = ({ symbol, currentBid = 0, currentAsk = 0 }: OrderBookProps) => {
  const [orderBook, setOrderBook] = useState<OrderBookData | null>(null);
  const [depth, setDepth] = useState<10 | 20 | 50>(20);
  const [loading, setLoading] = useState(false);

  // Fetch order book data
  useEffect(() => {
    if (!symbol) return;

    const fetchOrderBook = async () => {
      setLoading(true);
      try {
        const response = await fetch(
          buildApiUrl(`/api/orderbook?symbol=${symbol}&depth=${depth}`)
        );

        if (response.ok) {
          const data = await response.json();
          setOrderBook(data);
        } else {
          // TODO: API endpoint not available - no fallback data
          setOrderBook(null);
        }
      } catch (error) {
        console.error('Failed to fetch order book:', error);
        // TODO: API call failed - no fallback data
        setOrderBook(null);
      } finally {
        setLoading(false);
      }
    };

    fetchOrderBook();
    const interval = setInterval(fetchOrderBook, 1000); // Update every second

    return () => clearInterval(interval);
  }, [symbol, depth, currentBid, currentAsk]);

  // Calculate max volume for bar chart sizing
  const maxVolume = useMemo(() => {
    if (!orderBook) return 0;
    const allVolumes = [...orderBook.bids, ...orderBook.asks].map((entry) => entry.volume);
    return Math.max(...allVolumes, 0);
  }, [orderBook]);

  const formatPrice = (price: number) => {
    if (symbol.includes('JPY')) {
      return price.toFixed(3);
    }
    return price.toFixed(5);
  };

  const formatVolume = (volume: number) => {
    if (volume >= 1000) {
      return `${(volume / 1000).toFixed(1)}K`;
    }
    return volume.toFixed(2);
  };

  if (loading && !orderBook) {
    return (
      <div className="flex items-center justify-center h-full text-zinc-500">
        <Icon name="layers" size="sm" className="w-6 h-6 animate-pulse" />
        <span className="ml-2">Loading order book...</span>
      </div>
    );
  }

  if (!orderBook) {
    return (
      <div className="flex items-center justify-center h-full text-zinc-500">
        <p>No order book data available</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-zinc-900">
      {/* Header */}
      <div className="flex items-center justify-between p-3 border-b border-zinc-800">
        <div>
          <h3 className="text-sm font-semibold text-white">Order Book</h3>
          <p className="text-xs text-zinc-500">{symbol}</p>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs text-zinc-500">Depth:</span>
          <select
            value={depth}
            onChange={(e) => setDepth(Number(e.target.value) as 10 | 20 | 50)}
            className="px-2 py-1 text-xs bg-zinc-800 border border-zinc-700 rounded text-zinc-300 focus:outline-none focus:border-emerald-500"
          >
            <option value={10}>10</option>
            <option value={20}>20</option>
            <option value={50}>50</option>
          </select>
        </div>
      </div>

      {/* Spread Info */}
      <div className="flex items-center justify-between p-2 bg-zinc-800/50 border-b border-zinc-800 text-xs">
        <div className="flex items-center gap-2">
          <span className="text-zinc-500">Spread:</span>
          <span className="font-mono text-zinc-300">{formatPrice(orderBook.spread)}</span>
          <span className="text-zinc-500">({orderBook.spreadPips.toFixed(1)} pips)</span>
        </div>
        <div className="text-zinc-500">
          {new Date(orderBook.timestamp).toLocaleTimeString()}
        </div>
      </div>

      {/* Column Headers */}
      <div className="grid grid-cols-3 gap-2 px-3 py-2 border-b border-zinc-800 text-xs text-zinc-500 font-medium">
        <div className="text-left">Price</div>
        <div className="text-right">Volume</div>
        <div className="text-right">Total</div>
      </div>

      {/* Order Book Content */}
      <div className="flex-1 overflow-auto">
        {/* Asks (Sell Orders) - Reversed to show highest first */}
        <div className="border-b-2 border-red-500/20">
          {[...orderBook.asks].reverse().map((ask, index) => (
            <OrderBookRow
              key={`ask-${index}`}
              price={ask.price}
              volume={ask.volume}
              total={ask.total}
              maxVolume={maxVolume}
              side="ask"
              formatPrice={formatPrice}
              formatVolume={formatVolume}
            />
          ))}
        </div>

        {/* Current Market Price */}
        <div className="sticky top-0 z-10 bg-zinc-900 border-y border-zinc-700">
          <div className="flex items-center justify-between px-3 py-2">
            <div className="flex items-center gap-2">
              <Icon name="trending-down" size="sm" className="w-4 h-4 text-red-400" />
              <span className="text-sm font-mono font-bold text-red-400">
                {formatPrice(currentBid)}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-sm font-mono font-bold text-emerald-400">
                {formatPrice(currentAsk)}
              </span>
              <Icon name="trending-up" size="sm" className="w-4 h-4 text-emerald-400" />
            </div>
          </div>
        </div>

        {/* Bids (Buy Orders) */}
        <div className="border-t-2 border-emerald-500/20">
          {orderBook.bids.map((bid, index) => (
            <OrderBookRow
              key={`bid-${index}`}
              price={bid.price}
              volume={bid.volume}
              total={bid.total}
              maxVolume={maxVolume}
              side="bid"
              formatPrice={formatPrice}
              formatVolume={formatVolume}
            />
          ))}
        </div>
      </div>

      {/* Footer Stats */}
      <div className="flex items-center justify-between p-3 border-t border-zinc-800 text-xs">
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1">
            <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
            <span className="text-zinc-500">Bid Total:</span>
            <span className="font-mono text-emerald-400">
              {formatVolume(orderBook.bids.reduce((sum, b) => sum + b.volume, 0))}
            </span>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1">
            <div className="w-2 h-2 rounded-full bg-red-500"></div>
            <span className="text-zinc-500">Ask Total:</span>
            <span className="font-mono text-red-400">
              {formatVolume(orderBook.asks.reduce((sum, a) => sum + a.volume, 0))}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

type OrderBookRowProps = {
  price: number;
  volume: number;
  total: number;
  maxVolume: number;
  side: 'bid' | 'ask';
  formatPrice: (price: number) => string;
  formatVolume: (volume: number) => string;
};

const OrderBookRow = ({
  price,
  volume,
  total,
  maxVolume,
  side,
  formatPrice,
  formatVolume,
}: OrderBookRowProps) => {
  const percentage = maxVolume > 0 ? (volume / maxVolume) * 100 : 0;
  const bgColor = side === 'bid' ? 'bg-emerald-500/10' : 'bg-red-500/10';
  const textColor = side === 'bid' ? 'text-emerald-400' : 'text-red-400';

  return (
    <div className="relative group hover:bg-zinc-800/50 transition-colors">
      {/* Volume bar background */}
      <div
        className={`absolute right-0 top-0 h-full ${bgColor} transition-all duration-300`}
        style={{ width: `${percentage}%` }}
      />

      {/* Content */}
      <div className="relative grid grid-cols-3 gap-2 px-3 py-1.5 text-xs">
        <div className={`font-mono ${textColor}`}>{formatPrice(price)}</div>
        <div className="text-right font-mono text-zinc-300">{formatVolume(volume)}</div>
        <div className="text-right font-mono text-zinc-500">{formatVolume(total)}</div>
      </div>
    </div>
  );
};

