/**
 * Order Entry / Trade Ticket
 * Professional MT5-style order placement form
 */

import { Icon } from './ui/Icon';
import { useState, useEffect, useMemo } from 'react';
import { useTradeSettings } from '../store/useSettingsStore';
import { useAppStore } from '../store/useAppStore';
import { Calculator } from 'lucide-react';
import { useLastSymbolStore } from '../store/useLastSymbolStore';
import api from '../services/api';

interface OrderEntryProps {
  symbol: string;
  onClose: () => void;
  onOrderPlaced?: () => void;
}

type OrderType =
  | 'Market'
  | 'Buy Limit'
  | 'Sell Limit'
  | 'Buy Stop'
  | 'Sell Stop'
  | 'Buy Stop Limit'
  | 'Sell Stop Limit';

type ExpiryType = 'GTC' | 'Today' | 'Specified';

type PipsMode = 'price' | 'pips';

const LOT_PRESETS = [0.01, 0.1, 0.5, 1.0, 5.0, 10.0];

export default function OrderEntry({ symbol, onClose, onOrderPlaced }: OrderEntryProps) {
  const tradeSettings = useTradeSettings();
  const { ticks, account } = useAppStore();

  // Current prices from ticks
  const currentTick = ticks[symbol];
  const currentBid = currentTick?.bid || 0;
  const currentAsk = currentTick?.ask || 0;

  // Order parameters
  const [orderType, setOrderType] = useState<OrderType>('Market');
  const [volume, setVolume] = useState(tradeSettings.defaultVolume);
  const [price, setPrice] = useState('');
  const [stopLoss, setStopLoss] = useState('');
  const [takeProfit, setTakeProfit] = useState('');
  const [slMode, setSlMode] = useState<PipsMode>('price');
  const [tpMode, setTpMode] = useState<PipsMode>('price');
  const [expiry, setExpiry] = useState<ExpiryType>('GTC');
  const [expiryDate, setExpiryDate] = useState('');
  const [expiryTime, setExpiryTime] = useState('23:59');
  const [comment, setComment] = useState('');

  // UI state
  const [isPlacing, setIsPlacing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Determine if JPY pair (different pip size)
  const isJPY = symbol.includes('JPY');
  const pipSize = isJPY ? 0.01 : 0.0001;
  const pipMultiplier = isJPY ? 100 : 10000;

  // Check if order type is pending
  const isPendingOrder = orderType !== 'Market';

  // Auto-fill price for pending orders
  useEffect(() => {
    if (isPendingOrder && !price) {
      if (orderType.includes('Buy')) {
        setPrice(currentAsk.toFixed(isJPY ? 3 : 5));
      } else {
        setPrice(currentBid.toFixed(isJPY ? 3 : 5));
      }
    }
  }, [orderType, currentBid, currentAsk, isJPY, isPendingOrder, price]);

  // Calculate spread
  const spread = currentAsk - currentBid;
  const spreadPips = spread * pipMultiplier;

  // Convert pips to price
  const pipsToPrice = (pips: number, basePrice: number, direction: 'above' | 'below'): number => {
    const priceChange = pips * pipSize;
    return direction === 'above' ? basePrice + priceChange : basePrice - priceChange;
  };

  // Convert price to pips
  const priceToPips = (priceValue: number, basePrice: number): number => {
    return Math.abs((priceValue - basePrice) / pipSize);
  };

  // Get entry price for calculations
  const entryPrice = useMemo(() => {
    if (orderType === 'Market') {
      return orderType.includes('Buy') ? currentAsk : currentBid;
    }
    return parseFloat(price) || 0;
  }, [orderType, price, currentBid, currentAsk]);

  // Calculate SL price
  const slPrice = useMemo(() => {
    if (!stopLoss) return null;
    const slValue = parseFloat(stopLoss);
    if (isNaN(slValue)) return null;

    if (slMode === 'pips') {
      const isBuy = orderType.includes('Buy');
      return pipsToPrice(slValue, entryPrice, isBuy ? 'below' : 'above');
    }
    return slValue;
  }, [stopLoss, slMode, entryPrice, orderType, pipSize]);

  // Calculate TP price
  const tpPrice = useMemo(() => {
    if (!takeProfit) return null;
    const tpValue = parseFloat(takeProfit);
    if (isNaN(tpValue)) return null;

    if (tpMode === 'pips') {
      const isBuy = orderType.includes('Buy');
      return pipsToPrice(tpValue, entryPrice, isBuy ? 'above' : 'below');
    }
    return tpValue;
  }, [takeProfit, tpMode, entryPrice, orderType, pipSize]);

  // Risk calculator
  const riskCalc = useMemo(() => {
    // Mock values - in production, fetch from account settings
    const leverage = (account as any)?.leverage || 100;
    const accountCurrency = 'USD';
    const contractSize = 100000; // Standard lot

    // Calculate margin required
    const margin = (volume * contractSize * entryPrice) / leverage;

    // Calculate pip value (USD per pip for 1 lot)
    const pipValue = (contractSize * pipSize) * volume;

    // Calculate potential loss/profit
    let potentialLoss = 0;
    let potentialProfit = 0;

    if (slPrice) {
      const slPips = priceToPips(slPrice, entryPrice);
      potentialLoss = slPips * pipValue;
    }

    if (tpPrice) {
      const tpPips = priceToPips(tpPrice, entryPrice);
      potentialProfit = tpPips * pipValue;
    }

    return {
      margin,
      pipValue,
      potentialLoss,
      potentialProfit,
    };
  }, [volume, entryPrice, slPrice, tpPrice, pipSize, account]);

  // Handle volume preset click
  const handleVolumePreset = (preset: number) => {
    setVolume(preset);
  };

  // Get account login from app store (primary) or localStorage (fallback)
  const getAccountLogin = (): number => {
    // Primary: use the accountId from the Zustand store (set during login)
    const storeAccountId = useAppStore.getState().accountId;
    if (storeAccountId) {
      const parsed = parseInt(String(storeAccountId), 10);
      if (!isNaN(parsed) && parsed > 0) return parsed;
    }
    // Fallback: localStorage
    const storedLogin = localStorage.getItem('rtx_last_login') || localStorage.getItem('rtx_saved_username');
    return storedLogin ? parseInt(storedLogin, 10) || 0 : 0;
  };

  // Handle order placement ΓÇö calls MT5 Sync API directly (port 8088)
  const handlePlaceOrder = async (side: 'BUY' | 'SELL') => {
    if (isPlacing) return;

    setError(null);
    setIsPlacing(true);

    try {
      // Validate inputs
      if (volume <= 0) {
        throw new Error('Volume must be greater than 0');
      }

      if (isPendingOrder && !price) {
        throw new Error('Price is required for pending orders');
      }

      const accountLogin = getAccountLogin();
      console.log('[OrderEntry] Placing order:', { symbol, side, volume, accountLogin, isPendingOrder, price });

      // Call MT5 Sync Direct API (port 8088)
      const result = await api.mt5.submitOrder({
        symbol,
        action: side.toLowerCase(),
        volume,
        price: isPendingOrder ? parseFloat(price) : 0,
        sl: slPrice || undefined,
        tp: tpPrice || undefined,
        login: accountLogin,
        comment: comment.trim().slice(0, 64) || 'RTX sync trade',
        client_request_id: `rtx-${Date.now()}`,
      });

      console.log('[OrderEntry] Trade executed via MT5 Sync:', result);

      if (result?.success === false) {
        throw new Error(result.retcode_text || result.message || 'Trade execution failed');
      }

      // Success ΓÇö track last traded symbol
      useLastSymbolStore.getState().setLastSymbol(symbol, side);
      onOrderPlaced?.();
      onClose();
    } catch (err: any) {
      console.error('Order placement failed:', err);
      setError(err.message || 'Failed to place order');
      setTimeout(() => setError(null), 5000);
    } finally {
      setIsPlacing(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
      <div className="bg-[#131316] border border-zinc-700 rounded-lg shadow-2xl w-[480px] max-h-[90vh] overflow-y-auto custom-scrollbar">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 bg-[#252525] border-b border-zinc-700">
          <div className="flex items-center gap-3">
            <h3 className="text-sm font-bold text-zinc-200">New Order</h3>
            <span className="px-2 py-0.5 rounded bg-zinc-700/30 text-blue-400 text-xs font-mono font-bold">
              {symbol}
            </span>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded hover:bg-zinc-700 text-zinc-400"
          >
            <Icon name="x-close" size="md" />
          </button>
        </div>

        {/* Content */}
        <div className="p-4 space-y-4">
          {/* Error Display */}
          {error && (
            <div className="px-3 py-2 bg-rose-500/10 border border-rose-500/20 rounded text-xs text-rose-400 flex items-center gap-2">
              <Icon name="alert-triangle" size="sm" />
              <span>{error}</span>
            </div>
          )}

          {/* Current Prices */}
          <div className="grid grid-cols-2 gap-3">
            <div className="bg-[#252525] border border-zinc-700/50 rounded p-3">
              <div className="text-xs text-zinc-500 mb-1">Bid</div>
              <div className="text-lg font-mono font-bold text-rose-400">
                {currentBid.toFixed(isJPY ? 3 : 5)}
              </div>
            </div>
            <div className="bg-[#252525] border border-zinc-700/50 rounded p-3">
              <div className="text-xs text-zinc-500 mb-1">Ask</div>
              <div className="text-lg font-mono font-bold text-blue-400">
                {currentAsk.toFixed(isJPY ? 3 : 5)}
              </div>
            </div>
          </div>

          <div className="flex items-center justify-between text-xs text-zinc-500">
            <span>Spread:</span>
            <span className="font-mono text-zinc-400">{spreadPips.toFixed(1)} pips</span>
          </div>

          {/* Order Type */}
          <div>
            <label className="block text-xs text-zinc-400 mb-2">Order Type</label>
            <select
              value={orderType}
              onChange={(e) => setOrderType(e.target.value as OrderType)}
              className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-zinc-300 text-sm focus:outline-none focus:border-zinc-600"
            >
              <option value="Market">Market Execution</option>
              <option value="Buy Limit">Buy Limit</option>
              <option value="Sell Limit">Sell Limit</option>
              <option value="Buy Stop">Buy Stop</option>
              <option value="Sell Stop">Sell Stop</option>
              <option value="Buy Stop Limit">Buy Stop Limit</option>
              <option value="Sell Stop Limit">Sell Stop Limit</option>
            </select>
          </div>

          {/* Volume */}
          <div>
            <label className="block text-xs text-zinc-400 mb-2">Volume (Lots)</label>
            <input
              type="number"
              step={0.01}
              min={0.01}
              value={volume}
              onChange={(e) => {
                const val = parseFloat(e.target.value);
                if (!isNaN(val) && val >= 0.01) {
                  setVolume(val);
                }
              }}
              className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-zinc-300 text-sm font-mono focus:outline-none focus:border-zinc-600"
            />
            {/* Lot Presets */}
            <div className="flex flex-wrap gap-2 mt-2">
              {LOT_PRESETS.map((preset) => (
                <button
                  key={preset}
                  onClick={() => handleVolumePreset(preset)}
                  className={`px-2 py-1 rounded text-xs font-medium transition-colors ${volume === preset
                    ? 'bg-zinc-700/30 text-zinc-400 border border-zinc-600/50'
                    : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700 border border-zinc-700'
                    }`}
                >
                  {preset}
                </button>
              ))}
            </div>
          </div>

          {/* Price (for pending orders) */}
          {isPendingOrder && (
            <div>
              <label className="block text-xs text-zinc-400 mb-2">Price</label>
              <input
                type="number"
                step={pipSize}
                value={price}
                onChange={(e) => setPrice(e.target.value)}
                className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-zinc-300 text-sm font-mono focus:outline-none focus:border-zinc-600"
                placeholder={currentAsk.toFixed(isJPY ? 3 : 5)}
              />
            </div>
          )}

          {/* Stop Loss */}
          <div>
            <label className="block text-xs text-zinc-400 mb-2">Stop Loss (Optional)</label>
            <div className="flex gap-2">
              <input
                type="number"
                step={slMode === 'pips' ? 1 : pipSize}
                value={stopLoss}
                onChange={(e) => setStopLoss(e.target.value)}
                className="flex-1 px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-zinc-300 text-sm font-mono focus:outline-none focus:border-zinc-600"
                placeholder={slMode === 'pips' ? 'Pips' : 'Price'}
              />
              <button
                onClick={() => setSlMode(slMode === 'price' ? 'pips' : 'price')}
                className="px-3 py-2 bg-zinc-800 hover:bg-zinc-700 border border-zinc-700 rounded text-xs text-zinc-300 font-medium whitespace-nowrap"
              >
                {slMode === 'price' ? 'Price' : 'Pips'}
              </button>
            </div>
            {slPrice && slMode === 'pips' && (
              <div className="text-xs text-zinc-500 mt-1">
                = {slPrice.toFixed(isJPY ? 3 : 5)}
              </div>
            )}
          </div>

          {/* Take Profit */}
          <div>
            <label className="block text-xs text-zinc-400 mb-2">Take Profit (Optional)</label>
            <div className="flex gap-2">
              <input
                type="number"
                step={tpMode === 'pips' ? 1 : pipSize}
                value={takeProfit}
                onChange={(e) => setTakeProfit(e.target.value)}
                className="flex-1 px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-zinc-300 text-sm font-mono focus:outline-none focus:border-zinc-600"
                placeholder={tpMode === 'pips' ? 'Pips' : 'Price'}
              />
              <button
                onClick={() => setTpMode(tpMode === 'price' ? 'pips' : 'price')}
                className="px-3 py-2 bg-zinc-800 hover:bg-zinc-700 border border-zinc-700 rounded text-xs text-zinc-300 font-medium whitespace-nowrap"
              >
                {tpMode === 'price' ? 'Price' : 'Pips'}
              </button>
            </div>
            {tpPrice && tpMode === 'pips' && (
              <div className="text-xs text-zinc-500 mt-1">
                = {tpPrice.toFixed(isJPY ? 3 : 5)}
              </div>
            )}
          </div>

          {/* Expiry (for pending orders) */}
          {isPendingOrder && (
            <div>
              <label className="block text-xs text-zinc-400 mb-2">Expiry</label>
              <div className="space-y-2">
                <select
                  value={expiry}
                  onChange={(e) => setExpiry(e.target.value as ExpiryType)}
                  className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-zinc-300 text-sm focus:outline-none focus:border-zinc-600"
                >
                  <option value="GTC">Good Till Cancelled (GTC)</option>
                  <option value="Today">Today</option>
                  <option value="Specified">Specified Date/Time</option>
                </select>

                {expiry === 'Specified' && (
                  <div className="grid grid-cols-2 gap-2">
                    <div>
                      <input
                        type="date"
                        value={expiryDate}
                        onChange={(e) => setExpiryDate(e.target.value)}
                        className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-zinc-300 text-xs focus:outline-none focus:border-zinc-600"
                      />
                    </div>
                    <div>
                      <input
                        type="time"
                        value={expiryTime}
                        onChange={(e) => setExpiryTime(e.target.value)}
                        className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-zinc-300 text-xs focus:outline-none focus:border-zinc-600"
                      />
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Comment */}
          <div>
            <label className="block text-xs text-zinc-400 mb-2">Comment (Optional, max 64 chars)</label>
            <input
              type="text"
              maxLength={64}
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              className="w-full px-3 py-2 bg-[#252525] border border-zinc-700 rounded text-zinc-300 text-sm focus:outline-none focus:border-zinc-600"
              placeholder="Order comment..."
            />
            <div className="text-xs text-zinc-600 text-right mt-1">
              {comment.length}/64
            </div>
          </div>

          {/* Risk Calculator */}
          <div className="bg-[#252525] border border-zinc-700/50 rounded p-3">
            <div className="flex items-center gap-2 mb-3">
              <Calculator size={14} className="text-blue-400" />
              <h4 className="text-xs font-bold text-zinc-300">Risk Calculator</h4>
            </div>
            <div className="space-y-2 text-xs">
              <div className="flex justify-between">
                <span className="text-zinc-500">Required Margin:</span>
                <span className="text-zinc-300 font-mono font-semibold">
                  ${riskCalc.margin.toFixed(2)}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-zinc-500">Pip Value:</span>
                <span className="text-zinc-300 font-mono font-semibold">
                  ${riskCalc.pipValue.toFixed(2)}
                </span>
              </div>
              {riskCalc.potentialLoss > 0 && (
                <div className="flex justify-between">
                  <span className="text-zinc-500">Potential Loss (SL):</span>
                  <span className="text-rose-400 font-mono font-semibold">
                    -${riskCalc.potentialLoss.toFixed(2)}
                  </span>
                </div>
              )}
              {riskCalc.potentialProfit > 0 && (
                <div className="flex justify-between">
                  <span className="text-zinc-500">Potential Profit (TP):</span>
                  <span className="text-emerald-400 font-mono font-semibold">
                    +${riskCalc.potentialProfit.toFixed(2)}
                  </span>
                </div>
              )}
              {riskCalc.potentialProfit > 0 && riskCalc.potentialLoss > 0 && (
                <div className="flex justify-between">
                  <span className="text-zinc-500">Risk/Reward Ratio:</span>
                  <span className="text-blue-400 font-mono font-semibold">
                    1:{(riskCalc.potentialProfit / riskCalc.potentialLoss).toFixed(2)}
                  </span>
                </div>
              )}
            </div>
          </div>

          {/* One-Click Mode Info */}
          {tradeSettings.oneClickTrading && orderType === 'Market' && (
            <div className="flex items-start gap-2 px-3 py-2 bg-yellow-500/10 border border-yellow-500/20 rounded text-xs text-yellow-400">
              <Icon name="info" size="sm" className="flex-shrink-0 mt-0.5" />
              <span>One-click mode is enabled. Orders will be placed immediately.</span>
            </div>
          )}

          {/* Action Buttons */}
          <div className="grid grid-cols-2 gap-3 pt-2">
            {orderType === 'Market' ? (
              <>
                {/* SELL Button */}
                <button
                  onClick={() => handlePlaceOrder('SELL')}
                  disabled={isPlacing || volume <= 0}
                  className="flex flex-col items-center justify-center px-4 py-3 bg-rose-600 hover:bg-rose-700 disabled:bg-rose-600/30 disabled:cursor-not-allowed text-white rounded-lg transition-colors group"
                >
                  <Icon name="trending-down" size="lg" className="mb-1 group-hover:scale-110 transition-transform" />
                  <span className="text-sm font-bold">SELL</span>
                  <span className="text-xs font-mono mt-0.5 opacity-90">
                    {currentBid.toFixed(isJPY ? 3 : 5)}
                  </span>
                </button>

                {/* BUY Button */}
                <button
                  onClick={() => handlePlaceOrder('BUY')}
                  disabled={isPlacing || volume <= 0}
                  className="flex flex-col items-center justify-center px-4 py-3 bg-zinc-700 hover:bg-zinc-600 disabled:bg-blue-600/30 disabled:cursor-not-allowed text-white rounded-lg transition-colors group"
                >
                  <Icon name="trending-up" size="lg" className="mb-1 group-hover:scale-110 transition-transform" />
                  <span className="text-sm font-bold">BUY</span>
                  <span className="text-xs font-mono mt-0.5 opacity-90">
                    {currentAsk.toFixed(isJPY ? 3 : 5)}
                  </span>
                </button>
              </>
            ) : (
              <>
                {/* PLACE SELL ORDER Button */}
                {orderType.includes('Sell') && (
                  <button
                    onClick={() => handlePlaceOrder('SELL')}
                    disabled={isPlacing || volume <= 0 || !price}
                    className="col-span-2 flex items-center justify-center gap-2 px-4 py-3 bg-rose-600 hover:bg-rose-700 disabled:bg-rose-600/30 disabled:cursor-not-allowed text-white rounded-lg transition-colors font-bold"
                  >
                    <Icon name="trending-down" size="lg" />
                    <span>PLACE SELL ORDER</span>
                  </button>
                )}

                {/* PLACE BUY ORDER Button */}
                {orderType.includes('Buy') && (
                  <button
                    onClick={() => handlePlaceOrder('BUY')}
                    disabled={isPlacing || volume <= 0 || !price}
                    className="col-span-2 flex items-center justify-center gap-2 px-4 py-3 bg-zinc-700 hover:bg-zinc-600 disabled:bg-blue-600/30 disabled:cursor-not-allowed text-white rounded-lg transition-colors font-bold"
                  >
                    <Icon name="trending-up" size="lg" />
                    <span>PLACE BUY ORDER</span>
                  </button>
                )}
              </>
            )}
          </div>

          {/* Status Indicator */}
          {isPlacing && (
            <div className="text-center">
              <div className="text-xs text-blue-400 font-medium animate-pulse">
                Placing order...
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * Enhanced Order Entry Panel
 * Supports Market, Limit, Stop, and Stop-Limit orders with SL/TP
 */

import { Icon } from './ui/Icon';
import { useState, useMemo } from 'react';
import { useAppStore } from '../store/useAppStore';
import { useMT5Store } from '../store/useMT5Store';

import { API_BASE_URL as API_BASE } from '../config/api';

type OrderType = 'MARKET' | 'LIMIT' | 'STOP' | 'STOP_LIMIT';
type OrderSide = 'BUY' | 'SELL';

export const OrderEntryPanel = () => {
  const {
    selectedSymbol,
    ticks,
    orderVolume,
    setOrderVolume,
    isPlacingOrder,
    setLoadingStates,
    accountId,
  } = useAppStore();

  // MT5 mode
  const mt5Enabled = localStorage.getItem('rtx5_mt5_mode') === 'true';
  const mt5Store = useMT5Store();

  const [orderType, setOrderType] = useState<OrderType>('MARKET');
  const [limitPrice, setLimitPrice] = useState('');
  const [stopPrice, setStopPrice] = useState('');
  const [stopLoss, setStopLoss] = useState('');
  const [takeProfit, setTakeProfit] = useState('');

  const currentTick = ticks[selectedSymbol];

  const spread = useMemo(() => {
    if (!currentTick) return 0;
    return currentTick.ask - currentTick.bid;
  }, [currentTick]);

  const spreadPips = useMemo(() => {
    if (!selectedSymbol || !spread) return 0;
    // Forex pairs typically have 4 or 5 decimal places
    const pipMultiplier = selectedSymbol.includes('JPY') ? 100 : 10000;
    return spread * pipMultiplier;
  }, [selectedSymbol, spread]);

  const calculateEstimatedValue = (side: OrderSide) => {
    if (!currentTick) return 0;
    const price = side === 'BUY' ? currentTick.ask : currentTick.bid;
    return orderVolume * 100000 * price; // 1 lot = 100,000 units
  };

  const placeOrder = async (side: OrderSide) => {
    if (!accountId && !mt5Enabled) {
      alert('Please login first');
      return;
    }

    if (orderVolume <= 0) {
      alert('Invalid volume');
      return;
    }

    setLoadingStates({ isPlacingOrder: true });

    try {
      // MT5 MODE - Use MT5 store for order submission
      if (mt5Enabled) {
        if (!mt5Store.connected) {
          alert('MT5 not connected');
          setLoadingStates({ isPlacingOrder: false });
          return;
        }

        // MT5 only supports MARKET orders for now
        if (orderType !== 'MARKET') {
          alert('MT5 mode currently only supports MARKET orders');
          setLoadingStates({ isPlacingOrder: false });
          return;
        }

        const storeAccountId = useAppStore.getState().accountId;
        const mt5Login = parseInt(String(storeAccountId || localStorage.getItem('rtx_last_login') || localStorage.getItem('rtx_saved_username') || '0'), 10) || 0;

        const orderRequest = {
          symbol: selectedSymbol,
          action: side, // BUY or SELL
          volume: orderVolume,
          price: side === 'BUY' ? currentTick?.ask : currentTick?.bid,
          sl: stopLoss && parseFloat(stopLoss) > 0 ? parseFloat(stopLoss) : 0,
          tp: takeProfit && parseFloat(takeProfit) > 0 ? parseFloat(takeProfit) : 0,
          login: mt5Login
        };

        const result = await mt5Store.submitOrder(orderRequest);
        console.log('MT5 Order placed:', result);

        // Reset form on success
        setStopLoss('');
        setTakeProfit('');

        alert(`MT5 ${side} order placed successfully!`);
        setLoadingStates({ isPlacingOrder: false });
        return;
      }

      // B-BOOK MODE - Use existing B-Book API
      let endpoint = '';
      const body: any = {
        accountId,
        symbol: selectedSymbol,
        side,
        volume: orderVolume,
      };

      switch (orderType) {
        case 'MARKET':
          endpoint = `${API_BASE}/api/orders/market`;
          break;

        case 'LIMIT':
          if (!limitPrice || parseFloat(limitPrice) <= 0) {
            alert('Invalid limit price');
            setLoadingStates({ isPlacingOrder: false });
            return;
          }
          endpoint = `${API_BASE}/order/limit`;
          body.price = parseFloat(limitPrice);
          break;

        case 'STOP':
          if (!stopPrice || parseFloat(stopPrice) <= 0) {
            alert('Invalid stop price');
            setLoadingStates({ isPlacingOrder: false });
            return;
          }
          endpoint = `${API_BASE}/order/stop`;
          body.triggerPrice = parseFloat(stopPrice);
          break;

        case 'STOP_LIMIT':
          if (!stopPrice || !limitPrice) {
            alert('Invalid stop or limit price');
            setLoadingStates({ isPlacingOrder: false });
            return;
          }
          endpoint = `${API_BASE}/order/stop-limit`;
          body.triggerPrice = parseFloat(stopPrice);
          body.limitPrice = parseFloat(limitPrice);
          break;
      }

      // Add SL/TP if specified
      if (stopLoss && parseFloat(stopLoss) > 0) {
        body.sl = parseFloat(stopLoss);
      }
      if (takeProfit && parseFloat(takeProfit) > 0) {
        body.tp = parseFloat(takeProfit);
      }

      const response = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });

      if (response.ok) {
        const result = await response.json();
        console.log('Order placed:', result);

        // Reset form on success
        if (orderType !== 'MARKET') {
          setLimitPrice('');
          setStopPrice('');
        }
        setStopLoss('');
        setTakeProfit('');

        alert(`${orderType} ${side} order placed successfully!`);
      } else {
        const error = await response.text();
        alert(`Order failed: ${error}`);
      }
    } catch (error) {
      console.error('Order placement error:', error);
      alert('Failed to place order. Check console for details.');
    } finally {
      setLoadingStates({ isPlacingOrder: false });
    }
  };

  if (!currentTick) {
    return (
      <div className="p-4 text-center text-zinc-500">
        Waiting for market data...
      </div>
    );
  }

  return (
    <div className="p-4 space-y-4">
      {/* Symbol Header */}
      <div className="flex items-center justify-between pb-3 border-b border-zinc-800">
        <div>
          <h3 className="text-lg font-bold text-white">{selectedSymbol}</h3>
          <p className="text-xs text-zinc-500">
            Spread: {spreadPips.toFixed(1)} pips ({currentTick.lp || 'Unknown LP'})
          </p>
        </div>
        <div className="text-right">
          <div className="text-xs text-zinc-500">Bid / Ask</div>
          <div className="font-mono text-sm">
            <span className="text-red-400">{currentTick.bid.toFixed(5)}</span>
            {' / '}
            <span className="text-green-400">{currentTick.ask.toFixed(5)}</span>
          </div>
        </div>
      </div>

      {/* Order Type Selection */}
      <div className="grid grid-cols-4 gap-2">
        {(['MARKET', 'LIMIT', 'STOP', 'STOP_LIMIT'] as OrderType[]).map((type) => (
          <button
            key={type}
            onClick={() => setOrderType(type)}
            className={`px-3 py-2 rounded text-xs font-medium transition-colors ${orderType === type
                ? 'bg-blue-600 text-white'
                : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
              }`}
          >
            {type.replace('_', ' ')}
          </button>
        ))}
      </div>

      {/* Volume Input */}
      <div>
        <label className="block text-xs text-zinc-400 mb-1">
          <Icon name="credit-card" size="sm" className="inline w-3 h-3 mr-1" />
          Volume (Lots)
        </label>
        <input
          type="number"
          step="0.01"
          min="0.01"
          value={orderVolume}
          onChange={(e) => setOrderVolume(parseFloat(e.target.value) || 0.01)}
          className="w-full px-3 py-2 bg-zinc-900 border border-zinc-700 rounded text-white focus:outline-none focus:border-zinc-600"
        />
        <div className="text-xs text-zinc-500 mt-1">
          Quick: {[0.01, 0.1, 0.5, 1, 5].map((vol) => (
            <button
              key={vol}
              onClick={() => setOrderVolume(vol)}
              className="ml-2 text-blue-400 hover:text-zinc-300"
            >
              {vol}
            </button>
          ))}
        </div>
      </div>

      {/* Price Inputs for non-market orders */}
      {orderType !== 'MARKET' && (
        <div className="space-y-3">
          {(orderType === 'LIMIT' || orderType === 'STOP_LIMIT') && (
            <div>
              <label className="block text-xs text-zinc-400 mb-1">Limit Price</label>
              <input
                type="number"
                step="0.00001"
                value={limitPrice}
                onChange={(e) => setLimitPrice(e.target.value)}
                placeholder={currentTick.ask.toFixed(5)}
                className="w-full px-3 py-2 bg-zinc-900 border border-zinc-700 rounded text-white focus:outline-none focus:border-zinc-600"
              />
            </div>
          )}

          {(orderType === 'STOP' || orderType === 'STOP_LIMIT') && (
            <div>
              <label className="block text-xs text-zinc-400 mb-1">Stop Price</label>
              <input
                type="number"
                step="0.00001"
                value={stopPrice}
                onChange={(e) => setStopPrice(e.target.value)}
                placeholder={currentTick.bid.toFixed(5)}
                className="w-full px-3 py-2 bg-zinc-900 border border-zinc-700 rounded text-white focus:outline-none focus:border-zinc-600"
              />
            </div>
          )}
        </div>
      )}

      {/* Stop Loss / Take Profit */}
      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="block text-xs text-zinc-400 mb-1">
            <Icon name="shield" size="sm" className="inline w-3 h-3 mr-1" />
            Stop Loss
          </label>
          <input
            type="number"
            step="0.00001"
            value={stopLoss}
            onChange={(e) => setStopLoss(e.target.value)}
            placeholder="Optional"
            className="w-full px-3 py-2 bg-zinc-900 border border-zinc-700 rounded text-white text-sm focus:outline-none focus:border-red-500"
          />
        </div>
        <div>
          <label className="block text-xs text-zinc-400 mb-1">
            <Icon name="crosshair" size="sm" className="inline w-3 h-3 mr-1" />
            Take Profit
          </label>
          <input
            type="number"
            step="0.00001"
            value={takeProfit}
            onChange={(e) => setTakeProfit(e.target.value)}
            placeholder="Optional"
            className="w-full px-3 py-2 bg-zinc-900 border border-zinc-700 rounded text-white text-sm focus:outline-none focus:border-green-500"
          />
        </div>
      </div>

      {/* Order Buttons */}
      <div className="grid grid-cols-2 gap-3 pt-2">
        <button
          onClick={() => placeOrder('BUY')}
          disabled={isPlacingOrder}
          className="flex items-center justify-center gap-2 px-4 py-3 bg-green-600 hover:bg-green-700 disabled:bg-green-900 disabled:cursor-not-allowed text-white font-semibold rounded transition-colors"
        >
          <Icon name="trending-up" size="sm" className="w-4 h-4" />
          BUY {currentTick.ask.toFixed(5)}
        </button>
        <button
          onClick={() => placeOrder('SELL')}
          disabled={isPlacingOrder}
          className="flex items-center justify-center gap-2 px-4 py-3 bg-red-600 hover:bg-red-700 disabled:bg-red-900 disabled:cursor-not-allowed text-white font-semibold rounded transition-colors"
        >
          <Icon name="trending-down" size="sm" className="w-4 h-4" />
          SELL {currentTick.bid.toFixed(5)}
        </button>
      </div>

      {/* Estimated Value */}
      <div className="text-xs text-zinc-500 text-center">
        Est. value: ${calculateEstimatedValue('BUY').toFixed(2)} (BUY) / ${calculateEstimatedValue('SELL').toFixed(2)} (SELL)
      </div>
    </div>
  );
};

