/**
 * Portfolio Overview Panel
 * Complete portfolio view showing account metrics, positions, exposure, and performance
 */

import { Icon } from './ui/Icon';
import { useMemo } from 'react';
import { useAppStore } from '../store/useAppStore';

interface GroupedPosition {
  symbol: string;
  positions: any[];
  netDirection: 'LONG' | 'SHORT' | 'HEDGED';
  totalVolume: number;
  avgEntryPrice: number;
  currentPrice: number;
  unrealizedPL: number;
}

export function PortfolioOverview() {
  const account = useAppStore((state) => state.account);
  const positions = useAppStore((state) => state.positions);
  const ticks = useAppStore((state) => state.ticks);
  const trades = useAppStore((state) => state.trades);

  // Calculate account metrics
  const accountMetrics = useMemo(() => {
    if (!account) {
      return {
        balance: 0,
        equity: 0,
        usedMargin: 0,
        freeMargin: 0,
        equityChange: 0,
        usedMarginPercent: 0,
        freeMarginPercent: 0,
        freeMarginColor: 'text-green-400',
      };
    }

    const equityChange = account.equity - account.balance;
    const usedMarginPercent = account.equity > 0 ? (account.margin / account.equity) * 100 : 0;
    const freeMarginPercent = account.equity > 0 ? (account.freeMargin / account.equity) * 100 : 0;

    let freeMarginColor = 'text-green-400';
    if (freeMarginPercent < 20) freeMarginColor = 'text-red-400';
    else if (freeMarginPercent < 50) freeMarginColor = 'text-yellow-400';

    return {
      balance: account.balance,
      equity: account.equity,
      usedMargin: account.margin,
      freeMargin: account.freeMargin,
      equityChange,
      usedMarginPercent,
      freeMarginPercent,
      freeMarginColor,
    };
  }, [account]);

  // Group positions by symbol
  const groupedPositions = useMemo(() => {
    const groups = new Map<string, GroupedPosition>();

    positions.forEach((pos) => {
      if (!groups.has(pos.symbol)) {
        groups.set(pos.symbol, {
          symbol: pos.symbol,
          positions: [],
          netDirection: 'LONG',
          totalVolume: 0,
          avgEntryPrice: 0,
          currentPrice: 0,
          unrealizedPL: 0,
        });
      }

      const group = groups.get(pos.symbol)!;
      group.positions.push(pos);
      group.unrealizedPL += pos.unrealizedPnL;

      // Calculate net direction
      const longVolume = group.positions
        .filter((p) => p.side === 'BUY')
        .reduce((sum, p) => sum + p.volume, 0);
      const shortVolume = group.positions
        .filter((p) => p.side === 'SELL')
        .reduce((sum, p) => sum + p.volume, 0);

      if (longVolume > shortVolume) group.netDirection = 'LONG';
      else if (shortVolume > longVolume) group.netDirection = 'SHORT';
      else group.netDirection = 'HEDGED';

      group.totalVolume = Math.abs(longVolume - shortVolume);

      // Calculate weighted average entry price
      const totalValue = group.positions.reduce(
        (sum, p) => sum + p.openPrice * p.volume,
        0
      );
      const totalVol = group.positions.reduce((sum, p) => sum + p.volume, 0);
      group.avgEntryPrice = totalVol > 0 ? totalValue / totalVol : 0;

      // Get current price from ticks
      const tick = ticks[pos.symbol];
      if (tick) {
        group.currentPrice = group.netDirection === 'LONG' ? tick.bid : tick.ask;
      }
    });

    return Array.from(groups.values()).sort((a, b) => b.unrealizedPL - a.unrealizedPL);
  }, [positions, ticks]);

  const totalUnrealizedPL = useMemo(() => {
    return groupedPositions.reduce((sum, g) => sum + g.unrealizedPL, 0);
  }, [groupedPositions]);

  // Calculate exposure breakdown (margin used per symbol)
  const exposureData = useMemo(() => {
    const marginBySymbol = new Map<string, number>();

    positions.forEach((pos) => {
      const current = marginBySymbol.get(pos.symbol) || 0;
      // Simplified margin calculation (actual margin depends on leverage)
      const positionMargin = (pos.volume * pos.currentPrice * 100000) / 100; // Assuming 1:100 leverage
      marginBySymbol.set(pos.symbol, current + positionMargin);
    });

    const sorted = Array.from(marginBySymbol.entries())
      .sort((a, b) => b[1] - a[1])
      .map(([symbol, margin]) => ({ symbol, margin }));

    const top5 = sorted.slice(0, 5);
    const others = sorted.slice(5);
    const othersTotal = others.reduce((sum, item) => sum + item.margin, 0);

    const total = sorted.reduce((sum, item) => sum + item.margin, 0);

    const withPercentages = top5.map((item) => ({
      ...item,
      percentage: total > 0 ? (item.margin / total) * 100 : 0,
    }));

    if (othersTotal > 0) {
      withPercentages.push({
        symbol: 'Other',
        margin: othersTotal,
        percentage: total > 0 ? (othersTotal / total) * 100 : 0,
      });
    }

    return withPercentages;
  }, [positions]);

  // Calculate performance metrics
  const performanceMetrics = useMemo(() => {
    const now = new Date();
    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const weekStart = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);

    const todayTrades = trades.filter((t) => new Date(t.closeTime || '') >= todayStart);
    const weekTrades = trades.filter((t) => new Date(t.closeTime || '') >= weekStart);
    const monthTrades = trades.filter((t) => new Date(t.closeTime || '') >= monthStart);

    const todayPL = todayTrades.reduce((sum, t) => sum + t.profit, 0);
    const weekPL = weekTrades.reduce((sum, t) => sum + t.profit, 0);
    const monthPL = monthTrades.reduce((sum, t) => sum + t.profit, 0);

    // Best/Worst performing symbols (based on unrealized P&L)
    const best = groupedPositions.length > 0 ? groupedPositions[0] : null;
    const worst = groupedPositions.length > 0 ? groupedPositions[groupedPositions.length - 1] : null;

    const bestPercent = best && best.avgEntryPrice > 0
      ? ((best.currentPrice - best.avgEntryPrice) / best.avgEntryPrice) * 100
      : 0;
    const worstPercent = worst && worst.avgEntryPrice > 0
      ? ((worst.currentPrice - worst.avgEntryPrice) / worst.avgEntryPrice) * 100
      : 0;

    return {
      todayPL,
      weekPL,
      monthPL,
      bestSymbol: best?.symbol || '-',
      bestPercent,
      worstSymbol: worst?.symbol || '-',
      worstPercent,
    };
  }, [trades, groupedPositions]);

  // Colors for pie chart
  const colors = [
    'bg-zinc-600',
    'bg-green-500',
    'bg-yellow-500',
    'bg-red-500',
    'bg-purple-500',
    'bg-gray-500',
  ];

  return (
    <div className="flex flex-col h-full bg-[#131316] text-zinc-300 overflow-auto p-4 gap-4">
      {/* Top Row - Account Metrics */}
      <div className="grid grid-cols-4 gap-4">
        <MetricCard
          icon={<Icon name="credit-card" size="xl" />}
          label="Total Balance"
          value={`$${accountMetrics.balance.toFixed(2)}`}
          color="text-blue-400"
        />
        <MetricCard
          icon={<Icon name="trending-up" size="xl" />}
          label="Total Equity"
          value={`$${accountMetrics.equity.toFixed(2)}`}
          subtitle={`${accountMetrics.equityChange >= 0 ? '+' : ''}$${accountMetrics.equityChange.toFixed(2)}`}
          subtitleColor={accountMetrics.equityChange >= 0 ? 'text-green-400' : 'text-red-400'}
          color="text-green-400"
        />
        <MetricCard
          icon={<Icon name="crosshair" size="xl" />}
          label="Used Margin"
          value={`$${accountMetrics.usedMargin.toFixed(2)}`}
          subtitle={`${accountMetrics.usedMarginPercent.toFixed(1)}% of equity`}
          color="text-yellow-400"
        />
        <MetricCard
          icon={<Icon name="credit-card" size="xl" />}
          label="Free Margin"
          value={`$${accountMetrics.freeMargin.toFixed(2)}`}
          subtitle={`${accountMetrics.freeMarginPercent.toFixed(1)}% of equity`}
          color={accountMetrics.freeMarginColor}
        />
      </div>

      <div className="flex gap-4 flex-1 min-h-0">
        {/* Middle - Open Positions Summary */}
        <div className="flex-1 bg-[#252528] border border-zinc-700 rounded overflow-hidden flex flex-col">
          <div className="bg-[#131316] border-b border-zinc-700 px-4 py-3">
            <h3 className="text-sm font-semibold text-white">Open Positions Summary</h3>
          </div>

          <div className="flex-1 overflow-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#131316] sticky top-0">
                <tr className="border-b border-zinc-700">
                  <th className="px-4 py-2 text-left font-medium text-zinc-400">Symbol</th>
                  <th className="px-4 py-2 text-left font-medium text-zinc-400">Direction</th>
                  <th className="px-4 py-2 text-right font-medium text-zinc-400">Volume</th>
                  <th className="px-4 py-2 text-right font-medium text-zinc-400">Avg Entry</th>
                  <th className="px-4 py-2 text-right font-medium text-zinc-400">Current</th>
                  <th className="px-4 py-2 text-right font-medium text-zinc-400">Unrealized P&L</th>
                </tr>
              </thead>
              <tbody>
                {groupedPositions.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="text-center py-8 text-zinc-500">
                      No open positions
                    </td>
                  </tr>
                ) : (
                  <>
                    {groupedPositions.map((group) => (
                      <tr key={group.symbol} className="border-b border-zinc-800 hover:bg-zinc-800/50">
                        <td className="px-4 py-3 font-medium text-white">{group.symbol}</td>
                        <td className="px-4 py-3">
                          <span
                            className={`px-2 py-0.5 rounded text-[10px] font-medium ${
                              group.netDirection === 'LONG'
                                ? 'bg-green-500/20 text-green-400'
                                : group.netDirection === 'SHORT'
                                ? 'bg-red-500/20 text-red-400'
                                : 'bg-yellow-500/20 text-yellow-400'
                            }`}
                          >
                            {group.netDirection}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-right">{group.totalVolume.toFixed(2)}</td>
                        <td className="px-4 py-3 text-right">{group.avgEntryPrice.toFixed(5)}</td>
                        <td className="px-4 py-3 text-right">{group.currentPrice.toFixed(5)}</td>
                        <td
                          className={`px-4 py-3 text-right font-medium ${
                            group.unrealizedPL >= 0 ? 'text-green-400' : 'text-red-400'
                          }`}
                        >
                          ${group.unrealizedPL.toFixed(2)}
                        </td>
                      </tr>
                    ))}
                    <tr className="bg-[#131316] border-t-2 border-zinc-600 font-bold">
                      <td colSpan={5} className="px-4 py-3 text-white">Total</td>
                      <td
                        className={`px-4 py-3 text-right ${
                          totalUnrealizedPL >= 0 ? 'text-green-400' : 'text-red-400'
                        }`}
                      >
                        ${totalUnrealizedPL.toFixed(2)}
                      </td>
                    </tr>
                  </>
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* Right Sidebar - Exposure Breakdown */}
        <div className="w-80 bg-[#252528] border border-zinc-700 rounded overflow-hidden flex flex-col">
          <div className="bg-[#131316] border-b border-zinc-700 px-4 py-3">
            <h3 className="text-sm font-semibold text-white flex items-center gap-2">
              <Icon name="pie-chart" size="md" />
              Exposure Breakdown
            </h3>
          </div>

          <div className="flex-1 p-4 flex flex-col gap-4">
            {/* CSS Pie Chart */}
            <div className="relative w-48 h-48 mx-auto">
              {exposureData.length === 0 ? (
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-40 h-40 rounded-full border-4 border-zinc-700 flex items-center justify-center text-zinc-500 text-xs">
                    No exposure
                  </div>
                </div>
              ) : (
                <PieChart_
                  data={exposureData.map((item, i) => ({
                    ...item,
                    color: colors[i % colors.length],
                  }))}
                />
              )}
            </div>

            {/* Legend */}
            <div className="space-y-2">
              {exposureData.map((item, i) => (
                <div key={item.symbol} className="flex items-center justify-between text-xs">
                  <div className="flex items-center gap-2">
                    <div className={`w-3 h-3 rounded ${colors[i % colors.length]}`} />
                    <span className="text-zinc-300">{item.symbol}</span>
                  </div>
                  <span className="text-zinc-400 font-medium">{item.percentage.toFixed(1)}%</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Bottom - Performance Metrics */}
      <div className="grid grid-cols-5 gap-4">
        <PerformanceCard
          label="Today's P&L"
          value={`$${performanceMetrics.todayPL.toFixed(2)}`}
          color={performanceMetrics.todayPL >= 0 ? 'text-green-400' : 'text-red-400'}
        />
        <PerformanceCard
          label="This Week's P&L"
          value={`$${performanceMetrics.weekPL.toFixed(2)}`}
          color={performanceMetrics.weekPL >= 0 ? 'text-green-400' : 'text-red-400'}
        />
        <PerformanceCard
          label="This Month's P&L"
          value={`$${performanceMetrics.monthPL.toFixed(2)}`}
          color={performanceMetrics.monthPL >= 0 ? 'text-green-400' : 'text-red-400'}
        />
        <PerformanceCard
          label="Best Performing"
          value={performanceMetrics.bestSymbol}
          subtitle={`${performanceMetrics.bestPercent >= 0 ? '+' : ''}${performanceMetrics.bestPercent.toFixed(2)}%`}
          color="text-green-400"
        />
        <PerformanceCard
          label="Worst Performing"
          value={performanceMetrics.worstSymbol}
          subtitle={`${performanceMetrics.worstPercent >= 0 ? '+' : ''}${performanceMetrics.worstPercent.toFixed(2)}%`}
          color="text-red-400"
        />
      </div>
    </div>
  );
}

// Helper Components
interface MetricCardProps {
  icon: React.ReactNode;
  label: string;
  value: string;
  subtitle?: string;
  subtitleColor?: string;
  color: string;
}

function MetricCard({ icon, label, value, subtitle, subtitleColor, color }: MetricCardProps) {
  return (
    <div className="bg-[#252528] border border-zinc-700 rounded p-4">
      <div className="flex items-center gap-3 mb-2">
        <div className={color}>{icon}</div>
        <span className="text-xs text-zinc-400 uppercase font-medium">{label}</span>
      </div>
      <div className={`text-2xl font-bold ${color}`}>{value}</div>
      {subtitle && (
        <div className={`text-xs mt-1 ${subtitleColor || 'text-zinc-400'}`}>{subtitle}</div>
      )}
    </div>
  );
}

interface PerformanceCardProps {
  label: string;
  value: string;
  subtitle?: string;
  color: string;
}

function PerformanceCard({ label, value, subtitle, color }: PerformanceCardProps) {
  return (
    <div className="bg-[#252528] border border-zinc-700 rounded p-3">
      <div className="text-[10px] text-zinc-400 uppercase mb-1">{label}</div>
      <div className={`text-lg font-bold ${color}`}>{value}</div>
      {subtitle && <div className={`text-xs mt-0.5 ${color}`}>{subtitle}</div>}
    </div>
  );
}

// CSS Pie Chart Component
interface PieChartData {
  symbol: string;
  percentage: number;
  color: string;
}

function PieChart_({ data }: { data: PieChartData[] }) {
  let cumulativePercent = 0;

  return (
    <div className="relative w-full h-full">
      <svg viewBox="0 0 100 100" className="transform -rotate-90">
        <circle cx="50" cy="50" r="40" fill="#131316" />
        {data.map((item, i) => {
          const startAngle = (cumulativePercent / 100) * 360;
          const endAngle = ((cumulativePercent + item.percentage) / 100) * 360;
          const largeArc = item.percentage > 50 ? 1 : 0;

          const startRad = (startAngle * Math.PI) / 180;
          const endRad = (endAngle * Math.PI) / 180;

          const x1 = 50 + 40 * Math.cos(startRad);
          const y1 = 50 + 40 * Math.sin(startRad);
          const x2 = 50 + 40 * Math.cos(endRad);
          const y2 = 50 + 40 * Math.sin(endRad);

          const pathData = [
            `M 50 50`,
            `L ${x1} ${y1}`,
            `A 40 40 0 ${largeArc} 1 ${x2} ${y2}`,
            `Z`,
          ].join(' ');

          cumulativePercent += item.percentage;

          const colorMap: Record<string, string> = {
            'bg-zinc-600': '#8a8a8f',
            'bg-green-500': '#22c55e',
            'bg-yellow-500': '#eab308',
            'bg-red-500': '#ef4444',
            'bg-purple-500': '#a855f7',
            'bg-gray-500': '#6b7280',
          };

          return (
            <path
              key={i}
              d={pathData}
              fill={colorMap[item.color] || '#6b7280'}
              className="transition-opacity hover:opacity-80"
            />
          );
        })}
      </svg>
    </div>
  );
}

/**
 * Position List Component
 * Displays open positions with real-time P&L updates
 */

import { Icon } from './ui/Icon';
import { useState, useMemo } from 'react';
import { useAppStore } from '../store/useAppStore';
import type { Position } from '../store/useAppStore';

import api from '../services/api';

export const PositionList = () => {
  const { positions, ticks, accountId } = useAppStore();
  const [closingPositionId, setClosingPositionId] = useState<number | null>(null);
  const [modifyingPosition, setModifyingPosition] = useState<number | null>(null);
  const [newSL, setNewSL] = useState('');
  const [newTP, setNewTP] = useState('');

  // Calculate live P&L for each position
  const enrichedPositions = useMemo(() => {
    return positions.map((pos: Position) => {
      const tick = ticks[pos.symbol];
      if (!tick) return { ...pos, livePrice: pos.currentPrice, livePnL: pos.unrealizedPnL };

      // Use bid for long positions, ask for short positions
      const livePrice = pos.side === 'BUY' ? tick.bid : tick.ask;

      // Calculate P&L
      const priceDiff = pos.side === 'BUY'
        ? livePrice - pos.openPrice
        : pos.openPrice - livePrice;

      const pipValue = 10; // Simplified (actual calculation depends on symbol)
      const livePnL = priceDiff * pos.volume * 100000 / pipValue;

      return {
        ...pos,
        livePrice,
        livePnL: livePnL - (pos.commission + pos.swap),
      };
    });
  }, [positions, ticks]);

  const totalPnL = useMemo(() => {
    return enrichedPositions.reduce((sum: number, pos: { livePnL: number }) => sum + pos.livePnL, 0);
  }, [enrichedPositions]);

  const closePosition = async (positionId: number) => {
    if (!accountId) return;

    setClosingPositionId(positionId);

    try {
      const login = parseInt(accountId, 10) || 0;
      await api.mt5.closePosition(positionId, undefined, login);
      console.log('Position closed successfully via MT5 Sync');
    } catch (error: any) {
      console.error('Close position error:', error);
      alert('Failed to close position: ' + (error.message || 'Unknown error'));
    } finally {
      setClosingPositionId(null);
    }
  };

  const modifyPosition = async (positionId: number) => {
    if (!accountId) return;

    const sl = newSL ? parseFloat(newSL) : undefined;
    const tp = newTP ? parseFloat(newTP) : undefined;

    if (!sl && !tp) {
      alert('Please enter at least SL or TP');
      return;
    }

    try {
      await api.mt5.modifyPosition(positionId, sl || 0, tp || 0);
      console.log('Position modified successfully via MT5 Sync');
      setModifyingPosition(null);
      setNewSL('');
      setNewTP('');
    } catch (error: any) {
      console.error('Modify position error:', error);
      alert('Failed to modify position: ' + (error.message || 'Unknown error'));
    }
  };

  const closeAllPositions = async () => {
    if (!accountId || positions.length === 0) return;

    if (!confirm(`Close all ${positions.length} positions?`)) return;

    try {
      const login = parseInt(accountId, 10) || 0;
      await Promise.all(positions.map(pos =>
        api.mt5.closePosition(pos.id, undefined, login)
      ));
      console.log('All positions closed via MT5 Sync');
    } catch (error: any) {
      console.error('Close all error:', error);
      alert('Failed to close all positions: ' + (error.message || 'Unknown error'));
    }
  };

  const formatTime = (timeString: string) => {
    try {
      const date = new Date(timeString);
      return date.toLocaleString('en-US', {
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch {
      return timeString;
    }
  };

  if (positions.length === 0) {
    return (
      <div className="p-6 text-center text-zinc-500">
        <Icon name="credit-card" size="sm" className="w-12 h-12 mx-auto mb-2 text-zinc-700" />
        <p>No open positions</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-zinc-800">
        <div>
          <h3 className="text-sm font-semibold text-white">Open Positions</h3>
          <p className="text-xs text-zinc-500">
            {positions.length} position{positions.length !== 1 ? 's' : ''}
          </p>
        </div>
        <div className="flex items-center gap-3">
          <div className="text-right">
            <div className="text-xs text-zinc-500">Total P&L</div>
            <div
              className={`font-mono font-bold ${totalPnL >= 0 ? 'text-green-400' : 'text-red-400'
                }`}
            >
              {totalPnL >= 0 ? '+' : ''}${totalPnL.toFixed(2)}
            </div>
          </div>
          <button
            onClick={closeAllPositions}
            className="px-3 py-1.5 text-xs bg-red-600 hover:bg-red-700 text-white rounded transition-colors"
          >
            Close All
          </button>
        </div>
      </div>

      {/* Position List */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-sm">
          <thead className="sticky top-0 bg-zinc-900 border-b border-zinc-800">
            <tr className="text-xs text-zinc-500 text-left">
              <th className="p-2">Symbol</th>
              <th className="p-2">Type</th>
              <th className="p-2">Volume</th>
              <th className="p-2">Open</th>
              <th className="p-2">Current</th>
              <th className="p-2">SL/TP</th>
              <th className="p-2">P&L</th>
              <th className="p-2">Time</th>
              <th className="p-2">Actions</th>
            </tr>
          </thead>
          <tbody>
            {enrichedPositions.map((position: Position & { livePrice: number; livePnL: number }) => (
              <tr
                key={position.id}
                className="border-b border-zinc-800 hover:bg-zinc-900/50 transition-colors"
              >
                <td className="p-2 font-medium text-white">{position.symbol}</td>
                <td className="p-2">
                  <span
                    className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium ${position.side === 'BUY'
                      ? 'bg-green-900/30 text-green-400'
                      : 'bg-red-900/30 text-red-400'
                      }`}
                  >
                    {position.side === 'BUY' ? (
                      <Icon name="trending-up" size="sm" className="w-3 h-3" />
                    ) : (
                      <Icon name="trending-down" size="sm" className="w-3 h-3" />
                    )}
                    {position.side}
                  </span>
                </td>
                <td className="p-2 font-mono text-zinc-300">{position.volume.toFixed(2)}</td>
                <td className="p-2 font-mono text-zinc-400">
                  {position.openPrice.toFixed(5)}
                </td>
                <td className="p-2 font-mono text-white font-medium">
                  {position.livePrice.toFixed(5)}
                </td>
                <td className="p-2 text-xs text-zinc-500">
                  <div>{position.sl > 0 ? position.sl.toFixed(5) : '-'}</div>
                  <div>{position.tp > 0 ? position.tp.toFixed(5) : '-'}</div>
                </td>
                <td className="p-2">
                  <div
                    className={`font-mono font-bold ${position.livePnL >= 0 ? 'text-green-400' : 'text-red-400'
                      }`}
                  >
                    {position.livePnL >= 0 ? '+' : ''}${position.livePnL.toFixed(2)}
                  </div>
                  {(position.commission !== 0 || position.swap !== 0) && (
                    <div className="text-xs text-zinc-500">
                      C: ${position.commission.toFixed(2)} S: ${position.swap.toFixed(2)}
                    </div>
                  )}
                </td>
                <td className="p-2 text-xs text-zinc-500">
                  <Icon name="clock" size="sm" className="inline w-3 h-3 mr-1" />
                  {formatTime(position.openTime)}
                </td>
                <td className="p-2">
                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => setModifyingPosition(position.id)}
                      className="p-1.5 hover:bg-zinc-800 rounded transition-colors"
                      title="Modify SL/TP"
                    >
                      <Icon name="edit" size="sm" className="w-3.5 h-3.5 text-blue-400" />
                    </button>
                    <button
                      onClick={() => closePosition(position.id)}
                      disabled={closingPositionId === position.id}
                      className="p-1.5 hover:bg-zinc-800 rounded transition-colors disabled:opacity-50"
                      title="Close Position"
                    >
                      <Icon name="x-close" size="sm" className="w-3.5 h-3.5 text-red-400" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Modify Modal */}
      {modifyingPosition !== null && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-zinc-900 border border-zinc-700 rounded-lg p-6 w-96">
            <h3 className="text-lg font-bold text-white mb-4">Modify Position</h3>

            <div className="space-y-3">
              <div>
                <label className="block text-xs text-zinc-400 mb-1">Stop Loss</label>
                <input
                  type="number"
                  step="0.00001"
                  value={newSL}
                  onChange={(e) => setNewSL(e.target.value)}
                  placeholder="Optional"
                  className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded text-white focus:outline-none focus:border-zinc-600"
                />
              </div>

              <div>
                <label className="block text-xs text-zinc-400 mb-1">Take Profit</label>
                <input
                  type="number"
                  step="0.00001"
                  value={newTP}
                  onChange={(e) => setNewTP(e.target.value)}
                  placeholder="Optional"
                  className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded text-white focus:outline-none focus:border-zinc-600"
                />
              </div>
            </div>

            <div className="flex gap-2 mt-6">
              <button
                onClick={() => modifyPosition(modifyingPosition)}
                className="flex-1 px-4 py-2 bg-zinc-700 hover:bg-zinc-600 text-white rounded font-medium transition-colors"
              >
                Update
              </button>
              <button
                onClick={() => {
                  setModifyingPosition(null);
                  setNewSL('');
                  setNewTP('');
                }}
                className="flex-1 px-4 py-2 bg-zinc-700 hover:bg-zinc-600 text-white rounded font-medium transition-colors"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

/**
 * Position Size Calculator / Risk Manager
 * Advanced position sizing tool with risk/reward visualization
 */

import { Icon } from './ui/Icon';
import React, { useState, useMemo, useCallback } from 'react';
import { usePositionSizeStore, type CalculationHistory } from '../store/usePositionSizeStore';
import { Calculator } from 'lucide-react';

// Pip values for standard lot (100,000 units) in USD
const PIP_VALUES: Record<string, number> = {
  'EURUSD': 10,
  'GBPUSD': 10,
  'AUDUSD': 10,
  'NZDUSD': 10,
  'USDCAD': 9.60,
  'USDCHF': 10.20,
  'USDJPY': 9.10,
  'EURJPY': 9.10,
  'GBPJPY': 9.10,
  'AUDJPY': 9.10,
  'EURGBP': 12.80,
  'EURAUD': 6.50,
  'EURCHF': 10.20,
  'GBPCHF': 10.20,
  'AUDCAD': 9.60,
  'NZDCAD': 9.60,
  'CADCHF': 10.60,
  'CHFJPY': 9.10,
  'AUDNZD': 6.20,
  'GBPAUD': 6.50,
};

const SYMBOLS = Object.keys(PIP_VALUES);

// Risk profile presets
const RISK_PRESETS = [
  { name: 'Conservative', risk: 1, color: 'emerald' },
  { name: 'Moderate', risk: 2, color: 'yellow' },
  { name: 'Aggressive', risk: 5, color: 'red' },
];

interface BatchSymbol {
  symbol: string;
  stopLossPips: number;
}

export const PositionSizeCalculator: React.FC = () => {
  const { addCalculation, clearHistory, calculationHistory } = usePositionSizeStore();

  // Form inputs
  const [accountBalance, setAccountBalance] = useState<number>(10000);
  const [riskPercent, setRiskPercent] = useState<number>(2);
  const [stopLossPips, setStopLossPips] = useState<number>(20);
  const [selectedSymbol, setSelectedSymbol] = useState<string>('EURUSD');
  const [currentPrice, setCurrentPrice] = useState<number>(1.0850);

  // Batch calculator
  const [batchSymbols, setBatchSymbols] = useState<BatchSymbol[]>([
    { symbol: 'EURUSD', stopLossPips: 20 },
    { symbol: 'GBPUSD', stopLossPips: 25 },
  ]);

  // Calculate position size and related metrics
  const calculations = useMemo(() => {
    const pipValue = PIP_VALUES[selectedSymbol] || 10;
    const monetaryRisk = (accountBalance * riskPercent) / 100;
    const pipRiskValue = stopLossPips * pipValue;
    const positionSize = pipRiskValue > 0 ? monetaryRisk / pipRiskValue : 0;

    // Rewards at different RR ratios
    const reward1to1 = monetaryRisk;
    const reward1to2 = monetaryRisk * 2;
    const reward1to3 = monetaryRisk * 3;

    // Margin required (assuming 1:100 leverage)
    const leverage = 100;
    const lotSize = positionSize * 100000; // Convert to units
    const marginRequired = lotSize / leverage;

    return {
      positionSize: Number(positionSize.toFixed(2)),
      monetaryRisk: Number(monetaryRisk.toFixed(2)),
      reward1to1: Number(reward1to1.toFixed(2)),
      reward1to2: Number(reward1to2.toFixed(2)),
      reward1to3: Number(reward1to3.toFixed(2)),
      marginRequired: Number(marginRequired.toFixed(2)),
      pipValue,
      takeProfitPips1to1: stopLossPips,
      takeProfitPips1to2: stopLossPips * 2,
      takeProfitPips1to3: stopLossPips * 3,
    };
  }, [accountBalance, riskPercent, stopLossPips, selectedSymbol]);

  // Save calculation to history
  const saveCalculation = useCallback(() => {
    addCalculation({
      symbol: selectedSymbol,
      accountBalance,
      riskPercent,
      stopLossPips,
      positionSize: calculations.positionSize,
      monetaryRisk: calculations.monetaryRisk,
      reward1to1: calculations.reward1to1,
      reward1to2: calculations.reward1to2,
      reward1to3: calculations.reward1to3,
      marginRequired: calculations.marginRequired,
    });
  }, [addCalculation, selectedSymbol, accountBalance, riskPercent, stopLossPips, calculations]);

  // Batch calculations
  const batchResults = useMemo(() => {
    return batchSymbols.map((batch) => {
      const pipValue = PIP_VALUES[batch.symbol] || 10;
      const monetaryRisk = (accountBalance * riskPercent) / 100;
      const pipRiskValue = batch.stopLossPips * pipValue;
      const positionSize = pipRiskValue > 0 ? monetaryRisk / pipRiskValue : 0;

      return {
        symbol: batch.symbol,
        stopLossPips: batch.stopLossPips,
        positionSize: Number(positionSize.toFixed(2)),
        monetaryRisk: Number(monetaryRisk.toFixed(2)),
      };
    });
  }, [batchSymbols, accountBalance, riskPercent]);

  // Add symbol to batch
  const addBatchSymbol = () => {
    setBatchSymbols([...batchSymbols, { symbol: 'EURUSD', stopLossPips: 20 }]);
  };

  // Remove symbol from batch
  const removeBatchSymbol = (index: number) => {
    setBatchSymbols(batchSymbols.filter((_, i) => i !== index));
  };

  // Update batch symbol
  const updateBatchSymbol = (index: number, field: keyof BatchSymbol, value: string | number) => {
    const updated = [...batchSymbols];
    updated[index] = { ...updated[index], [field]: value };
    setBatchSymbols(updated);
  };

  return (
    <div className="flex flex-col h-full bg-zinc-900 text-zinc-100">
      {/* Header */}
      <div className="flex items-center gap-2 px-4 py-2 bg-zinc-800 border-b border-zinc-700">
        <Calculator className="w-4 h-4 text-emerald-400" />
        <span className="font-semibold text-sm">Position Size Calculator</span>
      </div>

      <div className="flex-1 overflow-auto p-4 space-y-4">
        {/* Input Form */}
        <div className="bg-zinc-800 border border-zinc-700 rounded p-4 space-y-4">
          <h3 className="text-sm font-semibold text-zinc-300 flex items-center gap-2">
            <Icon name="credit-card" size="sm" className="w-4 h-4" />
            Calculator Inputs
          </h3>

          <div className="grid grid-cols-2 gap-4">
            {/* Account Balance */}
            <div>
              <label className="text-xs text-zinc-400 block mb-1">Account Balance ($)</label>
              <input
                type="number"
                value={accountBalance}
                onChange={(e) => setAccountBalance(Number(e.target.value))}
                className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-sm text-zinc-100"
                min="100"
                step="100"
              />
            </div>

            {/* Risk Percent */}
            <div>
              <label className="text-xs text-zinc-400 block mb-1">Risk per Trade (%)</label>
              <input
                type="number"
                value={riskPercent}
                onChange={(e) => setRiskPercent(Math.min(5, Math.max(0.1, Number(e.target.value))))}
                className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-sm text-zinc-100"
                min="0.1"
                max="5"
                step="0.1"
              />
            </div>

            {/* Symbol Selector */}
            <div>
              <label className="text-xs text-zinc-400 block mb-1">Symbol</label>
              <select
                value={selectedSymbol}
                onChange={(e) => setSelectedSymbol(e.target.value)}
                className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-sm text-zinc-100"
              >
                {SYMBOLS.map((sym) => (
                  <option key={sym} value={sym}>
                    {sym} (${PIP_VALUES[sym]}/pip)
                  </option>
                ))}
              </select>
            </div>

            {/* Stop Loss Pips */}
            <div>
              <label className="text-xs text-zinc-400 block mb-1">Stop Loss (pips)</label>
              <input
                type="number"
                value={stopLossPips}
                onChange={(e) => setStopLossPips(Number(e.target.value))}
                className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-sm text-zinc-100"
                min="1"
                step="1"
              />
            </div>

            {/* Current Price */}
            <div>
              <label className="text-xs text-zinc-400 block mb-1">Current Price</label>
              <input
                type="number"
                value={currentPrice}
                onChange={(e) => setCurrentPrice(Number(e.target.value))}
                className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-sm text-zinc-100"
                step="0.0001"
              />
            </div>
          </div>

          {/* Risk Presets */}
          <div>
            <label className="text-xs text-zinc-400 block mb-2">Quick Risk Profiles</label>
            <div className="flex gap-2">
              {RISK_PRESETS.map((preset) => (
                <button
                  key={preset.name}
                  onClick={() => setRiskPercent(preset.risk)}
                  className={`px-3 py-1 rounded text-xs font-medium transition-colors ${
                    riskPercent === preset.risk
                      ? `bg-${preset.color}-600 text-white`
                      : `bg-zinc-700 text-zinc-300 hover:bg-zinc-600`
                  }`}
                >
                  {preset.name} ({preset.risk}%)
                </button>
              ))}
            </div>
          </div>

          {/* Save to History Button */}
          <button
            onClick={saveCalculation}
            className="w-full bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded text-sm font-medium transition-colors"
          >
            Save Calculation
          </button>
        </div>

        {/* Calculation Results */}
        <div className="grid grid-cols-3 gap-3">
          <div className="bg-zinc-800 border border-zinc-700 rounded p-3">
            <div className="text-xs text-zinc-400 mb-1">Position Size</div>
            <div className="text-xl font-bold text-emerald-400">{calculations.positionSize} lots</div>
          </div>

          <div className="bg-zinc-800 border border-zinc-700 rounded p-3">
            <div className="text-xs text-zinc-400 mb-1">Monetary Risk</div>
            <div className="text-xl font-bold text-red-400">${calculations.monetaryRisk}</div>
          </div>

          <div className="bg-zinc-800 border border-zinc-700 rounded p-3">
            <div className="text-xs text-zinc-400 mb-1">Margin Required</div>
            <div className="text-xl font-bold text-yellow-400">${calculations.marginRequired}</div>
          </div>
        </div>

        {/* Reward Scenarios */}
        <div className="bg-zinc-800 border border-zinc-700 rounded p-4">
          <h3 className="text-sm font-semibold text-zinc-300 mb-3 flex items-center gap-2">
            <Icon name="crosshair" size="sm" className="w-4 h-4" />
            Reward Scenarios (Risk/Reward Ratios)
          </h3>
          <div className="grid grid-cols-3 gap-3">
            <div className="bg-zinc-900 border border-zinc-700 rounded p-3">
              <div className="text-xs text-zinc-400 mb-1">1:1 RR</div>
              <div className="text-lg font-bold text-emerald-400">${calculations.reward1to1}</div>
              <div className="text-xs text-zinc-500 mt-1">TP: {calculations.takeProfitPips1to1} pips</div>
            </div>

            <div className="bg-zinc-900 border border-zinc-700 rounded p-3">
              <div className="text-xs text-zinc-400 mb-1">1:2 RR</div>
              <div className="text-lg font-bold text-emerald-400">${calculations.reward1to2}</div>
              <div className="text-xs text-zinc-500 mt-1">TP: {calculations.takeProfitPips1to2} pips</div>
            </div>

            <div className="bg-zinc-900 border border-zinc-700 rounded p-3">
              <div className="text-xs text-zinc-400 mb-1">1:3 RR</div>
              <div className="text-lg font-bold text-emerald-400">${calculations.reward1to3}</div>
              <div className="text-xs text-zinc-500 mt-1">TP: {calculations.takeProfitPips1to3} pips</div>
            </div>
          </div>
        </div>

        {/* Risk/Reward Visualizer */}
        <div className="bg-zinc-800 border border-zinc-700 rounded p-4">
          <h3 className="text-sm font-semibold text-zinc-300 mb-3 flex items-center gap-2">
            <Icon name="bar-chart-3" size="sm" className="w-4 h-4" />
            Risk/Reward Visualizer
          </h3>
          <RiskRewardChart
            currentPrice={currentPrice}
            stopLossPips={stopLossPips}
            takeProfitPips1to1={calculations.takeProfitPips1to1}
            takeProfitPips1to2={calculations.takeProfitPips1to2}
            takeProfitPips1to3={calculations.takeProfitPips1to3}
            monetaryRisk={calculations.monetaryRisk}
            reward1to1={calculations.reward1to1}
            reward1to2={calculations.reward1to2}
            reward1to3={calculations.reward1to3}
            symbol={selectedSymbol}
          />
        </div>

        {/* Pip Value Table */}
        <div className="bg-zinc-800 border border-zinc-700 rounded p-4">
          <h3 className="text-sm font-semibold text-zinc-300 mb-3 flex items-center gap-2">
            <Icon name="bar-chart-2" size="sm" className="w-4 h-4" />
            Pip Values (Standard Lot)
          </h3>
          <div className="grid grid-cols-4 gap-2 max-h-64 overflow-auto">
            {SYMBOLS.map((symbol) => (
              <div
                key={symbol}
                className={`bg-zinc-900 border rounded p-2 text-xs ${
                  symbol === selectedSymbol ? 'border-emerald-600' : 'border-zinc-700'
                }`}
              >
                <div className="font-medium text-zinc-300">{symbol}</div>
                <div className="text-emerald-400">${PIP_VALUES[symbol]}/pip</div>
              </div>
            ))}
          </div>
        </div>

        {/* Batch Calculator */}
        <div className="bg-zinc-800 border border-zinc-700 rounded p-4">
          <h3 className="text-sm font-semibold text-zinc-300 mb-3 flex items-center gap-2">
            <Icon name="layers" size="sm" className="w-4 h-4" />
            Batch Calculator
          </h3>

          <div className="space-y-2 mb-3">
            {batchSymbols.map((batch, index) => (
              <div key={index} className="flex items-center gap-2">
                <select
                  value={batch.symbol}
                  onChange={(e) => updateBatchSymbol(index, 'symbol', e.target.value)}
                  className="flex-1 bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-xs text-zinc-100"
                >
                  {SYMBOLS.map((sym) => (
                    <option key={sym} value={sym}>{sym}</option>
                  ))}
                </select>

                <input
                  type="number"
                  value={batch.stopLossPips}
                  onChange={(e) => updateBatchSymbol(index, 'stopLossPips', Number(e.target.value))}
                  placeholder="SL pips"
                  className="w-20 bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-xs text-zinc-100"
                  min="1"
                />

                <div className="text-xs text-zinc-300 w-24">
                  {batchResults[index]?.positionSize} lots
                </div>

                <button
                  onClick={() => removeBatchSymbol(index)}
                  className="p-1 hover:bg-zinc-700 rounded transition-colors"
                >
                  <Icon name="trash" size="sm" className="w-3 h-3 text-red-400" />
                </button>
              </div>
            ))}
          </div>

          <button
            onClick={addBatchSymbol}
            className="w-full bg-zinc-700 hover:bg-zinc-600 text-zinc-300 px-3 py-1 rounded text-xs transition-colors"
          >
            + Add Symbol
          </button>
        </div>

        {/* Calculation History */}
        <div className="bg-zinc-800 border border-zinc-700 rounded p-4">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-semibold text-zinc-300 flex items-center gap-2">
              <Icon name="history" size="sm" className="w-4 h-4" />
              Calculation History (Last 10)
            </h3>
            {calculationHistory.length > 0 && (
              <button
                onClick={clearHistory}
                className="text-xs text-red-400 hover:text-red-300 flex items-center gap-1"
              >
                <Icon name="trash" size="sm" className="w-3 h-3" />
                Clear
              </button>
            )}
          </div>

          {calculationHistory.length === 0 ? (
            <div className="text-xs text-zinc-500 text-center py-4">
              No calculations saved yet. Click "Save Calculation" to track your position sizes.
            </div>
          ) : (
            <div className="space-y-2 max-h-64 overflow-auto">
              {calculationHistory.map((calc) => (
                <div key={calc.id} className="bg-zinc-900 border border-zinc-700 rounded p-2 text-xs">
                  <div className="flex items-center justify-between mb-1">
                    <span className="font-medium text-zinc-300">{calc.symbol}</span>
                    <span className="text-zinc-500">
                      {new Date(calc.timestamp).toLocaleString()}
                    </span>
                  </div>
                  <div className="grid grid-cols-4 gap-2 text-zinc-400">
                    <div>
                      <span className="text-zinc-500">Lots:</span> {calc.positionSize}
                    </div>
                    <div>
                      <span className="text-zinc-500">Risk:</span> ${calc.monetaryRisk}
                    </div>
                    <div>
                      <span className="text-zinc-500">SL:</span> {calc.stopLossPips}p
                    </div>
                    <div>
                      <span className="text-zinc-500">R%:</span> {calc.riskPercent}%
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// Risk/Reward Chart Component
interface RiskRewardChartProps {
  currentPrice: number;
  stopLossPips: number;
  takeProfitPips1to1: number;
  takeProfitPips1to2: number;
  takeProfitPips1to3: number;
  monetaryRisk: number;
  reward1to1: number;
  reward1to2: number;
  reward1to3: number;
  symbol: string;
}

const RiskRewardChart: React.FC<RiskRewardChartProps> = ({
  currentPrice,
  stopLossPips,
  takeProfitPips1to1,
  takeProfitPips1to2,
  takeProfitPips1to3,
  monetaryRisk,
  reward1to1,
  reward1to2,
  reward1to3,
  symbol,
}) => {
  const pipSize = symbol.includes('JPY') ? 0.01 : 0.0001;

  const stopLossPrice = currentPrice - (stopLossPips * pipSize);
  const tp1Price = currentPrice + (takeProfitPips1to1 * pipSize);
  const tp2Price = currentPrice + (takeProfitPips1to2 * pipSize);
  const tp3Price = currentPrice + (takeProfitPips1to3 * pipSize);

  const priceRange = Math.max(
    Math.abs(currentPrice - stopLossPrice),
    Math.abs(tp3Price - currentPrice)
  ) * 2.2;

  const minPrice = currentPrice - priceRange / 2;
  const maxPrice = currentPrice + priceRange / 2;

  const priceToY = (price: number) => {
    return 300 - ((price - minPrice) / (maxPrice - minPrice)) * 280 + 10;
  };

  const entryY = priceToY(currentPrice);
  const slY = priceToY(stopLossPrice);
  const tp1Y = priceToY(tp1Price);
  const tp2Y = priceToY(tp2Price);
  const tp3Y = priceToY(tp3Price);

  return (
    <svg viewBox="0 0 600 300" className="w-full h-64 bg-zinc-900 rounded">
      {/* Background grid */}
      {[0, 1, 2, 3, 4].map((i) => (
        <line
          key={`grid-${i}`}
          x1="0"
          y1={60 * i}
          x2="600"
          y2={60 * i}
          stroke="#3f3f46"
          strokeWidth="1"
          strokeDasharray="2,2"
        />
      ))}

      {/* Stop Loss */}
      <line x1="0" y1={slY} x2="600" y2={slY} stroke="#ef4444" strokeWidth="2" />
      <text x="10" y={slY - 5} fill="#ef4444" fontSize="12">
        SL: {stopLossPrice.toFixed(symbol.includes('JPY') ? 3 : 5)} (-${monetaryRisk})
      </text>

      {/* Entry */}
      <line x1="0" y1={entryY} x2="600" y2={entryY} stroke="#60a5fa" strokeWidth="2" strokeDasharray="5,5" />
      <text x="10" y={entryY - 5} fill="#60a5fa" fontSize="12" fontWeight="bold">
        ENTRY: {currentPrice.toFixed(symbol.includes('JPY') ? 3 : 5)}
      </text>

      {/* Take Profit Levels */}
      <line x1="0" y1={tp1Y} x2="600" y2={tp1Y} stroke="#10b981" strokeWidth="1.5" strokeDasharray="3,3" />
      <text x="10" y={tp1Y - 5} fill="#10b981" fontSize="11">
        TP1 (1:1): {tp1Price.toFixed(symbol.includes('JPY') ? 3 : 5)} (+${reward1to1})
      </text>

      <line x1="0" y1={tp2Y} x2="600" y2={tp2Y} stroke="#10b981" strokeWidth="1.5" strokeDasharray="3,3" />
      <text x="10" y={tp2Y - 5} fill="#10b981" fontSize="11">
        TP2 (1:2): {tp2Price.toFixed(symbol.includes('JPY') ? 3 : 5)} (+${reward1to2})
      </text>

      <line x1="0" y1={tp3Y} x2="600" y2={tp3Y} stroke="#10b981" strokeWidth="1.5" strokeDasharray="3,3" />
      <text x="10" y={tp3Y - 5} fill="#10b981" fontSize="11">
        TP3 (1:3): {tp3Price.toFixed(symbol.includes('JPY') ? 3 : 5)} (+${reward1to3})
      </text>

      {/* Risk/Reward zones */}
      <rect x="550" y={entryY} width="40" height={slY - entryY} fill="#ef4444" opacity="0.2" />
      <rect x="550" y={tp1Y} width="40" height={entryY - tp1Y} fill="#10b981" opacity="0.15" />
      <rect x="550" y={tp2Y} width="40" height={tp1Y - tp2Y} fill="#10b981" opacity="0.25" />
      <rect x="550" y={tp3Y} width="40" height={tp2Y - tp3Y} fill="#10b981" opacity="0.35" />
    </svg>
  );
};

/**
 * Enhanced Positions/Orders Panel
 * Professional positions and orders management with inline editing
 * Features: SL/TP inline editing, partial close, close all, real-time P&L
 */

import { Icon } from './ui/Icon';
import { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { API_ENDPOINTS } from '../config/api';
import api from '../services/api';
import { useMT5Store } from '../store/useMT5Store';
import { useCurrentTick, useMarketDataStore } from '../store/useMarketDataStore';
import { useConfirmStore } from '../store/useConfirmStore';
import apiClient from '../api/client';
import { ModifyPositionDialog } from './ModifyPositionDialog';
import { PriceDisplay } from './ui/PriceDisplay';

interface Position {
    id: number;
    symbol: string;
    side: 'BUY' | 'SELL';
    volume: number;
    openPrice: number;
    currentPrice: number;
    openTime: string;
    sl: number;
    tp: number;
    swap: number;
    commission: number;
    unrealizedPnL: number;
}

interface PendingOrder {
    id: string;
    symbol: string;
    type: 'MARKET' | 'LIMIT' | 'STOP' | 'STOP_LIMIT';
    side: 'BUY' | 'SELL';
    volume: number;
    price: number;
    triggerPrice?: number;
    sl?: number;
    tp?: number;
    status: 'PENDING' | 'TRIGGERED' | 'FILLED' | 'CANCELLED';
    createdAt: string;
}

type TabType = 'Positions' | 'Orders';

interface PositionsPanelProps {
    accountId: string;
    wsConnection: WebSocket | null;
}

interface EditingState {
    positionId: number;
    field: 'sl' | 'tp';
    value: string;
}

const toNumber = (value: unknown, fallback = 0): number => {
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
};

const normalizePosition = (raw: Record<string, any>, index: number): Position => {
    const parsedId = Number.parseInt(String(raw.id ?? index + 1), 10);
    const openPrice = toNumber(raw.open_price ?? raw.openPrice ?? raw.price, 0);
    const currentPrice = toNumber(raw.current_price ?? raw.currentPrice, openPrice);
    const rawSide = String(raw.side ?? '').toUpperCase();

    return {
        id: Number.isFinite(parsedId) ? parsedId : index + 1,
        symbol: String(raw.symbol ?? ''),
        side: rawSide === 'SELL' || rawSide === 'SHORT' ? 'SELL' : 'BUY',
        volume: toNumber(raw.quantity ?? raw.volume, 0),
        openPrice,
        currentPrice,
        openTime: String(raw.opened_at ?? raw.openTime ?? new Date().toISOString()),
        sl: toNumber(raw.sl, 0),
        tp: toNumber(raw.tp, 0),
        swap: toNumber(raw.swap, 0),
        commission: toNumber(raw.commission, 0),
        unrealizedPnL: toNumber(raw.unrealized_pl ?? raw.unrealizedPnL, 0),
    };
};

const normalizeOrder = (raw: Record<string, any>, index: number): PendingOrder => {
    const side = String(raw.side ?? '').toUpperCase() === 'SELL' ? 'SELL' : 'BUY';
    const type = String(raw.type ?? '').toUpperCase();
    const normalizedType: PendingOrder['type'] =
        type === 'STOP_LIMIT' ? 'STOP_LIMIT' :
            type === 'STOP' ? 'STOP' :
                type === 'LIMIT' ? 'LIMIT' : 'MARKET';
    const status = String(raw.status ?? '').toUpperCase();

    return {
        id: String(raw.id ?? index + 1),
        symbol: String(raw.symbol ?? ''),
        type: normalizedType,
        side,
        volume: toNumber(raw.quantity ?? raw.volume, 0),
        price: toNumber(raw.price, 0),
        triggerPrice: toNumber(raw.stop_price ?? raw.triggerPrice, 0),
        sl: toNumber(raw.sl, 0),
        tp: toNumber(raw.tp, 0),
        status: status === 'PENDING' || status === 'TRIGGERED' || status === 'FILLED' || status === 'CANCELLED'
            ? status
            : 'PENDING',
        createdAt: String(raw.created_at ?? raw.createdAt ?? new Date().toISOString()),
    };
};

const getSymbolDigits = (symbol: string) => {
    if (symbol.includes('JPY')) return 3;
    if (symbol.startsWith('BTC') || symbol.startsWith('ETH') || symbol.startsWith('XAU')) return 2;
    if (symbol.startsWith('XAG')) return 3;
    return 5;
};

// Helper to get auth headers
const getAuthHeaders = (): Record<string, string> => {
    const token = localStorage.getItem('auth_token');
    return token ? { 'Authorization': `Bearer ${token}` } : {};
};

// High-frequency live Total PnL component
function LiveTotalPnL({ positions }: { positions: Position[] }) {
    // Subscribe only to ticks, avoid re-rendering entire PositionsPanel
    const symbolsData = useMarketDataStore(state => state.symbolData);

    const liveTotalPnL = useMemo(() => {
        return positions.reduce((sum, pos) => {
            let livePnL = pos.unrealizedPnL;
            const tick = symbolsData[pos.symbol]?.currentTick;

            if (tick && pos.openPrice > 0) {
                const livePrice = pos.side === 'BUY' ? tick.bid : tick.ask;
                let multiplier = 100000;
                if (pos.symbol.includes('JPY')) multiplier = 1000;
                else if (pos.symbol.startsWith('BTC') || pos.symbol.startsWith('ETH')) multiplier = 1;
                else if (pos.symbol.startsWith('XAU')) multiplier = 100;
                else if (pos.symbol.startsWith('XAG')) multiplier = 5000;

                const pipDiff = pos.side === 'BUY' ? (livePrice - pos.openPrice) : (pos.openPrice - livePrice);
                livePnL = pipDiff * pos.volume * multiplier;
            }
            return sum + livePnL;
        }, 0);
    }, [positions, symbolsData]);

    const formatMoney = (val: number | undefined | null) => {
        const v = val ?? 0;
        if (isNaN(v)) return '0.00';
        const parts = v.toFixed(2).split('.');
        parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, " ");
        return parts.join('.');
    };

    return (
        <span>
            Total P&L: <span className={`${liveTotalPnL >= 0 ? "text-[#4ade80]" : "text-[#f87171]"} font-bold px-1 rounded-sm`}>
                {formatMoney(liveTotalPnL)}
            </span>
        </span>
    );
}

// Component to handle individual live row updates efficiently
function PositionRow({
    pos,
    i,
    editing,
    setEditing,
    handleModifySLTP,
    setShowPartialClose,
    handleClosePosition,
    loading,
    onDoubleClick
}: {
    pos: Position,
    i: number,
    editing: EditingState | null,
    setEditing: (state: EditingState | null) => void,
    handleModifySLTP: (id: number, field: 'sl' | 'tp', value: string) => void,
    setShowPartialClose: (state: { positionId: number; maxVolume: number } | null) => void,
    handleClosePosition: (id: number) => void,
    loading: boolean,
    onDoubleClick: (pos: Position) => void
}) {
    const tick = useCurrentTick(pos.symbol);
    const digits = getSymbolDigits(pos.symbol);

    // If we have a live tick, recalculate the price
    // BUY position closes at BID, SELL position closes at ASK
    const livePrice = tick ? (pos.side === 'BUY' ? tick.bid : tick.ask) : pos.currentPrice;

    // Simple text color based on price direction (no blink)
    const priceColor = 'text-zinc-300';

    // Use ratio to estimate live PnL if original PnL is non-zero
    // (Actual MT5 PnL requires contract sizes, so ratio from live price change is safer)
    let livePnL = pos.unrealizedPnL;
    if (tick && pos.openPrice > 0) {
        let multiplier = 100000;
        if (pos.symbol.includes('JPY')) multiplier = 1000;
        else if (pos.symbol.startsWith('BTC') || pos.symbol.startsWith('ETH')) multiplier = 1;
        else if (pos.symbol.startsWith('XAU')) multiplier = 100;
        else if (pos.symbol.startsWith('XAG')) multiplier = 5000;

        const pipDiff = pos.side === 'BUY' ? (livePrice - pos.openPrice) : (pos.openPrice - livePrice);
        livePnL = pipDiff * pos.volume * multiplier;
    }

    // Plain PnL color (no blink)
    const pnlColor = '';

    const formatMoney = (val: number | undefined | null) => {
        const v = val ?? 0;
        if (isNaN(v)) return '0.00';
        const parts = v.toFixed(2).split('.');
        parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, " ");
        return parts.join('.');
    };

    const formatDate = (dateStr: string) => {
        try {
            return new Date(dateStr).toLocaleString('en-US', {
                year: 'numeric', month: '2-digit', day: '2-digit',
                hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
            }).replace(',', '');
        } catch {
            return dateStr;
        }
    };

    return (
        <tr className={`${i % 2 === 0 ? 'bg-[#131316]' : 'bg-[#0f0f12]'} hover:bg-[#191a1e] transition-colors group cursor-pointer`} onDoubleClick={() => onDoubleClick(pos)}>
            <td className="px-1 py-[2px] pl-2 text-zinc-500">{pos.id}</td>
            <td className="px-1 py-[2px] font-bold text-zinc-100">{pos.symbol}</td>
            <td className={`px-1 py-[2px] font-bold text-[10px] ${pos.side === 'BUY' ? 'text-blue-400' : 'text-red-400'}`}>
                {pos.side}
            </td>
            <td className="px-1 py-[2px] text-right font-medium text-zinc-200">{pos.volume.toFixed(2)}</td>
            <td className="px-1 py-[2px] text-right text-zinc-400"><PriceDisplay price={pos.openPrice} symbol={pos.symbol} /></td>
            <td className={`px-1 py-[2px] text-right ${priceColor}`}><PriceDisplay price={livePrice} symbol={pos.symbol} /></td>
            {/* SL - Inline Editing */}
            <td className="px-1 py-[2px] text-right">
                {editing?.positionId === pos.id && editing.field === 'sl' ? (
                    <input
                        type="number"
                        step="0.00001"
                        value={editing.value}
                        onChange={(e) => setEditing({ ...editing, value: e.target.value })}
                        onBlur={() => handleModifySLTP(pos.id, 'sl', editing.value)}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter') handleModifySLTP(pos.id, 'sl', editing.value);
                            if (e.key === 'Escape') setEditing(null);
                        }}
                        autoFocus
                        className="w-full bg-zinc-800 text-zinc-100 px-1 py-0.5 rounded text-[11px] font-mono"
                    />
                ) : (
                    <div
                        onClick={() => setEditing({ positionId: pos.id, field: 'sl', value: pos.sl.toString() })}
                        className="cursor-pointer hover:bg-zinc-700 rounded px-1"
                    >
                        <span className={pos.sl > 0 ? "text-red-300" : "text-zinc-600"}>
                            {pos.sl > 0 ? <PriceDisplay price={pos.sl} symbol={pos.symbol} /> : 'ΓÇö'}
                        </span>
                    </div>
                )}
            </td>
            {/* TP - Inline Editing */}
            <td className="px-1 py-[2px] text-right">
                {editing?.positionId === pos.id && editing.field === 'tp' ? (
                    <input
                        type="number"
                        step="0.00001"
                        value={editing.value}
                        onChange={(e) => setEditing({ ...editing, value: e.target.value })}
                        onBlur={() => handleModifySLTP(pos.id, 'tp', editing.value)}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter') handleModifySLTP(pos.id, 'tp', editing.value);
                            if (e.key === 'Escape') setEditing(null);
                        }}
                        autoFocus
                        className="w-full bg-zinc-800 text-zinc-100 px-1 py-0.5 rounded text-[11px] font-mono"
                    />
                ) : (
                    <div
                        onClick={() => setEditing({ positionId: pos.id, field: 'tp', value: pos.tp.toString() })}
                        className="cursor-pointer hover:bg-zinc-700 rounded px-1"
                    >
                        <span className={pos.tp > 0 ? "text-emerald-300" : "text-zinc-600"}>
                            {pos.tp > 0 ? <PriceDisplay price={pos.tp} symbol={pos.symbol} /> : 'ΓÇö'}
                        </span>
                    </div>
                )}
            </td>
            <td className={`px-1 py-[2px] text-right font-bold ${livePnL >= 0 ? 'text-[#4ade80]' : 'text-[#f87171]'} ${pnlColor}`}>
                {formatMoney(livePnL)}
            </td>
            <td className="px-1 py-[2px] text-right text-zinc-500 text-[10px]">{formatMoney(pos.swap)}</td>
            <td className="px-1 py-[2px] text-zinc-500 text-[10px]">{formatDate(pos.openTime).split(' ')[1]}</td>
            <td className="px-1 py-[2px] pr-2">
                <div className="flex items-center gap-1">
                    <button
                        onClick={() => setShowPartialClose({ positionId: pos.id, maxVolume: pos.volume })}
                        className="text-zinc-600 hover:text-yellow-400 hover:bg-zinc-700 w-5 h-5 rounded flex items-center justify-center transition-colors"
                        title="Partial Close"
                        disabled={loading}
                    >
                        <Icon name="trending-down" size="xs" />
                    </button>
                    <button
                        onClick={() => handleClosePosition(pos.id)}
                        className="text-zinc-600 hover:text-white hover:bg-zinc-700 w-5 h-5 rounded flex items-center justify-center transition-colors"
                        title="Close Position"
                        disabled={loading}
                    >
                        <Icon name="x-close" size="xs" />
                    </button>
                </div>
            </td>
        </tr>
    );
}

