/**
 * Risk Heatmap / Exposure Map
 * Comprehensive risk visualization with exposure analysis and concentration warnings
 */

import { Icon } from './ui/Icon';
import { useState, useMemo, useEffect } from 'react';
import { api } from '../services/api';

interface Position {
    id: number;
    symbol: string;
    side: 'BUY' | 'SELL';
    volume: number;
    openPrice: number;
    currentPrice: number;
    unrealizedPnL: number;
    margin: number;
}

// Positions come from the centralized API now

// Extract currency from symbol
function getCurrencies(symbol: string): { base: string; quote: string } {
    return {
        base: symbol.substring(0, 3),
        quote: symbol.substring(3, 6)
    };
}

// Get color based on intensity (0-1 scale)
function getIntensityColor(value: number, maxValue: number, type: 'profit' | 'loss' | 'neutral'): string {
    const intensity = Math.min(value / maxValue, 1);

    if (type === 'profit') {
        // Green gradient
        const g = Math.round(185 * intensity + 40 * (1 - intensity));
        return `rgb(40, ${g}, 100)`;
    } else if (type === 'loss') {
        // Red gradient
        const r = Math.round(239 * intensity + 40 * (1 - intensity));
        return `rgb(${r}, 68, 68)`;
    } else {
        // Blue gradient for neutral
        const b = Math.round(130 * intensity + 60 * (1 - intensity));
        return `rgb(60, 80, ${b})`;
    }
}

export function RiskHeatmap({ accountId }: { accountId?: string }) {
    const [positions, setPositions] = useState<Position[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchPositions = async () => {
            try {
                setLoading(true);
                const data = await api.positions.getPositions();
                // Map the Position[] response to the component's internal Position interface
                const mappedPositions: Position[] = data.map(p => ({
                    id: Number(p.id) || Math.random(),
                    symbol: p.symbol,
                    side: p.side.toUpperCase() as 'BUY' | 'SELL',
                    volume: p.quantity,
                    openPrice: p.open_price,
                    currentPrice: p.current_price,
                    unrealizedPnL: p.unrealized_pl,
                    margin: 0 // Margin might not be available per-position in current endpoint
                }));
                setPositions(mappedPositions);
            } catch (err) {
                console.error('[RiskHeatmap] Failed to fetch positions:', err);
            } finally {
                setLoading(false);
            }
        };

        fetchPositions();
        const interval = setInterval(fetchPositions, 5000); // Polling every 5 seconds
        return () => clearInterval(interval);
    }, [accountId]);

    // Calculate exposures
    const { totalExposure, netLongExposure, netShortExposure, largestExposure, currencyExposure, totalMargin, totalPnL } = useMemo(() => {
        if (positions.length === 0) {
            return {
                totalExposure: 0,
                netLongExposure: 0,
                netShortExposure: 0,
                largestExposure: { symbol: 'N/A', percent: 0 },
                currencyExposure: {} as { [key: string]: { long: number; short: number } },
                totalMargin: 0,
                totalPnL: 0
            };
        }

        const totalExp = positions.reduce((sum, p) => sum + (p.volume * 100000), 0); // Notional value
        const longExp = positions.filter(p => p.side === 'BUY').reduce((sum, p) => sum + (p.volume * 100000), 0);
        const shortExp = positions.filter(p => p.side === 'SELL').reduce((sum, p) => sum + (p.volume * 100000), 0);

        // Find largest single exposure
        const sorted = [...positions].sort((a, b) => (b.volume * 100000) - (a.volume * 100000));
        const largest = sorted[0];
        const largestPct = totalExp > 0 ? ((largest.volume * 100000) / totalExp) * 100 : 0;

        // Currency exposure
        const currExp: { [key: string]: { long: number; short: number } } = {};
        positions.forEach(p => {
            const { base, quote } = getCurrencies(p.symbol);

            if (!currExp[base]) currExp[base] = { long: 0, short: 0 };
            if (!currExp[quote]) currExp[quote] = { long: 0, short: 0 };

            if (p.side === 'BUY') {
                currExp[base].long += p.volume;
                currExp[quote].short += p.volume;
            } else {
                currExp[base].short += p.volume;
                currExp[quote].long += p.volume;
            }
        });

        const margin = positions.reduce((sum, p) => sum + p.margin, 0);
        const pnl = positions.reduce((sum, p) => sum + p.unrealizedPnL, 0);

        return {
            totalExposure: totalExp,
            netLongExposure: longExp,
            netShortExposure: shortExp,
            largestExposure: { symbol: largest.symbol, percent: largestPct },
            currencyExposure: currExp,
            totalMargin: margin,
            totalPnL: pnl
        };
    }, [positions]);

    // Calculate concentration risk
    const concentration = useMemo(() => {
        const totalNotional = positions.reduce((sum, p) => sum + (p.volume * 100000), 0);
        return positions.map(p => ({
            symbol: p.symbol,
            percent: totalNotional > 0 ? ((p.volume * 100000) / totalNotional) * 100 : 0
        }));
    }, [positions]);

    const hasSingleConcentrationWarning = concentration.some(c => c.percent > 25);

    // Calculate risk metrics
    const riskMetrics = useMemo(() => {
        const balance = 100000; // Mock balance
        const equity = balance + totalPnL;
        const marginLevel = totalMargin > 0 ? (equity / totalMargin) * 100 : 0;
        const freeMargin = equity - totalMargin;

        // Simplified VaR (95% confidence, 1-day)
        const portfolioStdDev = positions.length > 0
            ? Math.sqrt(positions.reduce((sum, p) => sum + Math.pow(p.unrealizedPnL, 2), 0) / positions.length)
            : 0;
        const var95 = 1.65 * portfolioStdDev; // 95% confidence

        // Max drawdown potential (worst case all positions at SL)
        const maxDrawdown = positions.reduce((sum, p) => sum + Math.abs(p.unrealizedPnL) * 1.5, 0); // 1.5x current loss

        // Diversification score (1-10): more unique currencies = higher score
        const uniqueCurrencies = new Set(positions.flatMap(p => [getCurrencies(p.symbol).base, getCurrencies(p.symbol).quote]));
        const diversificationScore = Math.min(10, uniqueCurrencies.size);

        return {
            marginLevel,
            freeMargin,
            var95,
            maxDrawdown,
            diversificationScore
        };
    }, [positions, totalPnL, totalMargin]);

    // Format currency
    const formatMoney = (val: number) => new Intl.NumberFormat('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(val);
    const formatPnL = (val: number) => new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2, signDisplay: 'always' }).format(val);

    // Get max values for heatmap scaling
    const maxVolume = Math.max(1, ...positions.map(p => p.volume));
    const maxNotional = Math.max(1, ...positions.map(p => p.volume * 100000));
    const maxPnL = Math.max(1, ...positions.map(p => Math.abs(p.unrealizedPnL)));
    const maxMargin = Math.max(1, ...positions.map(p => p.margin));

    return (
        <div className="h-full flex flex-col bg-[#131316] text-zinc-300 overflow-auto scrollbar-thin scrollbar-thumb-zinc-700">
            {/* Exposure Summary Bar */}
            <div className="bg-[#191a1e] border-b border-zinc-700 p-4 flex-shrink-0">
                <div className="grid grid-cols-4 gap-4">
                    <div>
                        <div className="text-xs text-zinc-500 mb-1">Total Exposure</div>
                        <div className="text-lg font-bold text-zinc-100">${formatMoney(totalExposure)}</div>
                    </div>
                    <div>
                        <div className="text-xs text-zinc-500 mb-1">Net Long / Short</div>
                        <div className="flex items-center gap-2">
                            <span className="text-sm text-green-400">${formatMoney(netLongExposure)}</span>
                            <span className="text-zinc-600">/</span>
                            <span className="text-sm text-red-400">${formatMoney(netShortExposure)}</span>
                        </div>
                    </div>
                    <div>
                        <div className="text-xs text-zinc-500 mb-1">Largest Single Exposure</div>
                        <div className="text-sm font-medium text-zinc-100">
                            {largestExposure.symbol} ({largestExposure.percent.toFixed(1)}%)
                            {largestExposure.percent > 25 && (
                                <Icon name="alert-triangle" size="sm" className="inline w-4 h-4 ml-1 text-yellow-400" />
                            )}
                        </div>
                    </div>
                    <div>
                        <div className="text-xs text-zinc-500 mb-1">Total P&L</div>
                        <div className={`text-lg font-bold ${totalPnL >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                            {formatPnL(totalPnL)}
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex-1 p-4 space-y-6 overflow-y-auto">
                {/* Heatmap Grid */}
                <div>
                    <h3 className="text-sm font-semibold text-zinc-400 mb-3 flex items-center gap-2">
                        <Icon name="shield" size="sm" className="w-4 h-4" />
                        Position Exposure Heatmap
                    </h3>
                    <div className="overflow-x-auto">
                        <table className="w-full border-collapse">
                            <thead className="bg-[#191a1e] text-zinc-400 text-[10px] uppercase">
                                <tr>
                                    <th className="p-2 text-left border border-zinc-700">Symbol</th>
                                    <th className="p-2 text-left border border-zinc-700">Side</th>
                                    <th className="p-2 text-right border border-zinc-700">Volume</th>
                                    <th className="p-2 text-right border border-zinc-700">Notional Value</th>
                                    <th className="p-2 text-right border border-zinc-700">Unrealized P&L</th>
                                    <th className="p-2 text-right border border-zinc-700">% of Portfolio</th>
                                    <th className="p-2 text-right border border-zinc-700">Margin Used</th>
                                </tr>
                            </thead>
                            <tbody className="text-xs font-mono">
                                {positions.map((pos, i) => {
                                    const notional = pos.volume * 100000;
                                    const pctPortfolio = (notional / totalExposure) * 100;

                                    return (
                                        <tr key={pos.id} className={i % 2 === 0 ? 'bg-[#131316]' : 'bg-[#0f0f12]'}>
                                            <td className="p-2 border border-zinc-800 font-bold text-zinc-100">{pos.symbol}</td>
                                            <td className={`p-2 border border-zinc-800 font-bold ${pos.side === 'BUY' ? 'text-blue-400' : 'text-red-400'}`}>
                                                {pos.side}
                                            </td>
                                            <td
                                                className="p-2 border border-zinc-800 text-right"
                                                style={{ backgroundColor: getIntensityColor(pos.volume, maxVolume, 'neutral') }}
                                                title={`${pos.volume.toFixed(2)} lots`}
                                            >
                                                {pos.volume.toFixed(2)}
                                            </td>
                                            <td
                                                className="p-2 border border-zinc-800 text-right"
                                                style={{ backgroundColor: getIntensityColor(notional, maxNotional, 'neutral') }}
                                                title={`$${formatMoney(notional)}`}
                                            >
                                                ${formatMoney(notional)}
                                            </td>
                                            <td
                                                className="p-2 border border-zinc-800 text-right font-bold"
                                                style={{ backgroundColor: getIntensityColor(Math.abs(pos.unrealizedPnL), maxPnL, pos.unrealizedPnL >= 0 ? 'profit' : 'loss') }}
                                                title={formatPnL(pos.unrealizedPnL)}
                                            >
                                                {formatPnL(pos.unrealizedPnL)}
                                            </td>
                                            <td className="p-2 border border-zinc-800 text-right">
                                                {pctPortfolio.toFixed(1)}%
                                                {pctPortfolio > 25 && <Icon name="alert-triangle" size="sm" className="inline w-3 h-3 ml-1 text-yellow-400" />}
                                            </td>
                                            <td
                                                className="p-2 border border-zinc-800 text-right"
                                                style={{ backgroundColor: getIntensityColor(pos.margin, maxMargin, 'neutral') }}
                                                title={`$${formatMoney(pos.margin)}`}
                                            >
                                                ${formatMoney(pos.margin)}
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Currency Exposure Chart */}
                <div>
                    <h3 className="text-sm font-semibold text-zinc-400 mb-3">Currency Exposure</h3>
                    <div className="space-y-2">
                        {Object.entries(currencyExposure).map(([currency, exposure]) => {
                            const netExposure = exposure.long - exposure.short;
                            const totalCurrExposure = exposure.long + exposure.short;
                            const longPct = totalCurrExposure > 0 ? (exposure.long / totalCurrExposure) * 100 : 50;
                            const shortPct = totalCurrExposure > 0 ? (exposure.short / totalCurrExposure) * 100 : 50;

                            return (
                                <div key={currency} className="bg-zinc-900 rounded p-2">
                                    <div className="flex items-center justify-between mb-1">
                                        <span className="text-xs font-bold text-zinc-300">{currency}</span>
                                        <span className={`text-xs font-mono ${netExposure >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                                            Net: {netExposure >= 0 ? '+' : ''}{netExposure.toFixed(2)} lots
                                        </span>
                                    </div>
                                    <div className="flex h-6 rounded overflow-hidden">
                                        <div
                                            className="bg-green-600 flex items-center justify-center text-[10px] text-white font-bold"
                                            style={{ width: `${longPct}%` }}
                                        >
                                            {exposure.long > 0.1 && `Long ${exposure.long.toFixed(1)}`}
                                        </div>
                                        <div
                                            className="bg-red-600 flex items-center justify-center text-[10px] text-white font-bold"
                                            style={{ width: `${shortPct}%` }}
                                        >
                                            {exposure.short > 0.1 && `Short ${exposure.short.toFixed(1)}`}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Concentration Risk & Risk Metrics Grid */}
                <div className="grid grid-cols-2 gap-6">
                    {/* Concentration Risk */}
                    <div>
                        <h3 className="text-sm font-semibold text-zinc-400 mb-3">Concentration Risk</h3>
                        <div className="bg-zinc-900 rounded p-4">
                            {hasSingleConcentrationWarning && (
                                <div className="flex items-center gap-2 mb-3 p-2 bg-yellow-500/10 border border-yellow-500/30 rounded">
                                    <Icon name="alert-triangle" size="sm" className="w-4 h-4 text-yellow-400" />
                                    <span className="text-xs text-yellow-400">High concentration detected (&gt;25% in single symbol)</span>
                                </div>
                            )}
                            <div className="space-y-1">
                                {concentration.slice(0, 5).map((c, i) => (
                                    <div key={c.symbol} className="flex items-center gap-2">
                                        <div className="w-20 text-xs font-mono text-zinc-400">{c.symbol}</div>
                                        <div className="flex-1 bg-zinc-800 rounded-full h-4 overflow-hidden">
                                            <div
                                                className={`h-full ${c.percent > 25 ? 'bg-yellow-500' : 'bg-zinc-600'}`}
                                                style={{ width: `${c.percent}%` }}
                                            />
                                        </div>
                                        <div className="w-12 text-xs font-mono text-right text-zinc-300">{c.percent.toFixed(1)}%</div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Risk Metrics */}
                    <div>
                        <h3 className="text-sm font-semibold text-zinc-400 mb-3">Risk Metrics</h3>
                        <div className="bg-zinc-900 rounded p-4 space-y-3">
                            <div className="flex items-center justify-between border-b border-zinc-800 pb-2">
                                <span className="text-xs text-zinc-500">Margin Level</span>
                                <span className={`text-sm font-bold ${riskMetrics.marginLevel > 200 ? 'text-green-400' : riskMetrics.marginLevel > 100 ? 'text-yellow-400' : 'text-red-400'}`}>
                                    {riskMetrics.marginLevel.toFixed(2)}%
                                </span>
                            </div>
                            <div className="flex items-center justify-between border-b border-zinc-800 pb-2">
                                <span className="text-xs text-zinc-500">Free Margin</span>
                                <span className="text-sm font-mono text-zinc-100">${formatMoney(riskMetrics.freeMargin)}</span>
                            </div>
                            <div className="flex items-center justify-between border-b border-zinc-800 pb-2">
                                <span className="text-xs text-zinc-500">Value at Risk (95%)</span>
                                <span className="text-sm font-mono text-red-400">${formatMoney(riskMetrics.var95)}</span>
                            </div>
                            <div className="flex items-center justify-between border-b border-zinc-800 pb-2">
                                <span className="text-xs text-zinc-500">Max Drawdown Potential</span>
                                <span className="text-sm font-mono text-red-400">${formatMoney(riskMetrics.maxDrawdown)}</span>
                            </div>
                            <div className="flex items-center justify-between">
                                <span className="text-xs text-zinc-500">Diversification Score</span>
                                <div className="flex items-center gap-2">
                                    <div className="flex gap-0.5">
                                        {[...Array(10)].map((_, i) => (
                                            <div
                                                key={i}
                                                className={`w-2 h-4 rounded-sm ${i < riskMetrics.diversificationScore ? 'bg-zinc-600' : 'bg-zinc-700'}`}
                                            />
                                        ))}
                                    </div>
                                    <span className="text-sm font-bold text-zinc-100">{riskMetrics.diversificationScore}/10</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

/**
 * Routing Metrics Dashboard Component
 * Real-time A/B/C-Book routing analytics with charts
 * Features: Distribution charts, timeline, confidence levels, WebSocket updates
 */

import { Icon } from './ui/Icon';
import { useState, useEffect, useRef, useMemo } from 'react';
import {
  createChart,
  type IChartApi,
  type LineData,
  type HistogramData,
  ColorType,
} from 'lightweight-charts';
import { getWebSocketService } from '../services/websocket';
import { useAppStore } from '../store/useAppStore';
import { API_BASE_URL as API_BASE, WS_ENDPOINTS } from '../config/api';
import { Activity, TrendingUp, Filter } from 'lucide-react';

// ============================================
// Type Definitions
// ============================================

type BookType = 'ABOOK' | 'BBOOK' | 'CBOOK';

type TimeRange = '1h' | '4h' | '24h' | '7d' | '30d' | 'custom';

type RoutingDecision = {
  timestamp: number;
  symbol: string;
  book: BookType;
  confidence: number;
  volume: number;
  reason: string;
};

type RoutingMetrics = {
  totalDecisions: number;
  breakdown: {
    ABOOK: number;
    BBOOK: number;
    CBOOK: number;
  };
  avgConfidence: number;
  recentDecisions: RoutingDecision[];
  timeline: Array<{
    timestamp: number;
    ABOOK: number;
    BBOOK: number;
    CBOOK: number;
  }>;
  confidenceDistribution: Array<{
    range: string;
    count: number;
  }>;
};

type RoutingMetricsDashboardProps = {
  className?: string;
};

// ============================================
// Component
// ============================================

export const RoutingMetricsDashboard = ({ className = '' }: RoutingMetricsDashboardProps) => {
  const { accountId, authToken } = useAppStore();

  // State
  const [metrics, setMetrics] = useState<RoutingMetrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [timeRange, setTimeRange] = useState<TimeRange>('24h');
  const [selectedSymbol, setSelectedSymbol] = useState<string>('');
  const [symbols, setSymbols] = useState<string[]>([]);
  const [autoRefresh, setAutoRefresh] = useState(true);

  // Chart refs
  const timelineChartRef = useRef<HTMLDivElement>(null);
  const confidenceChartRef = useRef<HTMLDivElement>(null);
  const timelineChart = useRef<IChartApi | null>(null);
  const confidenceChart = useRef<IChartApi | null>(null);

  // ============================================
  // Data Fetching
  // ============================================

  const fetchMetrics = async () => {
    if (!accountId) return;

    setLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams({
        accountId,
        timeRange,
        ...(selectedSymbol && { symbol: selectedSymbol }),
      });

      const response = await fetch(
        `${API_BASE}/api/routing/metrics?${params}`,
        {
          headers: authToken ? { Authorization: `Bearer ${authToken}` } : {},
        }
      );

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      setMetrics(data);
    } catch (err) {
      console.error('Failed to fetch routing metrics:', err);
      setError(err instanceof Error ? err.message : 'Failed to fetch metrics');
    } finally {
      setLoading(false);
    }
  };

  const fetchSymbols = async () => {
    try {
      const response = await fetch(`${API_BASE}/api/symbols`, {
        headers: authToken ? { Authorization: `Bearer ${authToken}` } : {},
      });

      if (response.ok) {
        const data = await response.json();
        setSymbols(data.map((s: { symbol: string }) => s.symbol));
      }
    } catch (err) {
      console.error('Failed to fetch symbols:', err);
    }
  };

  // ============================================
  // WebSocket Real-Time Updates
  // ============================================

  useEffect(() => {
    if (!accountId || !autoRefresh) return;

    const ws = getWebSocketService();
    ws.connect();

    const unsubscribe = ws.subscribe('routing_decisions', (data: RoutingDecision) => {
      // Filter by symbol if selected
      if (selectedSymbol && data.symbol !== selectedSymbol) return;

      // Update metrics with new decision
      setMetrics((prev) => {
        if (!prev) return prev;

        const newBreakdown = { ...prev.breakdown };
        newBreakdown[data.book] = (newBreakdown[data.book] || 0) + 1;

        return {
          ...prev,
          totalDecisions: prev.totalDecisions + 1,
          breakdown: newBreakdown,
          recentDecisions: [data, ...prev.recentDecisions.slice(0, 49)],
        };
      });
    });

    return () => {
      unsubscribe();
    };
  }, [accountId, selectedSymbol, autoRefresh]);

  // ============================================
  // Chart Initialization
  // ============================================

  useEffect(() => {
    if (!metrics) return;

    // Timeline Chart
    if (timelineChartRef.current && !timelineChart.current) {
      timelineChart.current = createChart(timelineChartRef.current, {
        width: timelineChartRef.current.clientWidth,
        height: 250,
        layout: {
          background: { type: ColorType.Solid, color: '#131316' },
          textColor: '#a1a1aa',
        },
        grid: {
          vertLines: { color: '#222226' },
          horzLines: { color: '#222226' },
        },
        timeScale: {
          borderColor: '#3f3f46',
          timeVisible: true,
          secondsVisible: false,
        },
        rightPriceScale: {
          borderColor: '#3f3f46',
        },
      });

      // Add series for each book type
      const abookSeries = (timelineChart.current as any).addAreaSeries({
        topColor: 'rgba(34, 197, 94, 0.4)',
        bottomColor: 'rgba(34, 197, 94, 0.0)',
        lineColor: 'rgba(34, 197, 94, 1)',
        lineWidth: 2,
        title: 'A-Book',
      });

      const bbookSeries = (timelineChart.current as any).addAreaSeries({
        topColor: 'rgba(59, 130, 246, 0.4)',
        bottomColor: 'rgba(59, 130, 246, 0.0)',
        lineColor: 'rgba(59, 130, 246, 1)',
        lineWidth: 2,
        title: 'B-Book',
      });

      const cbookSeries = (timelineChart.current as any).addAreaSeries({
        topColor: 'rgba(168, 85, 247, 0.4)',
        bottomColor: 'rgba(168, 85, 247, 0.0)',
        lineColor: 'rgba(168, 85, 247, 1)',
        lineWidth: 2,
        title: 'C-Book',
      });

      // Set data
      const abookData: LineData[] = metrics.timeline.map((t) => ({
        time: t.timestamp as any,
        value: t.ABOOK,
      }));

      const bbookData: LineData[] = metrics.timeline.map((t) => ({
        time: t.timestamp as any,
        value: t.BBOOK,
      }));

      const cbookData: LineData[] = metrics.timeline.map((t) => ({
        time: t.timestamp as any,
        value: t.CBOOK,
      }));

      abookSeries.setData(abookData);
      bbookSeries.setData(bbookData);
      cbookSeries.setData(cbookData);
    }

    // Confidence Distribution Chart
    if (confidenceChartRef.current && !confidenceChart.current) {
      confidenceChart.current = createChart(confidenceChartRef.current, {
        width: confidenceChartRef.current.clientWidth,
        height: 200,
        layout: {
          background: { type: ColorType.Solid, color: '#131316' },
          textColor: '#a1a1aa',
        },
        grid: {
          vertLines: { color: '#222226' },
          horzLines: { color: '#222226' },
        },
        timeScale: {
          borderColor: '#3f3f46',
          visible: false,
        },
        rightPriceScale: {
          borderColor: '#3f3f46',
        },
      });

      const histogramSeries = (confidenceChart.current as any).addHistogramSeries({
        color: '#8a8a8f',
        priceFormat: {
          type: 'volume',
        },
      });

      const histogramData: HistogramData[] = metrics.confidenceDistribution.map((d, idx) => ({
        time: idx as any,
        value: d.count,
        color: getConfidenceColor(d.range),
      }));

      histogramSeries.setData(histogramData);
    }

    // Handle resize
    const handleResize = () => {
      if (timelineChart.current && timelineChartRef.current) {
        timelineChart.current.resize(timelineChartRef.current.clientWidth, 250);
      }
      if (confidenceChart.current && confidenceChartRef.current) {
        confidenceChart.current.resize(confidenceChartRef.current.clientWidth, 200);
      }
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, [metrics]);

  // ============================================
  // Initial Data Load
  // ============================================

  useEffect(() => {
    fetchSymbols();
  }, []);

  useEffect(() => {
    fetchMetrics();

    // Auto-refresh every 30 seconds
    if (autoRefresh) {
      const interval = setInterval(fetchMetrics, 30000);
      return () => clearInterval(interval);
    }
  }, [accountId, timeRange, selectedSymbol, autoRefresh]);

  // ============================================
  // Computed Values
  // ============================================

  const bookPercentages = useMemo(() => {
    if (!metrics) return { ABOOK: 0, BBOOK: 0, CBOOK: 0 };

    const total = metrics.totalDecisions || 1;
    return {
      ABOOK: (metrics.breakdown.ABOOK / total) * 100,
      BBOOK: (metrics.breakdown.BBOOK / total) * 100,
      CBOOK: (metrics.breakdown.CBOOK / total) * 100,
    };
  }, [metrics]);

  // ============================================
  // Render
  // ============================================

  if (loading && !metrics) {
    return (
      <div className={`flex items-center justify-center h-full bg-zinc-900 ${className}`}>
        <div className="flex flex-col items-center gap-3">
          <Icon name="refresh" size="sm" className="w-8 h-8 text-blue-500 animate-spin" />
          <p className="text-sm text-zinc-500">Loading routing metrics...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className={`flex items-center justify-center h-full bg-zinc-900 ${className}`}>
        <div className="flex flex-col items-center gap-3 text-red-400">
          <Icon name="activity" size="sm" className="w-8 h-8" />
          <p className="text-sm">{error}</p>
          <button
            onClick={fetchMetrics}
            className="px-4 py-2 text-xs bg-red-600/20 hover:bg-red-600/30 border border-red-500/30 rounded transition-colors"
          >
            Retry
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className={`flex flex-col h-full bg-zinc-900 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-zinc-800">
        <div>
          <h3 className="text-sm font-semibold text-white flex items-center gap-2">
            <Icon name="bar-chart-3" size="sm" className="w-4 h-4 text-blue-500" />
            Routing Metrics Dashboard
          </h3>
          <p className="text-xs text-zinc-500">
            {metrics?.totalDecisions || 0} routing decisions
          </p>
        </div>

        {/* Controls */}
        <div className="flex items-center gap-3">
          {/* Symbol Filter */}
          <select
            value={selectedSymbol}
            onChange={(e) => setSelectedSymbol(e.target.value)}
            className="px-3 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-xs text-zinc-300 focus:outline-none focus:border-zinc-600"
          >
            <option value="">All Symbols</option>
            {symbols.map((symbol) => (
              <option key={symbol} value={symbol}>
                {symbol}
              </option>
            ))}
          </select>

          {/* Time Range */}
          <select
            value={timeRange}
            onChange={(e) => setTimeRange(e.target.value as TimeRange)}
            className="px-3 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-xs text-zinc-300 focus:outline-none focus:border-zinc-600"
          >
            <option value="1h">Last Hour</option>
            <option value="4h">Last 4 Hours</option>
            <option value="24h">Last 24 Hours</option>
            <option value="7d">Last 7 Days</option>
            <option value="30d">Last 30 Days</option>
          </select>

          {/* Auto Refresh Toggle */}
          <button
            onClick={() => setAutoRefresh(!autoRefresh)}
            className={`p-2 rounded transition-colors ${autoRefresh
              ? 'bg-blue-600 text-white'
              : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
              }`}
            title={autoRefresh ? 'Auto-refresh enabled' : 'Auto-refresh disabled'}
          >
            <Icon name="refresh" size="sm" className={`w-4 h-4 ${autoRefresh ? 'animate-spin' : ''}`} />
          </button>

          {/* Manual Refresh */}
          <button
            onClick={fetchMetrics}
            disabled={loading}
            className="px-3 py-1.5 bg-zinc-700 hover:bg-zinc-600 disabled:opacity-50 text-white rounded text-xs transition-colors"
          >
            Refresh
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-auto p-4 space-y-4">
        {/* Summary Cards */}
        <div className="grid grid-cols-4 gap-3">
          <SummaryCard
            label="Total Decisions"
            value={metrics?.totalDecisions.toLocaleString() || '0'}
            icon={Activity}
            color="blue"
          />
          <SummaryCard
            label="Avg Confidence"
            value={`${(metrics?.avgConfidence || 0).toFixed(1)}%`}
            icon={TrendingUp}
            color="green"
          />
          <SummaryCard
            label="A-Book"
            value={`${bookPercentages.ABOOK.toFixed(1)}%`}
            subtitle={`${metrics?.breakdown.ABOOK || 0} orders`}
            icon={Filter}
            color="green"
          />
          <SummaryCard
            label="B-Book"
            value={`${bookPercentages.BBOOK.toFixed(1)}%`}
            subtitle={`${metrics?.breakdown.BBOOK || 0} orders`}
            icon={Filter}
            color="blue"
          />
        </div>

        {/* Book Distribution Pie Chart */}
        <div className="bg-zinc-800/30 border border-zinc-800 rounded-lg p-4">
          <h4 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
            <Icon name="bar-chart-3" size="sm" className="w-4 h-4 text-blue-500" />
            A/B/C-Book Distribution
          </h4>
          <div className="grid grid-cols-3 gap-4">
            <BookDistributionCard
              book="A-Book"
              percentage={bookPercentages.ABOOK}
              count={metrics?.breakdown.ABOOK || 0}
              color="green"
            />
            <BookDistributionCard
              book="B-Book"
              percentage={bookPercentages.BBOOK}
              count={metrics?.breakdown.BBOOK || 0}
              color="blue"
            />
            <BookDistributionCard
              book="C-Book"
              percentage={bookPercentages.CBOOK}
              count={metrics?.breakdown.CBOOK || 0}
              color="purple"
            />
          </div>
        </div>

        {/* Timeline Chart */}
        <div className="bg-zinc-800/30 border border-zinc-800 rounded-lg p-4">
          <h4 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
            <Icon name="clock" size="sm" className="w-4 h-4 text-blue-500" />
            Routing Timeline
          </h4>
          <div ref={timelineChartRef} />
        </div>

        {/* Confidence Distribution */}
        <div className="bg-zinc-800/30 border border-zinc-800 rounded-lg p-4">
          <h4 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
            <Icon name="trending-up" size="sm" className="w-4 h-4 text-blue-500" />
            Confidence Distribution
          </h4>
          <div ref={confidenceChartRef} />
        </div>

        {/* Recent Decisions Table */}
        <div className="bg-zinc-800/30 border border-zinc-800 rounded-lg overflow-hidden">
          <div className="p-4 border-b border-zinc-800">
            <h4 className="text-sm font-semibold text-white flex items-center gap-2">
              <Icon name="activity" size="sm" className="w-4 h-4 text-blue-500" />
              Recent Routing Decisions
            </h4>
          </div>
          <div className="overflow-auto max-h-64">
            <table className="w-full text-sm">
              <thead className="sticky top-0 bg-zinc-900 border-b border-zinc-800">
                <tr className="text-xs text-zinc-500 text-left">
                  <th className="p-2">Time</th>
                  <th className="p-2">Symbol</th>
                  <th className="p-2">Book</th>
                  <th className="p-2">Confidence</th>
                  <th className="p-2">Volume</th>
                  <th className="p-2">Reason</th>
                </tr>
              </thead>
              <tbody>
                {metrics?.recentDecisions.slice(0, 20).map((decision, idx) => (
                  <tr
                    key={idx}
                    className="border-b border-zinc-800 hover:bg-zinc-900/50 transition-colors"
                  >
                    <td className="p-2 text-xs text-zinc-500 font-mono">
                      {new Date(decision.timestamp).toLocaleTimeString()}
                    </td>
                    <td className="p-2 font-medium text-white">{decision.symbol}</td>
                    <td className="p-2">
                      <span
                        className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${getBookBadgeClass(
                          decision.book
                        )}`}
                      >
                        {decision.book}
                      </span>
                    </td>
                    <td className="p-2 font-mono text-zinc-300">
                      {decision.confidence.toFixed(1)}%
                    </td>
                    <td className="p-2 font-mono text-zinc-300">{decision.volume.toFixed(2)}</td>
                    <td className="p-2 text-xs text-zinc-500">{decision.reason}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

// ============================================
// Helper Components
// ============================================

type SummaryCardProps = {
  label: string;
  value: string;
  subtitle?: string;
  icon: typeof Activity;
  color: string;
};

const SummaryCard = ({ label, value, subtitle, icon: Icon, color }: SummaryCardProps) => (
  <div className="flex flex-col gap-2 p-4 bg-zinc-800/30 rounded border border-zinc-800">
    <div className="flex items-center gap-2">
      <Icon className={`w-4 h-4 text-${color}-400`} />
      <span className="text-xs text-zinc-500">{label}</span>
    </div>
    <div className={`text-2xl font-bold text-${color}-400`}>{value}</div>
    {subtitle && <div className="text-xs text-zinc-500">{subtitle}</div>}
  </div>
);

type BookDistributionCardProps = {
  book: string;
  percentage: number;
  count: number;
  color: string;
};

const BookDistributionCard = ({ book, percentage, count, color }: BookDistributionCardProps) => (
  <div className="flex flex-col gap-2 p-4 bg-zinc-900/50 rounded border border-zinc-800">
    <div className="flex items-center justify-between">
      <span className="text-sm font-medium text-white">{book}</span>
      <span className={`text-lg font-bold text-${color}-400`}>{percentage.toFixed(1)}%</span>
    </div>
    <div className="w-full bg-zinc-800 rounded-full h-2 overflow-hidden">
      <div
        className={`h-full bg-${color}-500 transition-all duration-500`}
        style={{ width: `${percentage}%` }}
      />
    </div>
    <div className="text-xs text-zinc-500">{count.toLocaleString()} decisions</div>
  </div>
);

// ============================================
// Helper Functions
// ============================================

const getBookBadgeClass = (book: BookType): string => {
  switch (book) {
    case 'ABOOK':
      return 'bg-green-900/30 text-green-400';
    case 'BBOOK':
      return 'bg-blue-900/30 text-blue-400';
    case 'CBOOK':
      return 'bg-purple-900/30 text-purple-400';
    default:
      return 'bg-zinc-800 text-zinc-400';
  }
};

const getConfidenceColor = (range: string): string => {
  const value = parseInt(range.split('-')[0]);
  if (value >= 90) return '#22c55e'; // green
  if (value >= 70) return '#8a8a8f'; // blue
  if (value >= 50) return '#eab308'; // yellow
  return '#ef4444'; // red
};

/**
 * Routing Rules Management Panel
 * Allows admins to manage order routing rules with filters and priorities
 * Features: CRUD operations, drag-and-drop reordering, filter builder
 */

import { Icon } from './ui/Icon';
import { useState, useEffect } from 'react';
import { API_ENDPOINTS, buildApiUrl } from '../config/api';
import { GripVertical } from 'lucide-react';

// Type definitions for routing rules
type RoutingAction = 'A-Book' | 'B-Book' | 'Partial' | 'Reject';

type FilterCondition = {
  id: string;
  type: 'accountId' | 'userGroup' | 'symbol' | 'volumeRange';
  operator?: 'equals' | 'contains' | 'in' | 'between';
  value?: string | number | number[];
};

type RoutingRule = {
  id: string;
  priority: number;
  name: string;
  filters: FilterCondition[];
  action: RoutingAction;
  targetLP: string;
  hedgePercentage: number;
  enabled: boolean;
  createdAt: string;
  updatedAt: string;
};

export const RoutingRulesPanel = () => {
  const [rules, setRules] = useState<RoutingRule[]>([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingRule, setEditingRule] = useState<RoutingRule | null>(null);
  const [draggedItem, setDraggedItem] = useState<string | null>(null);
  const [liquidityProviders, setLiquidityProviders] = useState<string[]>([]);

  // Fetch data on mount
  useEffect(() => {
    fetchRules();
    fetchLiquidityProviders();
  }, []);

  const fetchRules = async () => {
    setLoading(true);
    try {
      const response = await fetch(API_ENDPOINTS.admin.routingRules);
      if (response.ok) {
        const data = await response.json();
        setRules(Array.isArray(data) ? data : []);
      }
    } catch (error) {
      console.error('Failed to fetch routing rules:', error);
      showMessage('error', 'Failed to load routing rules');
    } finally {
      setLoading(false);
    }
  };

  const fetchLiquidityProviders = async () => {
    try {
      const response = await fetch(buildApiUrl('/api/routing/liquidity-providers'));
      if (response.ok) {
        const data = await response.json();
        setLiquidityProviders(Array.isArray(data) ? data : []);
      }
    } catch (error) {
      console.error('Failed to fetch LPs:', error);
    }
  };

  const saveRule = async (rule: RoutingRule) => {
    try {
      const method = rule.id ? 'PUT' : 'POST';
      const endpoint = rule.id
        ? `${API_ENDPOINTS.admin.routingRules}/${rule.id}`
        : API_ENDPOINTS.admin.routingRules;

      const response = await fetch(endpoint, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(rule),
      });

      if (response.ok) {
        showMessage('success', `Rule ${rule.id ? 'updated' : 'created'} successfully`);
        await fetchRules();
        setIsFormOpen(false);
        setEditingRule(null);
      } else {
        const error = await response.text();
        showMessage('error', `Failed to save: ${error}`);
      }
    } catch (error) {
      showMessage('error', 'Failed to save rule');
    }
  };

  const deleteRule = async (id: string) => {
    if (!confirm('Are you sure you want to delete this rule?')) return;

    try {
      const response = await fetch(`${API_ENDPOINTS.admin.routingRules}/${id}`, {
        method: 'DELETE',
      });

      if (response.ok) {
        showMessage('success', 'Rule deleted successfully');
        await fetchRules();
      } else {
        showMessage('error', 'Failed to delete rule');
      }
    } catch (error) {
      showMessage('error', 'Failed to delete rule');
    }
  };

  const reorderRules = async (reorderedRules: RoutingRule[]) => {
    try {
      const response = await fetch(buildApiUrl('/api/routing/rules/reorder'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          rules: reorderedRules.map((r, idx) => ({ id: r.id, priority: idx })),
        }),
      });

      if (response.ok) {
        setRules(reorderedRules);
      }
    } catch (error) {
      console.error('Failed to reorder rules:', error);
    }
  };

  const handleDragStart = (id: string) => {
    setDraggedItem(id);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (targetId: string) => {
    if (!draggedItem || draggedItem === targetId) return;

    const draggedIdx = rules.findIndex((r) => r.id === draggedItem);
    const targetIdx = rules.findIndex((r) => r.id === targetId);

    const newRules = [...rules];
    [newRules[draggedIdx], newRules[targetIdx]] = [newRules[targetIdx], newRules[draggedIdx]];

    reorderRules(newRules);
    setDraggedItem(null);
  };

  const showMessage = (type: 'success' | 'error', text: string) => {
    setMessage({ type, text });
    setTimeout(() => setMessage(null), 3000);
  };

  const sortedRules = [...rules].sort((a, b) => a.priority - b.priority);

  return (
    <div className="flex flex-col h-full bg-zinc-900">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-zinc-800">
        <div>
          <h2 className="text-lg font-semibold text-white">Routing Rules</h2>
          <p className="text-xs text-zinc-500">Manage order routing logic and priorities</p>
        </div>
        <button
          onClick={() => {
            setEditingRule(null);
            setIsFormOpen(true);
          }}
          className="flex items-center gap-2 px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-black rounded font-medium transition-colors"
        >
          <Icon name="plus" size="sm" className="w-4 h-4" />
          New Rule
        </button>
      </div>

      {/* Message Toast */}
      {message && (
        <div
          className={`mx-4 mt-4 p-3 rounded border flex items-center gap-2 ${message.type === 'success'
              ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400'
              : 'bg-red-500/10 border-red-500/20 text-red-400'
            }`}
        >
          {message.type === 'success' ? (
            <Icon name="check-circle" size="sm" className="w-4 h-4" />
          ) : (
            <Icon name="error" size="sm" className="w-4 h-4" />
          )}
          <span className="text-sm">{message.text}</span>
        </div>
      )}

      {/* Form */}
      {isFormOpen && (
        <RuleForm
          rule={editingRule}
          liquidityProviders={liquidityProviders}
          onSave={saveRule}
          onCancel={() => {
            setIsFormOpen(false);
            setEditingRule(null);
          }}
        />
      )}

      {/* Rules List */}
      <div className="flex-1 overflow-auto p-4">
        {loading ? (
          <div className="flex items-center justify-center h-full text-zinc-500">
            <Icon name="refresh" size="sm" className="w-6 h-6 animate-spin mr-2" />
            Loading rules...
          </div>
        ) : sortedRules.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-zinc-500">
            <Icon name="error" size="sm" className="w-12 h-12 mb-2 text-zinc-700" />
            <p>No routing rules configured</p>
            <p className="text-xs text-zinc-600 mt-1">Create a new rule to get started</p>
          </div>
        ) : (
          <div className="space-y-2">
            {sortedRules.map((rule) => (
              <RuleRow
                key={rule.id}
                rule={rule}
                onEdit={() => {
                  setEditingRule(rule);
                  setIsFormOpen(true);
                }}
                onDelete={() => deleteRule(rule.id)}
                onDragStart={() => handleDragStart(rule.id)}
                onDragOver={handleDragOver}
                onDrop={() => handleDrop(rule.id)}
                isDragging={draggedItem === rule.id}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

// Individual Rule Row Component
const RuleRow = ({
  rule,
  onEdit,
  onDelete,
  onDragStart,
  onDragOver,
  onDrop,
  isDragging,
}: {
  rule: RoutingRule;
  onEdit: () => void;
  onDelete: () => void;
  onDragStart: () => void;
  onDragOver: (e: React.DragEvent) => void;
  onDrop: () => void;
  isDragging: boolean;
}) => {
  const [expanded, setExpanded] = useState(false);

  return (
    <div
      draggable
      onDragStart={onDragStart}
      onDragOver={onDragOver}
      onDrop={onDrop}
      className={`p-3 rounded-lg border transition-all ${isDragging
          ? 'bg-emerald-500/10 border-emerald-500/30 opacity-50'
          : 'bg-zinc-800/50 border-zinc-700 hover:bg-zinc-800'
        }`}
    >
      <div className="flex items-center gap-3">
        {/* Drag Handle */}
        <button
          onMouseDown={onDragStart}
          className="p-1 text-zinc-600 hover:text-zinc-400 cursor-grab active:cursor-grabbing"
        >
          <GripVertical className="w-4 h-4" />
        </button>

        {/* Priority Badge */}
        <div className="flex-shrink-0">
          <div className="w-8 h-8 rounded-full bg-emerald-500/20 text-emerald-400 flex items-center justify-center text-xs font-semibold">
            {rule.priority + 1}
          </div>
        </div>

        {/* Rule Info */}
        <div className="flex-1">
          <div className="flex items-center gap-2">
            <h3 className="font-medium text-white">{rule.name}</h3>
            <span
              className={`px-2 py-0.5 rounded text-xs font-medium ${rule.enabled
                  ? 'bg-emerald-500/20 text-emerald-400'
                  : 'bg-zinc-700 text-zinc-400'
                }`}
            >
              {rule.enabled ? 'Enabled' : 'Disabled'}
            </span>
          </div>
          <div className="flex items-center gap-4 mt-1 text-xs text-zinc-400">
            <span>Action: {rule.action}</span>
            <span>Target LP: {rule.targetLP}</span>
            <span>Hedge: {rule.hedgePercentage}%</span>
            <span>{rule.filters.length} filter(s)</span>
          </div>
        </div>

        {/* Expand Button */}
        <button
          onClick={() => setExpanded(!expanded)}
          className="p-1 text-zinc-600 hover:text-zinc-400"
        >
          <Icon name="chevron-down" size="sm"
            className={`w-4 h-4 transition-transform ${expanded ? 'rotate-180' : ''}`}
          />
        </button>

        {/* Action Buttons */}
        <button
          onClick={onEdit}
          className="p-1 text-zinc-600 hover:text-emerald-400 transition-colors"
          title="Edit rule"
        >
          <Icon name="edit" size="sm" className="w-4 h-4" />
        </button>
        <button
          onClick={onDelete}
          className="p-1 text-zinc-600 hover:text-red-400 transition-colors"
          title="Delete rule"
        >
          <Icon name="trash" size="sm" className="w-4 h-4" />
        </button>
      </div>

      {/* Expanded Filters View */}
      {expanded && rule.filters.length > 0 && (
        <div className="mt-3 pt-3 border-t border-zinc-700 space-y-2">
          <p className="text-xs text-zinc-500 font-medium">Filters:</p>
          {rule.filters.map((filter, idx) => (
            <div key={idx} className="text-xs text-zinc-400 ml-8">
              <span className="text-zinc-500">{filter.type}:</span>
              {filter.type === 'volumeRange' && Array.isArray(filter.value)
                ? ` ${filter.value[0]} - ${filter.value[1]}`
                : ` ${filter.value || 'any'}`}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

// Rule Form Component
const RuleForm = ({
  rule,
  liquidityProviders,
  onSave,
  onCancel,
}: {
  rule: RoutingRule | null;
  liquidityProviders: string[];
  onSave: (rule: RoutingRule) => void;
  onCancel: () => void;
}) => {
  const [formData, setFormData] = useState<Partial<RoutingRule>>(
    rule || {
      id: Math.random().toString(36).substr(2, 9),
      priority: 0,
      name: '',
      filters: [],
      action: 'A-Book' as RoutingAction,
      targetLP: '',
      hedgePercentage: 0,
      enabled: true,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    }
  );
  const [filterType, setFilterType] = useState<FilterCondition['type']>('accountId');
  const [filterValue, setFilterValue] = useState('');

  const addFilter = () => {
    if (!filterValue.trim()) return;

    const newFilter: FilterCondition = {
      id: Math.random().toString(36).substr(2, 9),
      type: filterType,
      operator: filterType === 'volumeRange' ? 'between' : 'equals',
      value: filterType === 'volumeRange' ? [0, 1000000] : filterValue,
    };

    setFormData({
      ...formData,
      filters: [...(formData.filters || []), newFilter],
    });
    setFilterValue('');
  };

  const removeFilter = (id: string) => {
    setFormData({
      ...formData,
      filters: formData.filters?.filter((f) => f.id !== id) || [],
    });
  };

  const handleSubmit = () => {
    if (!formData.name?.trim() || !formData.targetLP) {
      alert('Please fill in all required fields');
      return;
    }

    onSave({
      id: formData.id || Math.random().toString(36).substr(2, 9),
      priority: formData.priority || 0,
      name: formData.name,
      filters: formData.filters || [],
      action: formData.action || 'A-Book',
      targetLP: formData.targetLP,
      hedgePercentage: formData.hedgePercentage || 0,
      enabled: formData.enabled !== false,
      createdAt: formData.createdAt || new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    });
  };

  return (
    <div className="border-b border-zinc-800 p-4 bg-zinc-800/30 space-y-4">
      <h3 className="font-semibold text-white">
        {rule ? 'Edit Rule' : 'Create New Rule'}
      </h3>

      <div className="grid grid-cols-2 gap-4">
        {/* Rule Name */}
        <div className="space-y-2">
          <label className="text-xs text-zinc-400 font-medium">Rule Name</label>
          <input
            type="text"
            value={formData.name || ''}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            placeholder="e.g., High Volume EURUSD"
            className="w-full px-3 py-2 bg-zinc-700 border border-zinc-600 rounded text-white text-sm focus:outline-none focus:border-emerald-500"
          />
        </div>

        {/* Target LP */}
        <div className="space-y-2">
          <label className="text-xs text-zinc-400 font-medium">Target Liquidity Provider</label>
          <select
            value={formData.targetLP || ''}
            onChange={(e) => setFormData({ ...formData, targetLP: e.target.value })}
            className="w-full px-3 py-2 bg-zinc-700 border border-zinc-600 rounded text-white text-sm focus:outline-none focus:border-emerald-500"
          >
            <option value="">Select LP...</option>
            {liquidityProviders.map((lp) => (
              <option key={lp} value={lp}>
                {lp}
              </option>
            ))}
          </select>
        </div>

        {/* Action */}
        <div className="space-y-2">
          <label className="text-xs text-zinc-400 font-medium">Action</label>
          <select
            value={formData.action || 'A-Book'}
            onChange={(e) => setFormData({ ...formData, action: e.target.value as RoutingAction })}
            className="w-full px-3 py-2 bg-zinc-700 border border-zinc-600 rounded text-white text-sm focus:outline-none focus:border-emerald-500"
          >
            <option value="A-Book">A-Book (STP)</option>
            <option value="B-Book">B-Book (Market Maker)</option>
            <option value="Partial">Partial (Hybrid)</option>
            <option value="Reject">Reject</option>
          </select>
        </div>

        {/* Hedge Percentage */}
        <div className="space-y-2">
          <label className="text-xs text-zinc-400 font-medium">Hedge %</label>
          <input
            type="number"
            min="0"
            max="100"
            step="5"
            value={formData.hedgePercentage || 0}
            onChange={(e) =>
              setFormData({ ...formData, hedgePercentage: parseFloat(e.target.value) || 0 })
            }
            className="w-full px-3 py-2 bg-zinc-700 border border-zinc-600 rounded text-white text-sm focus:outline-none focus:border-emerald-500"
          />
        </div>
      </div>

      {/* Priority Slider */}
      <div className="space-y-2">
        <label className="text-xs text-zinc-400 font-medium">
          Priority: {formData.priority || 0}
        </label>
        <input
          type="range"
          min="0"
          max="100"
          value={formData.priority || 0}
          onChange={(e) => setFormData({ ...formData, priority: parseInt(e.target.value) })}
          className="w-full"
        />
      </div>

      {/* Filters Builder */}
      <div className="space-y-2">
        <label className="text-xs text-zinc-400 font-medium">Filters</label>
        <div className="flex gap-2">
          <select
            value={filterType}
            onChange={(e) => setFilterType(e.target.value as FilterCondition['type'])}
            className="px-3 py-2 bg-zinc-700 border border-zinc-600 rounded text-white text-sm focus:outline-none focus:border-emerald-500"
          >
            <option value="accountId">Account ID</option>
            <option value="userGroup">User Group</option>
            <option value="symbol">Symbol</option>
            <option value="volumeRange">Volume Range</option>
          </select>
          <input
            type="text"
            value={filterValue}
            onChange={(e) => setFilterValue(e.target.value)}
            placeholder="Filter value..."
            className="flex-1 px-3 py-2 bg-zinc-700 border border-zinc-600 rounded text-white text-sm focus:outline-none focus:border-emerald-500"
          />
          <button
            onClick={addFilter}
            className="px-3 py-2 bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 rounded text-sm font-medium hover:bg-emerald-500/30"
          >
            Add
          </button>
        </div>

        {/* Active Filters */}
        {formData.filters && formData.filters.length > 0 && (
          <div className="flex flex-wrap gap-2">
            {formData.filters.map((filter) => (
              <div
                key={filter.id}
                className="flex items-center gap-2 px-2 py-1 bg-emerald-500/10 border border-emerald-500/30 rounded text-xs text-emerald-400"
              >
                <span>
                  {filter.type}: {filter.value}
                </span>
                <button
                  onClick={() => removeFilter(filter.id)}
                  className="text-emerald-400 hover:text-red-400"
                >
                  ├ù
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Enable Toggle */}
      <div className="flex items-center gap-2">
        <input
          type="checkbox"
          id="enabled"
          checked={formData.enabled !== false}
          onChange={(e) => setFormData({ ...formData, enabled: e.target.checked })}
          className="w-4 h-4 rounded"
        />
        <label htmlFor="enabled" className="text-xs text-zinc-400">
          Enable this rule
        </label>
      </div>

      {/* Form Actions */}
      <div className="flex justify-end gap-2 pt-2">
        <button
          onClick={onCancel}
          className="px-4 py-2 bg-zinc-700 text-white rounded text-sm font-medium hover:bg-zinc-600"
        >
          Cancel
        </button>
        <button
          onClick={handleSubmit}
          className="px-4 py-2 bg-emerald-500 text-black rounded text-sm font-medium hover:bg-emerald-600"
        >
          {rule ? 'Update Rule' : 'Create Rule'}
        </button>
      </div>
    </div>
  );
};

/**
 * Rule Effectiveness Dashboard Component
 * Dynamic data-driven dashboard for analyzing trading rule performance
 * Features: Sortable rankings, performance charts, win rate distribution, drawdown analysis
 */

import { Icon } from './ui/Icon';
import { useState, useEffect, useMemo, useRef } from 'react';
import { createChart, ColorType, LineSeries, AreaSeries } from 'lightweight-charts';
import type { IChartApi } from 'lightweight-charts';
import { API_BASE_URL } from '../config/api';
import { Award, BarChart3, TrendingUp, Activity } from 'lucide-react';

// ============================================
// Types
// ============================================

type RuleMetrics = {
  ruleId: string;
  ruleName: string;
  totalTrades: number;
  winningTrades: number;
  losingTrades: number;
  winRate: number;
  totalPnL: number;
  grossProfit: number;
  grossLoss: number;
  profitFactor: number;
  sharpeRatio: number;
  maxDrawdown: number;
  maxDrawdownPercent: number;
  avgWin: number;
  avgLoss: number;
  largestWin: number;
  largestLoss: number;
  consecutiveWins: number;
  consecutiveLosses: number;
  avgTradeDuration: string;
  lastExecuted: string;
};

type TimeSeriesPoint = {
  time: number;
  value: number;
};

type SortField = keyof RuleMetrics;
type SortOrder = 'asc' | 'desc';
type TimeRange = '1D' | '1W' | '1M' | '3M' | 'ALL';

// ============================================
// Main Component
// ============================================

export const RuleEffectivenessDashboard = () => {
  const [rules, setRules] = useState<RuleMetrics[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>('sharpeRatio');
  const [sortOrder, setSortOrder] = useState<SortOrder>('desc');
  const [selectedRules, setSelectedRules] = useState<Set<string>>(new Set());
  const [timeRange, setTimeRange] = useState<TimeRange>('1M');
  const [_showTooltip, _setShowTooltip] = useState<string | null>(null);

  // Fetch rule metrics
  useEffect(() => {
    const fetchRules = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await fetch(`${API_BASE_URL}/api/analytics/rules/metrics?timeRange=${timeRange}`);

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }

        const data = await response.json();
        setRules(data || []);
      } catch (err) {
        console.error('Failed to fetch rule metrics:', err);
        setError(err instanceof Error ? err.message : 'Failed to load rule metrics');
        setRules([]);
      } finally {
        setLoading(false);
      }
    };

    fetchRules();
    const interval = setInterval(fetchRules, 30000); // Refresh every 30 seconds

    return () => clearInterval(interval);
  }, [timeRange]);

  // Sort rules
  const sortedRules = useMemo(() => {
    const sorted = [...rules].sort((a, b) => {
      const aValue = a[sortField];
      const bValue = b[sortField];

      if (typeof aValue === 'number' && typeof bValue === 'number') {
        return sortOrder === 'asc' ? aValue - bValue : bValue - aValue;
      }

      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortOrder === 'asc'
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue);
      }

      return 0;
    });

    return sorted;
  }, [rules, sortField, sortOrder]);

  // Calculate aggregate metrics
  const aggregateMetrics = useMemo(() => {
    if (rules.length === 0) {
      return {
        totalRules: 0,
        avgSharpe: 0,
        avgProfitFactor: 0,
        totalTrades: 0,
        overallWinRate: 0,
        bestSharpe: 0,
        worstDrawdown: 0,
      };
    }

    const totalTrades = rules.reduce((sum, r) => sum + r.totalTrades, 0);
    const totalWins = rules.reduce((sum, r) => sum + r.winningTrades, 0);

    return {
      totalRules: rules.length,
      avgSharpe: rules.reduce((sum, r) => sum + r.sharpeRatio, 0) / rules.length,
      avgProfitFactor: rules.reduce((sum, r) => sum + r.profitFactor, 0) / rules.length,
      totalTrades,
      overallWinRate: totalTrades > 0 ? (totalWins / totalTrades) * 100 : 0,
      bestSharpe: Math.max(...rules.map(r => r.sharpeRatio)),
      worstDrawdown: Math.min(...rules.map(r => r.maxDrawdownPercent)),
    };
  }, [rules]);

  // Handle sort
  const handleSort = (field: SortField) => {
    if (field === sortField) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('desc');
    }
  };

  // Handle rule selection
  const toggleRuleSelection = (ruleId: string) => {
    const newSelection = new Set(selectedRules);
    if (newSelection.has(ruleId)) {
      newSelection.delete(ruleId);
    } else {
      newSelection.add(ruleId);
    }
    setSelectedRules(newSelection);
  };

  // Get rank badge
  const getRankBadge = (index: number) => {
    if (index === 0) return { color: 'gold', icon: Award, label: '1st' };
    if (index === 1) return { color: 'silver', icon: Award, label: '2nd' };
    if (index === 2) return { color: 'bronze', icon: Award, label: '3rd' };
    return null;
  };

  return (
    <div className="flex flex-col h-full bg-zinc-900">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-zinc-800">
        <div>
          <h2 className="text-lg font-bold text-white">Rule Effectiveness Dashboard</h2>
          <p className="text-xs text-zinc-500">Performance metrics and rankings</p>
        </div>

        <div className="flex items-center gap-3">
          {/* Time Range Selector */}
          <div className="flex items-center gap-2 bg-zinc-800 rounded p-1">
            {(['1D', '1W', '1M', '3M', 'ALL'] as TimeRange[]).map((range) => (
              <button
                key={range}
                onClick={() => setTimeRange(range)}
                className={`px-3 py-1 rounded text-xs font-medium transition-colors ${timeRange === range
                  ? 'bg-emerald-500 text-white'
                  : 'text-zinc-400 hover:text-white'
                  }`}
              >
                {range}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Aggregate Metrics Cards */}
      <div className="grid grid-cols-4 gap-4 p-4 border-b border-zinc-800 bg-zinc-900/50">
        <MetricCard
          label="Total Rules"
          value={aggregateMetrics.totalRules.toString()}
          icon={BarChart3}
          color="blue"
          tooltip="Number of trading rules analyzed"
        />
        <MetricCard
          label="Avg Sharpe Ratio"
          value={aggregateMetrics.avgSharpe.toFixed(2)}
          icon={TrendingUp}
          color={aggregateMetrics.avgSharpe > 1 ? 'green' : aggregateMetrics.avgSharpe > 0 ? 'yellow' : 'red'}
          tooltip="Average risk-adjusted return (>1 is good, >2 is excellent)"
        />
        <MetricCard
          label="Avg Profit Factor"
          value={aggregateMetrics.avgProfitFactor.toFixed(2)}
          icon={Activity}
          color={aggregateMetrics.avgProfitFactor > 1.5 ? 'green' : aggregateMetrics.avgProfitFactor > 1 ? 'yellow' : 'red'}
          tooltip="Gross Profit / Gross Loss (>1.5 is good)"
        />
        <MetricCard
          label="Overall Win Rate"
          value={`${aggregateMetrics.overallWinRate.toFixed(1)}%`}
          icon={Award}
          color={aggregateMetrics.overallWinRate > 55 ? 'green' : aggregateMetrics.overallWinRate > 45 ? 'yellow' : 'red'}
          tooltip="Percentage of winning trades across all rules"
        />
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-auto">
        {loading && rules.length === 0 ? (
          <div className="flex items-center justify-center h-full text-zinc-500">
            <Icon name="clock" size="sm" className="w-6 h-6 animate-pulse mr-2" />
            Loading rule metrics...
          </div>
        ) : error ? (
          <div className="flex flex-col items-center justify-center h-full text-red-500">
            <Icon name="alert-triangle" size="sm" className="w-8 h-8 mb-2" />
            <p>{error}</p>
          </div>
        ) : rules.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-zinc-500">
            <Icon name="bar-chart-3" size="sm" className="w-8 h-8 mb-2 text-zinc-700" />
            <p>No rule data available</p>
            <p className="text-xs mt-1">Execute trades with rules to see metrics</p>
          </div>
        ) : (
          <div className="p-4 space-y-4">
            {/* Sortable Rule Ranking Table */}
            <div className="bg-zinc-800/30 rounded-lg border border-zinc-800 overflow-hidden">
              <div className="p-3 border-b border-zinc-800">
                <h3 className="text-sm font-semibold text-white flex items-center gap-2">
                  <Icon name="check-circle" size="sm" className="w-4 h-4" />
                  Rule Rankings
                  {selectedRules.size > 0 && (
                    <span className="text-xs text-emerald-400">
                      ({selectedRules.size} selected for comparison)
                    </span>
                  )}
                </h3>
              </div>

              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-zinc-900 border-b border-zinc-800">
                    <tr className="text-xs text-zinc-500">
                      <th className="p-2 text-left">
                        <input
                          type="checkbox"
                          className="rounded"
                          checked={selectedRules.size === rules.length}
                          onChange={(e) => {
                            if (e.target.checked) {
                              setSelectedRules(new Set(rules.map(r => r.ruleId)));
                            } else {
                              setSelectedRules(new Set());
                            }
                          }}
                        />
                      </th>
                      <th className="p-2 text-left">Rank</th>
                      <SortableHeader
                        label="Rule Name"
                        field="ruleName"
                        currentField={sortField}
                        currentOrder={sortOrder}
                        onSort={handleSort}
                      />
                      <SortableHeader
                        label="Sharpe Ratio"
                        field="sharpeRatio"
                        currentField={sortField}
                        currentOrder={sortOrder}
                        onSort={handleSort}
                        tooltip="Risk-adjusted return metric"
                      />
                      <SortableHeader
                        label="Profit Factor"
                        field="profitFactor"
                        currentField={sortField}
                        currentOrder={sortOrder}
                        onSort={handleSort}
                        tooltip="Gross Profit / Gross Loss"
                      />
                      <SortableHeader
                        label="Win Rate"
                        field="winRate"
                        currentField={sortField}
                        currentOrder={sortOrder}
                        onSort={handleSort}
                      />
                      <SortableHeader
                        label="Total P&L"
                        field="totalPnL"
                        currentField={sortField}
                        currentOrder={sortOrder}
                        onSort={handleSort}
                      />
                      <SortableHeader
                        label="Max DD %"
                        field="maxDrawdownPercent"
                        currentField={sortField}
                        currentOrder={sortOrder}
                        onSort={handleSort}
                        tooltip="Maximum drawdown percentage"
                      />
                      <SortableHeader
                        label="Trades"
                        field="totalTrades"
                        currentField={sortField}
                        currentOrder={sortOrder}
                        onSort={handleSort}
                      />
                    </tr>
                  </thead>
                  <tbody>
                    {sortedRules.map((rule, index) => {
                      const rankBadge = getRankBadge(index);
                      return (
                        <tr
                          key={rule.ruleId}
                          className="border-b border-zinc-800 hover:bg-zinc-900/50 transition-colors"
                        >
                          <td className="p-2">
                            <input
                              type="checkbox"
                              className="rounded"
                              checked={selectedRules.has(rule.ruleId)}
                              onChange={() => toggleRuleSelection(rule.ruleId)}
                            />
                          </td>
                          <td className="p-2">
                            {rankBadge ? (
                              <div className="flex items-center gap-1">
                                <rankBadge.icon
                                  className={`w-4 h-4 ${rankBadge.color === 'gold'
                                    ? 'text-yellow-400'
                                    : rankBadge.color === 'silver'
                                      ? 'text-zinc-400'
                                      : 'text-orange-600'
                                    }`}
                                />
                                <span className="text-xs font-medium text-zinc-400">
                                  {rankBadge.label}
                                </span>
                              </div>
                            ) : (
                              <span className="text-xs text-zinc-500">#{index + 1}</span>
                            )}
                          </td>
                          <td className="p-2 font-medium text-white">{rule.ruleName}</td>
                          <td className="p-2">
                            <MetricValue
                              value={rule.sharpeRatio}
                              format={(v) => v.toFixed(2)}
                              threshold={{ good: 1, excellent: 2 }}
                            />
                          </td>
                          <td className="p-2">
                            <MetricValue
                              value={rule.profitFactor}
                              format={(v) => v.toFixed(2)}
                              threshold={{ good: 1, excellent: 1.5 }}
                            />
                          </td>
                          <td className="p-2">
                            <MetricValue
                              value={rule.winRate}
                              format={(v) => `${v.toFixed(1)}%`}
                              threshold={{ good: 45, excellent: 55 }}
                            />
                          </td>
                          <td className="p-2">
                            <div
                              className={`font-mono font-bold ${rule.totalPnL >= 0 ? 'text-green-400' : 'text-red-400'
                                }`}
                            >
                              {rule.totalPnL >= 0 ? '+' : ''}${rule.totalPnL.toFixed(2)}
                            </div>
                          </td>
                          <td className="p-2">
                            <MetricValue
                              value={rule.maxDrawdownPercent}
                              format={(v) => `${v.toFixed(1)}%`}
                              threshold={{ good: -10, excellent: -5 }}
                              inverted
                            />
                          </td>
                          <td className="p-2 text-zinc-300 font-mono">{rule.totalTrades}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Win Rate Distribution */}
            {rules.length > 0 && (
              <WinRateDistribution rules={rules} />
            )}

            {/* Performance Timeline (if rules selected) */}
            {selectedRules.size > 0 && (
              <RulePerformanceChart
                selectedRuleIds={Array.from(selectedRules)}
                timeRange={timeRange}
              />
            )}

            {/* Drawdown Visualization (if rules selected) */}
            {selectedRules.size > 0 && (
              <DrawdownChart
                selectedRuleIds={Array.from(selectedRules)}
                timeRange={timeRange}
              />
            )}

            {/* Rule Comparison Table */}
            {selectedRules.size > 1 && (
              <RuleComparisonTable
                rules={rules.filter(r => selectedRules.has(r.ruleId))}
              />
            )}
          </div>
        )}
      </div>
    </div>
  );
};

// ============================================
// Metric Card Component
// ============================================

type MetricCardProps = {
  label: string;
  value: string;
  icon: React.ComponentType<{ className?: string }>;
  color: string;
  tooltip?: string;
};

const MetricCard = ({ label, value, icon: MetricIcon, color, tooltip }: MetricCardProps) => {
  const [showTooltip, setShowTooltip] = useState(false);

  const colorClasses = {
    blue: 'text-blue-400 border-zinc-600/20 bg-zinc-700/20',
    green: 'text-green-400 border-green-500/20 bg-green-500/10',
    yellow: 'text-yellow-400 border-yellow-500/20 bg-yellow-500/10',
    red: 'text-red-400 border-red-500/20 bg-red-500/10',
  }[color] || 'text-zinc-400 border-zinc-500/20 bg-zinc-500/10';

  return (
    <div className={`relative flex flex-col gap-2 p-4 rounded-lg border ${colorClasses}`}>
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <MetricIcon className={`w-5 h-5 text-${color}-400`} />
          <span className="text-xs text-zinc-400">{label}</span>
        </div>
        {tooltip && (
          <div
            className="relative"
            onMouseEnter={() => setShowTooltip(true)}
            onMouseLeave={() => setShowTooltip(false)}
          >
            <Icon name="info" size="sm" className="w-4 h-4 text-zinc-500 cursor-help" />
            {showTooltip && (
              <div className="absolute right-0 top-6 z-10 w-48 p-2 bg-zinc-950 border border-zinc-700 rounded text-xs text-zinc-300 shadow-lg">
                {tooltip}
              </div>
            )}
          </div>
        )}
      </div>
      <div className={`text-2xl font-bold text-${color}-400`}>{value}</div>
    </div>
  );
};

// ============================================
// Sortable Header Component
// ============================================

type SortableHeaderProps = {
  label: string;
  field: SortField;
  currentField: SortField;
  currentOrder: SortOrder;
  onSort: (field: SortField) => void;
  tooltip?: string;
};

const SortableHeader = ({
  label,
  field,
  currentField,
  currentOrder,
  onSort,
  tooltip,
}: SortableHeaderProps) => {
  const [showTooltip, setShowTooltip] = useState(false);
  const isActive = currentField === field;

  return (
    <th
      className="p-2 text-left cursor-pointer hover:text-emerald-400 transition-colors"
      onClick={() => onSort(field)}
    >
      <div className="flex items-center gap-1 relative">
        <span>{label}</span>
        {isActive && (
          currentOrder === 'asc' ? <Icon name="chevron-up" size="sm" className="w-3 h-3" /> : <Icon name="chevron-down" size="sm" className="w-3 h-3" />
        )}
        {tooltip && (
          <div
            className="relative"
            onMouseEnter={() => setShowTooltip(true)}
            onMouseLeave={() => setShowTooltip(false)}
          >
            <Icon name="info" size="sm" className="w-3 h-3 text-zinc-600 cursor-help" />
            {showTooltip && (
              <div className="absolute left-0 top-5 z-10 w-48 p-2 bg-zinc-950 border border-zinc-700 rounded text-xs text-zinc-300 shadow-lg font-normal">
                {tooltip}
              </div>
            )}
          </div>
        )}
      </div>
    </th>
  );
};

// ============================================
// Metric Value Component (with color coding)
// ============================================

type MetricValueProps = {
  value: number;
  format: (v: number) => string;
  threshold: { good: number; excellent: number };
  inverted?: boolean;
};

const MetricValue = ({ value, format, threshold, inverted = false }: MetricValueProps) => {
  let color = 'zinc';

  if (inverted) {
    if (value >= threshold.excellent) color = 'green';
    else if (value >= threshold.good) color = 'yellow';
    else color = 'red';
  } else {
    if (value >= threshold.excellent) color = 'green';
    else if (value >= threshold.good) color = 'yellow';
    else color = 'red';
  }

  return (
    <div className={`font-mono text-${color}-400 font-medium`}>
      {format(value)}
    </div>
  );
};

// ============================================
// Win Rate Distribution Component
// ============================================

type WinRateDistributionProps = {
  rules: RuleMetrics[];
};

const WinRateDistribution = ({ rules }: WinRateDistributionProps) => {
  const buckets = useMemo(() => {
    const ranges = [
      { min: 0, max: 30, label: '0-30%' },
      { min: 30, max: 40, label: '30-40%' },
      { min: 40, max: 50, label: '40-50%' },
      { min: 50, max: 60, label: '50-60%' },
      { min: 60, max: 70, label: '60-70%' },
      { min: 70, max: 100, label: '70%+' },
    ];

    return ranges.map(range => ({
      label: range.label,
      count: rules.filter(r => r.winRate >= range.min && r.winRate < range.max).length,
    }));
  }, [rules]);

  const maxCount = Math.max(...buckets.map(b => b.count), 1);

  return (
    <div className="bg-zinc-800/30 rounded-lg border border-zinc-800 p-4">
      <h3 className="text-sm font-semibold text-white mb-4 flex items-center gap-2">
        <Icon name="bar-chart-3" size="sm" className="w-4 h-4" />
        Win Rate Distribution
      </h3>
      <div className="space-y-3">
        {buckets.map((bucket) => (
          <div key={bucket.label} className="flex items-center gap-3">
            <div className="w-16 text-xs text-zinc-400">{bucket.label}</div>
            <div className="flex-1 bg-zinc-900 rounded-full h-6 overflow-hidden">
              <div
                className="h-full bg-gradient-to-r from-emerald-500 to-emerald-400 flex items-center justify-end px-2"
                style={{ width: `${(bucket.count / maxCount) * 100}%` }}
              >
                {bucket.count > 0 && (
                  <span className="text-xs font-medium text-white">{bucket.count}</span>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

// ============================================
// Rule Performance Chart Component
// ============================================

type RulePerformanceChartProps = {
  selectedRuleIds: string[];
  timeRange: TimeRange;
};

const RulePerformanceChart = ({ selectedRuleIds, timeRange }: RulePerformanceChartProps) => {
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!chartContainerRef.current) return;

    // Create chart
    const chart = createChart(chartContainerRef.current, {
      width: chartContainerRef.current.clientWidth,
      height: 300,
      layout: {
        background: { type: ColorType.Solid, color: 'transparent' },
        textColor: '#71717a',
      },
      grid: {
        vertLines: { color: '#222226' },
        horzLines: { color: '#222226' },
      },
      timeScale: {
        borderColor: '#3f3f46',
        timeVisible: true,
      },
      rightPriceScale: {
        borderColor: '#3f3f46',
      },
    });

    chartRef.current = chart;

    // Fetch and render data
    const fetchData = async () => {
      setLoading(true);
      try {
        const promises = selectedRuleIds.map(async (ruleId) => {
          const response = await fetch(
            `${API_BASE_URL}/api/analytics/rules/${ruleId}/pnl?timeRange=${timeRange}`
          );
          const data = await response.json();
          return { ruleId, data };
        });

        const results = await Promise.all(promises);

        // Add series for each rule
        const colors = ['#10b981', '#8a8a8f', '#f59e0b', '#8b5cf6', '#ec4899'];
        results.forEach((result, index) => {
          const series = chart.addSeries(LineSeries, {
            color: colors[index % colors.length],
            lineWidth: 2,
          });

          const formattedData = result.data.map((point: TimeSeriesPoint) => ({
            time: point.time,
            value: point.value,
          }));

          series.setData(formattedData);
        });

        chart.timeScale().fitContent();
      } catch (error) {
        console.error('Failed to fetch performance data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();

    // Handle resize
    const handleResize = () => {
      if (chartContainerRef.current && chartRef.current) {
        chartRef.current.applyOptions({
          width: chartContainerRef.current.clientWidth,
        });
      }
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      chart.remove();
    };
  }, [selectedRuleIds, timeRange]);

  return (
    <div className="bg-zinc-800/30 rounded-lg border border-zinc-800 p-4">
      <h3 className="text-sm font-semibold text-white mb-4 flex items-center gap-2">
        <Icon name="line-chart" size="sm" className="w-4 h-4" />
        Performance Timeline ({selectedRuleIds.length} rule{selectedRuleIds.length !== 1 ? 's' : ''})
      </h3>
      {loading && (
        <div className="flex items-center justify-center h-[300px] text-zinc-500">
          <Icon name="clock" size="sm" className="w-6 h-6 animate-pulse mr-2" />
          Loading chart data...
        </div>
      )}
      <div ref={chartContainerRef} className={loading ? 'hidden' : ''} />
    </div>
  );
};

// ============================================
// Drawdown Chart Component
// ============================================

type DrawdownChartProps = {
  selectedRuleIds: string[];
  timeRange: TimeRange;
};

const DrawdownChart = ({ selectedRuleIds, timeRange }: DrawdownChartProps) => {
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!chartContainerRef.current) return;

    const chart = createChart(chartContainerRef.current, {
      width: chartContainerRef.current.clientWidth,
      height: 250,
      layout: {
        background: { type: ColorType.Solid, color: 'transparent' },
        textColor: '#71717a',
      },
      grid: {
        vertLines: { color: '#222226' },
        horzLines: { color: '#222226' },
      },
      timeScale: {
        borderColor: '#3f3f46',
        timeVisible: true,
      },
      rightPriceScale: {
        borderColor: '#3f3f46',
      },
    });

    chartRef.current = chart;

    const fetchData = async () => {
      setLoading(true);
      try {
        const promises = selectedRuleIds.map(async (ruleId) => {
          const response = await fetch(
            `${API_BASE_URL}/api/analytics/rules/${ruleId}/drawdown?timeRange=${timeRange}`
          );
          const data = await response.json();
          return { ruleId, data };
        });

        const results = await Promise.all(promises);

        const colors = ['#ef4444', '#f97316', '#f59e0b', '#eab308', '#84cc16'];
        results.forEach((result, index) => {
          const series = chart.addSeries(AreaSeries, {
            topColor: `${colors[index % colors.length]}40`,
            bottomColor: `${colors[index % colors.length]}00`,
            lineColor: colors[index % colors.length],
            lineWidth: 2,
          });

          const formattedData = result.data.map((point: TimeSeriesPoint) => ({
            time: point.time,
            value: point.value,
          }));

          series.setData(formattedData);
        });

        chart.timeScale().fitContent();
      } catch (error) {
        console.error('Failed to fetch drawdown data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();

    const handleResize = () => {
      if (chartContainerRef.current && chartRef.current) {
        chartRef.current.applyOptions({
          width: chartContainerRef.current.clientWidth,
        });
      }
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      chart.remove();
    };
  }, [selectedRuleIds, timeRange]);

  return (
    <div className="bg-zinc-800/30 rounded-lg border border-zinc-800 p-4">
      <h3 className="text-sm font-semibold text-white mb-4 flex items-center gap-2">
        <Icon name="trending-down" size="sm" className="w-4 h-4" />
        Underwater Equity Curve (Drawdown)
      </h3>
      {loading && (
        <div className="flex items-center justify-center h-[250px] text-zinc-500">
          <Icon name="clock" size="sm" className="w-6 h-6 animate-pulse mr-2" />
          Loading drawdown data...
        </div>
      )}
      <div ref={chartContainerRef} className={loading ? 'hidden' : ''} />
    </div>
  );
};

// ============================================
// Rule Comparison Table Component
// ============================================

type RuleComparisonTableProps = {
  rules: RuleMetrics[];
};

const RuleComparisonTable = ({ rules }: RuleComparisonTableProps) => {
  const metrics = [
    { key: 'sharpeRatio', label: 'Sharpe Ratio', format: (v: number) => v.toFixed(2) },
    { key: 'profitFactor', label: 'Profit Factor', format: (v: number) => v.toFixed(2) },
    { key: 'winRate', label: 'Win Rate', format: (v: number) => `${v.toFixed(1)}%` },
    { key: 'totalPnL', label: 'Total P&L', format: (v: number) => `$${v.toFixed(2)}` },
    { key: 'maxDrawdownPercent', label: 'Max DD %', format: (v: number) => `${v.toFixed(1)}%` },
    { key: 'avgWin', label: 'Avg Win', format: (v: number) => `$${v.toFixed(2)}` },
    { key: 'avgLoss', label: 'Avg Loss', format: (v: number) => `$${v.toFixed(2)}` },
    { key: 'totalTrades', label: 'Total Trades', format: (v: number) => v.toString() },
  ];

  return (
    <div className="bg-zinc-800/30 rounded-lg border border-zinc-800 p-4">
      <h3 className="text-sm font-semibold text-white mb-4 flex items-center gap-2">
        <Icon name="activity" size="sm" className="w-4 h-4" />
        Side-by-Side Comparison ({rules.length} rules)
      </h3>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead className="bg-zinc-900 border-b border-zinc-800">
            <tr className="text-xs text-zinc-500">
              <th className="p-2 text-left sticky left-0 bg-zinc-900">Metric</th>
              {rules.map((rule) => (
                <th key={rule.ruleId} className="p-2 text-left">
                  {rule.ruleName}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {metrics.map((metric) => (
              <tr key={metric.key} className="border-b border-zinc-800">
                <td className="p-2 font-medium text-zinc-300 sticky left-0 bg-zinc-900/95">
                  {metric.label}
                </td>
                {rules.map((rule) => {
                  const value = rule[metric.key as keyof RuleMetrics] as number;
                  return (
                    <td key={rule.ruleId} className="p-2 font-mono text-zinc-400">
                      {metric.format(value)}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

