    return (
        <div className="h-full overflow-auto scrollbar-thin scrollbar-thumb-zinc-700 bg-[#131316]">
            <table className="w-full text-left border-collapse">
                <thead className="sticky top-0 bg-[#191a1e] text-zinc-400 z-10 font-bold text-[10px] uppercase tracking-wider border-b border-zinc-600">
                    <tr>
                        <th className="p-1 pl-2 border-r border-zinc-700 w-20">Symbol</th>
                        <th className="p-1 border-r border-zinc-700">Condition</th>
                        <th className="p-1 border-r border-zinc-700 w-20 text-right">Price</th>
                        <th className="p-1 border-r border-zinc-700 w-16">Status</th>
                        <th className="p-1 pr-4">Created</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-zinc-800 text-zinc-300 font-mono text-[11px]">
                    {alerts.length === 0 ? (
                        <tr>
                            <td colSpan={5} className="p-8 text-center text-zinc-600 text-xs italic">
                                No active alerts
                            </td>
                        </tr>
                    ) : (
                        alerts.map((alert, i) => (
                            <tr key={alert.id} className={`${i % 2 === 0 ? 'bg-[#131316]' : 'bg-[#0f0f12]'} hover:bg-[#191a1e] transition-colors`}>
                                <td className="p-1 pl-2 border-r border-zinc-800 font-bold text-zinc-100">{alert.symbol}</td>
                                <td className="p-1 border-r border-zinc-800 text-zinc-400">{alert.condition}</td>
                                <td className="p-1 border-r border-zinc-800 text-right text-zinc-300">{alert.price.toFixed(5)}</td>
                                <td className="p-1 border-r border-zinc-800">
                                    <span className={`text-[10px] px-1 rounded-sm ${alert.status === 'ACTIVE' ? 'bg-green-900/20 text-green-300' :
                                        alert.status === 'TRIGGERED' ? 'bg-yellow-900/20 text-yellow-300' :
                                            'bg-zinc-800 text-zinc-500'
                                        }`}>
                                        {alert.status}
                                    </span>
                                </td>
                                <td className="p-1 text-zinc-500 text-[10px] pr-4">{formatDate(alert.createdAt)}</td>
                            </tr>
                        ))
                    )}
                </tbody>
            </table>
        </div>
    );
}

function JournalTab({ entries }: { entries: JournalEntry[] }) {
    const formatTime = (timestamp: string) => {
        try {
            return new Date(timestamp).toLocaleTimeString('en-US', {
                hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
            });
        } catch {
            return timestamp;
        }
    };

    const getTypeColor = (type: JournalEntry['type']) => {
        switch (type) {
            case 'SUCCESS': return 'text-zinc-300';
            case 'WARNING': return 'text-yellow-400';
            case 'ERROR': return 'text-red-400';
            default: return 'text-zinc-400';
        }
    };

    const getTypeIcon = (type: JournalEntry['type']) => {
        switch (type) {
            case 'SUCCESS': return <Icon name="trending-up" size="xs" />;
            case 'WARNING': return <Icon name="alert-triangle" size="xs" />;
            case 'ERROR': return <Icon name="x-close" size="xs" />;
            default: return <Icon name="file-text" size="xs" />;
        }
    };

    return (
        <div className="h-full overflow-auto scrollbar-thin scrollbar-thumb-zinc-700 bg-[#131316] font-mono">
            <div className="p-2 space-y-1">
                {entries.length === 0 ? (
                    <div className="p-8 text-center text-zinc-600 text-xs italic">
                        No journal entries
                    </div>
                ) : (
                    entries.map((entry, i) => (
                        <div
                            key={i}
                            className="flex items-start gap-2 px-2 py-1 hover:bg-zinc-800/50 rounded text-[11px]"
                        >
                            <Icon name="clock" size="xs" className="text-zinc-600 mt-0.5 flex-shrink-0" />
                            <span className="text-zinc-500 tabular-nums min-w-[65px]">{formatTime(entry.timestamp)}</span>
                            <span className={`flex-shrink-0 ${getTypeColor(entry.type)}`}>
                                {getTypeIcon(entry.type)}
                            </span>
                            <span className="text-zinc-300 flex-1">{entry.message}</span>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
}

/**
 * Trade History Component
 * Displays closed trades with P&L, filters, and export functionality
 */

import { Icon } from './ui/Icon';
import { useState, useEffect, useMemo } from 'react';
import { buildApiUrl } from '../config/api';
import { useAppStore } from '../store/useAppStore';
import { useMT5Store } from '../store/useMT5Store';
import { DollarSign, TrendingUp } from 'lucide-react';

type Trade = {
  id: number;
  symbol: string;
  side: 'BUY' | 'SELL';
  volume: number;
  openPrice: number;
  closePrice: number;
  openTime: string;
  closeTime: string;
  profit: number;
  commission: number;
  swap: number;
  pips: number;
  duration: string;
};

type TradeHistoryProps = {
  accountId?: string;
};

export const TradeHistory = ({ accountId }: TradeHistoryProps) => {
  const { accountId: storeAccountId } = useAppStore();
  const activeAccountId = accountId || storeAccountId;

  const [trades, setTrades] = useState<Trade[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterSide, setFilterSide] = useState<'ALL' | 'BUY' | 'SELL'>('ALL');
  const [filterProfit, setFilterProfit] = useState<'ALL' | 'PROFIT' | 'LOSS'>('ALL');
  const [dateRange, setDateRange] = useState<'ALL' | 'TODAY' | 'WEEK' | 'MONTH'>('ALL');

  // MT5 mode
  const mt5Enabled = localStorage.getItem('rtx5_mt5_mode') === 'true';
  const mt5Store = useMT5Store();
  const mt5History = mt5Store.history.map((deal, idx) => ({
    id: deal.deal || idx,
    symbol: deal.symbol,
    side: deal.type.includes('BUY') ? 'BUY' as const : 'SELL' as const,
    volume: deal.volume,
    openPrice: deal.price,
    closePrice: deal.price,
    openTime: new Date(deal.time_ms).toISOString(),
    closeTime: new Date(deal.time_ms).toISOString(),
    profit: deal.profit,
    commission: deal.commission,
    swap: deal.swap,
    pips: 0,
    duration: '0s'
  }));

  // Fetch trade history
  useEffect(() => {
    if (mt5Enabled) {
      // Fetch MT5 history if not already loaded
      if (mt5Store.history.length === 0) {
        mt5Store.fetchHistory();
      }
      return;
    }

    if (!activeAccountId) return;

    const fetchTrades = async () => {
      setLoading(true);
      try {
        const response = await fetch(
          buildApiUrl(`/api/trades/history?accountId=${activeAccountId}`)
        );

        if (response.ok) {
          const data = await response.json();
          setTrades(data || []);
        }
      } catch (error) {
        console.error('Failed to fetch trade history:', error);
        setTrades([]);
      } finally {
        setLoading(false);
      }
    };

    fetchTrades();
    const interval = setInterval(fetchTrades, 5000); // Refresh every 5 seconds

    return () => clearInterval(interval);
  }, [activeAccountId, mt5Enabled, mt5Store]);

  // Use MT5 or B-Book trades based on mode
  const displayTrades = mt5Enabled ? mt5History : trades;

  // Filter trades
  const filteredTrades = useMemo(() => {
    return displayTrades.filter((trade) => {
      // Search filter
      if (searchTerm && !trade.symbol.toLowerCase().includes(searchTerm.toLowerCase())) {
        return false;
      }

      // Side filter
      if (filterSide !== 'ALL' && trade.side !== filterSide) {
        return false;
      }

      // Profit filter
      if (filterProfit === 'PROFIT' && trade.profit <= 0) return false;
      if (filterProfit === 'LOSS' && trade.profit >= 0) return false;

      // Date filter
      if (dateRange !== 'ALL') {
        const tradeDate = new Date(trade.closeTime);
        const now = new Date();
        const diffDays = Math.floor(
          (now.getTime() - tradeDate.getTime()) / (1000 * 60 * 60 * 24)
        );

        if (dateRange === 'TODAY' && diffDays > 0) return false;
        if (dateRange === 'WEEK' && diffDays > 7) return false;
        if (dateRange === 'MONTH' && diffDays > 30) return false;
      }

      return true;
    });
  }, [displayTrades, searchTerm, filterSide, filterProfit, dateRange]);

  // Calculate statistics
  const stats = useMemo(() => {
    const totalTrades = filteredTrades.length;
    const winningTrades = filteredTrades.filter((t) => t.profit > 0).length;
    const losingTrades = filteredTrades.filter((t) => t.profit < 0).length;
    const totalProfit = filteredTrades.reduce((sum, t) => sum + t.profit, 0);
    const totalCommission = filteredTrades.reduce((sum, t) => sum + t.commission, 0);
    const totalSwap = filteredTrades.reduce((sum, t) => sum + t.swap, 0);
    const netProfit = totalProfit - totalCommission - totalSwap;
    const winRate = totalTrades > 0 ? (winningTrades / totalTrades) * 100 : 0;

    return {
      totalTrades,
      winningTrades,
      losingTrades,
      totalProfit,
      totalCommission,
      totalSwap,
      netProfit,
      winRate,
    };
  }, [filteredTrades]);

  const exportToCSV = () => {
    if (filteredTrades.length === 0) {
      alert('No trades to export');
      return;
    }

    const headers = [
      'ID',
      'Symbol',
      'Side',
      'Volume',
      'Open Price',
      'Close Price',
      'Open Time',
      'Close Time',
      'Profit',
      'Commission',
      'Swap',
      'Pips',
      'Duration',
    ];

    const rows = filteredTrades.map((trade) => [
      trade.id,
      trade.symbol,
      trade.side,
      trade.volume,
      trade.openPrice,
      trade.closePrice,
      trade.openTime,
      trade.closeTime,
      trade.profit,
      trade.commission,
      trade.swap,
      trade.pips,
      trade.duration,
    ]);

    const csv = [headers, ...rows].map((row) => row.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `trade-history-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const formatTime = (timeString: string) => {
    try {
      const date = new Date(timeString);
      return date.toLocaleString('en-US', {
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch {
      return timeString;
    }
  };

  return (
    <div className="flex flex-col h-full bg-zinc-900">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-zinc-800">
        <div>
          <h3 className="text-sm font-semibold text-white">Trade History</h3>
          <p className="text-xs text-zinc-500">
            {filteredTrades.length} trade{filteredTrades.length !== 1 ? 's' : ''}
          </p>
        </div>
        <button
          onClick={exportToCSV}
          disabled={filteredTrades.length === 0}
          className="flex items-center gap-2 px-3 py-1.5 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 border border-emerald-500/20 rounded text-xs transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <Icon name="download" size="sm" className="w-3.5 h-3.5" />
          Export CSV
        </button>
      </div>

      {/* Statistics Panel */}
      <div className="grid grid-cols-4 gap-3 p-4 border-b border-zinc-800 bg-zinc-900/50">
        <StatCard
          label="Total Trades"
          value={stats.totalTrades.toString()}
          icon={DollarSign}
          color="blue"
        />
        <StatCard
          label="Win Rate"
          value={`${stats.winRate.toFixed(1)}%`}
          icon={TrendingUp}
          color={stats.winRate >= 50 ? 'green' : 'red'}
        />
        <StatCard
          label="Gross P&L"
          value={`$${stats.totalProfit.toFixed(2)}`}
          icon={DollarSign}
          color={stats.totalProfit >= 0 ? 'green' : 'red'}
        />
        <StatCard
          label="Net P&L"
          value={`$${stats.netProfit.toFixed(2)}`}
          icon={DollarSign}
          color={stats.netProfit >= 0 ? 'green' : 'red'}
        />
      </div>

      {/* Filters */}
      <div className="flex items-center gap-3 p-3 border-b border-zinc-800">
        {/* Search */}
        <div className="flex-1 relative">
          <Icon name="search" size="sm" className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
          <input
            type="text"
            placeholder="Search by symbol..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-8 pr-3 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-xs text-zinc-200 focus:outline-none focus:border-emerald-500"
          />
        </div>

        {/* Side Filter */}
        <select
          value={filterSide}
          onChange={(e) => setFilterSide(e.target.value as 'ALL' | 'BUY' | 'SELL')}
          className="px-3 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-xs text-zinc-300 focus:outline-none focus:border-emerald-500"
        >
          <option value="ALL">All Sides</option>
          <option value="BUY">Buy Only</option>
          <option value="SELL">Sell Only</option>
        </select>

        {/* Profit Filter */}
        <select
          value={filterProfit}
          onChange={(e) => setFilterProfit(e.target.value as 'ALL' | 'PROFIT' | 'LOSS')}
          className="px-3 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-xs text-zinc-300 focus:outline-none focus:border-emerald-500"
        >
          <option value="ALL">All Results</option>
          <option value="PROFIT">Profits Only</option>
          <option value="LOSS">Losses Only</option>
        </select>

        {/* Date Range */}
        <select
          value={dateRange}
          onChange={(e) => setDateRange(e.target.value as any)}
          className="px-3 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-xs text-zinc-300 focus:outline-none focus:border-emerald-500"
        >
          <option value="ALL">All Time</option>
          <option value="TODAY">Today</option>
          <option value="WEEK">Last 7 Days</option>
          <option value="MONTH">Last 30 Days</option>
        </select>
      </div>

      {/* Trade List */}
      <div className="flex-1 overflow-auto">
        {loading && trades.length === 0 ? (
          <div className="flex items-center justify-center h-full text-zinc-500">
            <Icon name="clock" size="sm" className="w-6 h-6 animate-pulse mr-2" />
            Loading trade history...
          </div>
        ) : filteredTrades.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-zinc-500">
            <Icon name="filter" size="sm" className="w-8 h-8 mb-2 text-zinc-700" />
            <p>No trades found</p>
            <p className="text-xs mt-1">Try adjusting your filters</p>
          </div>
        ) : (
          <table className="w-full text-sm">
            <thead className="sticky top-0 bg-zinc-900 border-b border-zinc-800">
              <tr className="text-xs text-zinc-500 text-left">
                <th className="p-2">ID</th>
                <th className="p-2">Symbol</th>
                <th className="p-2">Side</th>
                <th className="p-2">Volume</th>
                <th className="p-2">Open</th>
                <th className="p-2">Close</th>
                <th className="p-2">Pips</th>
                <th className="p-2">Profit</th>
                <th className="p-2">Costs</th>
                <th className="p-2">Close Time</th>
                <th className="p-2">Duration</th>
              </tr>
            </thead>
            <tbody>
              {filteredTrades.map((trade) => (
                <tr
                  key={trade.id}
                  className="border-b border-zinc-800 hover:bg-zinc-900/50 transition-colors"
                >
                  <td className="p-2 text-zinc-500 font-mono text-xs">#{trade.id}</td>
                  <td className="p-2 font-medium text-white">{trade.symbol}</td>
                  <td className="p-2">
                    <span
                      className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium ${trade.side === 'BUY'
                          ? 'bg-green-900/30 text-green-400'
                          : 'bg-red-900/30 text-red-400'
                        }`}
                    >
                      {trade.side === 'BUY' ? (
                        <Icon name="trending-up" size="sm" className="w-3 h-3" />
                      ) : (
                        <Icon name="trending-down" size="sm" className="w-3 h-3" />
                      )}
                      {trade.side}
                    </span>
                  </td>
                  <td className="p-2 font-mono text-zinc-300">{trade.volume.toFixed(2)}</td>
                  <td className="p-2 font-mono text-zinc-400">{trade.openPrice.toFixed(5)}</td>
                  <td className="p-2 font-mono text-zinc-400">{trade.closePrice.toFixed(5)}</td>
                  <td className="p-2 font-mono text-zinc-300">
                    {trade.pips >= 0 ? '+' : ''}
                    {trade.pips.toFixed(1)}
                  </td>
                  <td className="p-2">
                    <div
                      className={`font-mono font-bold ${trade.profit >= 0 ? 'text-green-400' : 'text-red-400'
                        }`}
                    >
                      {trade.profit >= 0 ? '+' : ''}${trade.profit.toFixed(2)}
                    </div>
                  </td>
                  <td className="p-2 text-xs text-zinc-500">
                    <div>C: ${trade.commission.toFixed(2)}</div>
                    <div>S: ${trade.swap.toFixed(2)}</div>
                  </td>
                  <td className="p-2 text-xs text-zinc-500">
                    <Icon name="clock" size="sm" className="inline w-3 h-3 mr-1" />
                    {formatTime(trade.closeTime)}
                  </td>
                  <td className="p-2 text-xs text-zinc-500">{trade.duration}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

type StatCardProps = {
  label: string;
  value: string;
  icon: typeof DollarSign;
  color: string;
};

const StatCard = ({ label, value, icon: Icon, color }: StatCardProps) => (
  <div className="flex flex-col gap-1 p-3 bg-zinc-800/30 rounded border border-zinc-800">
    <div className="flex items-center gap-2">
      <Icon className={`w-3.5 h-3.5 text-${color}-400`} />
      <span className="text-xs text-zinc-500">{label}</span>
    </div>
    <div className={`text-lg font-bold text-${color}-400`}>{value}</div>
  </div>
);

/**
 * Trade Journal V2 / Trading Diary
 * Advanced trade journaling system with calendar view, annotations, and analytics
 */

import { Icon } from './ui/Icon';
import { useState, useMemo } from 'react';
import { useTradeJournalStore, type SetupTag, type TradeAnnotation } from '../store/useTradeJournalStore';

interface Trade {
  id: number;
  date: string; // YYYY-MM-DD
  openTime: string;
  closeTime: string;
  symbol: string;
  type: 'BUY' | 'SELL';
  volume: number;
  openPrice: number;
  closePrice: number;
  profit: number;
  commission: number;
  swap: number;
}

type ViewMode = 'calendar' | 'list' | 'analytics';
type SessionType = 'Asian' | 'London' | 'NY';

export function TradeJournalV2() {
  const [viewMode, setViewMode] = useState<ViewMode>('calendar');
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [selectedTrade, setSelectedTrade] = useState<Trade | null>(null);
  const [showAnnotationForm, setShowAnnotationForm] = useState(false);
  const [showJournalForm, setShowJournalForm] = useState(false);

  // Filters
  const [filterSymbol, setFilterSymbol] = useState('ALL');
  const [filterTag, setFilterTag] = useState<SetupTag | 'ALL'>('ALL');
  const [filterPLMin, setFilterPLMin] = useState('');
  const [filterPLMax, setFilterPLMax] = useState('');

  const { annotations, addAnnotation, getAnnotation, addJournalEntry, getEntriesByDate } =
    useTradeJournalStore();

  // Generate 60 mock trades over 90 days
  const trades = useMemo(() => generateMockTrades(), []);

  // Filter trades
  const filteredTrades = useMemo(() => {
    return trades.filter(t => {
      if (filterSymbol !== 'ALL' && t.symbol !== filterSymbol) return false;
      if (filterTag !== 'ALL') {
        const ann = getAnnotation(t.id);
        if (!ann || !ann.tags.includes(filterTag)) return false;
      }
      if (filterPLMin && t.profit < parseFloat(filterPLMin)) return false;
      if (filterPLMax && t.profit > parseFloat(filterPLMax)) return false;
      return true;
    });
  }, [trades, filterSymbol, filterTag, filterPLMin, filterPLMax, getAnnotation]);

  // Get trades for selected date
  const selectedDateTrades = useMemo(() => {
    if (!selectedDate) return [];
    return filteredTrades.filter(t => t.date === selectedDate);
  }, [selectedDate, filteredTrades]);

  // Calculate monthly P&L by date
  const dailyPL = useMemo(() => {
    const plMap = new Map<string, number>();
    filteredTrades.forEach(t => {
      const current = plMap.get(t.date) || 0;
      plMap.set(t.date, current + t.profit);
    });
    return plMap;
  }, [filteredTrades]);

  // Get unique symbols
  const symbols = useMemo(() => {
    const unique = new Set(trades.map(t => t.symbol));
    return ['ALL', ...Array.from(unique)];
  }, [trades]);

  return (
    <div className="flex flex-col h-full bg-zinc-900 text-zinc-300 overflow-hidden">
      {/* Header */}
      <div className="bg-zinc-800 border-b border-zinc-700 p-3">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-lg font-semibold text-white">Trade Journal V2</h2>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setViewMode('calendar')}
              className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${
                viewMode === 'calendar'
                  ? 'bg-blue-600 text-white'
                  : 'bg-zinc-700 hover:bg-zinc-600 text-zinc-300'
              }`}
            >
              <Icon name="calendar" size="sm" className="inline mr-1" />
              Calendar
            </button>
            <button
              onClick={() => setViewMode('list')}
              className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${
                viewMode === 'list'
                  ? 'bg-blue-600 text-white'
                  : 'bg-zinc-700 hover:bg-zinc-600 text-zinc-300'
              }`}
            >
              List
            </button>
            <button
              onClick={() => setViewMode('analytics')}
              className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${
                viewMode === 'analytics'
                  ? 'bg-blue-600 text-white'
                  : 'bg-zinc-700 hover:bg-zinc-600 text-zinc-300'
              }`}
            >
              Analytics
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="flex items-center gap-2 flex-wrap text-xs">
          <div className="flex items-center gap-1.5">
            <Icon name="filter" size="xs" className="text-zinc-400" />
            <select
              value={filterSymbol}
              onChange={(e) => setFilterSymbol(e.target.value)}
              className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-xs outline-none focus:border-zinc-600"
            >
              {symbols.map(sym => (
                <option key={sym} value={sym}>{sym}</option>
              ))}
            </select>
          </div>

          <select
            value={filterTag}
            onChange={(e) => setFilterTag(e.target.value as SetupTag | 'ALL')}
            className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-xs outline-none focus:border-zinc-600"
          >
            <option value="ALL">All Tags</option>
            <option value="breakout">Breakout</option>
            <option value="reversal">Reversal</option>
            <option value="trend">Trend</option>
            <option value="range">Range</option>
            <option value="news">News</option>
            <option value="scalp">Scalp</option>
            <option value="swing">Swing</option>
          </select>

          <input
            type="number"
            placeholder="Min P&L"
            value={filterPLMin}
            onChange={(e) => setFilterPLMin(e.target.value)}
            className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-xs outline-none focus:border-zinc-600 w-20"
          />
          <input
            type="number"
            placeholder="Max P&L"
            value={filterPLMax}
            onChange={(e) => setFilterPLMax(e.target.value)}
            className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-xs outline-none focus:border-zinc-600 w-20"
          />

          <button
            onClick={() => {
              setFilterSymbol('ALL');
              setFilterTag('ALL');
              setFilterPLMin('');
              setFilterPLMax('');
            }}
            className="px-2 py-1 bg-zinc-700 hover:bg-zinc-600 rounded text-xs transition-colors"
          >
            Clear
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-auto">
        {viewMode === 'calendar' && (
          <CalendarView
            currentMonth={currentMonth}
            setCurrentMonth={setCurrentMonth}
            dailyPL={dailyPL}
            selectedDate={selectedDate}
            setSelectedDate={setSelectedDate}
            selectedDateTrades={selectedDateTrades}
            onTradeClick={(trade) => {
              setSelectedTrade(trade);
              setShowAnnotationForm(true);
            }}
            onAddJournalEntry={() => setShowJournalForm(true)}
          />
        )}

        {viewMode === 'list' && (
          <ListView
            trades={filteredTrades}
            onTradeClick={(trade) => {
              setSelectedTrade(trade);
              setShowAnnotationForm(true);
            }}
          />
        )}

        {viewMode === 'analytics' && (
          <AnalyticsView trades={filteredTrades} annotations={annotations} />
        )}
      </div>

      {/* Annotation Form Modal */}
      {showAnnotationForm && selectedTrade && (
        <AnnotationFormModal
          trade={selectedTrade}
          onClose={() => {
            setShowAnnotationForm(false);
            setSelectedTrade(null);
          }}
          onSave={(annotation) => {
            addAnnotation(annotation);
            setShowAnnotationForm(false);
            setSelectedTrade(null);
          }}
        />
      )}

      {/* Journal Entry Form Modal */}
      {showJournalForm && (
        <JournalEntryFormModal
          selectedDate={selectedDate || new Date().toISOString().split('T')[0]}
          onClose={() => setShowJournalForm(false)}
          onSave={(entry) => {
            addJournalEntry(entry);
            setShowJournalForm(false);
          }}
        />
      )}
    </div>
  );
}

// --- CALENDAR VIEW ---
interface CalendarViewProps {
  currentMonth: Date;
  setCurrentMonth: (date: Date) => void;
  dailyPL: Map<string, number>;
  selectedDate: string | null;
  setSelectedDate: (date: string | null) => void;
  selectedDateTrades: Trade[];
  onTradeClick: (trade: Trade) => void;
  onAddJournalEntry: () => void;
}

function CalendarView({
  currentMonth,
  setCurrentMonth,
  dailyPL,
  selectedDate,
  setSelectedDate,
  selectedDateTrades,
  onTradeClick,
  onAddJournalEntry,
}: CalendarViewProps) {
  const { getEntriesByDate } = useTradeJournalStore();

  const monthDays = useMemo(() => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const startOffset = firstDay.getDay();
    const days: (Date | null)[] = [];

    // Fill leading nulls
    for (let i = 0; i < startOffset; i++) {
      days.push(null);
    }

    // Fill month days
    for (let d = 1; d <= lastDay.getDate(); d++) {
      days.push(new Date(year, month, d));
    }

    return days;
  }, [currentMonth]);

  const previousMonth = () => {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1));
  };

  return (
    <div className="flex gap-3 p-4 h-full">
      {/* Calendar Grid */}
      <div className="flex-1">
        <div className="flex items-center justify-between mb-3">
          <button
            onClick={previousMonth}
            className="p-1.5 hover:bg-zinc-800 rounded transition-colors"
          >
            <Icon name="chevron-left" size="lg" />
          </button>
          <h3 className="text-sm font-semibold">
            {currentMonth.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
          </h3>
          <button
            onClick={nextMonth}
            className="p-1.5 hover:bg-zinc-800 rounded transition-colors"
          >
            <Icon name="chevron-right" size="lg" />
          </button>
        </div>

        {/* Day Headers */}
        <div className="grid grid-cols-7 gap-1 mb-1">
          {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
            <div key={day} className="text-center text-xs text-zinc-500 font-medium py-1">
              {day}
            </div>
          ))}
        </div>

        {/* Calendar Days */}
        <div className="grid grid-cols-7 gap-1">
          {monthDays.map((day, idx) => {
            if (!day) {
              return <div key={`empty-${idx}`} className="aspect-square" />;
            }

            const dateStr = day.toISOString().split('T')[0];
            const pl = dailyPL.get(dateStr) || 0;
            const hasTrades = pl !== 0;
            const isSelected = dateStr === selectedDate;
            const hasJournalEntry = getEntriesByDate(dateStr).length > 0;

            let bgColor = 'bg-zinc-800';
            if (hasTrades) {
              if (pl > 0) bgColor = 'bg-green-900/30 border border-green-700/50';
              else bgColor = 'bg-red-900/30 border border-red-700/50';
            }
            if (isSelected) {
              bgColor += ' ring-2 ring-blue-500';
            }

            return (
              <div
                key={dateStr}
                onClick={() => setSelectedDate(dateStr)}
                className={`aspect-square p-1 rounded cursor-pointer hover:bg-zinc-700 transition-colors ${bgColor} relative`}
              >
                <div className="text-xs text-zinc-300">{day.getDate()}</div>
                {hasTrades && (
                  <div
                    className={`text-[10px] font-medium mt-0.5 ${
                      pl > 0 ? 'text-green-400' : 'text-red-400'
                    }`}
                  >
                    ${pl.toFixed(0)}
                  </div>
                )}
                {hasJournalEntry && (
                  <div className="absolute top-0.5 right-0.5">
                    <Icon name="edit" size="sm" className="text-blue-400" />
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Selected Date Trades */}
      {selectedDate && (
        <div className="w-80 bg-zinc-800 border border-zinc-700 rounded p-3">
          <div className="flex items-center justify-between mb-3">
            <h4 className="text-sm font-semibold">
              {new Date(selectedDate).toLocaleDateString('en-US', {
                month: 'short',
                day: 'numeric',
                year: 'numeric',
              })}
            </h4>
            <button
              onClick={onAddJournalEntry}
              className="p-1 hover:bg-zinc-700 rounded transition-colors"
              title="Add journal entry"
            >
              <Icon name="plus" size="sm" />
            </button>
          </div>

          {selectedDateTrades.length === 0 ? (
            <div className="text-xs text-zinc-500 text-center py-4">No trades on this day</div>
          ) : (
            <div className="space-y-2 max-h-[calc(100vh-200px)] overflow-auto">
              {selectedDateTrades.map(trade => (
                <TradeCard key={trade.id} trade={trade} onClick={() => onTradeClick(trade)} />
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// --- TRADE CARD ---
function TradeCard({ trade, onClick }: { trade: Trade; onClick: () => void }) {
  const { getAnnotation } = useTradeJournalStore();
  const annotation = getAnnotation(trade.id);
  const isProfit = trade.profit >= 0;

  return (
    <div
      onClick={onClick}
      className="bg-zinc-900 border border-zinc-700 rounded p-2 cursor-pointer hover:bg-zinc-800 transition-colors"
    >
      <div className="flex items-center justify-between mb-1">
        <div className="flex items-center gap-2">
          <span className="text-xs font-medium text-white">{trade.symbol}</span>
          <span
            className={`text-[10px] font-medium px-1.5 py-0.5 rounded ${
              trade.type === 'BUY' ? 'bg-green-900/50 text-green-400' : 'bg-red-900/50 text-red-400'
            }`}
          >
            {trade.type}
          </span>
        </div>
        <span className={`text-xs font-bold ${isProfit ? 'text-green-400' : 'text-red-400'}`}>
          ${trade.profit.toFixed(2)}
        </span>
      </div>

      <div className="text-[10px] text-zinc-400 mb-1">
        {new Date(trade.openTime).toLocaleTimeString('en-US', {
          hour: '2-digit',
          minute: '2-digit',
        })}
        {' ΓåÆ '}
        {new Date(trade.closeTime).toLocaleTimeString('en-US', {
          hour: '2-digit',
          minute: '2-digit',
        })}
      </div>

      {annotation && annotation.tags.length > 0 && (
        <div className="flex gap-1 flex-wrap">
          {annotation.tags.map(tag => (
            <span
              key={tag}
              className="text-[9px] px-1.5 py-0.5 bg-blue-900/50 text-zinc-300 rounded"
            >
              {tag}
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

