                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Footer - Totals */}
      <div className="border-t border-zinc-700 bg-[#252526] px-4 py-3">
        <div className="grid grid-cols-4 gap-4 text-xs">
