/**
 * Clean MT5-Style Trading Chart
 * - Loads historical OHLC from /api/fix/candles/{symbol}
 * - WebSocket live tick updates
 * - Single price line (MT5 style)
 * - Proper candle aggregation
 */

import React, { useEffect, useRef, useState, useCallback } from 'react';
import {
  createChart,
  createSeriesMarkers,
  ColorType,
  CrosshairMode,
  CandlestickSeries,
  LineSeries,
  BarSeries,
  AreaSeries,
  HistogramSeries,
} from 'lightweight-charts';
import type { IChartApi, ISeriesApi, Time } from 'lightweight-charts';
import { useToolbarState } from '../hooks/useToolbarState';
import { drawingManager } from '../services/drawingManager';
import { getEnhancedWebSocketService } from '../services/websocket-enhanced';
import { candleAggregationService, type OHLCV, type Timeframe as AggTimeframe } from '../services/candleAggregationService';
import { useAppStore } from '../store/useAppStore';
import { useMarketDataStore } from '../store/useMarketDataStore';
import { commandBus } from '../services/commandBus';
import { OneClickTrading } from './OneClickTrading';
import { DrawingContextMenu } from './DrawingContextMenu';
import { PriceDisplay, getSymbolDigits } from './ui/PriceDisplay';

export type ChartType = 'candlestick' | 'bar' | 'line' | 'area';
export type Timeframe = 'M1' | 'M5' | 'M15' | 'M30' | 'H1' | 'H4' | 'D1' | 'W1' | 'MN';

interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

interface TradingChartProps {
  symbol: string;
  timeframe?: Timeframe;
  chartType?: ChartType;
}

export const TradingChart = React.memo(function TradingChart({
  symbol,
  timeframe = 'H1',
  chartType = 'candlestick',
}: TradingChartProps) {
  // Debug: Log mount and props
  console.log(`[TradingChart] MOUNTING: symbol=${symbol}, timeframe=${timeframe}, chartType=${chartType}`);
  const containerRef = useRef<HTMLDivElement>(null); // Main chart refs
  const chartRef = useRef<IChartApi | null>(null);
  const seriesRef = useRef<ISeriesApi<any> | null>(null);
  const volumeRef = useRef<ISeriesApi<any> | null>(null);
  const priceLineRef = useRef<any>(null); // Kept as 'any' as IPriceLine is not imported
  const autoScrollEnabledRef = useRef(useToolbarState().state.autoScrollEnabled);

  const [legend, setLegend] = useState({ o: 0, h: 0, l: 0, c: 0, v: 0 });
  const [isLoading, setIsLoading] = useState(true);
  const [showOneClick, setShowOneClick] = useState(true);
  const [apiError, setApiError] = useState<string | null>(null);


  const candlesRef = useRef<Candle[]>([]);
  const currentCandleRef = useRef<Candle | null>(null);
  const prevPriceRef = useRef<number | null>(null);
  const isDisposedRef = useRef(false);
  const isRebuildingRef = useRef(false);

  // Infinite scroll tracking
  const isLoadingMoreRef = useRef(false);
  const hasReachedBeginningRef = useRef(false);
  const loadMoreHistoryRef = useRef<(() => Promise<void>) | null>(null);

  // Initialize chart
  useEffect(() => {
    console.log(`[TradingChart] Chart init effect running`);
    // Guard against double-mount (React StrictMode) and existing chart
    if (!containerRef.current) {
      console.log(`[TradingChart] No container ref, skipping chart init`);
      return;
    }
    if (chartRef.current) {
      console.log(`[TradingChart] Chart already exists, skipping creation`);
      return;
    }
    isDisposedRef.current = false;

    const rootStyle = getComputedStyle(document.body);
    const textColor = rootStyle.getPropertyValue('--text-secondary').trim() || '#A1A1AA';
    const gridColor = rootStyle.getPropertyValue('--border-primary').trim() || '#222226';

    console.log(`[TradingChart] Container size: ${containerRef.current.offsetWidth}x${containerRef.current.offsetHeight}`);

    const chart = createChart(containerRef.current, {
      autoSize: true,
      layout: {
        background: { type: ColorType.Solid, color: '#0e0e12' },
        textColor: '#8b949e',
        attributionLogo: false,
      },
      grid: {
        vertLines: { color: 'rgba(255,255,255,0.04)' },
        horzLines: { color: 'rgba(255,255,255,0.04)' },
      },
      crosshair: {
        mode: CrosshairMode.Magnet,
        vertLine: { color: '#4a5568', width: 1, style: 2, labelVisible: false },
        horzLine: { color: '#4a5568', width: 1, style: 2, labelVisible: false },
      },
      handleScroll: {
        vertTouchDrag: false,
        horzTouchDrag: true,
        mouseWheel: false,      // custom handler does the scrolling
        pressedMouseMove: true, // drag still works
      },
      handleScale: {
        axisPressedMouseMove: false,
        axisDoubleClickReset: false,
        mouseWheel: false,      // wheel never zooms
        pinch: false,
      },
      rightPriceScale: {
        borderColor: '#1f2a36',
        scaleMargins: { top: 0.1, bottom: 0.2 },
      },
      timeScale: {
        borderColor: '#1f2a36',
        timeVisible: true,
        secondsVisible: false,
        barSpacing: 8,
        minBarSpacing: 3,
        rightOffset: 15,
        fixLeftEdge: false,
        fixRightEdge: true,
      },
    });

    chartRef.current = chart;

    // Initial setup handled by autoSize: true

    // ΓöÇΓöÇΓöÇ MT5-style Auto-Scroll (Snap back to live after 3s of inactivity) ΓöÇΓöÇΓöÇ
    let autoScrollTimer: ReturnType<typeof setTimeout> | null = null;
    let isUserInteracting = false;
    // autoScrollEnabled is now managed by autoScrollEnabledRef

    const resetAutoScrollTimer = () => {
      if (autoScrollTimer) clearTimeout(autoScrollTimer);
      if (isDisposedRef.current || !chartRef.current || !autoScrollEnabledRef.current) return;

      autoScrollTimer = setTimeout(() => {
        if (!isDisposedRef.current && chartRef.current && !isUserInteracting && autoScrollEnabledRef.current) {
          chartRef.current.timeScale().scrollToRealTime();
        }
        autoScrollTimer = null;
      }, 3000); // 3 seconds after last interaction
    };

    const handleInteractionStart = () => {
      isUserInteracting = true;
      if (autoScrollTimer) clearTimeout(autoScrollTimer);
    };

    const handleInteractionEnd = () => {
      isUserInteracting = false;
      resetAutoScrollTimer();
    };

    let wheelEndTimer: ReturnType<typeof setTimeout> | null = null;
    const wheelHandler = (e: WheelEvent) => {
      // Check if cursor is over the chart area using position, not DOM contains()
      // contains() fails for overlays/legend that are siblings of containerRef
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const overChart = e.clientX >= rect.left && e.clientX <= rect.right &&
                        e.clientY >= rect.top  && e.clientY <= rect.bottom;
      if (!overChart) return;

      e.preventDefault();
      e.stopPropagation();
      if (isDisposedRef.current || !chartRef.current) return;

      const timeScale = chartRef.current.timeScale();
      const visibleRange = timeScale.getVisibleLogicalRange();
      if (!visibleRange) return;

      // Scroll DOWN = pan left (older candles), Scroll UP = pan right (newer)
      const barsPerScroll = Math.max(1, Math.round(Math.abs(e.deltaY) / 20));
      const shift = e.deltaY > 0 ? -barsPerScroll : barsPerScroll;

      console.log(`[Chart] Wheel: deltaY=${e.deltaY}, shift=${shift}`);

      timeScale.setVisibleLogicalRange({
        from: visibleRange.from + shift,
        to: visibleRange.to + shift,
      });

      handleInteractionStart();
      if (wheelEndTimer) clearTimeout(wheelEndTimer);
      wheelEndTimer = setTimeout(() => {
        handleInteractionEnd();
        wheelEndTimer = null;
      }, 200);
    };
    // Attach to window with capture:true ΓÇö fires BEFORE any other handler
    window.addEventListener('wheel', wheelHandler, { passive: false, capture: true });

    const chartContainer = containerRef.current;
    if (chartContainer) {
      // Track pointer/drag interactions for auto-scroll timer
      chartContainer.addEventListener('pointerdown', handleInteractionStart);
      chartContainer.addEventListener('pointerup', handleInteractionEnd);
      chartContainer.addEventListener('pointerleave', handleInteractionEnd);
      chartContainer.addEventListener('touchstart', handleInteractionStart, { passive: true });
      chartContainer.addEventListener('touchend', handleInteractionEnd);
    }

    // Crosshair move for legend
    const crosshairHandler = (param: any) => {
      if (param.time && seriesRef.current) {
        const data = param.seriesData.get(seriesRef.current) as any;
        if (data) {
          setLegend({
            o: data.open || 0,
            h: data.high || 0,
            l: data.low || 0,
            c: data.close || data.value || 0,
            v: data.volume || 0,
          });
        }
      }
    };
    chart.subscribeCrosshairMove(crosshairHandler);

    // Infinite scroll range handler
    const logicalRangeHandler = (logicalRange: any) => {
      if (logicalRange && logicalRange.from < 50) {
        if (loadMoreHistoryRef.current) {
          loadMoreHistoryRef.current();
        }
      }
    };
    chart.timeScale().subscribeVisibleLogicalRangeChange(logicalRangeHandler);

    return () => {
      isDisposedRef.current = true;
      if (autoScrollTimer) clearTimeout(autoScrollTimer);
      if (wheelEndTimer) clearTimeout(wheelEndTimer);
      // Remove window-level wheel handler
      window.removeEventListener('wheel', wheelHandler, { capture: true } as EventListenerOptions);
      if (chartContainer) {
        chartContainer.removeEventListener('pointerdown', handleInteractionStart);
        chartContainer.removeEventListener('pointerup', handleInteractionEnd);
        chartContainer.removeEventListener('pointerleave', handleInteractionEnd);
        chartContainer.removeEventListener('touchstart', handleInteractionStart);
        chartContainer.removeEventListener('touchend', handleInteractionEnd);
      }
      chart.unsubscribeCrosshairMove(crosshairHandler);
      chart.timeScale().unsubscribeVisibleLogicalRangeChange(logicalRangeHandler);

      // Delay cleanup to allow any pending lightweight-charts requestAnimationFrame 
      // loops to finish, preventing "Object is disposed" runtime panics.
      const chartToDispose = chartRef.current;
      if (chartToDispose) {
        if ((chartToDispose as any)._cleanupDrawings) {
          (chartToDispose as any)._cleanupDrawings();
        }

        setTimeout(() => {
          try {
            chartToDispose.remove();
            console.log(`[TradingChart] Chart explicitly removed inside setTimeout.`);
          } catch (e) {
            // Ignore late disposal errors
          }
        }, 16); // 16ms = roughly 1 frame
      }

      chartRef.current = null;
      seriesRef.current = null;
      volumeRef.current = null;
      priceLineRef.current = null;
    };
  }, []);

  // Update chart with candles helper
  const updateChartData = useCallback((candles: Candle[], currentChartType?: ChartType) => {
    console.log(`[Chart] updateChartData called with ${candles?.length || 0} candles, type=${currentChartType}`);

    if (isDisposedRef.current) {
      console.log('[Chart] Cannot update - chart disposed');
      return;
    }
    if (!seriesRef.current) {
      console.log('[Chart] Cannot update - series not ready');
      return;
    }
    if (!volumeRef.current) {
      console.log('[Chart] Cannot update - volume series not ready');
      return;
    }

    // Determine the active chart type
    const activeType = currentChartType || prevChartTypeRef.current || 'candlestick';

    // Deduplicate and strictly sort ascending by time (required by lightweight-charts)
    // Live tick aggregates can occasionally append duplicate times at the end of candlesRef
    const uniqueCandles = new Map<number, Candle>();
    candles.forEach(c => uniqueCandles.set(c.time, c));
    const sortedCandles = Array.from(uniqueCandles.values()).sort((a, b) => a.time - b.time);

    // Format data based on chart type
    let formatted: any[];
    if (activeType === 'line' || activeType === 'area') {
      // Line and Area series need { time, value }
      formatted = sortedCandles.map(c => ({
        time: c.time as Time,
        value: c.close,
      }));
    } else {
      // Candlestick and Bar series need { time, open, high, low, close }
      formatted = sortedCandles.map(c => ({
        time: c.time as Time,
        open: c.open,
        high: c.high,
        low: c.low,
        close: c.close,
      }));
    }

    const volumeData = sortedCandles.map(c => ({
      time: c.time as Time,
      value: c.volume,
      color: c.close >= c.open ? 'rgba(0,200,150,0.25)' : 'rgba(255,77,79,0.25)',
    }));

    try {
      seriesRef.current.setData(formatted);
      volumeRef.current.setData(volumeData);

      // Auto-fit to show last ~80 candles for proper MT5-style candle sizing
      seriesRef.current.priceScale().applyOptions({ autoScale: true });
      const totalBars = formatted.length;
      if (totalBars > 0 && chartRef.current) {
        const visibleBars = Math.min(80, totalBars);
        chartRef.current.timeScale().setVisibleLogicalRange({
          from: totalBars - visibleBars,
          to: totalBars + 15,
        });
      }

      // Force chart to take container size (needed inside Electron)
      if (containerRef.current && chartRef.current) {
        const { offsetWidth, offsetHeight } = containerRef.current;
        chartRef.current.applyOptions({ width: offsetWidth, height: offsetHeight });
      }

      console.log('[Chart] Chart data updated successfully');
    } catch (e) {
      console.error('[Chart] Error setting chart data:', e);
      setApiError(`Data Format Error: ${e instanceof Error ? e.message : String(e)}`);
    }
  }, []);

  // Load historical data
  const loadHistory = useCallback(async () => {
    if (isDisposedRef.current || !symbol) {
      console.log('[Chart] Cannot load history - symbol not set or chart disposed');
      return;
    }

    setIsLoading(true);
    setApiError(null);
    console.log(`[Chart] Loading history for ${symbol}, timeframe: ${timeframe}`);

    try {
      const token = localStorage.getItem('auth_token');
      // Use relative URL ΓåÆ Vite proxy ΓåÆ backend (avoids CORS when in browser/dev)
      const url = `/api/fix/candles/${symbol}?timeframe=${timeframe}&limit=500`;

      console.log(`[Chart] Fetching: ${url}`);

      const response = await fetch(url, {
        headers: token ? { 'Authorization': `Bearer ${token}` } : {}
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();

      // Handle both { candles: [] } and direct array response
      const rawCandles = Array.isArray(data) ? data : (data.candles || []);
      console.log(`[Chart] Received ${rawCandles.length} candles`, data);

      // If API returns empty candles, initialize series so live ticks can build candles
      if (rawCandles.length === 0) {
        console.log(`[Chart] No historical candles for ${symbol} ${timeframe} ΓÇö live-only mode`);
        // Init series with empty data so tick update() calls work properly
        if (seriesRef.current) seriesRef.current.setData([]);
        if (volumeRef.current) volumeRef.current.setData([]);
        // Position at current time so live ticks appear in view
        if (chartRef.current) {
          chartRef.current.timeScale().scrollToRealTime();
        }
        setApiError(`No history for ${symbol} on ${timeframe} ΓÇö showing live ticks only`);
        setIsLoading(false);
        return;
      }

      const candles: Candle[] = rawCandles
        .filter((c: any) => c && (c.time ?? c.Time) != null && (c.open ?? c.Open) != null)
        .map((c: any) => ({
          time: typeof (c.time ?? c.Time) === 'string' ? new Date(c.time ?? c.Time).getTime() / 1000 : Number(c.time ?? c.Time),
          open: Number(c.open ?? c.Open) || 0,
          high: Number(c.high ?? c.High) || 0,
          low: Number(c.low ?? c.Low) || 0,
          close: Number(c.close ?? c.Close) || 0,
          volume: Number(c.volume ?? c.Volume) || 0,
        }));

      // Sort by time ascending
      candles.sort((a, b) => a.time - b.time);
      candlesRef.current = candles;

      // Feed historical candles into the aggregation service
      // This enables proper candle building from where historical data ends
      const ohlcvCandles: OHLCV[] = candles.map(c => ({
        time: c.time,
        open: c.open,
        high: c.high,
        low: c.low,
        close: c.close,
        volume: c.volume,
      }));
      candleAggregationService.loadHistoricalCandles(symbol, timeframe as AggTimeframe, ohlcvCandles);
      console.log(`[Chart] Loaded ${ohlcvCandles.length} historical candles into aggregation service for ${symbol} ${timeframe}`);

      // Update chart - live data
      setApiError(null);
      updateChartData(candles);

      // Set current forming candle
      if (candles.length > 0) {
        const last = candles[candles.length - 1];
        currentCandleRef.current = { ...last };
        setLegend({ o: last.open, h: last.high, l: last.low, c: last.close, v: last.volume });
        console.log(`[Chart] Last candle time: ${last.time}, close: ${last.close}`);

        // Initialize price line with last known price for non-live markets
        if (priceLineRef.current) {
          priceLineRef.current.applyOptions({ price: last.close, color: '#758696' }); // Neutral color until live tick
          prevPriceRef.current = last.close;
        }
      }

    } catch (err: any) {
      console.error('[Chart] Failed to load history:', err);
      const errMsg = err?.message || 'Unknown error';
      setApiError(`API error: ${errMsg}`);
    } finally {
      setIsLoading(false);
    }
  }, [symbol, timeframe, updateChartData]);

  // Load more historical data (infinite scroll)
  const loadMoreHistory = useCallback(async () => {
    if (isDisposedRef.current || !symbol || isLoadingMoreRef.current || hasReachedBeginningRef.current) return;

    const oldestCandle = candlesRef.current[0];
    if (!oldestCandle) return;

    isLoadingMoreRef.current = true;
    console.log(`[Chart] Infinite scroll: Fetching 5000 more candles before ${oldestCandle.time}`);

    try {
      const token = localStorage.getItem('auth_token');
      const url = `/api/fix/candles/${symbol}?timeframe=${timeframe}&limit=5000&to=${Math.floor(oldestCandle.time)}`;
      const response = await fetch(url, {
        headers: token ? { 'Authorization': `Bearer ${token}` } : {}
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();

      const rawCandles = Array.isArray(data) ? data : (data.candles || []);

      if (rawCandles.length === 0) {
        console.log(`[Chart] Reached absolute beginning of chart history for ${symbol}`);
        hasReachedBeginningRef.current = true;
        return;
      }

      const olderCandles: Candle[] = rawCandles
        .filter((c: any) => c && (c.time ?? c.Time) != null && (c.open ?? c.Open) != null)
        .map((c: any) => ({
          time: typeof (c.time ?? c.Time) === 'string' ? new Date(c.time ?? c.Time).getTime() / 1000 : Number(c.time ?? c.Time),
          open: Number(c.open ?? c.Open) || 0,
          high: Number(c.high ?? c.High) || 0,
          low: Number(c.low ?? c.Low) || 0,
          close: Number(c.close ?? c.Close) || 0,
          volume: Number(c.volume ?? c.Volume) || 0,
        }));

      // If we got fewer than requested, we probably hit the beginning of the market data
      if (olderCandles.length < 4000) {
        hasReachedBeginningRef.current = true;
      }

      // Filter out overlapping candles
      const newCandles = olderCandles.filter(c => c.time < oldestCandle.time);
      if (newCandles.length === 0) {
        hasReachedBeginningRef.current = true;
        return;
      }

      newCandles.sort((a, b) => a.time - b.time);
      console.log(`[Chart] Fetched ${newCandles.length} older candles`);

      // Prepend to current array
      candlesRef.current = [...newCandles, ...candlesRef.current];

      // Re-hydrate the chart with the new full array 
      // WITHOUT snapping the viewport to the right edge
      const activeType = prevChartTypeRef.current || 'candlestick';
      let formatted: any[];
      if (activeType === 'line' || activeType === 'area') {
        formatted = candlesRef.current.map(c => ({ time: c.time as Time, value: c.close }));
      } else {
        formatted = candlesRef.current.map(c => ({
          time: c.time as Time, open: c.open, high: c.high, low: c.low, close: c.close
        }));
      }

      const volumeData = candlesRef.current.map(c => ({
        time: c.time as Time,
        value: c.volume,
        color: c.close >= c.open ? 'rgba(0,200,150,0.25)' : 'rgba(255,77,79,0.25)',
      }));

      // Update series but maintain current left logical index so it visually stays in place
      if (seriesRef.current && volumeRef.current && chartRef.current) {
        // Temporarily save current range
        const timeScale = chartRef.current.timeScale();
        const currentPos = timeScale.scrollPosition();

        seriesRef.current.setData(formatted);
        volumeRef.current.setData(volumeData);

        // Shift position rightward so the view doesn't jump
        timeScale.scrollToPosition(currentPos + newCandles.length, false);
      }

      // Update aggregation service history with these older ones too
      const ohlcvCandles: OHLCV[] = newCandles.map(c => ({
        time: c.time,
        open: c.open,
        high: c.high,
        low: c.low,
        close: c.close,
        volume: c.volume,
      }));
      // We push strictly old candles so prepending isn't perfectly supported by the service,
      // but it mostly cares about building forward, so we can ignore adding historical prior to 0 here.

    } catch (err) {
      console.error('[Chart] Failed to load older history:', err);
    } finally {
      isLoadingMoreRef.current = false;
    }
  }, [symbol, timeframe]);

  // Keep ref pointing to the latest loadMoreHistory
  useEffect(() => {
    loadMoreHistoryRef.current = loadMoreHistory;
  }, [loadMoreHistory]);

  // Track previous chart type, symbol, and timeframe to avoid unnecessary recreation
  const prevChartTypeRef = useRef<ChartType>(chartType);
  const prevSymbolRef = useRef<string>(symbol);
  const prevTimeframeRef = useRef<Timeframe>(timeframe);

  // Create series when chart type, symbol, or timeframe changes
  useEffect(() => {
    if (isDisposedRef.current || !chartRef.current) return;

    // Check what changed
    const typeChanged = prevChartTypeRef.current !== chartType;
    const symbolChanged = prevSymbolRef.current !== symbol;
    const timeframeChanged = prevTimeframeRef.current !== timeframe;

    if (seriesRef.current && !typeChanged) {
      if (!symbolChanged && !timeframeChanged) {
        // Nothing changed
        console.log(`[TradingChart] Series already exists for ${chartType}/${symbol}/${timeframe}, skipping`);
        if (candlesRef.current.length > 0) {
          updateChartData(candlesRef.current, chartType);
        }
        return;
      } else if (timeframeChanged && !symbolChanged) {
        // ONLY timeframe changed ΓÇö clear old data and reload for new timeframe
        console.log(`[TradingChart] Timeframe changed to ${timeframe}, clearing old data and reloading`);

        candlesRef.current = [];
        currentCandleRef.current = null;
        hasReachedBeginningRef.current = false;
        isLoadingMoreRef.current = false;
        prevTimeframeRef.current = timeframe;

        // Clear existing visual data
        seriesRef.current.setData([]);
        if (volumeRef.current) volumeRef.current.setData([]);
        if (priceLineRef.current) {
          priceLineRef.current.applyOptions({ price: -1000000 });
        }

        // Reset aggregation service for new timeframe
        candleAggregationService.loadHistoricalCandles(symbol, timeframe as AggTimeframe, []);

        // Trigger history load for new timeframe
        loadHistory();
        return;
      } else {
        // ONLY symbol changed. Do NOT destroy the series! (Prevents Lightweight Charts disposal bug)
        console.log(`[TradingChart] Symbol changed to ${symbol}, updating existing series format`);

        candlesRef.current = [];
        currentCandleRef.current = null;
        prevPriceRef.current = null;
        hasReachedBeginningRef.current = false;
        isLoadingMoreRef.current = false;
        prevSymbolRef.current = symbol;
        prevTimeframeRef.current = timeframe;

        // Apply new precision
        const digits = getSymbolDigits(symbol);
        const minMove = 1 / Math.pow(10, digits);
        seriesRef.current.applyOptions({
          priceFormat: { type: 'price', precision: digits, minMove }
        });

        // Clear existing visual data
        seriesRef.current.setData([]);
        if (volumeRef.current) volumeRef.current.setData([]);
        if (priceLineRef.current) {
          priceLineRef.current.applyOptions({ price: -1000000 }); // Move offscreen until first tick
        }

        // Update drawing manager with new symbol context
        const overlayEl = containerRef.current?.parentElement?.querySelector('.chart-drawing-overlay') as HTMLElement | null;
        drawingManager.setChart(chartRef.current, seriesRef.current, symbol, 1, overlayEl);

        // Trigger history load for new symbol
        loadHistory();
        return;
      }
    }

    // If we're here, chart type changed or it's the very first time. Rebuild required.
    prevChartTypeRef.current = chartType;
    prevSymbolRef.current = symbol;
    prevTimeframeRef.current = timeframe;

    const hasCachedData = candlesRef.current.length > 0;

    if (symbolChanged && !seriesRef.current) {
      candlesRef.current = [];
      currentCandleRef.current = null;
      prevPriceRef.current = null;
    }

    // Only block ticks during rebuild when we DON'T have cached data
    // (With cached data, setData happens synchronously ΓÇö no tick window)
    if (!hasCachedData) {
      isRebuildingRef.current = true;
    }

    // Remove old series
    if (seriesRef.current) {
      if (priceLineRef.current) {
        try { seriesRef.current.removePriceLine(priceLineRef.current); } catch { }
        priceLineRef.current = null;
      }
      try { chartRef.current!.removeSeries(seriesRef.current); } catch { }
      seriesRef.current = null;
    }
    if (volumeRef.current) {
      try { chartRef.current!.removeSeries(volumeRef.current); } catch { }
      volumeRef.current = null;
    }

    // Create new series
    const chart = chartRef.current;
    let series: ISeriesApi<any>;

    // Compute price format based on symbol
    const digits = getSymbolDigits(symbol);
    const minMove = 1 / Math.pow(10, digits); // e.g. 0.01 for 2 digits, 0.00001 for 5
    const priceFormatOpts = { type: 'price' as const, precision: digits, minMove };

    console.log(`[TradingChart] Creating series for chartType=${chartType}, symbol=${symbol}, digits=${digits}`);

    switch (chartType) {
      case 'candlestick':
        series = chart.addSeries(CandlestickSeries, {
          upColor: '#00c896',
          downColor: '#ff4d4f',
          borderVisible: true,
          wickVisible: true,
          borderColor: '#00c896',
          borderUpColor: '#00c896',
          borderDownColor: '#ff4d4f',
          wickUpColor: '#00c896',
          wickDownColor: '#ff4d4f',
          priceFormat: priceFormatOpts,
        });
        break;
      case 'bar':
        series = chart.addSeries(BarSeries, {
          upColor: '#00c896',
          downColor: '#ff4d4f',
          priceFormat: priceFormatOpts,
        });
        break;
      case 'line':
        series = chart.addSeries(LineSeries, {
          color: '#2962FF',
          lineWidth: 2,
          priceFormat: priceFormatOpts,
        });
        break;
      case 'area':
        series = chart.addSeries(AreaSeries, {
          lineColor: '#2962FF',
          topColor: 'rgba(41, 98, 255, 0.4)',
          bottomColor: 'rgba(41, 98, 255, 0.0)',
          priceFormat: priceFormatOpts,
        });
        break;
      default:
        series = chart.addSeries(CandlestickSeries, {
          upColor: '#26a69a',
          downColor: '#ef5350',
          priceFormat: priceFormatOpts,
        });
    }

    seriesRef.current = series;
    console.log(`[TradingChart] Series created and stored in ref`);

    // Create volume series
    const volSeries = chart.addSeries(HistogramSeries, {
      color: '#26a69a',
      priceScaleId: '',
      priceFormat: { type: 'volume' },
    });
    volSeries.priceScale().applyOptions({ scaleMargins: { top: 0.85, bottom: 0 } });
    volumeRef.current = volSeries;

    // Create live price line (MT5 style - horizontal dashed line, no axis label)
    priceLineRef.current = series.createPriceLine({
      price: 0,
      color: '#2962FF',
      lineWidth: 1,
      lineStyle: 2,
      axisLabelVisible: false,
      title: '',
    });

    // Set data if available
    if (candlesRef.current.length > 0) {
      console.log(`[TradingChart] Setting existing ${candlesRef.current.length} candles`);
      updateChartData(candlesRef.current, chartType);
    } else {
      // Try to load history now that series is ready
      console.log(`[TradingChart] No cached candles, triggering history load`);
      loadHistory();
    }

    // Fallback: only trigger if no data yet (not needed when chart type switching with cached data)
    if (!hasCachedData) {
      setTimeout(() => {
        if (candlesRef.current.length === 0 && seriesRef.current) {
          console.log(`[TradingChart] Fallback: triggering delayed history load`);
          loadHistory();
        }
      }, 500);
    }

    // Update drawing manager with overlay container reference
    const overlayEl = containerRef.current?.parentElement?.querySelector('.chart-drawing-overlay') as HTMLElement | null;
    drawingManager.setChart(chart, series, symbol, 1, overlayEl);

    let isDrawingFreehand = false;

    const clickHandler = (param: any) => {
      if (!param.time || !param.point || !seriesRef.current) return;
      const activeDrawing = drawingManager.getActiveDrawing();
      if (activeDrawing && activeDrawing.type !== 'freehand') {
        const price = seriesRef.current.coordinateToPrice(param.point.y);
        if (price !== null) {
          // Text tool: prompt for label text before placing
          if (activeDrawing.type === 'text' && activeDrawing.points.length === 0) {
            const userText = prompt('Enter text label:');
            if (!userText) {
              // User cancelled ΓÇö don't place the text
              return;
            }
            drawingManager.updateActiveDrawing({ text: userText });
          }
          drawingManager.addPoint(param.time as number, price);
        }
      }
    };
    chart.subscribeClick(clickHandler);

    const handlePointerDown = (e: PointerEvent) => {
      const activeDrawing = drawingManager.getActiveDrawing();
      if (activeDrawing && activeDrawing.type === 'freehand') {
        isDrawingFreehand = true;
      }
    };

    if (containerRef.current) {
      containerRef.current.addEventListener('pointerdown', handlePointerDown as EventListener);
    }

    const handlePointerUp = () => {
      if (isDrawingFreehand) {
        isDrawingFreehand = false;
        const activeDrawing = drawingManager.getActiveDrawing();
        if (activeDrawing && activeDrawing.points.length > 1) {
          drawingManager.finishDrawing();
        } else if (activeDrawing) {
          drawingManager.cancelDrawing();
        }
      }
    };
    window.addEventListener('pointerup', handlePointerUp);

    const crosshairHandler = (param: any) => {
      if (param.time && param.point && seriesRef.current) {
        const price = seriesRef.current.coordinateToPrice(param.point.y);
        if (price !== null) {
          if (isDrawingFreehand) {
            drawingManager.addPoint(param.time as number, price);
            drawingManager.renderAllDrawings();
          } else {
            const activeDrawing = drawingManager.getActiveDrawing();
            if (activeDrawing && activeDrawing.points.length > 0) {
              drawingManager.updatePreviewPoint(param.time as number, price);
            }
          }
        }
      } else {
        // Clear preview if mouse leaves chart
        drawingManager.updatePreviewPoint(0, 0); // Or handle it cleanly
      }
    };
    chart.subscribeCrosshairMove(crosshairHandler);

    // Save cleanup functions to chart object or local scope for unmount
    (chart as any)._cleanupDrawings = () => {
      chart.unsubscribeClick(clickHandler);
      chart.unsubscribeCrosshairMove(crosshairHandler);
      if (containerRef.current) {
        containerRef.current.removeEventListener('pointerdown', handlePointerDown as EventListener);
      }
      window.removeEventListener('pointerup', handlePointerUp);
    };

    isRebuildingRef.current = false; // Safe to resume ticks and resizes
  }, [chartType, symbol, loadHistory, updateChartData]);

  // Helper: Get timeframe in seconds
  const getTimeframeSeconds = (tf: Timeframe): number => {
    const map: Record<Timeframe, number> = {
      M1: 60, M5: 300, M15: 900, M30: 1800,
      H1: 3600, H4: 14400, D1: 86400, W1: 604800, MN: 2592000,
    };
    return map[tf] || 60;
  };

  // Load history when symbol/timeframe changes
  useEffect(() => {
    if (!symbol) {
      console.log('[Chart] No symbol, skipping history load');
      return;
    }
    // Load history even if series is not ready - data will be stored and applied when series is created
    console.log(`[Chart] Triggering history load for ${symbol} ${timeframe}`);
    loadHistory();
  }, [symbol, timeframe, loadHistory, loadMoreHistory]);

  // Subscribe to ticks from global store (shared WebSocket)
  // Uses CandleAggregationService for proper candle building
  useEffect(() => {
    if (!symbol) return;

    console.log(`[Chart] Subscribing to ticks for ${symbol} on ${timeframe} (via aggregation service)`);

    const normalizedSymbol = symbol.replace(/[^a-zA-Z0-9]/g, '').toUpperCase();
    let lastTickTimestamp = 0; // Deduplicate ticks

    // Check for ticks periodically (every 100ms)
    const interval = setInterval(() => {
      if (isDisposedRef.current || isRebuildingRef.current || !seriesRef.current) return;

      const state = useAppStore.getState();
      // Try exact match first
      let tick = state.ticks[symbol];
      // Try uppercase
      if (!tick) tick = state.ticks[symbol.toUpperCase()];
      // Try normalized (no special chars)
      if (!tick) {
        const match = Object.keys(state.ticks).find(k =>
          k.replace(/[^a-zA-Z0-9]/g, '').toUpperCase() === normalizedSymbol
        );
        if (match) tick = state.ticks[match];
      }

      if (tick && tick.bid) {
        const price = (tick.bid + (tick.ask || tick.bid)) / 2;

        // Normalize timestamp - handle both milliseconds and seconds
        let timestamp = tick.timestamp || Math.floor(Date.now() / 1000);
        if (timestamp > 1_000_000_000_000) {
          timestamp = Math.floor(timestamp / 1000);
        }

        // Skip duplicate ticks
        if (timestamp === lastTickTimestamp && prevPriceRef.current === price) return;
        lastTickTimestamp = timestamp;

        // Update price line
        if (priceLineRef.current) {
          const prevPrice = prevPriceRef.current;
          let color = '#2962FF';
          if (prevPrice !== null) {
            if (price > prevPrice) color = '#26a69a';
            else if (price < prevPrice) color = '#ef5350';
          }
          priceLineRef.current.applyOptions({ price: tick.bid, color });
          prevPriceRef.current = price;
        }

        // Process tick through the aggregation service
        // This handles M1 candle creation, completion, and higher TF building
        const tickTimestampMs = timestamp < 1_000_000_000_000 ? timestamp * 1000 : timestamp;
        const updates = candleAggregationService.processTick({
          symbol,
          bid: tick.bid,
          ask: tick.ask || tick.bid,
          timestamp: tickTimestampMs,
          volume: 1,
        });

        // Get the updated candle for current timeframe from the service
        const updatedCandle = updates.get(timeframe as AggTimeframe);
        if (updatedCandle) {
          // Check if a new candle started (different time than current)
          if (!currentCandleRef.current || currentCandleRef.current.time !== updatedCandle.time) {
            // A new candle period started
            // Get all candles from the service to keep candlesRef in sync
            const allCandles = candleAggregationService.getCandles(symbol, timeframe as AggTimeframe, false);
            candlesRef.current = allCandles.map(c => ({
              time: c.time, open: c.open, high: c.high, low: c.low, close: c.close, volume: c.volume
            }));
          }

          // Update the current forming candle
          currentCandleRef.current = {
            time: updatedCandle.time,
            open: updatedCandle.open,
            high: updatedCandle.high,
            low: updatedCandle.low,
            close: updatedCandle.close,
            volume: updatedCandle.volume,
          };
        } else {
          // Fallback: manual candle building if service didn't return for this TF
          const tfSeconds = getTimeframeSeconds(timeframe);
          const candleTime = Math.floor(timestamp / tfSeconds) * tfSeconds;

          if (!currentCandleRef.current || currentCandleRef.current.time !== candleTime) {
            if (currentCandleRef.current) {
              candlesRef.current.push(currentCandleRef.current);
              if (candlesRef.current.length > 500) {
                candlesRef.current = candlesRef.current.slice(-500);
              }
            }
            currentCandleRef.current = {
              time: candleTime, open: price, high: price, low: price, close: price, volume: 1
            };
          } else {
            const c = currentCandleRef.current;
            c.high = Math.max(c.high, price);
            c.low = Math.min(c.low, price);
            c.close = price;
            c.volume += 1;
          }
        }

        // Update chart with current candle
        if (currentCandleRef.current) {
          const c = currentCandleRef.current;
          try {
            if (chartType === 'line' || chartType === 'area') {
              seriesRef.current.update({ time: c.time as Time, value: c.close });
            } else {
              seriesRef.current.update({
                time: c.time as Time, open: c.open, high: c.high, low: c.low, close: c.close
              });
            }
            if (volumeRef.current) {
              volumeRef.current.update({
                time: c.time as Time, value: c.volume,
                color: c.close >= c.open ? 'rgba(22, 163, 74, 0.3)' : 'rgba(220, 38, 38, 0.3)'
              });
            }
            setLegend({ o: c.open, h: c.high, l: c.low, c: c.close, v: c.volume });
          } catch (e) {
            // Ignore update errors
          }
        }
      }
    }, 100);

    return () => {
      console.log(`[Chart] Unsubscribing from ticks for ${symbol}`);
      clearInterval(interval);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [symbol, timeframe, chartType]); // handleTick removed to prevent interval restart

  // The primary tick aggregation interval handles all live OHLCV updates perfectly.

  // Native autoSize handles resizing internally

  // Handle ZOOM_IN / ZOOM_OUT commands from toolbar buttons only (no mouse wheel zoom)
  useEffect(() => {
    const handleZoomIn = () => {
      if (isDisposedRef.current || !chartRef.current) return;
      try {
        const timeScale = chartRef.current.timeScale();
        const visibleRange = timeScale.getVisibleLogicalRange();
        if (!visibleRange) return;
        const center = (visibleRange.from + visibleRange.to) / 2;
        const half = (visibleRange.to - visibleRange.from) / 2;
        // Zoom in = show 20% fewer bars (bigger candles)
        const newHalf = Math.max(half * 0.8, 5);
        timeScale.setVisibleLogicalRange({ from: center - newHalf, to: center + newHalf });
      } catch (e) { /* disposed */ }
    };

    const handleZoomOut = () => {
      if (isDisposedRef.current || !chartRef.current) return;
      try {
        const timeScale = chartRef.current.timeScale();
        const visibleRange = timeScale.getVisibleLogicalRange();
        if (!visibleRange) return;
        const center = (visibleRange.from + visibleRange.to) / 2;
        const half = (visibleRange.to - visibleRange.from) / 2;
        // Zoom out = show 25% more bars (smaller candles)
        const newHalf = Math.min(half * 1.25, 2500);
        timeScale.setVisibleLogicalRange({ from: center - newHalf, to: center + newHalf });
      } catch (e) { /* disposed */ }
    };

    const unsub1 = commandBus.subscribe('ZOOM_IN', handleZoomIn);
    const unsub2 = commandBus.subscribe('ZOOM_OUT', handleZoomOut);

    // Auto-Scroll (Snap to live edge)
    const unsubAutoScroll = commandBus.subscribe('SET_AUTO_SCROLL' as any, (payload: any) => {
      if (isDisposedRef.current || !chartRef.current) return;
      try {
        const enabled = payload?.enabled === true;
        autoScrollEnabledRef.current = enabled;
        if (enabled) {
          chartRef.current.timeScale().scrollToRealTime();
        }
      } catch (e) { /* disposed */ }
    });

    // Chart Shift (Right Margin)
    const unsubChartShift = commandBus.subscribe('SET_CHART_SHIFT' as any, (payload: any) => {
      if (isDisposedRef.current || !chartRef.current) return;
      try {
        const enabled = payload?.enabled === true;
        chartRef.current.timeScale().applyOptions({
          rightOffset: enabled ? 15 : 0
        });
        if (enabled) chartRef.current.timeScale().scrollToRealTime();
      } catch (e) { /* disposed */ }
    });

    return () => {
      unsub1();
      unsub2();
      unsubAutoScroll();
      unsubChartShift();
    };
  }, []);

  // Handle SELECT_TOOL command ΓÇö bridge toolbar buttons to drawingManager
  useEffect(() => {
    const unsubSelectTool = commandBus.subscribe('SELECT_TOOL', (payload) => {
      const tool = payload.tool;

      // Cancel any active drawing first
      drawingManager.cancelDrawing();

      if (tool === 'cursor') {
        // Cursor mode ΓÇö restore built-in pan/scroll, keep mouseWheel off scale
        drawingManager.unselectAll();
        if (chartRef.current) {
          chartRef.current.applyOptions({
            handleScroll: { mouseWheel: true, pressedMouseMove: true, horzTouchDrag: true },
            handleScale: { mouseWheel: false, pinch: false, axisPressedMouseMove: false },
          });
        }
        console.log('[Chart] Tool: cursor (selection mode)');
      } else {
        // Start a new drawing ΓÇö but always keep scroll pan active
        if (chartRef.current) {
          chartRef.current.applyOptions({
            handleScroll: { mouseWheel: true, pressedMouseMove: true, horzTouchDrag: true },
            handleScale: { mouseWheel: false, pinch: false, axisPressedMouseMove: false },
          });
        }
        const validDrawingTypes = ['trendline', 'hline', 'vline', 'text', 'channel', 'fibonacci', 'shapes', 'rectangle', 'ellipse', 'fib_extension', 'measure', 'freehand', 'callout'];
        if (validDrawingTypes.includes(tool)) {
          drawingManager.startDrawing(tool as any, '#8a8a8f');
          console.log(`[Chart] Tool: ${tool} ΓÇö drawing started, click on chart to place points`);
        } else {
          console.log(`[Chart] Tool: ${tool} ΓÇö not a drawing tool, ignoring`);
        }
      }
    });

    return () => {
      unsubSelectTool();
    };
  }, []);

  // Handle UNDO / REDO / DELETE commands from toolbar
  useEffect(() => {
    const unsubUndo = commandBus.subscribe('UNDO', () => {
      drawingManager.undo();
      console.log('[Chart] Undo drawing');
    });

    const unsubRedo = commandBus.subscribe('REDO', () => {
      drawingManager.redo();
      console.log('[Chart] Redo drawing');
    });

    const unsubDeleteSelected = commandBus.subscribe('DELETE_SELECTED_DRAWING', () => {
      drawingManager.deleteSelected();
      console.log('[Chart] Deleted selected drawings');
    });

    const unsubDeleteById = commandBus.subscribe('DELETE_DRAWING', (payload) => {
      drawingManager.deleteDrawing(payload.id);
      console.log(`[Chart] Deleted drawing: ${payload.id}`);
    });

    return () => {
      unsubUndo();
      unsubRedo();
      unsubDeleteSelected();
      unsubDeleteById();
    };
  }, []);

  // Handle TOGGLE_CROSSHAIR command
  useEffect(() => {
    const unsubCrosshair = commandBus.subscribe('TOGGLE_CROSSHAIR', () => {
      if (!chartRef.current) return;
      const current = chartRef.current.options().crosshair?.mode;
      const newMode = current === CrosshairMode.Normal ? CrosshairMode.Magnet : CrosshairMode.Normal;
      chartRef.current.applyOptions({
        crosshair: { mode: newMode },
      });
      console.log(`[Chart] Crosshair mode: ${newMode === CrosshairMode.Normal ? 'Normal' : 'Magnet'}`);
    });

    return () => {
      unsubCrosshair();
    };
  }, []);

  // Keyboard shortcuts for drawing tools + Alt+T one-click trading
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Skip if user is typing in an input/textarea
      const tag = (e.target as HTMLElement)?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;

      // Alt+T = Toggle One-Click Trading panel (show/hide)
      if (e.altKey && (e.key === 't' || e.key === 'T' || e.code === 'KeyT')) {
        e.preventDefault();
        setShowOneClick(prev => !prev);
        return;
      }

      // Ctrl+Z = Undo
      if (e.ctrlKey && e.key === 'z') {
        e.preventDefault();
        drawingManager.undo();
        console.log('[Chart] Keyboard: Undo');
      }

      // Ctrl+Y = Redo
      if (e.ctrlKey && e.key === 'y') {
        e.preventDefault();
        drawingManager.redo();
        console.log('[Chart] Keyboard: Redo');
      }

      // Delete / Backspace = Delete selected drawing
      if (e.key === 'Delete' || e.key === 'Backspace') {
        // Only delete if not in an input field
        drawingManager.deleteSelected();
        console.log('[Chart] Keyboard: Delete selected');
      }

      // Escape = Cancel active drawing or deselect all
      if (e.key === 'Escape') {
        const active = drawingManager.getActiveDrawing();
        if (active) {
          drawingManager.cancelDrawing();
          console.log('[Chart] Keyboard: Cancelled active drawing');
        } else {
          drawingManager.unselectAll();
          console.log('[Chart] Keyboard: Deselected all');
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    // Listen for toggle-one-click-trading event from dashboard toolbar
    const handleToggleOneClick = () => setShowOneClick(prev => !prev);
    window.addEventListener('toggle-one-click-trading', handleToggleOneClick);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('toggle-one-click-trading', handleToggleOneClick);
    };
  }, []);

  // ΓöÇΓöÇΓöÇ Position Indicators on Chart (MT5-style entry/SL/TP lines) ΓöÇΓöÇΓöÇ
  const positionLinesRef = useRef<any[]>([]);
  const markersHandleRef = useRef<any>(null);
  const positionLabelsRef = useRef<HTMLDivElement[]>([]);
  const positionLabelDataRef = useRef<{ price: number; text: string; color: string }[]>([]);

  // Helper: update left-side label Y positions based on current chart scale
  const updateLabelPositions = useCallback(() => {
    if (!seriesRef.current || positionLabelsRef.current.length === 0) return;
    const series = seriesRef.current;
    const labels = positionLabelsRef.current;
    const data = positionLabelDataRef.current;

    for (let i = 0; i < labels.length; i++) {
      const label = labels[i];
      const d = data[i];
      if (!label || !d) continue;
      try {
        const y = series.priceToCoordinate(d.price);
        if (y === null || y < 0) {
          label.style.display = 'none';
        } else {
          label.style.display = 'flex';
          label.style.top = `${y - 9}px`; // center vertically on the line
        }
      } catch {
        label.style.display = 'none';
      }
    }
  }, []);

  // Subscribe to positions from the store and render price lines
  useEffect(() => {
    if (isDisposedRef.current || !seriesRef.current || !symbol) return;

    const overlayEl = containerRef.current?.parentElement?.querySelector('.chart-drawing-overlay') as HTMLElement | null;

    const cleanup = () => {
      // Remove all existing position lines
      if (seriesRef.current) {
        for (const line of positionLinesRef.current) {
          try { seriesRef.current.removePriceLine(line); } catch { }
        }
      }
      positionLinesRef.current = [];
      // Remove all custom left-side labels
      for (const label of positionLabelsRef.current) {
        try { label.remove(); } catch { }
      }
      positionLabelsRef.current = [];
      positionLabelDataRef.current = [];
    };

    const createLeftLabel = (text: string, color: string, price: number) => {
      if (!overlayEl) return;
      const label = document.createElement('div');
      label.style.cssText = `
        position: absolute;
        left: 4px;
        display: flex;
        align-items: center;
        gap: 3px;
        padding: 1px 6px;
        background: ${color}22;
        border: 1px solid ${color}66;
        border-radius: 3px;
        color: ${color};
        font-size: 10px;
        font-family: Consolas, monospace;
        font-weight: 600;
        white-space: nowrap;
        z-index: 5;
        pointer-events: none;
        line-height: 16px;
      `;
      label.textContent = text;
      overlayEl.appendChild(label);
      positionLabelsRef.current.push(label);
      positionLabelDataRef.current.push({ price, text, color });
    };

    const renderPositionLines = () => {
      if (isDisposedRef.current || !seriesRef.current) return;

      cleanup();

      const state = useAppStore.getState();
      const positions = state.positions || [];

      // Filter positions for this chart's symbol
      const normalizedChartSymbol = symbol.replace(/[^a-zA-Z0-9]/g, '').toUpperCase();
      const myPositions = positions.filter(p => {
        const posSymbol = (p.symbol || '').replace(/[^a-zA-Z0-9]/g, '').toUpperCase();
        return posSymbol === normalizedChartSymbol || posSymbol.startsWith(normalizedChartSymbol) || normalizedChartSymbol.startsWith(posSymbol);
      });

      console.log(`[TradingChart] Found ${myPositions.length} positions for chart symbol ${symbol} (out of ${positions.length} total)`);

      if (myPositions.length === 0) return;

      const series = seriesRef.current;
      const markers: any[] = [];

      for (const pos of myPositions) {
        const isBuy = pos.side === 'BUY';
        const entryColor = isBuy ? '#26a69a' : '#ef5350';

        // Entry price line ΓÇö no title (label rendered as custom HTML on left side)
        if (pos.openPrice > 0) {
          const entryLine = series.createPriceLine({
            price: pos.openPrice,
            color: entryColor,
            lineWidth: 1,
            lineStyle: 2, // Dashed
            axisLabelVisible: false,
            title: '',
          });
          positionLinesRef.current.push(entryLine);
          // Create left-side label
          createLeftLabel(`${isBuy ? 'BUY' : 'SELL'} ${pos.volume}`, entryColor, pos.openPrice);
        }

        // Stop Loss line ΓÇö label on LEFT via custom HTML
        if (pos.sl && pos.sl > 0) {
          const slLine = series.createPriceLine({
            price: pos.sl,
            color: '#ef5350',
            lineWidth: 1,
            lineStyle: 3, // Dotted
            axisLabelVisible: false,
            title: '',
          });
          positionLinesRef.current.push(slLine);
          createLeftLabel(`SL ${pos.sl}`, '#ef5350', pos.sl);
        }

        // Take Profit line ΓÇö label on LEFT via custom HTML
        if (pos.tp && pos.tp > 0) {
          const tpLine = series.createPriceLine({
            price: pos.tp,
            color: '#26a69a',
            lineWidth: 1,
            lineStyle: 3, // Dotted
            axisLabelVisible: false,
            title: '',
          });
          positionLinesRef.current.push(tpLine);
          createLeftLabel(`TP ${pos.tp}`, '#26a69a', pos.tp);
        }

        // Add marker (arrow) at position open time
        if (pos.openTime) {
          let openTimestamp: number;
          if (typeof pos.openTime === 'string') {
            openTimestamp = Math.floor(new Date(pos.openTime).getTime() / 1000);
          } else {
            openTimestamp = Number(pos.openTime);
            if (openTimestamp > 1_000_000_000_000) openTimestamp = Math.floor(openTimestamp / 1000);
          }

          if (openTimestamp > 0) {
            markers.push({
              time: openTimestamp as Time,
              position: isBuy ? 'belowBar' : 'aboveBar',
              color: isBuy ? '#26a69a' : '#ef5350',
              shape: isBuy ? 'arrowUp' : 'arrowDown',
              text: `${isBuy ? 'BUY' : 'SELL'} ${pos.volume}`,
            });
          }
        }
      }

      // Set markers using v5 createSeriesMarkers API
      if (markersHandleRef.current) {
        try { markersHandleRef.current.detach(); } catch { }
        markersHandleRef.current = null;
      }
      if (markers.length > 0) {
        markers.sort((a, b) => (a.time as number) - (b.time as number));
        try {
          markersHandleRef.current = createSeriesMarkers(series, markers);
        } catch {
          // Ignore marker errors
        }
      }

      // Position labels after creating them
      updateLabelPositions();
    };

    // Render immediately
    renderPositionLines();

    // Update label positions on crosshair move (handles scroll/zoom)
    const crosshairLabelUpdater = () => {
      updateLabelPositions();
    };
    if (chartRef.current) {
      chartRef.current.subscribeCrosshairMove(crosshairLabelUpdater);
    }

    // Also update on time scale changes (scroll, zoom)
    const timeScaleHandler = () => {
      updateLabelPositions();
    };
    if (chartRef.current) {
      chartRef.current.timeScale().subscribeVisibleLogicalRangeChange(timeScaleHandler);
    }

    // Re-render instantly when positions change in the global store
    const unsubscribePositions = useAppStore.subscribe((state, prevState) => {
      if (state.positions !== prevState.positions) {
        console.log(`[TradingChart] Positions updated in store, re-rendering lines for ${symbol}`);
        renderPositionLines();
      }
    });

    return () => {
      unsubscribePositions();
      if (chartRef.current) {
        try { chartRef.current.unsubscribeCrosshairMove(crosshairLabelUpdater); } catch { }
        try { chartRef.current.timeScale().unsubscribeVisibleLogicalRangeChange(timeScaleHandler); } catch { }
      }
      cleanup();
      if (markersHandleRef.current) {
        try { markersHandleRef.current.detach(); } catch { }
        markersHandleRef.current = null;
      }
    };
  }, [symbol, chartType, updateLabelPositions]);


  return (
    <div className="relative w-full h-full bg-[#0d0d0d]">




      {/* API Error banner */}
      {apiError && (
        <div className="absolute bottom-2 left-2 right-2 z-20 flex items-center gap-2 px-3 py-1.5 rounded text-[11px] bg-red-900/80 text-red-200 border border-red-700/60 backdrop-blur-sm">
          <svg className="w-3.5 h-3.5 flex-shrink-0 text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          <span className="flex-1 truncate">{apiError}</span>
          <button
            onClick={() => setApiError(null)}
            className="text-red-400 hover:text-red-200 text-base leading-none px-1"
          >
            ├ù
          </button>
        </div>
      )}

      {/* Loading */}
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/50 z-20">
          <div className="text-white text-sm">Loading {symbol}...</div>
        </div>
      )}



      {/* Chart Container - must have explicit dimensions for lightweight-charts */}
      <div ref={containerRef} className="absolute inset-0 w-full h-full" />

      {/* Drawing Overlay */}
      <div className="chart-drawing-overlay absolute inset-0 pointer-events-none" />

      {/* Drawing Context Menu (Right-click on drawings) */}
      <DrawingContextMenu onClose={() => { }} />

      {/* One-Click Trading Panel (Alt+T to toggle) */}
      <OneClickTrading symbol={symbol} timeframe={timeframe} visible={showOneClick} />
    </div>
  );
});

/**
 * Clean MT5-Style Trading Chart
 * - Loads historical OHLC from /api/fix/candles/{symbol}
 * - WebSocket live tick updates
 * - Single price line (MT5 style)
 * - Proper candle aggregation
 */

import { useEffect, useRef, useState, useCallback } from 'react';
import {
  createChart,
  ColorType,
  CrosshairMode,
  CandlestickSeries,
  LineSeries,
  BarSeries,
  AreaSeries,
  HistogramSeries,
} from 'lightweight-charts';
import type { IChartApi, ISeriesApi, Time } from 'lightweight-charts';
import { drawingManager } from '../services/drawingManager';

export type ChartType = 'candlestick' | 'bar' | 'line' | 'area';
export type Timeframe = 'M1' | 'M5' | 'M15' | 'M30' | 'H1' | 'H4' | 'D1' | 'W1' | 'MN';

interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

interface TradingChartProps {
  symbol: string;
  timeframe?: Timeframe;
  chartType?: ChartType;
}

export function TradingChartClean({
  symbol,
  timeframe = 'M1',
  chartType = 'candlestick',
}: TradingChartProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const seriesRef = useRef<ISeriesApi<any> | null>(null);
  const volumeRef = useRef<ISeriesApi<any> | null>(null);
  const priceLineRef = useRef<any>(null);

  const [legend, setLegend] = useState({ o: 0, h: 0, l: 0, c: 0, v: 0 });
  const [isLoading, setIsLoading] = useState(true);

  const candlesRef = useRef<Candle[]>([]);
  const wsRef = useRef<WebSocket | null>(null);
  const currentCandleRef = useRef<Candle | null>(null);
  const prevPriceRef = useRef<number | null>(null);

  // Initialize chart
  useEffect(() => {
    if (!containerRef.current) return;

    const rootStyle = getComputedStyle(document.body);
    const textColor = rootStyle.getPropertyValue('--text-secondary').trim() || '#A1A1AA';
    const gridColor = rootStyle.getPropertyValue('--border-primary').trim() || '#222226';

    const chart = createChart(containerRef.current, {
      autoSize: true,
      layout: {
        background: { type: ColorType.Solid, color: 'transparent' },
        textColor: textColor,
        attributionLogo: false,
      },
      grid: {
        vertLines: { color: gridColor, style: 2 },
        horzLines: { color: gridColor, style: 2 },
      },
      crosshair: {
        mode: CrosshairMode.Normal,
        vertLine: { color: '#758696', width: 1, style: 2, labelVisible: true },
        horzLine: { color: '#758696', width: 1, style: 2, labelVisible: true },
      },
      rightPriceScale: {
        borderColor: '#2b2b2b',
        scaleMargins: { top: 0.1, bottom: 0.2 },
      },
      timeScale: {
        borderColor: '#2b2b2b',
        timeVisible: true,
        secondsVisible: false,
      },
    });

    chartRef.current = chart;

    // Crosshair move for legend
    chart.subscribeCrosshairMove((param) => {
      if (param.time && seriesRef.current) {
        const data = param.seriesData.get(seriesRef.current) as any;
        if (data) {
          setLegend({
            o: data.open || 0,
            h: data.high || 0,
            l: data.low || 0,
            c: data.close || data.value || 0,
            v: data.volume || 0,
          });
        }
      }
    });

    return () => {
      chart.remove();
      chartRef.current = null;
    };
  }, []);

  // Create series when chart type changes
  useEffect(() => {
    if (!chartRef.current) return;

    // Remove old series
    if (seriesRef.current) {
      if (priceLineRef.current) {
        try { seriesRef.current.removePriceLine(priceLineRef.current); } catch { }
        priceLineRef.current = null;
      }
      try { chartRef.current.removeSeries(seriesRef.current); } catch { }
    }
    if (volumeRef.current) {
      try { chartRef.current.removeSeries(volumeRef.current); } catch { }
    }

    // Create new series
    const chart = chartRef.current;
    let series: ISeriesApi<any>;

    switch (chartType) {
      case 'candlestick':
        series = chart.addSeries(CandlestickSeries, {
          upColor: '#000000',
          downColor: '#ef5350',
          borderUpColor: '#00FF00',
          borderDownColor: '#ef5350',
          wickUpColor: '#00FF00',
          wickDownColor: '#ef5350',
          priceFormat: { type: 'price', precision: 5, minMove: 0.00001 },
        });
        break;
      case 'bar':
        series = chart.addSeries(BarSeries, {
          upColor: '#26a69a',
          downColor: '#ef5350',
        });
        break;
      case 'line':
        series = chart.addSeries(LineSeries, {
          color: '#2962FF',
          lineWidth: 2,
        });
        break;
      case 'area':
        series = chart.addSeries(AreaSeries, {
          lineColor: '#2962FF',
          topColor: 'rgba(41, 98, 255, 0.4)',
          bottomColor: 'rgba(41, 98, 255, 0.0)',
        });
        break;
      default:
        series = chart.addSeries(CandlestickSeries, {
          upColor: '#26a69a',
          downColor: '#ef5350',
        });
    }

    seriesRef.current = series;

    // Create volume series
    const volSeries = chart.addSeries(HistogramSeries, {
      color: '#26a69a',
      priceScaleId: '',
      priceFormat: { type: 'volume' },
    });
    volSeries.priceScale().applyOptions({ scaleMargins: { top: 0.85, bottom: 0 } });
    volumeRef.current = volSeries;

    // Create live price line
    priceLineRef.current = series.createPriceLine({
      price: 0,
      color: '#2962FF',
      lineWidth: 1,
      lineStyle: 2,
      axisLabelVisible: true,
      title: '',
    });

    // Set data if available
    if (candlesRef.current.length > 0) {
      updateChartData(candlesRef.current);
    }

    // Update drawing manager
    drawingManager.setChart(chart, series, symbol);

  }, [chartType, symbol]);

  // Load historical data
  const loadHistory = useCallback(async () => {
    if (!symbol) return;

    setIsLoading(true);
    try {
      const { apiClient } = await import('../api/client');
      const data = await apiClient.get<any>(`/api/fix/candles/${symbol}?timeframe=${timeframe}&limit=200`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('auth_token') || ''}`,
        },
      });

      const candles: Candle[] = (data?.candles || []).map((c: any) => ({
        time: c.time,
        open: Number(c.open),
        high: Number(c.high),
        low: Number(c.low),
        close: Number(c.close),
        volume: Number(c.volume) || 0,
      }));

      // Sort by time
      candles.sort((a, b) => a.time - b.time);
      candlesRef.current = candles;

      updateChartData(candles);

      // Set current forming candle
      if (candles.length > 0) {
        const last = candles[candles.length - 1];
        currentCandleRef.current = { ...last };
        setLegend({ o: last.open, h: last.high, l: last.low, c: last.close, v: last.volume });
      }

    } catch (err) {
      console.error('[Chart] Failed to load history:', err);
    } finally {
      setIsLoading(false);
    }
  }, [symbol, timeframe]);

  // Update chart with candles
  const updateChartData = (candles: Candle[]) => {
    if (!seriesRef.current || !volumeRef.current) return;

    const formatted = candles.map(c => ({
      time: c.time as Time,
      open: c.open,
      high: c.high,
      low: c.low,
      close: c.close,
    }));

    const volumeData = candles.map(c => ({
      time: c.time as Time,
      value: c.volume,
      color: c.close >= c.open ? 'rgba(38, 166, 154, 0.5)' : 'rgba(239, 68, 68, 0.5)',
    }));

    seriesRef.current.setData(formatted);
    volumeRef.current.setData(volumeData);

    // Auto-fit
    seriesRef.current.priceScale().applyOptions({ autoScale: true });
    chartRef.current?.timeScale().fitContent();
  };

  // Connect WebSocket
  useEffect(() => {
    if (!symbol) return;

    // Load history first
    loadHistory();

    // Connect WebSocket
    const wsUrl = import.meta.env.VITE_WS_URL || 'wss://rtxbackend.tradecopier.org/fix-ws';

    const ws = new WebSocket(wsUrl);
    wsRef.current = ws;
    let isUnmounting = false;
    let opened = false;

    ws.onopen = () => {
      opened = true;
      console.log('[Chart] WebSocket connected');
      // Subscribe to symbol ticks
      ws.send(JSON.stringify({ type: 'subscribe', channel: `quotes.${symbol}` }));
    };

    ws.onmessage = (event) => {
      try {
        const msg = JSON.parse(event.data);

        if (msg.type === 'channel_message' && msg.channel?.includes('prices')) {
          const tick = msg.data || msg;
          if (tick.symbol === symbol && tick.bid) {
            handleTick(tick);
          }
        }
      } catch (e) {
        // Ignore parse errors
      }
    };

    ws.onerror = (e) => {
      if (isUnmounting) return;
      console.error('[Chart] WebSocket error:', e);
    };
    ws.onclose = (event) => {
      if (isUnmounting) return;
      if (!opened && import.meta.env.DEV) return;
      console.log(`[Chart] WebSocket closed (code=${event.code})`);
    };

    return () => {
      isUnmounting = true;
      ws.close(1000, 'Component unmounted');
      wsRef.current = null;
    };
  }, [symbol, loadHistory]);

  // Process incoming tick
  const handleTick = (tick: any) => {
    if (!seriesRef.current) return;

    const price = (tick.bid + (tick.ask || tick.bid)) / 2;
    const timestamp = tick.timestamp || Math.floor(Date.now() / 1000);

    // Update price line
    if (priceLineRef.current) {
      const prevPrice = prevPriceRef.current;
      let color = '#2962FF';

      if (prevPrice !== null) {
        if (price > prevPrice) color = '#26a69a';
        else if (price < prevPrice) color = '#ef5350';
      }

      priceLineRef.current.applyOptions({
        price: tick.bid,
        color,
        title: tick.bid.toFixed(5),
        axisLabelColor: color,
      });

      prevPriceRef.current = price;
    }

    // Update current candle
    const tfSeconds = getTimeframeSeconds(timeframe);
    const candleTime = Math.floor(timestamp / tfSeconds) * tfSeconds;

    if (!currentCandleRef.current || currentCandleRef.current.time !== candleTime) {
      // New candle
      if (currentCandleRef.current) {
        // Add completed candle to history
        candlesRef.current.push(currentCandleRef.current);
        if (candlesRef.current.length > 500) {
          candlesRef.current = candlesRef.current.slice(-500);
        }
      }

      // Start new candle
      currentCandleRef.current = {
        time: candleTime,
        open: price,
        high: price,
        low: price,
        close: price,
        volume: 1,
      };
    } else {
      // Update forming candle
      const c = currentCandleRef.current;
      c.high = Math.max(c.high, price);
      c.low = Math.min(c.low, price);
      c.close = price;
      c.volume += 1;
    }

    // Update chart
    if (currentCandleRef.current) {
      const c = currentCandleRef.current;

      if (chartType === 'line' || chartType === 'area') {
        seriesRef.current.update({ time: c.time as Time, value: c.close });
      } else {
        seriesRef.current.update({
          time: c.time as Time,
          open: c.open,
          high: c.high,
          low: c.low,
          close: c.close,
        });
      }

      if (volumeRef.current) {
        volumeRef.current.update({
          time: c.time as Time,
          value: c.volume,
          color: c.close >= c.open ? 'rgba(38, 166, 154, 0.5)' : 'rgba(239, 68, 68, 0.5)',
        });
      }

      // Update legend
      setLegend({ o: c.open, h: c.high, l: c.low, c: c.close, v: c.volume });
    }
  };

  const getTimeframeSeconds = (tf: Timeframe): number => {
    const map: Record<Timeframe, number> = {
      M1: 60, M5: 300, M15: 900, M30: 1800,
      H1: 3600, H4: 14400, D1: 86400, W1: 604800, MN: 2592000,
    };
    return map[tf] || 60;
  };

  return (
    <div className="relative w-full h-full bg-background">
      {/* Legend */}
      <div className="absolute top-2 left-2 z-10 flex gap-4 text-[11px] font-mono bg-background/80 px-2 py-1 rounded border border-border">
        <span className="text-muted-foreground">O: <span className="text-foreground">{legend.o.toFixed(5)}</span></span>
        <span className="text-muted-foreground">H: <span className="text-foreground">{legend.h.toFixed(5)}</span></span>
        <span className="text-muted-foreground">L: <span className="text-foreground">{legend.l.toFixed(5)}</span></span>
        <span className="text-muted-foreground">C: <span className={legend.c >= legend.o ? 'text-profit' : 'text-loss'}>{legend.c.toFixed(5)}</span></span>
        <span className="text-muted-foreground">V: <span className="text-foreground">{legend.v}</span></span>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-background/50 z-20">
          <div className="text-foreground text-sm">Loading {symbol}...</div>
        </div>
      )}

      {/* Chart Container */}
      <div ref={containerRef} className="w-full h-full" />

      {/* Drawing Overlay */}
      <div className="chart-drawing-overlay absolute inset-0 pointer-events-none" />
    </div>
  );
}

/**
 * Trading Signals Panel
 * Display trading signals from signal providers
 */

import { Icon } from './ui/Icon';
import React, { useState, useEffect, useMemo } from 'react';
import {
  useSignalStore,
  type Signal,
  type SignalProvider,
  type SymbolGroup,
  type SignalDirection,
} from '../store/useSignalStore';

type SortField = 'timestamp' | 'symbol' | 'confidence' | 'pnl';
type SortDirection = 'asc' | 'desc';

export function TradingSignals() {
  const {
    signals: allSignals,
    historicalSignals,
    selectedProvider,
    symbolGroupFilter,
    signalTypeFilter,
    timeframeFilter,
    autoRefresh,
    refreshInterval,
    setSelectedProvider,
    setSymbolGroupFilter,
    setSignalTypeFilter,
    setTimeframeFilter,
    setAutoRefresh,
    setRefreshInterval,
    getFilteredSignals,
    getProviderStats,
    refreshSignals,
  } = useSignalStore();

  const [expandedSignalId, setExpandedSignalId] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>('timestamp');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');

  const filteredSignals = getFilteredSignals();

  // Sort signals
  const sortedSignals = useMemo(() => {
    const sorted = [...filteredSignals];
    sorted.sort((a, b) => {
      let aVal: any = a[sortField];
      let bVal: any = b[sortField];

      if (sortField === 'timestamp') {
        aVal = a.timestamp.getTime();
        bVal = b.timestamp.getTime();
      }

      if (aVal < bVal) return sortDirection === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortDirection === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [filteredSignals, sortField, sortDirection]);

  // Auto-refresh
  useEffect(() => {
    if (!autoRefresh) return;

    const interval = setInterval(() => {
      refreshSignals();
    }, refreshInterval * 1000);

    return () => clearInterval(interval);
  }, [autoRefresh, refreshInterval, refreshSignals]);

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortDirection('desc');
    }
  };

  const handleCopyToOrderEntry = (signal: Signal) => {
    // Dispatch custom event with signal data
    window.dispatchEvent(
      new CustomEvent('openOrderEntry', {
        detail: {
          symbol: signal.symbol,
          direction: signal.direction,
          entryPrice: signal.entryPrice,
          stopLoss: signal.stopLoss,
          takeProfit: signal.takeProfit,
          volume: signal.suggestedLotSize,
        },
      })
    );
  };

  const getRiskRewardRatio = (signal: Signal) => {
    const risk = Math.abs(signal.entryPrice - signal.stopLoss);
    const reward = Math.abs(signal.takeProfit - signal.entryPrice);
    return reward / risk;
  };

  const providers: (SignalProvider | 'All')[] = ['All', 'RTX5 Algo', 'FX Maestro', 'CryptoEdge'];
  const symbolGroups: SymbolGroup[] = ['All', 'Forex', 'Crypto', 'Metals'];
  const signalTypes: ('All' | SignalDirection)[] = ['All', 'BUY', 'SELL'];
  const timeframes = ['All', 'M15', 'H1', 'H4', 'D1'];

  // Provider stats for selected provider
  const providerStats =
    selectedProvider !== 'All' ? getProviderStats(selectedProvider) : null;

  return (
    <div className="h-full flex bg-[#131316] text-zinc-300">
      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Header / Controls */}
        <div className="bg-[#252528] border-b border-zinc-700 p-2 flex items-center gap-3 flex-wrap">
          {/* Provider Selector */}
          <div className="flex items-center gap-2">
            <label className="text-xs text-zinc-500">Provider:</label>
            <select
              value={selectedProvider}
              onChange={(e) =>
                setSelectedProvider(e.target.value as SignalProvider | 'All')
              }
              className="px-2 py-1 bg-[#131316] border border-zinc-700 rounded text-xs text-zinc-300 focus:outline-none focus:border-zinc-600"
            >
              {providers.map((p) => (
                <option key={p} value={p}>
                  {p}
                </option>
              ))}
            </select>
          </div>

          {/* Symbol Group Filter */}
          <div className="flex items-center gap-2">
            <label className="text-xs text-zinc-500">Group:</label>
            <select
              value={symbolGroupFilter}
              onChange={(e) => setSymbolGroupFilter(e.target.value as SymbolGroup)}
              className="px-2 py-1 bg-[#131316] border border-zinc-700 rounded text-xs text-zinc-300 focus:outline-none focus:border-zinc-600"
            >
              {symbolGroups.map((g) => (
                <option key={g} value={g}>
                  {g}
                </option>
              ))}
            </select>
          </div>

          {/* Signal Type Filter */}
          <div className="flex items-center gap-2">
            <label className="text-xs text-zinc-500">Type:</label>
            <select
              value={signalTypeFilter}
              onChange={(e) =>
                setSignalTypeFilter(e.target.value as 'All' | SignalDirection)
              }
              className="px-2 py-1 bg-[#131316] border border-zinc-700 rounded text-xs text-zinc-300 focus:outline-none focus:border-zinc-600"
            >
              {signalTypes.map((t) => (
                <option key={t} value={t}>
