  selectedSymbol: string;
  onOpenOrderEntry?: (symbol: string) => void;
}

export const WatchlistManager: React.FC<WatchlistManagerProps> = ({
  onSelectSymbol,
  selectedSymbol,
  onOpenOrderEntry,
}) => {
  const {
    watchlists,
    activeWatchlistId,
    setActiveWatchlist,
    createWatchlist,
    deleteWatchlist,
    renameWatchlist,
    addSymbolToWatchlist,
    removeSymbolFromWatchlist,
    reorderSymbols,
    getActiveWatchlist,
  } = useWatchlistStore();

  const [isCreating, setIsCreating] = useState(false);
  const [isRenaming, setIsRenaming] = useState(false);
  const [newWatchlistName, setNewWatchlistName] = useState('');
  const [renameValue, setRenameValue] = useState('');
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [draggedSymbol, setDraggedSymbol] = useState<string | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [dropdownOpen, setDropdownOpen] = useState(false);

  const activeWatchlist = getActiveWatchlist();

  // Fetch available symbols from API
  const [availableSymbols, setAvailableSymbols] = useState<string[]>([]);
  const [isLoadingSymbols, setIsLoadingSymbols] = useState(false);

  useEffect(() => {
    const fetchSymbols = async () => {
      setIsLoadingSymbols(true);
      try {
        const response = await fetch(API_ENDPOINTS.symbols);
        if (response.ok) {
          const data = await response.json();
          // Handle both array and object response formats
          const symbols = Array.isArray(data) ? data : (data.symbols || []);
          // Extract symbol names if objects, or use directly if strings
          const symbolNames = symbols.map((s: any) =>
            typeof s === 'string' ? s : s.symbol
          ).filter(Boolean);
          setAvailableSymbols(symbolNames);
        } else {
          console.error('Failed to fetch symbols:', response.statusText);
        }
      } catch (error) {
        console.error('Error fetching symbols:', error);
      } finally {
        setIsLoadingSymbols(false);
      }
    };

    fetchSymbols();
  }, []);

  // Filter symbols for search
  const filteredSymbols = availableSymbols.filter((symbol) =>
    symbol.toLowerCase().includes(searchQuery.toLowerCase())
  ).filter((symbol) =>
    !activeWatchlist?.symbols.includes(symbol)
  );

  // Handle create watchlist
  const handleCreateWatchlist = () => {
    if (newWatchlistName.trim()) {
      createWatchlist(newWatchlistName.trim());
      setNewWatchlistName('');
      setIsCreating(false);
    }
  };

  // Handle rename watchlist
  const handleRenameWatchlist = () => {
    if (activeWatchlist && renameValue.trim() && !activeWatchlist.isDefault) {
      renameWatchlist(activeWatchlist.id, renameValue.trim());
      setIsRenaming(false);
      setRenameValue('');
    }
  };

  // Handle delete watchlist
  const handleDeleteWatchlist = (id: string) => {
    if (window.confirm('Are you sure you want to delete this watchlist?')) {
      deleteWatchlist(id);
      setDropdownOpen(false);
    }
  };

  // Handle add symbol from search
  const handleAddSymbol = (symbol: string) => {
    if (activeWatchlist) {
      addSymbolToWatchlist(activeWatchlist.id, symbol);
      setSearchQuery('');
    }
  };

  // Handle remove symbol
  const handleRemoveSymbol = (symbol: string) => {
    if (activeWatchlist) {
      removeSymbolFromWatchlist(activeWatchlist.id, symbol);
    }
  };

  // Drag and drop handlers
  const handleDragStart = (e: React.DragEvent, symbol: string, index: number) => {
    setDraggedSymbol(symbol);
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, dropIndex: number) => {
    e.preventDefault();

    if (draggedSymbol && draggedIndex !== null && activeWatchlist && draggedIndex !== dropIndex) {
      const newSymbols = [...activeWatchlist.symbols];
      newSymbols.splice(draggedIndex, 1);
      newSymbols.splice(dropIndex, 0, draggedSymbol);
      reorderSymbols(activeWatchlist.id, newSymbols);
    }

    setDraggedSymbol(null);
    setDraggedIndex(null);
  };

  const handleDragEnd = () => {
    setDraggedSymbol(null);
    setDraggedIndex(null);
  };

  return (
    <div className="flex flex-col h-full bg-[#0d0d11]">
      {/* Tab Bar */}
      <div className="bg-[#1e222d] border-b border-[#363c4e] flex items-center overflow-x-auto custom-scrollbar">
        <div className="flex items-center flex-1 min-w-0">
          {watchlists.map((watchlist) => (
            <button
              key={watchlist.id}
              onClick={() => setActiveWatchlist(watchlist.id)}
              className={`px-3 py-2 text-xs font-medium whitespace-nowrap transition-colors border-b-2 ${
                activeWatchlistId === watchlist.id
                  ? 'border-[#2962ff] text-[#d1d4dc] bg-[#0d0d11]'
                  : 'border-transparent text-gray-500 hover:text-[#d1d4dc] hover:bg-[#2a2e39]'
              }`}
            >
              {watchlist.name}
            </button>
          ))}
        </div>

        {/* Actions Dropdown */}
        <div className="relative flex-shrink-0">
          <button
            onClick={() => setDropdownOpen(!dropdownOpen)}
            className="p-2 text-gray-400 hover:text-[#d1d4dc] hover:bg-[#2a2e39] transition-colors"
            title="Watchlist actions"
          >
            <Icon name="chevron-down" size="md" />
          </button>

          {dropdownOpen && (
            <>
              {/* Backdrop */}
              <div
                className="fixed inset-0 z-10"
                onClick={() => setDropdownOpen(false)}
              />

              {/* Dropdown Menu */}
              <div className="absolute right-0 top-full mt-1 bg-[#1e222d] border border-[#363c4e] rounded shadow-lg z-20 min-w-[200px]">
                <button
                  onClick={() => {
                    setIsCreating(true);
                    setDropdownOpen(false);
                  }}
                  className="flex items-center gap-2 w-full px-3 py-2 text-xs text-[#d1d4dc] hover:bg-[#2a2e39] transition-colors"
                >
                  <Icon name="plus" size="sm" />
                  <span>New Watchlist</span>
                </button>

                {activeWatchlist && !activeWatchlist.isDefault && (
                  <>
                    <button
                      onClick={() => {
                        setRenameValue(activeWatchlist.name);
                        setIsRenaming(true);
                        setDropdownOpen(false);
                      }}
                      className="flex items-center gap-2 w-full px-3 py-2 text-xs text-[#d1d4dc] hover:bg-[#2a2e39] transition-colors"
                    >
                      <Icon name="edit" size="sm" />
                      <span>Rename</span>
                    </button>

                    <button
                      onClick={() => handleDeleteWatchlist(activeWatchlist.id)}
                      className="flex items-center gap-2 w-full px-3 py-2 text-xs text-[#ef5350] hover:bg-[#2a2e39] transition-colors"
                    >
                      <Icon name="trash" size="sm" />
                      <span>Delete</span>
                    </button>
                  </>
                )}

                <div className="h-px bg-[#363c4e] my-1"></div>

                <button
                  onClick={() => {
                    setIsSearchOpen(true);
                    setDropdownOpen(false);
                  }}
                  className="flex items-center gap-2 w-full px-3 py-2 text-xs text-[#d1d4dc] hover:bg-[#2a2e39] transition-colors"
                >
                  <Icon name="search" size="sm" />
                  <span>Add Symbol</span>
                </button>
              </div>
            </>
          )}
        </div>
      </div>

      {/* Create Watchlist Modal */}
      {isCreating && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
          <div className="bg-[#1e222d] border border-[#363c4e] rounded-lg shadow-2xl w-[400px] p-4">
            <h3 className="text-sm font-bold text-[#d1d4dc] mb-4">Create New Watchlist</h3>
            <input
              type="text"
              value={newWatchlistName}
              onChange={(e) => setNewWatchlistName(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleCreateWatchlist()}
              placeholder="Watchlist name..."
              autoFocus
              className="w-full px-3 py-2 bg-[#0d0d11] border border-[#363c4e] rounded text-[#d1d4dc] text-sm focus:outline-none focus:border-[#2962ff]"
            />
            <div className="flex gap-2 mt-4">
              <button
                onClick={handleCreateWatchlist}
                className="flex-1 px-4 py-2 bg-[#2962ff] hover:bg-[#1e53e5] text-white text-sm rounded transition-colors"
              >
                Create
              </button>
              <button
                onClick={() => {
                  setIsCreating(false);
                  setNewWatchlistName('');
                }}
                className="flex-1 px-4 py-2 bg-[#363c4e] hover:bg-[#434651] text-[#d1d4dc] text-sm rounded transition-colors"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Rename Watchlist Modal */}
      {isRenaming && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
          <div className="bg-[#1e222d] border border-[#363c4e] rounded-lg shadow-2xl w-[400px] p-4">
            <h3 className="text-sm font-bold text-[#d1d4dc] mb-4">Rename Watchlist</h3>
            <input
              type="text"
              value={renameValue}
              onChange={(e) => setRenameValue(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleRenameWatchlist()}
              placeholder="New name..."
              autoFocus
              className="w-full px-3 py-2 bg-[#0d0d11] border border-[#363c4e] rounded text-[#d1d4dc] text-sm focus:outline-none focus:border-[#2962ff]"
            />
            <div className="flex gap-2 mt-4">
              <button
                onClick={handleRenameWatchlist}
                className="flex-1 px-4 py-2 bg-[#2962ff] hover:bg-[#1e53e5] text-white text-sm rounded transition-colors"
              >
                Rename
              </button>
              <button
                onClick={() => {
                  setIsRenaming(false);
                  setRenameValue('');
                }}
                className="flex-1 px-4 py-2 bg-[#363c4e] hover:bg-[#434651] text-[#d1d4dc] text-sm rounded transition-colors"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add Symbol Search Modal */}
      {isSearchOpen && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
          <div className="bg-[#1e222d] border border-[#363c4e] rounded-lg shadow-2xl w-[400px] max-h-[600px] flex flex-col">
            {/* Header */}
            <div className="flex items-center justify-between p-4 border-b border-[#363c4e]">
              <h3 className="text-sm font-bold text-[#d1d4dc]">Add Symbol</h3>
              <button
                onClick={() => {
                  setIsSearchOpen(false);
                  setSearchQuery('');
                }}
                className="p-1 text-gray-400 hover:text-[#d1d4dc] transition-colors"
              >
                <Icon name="x-close" size="md" />
              </button>
            </div>

            {/* Search Input */}
            <div className="p-4 border-b border-[#363c4e]">
              <div className="relative">
                <Icon name="search" size="md" className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search symbols..."
                  autoFocus
                  className="w-full pl-9 pr-3 py-2 bg-[#0d0d11] border border-[#363c4e] rounded text-[#d1d4dc] text-sm focus:outline-none focus:border-[#2962ff]"
                />
              </div>
            </div>

            {/* Symbol List */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
              {isLoadingSymbols ? (
                <div className="flex items-center justify-center h-32 text-gray-500 text-xs">
                  Loading symbols...
                </div>
              ) : filteredSymbols.length === 0 ? (
                <div className="flex items-center justify-center h-32 text-gray-500 text-xs">
                  {searchQuery ? 'No symbols found' : 'Start typing to search'}
                </div>
              ) : (
                <div className="space-y-1">
                  {filteredSymbols.map((symbol) => (
                    <button
                      key={symbol}
                      onClick={() => handleAddSymbol(symbol)}
                      className="w-full flex items-center justify-between px-3 py-2 text-sm text-[#d1d4dc] hover:bg-[#2a2e39] rounded transition-colors"
                    >
                      <span className="font-medium">{symbol}</span>
                      <Icon name="plus" size="sm" className="text-[#2962ff]" />
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* MarketWatch with active watchlist */}
      {activeWatchlist && (
        <MarketWatch
          watchlist={activeWatchlist.symbols}
          onSelectSymbol={onSelectSymbol}
          selectedSymbol={selectedSymbol}
          onOpenOrderEntry={onOpenOrderEntry}
        />
      )}
    </div>
  );
};

/**
 * WelcomeTerminal ΓÇö MT5-style startup terminal with embedded login dialog.
 *
 * Shown instead of the old full-screen Login page.
 * Renders the trading interface behind (dimmed) and shows:
 *   1. A terminal console with scrolling startup log messages.
 *   2. A floating "Login to Trade Account" dialog over it.
 *
 * Once the user authenticates, the onLogin callback fires and this component
 * unmounts ΓÇö the main platform takes over seamlessly.
 */

import React, { useState, useEffect, useRef } from 'react';
import { useAppStore } from '../store/useAppStore';
import { api } from '../services/api';

interface WelcomeTerminalProps {
    onLogin: (accountId: string) => void;
}

interface LogLine {
    time: string;
    text: string;
    type: 'info' | 'ok' | 'warn' | 'err';
}

const now = () =>
    new Date().toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false,
    });

const STARTUP_SEQUENCE: { delay: number; text: string; type: LogLine['type'] }[] = [
    { delay: 0, text: 'RTX Terminal  ΓÇö  Institutional Trading Environment', type: 'info' },
    { delay: 120, text: 'Build 1.0.0  (c) 2025 RTX Systems', type: 'info' },
    { delay: 280, text: '----------------------------------------------------', type: 'info' },
    { delay: 450, text: 'Initializing market data subsystem...', type: 'info' },
    { delay: 700, text: 'Loading symbol catalog...', type: 'info' },
    { delay: 950, text: 'Connecting to rtxbackend.tradecopier.org:443', type: 'info' },
    { delay: 1300, text: 'FIX gateway handshake OK', type: 'ok' },
    { delay: 1550, text: 'WebSocket market feed: READY', type: 'ok' },
    { delay: 1800, text: 'Price aggregation engine: ONLINE', type: 'ok' },
    { delay: 2050, text: '----------------------------------------------------', type: 'info' },
    { delay: 2200, text: 'Please login to your trade account to continue.', type: 'warn' },
];

export function WelcomeTerminal({ onLogin }: WelcomeTerminalProps) {
    // ΓöÇΓöÇ Terminal log state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const [lines, setLines] = useState<LogLine[]>([]);
    const logEndRef = useRef<HTMLDivElement>(null);

    // ΓöÇΓöÇ Login form state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [rememberMe, setRememberMe] = useState(false);

    const addSavedAccount = useAppStore(s => s.addSavedAccount);
    const setActiveAccount = useAppStore(s => s.setActiveAccount);

    // Pre-fill remembered credentials
    useEffect(() => {
        const savedUser = localStorage.getItem('rtx_saved_username');
        const savedPass = localStorage.getItem('rtx_saved_password');
        if (savedUser && savedPass) {
            setUsername(savedUser);
            try { setPassword(atob(savedPass)); } catch { /* ignore */ }
            setRememberMe(true);
        }
    }, []);

    // Run startup log sequence
    useEffect(() => {
        const timers: ReturnType<typeof setTimeout>[] = [];
        STARTUP_SEQUENCE.forEach(({ delay, text, type }) => {
            timers.push(
                setTimeout(() => {
                    setLines(prev => [...prev, { time: now(), text, type }]);
                }, delay)
            );
        });
        return () => timers.forEach(clearTimeout);
    }, []);

    // Auto-scroll log
    useEffect(() => {
        logEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [lines]);

    // ΓöÇΓöÇ Login handler ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError(null);

        const BACKEND_URL = 'https://rtxbackend.tradecopier.org';

        try {
            const data = await api.auth.login(username, password, BACKEND_URL);
            const token = data.access_token;
            if (!token) throw new Error('No authentication token received');

            const accountId = data.user?.id || username;

            // Persist credentials & tokens
            localStorage.setItem('rtx_last_login', String(accountId));
            localStorage.setItem('rtx_saved_username', username);
            try { localStorage.setItem('rtx_saved_password', btoa(password)); } catch { /* ignore */ }

            const { setBaseUrl, setToken, setRefreshToken } = await import('../api/client');
            setBaseUrl(BACKEND_URL);
            setToken(token);
            if (data.refresh_token) setRefreshToken(data.refresh_token);
            if (data.expires_at) localStorage.setItem('token_expires_at', data.expires_at);

            // Update Zustand store
            useAppStore.getState().setAuthenticated(true, String(accountId), token, data.refresh_token);

            // Save to multi-account list
            const loginNum = parseInt(username, 10);
            if (!isNaN(loginNum)) {
                addSavedAccount({
                    login: loginNum,
                    name: data.user?.username || '',
                    server: 'FlexyMarkets-Server',
                    isLive: true,
                    lastUsed: Date.now(),
                    password: btoa(password),
                });
                setActiveAccount(loginNum);
            }

            // Append success line to terminal
            setLines(prev => [
                ...prev,
                { time: now(), text: `Connected ΓÇö Account ${accountId}  [ ${data.user?.username || username} ]`, type: 'ok' },
                { time: now(), text: 'Loading workspace...', type: 'info' },
            ]);

            // Short pause for user to see the "Connected" message, then hand off
            setTimeout(() => onLogin(String(accountId)), 600);
        } catch (err: any) {
            console.error('[WelcomeTerminal] Login error:', err);
            setError(err.message || 'Authentication failed');
            setLines(prev => [
                ...prev,
                { time: now(), text: `Login failed: ${err.message || 'Authentication error'}`, type: 'err' },
            ]);
        } finally {
            setLoading(false);
        }
    };

    // ΓöÇΓöÇ Colour helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const lineColor = (type: LogLine['type']) => {
        switch (type) {
            case 'ok': return '#22c55e';   // green-500
            case 'warn': return '#eab308';   // yellow-500
            case 'err': return '#ef4444';   // red-500
            default: return '#71717a';   // zinc-500
        }
    };

    // ΓöÇΓöÇ Render ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    return (
        /* Full-screen dark overlay */
        <div
            onContextMenu={e => e.stopPropagation()}
            onMouseDownCapture={e => {
                // Prevent any mousedown from leaking through to panels below
                // (which would trigger their right-click context menus via portals)
                const target = e.target as HTMLElement;
                if (!target.closest('[data-welcome-card]')) {
                    e.stopPropagation();
                }
            }}
            style={{
                position: 'fixed',
                inset: 0,
                background: 'rgba(9,9,11,0.92)',
                backdropFilter: 'blur(6px)',
                WebkitBackdropFilter: 'blur(6px)',
                zIndex: 99999,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontFamily: "'Consolas','Fira Mono','Menlo',monospace",
            }}
        >
            {/*
              ΓöîΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÉ
              Γöé  Two-column card: terminal log (left) + login form (right)  Γöé
              ΓööΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÿ
            */}
            <div
                data-welcome-card
                style={{
                    display: 'flex',
                    gap: 0,
                    width: 'min(960px, 96vw)',
                    height: 'min(540px, 92vh)',
                    borderRadius: 8,
                    overflow: 'hidden',
                    boxShadow: '0 32px 64px rgba(0,0,0,0.7)',
                    border: '1px solid #222226',
                }}
            >
                {/* ΓöÇΓöÇ LEFT: Terminal Console ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
                <div
                    style={{
                        flex: 1,
                        background: '#0c0c10',
                        display: 'flex',
                        flexDirection: 'column',
                        overflow: 'hidden',
                    }}
                >
                    {/* Title bar */}
                    <div
                        style={{
                            padding: '8px 14px',
                            background: '#111114',
                            borderBottom: '1px solid #222226',
                            display: 'flex',
                            alignItems: 'center',
                            gap: 8,
                        }}
                    >
                        <span
                            style={{
                                display: 'inline-block',
                                width: 10,
                                height: 10,
                                borderRadius: '50%',
                                background: '#22c55e',
                                boxShadow: '0 0 6px #22c55e',
                            }}
                        />
                        <span style={{ color: '#52525b', fontSize: 11, letterSpacing: '0.1em' }}>
                            RTX JOURNAL
                        </span>
                    </div>

                    {/* Log lines */}
                    <div
                        style={{
                            flex: 1,
                            overflowY: 'auto',
                            padding: '10px 14px',
                            fontSize: 11.5,
                            lineHeight: 1.7,
                        }}
                    >
                        {lines.map((line, i) => (
                            <div key={i} style={{ display: 'flex', gap: 10 }}>
                                <span style={{ color: '#3f3f46', minWidth: 60, flexShrink: 0 }}>
                                    {line.time}
                                </span>
                                <span style={{ color: lineColor(line.type) }}>{line.text}</span>
                            </div>
                        ))}
                        <div ref={logEndRef} />
                    </div>
                </div>

                {/* ΓöÇΓöÇ RIGHT: Login Dialog ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
                <div
                    style={{
                        width: 320,
                        flexShrink: 0,
                        background: '#131316',
                        borderLeft: '1px solid #222226',
                        display: 'flex',
                        flexDirection: 'column',
                        padding: '32px 28px',
                        gap: 0,
                    }}
                >
                    {/* Logo & title */}
                    <div style={{ textAlign: 'center', marginBottom: 28 }}>
                        {/* RTX Logo ΓÇö dark background version */}
                        <img
                            src="/logo.png"
                            alt="RTX"
                            style={{
                                width: 64,
                                height: 64,
                                borderRadius: 12,
                                margin: '0 auto 14px',
                                display: 'block',
                                objectFit: 'contain',
                                boxShadow: '0 0 20px rgba(109,192,74,0.20)',
                            }}
                        />
                        <p style={{ color: '#f4f4f5', fontSize: 16, fontWeight: 700, margin: 0, letterSpacing: '0.03em', fontFamily: 'system-ui, sans-serif' }}>
                            RTX Terminal
                        </p>
                        <p style={{ color: '#52525b', fontSize: 11, margin: '4px 0 0', fontFamily: 'system-ui, sans-serif' }}>
                            Login to Trade Account
                        </p>
                    </div>

                    {/* Error */}
                    {error && (
                        <div
                            style={{
                                marginBottom: 14,
                                padding: '8px 12px',
                                borderRadius: 6,
                                background: 'rgba(239,68,68,0.1)',
                                border: '1px solid rgba(239,68,68,0.25)',
                                color: '#f87171',
                                fontSize: 12,
                                fontFamily: 'system-ui, sans-serif',
                            }}
                        >
                            {error}
                        </div>
                    )}

                    {/* Form */}
                    <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 12, flex: 1 }}>
                        <div>
                            <label style={labelStyle}>Account ID</label>
                            <input
                                type="text"
                                placeholder="Enter Account ID"
                                required
                                autoFocus
                                value={username}
                                onChange={e => setUsername(e.target.value)}
                                style={inputStyle}
                                onFocus={e => (e.target.style.borderColor = '#10b981')}
                                onBlur={e => (e.target.style.borderColor = '#3f3f46')}
                            />
                        </div>

                        <div>
                            <label style={labelStyle}>Password</label>
                            <input
                                type="password"
                                placeholder="Enter Password"
                                required
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                                style={inputStyle}
                                onFocus={e => (e.target.style.borderColor = '#10b981')}
                                onBlur={e => (e.target.style.borderColor = '#3f3f46')}
                            />
                        </div>

                        <div style={{ display: 'flex', alignItems: 'center', gap: 8, margin: '2px 0' }}>
                            <input
                                type="checkbox"
                                id="wtRemember"
                                checked={rememberMe}
                                onChange={e => setRememberMe(e.target.checked)}
                                style={{ accentColor: '#10b981', width: 14, height: 14, cursor: 'pointer' }}
                            />
                            <label
                                htmlFor="wtRemember"
                                style={{ color: '#71717a', fontSize: 12, cursor: 'pointer', fontFamily: 'system-ui, sans-serif' }}
                            >
                                Remember credentials
                            </label>
                        </div>

                        <button
                            type="submit"
                            disabled={loading}
                            style={{
                                marginTop: 8,
                                padding: '11px 0',
                                borderRadius: 7,
                                border: 'none',
                                background: loading
                                    ? '#064e3b'
                                    : 'linear-gradient(135deg,#059669,#10b981)',
                                color: '#fff',
                                fontWeight: 700,
                                fontSize: 13,
                                cursor: loading ? 'not-allowed' : 'pointer',
                                letterSpacing: '0.03em',
                                transition: 'opacity 0.2s',
                                opacity: loading ? 0.7 : 1,
                                fontFamily: 'system-ui, sans-serif',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                gap: 8,
                            }}
                        >
                            {loading ? (
                                <>
                                    <span
                                        style={{
                                            display: 'inline-block',
                                            width: 14,
                                            height: 14,
                                            border: '2px solid rgba(255,255,255,0.3)',
                                            borderTopColor: '#fff',
                                            borderRadius: '50%',
                                            animation: 'rtx-spin 0.7s linear infinite',
                                        }}
                                    />
                                    Connecting...
                                </>
                            ) : (
                                <>
                                    Login
                                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                        <line x1="5" y1="12" x2="19" y2="12" />
                                        <polyline points="12 5 19 12 12 19" />
                                    </svg>
                                </>
                            )}
                        </button>
                    </form>

                    {/* Footer */}
                    <div
                        style={{
                            marginTop: 'auto',
                            paddingTop: 20,
                            borderTop: '1px solid #222226',
                            display: 'flex',
                            alignItems: 'center',
                            gap: 6,
                        }}
                    >
                        <span
                            style={{
                                display: 'inline-block',
                                width: 7,
                                height: 7,
                                borderRadius: '50%',
                                background: '#22c55e',
                                boxShadow: '0 0 4px #22c55e',
                            }}
                        />
                        <span style={{ color: '#52525b', fontSize: 11, fontFamily: 'system-ui,sans-serif' }}>
                            System Operational
                        </span>
                    </div>
                </div>
            </div>

            {/* Spinner keyframe injected once */}
            <style>{`
                @keyframes rtx-spin {
                    to { transform: rotate(360deg); }
                }
            `}</style>
        </div>
    );
}

// ΓöÇΓöÇ Shared input styles ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const labelStyle: React.CSSProperties = {
    display: 'block',
    color: '#52525b',
    fontSize: 10,
    fontWeight: 700,
    textTransform: 'uppercase',
    letterSpacing: '0.15em',
    marginBottom: 6,
    fontFamily: 'system-ui, sans-serif',
};

const inputStyle: React.CSSProperties = {
    width: '100%',
    boxSizing: 'border-box',
    padding: '9px 12px',
    borderRadius: 6,
    border: '1px solid #3f3f46',
    background: '#0d0d11',
    color: '#f4f4f5',
    fontSize: 13,
    outline: 'none',
    transition: 'border-color 0.15s',
    fontFamily: 'system-ui, sans-serif',
};

/**
 * Workspace Manager Component
 * UI for saving, loading, and managing workspaces
 */

import React, { useState, useEffect } from 'react';
import { useWorkspace } from '../hooks/useWorkspace';
import type { WorkspaceMetadata } from '../types/workspace';

interface WorkspaceManagerProps {
  onClose?: () => void;
}

export const WorkspaceManager: React.FC<WorkspaceManagerProps> = ({ onClose }) => {
  const {
    currentWorkspace,
    workspaceList,
    autoSaveState,
    isSaving,
    isLoading,
    isLoadingList,
    error,
    saveWorkspace,
    loadWorkspace,
    deleteWorkspace,
    createNewWorkspace,
    duplicateWorkspace,
    setDefaultWorkspace,
    clearError,
  } = useWorkspace();

  const [showNewDialog, setShowNewDialog] = useState(false);
  const [showRenameDialog, setShowRenameDialog] = useState(false);
  const [newWorkspaceName, setNewWorkspaceName] = useState('');
  const [newWorkspaceDescription, setNewWorkspaceDescription] = useState('');
  const [selectedWorkspace, setSelectedWorkspace] = useState<WorkspaceMetadata | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Filter workspaces based on search
  const filteredWorkspaces = workspaceList.filter(ws =>
    ws.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    ws.description?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Handle save current workspace
  const handleSaveCurrent = async () => {
    try {
      if (currentWorkspace) {
        await saveWorkspace();
        alert('Workspace saved successfully');
      }
    } catch (err: any) {
      alert(`Failed to save workspace: ${err.message}`);
    }
  };

  // Handle create new workspace
  const handleCreateNew = async () => {
    if (!newWorkspaceName.trim()) {
      alert('Workspace name is required');
      return;
    }

    try {
      await createNewWorkspace(newWorkspaceName, newWorkspaceDescription);
      setShowNewDialog(false);
      setNewWorkspaceName('');
      setNewWorkspaceDescription('');
      alert('Workspace created successfully');
    } catch (err: any) {
      alert(`Failed to create workspace: ${err.message}`);
    }
  };

  // Handle load workspace
  const handleLoad = async (workspaceId: string) => {
    try {
      await loadWorkspace(workspaceId);
      alert('Workspace loaded successfully');
      onClose?.();
    } catch (err: any) {
      alert(`Failed to load workspace: ${err.message}`);
    }
  };

  // Handle delete workspace
  const handleDelete = async (workspaceId: string, workspaceName: string) => {
    if (!confirm(`Are you sure you want to delete workspace "${workspaceName}"?`)) {
      return;
    }

    try {
      await deleteWorkspace(workspaceId);
      alert('Workspace deleted successfully');
    } catch (err: any) {
      alert(`Failed to delete workspace: ${err.message}`);
    }
  };

  // Handle duplicate workspace
  const handleDuplicate = async (workspaceId: string, originalName: string) => {
    const newName = prompt(`Enter name for duplicated workspace:`, `${originalName} (Copy)`);
    if (!newName) return;

    try {
      await duplicateWorkspace(workspaceId, newName);
      alert('Workspace duplicated successfully');
    } catch (err: any) {
      alert(`Failed to duplicate workspace: ${err.message}`);
    }
  };

  // Handle set default
  const handleSetDefault = async (workspaceId: string) => {
    try {
      await setDefaultWorkspace(workspaceId);
      alert('Default workspace updated');
    } catch (err: any) {
      alert(`Failed to set default workspace: ${err.message}`);
    }
  };

  // Format date
  const formatDate = (date: Date) => {
    return new Date(date).toLocaleString();
  };

  return (
    <div className="workspace-manager">
      <div className="workspace-manager-header">
        <h2>Workspace Manager</h2>
        {onClose && (
          <button className="close-button" onClick={onClose}>├ù</button>
        )}
      </div>

      {/* Auto-save indicator */}
      {autoSaveState.hasUnsavedChanges && (
        <div className="auto-save-indicator warning">
          Unsaved changes
          {autoSaveState.saving && ' - Saving...'}
        </div>
      )}

      {autoSaveState.lastSaved && !autoSaveState.hasUnsavedChanges && (
        <div className="auto-save-indicator success">
          Last saved: {formatDate(autoSaveState.lastSaved)}
        </div>
      )}

      {error && (
        <div className="error-banner">
          <span>{error.message}</span>
          <button onClick={clearError}>├ù</button>
        </div>
      )}

      {/* Current workspace section */}
      <div className="current-workspace-section">
        <h3>Current Workspace</h3>
        {currentWorkspace ? (
          <div className="current-workspace-info">
            <div>
              <strong>{currentWorkspace.name}</strong>
              {currentWorkspace.description && (
                <p className="description">{currentWorkspace.description}</p>
              )}
              <p className="meta">
                {currentWorkspace.charts.length} charts |
                Updated: {formatDate(currentWorkspace.updatedAt)}
              </p>
            </div>
            <button
              className="btn-primary"
              onClick={handleSaveCurrent}
              disabled={isSaving}
            >
              {isSaving ? 'Saving...' : 'Save'}
            </button>
          </div>
        ) : (
          <p className="no-workspace">No workspace loaded</p>
        )}
      </div>

      {/* Actions */}
      <div className="workspace-actions">
        <button
          className="btn-primary"
          onClick={() => setShowNewDialog(true)}
        >
          + New Workspace
        </button>
        <input
          type="text"
          className="search-input"
          placeholder="Search workspaces..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
      </div>

      {/* Workspace list */}
      <div className="workspace-list">
        <h3>Saved Workspaces ({filteredWorkspaces.length})</h3>

        {isLoadingList ? (
          <div className="loading">Loading workspaces...</div>
        ) : filteredWorkspaces.length === 0 ? (
          <p className="no-workspaces">
            {searchQuery ? 'No workspaces found' : 'No saved workspaces'}
          </p>
        ) : (
          <div className="workspace-items">
            {filteredWorkspaces.map((ws) => (
              <div
                key={ws.id}
                className={`workspace-item ${ws.isDefault ? 'default' : ''}`}
              >
                <div className="workspace-item-content">
                  <div className="workspace-item-header">
                    <strong>{ws.name}</strong>
                    {ws.isDefault && <span className="badge-default">Default</span>}
                  </div>
                  {ws.description && (
                    <p className="description">{ws.description}</p>
                  )}
                  <div className="workspace-item-meta">
                    <span>{ws.chartCount} charts</span>
                    <span>ΓÇó</span>
                    <span>{formatDate(ws.updatedAt)}</span>
                  </div>
                  {ws.tags && ws.tags.length > 0 && (
                    <div className="workspace-tags">
                      {ws.tags.map((tag, i) => (
                        <span key={i} className="tag">{tag}</span>
                      ))}
                    </div>
                  )}
                </div>

                <div className="workspace-item-actions">
                  <button
                    className="btn-small"
                    onClick={() => handleLoad(ws.id)}
                    disabled={isLoading}
                  >
                    Load
                  </button>
                  <button
                    className="btn-small"
                    onClick={() => handleDuplicate(ws.id, ws.name)}
                  >
                    Duplicate
                  </button>
                  {!ws.isDefault && (
                    <button
                      className="btn-small"
                      onClick={() => handleSetDefault(ws.id)}
                    >
                      Set Default
                    </button>
                  )}
                  <button
                    className="btn-small btn-danger"
                    onClick={() => handleDelete(ws.id, ws.name)}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* New workspace dialog */}
      {showNewDialog && (
        <div className="modal-overlay" onClick={() => setShowNewDialog(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h3>Create New Workspace</h3>
            <div className="form-group">
              <label>Name *</label>
              <input
                type="text"
                value={newWorkspaceName}
                onChange={(e) => setNewWorkspaceName(e.target.value)}
                placeholder="Enter workspace name"
                autoFocus
              />
            </div>
            <div className="form-group">
              <label>Description</label>
              <textarea
                value={newWorkspaceDescription}
                onChange={(e) => setNewWorkspaceDescription(e.target.value)}
                placeholder="Enter description (optional)"
                rows={3}
              />
            </div>
            <div className="modal-actions">
              <button
                className="btn-secondary"
                onClick={() => {
                  setShowNewDialog(false);
                  setNewWorkspaceName('');
                  setNewWorkspaceDescription('');
                }}
              >
                Cancel
              </button>
              <button
                className="btn-primary"
                onClick={handleCreateNew}
                disabled={isSaving || !newWorkspaceName.trim()}
              >
                {isSaving ? 'Creating...' : 'Create'}
              </button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .workspace-manager {
          display: flex;
          flex-direction: column;
          height: 100%;
          background: #1a1a1a;
          color: #e0e0e0;
          padding: 20px;
          overflow: hidden;
        }

        .workspace-manager-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 20px;
        }

        .workspace-manager-header h2 {
          margin: 0;
          font-size: 24px;
        }

        .close-button {
          background: none;
          border: none;
          color: #e0e0e0;
          font-size: 32px;
          cursor: pointer;
          padding: 0;
          width: 32px;
          height: 32px;
          line-height: 32px;
        }

        .close-button:hover {
          color: #fff;
        }

        .auto-save-indicator {
          padding: 8px 12px;
          border-radius: 4px;
          margin-bottom: 16px;
          font-size: 13px;
        }

        .auto-save-indicator.warning {
          background: rgba(255, 193, 7, 0.2);
          color: #ffc107;
          border: 1px solid rgba(255, 193, 7, 0.3);
        }

        .auto-save-indicator.success {
          background: rgba(76, 175, 80, 0.2);
          color: #4caf50;
          border: 1px solid rgba(76, 175, 80, 0.3);
        }

        .error-banner {
          background: rgba(244, 67, 54, 0.2);
          color: #f44336;
          border: 1px solid rgba(244, 67, 54, 0.3);
          padding: 12px;
          border-radius: 4px;
          margin-bottom: 16px;
          display: flex;
          justify-content: space-between;
          align-items: center;
        }

        .error-banner button {
          background: none;
          border: none;
          color: #f44336;
          cursor: pointer;
          font-size: 20px;
          padding: 0 8px;
        }

        .current-workspace-section {
          background: #252525;
          padding: 16px;
          border-radius: 8px;
          margin-bottom: 20px;
        }

        .current-workspace-section h3 {
          margin: 0 0 12px 0;
          font-size: 16px;
        }

        .current-workspace-info {
          display: flex;
          justify-content: space-between;
          align-items: flex-start;
          gap: 16px;
        }

        .current-workspace-info strong {
          font-size: 18px;
          display: block;
          margin-bottom: 4px;
        }

        .description {
          color: #999;
          margin: 4px 0;
          font-size: 13px;
        }

        .meta {
          color: #666;
          font-size: 12px;
          margin: 4px 0 0 0;
        }

        .no-workspace {
          color: #666;
          font-style: italic;
        }

        .workspace-actions {
          display: flex;
          gap: 12px;
          margin-bottom: 20px;
        }

        .search-input {
          flex: 1;
          background: #252525;
          border: 1px solid #404040;
          color: #e0e0e0;
          padding: 8px 12px;
          border-radius: 4px;
          font-size: 14px;
        }

