/**
 * DockContainer Component
 * MT5-style docking with compass rose indicator and blue preview
 */

import { Icon } from '../ui/Icon';
import React, { useRef, useEffect, useState, useCallback } from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';
import { useDockLayoutStore } from '../../store/useDockLayoutStore';
import { DockContainer as DockContainerType, DockPanelConfig } from '../../services/dockManager';
import { DockPanel } from './DockPanel';
import { DockResizeHandle } from './DockResizeHandle';
import { X } from 'lucide-react';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export interface DockContainerProps {
  container?: DockContainerType;
  isRoot?: boolean;
  className?: string;
  style?: React.CSSProperties;
  renderPanel?: (panel: DockPanelConfig, isActive: boolean) => React.ReactNode;
}

// ΓöÇΓöÇΓöÇ Shared Dock State (synchronous, no React state batching issues) ΓöÇΓöÇ
// Using a plain object that is mutated synchronously avoids the race condition
// where React setState batching causes the global mouseup to read stale values.
const dockIntent = {
  targetPanelId: null as string | null,
  direction: null as string | null,
};

// ΓöÇΓöÇΓöÇ Compass Rose Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const CompassRose: React.FC<{
  targetPanelId: string;
  hoveredDir: string | null;
  onHoverChange: (dir: string | null) => void;
}> = ({ targetPanelId, hoveredDir, onHoverChange }) => {
  const dirs = [
    { key: 'top', icon: 'Γû▓', pos: 'top-0 left-1/2 -translate-x-1/2' },
    { key: 'bottom', icon: 'Γû╝', pos: 'bottom-0 left-1/2 -translate-x-1/2' },
    { key: 'left', icon: 'Γùä', pos: 'left-0 top-1/2 -translate-y-1/2' },
    { key: 'right', icon: 'Γû║', pos: 'right-0 top-1/2 -translate-y-1/2' },
    { key: 'center', icon: 'Γûá', pos: 'top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2' },
  ];

  return (
    <div className="relative w-[100px] h-[100px] pointer-events-auto z-[200]">
      {dirs.map(({ key, icon, pos }) => (
        <div
          key={key}
          className={cn(
            'absolute w-[30px] h-[30px] flex items-center justify-center',
            'border border-zinc-400 rounded-[3px] text-[13px] leading-none',
            'transition-all duration-75 cursor-pointer pointer-events-auto select-none',
            hoveredDir === key
              ? 'bg-zinc-8000 text-white border-blue-400 shadow-lg scale-110'
              : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-500 hover:text-white hover:border-blue-300 shadow-md',
            pos
          )}
          onMouseEnter={() => {
            // Set synchronously so global mouseup can read it
            dockIntent.targetPanelId = targetPanelId;
            dockIntent.direction = key;
            onHoverChange(key);
          }}
          onMouseLeave={() => {
            dockIntent.targetPanelId = null;
            dockIntent.direction = null;
            onHoverChange(null);
          }}
        >
          {icon}
        </div>
      ))}
    </div>
  );
};

// ΓöÇΓöÇΓöÇ Blue Preview Overlay ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const DockPreview: React.FC<{ direction: string | null }> = ({ direction }) => {
  if (!direction) return null;

  const classes: Record<string, string> = {
    top: 'top-0 left-0 right-0 h-1/2',
    bottom: 'bottom-0 left-0 right-0 h-1/2',
    left: 'left-0 top-0 bottom-0 w-1/2',
    right: 'right-0 top-0 bottom-0 w-1/2',
    center: 'inset-0',
  };

  return (
    <div
      className={cn(
        'absolute pointer-events-none z-[150] transition-all duration-100',
        'bg-zinc-500/25 border-2 border-blue-400/50',
        classes[direction] || ''
      )}
    />
  );
};

// ΓöÇΓöÇΓöÇ Main DockContainer ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export const DockContainer: React.FC<DockContainerProps> = ({
  container,
  isRoot = false,
  className,
  style,
  renderPanel,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [dropTargetId, setDropTargetId] = useState<string | null>(null);
  const [compassDir, setCompassDir] = useState<string | null>(null);

  const {
    layout,
    dragState,
    dragInfo,
    startDrag,
    endDrag,
    cancelDrag,
    setActiveTab,
    removePanel,
    floatPanel,
    dockPanel,
    updateContainerSize,
    updateFloatingPosition,
  } = useDockLayoutStore();

  const currentContainer = container || layout.root;

  // Handle panel drag start
  const handlePanelDragStart = useCallback((panel: DockPanelConfig, isFloating: boolean) => (e: React.MouseEvent | React.TouchEvent) => {
    const target = e.target as HTMLElement;
    if (target.closest('button')) return;

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    startDrag(panel.id, panel.title, clientX, clientY, isFloating);
  }, [startDrag]);

  // Global drag handling ΓÇö only attach on root container
  useEffect(() => {
    if (!isRoot) return;
    if (dragState !== 'dragging') {
      setDropTargetId(null);
      setCompassDir(null);
      dockIntent.targetPanelId = null;
      dockIntent.direction = null;
      return;
    }

    const handleMouseMove = (e: MouseEvent) => {
      const { dragInfo, updateDrag } = useDockLayoutStore.getState();
      if (!dragInfo) return;

      updateDrag(e.clientX, e.clientY);

      // Find which panel we're hovering over
      const panels = document.querySelectorAll('[data-dock-panel]');
      let foundTarget: string | null = null;

      panels.forEach((panelEl) => {
        const rect = panelEl.getBoundingClientRect();
        if (
          e.clientX >= rect.left && e.clientX <= rect.right &&
          e.clientY >= rect.top && e.clientY <= rect.bottom
        ) {
          const panelId = panelEl.getAttribute('data-dock-panel');
          if (panelId && panelId !== dragInfo.panelId) {
            foundTarget = panelId;
          }
        }
      });

      setDropTargetId(foundTarget);

      // Clear compass intent if we moved off the target
      if (!foundTarget) {
        dockIntent.targetPanelId = null;
        dockIntent.direction = null;
        setCompassDir(null);
      }
    };

    const handleMouseUp = (e: MouseEvent) => {
      const { dragInfo } = useDockLayoutStore.getState();
      if (!dragInfo) return;

      // Check the synchronous dockIntent first
      if (dockIntent.targetPanelId && dockIntent.direction) {
        // Dock to the compass direction
        dockPanel(dragInfo.panelId, dockIntent.targetPanelId, dockIntent.direction as any);
      } else if (dragInfo.isFloating) {
        // Keep floating, update position
        let newX = e.clientX - 200;
        let newY = e.clientY - 50;
        newX = Math.max(20, Math.min(newX, window.innerWidth - 200));
        newY = Math.max(20, Math.min(newY, window.innerHeight - 200));
        updateFloatingPosition(dragInfo.panelId, { x: newX, y: newY });
      } else {
        // Float the panel
        let newX = e.clientX - 200;
        let newY = e.clientY - 50;
        newX = Math.max(20, Math.min(newX, window.innerWidth - 200));
        newY = Math.max(20, Math.min(newY, window.innerHeight - 200));
        floatPanel(dragInfo.panelId, { x: newX, y: newY });
      }

      // Reset state
      dockIntent.targetPanelId = null;
      dockIntent.direction = null;
      setDropTargetId(null);
      setCompassDir(null);
      endDrag();
    };

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        cancelDrag();
        dockIntent.targetPanelId = null;
        dockIntent.direction = null;
        setDropTargetId(null);
        setCompassDir(null);
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isRoot, dragState, endDrag, cancelDrag, floatPanel, dockPanel, updateFloatingPosition]);

  // Handle resize
  const handleResize = useCallback((childIndex: number, newRatio: number) => {
    if (!currentContainer.children[childIndex]) return;
    const child = currentContainer.children[childIndex] as any;
    if (child.id) {
      updateContainerSize(child.id, newRatio);
    }
  }, [currentContainer, updateContainerSize]);

  const isDragging = dragState === 'dragging';

  // ΓöÇΓöÇΓöÇ Render split container ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  if (currentContainer.type === 'split') {
    const isHorizontal = currentContainer.direction === 'horizontal';

    return (
      <div
        ref={containerRef}
        className={cn(
          'flex h-full overflow-hidden',
          isHorizontal ? 'flex-row' : 'flex-col',
          className
        )}
        style={style}
      >
        {currentContainer.children.map((child, index) => {
          const isContainer = 'children' in child;
          const childItem = child as DockContainerType;
          const ratio = childItem.ratio || (1 / currentContainer.children.length);

          return (
            <React.Fragment key={childItem.id || index}>
              <div
                className="flex flex-col overflow-hidden min-h-0 min-w-0"
                style={{
                  flex: ratio,
                  minWidth: isHorizontal ? 40 : undefined,
                  minHeight: !isHorizontal ? 24 : undefined,
                }}
              >
                {isContainer ? (
                  <DockContainer
                    container={childItem}
                    renderPanel={renderPanel}
                  />
                ) : (
                  <PanelSlot
                    panel={child as DockPanelConfig}
                    isDragging={isDragging}
                    dropTargetId={dropTargetId}
                    compassDir={compassDir}
                    onCompassDirChange={setCompassDir}
                    onDragStart={handlePanelDragStart(child as DockPanelConfig, false)}
                    onClose={() => removePanel((child as DockPanelConfig).id)}
                    onFloat={() => floatPanel((child as DockPanelConfig).id)}
                    renderPanel={renderPanel}
                  />
                )}
              </div>

              {index < currentContainer.children.length - 1 && (
                <DockResizeHandle
                  direction={isHorizontal ? 'vertical' : 'horizontal'}
                  onResize={(delta) => {
                    // For a horizontal split (flex-row), we are dragging a vertical handle left/right.
                    // The total size we care about is the container's width.
                    // For a vertical split (flex-col), we drag a horizontal handle up/down.
                    const totalSize = isHorizontal
                      ? containerRef.current?.offsetWidth || window.innerWidth
                      : containerRef.current?.offsetHeight || window.innerHeight;

                    const ratioDelta = delta / totalSize;
                    const currentRatio = childItem.ratio || (1 / currentContainer.children.length);
                    const nextChild = currentContainer.children[index + 1] as DockContainerType;
                    const nextRatio = nextChild?.ratio || (1 / currentContainer.children.length);

                    const newCur = Math.max(0.05, Math.min(0.95, currentRatio + ratioDelta));
                    const newNext = Math.max(0.05, Math.min(0.95, nextRatio - ratioDelta));
                    const combined = currentRatio + nextRatio;

                    handleResize(index, combined * (newCur / (newCur + newNext)));
                    handleResize(index + 1, combined * (newNext / (newCur + newNext)));
                  }}
                />
              )}
            </React.Fragment>
          );
        })}
      </div>
    );
  }

  // ΓöÇΓöÇΓöÇ Render tabs container ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  if (currentContainer.type === 'tabs') {
    const activeTabId = currentContainer.activeTab || (currentContainer.children[0] as DockPanelConfig)?.id;

    return (
      <div
        ref={containerRef}
        className={cn('flex flex-col h-full bg-[#131316] border border-zinc-700/30 overflow-hidden', className)}
        style={style}
      >
        {/* Tab Bar */}
        <div className="flex-none flex items-center gap-0 bg-[#2a2a2a] border-b border-zinc-700/40 overflow-x-auto h-[24px]">
          {currentContainer.children.map((child) => {
            const panel = child as DockPanelConfig;
            const isActive = panel.id === activeTabId;

            return (
              <div
                key={panel.id}
                className={cn(
                  'group flex items-center gap-1 px-2 h-full text-[11px] cursor-pointer select-none border-r border-zinc-700/30',
                  isActive
                    ? 'bg-[#131316] text-zinc-200'
                    : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-700/30'
                )}
                onClick={() => {
                  setActiveTab(currentContainer.id, panel.id);
                  if (panel.component === 'Chart' && panel.props?.symbol) {
                    window.dispatchEvent(new CustomEvent('chartSymbolChanged', {
                      detail: { symbol: panel.props.symbol }
                    }));
                  }
                }}
                onMouseDown={(e) => {
                  if (e.button === 0 && panel.floatable !== false) {
                    handlePanelDragStart(panel, false)(e);
                  }
                }}
              >
                <span className="truncate max-w-[120px]">{panel.title}</span>
                {panel.closable !== false && (
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      removePanel(panel.id);
                    }}
                    className="opacity-0 group-hover:opacity-100 w-4 h-4 flex items-center justify-center rounded-sm hover:bg-red-500/60 text-zinc-400 hover:text-white"
                  >
                    <X className="w-2.5 h-2.5" />
                  </button>
                )}
              </div>
            );
          })}
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-hidden relative">
          {currentContainer.children.map((child) => {
            const panel = child as DockPanelConfig;
            const isActive = panel.id === activeTabId;

            return (
              <div
                key={panel.id}
                className="absolute inset-0"
                style={{
                  opacity: isActive ? 1 : 0,
                  pointerEvents: isActive ? 'auto' : 'none',
                  zIndex: isActive ? 1 : 0,
                }}
              >
                <PanelSlot
                  panel={panel}
                  isActive={isActive}
                  showHeader={false}
                  isDragging={isDragging}
                  dropTargetId={dropTargetId}
                  compassDir={compassDir}
                  onCompassDirChange={setCompassDir}
                  onDragStart={handlePanelDragStart(panel, false)}
                  onClose={() => removePanel(panel.id)}
                  onFloat={() => floatPanel(panel.id)}
                  renderPanel={renderPanel}
                />
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  // ΓöÇΓöÇΓöÇ Render root or single panel ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  return (
    <div
      ref={containerRef}
      className={cn('flex flex-col h-full', className)}
      style={style}
    >
      {currentContainer.children.length === 0 ? (
        <div className="flex items-center justify-center h-full text-zinc-500">
          <p className="text-sm">Empty ΓÇö drag panels here</p>
        </div>
      ) : currentContainer.children.length === 1 && !('children' in currentContainer.children[0]) ? (
        <PanelSlot
          panel={currentContainer.children[0] as DockPanelConfig}
          isDragging={isDragging}
          dropTargetId={dropTargetId}
          compassDir={compassDir}
          onCompassDirChange={setCompassDir}
          onDragStart={handlePanelDragStart(currentContainer.children[0] as DockPanelConfig, false)}
          onClose={() => removePanel((currentContainer.children[0] as DockPanelConfig).id)}
          onFloat={() => floatPanel((currentContainer.children[0] as DockPanelConfig).id)}
          renderPanel={renderPanel}
        />
      ) : (
        currentContainer.children.map((child, index) => {
          const isContainer = 'children' in child;
          if (isContainer) {
            return (
              <DockContainer
                key={(child as DockContainerType).id || index}
                container={child as DockContainerType}
                renderPanel={renderPanel}
                className="flex-1"
              />
            );
          }
          return (
            <PanelSlot
              key={(child as DockPanelConfig).id}
              panel={child as DockPanelConfig}
              isDragging={isDragging}
              dropTargetId={dropTargetId}
              compassDir={compassDir}
              onCompassDirChange={setCompassDir}
              onDragStart={handlePanelDragStart(child as DockPanelConfig, false)}
              onClose={() => removePanel((child as DockPanelConfig).id)}
              onFloat={() => floatPanel((child as DockPanelConfig).id)}
              renderPanel={renderPanel}
              className="flex-1"
            />
          );
        })
      )}
    </div>
  );
};

// ΓöÇΓöÇΓöÇ Panel Slot ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
interface PanelSlotProps {
  panel: DockPanelConfig;
  isActive?: boolean;
  showHeader?: boolean;
  isDragging: boolean;
  dropTargetId: string | null;
  compassDir: string | null;
  onCompassDirChange: (dir: string | null) => void;
  onDragStart: (e: React.MouseEvent | React.TouchEvent) => void;
  onClose: () => void;
  onFloat: () => void;
  renderPanel?: (panel: DockPanelConfig, isActive: boolean) => React.ReactNode;
  className?: string;
}

const PanelSlot: React.FC<PanelSlotProps> = ({
  panel,
  isActive = true,
  showHeader = true,
  isDragging,
  dropTargetId,
  compassDir,
  onCompassDirChange,
  onDragStart,
  onClose,
  onFloat,
  renderPanel,
  className,
}) => {
  const isDropTarget = isDragging && dropTargetId === panel.id;
  const showCompass = isDropTarget;
  const showPreview = isDropTarget && compassDir !== null;

  return (
    <div data-dock-panel={panel.id} className={cn('h-full relative', className)}>
      <DockPanel
        panel={panel}
        isActive={isActive}
        showHeader={showHeader}
        isDropTarget={isDropTarget}
        onClose={onClose}
        onFloat={onFloat}
        onDragStart={onDragStart}
      >
        {renderPanel ? renderPanel(panel, isActive) : null}
      </DockPanel>

      {/* Blue preview highlight */}
      {showPreview && <DockPreview direction={compassDir} />}

      {/* Compass rose centered on this panel */}
      {showCompass && (
        <div className="absolute inset-0 z-[180] flex items-center justify-center pointer-events-none">
          <CompassRose
            targetPanelId={panel.id}
            hoveredDir={compassDir}
            onHoverChange={onCompassDirChange}
          />
        </div>
      )}
    </div>
  );
};

// ΓöÇΓöÇΓöÇ Floating Panels Layer ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export const FloatingPanelsLayer: React.FC<{
  renderPanel?: (panel: DockPanelConfig, isActive: boolean) => React.ReactNode;
}> = ({ renderPanel }) => {
  const {
    layout,
    removePanel,
    dockPanel,
    updateFloatingPosition,
    updateFloatingSize,
    startDrag,
  } = useDockLayoutStore();

  // 8-directional resize
  const startResize = (e: React.MouseEvent, floating: any, direction: string) => {
    e.preventDefault();
    e.stopPropagation();

    const startX = e.clientX;
    const startY = e.clientY;
    const startW = floating.size?.width || 400;
    const startH = floating.size?.height || 300;
    const startPX = floating.position?.x || 100;
    const startPY = floating.position?.y || 100;

    let curW = startW, curH = startH, curX = startPX, curY = startPY;

    const onMove = (me: MouseEvent) => {
      const dx = me.clientX - startX;
      const dy = me.clientY - startY;

      if (direction.includes('w')) {
        const pw = startW - dx;
        if (pw >= 200) { curW = pw; curX = startPX + dx; }
        else { curW = 200; curX = startPX + (startW - 200); }
      }
      if (direction.includes('e')) curW = Math.max(200, startW + dx);
      if (direction.includes('n')) {
        const ph = startH - dy;
        if (ph >= 150) { curH = ph; curY = startPY + dy; }
        else { curH = 150; curY = startPY + (startH - 150); }
      }
      if (direction.includes('s')) curH = Math.max(150, startH + dy);

      updateFloatingSize(floating.id, { width: curW, height: curH });
      updateFloatingPosition(floating.id, { x: curX, y: curY });
    };

    const onUp = () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  };

  // Floating drag
  const handleFloatingDrag = (floating: any, panel: DockPanelConfig) => (e: React.MouseEvent) => {
    const startMX = e.clientX, startMY = e.clientY;
    const startPX = floating.position?.x || 100;
    const startPY = floating.position?.y || 100;

    startDrag(panel.id, panel.title, startMX, startMY, true);

    const onMove = (me: MouseEvent) => {
      updateFloatingPosition(floating.id, {
        x: startPX + (me.clientX - startMX),
        y: startPY + (me.clientY - startMY),
      });
    };

    const onUp = () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  };

  if (layout.floatingPanels.length === 0) return null;

  return (
    <>
      {layout.floatingPanels.map((floating) => {
        const panel = floating.children[0] as DockPanelConfig;
        if (!panel) return null;

        return (
          <div
            key={floating.id}
            data-dock-panel={panel.id}
            className="fixed z-50"
            style={{
              left: floating.position?.x || 100,
              top: floating.position?.y || 100,
              width: floating.size?.width || 400,
              height: floating.size?.height || 300,
            }}
          >
            <DockPanel
              panel={panel}
              isActive={true}
              isFloating={true}
              onClose={() => removePanel(panel.id)}
              onFloat={() => dockPanel(panel.id, 'root', 'center')}
              onDragStart={handleFloatingDrag(floating, panel)}
            >
              {renderPanel?.(panel, true)}
            </DockPanel>

            {/* 8 resize handles */}
            <div className="absolute top-0 left-6 right-6 h-2 cursor-ns-resize z-20" onMouseDown={(e) => startResize(e, floating, 'n')} />
            <div className="absolute bottom-0 left-6 right-6 h-2 cursor-ns-resize z-20" onMouseDown={(e) => startResize(e, floating, 's')} />
            <div className="absolute top-6 bottom-6 left-0 w-2 cursor-ew-resize z-20" onMouseDown={(e) => startResize(e, floating, 'w')} />
            <div className="absolute top-6 bottom-6 right-0 w-2 cursor-ew-resize z-20" onMouseDown={(e) => startResize(e, floating, 'e')} />
            <div className="absolute top-0 left-0 w-5 h-5 cursor-nwse-resize z-30" onMouseDown={(e) => startResize(e, floating, 'nw')} />
            <div className="absolute top-0 right-0 w-5 h-5 cursor-nesw-resize z-30" onMouseDown={(e) => startResize(e, floating, 'ne')} />
            <div className="absolute bottom-0 left-0 w-5 h-5 cursor-nesw-resize z-30" onMouseDown={(e) => startResize(e, floating, 'sw')} />
            <div className="absolute bottom-0 right-0 w-5 h-5 cursor-nwse-resize z-30" onMouseDown={(e) => startResize(e, floating, 'se')} />
          </div>
        );
      })}
    </>
  );
};

