/**
 * DockPanel Component
 * MT5-style panel with thin title bar ΓÇö supports Minimize and Close.
 *
 * Minimize: collapses content, shows only the title bar (click title to restore).
 * Close:    removes the panel from the dock layout entirely.
 */

import { Icon } from '../ui/Icon';
import React, { useState } from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';
import type { DockPanelConfig } from '../../services/dockManager';
import { X, Minus } from 'lucide-react';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export interface DockPanelProps {
  panel: DockPanelConfig;
  isActive?: boolean;
  isFloating?: boolean;
  isDropTarget?: boolean;
  showHeader?: boolean;
  className?: string;
  children?: React.ReactNode;
  onClose?: () => void;
  onFloat?: () => void;
  onActivate?: () => void;
  onDragStart?: (e: React.MouseEvent | React.TouchEvent) => void;
  style?: React.CSSProperties;
}

export const DockPanel: React.FC<DockPanelProps> = ({
  panel,
  isActive = true,
  isFloating = false,
  isDropTarget,
  showHeader = true,
  className,
  children,
  onClose,
  onFloat,
  onActivate,
  onDragStart,
  style,
}) => {
  // ΓöÇΓöÇ Minimize state (local ΓÇö collapses content to title bar only) ΓöÇΓöÇ
  const [minimized, setMinimized] = useState(false);

  return (
    <div
      className={cn(
        'flex flex-col bg-[#131316] overflow-hidden relative',
        minimized ? 'h-[22px]' : 'h-full',
        isFloating && 'shadow-2xl border border-zinc-600/40',
        !isFloating && 'border border-[#28282e]/60',
        isDropTarget && 'ring-2 ring-[#8a8a8f]/40 ring-inset',
        className
      )}
      style={style}
      onMouseDown={onActivate}
    >
      {/* ΓöÇΓöÇ MT5-style thin title bar ΓöÇΓöÇ */}
      {showHeader && (
        <div
          className={cn(
            'flex items-center h-[22px] px-1.5 select-none flex-shrink-0',
            // Make cursor a pointer when minimized (click to restore)
            minimized ? 'cursor-pointer' : 'cursor-default',
            isActive
              ? 'bg-gradient-to-r from-[#222226] to-[#191a1e] border-b border-[#28282e]'
              : 'bg-[#131316] border-b border-[#1e1e22]/80',
          )}
          onMouseDown={(e) => {
            // Click on empty header area while minimized ΓåÆ restore
            const target = e.target as HTMLElement;
            if (target.closest('button')) return;
            if (minimized) {
              setMinimized(false);
              return;
            }
            onDragStart?.(e);
          }}
          title={minimized ? `Click to restore ${panel.title}` : undefined}
        >
          {/* Title */}
          <span className="flex-1 text-[11px] font-normal text-zinc-300 truncate leading-[22px]">
            {panel.title}
            {minimized && (
              <span className="ml-1 text-[9px] text-zinc-600 italic">(minimized)</span>
            )}
          </span>

          {/* ΓöÇΓöÇ Minimize button ΓöÇΓöÇ */}
          <button
            onClick={(e) => {
              e.stopPropagation();
              setMinimized((m) => !m);
            }}
            className="w-[16px] h-[16px] flex items-center justify-center rounded-sm hover:bg-zinc-600/80 text-zinc-400 hover:text-white transition-colors mr-0.5"
            title={minimized ? 'Restore' : 'Minimize'}
          >
            {minimized
              ? <Icon name="chevron-up" size="xs" />
              : <Minus className="w-2.5 h-2.5" />
            }
          </button>

          {/* ΓöÇΓöÇ Close button ΓöÇΓöÇ */}
          {panel.closable !== false && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                onClose?.();
              }}
              className="w-[16px] h-[16px] flex items-center justify-center rounded-sm hover:bg-red-500/80 text-zinc-400 hover:text-white transition-colors"
              title="Close"
            >
              <X className="w-3 h-3" />
            </button>
          )}
        </div>
      )}

      {/* ΓöÇΓöÇ Content ΓÇö hidden when minimized ΓöÇΓöÇ */}
      {!minimized && (
        <div className="flex-1 overflow-hidden min-h-0 min-w-0 relative">
          {children || (
            <div className="flex items-center justify-center h-full text-zinc-500 p-4">
              <p className="text-xs">{panel.title}</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default DockPanel;

