import React, { useEffect, useState, useCallback, useRef } from 'react';
import { useDockLayoutStore } from '../../store/useDockLayoutStore';
import { DockContainer, FloatingPanelsLayer } from './DockContainer';
import { TradingChart } from '../TradingChart';
import { ErrorBoundary } from '../ErrorBoundary';
import type { Timeframe, ChartType } from '../TradingChart';
import type { DockPanelConfig } from '../../services/dockManager';
import { useAppStore } from '../../store/useAppStore';
import { ChartLoginPlaceholder } from '../ChartLoginPlaceholder';

import { MarketWatchPanel } from '../layout/MarketWatchPanel';
import { NavigatorPanel } from '../layout/NavigatorPanel';
import { BottomDock } from '../BottomDock';

interface DockWorkspaceProps {
    globalChartType: ChartType;
    globalTimeframe: Timeframe;
    allSymbols: any[];
    selectedSymbol: string;
    onSymbolSelect: (symbol: string) => void;
    account: any;
    positions: any[];
    orders: any[];
    history: any[];
    ledger: any[];
    onClosePosition: (id: string | number) => void;
    onModifyPosition: (id: number, sl: number, tp: number) => void;
    onCancelOrder: (id: string | number) => void;
    onCloseBulk: (type: 'ALL' | 'WINNERS' | 'LOSERS', symbol?: string) => void;
}

export const DockWorkspace: React.FC<DockWorkspaceProps> = ({
    globalChartType,
    globalTimeframe,
    allSymbols,
    selectedSymbol,
    onSymbolSelect,
    account,
    positions,
    orders,
    history,
    ledger,
    onClosePosition,
    onModifyPosition,
    onCancelOrder,
    onCloseBulk
}) => {
    const [isInitialized, setIsInitialized] = useState(false);

    useEffect(() => {
        setIsInitialized(true);
    }, []);

    const isAuthenticated = useAppStore(s => s.isAuthenticated);

    const renderPanel = useCallback((panel: DockPanelConfig, isActive: boolean) => {
        if (panel.component === 'Chart') {
            const chartSymbol = panel.props?.symbol || 'EURUSD';
            // Show placeholder when not authenticated
            if (!isAuthenticated) {
                return (
                    <div className="flex-1 w-full h-full min-h-0 min-w-0 relative flex flex-col">
                        <ChartLoginPlaceholder symbol={chartSymbol} />
                    </div>
                );
            }
            return (
                <div className="flex-1 w-full h-full min-h-0 min-w-0 relative flex flex-col group/chartpanel"
                    style={{ background: '#0e0e12', border: '1px solid #28282e', borderRadius: 6, overflow: 'hidden', transition: 'border-color 0.15s' }}
                    onMouseEnter={e => (e.currentTarget.style.borderColor = '#5a5a65')}
                    onMouseLeave={e => (e.currentTarget.style.borderColor = '#28282e')}
                >
                    <ErrorBoundary>
                        <TradingChart
                            key={`chart-${panel.id}-${chartSymbol}`}
                            symbol={chartSymbol}
                            timeframe={globalTimeframe}
                            chartType={globalChartType}
                        />
                    </ErrorBoundary>
                </div>
            );
        }
        if (panel.component === 'MarketWatch') {
            return (
                <div className="flex-1 w-full h-full min-h-0 min-w-0 relative bg-[#131316] flex flex-col">
                    <ErrorBoundary>
                        <MarketWatchPanel
                            className="flex-1 min-h-0 min-w-0 w-full h-full"
                            allSymbols={allSymbols}
                            selectedSymbol={selectedSymbol}
                            onSymbolSelect={onSymbolSelect}
                        />
                    </ErrorBoundary>
                </div>
            );
        }
        if (panel.component === 'Navigator') {
            return (
                <div className="flex-1 w-full h-full min-h-0 min-w-0 relative bg-[#131316] flex flex-col">
                    <ErrorBoundary>
                        <NavigatorPanel />
                    </ErrorBoundary>
                </div>
            );
        }
        if (panel.component === 'Terminal') {
            return (
                <div className="flex-1 w-full h-full min-h-0 min-w-0 relative bg-[#131316] flex flex-col overflow-hidden">
                    <ErrorBoundary>
                        <BottomDock
                            height="100%"
                            account={account}
                            positions={positions}
                            orders={orders}
                            history={history}
                            ledger={ledger}
                            onClosePosition={onClosePosition as any}
                            onModifyPosition={onModifyPosition}
                            onCancelOrder={onCancelOrder as any}
                            onCloseBulk={onCloseBulk as any}
                        />
                    </ErrorBoundary>
                </div>
            );
        }
        return <div className="p-4 text-muted-foreground whitespace-nowrap overflow-hidden">Unknown Panel type: {panel.component}</div>;
    }, [
        isAuthenticated,
        globalChartType, globalTimeframe,
        allSymbols, selectedSymbol, onSymbolSelect,
        account, positions, orders, history, ledger,
        onClosePosition, onModifyPosition, onCancelOrder, onCloseBulk
    ]);

    if (!isInitialized) return null;

    return (
        <DockWorkspaceClean renderPanel={renderPanel} />
    );
};

// Clean workspace - just renders the dock layout
const DockWorkspaceClean: React.FC<{
    renderPanel: (panel: DockPanelConfig, isActive: boolean) => React.ReactNode;
}> = ({ renderPanel }) => {
    const { layout, resetToDefaultLayout } = useDockLayoutStore();

    const isLayoutEmpty = !layout.root.children || layout.root.children.length === 0;

    // Listen for reset layout event from menu
    useEffect(() => {
        const handleResetLayout = () => {
            resetToDefaultLayout();
        };
        window.addEventListener('resetLayout', handleResetLayout);
        return () => window.removeEventListener('resetLayout', handleResetLayout);
    }, [resetToDefaultLayout]);

    return (
        <div className="flex-1 w-full h-full relative overflow-hidden" style={{ background: '#0d0d11', padding: '6px', gap: '6px' }}>
            {/* Reset Layout Button */}
            {isLayoutEmpty && (
                <button
                    onClick={() => resetToDefaultLayout()}
                    className="absolute top-4 right-4 z-50 bg-emerald-500 hover:bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm font-medium shadow-lg transition-colors"
                >
                    Reset Layout
                </button>
            )}

            <DockContainer
                container={layout.root}
                isRoot={true}
                renderPanel={renderPanel}
            />
            <FloatingPanelsLayer renderPanel={renderPanel} />
        </div>
    );
};

/**
 * DropZoneOverlay Component
 * MT5-Style compass-rose dock zone indicators during panel drag operations
 */

import { Icon } from '../ui/Icon';
import React, { useCallback } from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';
import { useDockLayoutStore } from '../../store/useDockLayoutStore';
import type { DockDirection } from '../../services/dockManager';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export interface DropZoneOverlayProps {
  containerId: string;
  containerRect: { x: number; y: number; width: number; height: number };
}

/**
 * MT5-style compass-rose dock zone buttons
 * Shows 5 small square buttons (Top, Bottom, Left, Right, Center) 
 * in the center of the target container when dragging.
 */
export const DropZoneOverlay: React.FC<DropZoneOverlayProps> = ({
  containerId,
  containerRect,
}) => {
  const { dragState, activeDropZone, updateDropZone } = useDockLayoutStore();

  const isVisible = dragState === 'dragging';
  if (!isVisible) return null;

  const isActiveZone = (dir: DockDirection) =>
    activeDropZone?.targetContainerId === containerId && activeDropZone?.direction === dir;

  const handleZoneHover = useCallback((direction: DockDirection) => {
    updateDropZone({
      id: `${containerId}-${direction}`,
      direction,
      rect: containerRect,
      targetContainerId: containerId,
      priority: direction === 'center' ? 0 : 1,
    });
  }, [containerId, containerRect, updateDropZone]);

  const handleZoneLeave = useCallback(() => {
    updateDropZone(null);
  }, [updateDropZone]);

  // Button size and spacing
  const btnSize = 36;
  const gap = 4;

  return (
    <div className="absolute inset-0 z-50 overflow-hidden rounded-lg bg-black/20">
      {/* Background instruction */}
      <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-background/90 backdrop-blur-sm px-4 py-2 rounded-full border border-border shadow-lg">
        <span className="text-sm font-medium text-foreground">
          Hover over arrows to preview ΓÇó Release to dock
        </span>
      </div>

      {/* Highlight the active zone area */}
      {activeDropZone?.targetContainerId === containerId && (
        <div
          className={cn(
            "absolute bg-emerald-500/20 border-2 border-emerald-500/50 transition-all duration-150 ease-out rounded-lg",
            activeDropZone.direction === 'top' && "top-2 left-2 right-2 h-[48%]",
            activeDropZone.direction === 'bottom' && "bottom-2 left-2 right-2 h-[48%]",
            activeDropZone.direction === 'left' && "left-2 top-2 bottom-2 w-[48%]",
            activeDropZone.direction === 'right' && "right-2 top-2 bottom-2 w-[48%]",
            activeDropZone.direction === 'center' && "inset-4"
          )}
        />
      )}

      {/* MT5-style Compass Rose - 5 dock zone buttons */}
      <div
        className="absolute pointer-events-auto bg-background/80 backdrop-blur-md p-4 rounded-2xl border border-border shadow-2xl"
        style={{
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
        }}
      >
        <div className="text-center text-xs font-medium text-muted-foreground mb-3">
          Drop Zone
        </div>
        {/* Layout: 3x3 grid with buttons at cross positions */}
        <div
          className="grid"
          style={{
            gridTemplateColumns: `${btnSize}px ${btnSize}px ${btnSize}px`,
            gridTemplateRows: `${btnSize}px ${btnSize}px ${btnSize}px`,
            gap: `${gap}px`,
          }}
        >
          {/* Row 1: empty - TOP - empty */}
          <div />
          <DockZoneButton
            direction="top"
            icon="Γû▓"
            isActive={isActiveZone('top')}
            onHover={handleZoneHover}
            onLeave={handleZoneLeave}
            size={btnSize}
            label="Top"
          />
          <div />

          {/* Row 2: LEFT - CENTER - RIGHT */}
          <DockZoneButton
            direction="left"
            icon="Γùä"
            isActive={isActiveZone('left')}
            onHover={handleZoneHover}
            onLeave={handleZoneLeave}
            size={btnSize}
            label="Left"
          />
          <DockZoneButton
            direction="center"
            icon="Γûá"
            isActive={isActiveZone('center')}
            onHover={handleZoneHover}
            onLeave={handleZoneLeave}
            size={btnSize}
            label="Tab"
          />
          <DockZoneButton
            direction="right"
            icon="Γû║"
            isActive={isActiveZone('right')}
            onHover={handleZoneHover}
            onLeave={handleZoneLeave}
            size={btnSize}
            label="Right"
          />

          {/* Row 3: empty - BOTTOM - empty */}
          <div />
          <DockZoneButton
            direction="bottom"
            icon="Γû╝"
            isActive={isActiveZone('bottom')}
            onHover={handleZoneHover}
            onLeave={handleZoneLeave}
            size={btnSize}
            label="Bottom"
          />
          <div />
        </div>
      </div>
    </div>
  );
};

/**
 * Individual dock zone button (MT5 style small square)
 */
const DockZoneButton: React.FC<{
  direction: DockDirection;
  icon: string;
  isActive: boolean;
  onHover: (dir: DockDirection) => void;
  onLeave: () => void;
  size: number;
  label: string;
}> = ({ direction, icon, isActive, onHover, onLeave, size, label }) => {
  return (
    <div
      className={cn(
        'flex flex-col items-center justify-center rounded-lg border-2 transition-all duration-150 cursor-pointer select-none',
        isActive
          ? 'bg-emerald-500 border-emerald-400 text-white shadow-lg shadow-emerald-500/30 scale-110'
          : 'bg-zinc-800/90 border-zinc-600 text-zinc-400 hover:bg-emerald-500/80 hover:border-emerald-400 hover:text-white'
      )}
      style={{ width: size, height: size }}
      onMouseEnter={() => onHover(direction)}
      onMouseLeave={onLeave}
      title={`Dock ${direction}`}
    >
      <span className="text-[14px] font-bold leading-none">{icon}</span>
      {isActive && (
        <span className="text-[8px] mt-0.5">{label}</span>
      )}
    </div>
  );
};

/**
 * Ghost Preview Component
 */
export const GhostPreview: React.FC = () => {
  const { ghostPreview, activeDropZone, dragState } = useDockLayoutStore();

  if (dragState !== 'dragging' || !ghostPreview.visible) return null;

  return (
    <div
      className={cn(
        'fixed pointer-events-none z-[100] transition-all duration-100',
        activeDropZone ? 'opacity-100' : 'opacity-50'
      )}
      style={{
        left: ghostPreview.x,
        top: ghostPreview.y,
        width: ghostPreview.width,
        height: ghostPreview.height,
      }}
    >
      <div
        className={cn(
          'w-full h-full rounded-lg border-2 border-dashed',
          activeDropZone
            ? 'border-zinc-600 bg-zinc-700/20 shadow-lg shadow-blue-500/20'
            : 'border-muted-foreground bg-background/50'
        )}
      >
        {activeDropZone && (
          <div className="absolute -top-8 left-1/2 -translate-x-1/2 bg-zinc-8000 text-white px-2 py-1 rounded text-xs font-medium whitespace-nowrap">
            Dock {activeDropZone.direction}
          </div>
        )}
      </div>
    </div>
  );
};

/**
 * Global Drop Zone Overlay - shows drag cursor and instructions
 */
export const GlobalDropZoneOverlay: React.FC = () => {
  const { dragState, dragInfo } = useDockLayoutStore();

  if (dragState !== 'dragging' || !dragInfo) return null;

  return (
    <>
      {/* Drag Cursor - follows mouse */}
      <div
        className="fixed z-[100] pointer-events-none"
        style={{
          left: dragInfo.currentX - 16,
          top: dragInfo.currentY - 16,
        }}
      >
        <div className="w-8 h-8 bg-emerald-500 rounded-full flex items-center justify-center shadow-lg ring-2 ring-white">
          <Icon name="grid" size="sm" className="w-4 h-4 text-white" />
        </div>
      </div>

      {/* Bottom instructions */}
      <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-[100] bg-background/90 backdrop-blur-sm px-4 py-2 rounded-full border border-border shadow-lg">
        <span className="text-xs text-muted-foreground">
          Hover over target panel arrows to preview ΓÇó Release to dock ΓÇó ESC to cancel
        </span>
      </div>
    </>
  );
};

export default DropZoneOverlay;

