};

// Drop Zone Indicator
const DropZoneIndicator: React.FC<{
  direction: DockDirection;
  isActive: boolean;
  onEnter: () => void;
  onLeave: () => void;
}> = ({ direction, isActive, onEnter, onLeave }) => {
  const icons = {
    top: ArrowUp,
    bottom: ArrowDown,
    left: ArrowLeft,
    right: ArrowRight,
    center: LayoutGrid,
    tab: LayoutGrid,
  };

  const labels = { top: 'Top', bottom: 'Bottom', left: 'Left', right: 'Right', center: 'Tab', tab: 'Tab' };
