const PRIORITIES = ['High', 'Medium', 'Low', 'Holiday'];
const CURRENCIES = ['ALL', 'USD', 'EUR', 'GBP', 'JPY', 'AUD', 'CAD', 'CHF', 'CNY', 'NZD'];
const COUNTRIES = [
    'All Countries', 'United States', 'European Union', 'United Kingdom', 'Japan',
