            )}

            {showExitDialog && (
                <ExitConfirmDialog
                    isOpen={showExitDialog}
                    changes={{
                        hasWorkspaceChanges: hasUnsavedChanges,
                        hasOpenTrades: false,
                        hasDraftOrders: false,
                        openTradesCount: 0,
                        draftOrdersCount: 0,
