                    if (baseMatch) tick = liveTicks[baseMatch];
                  }

                  return (
                    <MarketWatchRow
                      key={symbol}
                      symbol={symbol}
                      tick={tick}
                      isSelected={symbol === normalizeSymbol(selectedSymbol)}
                      onClick={() => onSymbolSelect(symbol)}
                      contextMenuItems={getContextMenuItems(symbol)}
                      showAsk={showAsk}
                      showSpread={showSpread}
                      showDaily={showDaily}
                    />
                  );
                })}
              </tbody>
