                            const buildNestedMenu = (symbols: typeof availableSymbols): MenuItem[] => {
                                const root: MenuItem[] = [];
                                const groups: Record<string, typeof availableSymbols> = {};

                                symbols.forEach(sym => {
                                    // If category is empty, it's a root item
