                                // Add grouped items (folders) after root items
                                Object.keys(groups).sort().forEach(key => {
                                    const groupSymbols = groups[key];
                                    // Recurse
                                    root.push({
                                        label: key,
                                        children: buildNestedMenu(groupSymbols)
                                    });
                                });
                                return root;
                            };
                            return buildNestedMenu(availableSymbols);
                        })()
