interface TopToolbarProps {
    chartType: ChartType;
    timeframe: Timeframe;
    onChartTypeChange: (type: ChartType) => void;
    onTimeframeChange: (tf: Timeframe) => void;
    onToggleDOM?: () => void;
    symbol?: string;
    onLoadTemplate?: (template: any) => void;
}

import { MenuBar } from './MenuBar';
import { DrawingsDropdown } from './DrawingsDropdown';
import { ChartTemplateManager } from '../ChartTemplateManager';
import { indicatorManager } from '../../services/indicatorManager';
import { drawingManager } from '../../services/drawingManager';
import { captureFullPage } from '../../services/screenshotService';

export const TopToolbar: React.FC<TopToolbarProps> = ({
    chartType,
    timeframe,
    onChartTypeChange,
    onTimeframeChange,
    onToggleDOM,
    symbol = 'BTCUSD',
    onLoadTemplate
}) => {
    const { state: toolbarState, dispatch: dispatchToolbar } = useToolbarState();
    const { dispatch: dispatchCommand } = useCommandBus();

    // Sync magnet state to drawingManager
    useEffect(() => {
        drawingManager.setMagnetEnabled(toolbarState.magnetEnabled);
    }, [toolbarState.magnetEnabled]);

    // Sync active drawing tool to drawingManager
    useEffect(() => {
        if (toolbarState.activeTool && toolbarState.activeTool !== 'cursor') {
            drawingManager.startDrawing(toolbarState.activeTool as any);
        } else {
            drawingManager.cancelDrawing();
        }
    }, [toolbarState.activeTool]);

    // Auto-reset to cursor after drawing is completed
    useEffect(() => {
        const handleDrawingSaved = () => {
            dispatchToolbar({ type: 'SELECT_TOOL', tool: 'cursor' });
        };
        window.addEventListener('drawing:saved', handleDrawingSaved);
        return () => window.removeEventListener('drawing:saved', handleDrawingSaved);
    }, [dispatchToolbar]);

    // Register keyboard shortcuts on mount
    useEffect(() => {
        const unregister = registerKeyboardShortcutsWithInputCheck(dispatchCommand);
        return unregister;
    }, [dispatchCommand]);

    // Sync props with toolbar state
    useEffect(() => {
        if (chartType !== toolbarState.chartType) {
            dispatchToolbar({ type: 'SET_CHART_TYPE', chartType: chartType as any });
        }
    }, [chartType, toolbarState.chartType, dispatchToolbar]);

    useEffect(() => {
        if (timeframe !== toolbarState.timeframe) {
            dispatchToolbar({ type: 'SET_TIMEFRAME', timeframe });
        }
    }, [timeframe, toolbarState.timeframe, dispatchToolbar]);

    return (
        <div className="flex flex-col z-50 relative">
            {/* 1. Header Bar (Topmost) */}
            <HeaderBar
                symbol={symbol}
                timeframe={timeframe}
                server="FlexyMarkets-Server"
            />

            {/* 2. Menu Bar (File, View, etc.) */}
            <MenuBar />

            {/* 3. Main Toolbar (Icons Row) */}
            <MainToolbar
                chartType={chartType}
                timeframe={timeframe}
                onChartTypeChange={onChartTypeChange}
                onTimeframeChange={onTimeframeChange}
                onToggleDOM={onToggleDOM}
                toolbarState={toolbarState}
                dispatchCommand={dispatchCommand}
                dispatchToolbar={dispatchToolbar}
                symbol={symbol}
                onLoadTemplate={onLoadTemplate}
            />

        </div>
    );
};

// --- Sub-Components ---

const HeaderBar = ({ symbol, timeframe, server }: { symbol: string, timeframe: string, server: string }) => {
    const accountId = useAppStore((s) => s.accountId) || '---';
    const [isMaximized, setIsMaximized] = React.useState(false);

    // Sync initial maximize state and subscribe to changes
    React.useEffect(() => {
        const electronWin = (window as any).electron?.window;
        if (!electronWin) return;
        // Get initial state
        electronWin.isMaximized().then(setIsMaximized).catch(() => { });
        // Listen for changes
        const cleanup = electronWin.onMaximizeChange((val: boolean) => setIsMaximized(val));
        return cleanup;
    }, []);

    const handleMinimize = () => (window as any).electron?.window?.minimize();
    const handleMaximize = () => (window as any).electron?.window?.maximize();
    const handleClose = () => (window as any).electron?.window?.close();

    return (
        <div
            className="h-7 bg-[#131316] flex items-center justify-between text-[12px] font-segoe select-none text-zinc-300 border-b border-[#2a2e39]"
            style={{ WebkitAppRegion: 'drag' } as React.CSSProperties}
        >
            {/* Left: Standard Title */}
            <div className="flex items-center gap-2 px-2" style={{ WebkitAppRegion: 'no-drag' } as React.CSSProperties}>
                <img src="./titlebar-icon.png" alt="RTX Logo" className="w-4 h-4 object-contain ml-1 rounded-sm" />
                <span>{accountId} - {server} - Hedge - Flexy Markets Limited - {symbol},{timeframe.toUpperCase()}</span>
            </div>

            {/* Right: Window Controls ΓÇö no-drag so clicks register */}
            <div
                className="flex items-center gap-0 h-full"
                style={{ WebkitAppRegion: 'no-drag' } as React.CSSProperties}
            >
                {/* Minimize */}
                <button
                    className="h-full px-3 hover:bg-white/10 transition-colors flex items-center justify-center"
                    onClick={handleMinimize}
                    title="Minimize"
                >
                    <Minus size={10} className="text-zinc-400" strokeWidth={1.8} />
                </button>

                {/* Maximize / Restore */}
                <button
                    className="h-full px-3 hover:bg-white/10 transition-colors flex items-center justify-center"
                    onClick={handleMaximize}
                    title={isMaximized ? 'Restore' : 'Maximize'}
                >
                    {isMaximized ? (
                        /* Restore icon: two overlapping squares */
                        <svg width="11" height="11" viewBox="0 0 12 12" fill="none" className="text-zinc-400" stroke="currentColor" strokeWidth="1.5">
                            <rect x="3" y="1" width="8" height="8" rx="1" />
                            <path d="M1 4v6a1 1 0 001 1h6" />
                        </svg>
                    ) : (
                        /* Maximize icon: single square */
                        <svg width="11" height="11" viewBox="0 0 12 12" fill="none" className="text-zinc-400" stroke="currentColor" strokeWidth="1.5">
                            <rect x="1" y="1" width="10" height="10" rx="1" />
                        </svg>
                    )}
                </button>

                {/* Close */}
                <button
                    className="h-full px-4 hover:bg-red-500 hover:text-white transition-colors flex items-center justify-center group"
                    onClick={handleClose}
                    title="Close"
                >
                    <svg width="10" height="10" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" className="text-zinc-400 group-hover:text-white"><path d="M2 2l8 8M10 2l-8 8"/></svg>
                </button>
            </div>

        </div>
    );
};


interface MainToolbarProps extends TopToolbarProps {
    toolbarState: any;
    dispatchCommand: (cmd: Command) => void;
    dispatchToolbar: (action: any) => void;
    symbol: string;
    onLoadTemplate?: (template: any) => void;
}

const MainToolbar = ({
    chartType,
    timeframe,
    onChartTypeChange,
    onTimeframeChange,
    onToggleDOM,
    toolbarState,
    dispatchCommand,
    dispatchToolbar,
    symbol,
    onLoadTemplate
}: MainToolbarProps) => {

    const handleToolSelect = (toolId: string) => {
        dispatchToolbar({ type: 'SELECT_TOOL', tool: toolId as any });
    };

    // User dropdown state
    const [showUserMenu, setShowUserMenu] = useState(false);
    const [loggingOut, setLoggingOut] = useState(false);
    const userMenuRef = useRef<HTMLDivElement>(null);
    const dropdownRef = useRef<HTMLDivElement>(null);
    const accountId = useAppStore((s) => s.accountId) || '---';

    // Close dropdown on outside click
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            const target = e.target as Node;
            // Check both the button wrapper AND the portal dropdown
            if (
                userMenuRef.current && !userMenuRef.current.contains(target) &&
                dropdownRef.current && !dropdownRef.current.contains(target)
            ) {
                setShowUserMenu(false);
            }
        };
        if (showUserMenu) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [showUserMenu]);

    const handleLogout = () => {
        // Fire-and-forget the backend logout API (don't wait)
        fetch('https://rtxbackend.tradecopier.org/api/logout', {
            method: 'POST',
            headers: {
                'accept': '*/*',
                'Authorization': `Bearer ${localStorage.getItem('auth_token') || ''}`,
            },
        }).catch(() => { /* ignore */ });

        // Clear all auth state immediately
        useAppStore.getState().logout();
        // Force full page reload to show login
        window.location.reload();
    };

    return (
        <div className="flex items-center bg-[#131316] border-b border-[#2a2e39] h-[40px] px-1.5 shadow-sm select-none overflow-x-auto no-scrollbar gap-[2px]">



            {/* New Order & Last Symbol */}
            <MT5Group>

                <button
                    className="flex items-center gap-1.5 px-2.5 h-[32px] rounded-[3px] bg-transparent border border-transparent hover:border-zinc-700 hover:bg-[#2a2e39] text-[12px] text-zinc-300 hover:text-white transition-all font-segoe"
                    title="New Order (F9)"
                    onClick={() => {
                        window.dispatchEvent(new CustomEvent('openNewOrder'));
                    }}
                >
                    <FileText size={16} strokeWidth={1.5} className="text-blue-400" />
                    <span>New Order</span>
                </button>

                {/* Last Symbol Trader Toggle */}
                <button
                    className={`flex items-center gap-1.5 px-2.5 h-[32px] rounded-[3px] border text-[12px] transition-all font-segoe ${useLastSymbolStore.getState().panelVisible
                        ? 'bg-amber-500/15 border-amber-500/30 text-amber-400 hover:bg-amber-500/25'
                        : 'bg-transparent border-transparent hover:border-zinc-700 hover:bg-[#2a2e39] text-zinc-300 hover:text-white'
                        }`}
                    title="Last Symbol Trader Panel (Shift+B/S/X)"
                    onClick={() => useLastSymbolStore.getState().togglePanel()}
                >
                    <TrendingUp size={16} strokeWidth={1.5} />
                    <span>Last Symbol</span>
                    {useLastSymbolStore.getState().lastSymbol && (
                        <span className="px-1 py-0.5 rounded bg-amber-500/20 text-amber-400 text-[9px] font-mono font-bold">
                            {useLastSymbolStore.getState().lastSymbol}
                        </span>
                    )}
                </button>
            </MT5Group>

            <MT5Divider />

            {/* Group 3: Chart Types */}
            <MT5Group>
                <MT5Btn icon={<BarChart2 size={16} strokeWidth={1.5} className="text-emerald-500" />} title="Bar Chart" active={toolbarState.chartType === 'bar'} onClick={() => { onChartTypeChange('bar'); dispatchToolbar({ type: 'SET_CHART_TYPE', chartType: 'bar' }); dispatchCommand({ type: 'SET_CHART_TYPE', payload: { chartType: 'bar' } }); }} />
                <MT5Btn icon={<CandlestickChart size={16} strokeWidth={1.5} className="text-emerald-500" />} title="Candlesticks" active={toolbarState.chartType === 'candlestick'} onClick={() => { onChartTypeChange('candlestick'); dispatchToolbar({ type: 'SET_CHART_TYPE', chartType: 'candlestick' }); dispatchCommand({ type: 'SET_CHART_TYPE', payload: { chartType: 'candlestick' } }); }} />
                <MT5Btn icon={<LineChart size={16} strokeWidth={1.5} className="text-emerald-500" />} title="Line Chart" active={toolbarState.chartType === 'line' || toolbarState.chartType === 'area'} onClick={() => { onChartTypeChange('area'); dispatchToolbar({ type: 'SET_CHART_TYPE', chartType: 'area' }); dispatchCommand({ type: 'SET_CHART_TYPE', payload: { chartType: 'area' } }); }} />
            </MT5Group>

            <MT5Divider />

            {/* Group 4: Zoom */}
            <MT5Group>
                <MT5Btn icon={<ZoomIn size={16} strokeWidth={1.5} className="text-blue-400" />} title="Zoom In" onClick={() => dispatchCommand({ type: 'ZOOM_IN', payload: {} })} />
                <MT5Btn icon={<ZoomOut size={16} strokeWidth={1.5} className="text-blue-400" />} title="Zoom Out" onClick={() => dispatchCommand({ type: 'ZOOM_OUT', payload: {} })} />
            </MT5Group>

            <MT5Divider />

            {/* Group 5: Tile Windows */}
            <MT5Group>
                <MT5Btn icon={<LayoutPanelTop size={16} strokeWidth={1.5} className="text-blue-400" />} title="Arrange Windows" onClick={() => dispatchCommand({ type: 'TILE_WINDOWS', payload: { mode: 'grid' } })} />
            </MT5Group>

            <MT5Divider />

            {/* Group 6: Scroll/Shift */}
            <MT5Group>
                <MT5Btn icon={<RefreshCw size={16} strokeWidth={1.5} className="text-emerald-500" />} title="Auto Scroll" active={toolbarState.autoScrollEnabled} onClick={() => dispatchToolbar({ type: 'TOGGLE_AUTO_SCROLL' })} />
                <MT5Btn icon={<AlignJustify size={16} strokeWidth={1.5} className="text-emerald-500" />} title="Chart Shift" active={toolbarState.chartShiftEnabled} onClick={() => dispatchToolbar({ type: 'TOGGLE_CHART_SHIFT' })} />
            </MT5Group>

            <MT5Divider />

            {/* Group 7: Indicators */}
            <MT5Group>
                <MT5Btn icon={<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><rect x="1.5" y="2" width="13" height="12" rx="1"/><polyline points="3 11 5 7.5 7.5 9.5 10 5.5 13 7" strokeWidth="1.3"/><circle cx="12.5" cy="3.5" r="1" fill="#fbbf24" stroke="none"/></svg>} title="Indicators List" onClick={() => dispatchCommand({ type: 'OPEN_INDICATOR_LIST', payload: {} })} />
            </MT5Group>

            <MT5Divider />

            {/* Group 8: Timeframes */}
            <div className="flex items-center gap-[1px]">
                {(['M1', 'M5', 'M15', 'M30', 'H1', 'H4', 'D1', 'W1', 'MN'] as string[]).map((tf) => (
                    <button
                        key={tf}
                        onClick={() => {
                            onTimeframeChange(tf as Timeframe);
                            dispatchCommand({ type: 'SET_TIMEFRAME', payload: { timeframe: tf } });
                        }}
                        className={`px-1.5 py-0.5 text-[11px] font-segoe rounded-[3px] transition-all border ${timeframe === tf
                            ? 'bg-zinc-8000/15 text-blue-400 border-zinc-600/30'
                            : 'text-zinc-400 bg-transparent border-transparent hover:bg-[#2a2e39] hover:text-white hover:border-zinc-700'
                            }`}
                    >
                        {tf}
                    </button>
                ))}
            </div>

            <MT5Divider />

            {/* Group 9: Drawing Tools */}
            <MT5Group>
                <MT5Btn icon={<MousePointer2 size={16} strokeWidth={1.5} className="text-blue-400" />} active={toolbarState.activeTool === null || toolbarState.activeTool === 'cursor'} onClick={() => handleToolSelect('cursor')} title="Cursor" />
                <MT5Btn icon={<Crosshair size={16} strokeWidth={1.5} className="text-blue-400" />} active={toolbarState.crosshairEnabled && toolbarState.activeTool !== 'cursor'} onClick={() => { dispatchCommand({ type: 'TOGGLE_CROSSHAIR', payload: {} }); if (toolbarState.activeTool !== null) handleToolSelect('cursor'); }} title="Crosshair" />
                <MT5Btn icon={<MoveVertical size={16} strokeWidth={1.5} className="text-blue-400" />} active={toolbarState.activeTool === 'vline'} onClick={() => handleToolSelect('vline')} title="Vertical Line" />
                <MT5Btn icon={<MoveHorizontal size={16} strokeWidth={1.5} className="text-blue-400" />} active={toolbarState.activeTool === 'hline'} onClick={() => handleToolSelect('hline')} title="Horizontal Line" />
                <MT5Btn icon={<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"><line x1="2.5" y1="13.5" x2="13.5" y2="2.5"/><circle cx="2.5" cy="13.5" r="1.5" fill="currentColor" stroke="none"/><circle cx="13.5" cy="2.5" r="1.5" fill="currentColor" stroke="none"/></svg>} active={toolbarState.activeTool === 'trendline'} onClick={() => handleToolSelect('trendline')} title="Trend Line" />
                <MT5Btn icon={<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"><line x1="2" y1="13" x2="12" y2="3"/><line x1="5" y1="14" x2="15" y2="4" strokeDasharray="2.5 1.5"/><circle cx="2" cy="13" r="1.5" fill="currentColor" stroke="none"/><circle cx="12" cy="3" r="1.5" fill="currentColor" stroke="none"/></svg>} active={toolbarState.activeTool === 'channel'} onClick={() => handleToolSelect('channel')} title="Equidistant Channel" />
                <MT5Btn icon={<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round"><line x1="1" y1="3" x2="15" y2="3"/><line x1="1" y1="7" x2="15" y2="7"/><line x1="1" y1="10" x2="15" y2="10"/><line x1="1" y1="13" x2="15" y2="13"/><line x1="3" y1="13" x2="13" y2="3" strokeDasharray="2 2"/></svg>} active={toolbarState.activeTool === 'fibonacci'} onClick={() => handleToolSelect('fibonacci')} title="Fibonacci Retracement" />
                <MT5Btn icon={<Type size={16} strokeWidth={1.5} className="text-blue-400" />} active={toolbarState.activeTool === 'text'} onClick={() => handleToolSelect('text')} title="Text" />
                <MT5Btn icon={<Shapes size={16} strokeWidth={1.5} className="text-blue-400" />} active={toolbarState.activeTool === 'rectangle' || toolbarState.activeTool === 'ellipse'} onClick={() => handleToolSelect('rectangle')} title="Rectangle" />
            </MT5Group>

            <MT5Divider />

            {/* Group 10: Screenshot */}
            <MT5Group>
                <MT5Btn icon={<Camera size={16} strokeWidth={1.5} className="text-blue-400" />} title="Screenshot (Export Chart)" onClick={() => {
                    captureFullPage();
                }} />
            </MT5Group>

            {/* Spacer pushing the rest to the right (if space permits) */}
            <div className="flex-1" />

            {/* Group 10: Far right controls */}
            <MT5Group>
                <MT5Btn icon={<Search size={15} strokeWidth={1.5} className="text-zinc-400" />} title="Search" />

                {/* User Icon with Logout Dropdown */}
                <div className="relative" ref={userMenuRef}>
                    <button
                        onClick={() => setShowUserMenu(!showUserMenu)}
                        className={`flex items-center justify-center w-[32px] h-[32px] rounded-[3px] transition-all border group relative ${showUserMenu
                            ? 'bg-zinc-8000/15 border-zinc-600/30 text-blue-400'
                            : 'bg-transparent border-transparent hover:border-zinc-700 hover:bg-[#2a2e39] text-zinc-400 hover:text-white'
                            }`}
                        title="Account"
                    >
                        <User size={16} strokeWidth={1.5} />
                        <div className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 text-white rounded-full flex items-center justify-center text-[7px] font-bold">1</div>
                    </button>

                    {/* Dropdown Menu - rendered via portal to escape overflow clipping */}
                    {showUserMenu && ReactDOM.createPortal(
                        <div
                            ref={dropdownRef}
                            className="fixed w-52 bg-[#1e222d] border border-zinc-600 rounded shadow-2xl z-[9999] py-1"
                            style={{
                                top: (userMenuRef.current?.getBoundingClientRect().bottom ?? 0) + 4,
                                right: window.innerWidth - (userMenuRef.current?.getBoundingClientRect().right ?? 0),
                            }}
                        >
                            {/* Account info */}
                            <div className="px-3 py-2 border-b border-zinc-700">
                                <div className="text-[10px] text-zinc-500 uppercase tracking-wider mb-1">Account</div>
                                <div className="text-[12px] text-zinc-200 font-mono font-medium">{accountId}</div>
                            </div>

                            {/* Logout button */}
                            <button
                                onClick={handleLogout}
                                disabled={loggingOut}
                                className="w-full flex items-center gap-2.5 px-3 py-2 text-[12px] text-red-400 hover:bg-red-500/15 hover:text-red-300 transition-colors disabled:opacity-50"
                            >
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                    <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" />
                                    <polyline points="16 17 21 12 16 7" />
                                    <line x1="21" y1="12" x2="9" y2="12" />
                                </svg>
                                {loggingOut ? 'Logging out...' : 'Log Out'}
                            </button>
                        </div>,
                        document.body
                    )}
                </div>

                <Shield size={15} strokeWidth={1.5} className="text-emerald-500 mx-1" />
                {/* Ping bar block */}
                <div className="w-[40px] h-3.5 border border-zinc-600 ml-1 mt-0.5 relative bg-[#0d0d11]">
                    <div className="absolute top-0 left-0 h-full w-[15%] bg-emerald-500"></div>
                </div>
            </MT5Group>

        </div>
    );
};



// --- MT5 Style Utility Components (matching DrawingToolbar) ---

const MT5Group = ({ children }: { children: React.ReactNode }) => (
    <div className="flex items-center gap-[2px]">
        {children}
    </div>
);

const MT5Divider = () => (
    <div className="mx-[4px] w-[2px] h-6 border-l border-[#2a2e39] bg-[#1a1c23] shadow-sm" />
);

interface MT5BtnProps {
    icon: React.ReactNode;
    title: string;
    active?: boolean;
    onClick?: () => void;
}

const MT5Btn = ({ icon, title, active, onClick }: MT5BtnProps) => (
    <button
        onClick={onClick}
        title={title}
        className={`flex items-center justify-center w-[32px] h-[32px] rounded-[3px] transition-all border group
            ${active
                ? 'bg-zinc-8000/15 border-zinc-600/30 shadow-[inset_0_1px_2px_rgba(0,0,0,0.2)] text-blue-400'
                : 'bg-transparent border-transparent hover:border-zinc-700 hover:bg-[#2a2e39] text-zinc-400 hover:text-white'
            }
        `}
    >
        {/* Pass active state down implicitly if children rely on currentColor */}
        {icon}
    </button>
);

