/**
 * Toast Notification Component
 * Transient notifications that auto-dismiss based on severity
 */

import { Icon } from '../ui/Icon';
import React, { useEffect, useState } from 'react';
import type { NotificationSeverity } from '../../store/useNotificationStore';

export interface ToastNotification {
  id: string;
  severity: NotificationSeverity;
  title: string;
  message: string;
  onDismiss: () => void;
}

interface ToastProps {
  notification: ToastNotification;
}

export const Toast: React.FC<ToastProps> = ({ notification }) => {
  const [isExiting, setIsExiting] = useState(false);

  // Auto-dismiss based on severity
  useEffect(() => {
    if (notification.severity === 'critical') {
      // Critical notifications don't auto-dismiss
      return;
    }

    const duration =
      notification.severity === 'error' ? 15000 :
      notification.severity === 'warning' ? 10000 :
      5000; // info default

    const timer = setTimeout(() => {
      handleDismiss();
    }, duration);

    return () => clearTimeout(timer);
  }, [notification.severity]);

  const handleDismiss = () => {
    setIsExiting(true);
    setTimeout(() => {
      notification.onDismiss();
    }, 200); // Match animation duration
  };

  const getSeverityConfig = () => {
    switch (notification.severity) {
      case 'critical':
        return {
          icon: <Icon name="x-close" size="sm" className="w-5 h-5 flex-shrink-0" />,
          borderColor: 'border-rose-500',
          bgColor: 'bg-rose-500/10',
          textColor: 'text-rose-300',
          iconColor: 'text-rose-400',
        };
      case 'error':
        return {
          icon: <Icon name="error" size="sm" className="w-5 h-5 flex-shrink-0" />,
          borderColor: 'border-orange-500',
          bgColor: 'bg-orange-500/10',
          textColor: 'text-orange-300',
          iconColor: 'text-orange-400',
        };
      case 'warning':
        return {
          icon: <Icon name="alert-triangle" size="sm" className="w-5 h-5 flex-shrink-0" />,
          borderColor: 'border-yellow-500',
          bgColor: 'bg-yellow-500/10',
          textColor: 'text-yellow-300',
          iconColor: 'text-yellow-400',
        };
      case 'info':
      default:
        return {
          icon: <Icon name="info" size="sm" className="w-5 h-5 flex-shrink-0" />,
          borderColor: 'border-zinc-600',
          bgColor: 'bg-zinc-700/20',
          textColor: 'text-zinc-300',
          iconColor: 'text-blue-400',
        };
    }
  };

  const config = getSeverityConfig();

  return (
    <div
      className={`w-80 ${config.bgColor} ${config.borderColor} border-l-4 rounded-lg shadow-2xl p-4 mb-3 transition-all duration-200 ${
        isExiting ? 'opacity-0 translate-x-full' : 'opacity-100 translate-x-0 animate-in slide-in-from-right-5'
      }`}
    >
      <div className="flex items-start gap-3">
        <div className={config.iconColor}>
          {config.icon}
        </div>

        <div className="flex-1 min-w-0">
          <h4 className={`text-sm font-bold ${config.textColor} mb-1`}>
            {notification.title}
          </h4>
          <p className="text-xs text-zinc-400 leading-relaxed break-words">
            {notification.message}
          </p>
        </div>

        <button
          onClick={handleDismiss}
          className="flex-shrink-0 text-zinc-500 hover:text-zinc-300 transition-colors"
        >
          <Icon name="x-close" size="sm" className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
};

/**
 * Toast Container Component
 * Manages and renders multiple toast notifications
 */

interface ToastContainerProps {
  notifications: ToastNotification[];
}

export const ToastContainer: React.FC<ToastContainerProps> = ({ notifications }) => {
  // Limit to 5 visible toasts
  const visibleToasts = notifications.slice(0, 5);

  if (visibleToasts.length === 0) return null;

  return (
    <div className="fixed top-4 right-4 z-[9999] pointer-events-none">
      <div className="pointer-events-auto space-y-0">
        {visibleToasts.map((notification) => (
          <Toast key={notification.id} notification={notification} />
        ))}
      </div>
    </div>
  );
};

/**
 * Alerts & Notifications Panel
 * Price alerts, trade notifications, and system messages
 */

import { Icon } from '../ui/Icon';
import { useState, useCallback, useMemo } from 'react';
import type { Alert, AlertType, AlertPriority, PriceAlert, Notification } from '../../types/trading';

export const AlertsPanel = () => {
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [showCreateAlert, setShowCreateAlert] = useState(false);
  const [filter, setFilter] = useState<'ALL' | 'ACTIVE' | 'TRIGGERED'>('ALL');

  const filteredAlerts = useMemo(() => {
    if (filter === 'ALL') return alerts;
    return alerts.filter((alert) => alert.status === filter);
  }, [alerts, filter]);

  const addNotification = useCallback((notification: Omit<Notification, 'id' | 'timestamp'>) => {
    const newNotif: Notification = {
      ...notification,
      id: `notif-${Date.now()}-${Math.random()}`,
      timestamp: Date.now(),
    };

    setNotifications((prev) => [newNotif, ...prev].slice(0, 50));

    // Auto-remove after duration
    if (notification.duration) {
      setTimeout(() => {
        setNotifications((prev) => prev.filter((n) => n.id !== newNotif.id));
      }, notification.duration);
    }
  }, []);

  const removeAlert = useCallback((id: string) => {
    setAlerts((prev) => prev.filter((a) => a.id !== id));
  }, []);

  const removeNotification = useCallback((id: string) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));
  }, []);

  return (
    <div className="flex flex-col h-full bg-zinc-900">
      {/* Header */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-zinc-800 bg-zinc-900/50">
        <div className="flex items-center gap-2">
          <Icon name="bell" size="sm" className="w-4 h-4 text-emerald-400" />
          <h3 className="text-xs font-semibold text-zinc-300 uppercase tracking-wide">
            Alerts & Notifications
          </h3>
          {alerts.filter((a) => a.status === 'ACTIVE').length > 0 && (
            <span className="px-1.5 py-0.5 bg-emerald-500/20 text-emerald-400 text-[10px] font-medium rounded">
              {alerts.filter((a) => a.status === 'ACTIVE').length}
            </span>
          )}
        </div>
        <button
          onClick={() => setShowCreateAlert(true)}
          className="p-1.5 hover:bg-zinc-800 rounded transition-colors text-zinc-400 hover:text-zinc-200"
          title="Create Alert"
        >
          <Icon name="plus" size="sm" />
        </button>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-zinc-800">
        <button
          onClick={() => setFilter('ALL')}
          className={`flex-1 px-3 py-2 text-xs font-medium transition-colors ${
            filter === 'ALL'
              ? 'text-emerald-400 border-b-2 border-emerald-500 bg-emerald-500/5'
              : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-800/50'
          }`}
        >
          All ({alerts.length})
        </button>
        <button
          onClick={() => setFilter('ACTIVE')}
          className={`flex-1 px-3 py-2 text-xs font-medium transition-colors ${
            filter === 'ACTIVE'
              ? 'text-emerald-400 border-b-2 border-emerald-500 bg-emerald-500/5'
              : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-800/50'
          }`}
        >
          Active ({alerts.filter((a) => a.status === 'ACTIVE').length})
        </button>
        <button
          onClick={() => setFilter('TRIGGERED')}
          className={`flex-1 px-3 py-2 text-xs font-medium transition-colors ${
            filter === 'TRIGGERED'
              ? 'text-emerald-400 border-b-2 border-emerald-500 bg-emerald-500/5'
              : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-800/50'
          }`}
        >
          History ({alerts.filter((a) => a.status === 'TRIGGERED').length})
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto">
        {/* Notifications Section */}
        {notifications.length > 0 && (
          <div className="border-b border-zinc-800">
            <div className="px-3 py-2 bg-zinc-900/30">
              <div className="text-[10px] font-medium text-zinc-500 uppercase tracking-wide">
                Recent Notifications
              </div>
            </div>
            <div className="divide-y divide-zinc-800">
              {notifications.slice(0, 5).map((notif) => (
                <NotificationItem
                  key={notif.id}
                  notification={notif}
                  onRemove={() => removeNotification(notif.id)}
                />
              ))}
            </div>
          </div>
        )}

        {/* Alerts Section */}
        <div>
          {filteredAlerts.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-zinc-600">
              <Icon name="bell" size="sm" className="w-12 h-12 mb-3 opacity-50" />
              <p className="text-sm">No alerts</p>
              <button
                onClick={() => setShowCreateAlert(true)}
                className="mt-3 px-3 py-1.5 text-xs bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 border border-emerald-500/20 rounded font-medium transition-colors"
              >
                Create Alert
              </button>
            </div>
          ) : (
            <div className="divide-y divide-zinc-800">
              {filteredAlerts.map((alert) => (
                <AlertItem key={alert.id} alert={alert} onRemove={() => removeAlert(alert.id)} />
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Create Alert Modal */}
      {showCreateAlert && (
        <CreateAlertModal onClose={() => setShowCreateAlert(false)} onCreate={(alert) => {
          setAlerts((prev) => [alert, ...prev]);
          setShowCreateAlert(false);
        }} />
      )}
    </div>
  );
};

// Notification Item Component
const NotificationItem = ({
  notification,
  onRemove,
}: {
  notification: Notification;
  onRemove: () => void;
}) => {
  const icons = {
    SUCCESS: <Icon name="check-circle" size="sm" className="w-4 h-4 text-emerald-400" />,
    ERROR: <Icon name="alert-triangle" size="sm" className="w-4 h-4 text-red-400" />,
    WARNING: <Icon name="alert-triangle" size="sm" className="w-4 h-4 text-yellow-400" />,
    INFO: <Icon name="info" size="sm" className="w-4 h-4 text-blue-400" />,
  };

  const colors = {
    SUCCESS: 'border-emerald-500/20 bg-emerald-500/5',
    ERROR: 'border-red-500/20 bg-red-500/5',
    WARNING: 'border-yellow-500/20 bg-yellow-500/5',
    INFO: 'border-zinc-600/20 bg-zinc-800/30',
  };

  return (
    <div className={`px-3 py-2 border-l-2 ${colors[notification.type]} group`}>
      <div className="flex items-start gap-2">
        <div className="flex-shrink-0 mt-0.5">{icons[notification.type]}</div>
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2">
            <div className="text-xs font-medium text-white">{notification.title}</div>
            <button
              onClick={onRemove}
              className="flex-shrink-0 opacity-0 group-hover:opacity-100 p-0.5 hover:bg-zinc-800 rounded transition-all"
            >
              <Icon name="x-close" size="xs" className="text-zinc-500" />
            </button>
          </div>
          <p className="text-[10px] text-zinc-400 mt-0.5">{notification.message}</p>
          <div className="flex items-center gap-2 mt-1">
            <Icon name="clock" size="xs" className="text-zinc-600" />
            <span className="text-[10px] text-zinc-600">
              {new Date(notification.timestamp).toLocaleTimeString()}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

// Alert Item Component
const AlertItem = ({ alert, onRemove }: { alert: Alert; onRemove: () => void }) => {
  const isPriceAlert = alert.type === 'PRICE';
  const priceAlert = isPriceAlert ? (alert as PriceAlert) : null;

  const statusColors = {
    ACTIVE: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20',
    TRIGGERED: 'text-blue-400 bg-zinc-700/20 border-zinc-600/20',
    EXPIRED: 'text-zinc-500 bg-zinc-800/10 border-zinc-700/20',
    CANCELLED: 'text-red-400 bg-red-500/10 border-red-500/20',
  };

  const priorityIcons = {
    LOW: <Icon name="info" size="xs" className="text-zinc-500" />,
    MEDIUM: <Icon name="bell" size="xs" className="text-blue-400" />,
    HIGH: <Icon name="alert-triangle" size="xs" className="text-yellow-400" />,
    CRITICAL: <Icon name="alert-triangle" size="xs" className="text-red-400" />,
  };

  return (
    <div className="px-3 py-2 hover:bg-zinc-800/50 transition-colors group">
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-start gap-2 flex-1">
          <div className="mt-0.5">{priorityIcons[alert.priority]}</div>
          <div className="flex-1 min-w-0">
            {priceAlert ? (
              <>
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-sm font-medium text-white">{priceAlert.symbol}</span>
                  <span
                    className={`px-1.5 py-0.5 text-[10px] font-medium rounded border ${
                      statusColors[priceAlert.status]
                    }`}
                  >
                    {priceAlert.status}
                  </span>
                </div>
                <div className="flex items-center gap-2 text-xs text-zinc-400">
                  {priceAlert.condition === 'ABOVE' || priceAlert.condition === 'CROSSES_UP' ? (
                    <Icon name="trending-up" size="xs" className="text-emerald-400" />
                  ) : (
                    <Icon name="trending-down" size="xs" className="text-red-400" />
                  )}
                  <span>
                    {priceAlert.condition.replace('_', ' ')} {priceAlert.targetPrice.toFixed(5)}
                  </span>
                </div>
                {priceAlert.currentPrice && (
                  <div className="text-[10px] text-zinc-600 mt-1">
                    Current: {priceAlert.currentPrice.toFixed(5)}
                  </div>
                )}
              </>
            ) : (
              <>
                <div className="text-sm font-medium text-white mb-0.5">{alert.title}</div>
                <div className="text-xs text-zinc-400">{alert.message}</div>
              </>
            )}
            <div className="flex items-center gap-2 mt-1.5 text-[10px] text-zinc-600">
              <Icon name="clock" size="xs" />
              <span>{new Date(alert.createdAt).toLocaleString()}</span>
            </div>
          </div>
        </div>
        <button
          onClick={onRemove}
          className="flex-shrink-0 opacity-0 group-hover:opacity-100 p-1 hover:bg-zinc-800 rounded transition-all"
        >
          <Icon name="x-close" size="sm" className="text-zinc-500" />
        </button>
      </div>
    </div>
  );
};

// Create Alert Modal Component
const CreateAlertModal = ({
  onClose,
  onCreate,
}: {
  onClose: () => void;
  onCreate: (alert: Alert) => void;
}) => {
  const [symbol, setSymbol] = useState('');
  const [condition, setCondition] = useState<PriceAlert['condition']>('ABOVE');
  const [targetPrice, setTargetPrice] = useState('');
  const [priority, setPriority] = useState<AlertPriority>('MEDIUM');

  const handleCreate = () => {
    if (!symbol || !targetPrice) return;

    const alert: PriceAlert = {
      id: `alert-${Date.now()}`,
      symbol,
      type: 'PRICE',
      condition,
      targetPrice: parseFloat(targetPrice),
      status: 'ACTIVE',
      priority,
      createdAt: new Date().toISOString(),
    };

    onCreate(alert);
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
      <div className="bg-zinc-900 border border-zinc-700 rounded-lg p-6 w-96 shadow-xl">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-bold text-white">Create Price Alert</h3>
          <button onClick={onClose} className="p-1 hover:bg-zinc-800 rounded transition-colors">
            <Icon name="x-close" size="lg" className="text-zinc-500" />
          </button>
        </div>

        <div className="space-y-3">
          <div>
            <label className="block text-xs text-zinc-400 mb-1">Symbol</label>
            <input
              type="text"
              value={symbol}
              onChange={(e) => setSymbol(e.target.value.toUpperCase())}
              placeholder="EURUSD"
              className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded text-white focus:outline-none focus:border-emerald-500"
            />
          </div>

          <div>
            <label className="block text-xs text-zinc-400 mb-1">Condition</label>
            <select
              value={condition}
              onChange={(e) => setCondition(e.target.value as PriceAlert['condition'])}
              className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded text-white focus:outline-none focus:border-emerald-500"
            >
              <option value="ABOVE">Price Above</option>
              <option value="BELOW">Price Below</option>
              <option value="CROSSES_UP">Crosses Up</option>
              <option value="CROSSES_DOWN">Crosses Down</option>
            </select>
          </div>

          <div>
            <label className="block text-xs text-zinc-400 mb-1">Target Price</label>
            <input
              type="number"
              step="0.00001"
              value={targetPrice}
              onChange={(e) => setTargetPrice(e.target.value)}
              placeholder="1.08500"
              className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded text-white focus:outline-none focus:border-emerald-500"
            />
          </div>

          <div>
            <label className="block text-xs text-zinc-400 mb-1">Priority</label>
            <select
              value={priority}
              onChange={(e) => setPriority(e.target.value as AlertPriority)}
              className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded text-white focus:outline-none focus:border-emerald-500"
            >
              <option value="LOW">Low</option>
              <option value="MEDIUM">Medium</option>
              <option value="HIGH">High</option>
              <option value="CRITICAL">Critical</option>
            </select>
          </div>
        </div>

        <div className="flex gap-2 mt-6">
          <button
            onClick={handleCreate}
            disabled={!symbol || !targetPrice}
            className="flex-1 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Create Alert
          </button>
          <button
            onClick={onClose}
            className="flex-1 px-4 py-2 bg-zinc-700 hover:bg-zinc-600 text-white rounded font-medium transition-colors"
          >
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
};

/**
 * Professional Depth of Market (Order Book)
 * Level 2 market depth with cumulative volume visualization and real-time updates
 */

import { Icon } from '../ui/Icon';
import { useState, useEffect, useMemo } from 'react';
import type { MarketDepth, MarketDepthEntry } from '../../types/trading';
import { buildApiUrl } from '../../config/api';

type DepthOfMarketProps = {
  symbol: string;
  depth?: 10 | 20 | 50;
};

export const DepthOfMarket = ({ symbol, depth = 20 }: DepthOfMarketProps) => {
  const [marketDepth, setMarketDepth] = useState<MarketDepth | null>(null);
  const [selectedDepth, setSelectedDepth] = useState<10 | 20 | 50>(depth);
  const [grouping, setGrouping] = useState<number>(1); // Price grouping (pips)
  const [showCumulative, setShowCumulative] = useState(true);

  // Fetch market depth data
  useEffect(() => {
    if (!symbol) return;

    const fetchDepth = async () => {
      try {
        const response = await fetch(
          buildApiUrl(`/api/market-depth?symbol=${symbol}&depth=${selectedDepth}`)
        );

        if (response.ok) {
          const data = await response.json();
          setMarketDepth(data);
        } else {
          // TODO: API endpoint not available - no fallback data
          setMarketDepth(null);
        }
      } catch (error) {
        console.error('Failed to fetch market depth:', error);
        // TODO: API call failed - no fallback data
        setMarketDepth(null);
      }
    };

    fetchDepth();
    const interval = setInterval(fetchDepth, 1000);

    return () => clearInterval(interval);
  }, [symbol, selectedDepth]);

  // Calculate max volume for visualization
  const maxVolume = useMemo(() => {
    if (!marketDepth) return 0;
    const allVolumes = [...marketDepth.bids, ...marketDepth.asks].map((e) => e.volume);
    return Math.max(...allVolumes, 0);
  }, [marketDepth]);

  // Group price levels if needed
  const groupedBids = useMemo(() => {
    if (!marketDepth || grouping === 1) return marketDepth?.bids || [];

    return groupPriceLevels(marketDepth.bids, grouping, 'bid');
  }, [marketDepth, grouping]);

  const groupedAsks = useMemo(() => {
    if (!marketDepth || grouping === 1) return marketDepth?.asks || [];

    return groupPriceLevels(marketDepth.asks, grouping, 'ask');
  }, [marketDepth, grouping]);

  if (!marketDepth) {
    return (
      <div className="flex items-center justify-center h-full bg-zinc-900 text-zinc-500">
        <Icon name="layers" size="sm" className="w-6 h-6 animate-pulse mr-2" />
        <span>Loading depth...</span>
      </div>
    );
  }

  const midPrice = (marketDepth.bids[0]?.price + marketDepth.asks[0]?.price) / 2;

  return (
    <div className="flex flex-col h-full bg-zinc-900">
      {/* Header */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-zinc-800 bg-zinc-900/50">
        <div>
          <div className="flex items-center gap-2">
            <Icon name="layers" size="sm" className="w-4 h-4 text-emerald-400" />
            <h3 className="text-xs font-semibold text-zinc-300 uppercase tracking-wide">Depth of Market</h3>
          </div>
          <p className="text-[10px] text-zinc-500 mt-0.5">{symbol}</p>
        </div>

        <div className="flex items-center gap-2">
          <select
            value={selectedDepth}
            onChange={(e) => setSelectedDepth(Number(e.target.value) as 10 | 20 | 50)}
            className="px-2 py-1 text-[10px] bg-zinc-800 border border-zinc-700 rounded text-zinc-300 focus:outline-none focus:border-emerald-500"
          >
            <option value={10}>10 Levels</option>
            <option value={20}>20 Levels</option>
            <option value={50}>50 Levels</option>
          </select>
        </div>
      </div>

      {/* Spread Info */}
      <div className="px-3 py-2 border-b border-zinc-800 bg-zinc-900/30">
        <div className="grid grid-cols-3 gap-4 text-xs">
          <div>
            <div className="text-[10px] text-zinc-500 mb-0.5">Spread</div>
            <div className="font-mono text-zinc-300">{marketDepth.spread.toFixed(5)}</div>
          </div>
          <div>
            <div className="text-[10px] text-zinc-500 mb-0.5">Pips</div>
            <div className="font-mono text-zinc-300">{marketDepth.spreadPips.toFixed(1)}</div>
          </div>
          <div>
            <div className="text-[10px] text-zinc-500 mb-0.5">Mid Price</div>
            <div className="font-mono text-emerald-400">{midPrice.toFixed(5)}</div>
          </div>
        </div>
      </div>

      {/* Controls */}
      <div className="flex items-center justify-between px-3 py-1.5 border-b border-zinc-800 bg-zinc-900/20 text-[10px]">
        <button
          onClick={() => setShowCumulative(!showCumulative)}
          className={`px-2 py-1 rounded font-medium transition-colors ${showCumulative
            ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30'
            : 'bg-zinc-800 text-zinc-500 hover:text-zinc-300'
            }`}
        >
          Cumulative
        </button>

        <div className="flex items-center gap-1">
          <span className="text-zinc-500">Group:</span>
          <select
            value={grouping}
            onChange={(e) => setGrouping(Number(e.target.value))}
            className="px-1.5 py-0.5 bg-zinc-800 border border-zinc-700 rounded text-zinc-300 focus:outline-none"
          >
            <option value={1}>1 pip</option>
            <option value={5}>5 pips</option>
            <option value={10}>10 pips</option>
          </select>
        </div>
      </div>

      {/* Column Headers */}
      <div className="grid grid-cols-3 gap-2 px-3 py-1.5 border-b border-zinc-800 bg-zinc-900/30 text-[10px] font-medium text-zinc-500 uppercase tracking-wide">
        <div className="text-right">Price</div>
        <div className="text-right">Volume</div>
        <div className="text-right">{showCumulative ? 'Total' : 'Orders'}</div>
      </div>

      {/* Order Book */}
      <div className="flex-1 overflow-y-auto">
        {/* Asks (Sell Orders) - Reversed */}
        <div className="border-b-2 border-red-500/20">
          {[...groupedAsks].reverse().map((ask, index) => (
            <DepthRow
              key={`ask-${index}`}
              entry={ask}
              maxVolume={maxVolume}
              side="ask"
              showCumulative={showCumulative}
            />
          ))}
        </div>

        {/* Current Spread Indicator */}
        <div className="sticky top-0 z-10 bg-zinc-900 border-y border-zinc-700 shadow-lg">
          <div className="flex items-center justify-between px-3 py-2">
            <div className="flex items-center gap-2">
              <Icon name="trending-down" size="sm" className="w-4 h-4 text-red-400" />
              <div>
                <div className="text-[10px] text-zinc-500">Best Bid</div>
                <div className="text-sm font-mono font-bold text-red-400">
                  {marketDepth.bids[0]?.price.toFixed(5)}
                </div>
              </div>
            </div>

            <div className="text-center">
              <div className="text-[10px] text-zinc-500">Spread</div>
              <div className="text-xs font-mono text-zinc-400">
                {marketDepth.spreadPips.toFixed(1)} pips
              </div>
            </div>

            <div className="flex items-center gap-2">
              <div className="text-right">
                <div className="text-[10px] text-zinc-500">Best Ask</div>
                <div className="text-sm font-mono font-bold text-emerald-400">
                  {marketDepth.asks[0]?.price.toFixed(5)}
                </div>
              </div>
              <Icon name="trending-up" size="sm" className="w-4 h-4 text-emerald-400" />
            </div>
          </div>
        </div>

        {/* Bids (Buy Orders) */}
        <div className="border-t-2 border-emerald-500/20">
          {groupedBids.map((bid, index) => (
            <DepthRow
              key={`bid-${index}`}
              entry={bid}
              maxVolume={maxVolume}
              side="bid"
              showCumulative={showCumulative}
            />
          ))}
        </div>
      </div>

      {/* Footer Stats */}
      <div className="flex items-center justify-between px-3 py-2 border-t border-zinc-800 bg-zinc-900/50 text-[10px]">
        <div className="flex items-center gap-1">
          <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
          <span className="text-zinc-500">Bid Total:</span>
          <span className="font-mono text-emerald-400">
            {formatVolume(groupedBids.reduce((sum, b) => sum + b.volume, 0))}
          </span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-2 h-2 rounded-full bg-red-500"></div>
          <span className="text-zinc-500">Ask Total:</span>
          <span className="font-mono text-red-400">
            {formatVolume(groupedAsks.reduce((sum, a) => sum + a.volume, 0))}
          </span>
        </div>
      </div>
    </div>
  );
};

// Depth Row Component
const DepthRow = ({
  entry,
  maxVolume,
  side,
  showCumulative,
}: {
  entry: MarketDepthEntry;
  maxVolume: number;
  side: 'bid' | 'ask';
  showCumulative: boolean;
}) => {
  const percentage = maxVolume > 0 ? (entry.volume / maxVolume) * 100 : 0;
  const textColor = side === 'bid' ? 'text-emerald-400' : 'text-red-400';
  const barColor = side === 'bid' ? 'bg-emerald-500/30' : 'bg-red-500/30';

  return (
    <div className={`relative group hover:bg-zinc-800/50 transition-colors`}>
      {/* Volume bar background */}
      <div
        className={`absolute ${side === 'bid' ? 'right-0' : 'left-0'} top-0 h-full ${barColor} transition-all duration-300`}
        style={{ width: `${percentage}%` }}
      />

      {/* Content */}
      <div className="relative grid grid-cols-3 gap-2 px-3 py-1.5 text-xs">
        <div className={`font-mono ${textColor} font-medium text-right`}>
          {entry.price.toFixed(5)}
        </div>
        <div className="text-right font-mono text-zinc-300">
          {formatVolume(entry.volume)}
        </div>
        <div className="text-right font-mono text-zinc-500 text-[10px]">
          {showCumulative ? formatVolume(entry.cumulative) : (entry.orders || '-')}
        </div>
      </div>
    </div>
  );
};

// Utility Functions
const formatVolume = (volume: number): string => {
  if (volume >= 1000000) {
    return `${(volume / 1000000).toFixed(2)}M`;
  }
  if (volume >= 1000) {
    return `${(volume / 1000).toFixed(2)}K`;
  }
  return volume.toFixed(2);
};

const groupPriceLevels = (
  levels: MarketDepthEntry[],
  grouping: number,
  side: 'bid' | 'ask'
): MarketDepthEntry[] => {
  const pipValue = 0.0001;
  const groupSize = grouping * pipValue;

  const grouped = new Map<number, MarketDepthEntry>();

  levels.forEach((level) => {
    const groupKey =
      side === 'bid'
        ? Math.floor(level.price / groupSize) * groupSize
        : Math.ceil(level.price / groupSize) * groupSize;

    const existing = grouped.get(groupKey);

    if (existing) {
      existing.volume += level.volume;
      existing.cumulative += level.volume;
      existing.orders = (existing.orders || 0) + (level.orders || 1);
    } else {
      grouped.set(groupKey, {
        price: groupKey,
        volume: level.volume,
        cumulative: level.cumulative,
        orders: level.orders || 1,
      });
    }
  });

  return Array.from(grouped.values()).sort((a, b) =>
    side === 'bid' ? b.price - a.price : a.price - b.price
  );
};

