      <span>{label}</span>
      <Icon name="sort" size="xs"
        className={`transition-all ${isActive ? 'text-emerald-400' : 'text-zinc-600'} ${
          isActive && sortConfig.direction === 'desc' ? 'rotate-180' : ''
