      </div>

      <div
        className={`flex items-center justify-center gap-1 w-14 ${isReal ? 'text-emerald-400' : 'text-red-400'}`}
        title={isReal ? 'Γ£ô Real market data from YOFX broker' : 'ΓÜá∩╕Å Simulated data - not real market prices'}
      >
        {isReal ? (
          <Icon name="check-circle" size="sm" className="w-3 h-3" />
        ) : (
          <Icon name="alert-triangle" size="sm" className="w-3 h-3" />
        )}
        <span className="text-[9px] font-bold uppercase">{lpValue}</span>
      </div>

      <div className="text-right font-mono text-zinc-300">
        {formatPrice(item.bid, item.symbol)}
      </div>

      <div className={`text-right font-mono font-medium ${changeColor}`}>
        {item.changePercent >= 0 ? '+' : ''}
        {item.changePercent.toFixed(2)}%
      </div>
    </div>
  );
};

// Context Menu Component
const ContextMenu = ({
  position,
  items,
  onClose,
  ref,
}: {
  position: ContextMenuPosition;
  items: ContextMenuItem[];
  onClose: () => void;
  ref: React.RefObject<HTMLDivElement>;
}) => {
  return (
    <div
      ref={ref}
      className="fixed bg-zinc-900 border border-zinc-700 rounded-lg shadow-xl py-1 z-50 min-w-[180px]"
      style={{ top: position.y, left: position.x }}
    >
      {items.map((item, index) => (
        <button
          key={index}
          onClick={item.onClick}
          disabled={item.disabled}
          className="w-full flex items-center gap-2 px-3 py-2 text-xs text-zinc-300 hover:bg-zinc-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          {item.icon && <span className="flex-shrink-0">{item.icon}</span>}
          <span className="flex-1 text-left">{item.label}</span>
          {item.shortcut && <span className="text-zinc-500 text-[10px]">{item.shortcut}</span>}
        </button>
      ))}
    </div>
  );
};

// Utility function
const formatPrice = (price: number, symbol: string): string => {
  if (symbol.includes('JPY')) {
    return price.toFixed(3);
  }
  return price.toFixed(5);
};

