/**
 * Time & Sales Ticker
 * Scrolling tape of recent trades with buy/sell color coding and aggregated volume
 */

import { Icon } from '../ui/Icon';
import { useState, useEffect, useRef, useMemo } from 'react';
import type { TimeSalesEntry } from '../../types/trading';
import { useWebSocket } from '../../hooks/useWebSocket';
import { TrendingUp, TrendingDown } from 'lucide-react';

type TimeSalesProps = {
  symbol: string;
  maxEntries?: number;
};

export const TimeSales = ({ symbol, maxEntries = 100 }: TimeSalesProps) => {
  const [entries, setEntries] = useState<TimeSalesEntry[]>([]);
  const [filter, setFilter] = useState<'ALL' | 'BUY' | 'SELL'>('ALL');
  const [isPaused, setIsPaused] = useState(false);
  const listRef = useRef<HTMLDivElement>(null);

  // Use centralized WebSocket connection
  const {
    data: wsData,
    isConnected,
    connectionState,
    isStale,
    reconnect,
  } = useWebSocket<{ type: string; symbol: string; price: number; volume: number; side: string; timestamp: number; aggressor?: string }>({
    channel: `timesales:${symbol}`,
    autoConnect: true,
  });

  // Auto-scroll to latest entry
  useEffect(() => {
    if (!isPaused && listRef.current) {
      listRef.current.scrollTop = 0;
    }
  }, [entries, isPaused]);

  // Handle WebSocket data updates
  useEffect(() => {
    if (!wsData || wsData.type !== 'time_sales') return;

    const entry: TimeSalesEntry = {
      id: `${wsData.timestamp}-${Math.random()}`,
      symbol: wsData.symbol,
      price: wsData.price,
      volume: wsData.volume,
      side: wsData.side as 'BUY' | 'SELL',
      timestamp: wsData.timestamp,
      aggressor: wsData.aggressor as 'BUYER' | 'SELLER' | undefined,
    };

    setEntries((prev) => {
      const updated = [entry, ...prev];
      return updated.slice(0, maxEntries);
    });
  }, [wsData, maxEntries]);

  // Filter entries
  const filteredEntries = useMemo(() => {
    if (filter === 'ALL') return entries;
    return entries.filter((entry) => entry.side === filter);
  }, [entries, filter]);

  // Calculate aggregated volume
  const volumeStats = useMemo(() => {
    const buyVolume = entries.filter((e) => e.side === 'BUY').reduce((sum, e) => sum + e.volume, 0);
    const sellVolume = entries.filter((e) => e.side === 'SELL').reduce((sum, e) => sum + e.volume, 0);
    const totalVolume = buyVolume + sellVolume;

    return {
      buyVolume,
      sellVolume,
      totalVolume,
      buyPercent: totalVolume > 0 ? (buyVolume / totalVolume) * 100 : 50,
      sellPercent: totalVolume > 0 ? (sellVolume / totalVolume) * 100 : 50,
    };
  }, [entries]);

  return (
    <div className="flex flex-col h-full bg-zinc-900 border-r border-zinc-800">
      {/* Header */}
      <div className="px-3 py-2 border-b border-zinc-800 bg-zinc-900/50">
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center gap-2">
            <Icon name="activity" size="sm" className="w-4 h-4 text-emerald-400" />
            <h3 className="text-xs font-semibold text-zinc-300 uppercase tracking-wide">Time & Sales</h3>
            {/* Connection Status Indicator */}
            {connectionState === 'connected' ? (
              <span title={isStale ? 'Connection stale' : 'Connected'}>
                <Icon name="wifi" size="sm" className={`w-3 h-3 ${isStale ? 'text-yellow-500' : 'text-emerald-500'}`} />
              </span>
            ) : (
              <span title={connectionState === 'connecting' ? 'Connecting...' : 'Disconnected'}>
                <Icon name="disconnected" size="sm"
                  className={`w-3 h-3 ${connectionState === 'connecting' ? 'text-blue-500 animate-pulse' : 'text-red-500'}`}
                />
              </span>
            )}
          </div>
          <div className="flex items-center gap-2">
            {!isConnected && (
              <button
                onClick={reconnect}
                className="px-2 py-1 text-[10px] font-medium rounded bg-zinc-700/30 text-zinc-400 border border-zinc-600/30 hover:bg-zinc-700/40"
                title="Reconnect"
              >
                RECONNECT
              </button>
            )}
            <button
              onClick={() => setIsPaused(!isPaused)}
              className={`px-2 py-1 text-[10px] font-medium rounded transition-colors ${isPaused
                ? 'bg-yellow-500/20 text-yellow-400 border border-yellow-500/30'
                : 'bg-zinc-800 text-zinc-400 hover:text-zinc-200'
                }`}
            >
              {isPaused ? 'PAUSED' : 'LIVE'}
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="flex gap-1">
          {(['ALL', 'BUY', 'SELL'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`flex-1 px-2 py-1 text-[10px] font-medium rounded transition-colors ${filter === f
                ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30'
                : 'bg-zinc-800/50 text-zinc-500 hover:text-zinc-300'
                }`}
            >
              {f}
            </button>
          ))}
        </div>
      </div>

      {/* Volume Statistics */}
      <div className="px-3 py-2 border-b border-zinc-800 bg-zinc-900/30">
        <div className="flex items-center justify-between text-[10px] mb-1">
          <div className="flex items-center gap-1">
            <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
            <span className="text-zinc-500">Buy</span>
            <span className="font-mono text-emerald-400 ml-1">{volumeStats.buyVolume.toFixed(2)}</span>
          </div>
          <div className="flex items-center gap-1">
            <span className="font-mono text-red-400 mr-1">{volumeStats.sellVolume.toFixed(2)}</span>
            <span className="text-zinc-500">Sell</span>
            <div className="w-2 h-2 rounded-full bg-red-500"></div>
          </div>
        </div>
        <div className="h-1.5 bg-zinc-800 rounded-full overflow-hidden flex">
          <div
            className="bg-emerald-500 transition-all duration-300"
            style={{ width: `${volumeStats.buyPercent}%` }}
          ></div>
          <div
            className="bg-red-500 transition-all duration-300"
            style={{ width: `${volumeStats.sellPercent}%` }}
          ></div>
        </div>
      </div>

      {/* Column Headers */}
      <div className="grid grid-cols-[auto_1fr_1fr_1fr] gap-2 px-3 py-1.5 border-b border-zinc-800 bg-zinc-900/30 text-[10px] font-medium text-zinc-500 uppercase tracking-wide sticky top-0">
        <div className="w-4"></div>
        <div>Time</div>
        <div className="text-right">Price</div>
        <div className="text-right">Vol</div>
      </div>

      {/* Entries List */}
      <div ref={listRef} className="flex-1 overflow-y-auto">
        {filteredEntries.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-zinc-600">
            <Icon name="clock" size="sm" className="w-8 h-8 mb-2" />
            <p className="text-xs">No trades yet</p>
          </div>
        ) : (
          filteredEntries.map((entry) => (
            <TimeSalesRow key={entry.id} entry={entry} />
          ))
        )}
      </div>

      {/* Footer Stats */}
      <div className="px-3 py-2 border-t border-zinc-800 bg-zinc-900/50 text-[10px] text-zinc-500">
        <div className="flex items-center justify-between">
          <span>Total Trades</span>
          <span className="font-mono text-zinc-300">{entries.length}</span>
        </div>
      </div>
    </div>
  );
};

// Time & Sales Row Component
const TimeSalesRow = ({ entry }: { entry: TimeSalesEntry }) => {
  const isBuy = entry.side === 'BUY';
  const bgColor = isBuy ? 'bg-emerald-500/5 hover:bg-emerald-500/10' : 'bg-red-500/5 hover:bg-red-500/10';
  const sideColor = isBuy ? 'text-emerald-400' : 'text-red-400';
  const borderColor = isBuy ? 'border-emerald-500' : 'border-red-500';

  const time = new Date(entry.timestamp).toLocaleTimeString('en-US', {
    hour12: false,
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });

  const SideIcon = isBuy ? TrendingUp : TrendingDown;

  return (
    <div
      className={`grid grid-cols-[auto_1fr_1fr_1fr] gap-2 px-3 py-1.5 border-l-2 ${borderColor} ${bgColor} transition-colors text-xs`}
    >
      <div className="flex items-center justify-center w-4">
        <SideIcon className={`w-3 h-3 ${sideColor}`} />
      </div>
      <div className="font-mono text-zinc-500 text-[10px]">{time}</div>
      <div className={`text-right font-mono ${sideColor} font-medium`}>
        {entry.price.toFixed(5)}
      </div>
      <div className="text-right font-mono text-zinc-400 text-[10px]">
        {entry.volume.toFixed(2)}
      </div>
    </div>
  );
};

/**
 * Notification Preferences Panel
 * Detailed notification settings for all categories
 */

import { Icon } from '../ui/Icon';
import React from 'react';
import {
  useSettingsStore,
  type CategorySettings,
  type NotificationSound,
  type NotificationPriority,
  type HistoryRetention,
} from '../../store/useSettingsStore';
import { useNotificationStore } from '../../store/useNotificationStore';

interface NotificationCategory {
  id: string;
  label: string;
  description: string;
  icon: React.ReactNode;
}

const CATEGORIES: NotificationCategory[] = [
  {
    id: 'tradeExecution' as any,
    label: 'Trade Execution',
    description: 'Order filled, position opened/closed',
    icon: <Icon name="trending-up" size="md" />,
  },
  {
    id: 'priceAlerts' as any,
    label: 'Price Alerts',
    description: 'Triggered alerts from Alert Manager',
    icon: <Icon name="bell" size="md" />,
  },
  {
    id: 'marginWarnings' as any,
    label: 'Margin Warnings',
    description: 'Margin call, stop-out approaching',
    icon: <Icon name="alert-triangle" size="md" />,
  },
  {
    id: 'system' as any,
    label: 'System',
    description: 'Connection lost, reconnected, maintenance',
    icon: <Icon name="wifi" size="md" />,
  },
  {
    id: 'news' as any,
    label: 'News',
    description: 'High-impact economic events',
    icon: <Icon name="newspaper" size="md" />,
  },
  {
    id: 'account' as any,
    label: 'Account',
    description: 'Deposits, withdrawals, balance changes',
    icon: <Icon name="user" size="md" />,
  },
];

const SOUND_OPTIONS: { value: NotificationSound; label: string }[] = [
  { value: 'default', label: 'Default' },
  { value: 'chime', label: 'Chime' },
  { value: 'alert', label: 'Alert' },
  { value: 'silent', label: 'Silent' },
];

const PRIORITY_OPTIONS: { value: NotificationPriority; label: string; color: string }[] = [
  { value: 'low', label: 'Low', color: 'text-gray-400' },
  { value: 'medium', label: 'Medium', color: 'text-blue-400' },
  { value: 'high', label: 'High', color: 'text-yellow-400' },
  { value: 'critical', label: 'Critical', color: 'text-rose-400' },
];

const HISTORY_RETENTION_OPTIONS: { value: HistoryRetention; label: string }[] = [
  { value: '1hr', label: '1 hour' },
  { value: '6hr', label: '6 hours' },
  { value: '24hr', label: '24 hours' },
  { value: '7d', label: '7 days' },
];

export function NotificationPreferences() {
  const notifications = useSettingsStore((state) => state.notifications);
  const updateNotificationsSettings = useSettingsStore((state) => state.updateNotificationsSettings);
  const clearAll = useNotificationStore((state) => state.clearAll);

  const updateCategorySettings = (
    categoryKey: keyof typeof notifications,
    settings: Partial<CategorySettings>
  ) => {
    updateNotificationsSettings({
      [categoryKey]: {
        ...(notifications[categoryKey] as CategorySettings),
        ...settings,
      },
    });
  };

  const handleClearAll = () => {
    if (window.confirm('Are you sure you want to clear all notifications?')) {
      clearAll();
    }
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-6">
        {/* Global Settings */}
        <div className="space-y-4">
          <h3 className="text-xs font-bold text-zinc-300 uppercase tracking-wider flex items-center gap-2">
            <Icon name="monitor" size="sm" />
            Global Settings
          </h3>

          <div className="bg-[#131316] border border-zinc-700 rounded p-4 space-y-4">
            {/* Do Not Disturb */}
            <div className="flex items-start justify-between">
              <div className="flex items-start gap-3 flex-1">
                <Icon name="settings" size="md" className="text-zinc-400 mt-0.5 flex-shrink-0" />
                <div className="flex-1">
                  <div className="text-sm text-zinc-200 font-medium">Do Not Disturb</div>
                  <div className="text-xs text-zinc-500 mt-0.5">
                    Mutes all non-critical notifications
                  </div>
                </div>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  checked={notifications.doNotDisturb}
                  onChange={(e) =>
                    updateNotificationsSettings({ doNotDisturb: e.target.checked })
                  }
                  className="sr-only peer"
                />
                <div className="w-9 h-5 bg-zinc-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full rtl:peer-checked:after:-translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:start-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-blue-600"></div>
              </label>
            </div>

            {/* DND Schedule */}
            <div className="flex items-start gap-3">
              <Icon name="clock" size="md" className="text-zinc-400 mt-2 flex-shrink-0" />
              <div className="flex-1 space-y-3">
                <div className="flex items-center justify-between">
                  <div className="text-sm text-zinc-200 font-medium">DND Schedule</div>
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      type="checkbox"
                      checked={notifications.dndSchedule.enabled}
                      onChange={(e) =>
                        updateNotificationsSettings({
                          dndSchedule: {
                            ...notifications.dndSchedule,
                            enabled: e.target.checked,
                          },
                        })
                      }
                      className="sr-only peer"
                    />
                    <div className="w-9 h-5 bg-zinc-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full rtl:peer-checked:after:-translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:start-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-blue-600"></div>
                  </label>
                </div>
                {notifications.dndSchedule.enabled && (
                  <div className="flex items-center gap-3">
                    <div className="flex-1">
                      <label className="block text-xs text-zinc-500 mb-1">From</label>
                      <input
                        type="time"
                        value={notifications.dndSchedule.fromTime}
                        onChange={(e) =>
                          updateNotificationsSettings({
                            dndSchedule: {
                              ...notifications.dndSchedule,
                              fromTime: e.target.value,
                            },
                          })
                        }
                        className="w-full px-2 py-1.5 bg-[#252528] border border-zinc-700 rounded text-zinc-300 text-xs focus:outline-none focus:border-zinc-600"
                      />
                    </div>
                    <div className="flex-1">
                      <label className="block text-xs text-zinc-500 mb-1">To</label>
                      <input
                        type="time"
                        value={notifications.dndSchedule.toTime}
                        onChange={(e) =>
                          updateNotificationsSettings({
                            dndSchedule: {
                              ...notifications.dndSchedule,
                              toTime: e.target.value,
                            },
                          })
                        }
                        className="w-full px-2 py-1.5 bg-[#252528] border border-zinc-700 rounded text-zinc-300 text-xs focus:outline-none focus:border-zinc-600"
                      />
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Max Notifications Per Minute */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <label className="text-sm text-zinc-200 font-medium">
                  Max Notifications Per Minute
                </label>
                <span className="text-sm text-blue-400 font-mono">
                  {notifications.maxNotificationsPerMinute}
                </span>
              </div>
              <input
                type="range"
                min="1"
                max="20"
                value={notifications.maxNotificationsPerMinute}
                onChange={(e) =>
                  updateNotificationsSettings({
                    maxNotificationsPerMinute: parseInt(e.target.value),
                  })
                }
                className="w-full h-2 bg-zinc-700 rounded-lg appearance-none cursor-pointer accent-blue-600"
              />
            </div>

            {/* History Retention */}
            <div className="space-y-2">
              <label className="block text-sm text-zinc-200 font-medium">
                Notification History Retention
              </label>
              <select
                value={notifications.historyRetention}
                onChange={(e) =>
                  updateNotificationsSettings({
                    historyRetention: e.target.value as HistoryRetention,
                  })
                }
                className="w-full px-3 py-2 bg-[#252528] border border-zinc-700 rounded text-zinc-300 text-sm focus:outline-none focus:border-zinc-600"
              >
                {HISTORY_RETENTION_OPTIONS.map((option) => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Clear All Button */}
            <button
              onClick={handleClearAll}
              className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-rose-600/20 hover:bg-rose-600/30 text-rose-400 border border-rose-600/30 rounded text-sm transition-colors"
            >
              <Icon name="trash" size="sm" />
              <span>Clear All Notifications</span>
            </button>
          </div>
        </div>

        {/* Notification Categories */}
        <div className="space-y-4">
          <h3 className="text-xs font-bold text-zinc-300 uppercase tracking-wider flex items-center gap-2">
            <Icon name="bell" size="sm" />
            Notification Categories
          </h3>

          <div className="space-y-3">
            {CATEGORIES.map((category) => {
              const categorySettings = notifications[
                category.id as keyof typeof notifications
              ] as CategorySettings;

              if (!categorySettings || typeof categorySettings !== 'object') {
                return null;
              }

              return (
                <div
                  key={category.id}
                  className="bg-[#131316] border border-zinc-700 rounded p-4"
                >
