                        className="sr-only peer"
                      />
                      <div className="w-9 h-5 bg-zinc-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full rtl:peer-checked:after:-translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:start-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-blue-600"></div>
                    </label>
                  </div>

                  {/* Category Settings */}
                  {categorySettings.enabled && (
                    <div className="space-y-3 pl-7">
                      {/* Show Popup */}
                      <label className="flex items-center gap-2 cursor-pointer">
                        <input
                          type="checkbox"
                          checked={categorySettings.showPopup}
                          onChange={(e) =>
                            updateCategorySettings(category.id as any, {
                              showPopup: e.target.checked,
                            })
                          }
                          className="w-4 h-4 text-blue-600 bg-zinc-700 border-zinc-600 rounded focus:ring-blue-500 focus:ring-2"
                        />
                        <span className="text-xs text-zinc-300">Show popup notification</span>
                      </label>

                      {/* Play Sound */}
                      <label className="flex items-center gap-2 cursor-pointer">
                        <input
                          type="checkbox"
                          checked={categorySettings.playSound}
                          onChange={(e) =>
                            updateCategorySettings(category.id as any, {
                              playSound: e.target.checked,
                            })
                          }
                          className="w-4 h-4 text-blue-600 bg-zinc-700 border-zinc-600 rounded focus:ring-blue-500 focus:ring-2"
                        />
                        <span className="text-xs text-zinc-300">Play sound</span>
                      </label>

                      {/* Sound Selector */}
                      {categorySettings.playSound && (
                        <div className="space-y-1">
                          <label className="block text-xs text-zinc-500">Sound</label>
                          <select
                            value={categorySettings.sound}
                            onChange={(e) =>
                              updateCategorySettings(category.id as any, {
                                sound: e.target.value as NotificationSound,
                              })
                            }
                            className="w-full px-2 py-1.5 bg-[#252528] border border-zinc-700 rounded text-zinc-300 text-xs focus:outline-none focus:border-zinc-600"
                          >
                            {SOUND_OPTIONS.map((option) => (
                              <option key={option.value} value={option.value}>
                                {option.label}
                              </option>
                            ))}
                          </select>
                        </div>
                      )}

                      {/* Priority Level */}
                      <div className="space-y-1">
                        <label className="block text-xs text-zinc-500">Priority Level</label>
                        <select
                          value={categorySettings.priority}
                          onChange={(e) =>
                            updateCategorySettings(category.id as any, {
                              priority: e.target.value as NotificationPriority,
                            })
                          }
                          className="w-full px-2 py-1.5 bg-[#252528] border border-zinc-700 rounded text-zinc-300 text-xs focus:outline-none focus:border-zinc-600"
                        >
                          {PRIORITY_OPTIONS.map((option) => (
                            <option key={option.value} value={option.value}>
                              {option.label}
                            </option>
                          ))}
                        </select>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

import { Icon } from '../ui/Icon';
import React, { useState, useEffect, useRef } from 'react';
import { useSettingsStore, type SettingsState } from '../../store/useSettingsStore';
import { useAppStore } from '../../store/useAppStore';
import { NotificationPreferences } from './NotificationPreferences';

interface OptionsDialogProps {
    isOpen: boolean;
    onClose: () => void;
}

type TabId = 'server' | 'charts' | 'trade' | 'automation' | 'events' | 'notifications' | 'email' | 'ftp' | 'community' | 'signals';

export const OptionsDialog: React.FC<OptionsDialogProps> = ({ isOpen, onClose }) => {
    const [activeTab, setActiveTab] = useState<TabId>('server');
    const snapshotRef = useRef<SettingsState | null>(null);

    const getSnapshot = useSettingsStore((state) => state.getSnapshot);
    const restoreSnapshot = useSettingsStore((state) => state.restoreSnapshot);

    // Capture snapshot when dialog opens
    useEffect(() => {
        if (isOpen) {
            snapshotRef.current = getSnapshot();
        }
    }, [isOpen, getSnapshot]);

    // Handle Cancel - revert to snapshot
    const handleCancel = () => {
        if (snapshotRef.current) {
            restoreSnapshot(snapshotRef.current);
        }
        onClose();
    };

    // Handle OK - just close (settings already persisted)
    const handleOK = () => {
        onClose();
    };

    // Close on Escape
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape' && isOpen) handleCancel();
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen]);

    if (!isOpen) return null;

    const tabs: { id: TabId; label: string }[] = [
        { id: 'server', label: 'Server' },
        { id: 'charts', label: 'Charts' },
        { id: 'trade', label: 'Trade' },
        { id: 'automation', label: 'Automation & Bots' },
        { id: 'events', label: 'Events' },
        { id: 'notifications', label: 'Notifications' },
        { id: 'email', label: 'Email' },
        { id: 'ftp', label: 'FTP' },
        { id: 'community', label: 'Community' },
        { id: 'signals', label: 'Signals' },
    ];

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="w-[800px] h-[600px] bg-[#252528] rounded-lg shadow-2xl border border-zinc-700 flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">
                {/* Header */}
                <div className="h-10 bg-[#131316] border-b border-zinc-700 flex items-center justify-between px-4 select-none">
                    <span className="text-sm font-medium text-zinc-200">Options</span>
                    <button onClick={onClose} className="text-zinc-500 hover:text-white transition-colors">
                        <Icon name="x-close" size="md" />
                    </button>
                </div>

                {/* Tabs */}
                <div className="bg-[#131316] border-b border-zinc-700 px-2 flex items-center gap-1 overflow-x-auto scrollbar-hide">
                    {tabs.map((tab) => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={`px-3 py-2 text-[12px] font-medium border-b-2 transition-all whitespace-nowrap
                                ${activeTab === tab.id
                                    ? 'border-zinc-600 text-blue-400'
                                    : 'border-transparent text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800/50'}`}
                        >
                            {tab.label}
                        </button>
                    ))}
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6 bg-[#252528]">
                    {activeTab === 'server' && <ServerTab />}
                    {activeTab === 'charts' && <ChartsTab />}
                    {activeTab === 'trade' && <TradeTab />}
                    {activeTab === 'automation' && <AutomationTab />}
                    {activeTab === 'events' && <PlaceholderTab icon={<Icon name="activity" size="xl" />} title="Events" desc="Configure sound notifications and system events." />}
                    {activeTab === 'notifications' && <NotificationPreferences />}
                    {activeTab === 'email' && <PlaceholderTab icon={<Icon name="mail" size="xl" />} title="Email" desc="SMTP server configuration for alerts." />}
                    {activeTab === 'ftp' && <PlaceholderTab icon={<Icon name="hard-drive" size="xl" />} title="FTP" desc="Automated report publishing settings." />}
                    {activeTab === 'community' && <PlaceholderTab icon={<Icon name="globe" size="xl" />} title="RTX5 Community" desc="Login to the proprietary RTX5 ecosystem." />}
                    {activeTab === 'signals' && <PlaceholderTab icon={<Icon name="wifi" size="xl" />} title="RTX5 Signals Hub" desc="Subscribe to institutional signal providers." />}
                </div>

                {/* Footer */}
                <div className="h-14 bg-[#131316] border-t border-zinc-700 flex items-center justify-end px-4 gap-3">
                    <button onClick={handleCancel} className="px-4 py-1.5 text-xs font-medium text-zinc-300 hover:bg-zinc-700 rounded transition-colors">
                        Cancel
                    </button>
                    <button onClick={handleOK} className="px-4 py-1.5 text-xs font-medium bg-zinc-700 hover:bg-zinc-600 text-white rounded transition-colors">
                        Apply
                    </button>
                    <button onClick={handleOK} className="px-4 py-1.5 text-xs font-medium bg-zinc-700 hover:bg-zinc-600 text-white rounded transition-colors shadow-sm">
                        OK
                    </button>
                </div>
            </div>
        </div>
    );
};

const ServerTab = () => {
    const server = useSettingsStore((state) => state.server);
    const updateServerSettings = useSettingsStore((state) => state.updateServerSettings);
    const accountId = useAppStore(state => state.accountId);

    return (
        <div className="space-y-6 text-xs text-zinc-300">
            <div className="grid grid-cols-[100px_1fr] gap-4 items-center">
                <label className="text-right text-zinc-400">Server:</label>
                <select
                    value={server.serverName}
                    onChange={(e) => updateServerSettings({ serverName: e.target.value })}
                    className="w-full bg-[#131316] border border-zinc-700 rounded px-2 py-1.5 outline-none focus:border-zinc-600"
                >
                    <option>FlexyMarkets-Server</option>
                    <option>FlexyMarkets-Demo</option>
                </select>

                <label className="text-right text-zinc-400">Login:</label>
                <input type="text" value={accountId || "Guest"} readOnly className="bg-[#131316] border border-zinc-700 rounded px-2 py-1.5 outline-none focus:border-zinc-600" />

                <label className="text-right text-zinc-400">Password:</label>
                <div className="flex gap-2">
                    <input type="password" value="********" readOnly className="flex-1 bg-[#131316] border border-zinc-700 rounded px-2 py-1.5 outline-none focus:border-zinc-600" />
                    <button className="px-3 py-1 bg-zinc-700 hover:bg-zinc-600 rounded text-zinc-200">Change</button>
                </div>
            </div>

            <div className="ml-[116px] space-y-3">
                <label className="flex items-center gap-2 cursor-pointer">
                    <input
                        type="checkbox"
                        checked={server.proxyEnabled}
                        onChange={(e) => updateServerSettings({ proxyEnabled: e.target.checked })}
                        className="rounded bg-zinc-700 border-zinc-600 text-blue-500 focus:ring-0 focus:ring-offset-0"
                    />
                    <span>Enable proxy server</span>
                    <button className="ml-auto px-3 py-0.5 bg-zinc-800 border border-zinc-700 rounded hover:bg-zinc-700">Proxy...</button>
