import { Icon } from './/Icon';
import { useState, useMemo } from 'react';
type Column<T> = {
  key: keyof T | string;
  header: string;
  render?: (value: any, row: T) => React.ReactNode;
  sortable?: boolean;
  width?: string;
  align?: 'left' | 'center' | 'right';
  className?: string;
};

type DataTableProps<T> = {
  data: T[];
  columns: Column<T>[];
  keyExtractor: (row: T) => string | number;
  onRowClick?: (row: T) => void;
  stickyHeader?: boolean;
  virtualized?: boolean;
  maxHeight?: string;
  className?: string;
};

export function DataTable<T extends Record<string, any>>({
  data,
  columns,
  keyExtractor,
  onRowClick,
  stickyHeader = true,
  maxHeight,
  className = ''
}: DataTableProps<T>) {
  const [sortColumn, setSortColumn] = useState<string | null>(null);
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');

  const sortedData = useMemo(() => {
    if (!sortColumn) return data;

    return [...data].sort((a, b) => {
      const aValue = a[sortColumn];
      const bValue = b[sortColumn];

      if (aValue === bValue) return 0;

      const comparison = aValue > bValue ? 1 : -1;
      return sortDirection === 'asc' ? comparison : -comparison;
    });
  }, [data, sortColumn, sortDirection]);

  const handleSort = (columnKey: string) => {
    if (sortColumn === columnKey) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      setSortColumn(columnKey);
      setSortDirection('asc');
    }
  };

  const getValue = (row: T, key: string) => {
    return key.split('.').reduce((obj, k) => obj?.[k], row as any);
  };

  return (
    <div
      className={`overflow-auto ${className}`}
      style={{ maxHeight }}
    >
      <table className="data-grid">
        <thead className={stickyHeader ? 'sticky top-0 z-10' : ''}>
          <tr>
            {columns.map((column) => (
              <th
                key={String(column.key)}
                style={{ width: column.width }}
                className={`
                  ${column.align === 'center' ? 'text-center' : column.align === 'right' ? 'text-right' : 'text-left'}
                  ${column.sortable ? 'cursor-pointer select-none hover:bg-zinc-700/50' : ''}
                  ${column.className || ''}
                `}
                onClick={() => column.sortable && handleSort(String(column.key))}
              >
                <div className="flex items-center gap-1 justify-between">
                  <span>{column.header}</span>
                  {column.sortable && (
                    <span className="text-zinc-600">
                      {sortColumn === column.key ? (
                        sortDirection === 'asc' ? (
                          <Icon name="arrow-up" size="xs" className="text-zinc-400" />
                        ) : (
                          <Icon name="arrow-down" size="xs" className="text-zinc-400" />
                        )
                      ) : (
                        <Icon name="arrow-up" size="xs" />
                      )}
                    </span>
                  )}
                </div>
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {sortedData.map((row) => (
            <tr
              key={keyExtractor(row)}
              onClick={() => onRowClick?.(row)}
              className={onRowClick ? 'cursor-pointer' : ''}
            >
              {columns.map((column) => {
                const value = getValue(row, String(column.key));
                return (
                  <td
                    key={String(column.key)}
                    className={`
                      ${column.align === 'center' ? 'text-center' : column.align === 'right' ? 'text-right' : 'text-left'}
                      ${column.className || ''}
                    `}
                  >
                    {column.render ? column.render(value, row) : value}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
      {sortedData.length === 0 && (
        <div className="p-8 text-center text-zinc-600 italic text-sm">
          No data available
        </div>
      )}
    </div>
  );
}

/**
 * Icon Component
 * 
 * Centralized, theme-aware icon component that renders icons from the registry.
 * All icons share a consistent visual style matching the DrawingToolbar:
 * - 16├ù16 viewBox
 * - Stroke-only (no fills)
 * - strokeWidth 1.5
 * - Round linecap/linejoin
 * - Monochrome with currentColor inheritance
 * 
 * @example
 * <Icon name="settings" />
 * <Icon name="trend-line" size="lg" className="text-blue-400" />
 * <Icon name="check" size="sm" state="active" />
 */

import React from 'react';
import { getIconPaths, type IconName } from './iconRegistry';

export type IconSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
export type IconState = 'default' | 'hover' | 'active' | 'disabled' | 'selected';

export interface IconProps {
    /** Registry key ΓÇö e.g. 'trend-line', 'settings', 'bell' */
    name: IconName;
    /** Preset size: xs=12, sm=14, md=16, lg=20, xl=24 */
    size?: IconSize | number;
    /** Additional CSS classes (color, spacing, etc.) */
    className?: string;
    /** Accessible tooltip text */
    title?: string;
    /** Visual state ΓÇö sets color automatically unless className overrides */
    state?: IconState;
    /** Inline style overrides */
    style?: React.CSSProperties;
    /** Click handler */
    onClick?: (e: React.MouseEvent) => void;
}

const SIZE_MAP: Record<IconSize, number> = {
    xs: 12,
    sm: 14,
    md: 20,
    lg: 24,
    xl: 28,
};

const STATE_CLASSES: Record<IconState, string> = {
    default: '',   // Inherit from parent via currentColor
    hover: 'text-zinc-200',
    active: 'text-blue-400',
    disabled: 'text-zinc-600 opacity-50',
    selected: 'text-blue-400',
};

export const Icon: React.FC<IconProps> = ({
    name,
    size = 'md',
    className = '',
    title,
    state,
    style,
    onClick,
}) => {
    const pixelSize = typeof size === 'number' ? size : SIZE_MAP[size];
    const paths = getIconPaths(name);

    if (!paths) {
        if (process.env.NODE_ENV === 'development') {
            console.warn(`[Icon] Unknown icon name: "${name}"`);
        }
        // Render a small placeholder square in dev
        return (
            <svg
                width={pixelSize}
                height={pixelSize}
                viewBox="0 0 16 16"
                fill="none"
                stroke="currentColor"
                strokeWidth={1.5}
                className={`inline-block ${className}`}
                aria-hidden="true"
            >
                <rect x="3" y="3" width="10" height="10" strokeDasharray="2 2" />
            </svg>
        );
    }

    const stateClasses = state ? STATE_CLASSES[state] : '';

    return (
        <svg
            width={pixelSize}
            height={pixelSize}
            viewBox="0 0 16 16"
            fill="none"
            stroke="currentColor"
            strokeWidth={1.5}
            strokeLinecap="round"
            strokeLinejoin="round"
            className={`inline-block flex-shrink-0 ${stateClasses} ${className}`.trim()}
            style={style}
            role={title ? 'img' : undefined}
            aria-label={title}
            aria-hidden={!title}
            onClick={onClick}
        >
            {title && <title>{title}</title>}
            {paths}
        </svg>
    );
};

/**
 * Re-export icon names for convenience
 */
export { iconNames, type IconName } from './iconRegistry';

export default Icon;

import { Icon } from './/Icon';
import { useEffect, useState } from 'react';
import { Command } from 'lucide-react';
type Shortcut = {
  key: string;
  description: string;
  action: () => void;
  category?: string;
};

type KeyboardShortcutsProps = {
  shortcuts: Shortcut[];
  enabled?: boolean;
};

export function KeyboardShortcuts({ shortcuts, enabled = true }: KeyboardShortcutsProps) {
  useEffect(() => {
    if (!enabled) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      const key = [
        e.ctrlKey && 'Ctrl',
        e.altKey && 'Alt',
        e.shiftKey && 'Shift',
        e.metaKey && 'Cmd',
        e.key.toUpperCase()
      ].filter(Boolean).join('+');

      const shortcut = shortcuts.find(s => s.key === key);
      if (shortcut) {
        e.preventDefault();
        shortcut.action();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [shortcuts, enabled]);

  return null;
}

export function KeyboardShortcutsModal({ shortcuts, onClose }: {
  shortcuts: Shortcut[];
  onClose: () => void;
}) {
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === '?' && e.shiftKey) {
        setIsOpen(!isOpen);
      }
      if (e.key === 'Escape' && isOpen) {
        setIsOpen(false);
      }
    };

    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [isOpen]);

  if (!isOpen) return null;

  // Group by category
  const grouped = shortcuts.reduce((acc, shortcut) => {
    const category = shortcut.category || 'General';
    if (!acc[category]) acc[category] = [];
    acc[category].push(shortcut);
    return acc;
  }, {} as Record<string, Shortcut[]>);

  return (
    <div
      className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[var(--z-modal)] flex items-center justify-center"
      onClick={() => setIsOpen(false)}
    >
      <div
        className="bg-[var(--bg-secondary)] border border-[var(--border-secondary)] rounded-lg shadow-xl max-w-2xl w-full max-h-[80vh] overflow-auto m-4"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="panel-header flex items-center justify-between sticky top-0 bg-[var(--bg-secondary)] z-10">
          <div className="flex items-center gap-2">
            <Command size={18} className="text-zinc-400" />
            <h2 className="text-lg font-semibold text-zinc-200">Keyboard Shortcuts</h2>
          </div>
          <button
            onClick={() => setIsOpen(false)}
            className="text-zinc-400 hover:text-zinc-200 text-sm"
          >
            ESC
          </button>
        </div>

        <div className="p-4 space-y-6">
          {Object.entries(grouped).map(([category, items]) => (
            <div key={category}>
              <h3 className="text-sm font-semibold text-zinc-400 mb-3 uppercase tracking-wide">
                {category}
              </h3>
              <div className="space-y-2">
                {items.map((shortcut, index) => (
                  <div
                    key={index}
                    className="flex items-center justify-between py-2 px-3 rounded hover:bg-zinc-800/50"
                  >
                    <span className="text-sm text-zinc-300">{shortcut.description}</span>
                    <kbd className="px-2 py-1 bg-zinc-800 border border-zinc-700 rounded text-xs font-mono text-zinc-300">
                      {shortcut.key.split('+').map((k, i, arr) => (
                        <span key={i}>
                          {k}
                          {i < arr.length - 1 && <span className="mx-1 text-zinc-600">+</span>}
                        </span>
                      ))}
                    </kbd>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>

        <div className="panel-header border-t border-zinc-800 text-center text-xs text-zinc-500">
          Press <kbd className="px-1 bg-zinc-800 rounded">?</kbd> to toggle this dialog
        </div>
      </div>
    </div>
  );
}

/**
 * PriceDisplay ΓÇö MT5-style price formatting
 * Shows last 2 decimal digits in a larger/bolder font,
 * matching the Flexy Markets MT5 terminal style.
 */
import React from 'react';

/** Determine decimal digits for a symbol */
export function getSymbolDigits(symbol: string): number {
    const sym = symbol.toUpperCase();
    if (sym.includes('JPY')) return 3;
    if (sym.startsWith('BTC') || sym.startsWith('ETH') || sym.startsWith('SOL') || sym.startsWith('LTC') || sym.startsWith('XRP')) return 2;
    if (sym.startsWith('XAU')) return 2;
    if (sym.startsWith('XAG')) return 3;
    return 5;
}

interface PriceDisplayProps {
    /** The numeric price value */
    price: number;
    /** Symbol name for digit detection, e.g. "BTCUSD" */
    symbol: string;
    /** Optional explicit digits override */
    digits?: number;
    /** Optional className applied to the wrapper span */
    className?: string;
    /** Size of the large last-2-digit text. 'sm' for table rows, 'lg' for panels */
    size?: 'sm' | 'lg';
}

/**
 * Renders a price with the last 2 decimal digits in a larger, bolder font.
 * 
 * Example (EURUSD 1.33601):
 *   small: "1.336"  big: "01"
 * 
 * Example (BTCUSD 67895.43):
 *   small: "67895."  big: "43"
 */
export const PriceDisplay: React.FC<PriceDisplayProps> = ({
    price,
    symbol,
    digits: explicitDigits,
    className = '',
    size = 'sm',
}) => {
    if (!Number.isFinite(price) || price === 0) {
        return <span className={className}>-</span>;
    }

    const d = explicitDigits ?? getSymbolDigits(symbol);
    const full = price.toFixed(d);

    let smallPart: string;
    let bigPart: string;

    if (d <= 1) {
        // No split possible for 0-1 decimals
        return <span className={className}>{full}</span>;
    }

    if (d === 2) {
        // e.g. "67895.43" ΓåÆ small="67895." big="43"
        const dotIdx = full.indexOf('.');
        smallPart = full.slice(0, dotIdx + 1);
        bigPart = full.slice(dotIdx + 1);
    } else {
        // e.g. "1.33601" ΓåÆ small="1.336" big="01"
        const dotIdx = full.indexOf('.');
        const decPart = full.slice(dotIdx + 1);
        smallPart = full.slice(0, dotIdx + 1) + decPart.slice(0, -2);
        bigPart = decPart.slice(-2);
    }

    const bigFontSize = size === 'lg' ? 'text-[14px]' : 'text-[13px]';
    const bigFontWeight = 'font-extrabold';

    return (
        <span className={`${className} whitespace-nowrap`}>
            <span>{smallPart}</span>
            <span className={`${bigFontSize} ${bigFontWeight}`}>{bigPart}</span>
        </span>
    );
};

/**
 * Plain string formatter that returns "small|big" for non-React contexts.
 * Mostly you should use the <PriceDisplay> component instead.
 */
export function formatPriceParts(price: number, symbol: string, explicitDigits?: number): { small: string; big: string } {
    const d = explicitDigits ?? getSymbolDigits(symbol);
    if (!Number.isFinite(price) || price === 0) return { small: '-', big: '' };
    const full = price.toFixed(d);
    if (d <= 1) return { small: full, big: '' };
    if (d === 2) {
        const dotIdx = full.indexOf('.');
        return { small: full.slice(0, dotIdx + 1), big: full.slice(dotIdx + 1) };
    }
    const dotIdx = full.indexOf('.');
    const decPart = full.slice(dotIdx + 1);
    return { small: full.slice(0, dotIdx + 1) + decPart.slice(0, -2), big: decPart.slice(-2) };
}

export default PriceDisplay;

import { Icon } from './/Icon';
import React, { useRef, useState, useEffect } from 'react';
import { useHoverIntent } from '../../hooks/useHoverIntent';
import { useSafeHoverTriangle } from '../../hooks/useSafeHoverTriangle';

interface SubmenuItemProps {
  label: string;
  shortcut?: string;
  checked?: boolean;
  hasSubmenu?: boolean;
  active?: boolean;
  action?: () => void;
  icon?: React.ReactNode;
  autoClose?: boolean;
  submenu?: React.ReactNode;
  onSubmenuChange?: (isOpen: boolean) => void;
}

/**
 * SubmenuItem - Context menu item with MT5-equivalent hover behavior
 *
 * Features:
 * - 150ms hover intent delay (feels instant but prevents accidents)
 * - Safe hover triangle (move cursor toward submenu without closing)
 * - No flickering when moving between items
 * - Desktop-grade UX matching professional trading platforms
 */
export const SubmenuItem: React.FC<SubmenuItemProps> = ({
  label,
  shortcut,
  checked,
  hasSubmenu,
  active,
  action,
  icon,
  autoClose = true,
  submenu,
  onSubmenuChange,
}) => {
  const parentRef = useRef<HTMLDivElement>(null);
  const submenuRef = useRef<HTMLDivElement>(null);
  const [isSubmenuOpen, setIsSubmenuOpen] = useState(false);

  // Hover intent for parent item (150ms delay)
  const hoverIntent = useHoverIntent({ delay: 150, sensitivity: 7 });

  // Safe hover triangle for submenu navigation
  const safeTriangle = useSafeHoverTriangle({
    parentElement: parentRef.current,
    submenuElement: submenuRef.current,
    tolerance: 100,
  });

  // Open submenu when hover intent is triggered
  useEffect(() => {
    if (hasSubmenu && hoverIntent.isHovering) {
      setIsSubmenuOpen(true);
      onSubmenuChange?.(true);
    }
  }, [hoverIntent.isHovering, hasSubmenu, onSubmenuChange]);

  // Handle mouse leave with safe triangle logic
  useEffect(() => {
    if (!hasSubmenu) return;

    const handleGlobalMouseMove = () => {
      if (isSubmenuOpen) {
        // Check if mouse should keep submenu open
        const shouldStay = safeTriangle.shouldStayOpen();

        if (!shouldStay) {
          // Small delay before closing to prevent flicker
          setTimeout(() => {
            if (!safeTriangle.shouldStayOpen()) {
              setIsSubmenuOpen(false);
              onSubmenuChange?.(false);
              hoverIntent.reset();
            }
          }, 100);
        }
      }
    };

    if (isSubmenuOpen) {
      const timer = setInterval(handleGlobalMouseMove, 50);
      return () => clearInterval(timer);
    }
  }, [isSubmenuOpen, hasSubmenu, safeTriangle, hoverIntent, onSubmenuChange]);

  const handleClick = (e: React.MouseEvent) => {
    e.stopPropagation();

    if (hasSubmenu) {
      // Toggle submenu on click (secondary interaction)
      setIsSubmenuOpen(!isSubmenuOpen);
      onSubmenuChange?.(!isSubmenuOpen);
    } else if (action) {
      action();
    }
  };

  return (
    <div
      ref={parentRef}
      className={`flex items-center px-3 py-1.5 hover:bg-zinc-700 hover:text-white cursor-pointer group relative ${
        active || isSubmenuOpen ? 'bg-zinc-700 text-white' : 'text-zinc-300'
      }`}
      onClick={handleClick}
      onMouseEnter={hoverIntent.onMouseEnter}
      onMouseMove={hoverIntent.onMouseMove}
      onMouseLeave={hoverIntent.onMouseLeave}
    >
      <div className="w-5 flex items-center justify-center mr-1">
        {checked && <Icon name="check" size="xs" />}
        {icon && !checked && <span className="text-zinc-400 group-hover:text-white">{icon}</span>}
      </div>
      <span className="flex-1">{label}</span>
      {shortcut && (
        <span className="text-[10px] text-zinc-500 group-hover:text-zinc-200 ml-4 font-mono">
          {shortcut}
        </span>
      )}
      {hasSubmenu && <Icon name="chevron-right" size="xs" className="ml-2 text-zinc-500 group-hover:text-white" />}

      {/* Submenu */}
      {hasSubmenu && isSubmenuOpen && submenu && (
        <div
          ref={submenuRef}
          className="absolute left-full top-0 -ml-1 w-48 bg-[#131316] border border-zinc-600 shadow-xl rounded-sm py-1 z-50"
          style={{ pointerEvents: 'auto' }}
        >
          {submenu}
        </div>
      )}
    </div>
  );
};

