/**
 * useCanvasSelection Hook
 * Provides easy access to canvas selection state and actions
 */

import { useCallback, useEffect, useRef } from 'react';
import {
  useCanvasSelectionStore,
  createDefaultSnapZones,
  type Rect,
  type SnapZone,
} from '../store/useCanvasSelectionStore';

export interface UseCanvasSelectionOptions {
  containerWidth?: number;
  containerHeight?: number;
  customSnapZones?: SnapZone[];
  onSelectionChange?: (rect: Rect | null) => void;
  onSelectionConfirm?: (rect: Rect) => void;
  onSelectionCancel?: () => void;
  enableKeyboardShortcuts?: boolean;
}

export interface UseCanvasSelectionReturn {
  // State
  selectionRect: Rect | null;
  mode: 'idle' | 'selecting' | 'selected' | 'moving' | 'resizing' | 'cropping';
  isSnapped: boolean;
  activeSnapZone: SnapZone | null;
  snapGuides: { type: 'vertical' | 'horizontal'; position: number; source: 'center' | 'edge' | 'zone' }[];
  canUndo: boolean;
  canRedo: boolean;
  isCropping: boolean;
  maintainAspectRatio: boolean;
  showSnapGuides: boolean;
  showZoneHighlights: boolean;

  // Actions
  startSelection: (x: number, y: number) => void;
  updateSelection: (x: number, y: number) => void;
  endSelection: () => void;
  clearSelection: () => void;
  confirmSelection: () => void;

  // Move actions
  startMove: (x: number, y: number) => void;
  updateMove: (x: number, y: number, containerBounds: Rect) => void;
  endMove: () => void;

  // Resize actions
  startResize: (handle: 'n' | 'ne' | 'e' | 'se' | 's' | 'sw' | 'w' | 'nw' | null, x: number, y: number) => void;
  updateResize: (x: number, y: number, containerBounds: Rect, minSize?: number) => void;
  endResize: () => void;

  // Crop actions
  startCrop: () => void;
  applyCrop: () => void;
  cancelCrop: () => void;

  // History actions
  undo: () => void;
  redo: () => void;

  // Settings
  setMaintainAspectRatio: (value: boolean) => void;
  setShowSnapGuides: (value: boolean) => void;
  setShowZoneHighlights: (value: boolean) => void;
  setSnapZones: (zones: SnapZone[]) => void;

  // Nudge actions
  nudgeUp: (step?: number) => void;
  nudgeDown: (step?: number) => void;
  nudgeLeft: (step?: number) => void;
  nudgeRight: (step?: number) => void;
  expandWidth: (step?: number) => void;
  expandHeight: (step?: number) => void;
  shrinkWidth: (step?: number) => void;
  shrinkHeight: (step?: number) => void;

  // Utils
  initializeSnapZones: (width: number, height: number, customZones?: SnapZone[]) => void;
  isPointInSelection: (x: number, y: number) => boolean;
  getRelativeCoordinates: (clientX: number, clientY: number, containerElement: HTMLElement) => { x: number; y: number };
}

export const useCanvasSelection = (options: UseCanvasSelectionOptions = {}): UseCanvasSelectionReturn => {
  const {
    containerWidth = 800,
    containerHeight = 600,
    customSnapZones,
    onSelectionChange,
    onSelectionConfirm,
    onSelectionCancel,
    enableKeyboardShortcuts = true,
  } = options;

  const containerRef = useRef<HTMLElement | null>(null);

  // Get state from store
  const store = useCanvasSelectionStore();

  // Initialize snap zones on mount
  useEffect(() => {
    const zones = customSnapZones || createDefaultSnapZones(containerWidth, containerHeight);
    store.setSnapZones(zones);
  }, [containerWidth, containerHeight, customSnapZones]);

  // Notify parent of selection changes
  useEffect(() => {
    onSelectionChange?.(store.selectionRect);
  }, [store.selectionRect, onSelectionChange]);

  // Keyboard shortcuts
  useEffect(() => {
    if (!enableKeyboardShortcuts) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      // Undo/Redo
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        e.preventDefault();
        if (e.shiftKey) {
          store.redo();
        } else {
          store.undo();
        }
        return;
      }

      // Confirm/Cancel
      if (e.key === 'Enter') {
        e.preventDefault();
        if (store.isCropping) {
          store.applyCrop();
        } else if (store.selectionRect) {
          onSelectionConfirm?.(store.selectionRect);
        }
        return;
      }

      if (e.key === 'Escape') {
        e.preventDefault();
        if (store.isCropping) {
          store.cancelCrop();
        } else {
          store.clearSelection();
          onSelectionCancel?.();
        }
        return;
      }

      // Arrow key nudging
      if (store.mode === 'selected' && store.selectionRect) {
        const step = e.shiftKey ? 10 : 1;
        switch (e.key) {
          case 'ArrowUp':
            e.preventDefault();
            store.nudgeSelection(0, -step);
            break;
          case 'ArrowDown':
            e.preventDefault();
            store.nudgeSelection(0, step);
            break;
          case 'ArrowLeft':
            e.preventDefault();
            store.nudgeSelection(-step, 0);
            break;
          case 'ArrowRight':
            e.preventDefault();
            store.nudgeSelection(step, 0);
            break;
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [enableKeyboardShortcuts, store, onSelectionConfirm, onSelectionCancel]);

  // Helper: Initialize snap zones
  const initializeSnapZones = useCallback((width: number, height: number, customZones?: SnapZone[]) => {
    const zones = customZones || createDefaultSnapZones(width, height);
    store.setSnapZones(zones);
  }, [store]);

  // Helper: Check if point is in selection
  const isPointInSelection = useCallback((x: number, y: number): boolean => {
    if (!store.selectionRect) return false;
    const { x: sx, y: sy, width, height } = store.selectionRect;
    return x >= sx && x <= sx + width && y >= sy && y <= sy + height;
  }, [store.selectionRect]);

  // Helper: Get relative coordinates
  const getRelativeCoordinates = useCallback((clientX: number, clientY: number, containerElement: HTMLElement): { x: number; y: number } => {
    const rect = containerElement.getBoundingClientRect();
    return {
      x: clientX - rect.left,
      y: clientY - rect.top,
    };
  }, []);

  // Nudge helpers
  const nudgeUp = useCallback((step = 1) => {
    if (store.mode === 'selected') {
      store.nudgeSelection(0, -step);
    }
  }, [store]);

  const nudgeDown = useCallback((step = 1) => {
    if (store.mode === 'selected') {
      store.nudgeSelection(0, step);
    }
  }, [store]);

  const nudgeLeft = useCallback((step = 1) => {
    if (store.mode === 'selected') {
      store.nudgeSelection(-step, 0);
    }
  }, [store]);

  const nudgeRight = useCallback((step = 1) => {
    if (store.mode === 'selected') {
      store.nudgeSelection(step, 0);
    }
  }, [store]);

  const expandWidth = useCallback((step = 10) => {
    if (store.mode === 'selected') {
      store.expandSelection(step, 0);
    }
  }, [store]);

  const expandHeight = useCallback((step = 10) => {
    if (store.mode === 'selected') {
      store.expandSelection(0, step);
    }
  }, [store]);

  const shrinkWidth = useCallback((step = 10) => {
    if (store.mode === 'selected') {
      store.expandSelection(-step, 0);
    }
  }, [store]);

  const shrinkHeight = useCallback((step = 10) => {
    if (store.mode === 'selected') {
      store.expandSelection(0, -step);
    }
  }, [store]);

  // Confirm selection helper
  const confirmSelection = useCallback(() => {
    if (store.selectionRect) {
      onSelectionConfirm?.(store.selectionRect);
    }
  }, [store.selectionRect, onSelectionConfirm]);

  return {
    // State
    selectionRect: store.selectionRect,
    mode: store.mode,
    isSnapped: store.isSnapped,
    activeSnapZone: store.activeSnapZone,
    snapGuides: store.snapGuides,
    canUndo: store.canUndo(),
    canRedo: store.canRedo(),
    isCropping: store.isCropping,
    maintainAspectRatio: store.maintainAspectRatio,
    showSnapGuides: store.showSnapGuides,
    showZoneHighlights: store.showZoneHighlights,

    // Actions
    startSelection: store.startSelection,
    updateSelection: store.updateSelection,
    endSelection: store.endSelection,
    clearSelection: store.clearSelection,
    confirmSelection,

    // Move actions
    startMove: store.startMove,
    updateMove: store.updateMove,
    endMove: store.endMove,

    // Resize actions
    startResize: store.startResize,
    updateResize: store.updateResize,
    endResize: store.endResize,

    // Crop actions
    startCrop: store.startCrop,
    applyCrop: store.applyCrop,
    cancelCrop: store.cancelCrop,

    // History actions
    undo: store.undo,
    redo: store.redo,

    // Settings
    setMaintainAspectRatio: store.setMaintainAspectRatio,
    setShowSnapGuides: store.setShowSnapGuides,
    setShowZoneHighlights: store.setShowZoneHighlights,
    setSnapZones: store.setSnapZones,

    // Nudge actions
    nudgeUp,
    nudgeDown,
    nudgeLeft,
    nudgeRight,
    expandWidth,
    expandHeight,
    shrinkWidth,
    shrinkHeight,

    // Utils
    initializeSnapZones,
    isPointInSelection,
    getRelativeCoordinates,
  };
};

export default useCanvasSelection;

/**
 * Chart Print Hook
 * Provides chart printing functionality with setup and preview dialogs
 */

import { useState, useCallback } from 'react';
import { chartPrinter, type PrintPreferences, type ChartPrintData } from '../services/chartPrinter';
import type { IChartApi } from 'lightweight-charts';

export interface UseChartPrintOptions {
  accountId?: string;
  symbol: string;
  timeframe: string;
  chartApi?: IChartApi | null;
  getIndicators?: () => Array<{ name: string; parameters: Record<string, any> }>;
  getDrawings?: () => Array<{ type: string; label?: string }>;
}

export function useChartPrint(options: UseChartPrintOptions) {
  const [showSetupDialog, setShowSetupDialog] = useState(false);
  const [showPreviewDialog, setShowPreviewDialog] = useState(false);
  const [printPreferences, setPrintPreferences] = useState<PrintPreferences | null>(null);
  const [chartData, setChartData] = useState<ChartPrintData | null>(null);

  /**
   * Open print setup dialog
   */
  const openPrintSetup = useCallback(() => {
    setShowSetupDialog(true);
  }, []);

  /**
   * Handle setup dialog completion
   */
  const handleSetupComplete = useCallback(
    (preferences: PrintPreferences) => {
      // Capture chart data
      const data: ChartPrintData = {
        symbol: options.symbol,
        timeframe: options.timeframe,
        dateRange: {
          from: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), // Default: 30 days ago
          to: new Date(),
        },
        indicators: options.getIndicators ? options.getIndicators() : [],
        drawings: options.getDrawings ? options.getDrawings() : [],
      };

      // Capture chart canvas if API is available
      if (options.chartApi) {
        const canvas = chartPrinter.captureChartCanvas(options.chartApi);
        if (canvas) {
          data.chartCanvas = canvas;
        }
      }

      setChartData(data);
      setPrintPreferences(preferences);
      setShowSetupDialog(false);
      setShowPreviewDialog(true);
    },
    [options]
  );

  /**
   * Handle direct print (skip preview)
   */
  const handleDirectPrint = useCallback(async () => {
    if (!chartData || !printPreferences) return;

    try {
      await chartPrinter.printChart(chartData, printPreferences);
      setShowPreviewDialog(false);
      setChartData(null);
      setPrintPreferences(null);
    } catch (error) {
      console.error('Print failed:', error);
    }
  }, [chartData, printPreferences]);

  /**
   * Close all dialogs
   */
  const closeDialogs = useCallback(() => {
    setShowSetupDialog(false);
    setShowPreviewDialog(false);
    setChartData(null);
    setPrintPreferences(null);
  }, []);

  return {
    // State
    showSetupDialog,
    showPreviewDialog,
    printPreferences,
    chartData,

    // Actions
    openPrintSetup,
    handleSetupComplete,
    handleDirectPrint,
    closeDialogs,
  };
}

/**
 * useCommandBus Hook
 * React integration for the centralized command bus
 * Provides dispatch and subscription methods with proper cleanup
 */

import { useCallback, useEffect } from 'react';
import { commandBus } from '../services/commandBus';
import type {
  Command,
  CommandType,
  CommandHandler,
  Unsubscribe,
  PayloadFor,
} from '../types/commands';

/**
 * useCommandBus Hook
 * Provides access to the centralized command bus
 *
 * @example
 * const { dispatch, useCommandSubscription } = useCommandBus();
 *
 * // Dispatch a command
 * dispatch({ type: 'SET_CHART_TYPE', payload: { chartType: 'line' } });
 *
 * // Subscribe to commands
 * useCommandSubscription('OPEN_ORDER_PANEL', (payload) => {
 *   console.log('Order panel opened for', payload.symbol);
 * });
 */
export function useCommandBus() {
  /**
   * Dispatch a command
   * Memoized to ensure stable reference
   */
  const dispatch = useCallback((command: Command): void => {
    commandBus.dispatch(command);
  }, []);

  /**
   * Subscribe to a specific command type
   * Handles cleanup automatically
   *
   * @param type - The command type to listen for
   * @param handler - Function to call when command is dispatched
   *
   * @example
   * useCommandSubscription('SET_CHART_TYPE', (payload) => {
   *   console.log('Chart type changed to:', payload.chartType);
   * });
   */
  const useCommandSubscription = useCallback(
    <T extends CommandType>(
      type: T,
      handler: CommandHandler<T>
    ): void => {
      useEffect(() => {
        // Subscribe to the command type
        const unsubscribe = commandBus.subscribe(type, handler);

        // Clean up on unmount
        return unsubscribe;
      }, [type, handler]);
    },
    []
  );

  /**
   * Get command history
   * Useful for debugging
   */
  const getHistory = useCallback((): Command[] => {
    return commandBus.getHistory();
  }, []);

  /**
   * Replay commands
   * Useful for testing
   */
  const replay = useCallback(
    async (commands: Command[]): Promise<void> => {
      return commandBus.replay(commands);
    },
    []
  );

  /**
   * Subscribe to commands
   * Direct subscription method (not a hook)
   * Returns unsubscribe function
   */
  const subscribe = useCallback(
    (handler: (cmd: Command) => void): Unsubscribe => {
      return commandBus.subscribe('*' as CommandType, handler as any);
    },
    []
  );

  return {
    dispatch,
    subscribe,
    useCommandSubscription,
    getHistory,
    replay,
  };
}

/**
 * useCommandDispatch Hook
 * Simple hook to get only the dispatch function
 * Use when you only need to dispatch commands
 *
 * @example
 * const dispatch = useCommandDispatch();
 * dispatch({ type: 'ZOOM_IN', payload: {} });
 */
export function useCommandDispatch() {
  const dispatch = useCallback((command: Command): void => {
    commandBus.dispatch(command);
  }, []);

  return dispatch;
}

/**
 * useCommandListener Hook
 * Simple hook to listen for a specific command type
 * Automatically handles cleanup
 *
 * @param type - The command type to listen for
 * @param handler - Function to call when command is dispatched
 *
 * @example
 * useCommandListener('SET_CHART_TYPE', (payload) => {
 *   console.log('Chart type:', payload.chartType);
 * });
 */
export function useCommandListener<T extends CommandType>(
  type: T,
  handler: CommandHandler<T>
): void {
  useEffect(() => {
    const unsubscribe = commandBus.subscribe(type, handler);
    return unsubscribe;
  }, [type, handler]);
}

/**
 * useCommandHistory Hook
 * Get access to command history and controls
 *
 * @example
 * const { history, clear, replay } = useCommandHistory();
 * console.log('Last 5 commands:', history.slice(-5));
 */
export function useCommandHistory() {
  const getHistory = useCallback((): Command[] => {
    return commandBus.getHistory();
  }, []);

  const clear = useCallback((): void => {
    commandBus.clearHistory();
  }, []);

  const replay = useCallback(
    async (commands?: Command[]): Promise<void> => {
      const toReplay = commands || getHistory();
      return commandBus.replay(toReplay);
    },
    []
  );

  return {
    getHistory,
    clear,
    replay,
  };
}

