import { useState, useRef, useCallback, useEffect } from 'react';

interface Point {
  x: number;
  y: number;
}

interface SafeHoverTriangleOptions {
  parentElement: HTMLElement | null;
  submenuElement: HTMLElement | null;
  tolerance?: number;
}

/**
 * Implements the "safe hover triangle" pattern used in professional desktop menus.
 * Creates a virtual triangle from cursor to submenu corners - if mouse stays in triangle,
 * submenu stays open even when moving diagonally toward it.
 *
 * This prevents the frustrating "submenu closes before I can reach it" problem.
 *
 * Based on Amazon mega-menu algorithm and standard desktop UI patterns.
 */
export function useSafeHoverTriangle(options: SafeHoverTriangleOptions) {
  const { parentElement, submenuElement, tolerance = 100 } = options;
  const [isInSafeZone, setIsInSafeZone] = useState(false);
  const mousePositionRef = useRef<Point>({ x: 0, y: 0 });
  const lastMovementTimeRef = useRef<number>(Date.now());

  /**
   * Check if a point is inside a triangle using cross product method
   */
  const isPointInTriangle = useCallback((point: Point, triangle: [Point, Point, Point]): boolean => {
    const [p1, p2, p3] = triangle;

    const sign = (p1: Point, p2: Point, p3: Point): number => {
      return (p1.x - p3.x) * (p2.y - p3.y) - (p2.x - p3.x) * (p1.y - p3.y);
    };

    const d1 = sign(point, p1, p2);
    const d2 = sign(point, p2, p3);
    const d3 = sign(point, p3, p1);

    const hasNeg = (d1 < 0) || (d2 < 0) || (d3 < 0);
    const hasPos = (d1 > 0) || (d2 > 0) || (d3 > 0);

    return !(hasNeg && hasPos);
  }, []);

  /**
   * Get the safe hover triangle coordinates
   */
  const getSafeTriangle = useCallback((): [Point, Point, Point] | null => {
    if (!parentElement || !submenuElement) return null;

    const parentRect = parentElement.getBoundingClientRect();
    const submenuRect = submenuElement.getBoundingClientRect();
    const mouse = mousePositionRef.current;

    // Determine if submenu is on right or left
    const isSubmenuOnRight = submenuRect.left > parentRect.right;

    if (isSubmenuOnRight) {
      // Triangle: cursor ΓåÆ top-left of submenu ΓåÆ bottom-left of submenu
      return [
        { x: mouse.x, y: mouse.y },
        { x: submenuRect.left, y: submenuRect.top - tolerance },
        { x: submenuRect.left, y: submenuRect.bottom + tolerance },
      ];
    } else {
      // Triangle: cursor ΓåÆ top-right of submenu ΓåÆ bottom-right of submenu
      return [
        { x: mouse.x, y: mouse.y },
        { x: submenuRect.right, y: submenuRect.top - tolerance },
        { x: submenuRect.right, y: submenuRect.bottom + tolerance },
      ];
    }
  }, [parentElement, submenuElement, tolerance]);

  /**
   * Check if current mouse position is in safe zone
   */
  const checkSafeZone = useCallback((point: Point): boolean => {
    if (!parentElement || !submenuElement) return false;

    const triangle = getSafeTriangle();
    if (!triangle) return false;

    return isPointInTriangle(point, triangle);
  }, [parentElement, submenuElement, getSafeTriangle, isPointInTriangle]);

  /**
   * Handle mouse movement to update safe zone status
   */
  const onMouseMove = useCallback((e: MouseEvent) => {
    const point = { x: e.clientX, y: e.clientY };
    mousePositionRef.current = point;
    lastMovementTimeRef.current = Date.now();

    const inSafeZone = checkSafeZone(point);
    setIsInSafeZone(inSafeZone);
  }, [checkSafeZone]);

  /**
   * Track if mouse is over parent or submenu
   */
  const isMouseOverElements = useCallback((point: Point): boolean => {
    if (!parentElement || !submenuElement) return false;

    const parentRect = parentElement.getBoundingClientRect();
    const submenuRect = submenuElement.getBoundingClientRect();

    const overParent = (
      point.x >= parentRect.left &&
      point.x <= parentRect.right &&
      point.y >= parentRect.top &&
      point.y <= parentRect.bottom
    );

    const overSubmenu = (
      point.x >= submenuRect.left &&
      point.x <= submenuRect.right &&
      point.y >= submenuRect.top &&
      point.y <= submenuRect.bottom
    );

    return overParent || overSubmenu;
  }, [parentElement, submenuElement]);

  /**
   * Determine if submenu should stay open
   */
  const shouldStayOpen = useCallback((): boolean => {
    const point = mousePositionRef.current;

    // Always stay open if mouse is directly over parent or submenu
    if (isMouseOverElements(point)) return true;

    // Stay open if mouse is in safe hover triangle
    if (isInSafeZone) return true;

    return false;
  }, [isInSafeZone, isMouseOverElements]);

  // Set up global mouse tracking
  useEffect(() => {
    if (parentElement && submenuElement) {
      document.addEventListener('mousemove', onMouseMove);
      return () => {
        document.removeEventListener('mousemove', onMouseMove);
      };
    }
  }, [parentElement, submenuElement, onMouseMove]);

  return {
    isInSafeZone,
    shouldStayOpen,
    mousePosition: mousePositionRef.current,
  };
}

import { useReducer, useEffect } from 'react';
import type { ToolbarAction } from '../store/toolbarState';
import { toolbarReducer, initialToolbarState } from '../store/toolbarState';
import { useCommandBus } from './useCommandBus';
import type { Command } from '../types/commands';

export function useToolbarState() {
  const [state, dispatchLocal] = useReducer(toolbarReducer, initialToolbarState);
  const { dispatch: dispatchCommand, subscribe } = useCommandBus();

  // Subscribe to command bus for incoming commands that affect toolbar state
  useEffect(() => {
    const unsubscribe = subscribe((cmd: Command) => {
      // Map commands to toolbar actions
      switch (cmd.type) {
        case 'SELECT_TOOL':
          dispatchLocal({ type: 'SELECT_TOOL', tool: cmd.payload.tool, subtype: (cmd.payload as any).subtype });
          break;

        case 'SET_CHART_TYPE':
          dispatchLocal({ type: 'SET_CHART_TYPE', chartType: cmd.payload.chartType });
          break;

        case 'SET_TIMEFRAME':
          dispatchLocal({ type: 'SET_TIMEFRAME', timeframe: cmd.payload.timeframe });
          break;

        case 'TOGGLE_CROSSHAIR':
          dispatchLocal({ type: 'TOGGLE_CROSSHAIR' });
          break;

        case 'ZOOM_IN':
          dispatchLocal({ type: 'ZOOM', delta: 2 });
          break;

        case 'ZOOM_OUT':
          dispatchLocal({ type: 'ZOOM', delta: -2 });
          break;

        case 'DELETE_DRAWING':
          dispatchLocal({ type: 'DELETE_DRAWING', id: cmd.payload.id });
          break;

        case 'SET_AUTO_SCROLL':
          dispatchLocal({ type: 'SET_AUTO_SCROLL', enabled: cmd.payload.enabled });
          break;

        case 'SET_CHART_SHIFT':
          dispatchLocal({ type: 'SET_CHART_SHIFT', enabled: cmd.payload.enabled });
          break;

        case 'TOGGLE_MAGNET':
          dispatchLocal({ type: 'TOGGLE_MAGNET' });
          break;

        default:
          break;
      }
    });

    return unsubscribe;
  }, [subscribe]);

  // Wrapper to dispatch both locally and to command bus
  const dispatch = (action: ToolbarAction) => {
    // Update local state
    dispatchLocal(action);

    // Emit to command bus for other components (map ToolbarAction to Command)
    // Note: Not all ToolbarActions map to Commands - some are internal only
    switch (action.type) {
      case 'SELECT_TOOL':
        dispatchCommand({
          type: 'SELECT_TOOL',
          payload: { tool: action.tool || 'cursor', subtype: action.subtype }
        } as Command);
        break;

      case 'SET_CHART_TYPE':
        dispatchCommand({
          type: 'SET_CHART_TYPE',
          payload: { chartType: action.chartType }
        } as Command);
        break;

      case 'SET_TIMEFRAME':
        dispatchCommand({
          type: 'SET_TIMEFRAME',
          payload: { timeframe: action.timeframe }
        } as Command);
        break;

      case 'TOGGLE_CROSSHAIR':
        dispatchCommand({
          type: 'TOGGLE_CROSSHAIR',
          payload: {}
        } as Command);
        break;

      case 'ZOOM':
        // Map ZOOM action to ZOOM_IN or ZOOM_OUT command based on delta
        if (action.delta > 0) {
          dispatchCommand({
            type: 'ZOOM_IN',
            payload: {}
          } as Command);
        } else {
          dispatchCommand({
            type: 'ZOOM_OUT',
            payload: {}
          } as Command);
        }
        break;

      case 'DELETE_DRAWING':
        dispatchCommand({
          type: 'DELETE_DRAWING',
          payload: { id: action.id }
        } as Command);
        break;
      case 'TOGGLE_AUTO_SCROLL':
        dispatchCommand({
          type: 'SET_AUTO_SCROLL',
          payload: { enabled: !state.autoScrollEnabled }
        } as Command);
        break;

      case 'TOGGLE_CHART_SHIFT':
        dispatchCommand({
          type: 'SET_CHART_SHIFT',
          payload: { enabled: !state.chartShiftEnabled }
        } as Command);
        break;

      default:
        break;
    }
  };

  return {
    state,
    dispatch
  };
}

/**
 * React Hook for Web Worker Management
 * - Easy-to-use interface for Web Workers
 * - Promise-based API
 * - Automatic cleanup
 * - Error handling
 */

import { useEffect, useRef, useCallback } from 'react';

interface WorkerResponse<T> {
  type: 'success' | 'error';
  requestId: string;
  result?: T;
  error?: string;
}

interface PendingRequest<T> {
  resolve: (value: T) => void;
  reject: (error: Error) => void;
  timeout: ReturnType<typeof setTimeout>;
}

export function useWebWorker<T = unknown>(workerPath: string, timeout = 30000) {
  const workerRef = useRef<Worker | null>(null);
  const pendingRequests = useRef<Map<string, PendingRequest<T>>>(new Map());
  const requestIdCounter = useRef(0);

  // Initialize worker
  useEffect(() => {
    try {
      workerRef.current = new Worker(new URL(workerPath, import.meta.url), {
        type: 'module',
      });

      workerRef.current.onmessage = (event: MessageEvent<WorkerResponse<T>>) => {
        const { type, requestId, result, error } = event.data;

        const pending = pendingRequests.current.get(requestId);
        if (!pending) return;

        clearTimeout(pending.timeout);
        pendingRequests.current.delete(requestId);

        if (type === 'success' && result !== undefined) {
          pending.resolve(result);
        } else if (type === 'error') {
          pending.reject(new Error(error || 'Worker error'));
        }
      };

      workerRef.current.onerror = (error) => {
        console.error('[Worker] Error:', error);
        // Reject all pending requests
        pendingRequests.current.forEach((pending) => {
          clearTimeout(pending.timeout);
          pending.reject(new Error('Worker crashed'));
        });
        pendingRequests.current.clear();
      };
    } catch (error) {
      console.error('[Worker] Failed to create worker:', error);
    }

    // Cleanup on unmount
    return () => {
      if (workerRef.current) {
        workerRef.current.terminate();
        workerRef.current = null;
      }

      // Clear all pending requests
      pendingRequests.current.forEach((pending) => {
        clearTimeout(pending.timeout);
        pending.reject(new Error('Component unmounted'));
      });
      pendingRequests.current.clear();
    };
  }, [workerPath]);

  // Post message to worker
  const postMessage = useCallback(
    (type: string, data: unknown): Promise<T> => {
      return new Promise((resolve, reject) => {
        if (!workerRef.current) {
          reject(new Error('Worker not initialized'));
          return;
        }

        const requestId = `req_${++requestIdCounter.current}`;

        // Set timeout
        const timeoutId = setTimeout(() => {
          pendingRequests.current.delete(requestId);
          reject(new Error('Worker request timeout'));
        }, timeout);

        // Store pending request
        pendingRequests.current.set(requestId, {
          resolve,
          reject,
          timeout: timeoutId,
        });

        // Send message
        workerRef.current.postMessage({
          type,
          data,
          requestId,
        });
      });
    },
    [timeout]
  );

  return { postMessage };
}

/**
 * React Hook for Workspace Management
 * Provides workspace state and operations with auto-save
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { workspaceManager } from '../services/workspaceManager';
import { workspaceApi } from '../services/workspaceApi';
import type {
  Workspace,
  WorkspaceMetadata,
  AutoSaveState,
  WorkspaceError,
} from '../types/workspace';

interface UseWorkspaceOptions {
  autoSaveEnabled?: boolean;
  autoSaveInterval?: number;
}

interface UseWorkspaceReturn {
  // Current workspace state
  currentWorkspace: Workspace | null;
  workspaceList: WorkspaceMetadata[];

  // Auto-save state
  autoSaveState: AutoSaveState;

  // Loading states
  isSaving: boolean;
  isLoading: boolean;
  isLoadingList: boolean;

  // Error state
  error: WorkspaceError | null;

  // Operations
  saveWorkspace: (name?: string, description?: string) => Promise<void>;
  loadWorkspace: (workspaceId: string) => Promise<void>;
  deleteWorkspace: (workspaceId: string) => Promise<void>;
  refreshWorkspaceList: () => Promise<void>;
  createNewWorkspace: (name: string, description?: string) => Promise<void>;
  duplicateWorkspace: (workspaceId: string, newName: string) => Promise<void>;
  setDefaultWorkspace: (workspaceId: string) => Promise<void>;

  // Auto-save control
  setAutoSaveEnabled: (enabled: boolean) => void;
  setAutoSaveInterval: (interval: number) => void;

  // Utility
  hasUnsavedChanges: boolean;
  clearError: () => void;
}

export function useWorkspace(options: UseWorkspaceOptions = {}): UseWorkspaceReturn {
  const {
    autoSaveEnabled = true,
    autoSaveInterval = 30000,
  } = options;

  // State
  const [currentWorkspace, setCurrentWorkspace] = useState<Workspace | null>(null);
  const [workspaceList, setWorkspaceList] = useState<WorkspaceMetadata[]>([]);
  const [autoSaveState, setAutoSaveState] = useState<AutoSaveState>(
    workspaceManager.getAutoSaveState()
  );
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingList, setIsLoadingList] = useState(false);
  const [error, setError] = useState<WorkspaceError | null>(null);

  // Refs
  const autoSaveStateRef = useRef(autoSaveState);
  autoSaveStateRef.current = autoSaveState;

  // Initialize workspace manager
  useEffect(() => {
    workspaceManager.setAutoSaveEnabled(autoSaveEnabled);
    workspaceManager.setAutoSaveInterval(autoSaveInterval);

    // Listen for auto-save state changes
    const unsubscribe = workspaceManager.addChangeListener((hasChanges) => {
      setAutoSaveState(workspaceManager.getAutoSaveState());
    });

    // Load workspace list on mount
    refreshWorkspaceList();

    return () => {
      unsubscribe();
    };
  }, []);

  // Update auto-save settings when options change
  useEffect(() => {
    workspaceManager.setAutoSaveEnabled(autoSaveEnabled);
  }, [autoSaveEnabled]);

  useEffect(() => {
    workspaceManager.setAutoSaveInterval(autoSaveInterval);
  }, [autoSaveInterval]);

  // Save workspace
  const saveWorkspace = useCallback(async (name?: string, description?: string) => {
    try {
      setIsSaving(true);
      setError(null);

      await workspaceManager.saveWorkspace(name, description);

      const saved = workspaceManager.getCurrentWorkspace();
      setCurrentWorkspace(saved);
      setAutoSaveState(workspaceManager.getAutoSaveState());

      // Refresh list to show updated workspace
      await refreshWorkspaceList();
    } catch (err: any) {
      const workspaceError: WorkspaceError = {
        code: err.statusCode === 401 ? 'UNAUTHORIZED' :
              err.statusCode === 409 ? 'CONFLICT' :
              err.name === 'ApiError' ? 'NETWORK_ERROR' : 'SERVER_ERROR',
        message: err.message || 'Failed to save workspace',
        details: err,
      };
      setError(workspaceError);
      throw err;
    } finally {
      setIsSaving(false);
    }
  }, []);

  // Load workspace
  const loadWorkspace = useCallback(async (workspaceId: string) => {
    try {
      setIsLoading(true);
      setError(null);

      await workspaceManager.loadWorkspace(workspaceId);

      const loaded = workspaceManager.getCurrentWorkspace();
      setCurrentWorkspace(loaded);
      setAutoSaveState(workspaceManager.getAutoSaveState());
    } catch (err: any) {
      const workspaceError: WorkspaceError = {
        code: err.statusCode === 404 ? 'NOT_FOUND' :
              err.statusCode === 401 ? 'UNAUTHORIZED' :
              err.name === 'ApiError' ? 'NETWORK_ERROR' : 'SERVER_ERROR',
        message: err.message || 'Failed to load workspace',
        details: err,
      };
      setError(workspaceError);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Delete workspace
  const deleteWorkspace = useCallback(async (workspaceId: string) => {
    try {
      setError(null);

      const response = await workspaceApi.deleteWorkspace(workspaceId);

      if (!response.success) {
        throw new Error(response.message || 'Failed to delete workspace');
      }

      // Refresh list
      await refreshWorkspaceList();

      // If deleted workspace was current, clear current
      if (currentWorkspace?.id === workspaceId) {
        setCurrentWorkspace(null);
      }
    } catch (err: any) {
      const workspaceError: WorkspaceError = {
        code: err.statusCode === 404 ? 'NOT_FOUND' :
              err.statusCode === 401 ? 'UNAUTHORIZED' :
              err.name === 'ApiError' ? 'NETWORK_ERROR' : 'SERVER_ERROR',
        message: err.message || 'Failed to delete workspace',
        details: err,
      };
      setError(workspaceError);
      throw err;
    }
  }, [currentWorkspace]);

  // Refresh workspace list
  const refreshWorkspaceList = useCallback(async () => {
    try {
      setIsLoadingList(true);
      setError(null);

      const response = await workspaceApi.listWorkspaces();

      if (response.success) {
        setWorkspaceList(response.workspaces);
      }
    } catch (err: any) {
      const workspaceError: WorkspaceError = {
        code: err.statusCode === 401 ? 'UNAUTHORIZED' :
              err.name === 'ApiError' ? 'NETWORK_ERROR' : 'SERVER_ERROR',
        message: err.message || 'Failed to load workspace list',
        details: err,
      };
      setError(workspaceError);
    } finally {
      setIsLoadingList(false);
    }
  }, []);

  // Create new workspace
  const createNewWorkspace = useCallback(async (name: string, description?: string) => {
    try {
      setIsSaving(true);
      setError(null);

      // Capture current state with new name
      const workspace = await workspaceManager.captureWorkspaceState(name, description);
      workspace.id = ''; // Force new ID

      // Save to backend
      await workspaceManager.saveWorkspace(name, description);

      const saved = workspaceManager.getCurrentWorkspace();
      setCurrentWorkspace(saved);

      // Refresh list
      await refreshWorkspaceList();
    } catch (err: any) {
      const workspaceError: WorkspaceError = {
        code: err.name === 'ApiError' ? 'NETWORK_ERROR' : 'SERVER_ERROR',
        message: err.message || 'Failed to create workspace',
        details: err,
      };
      setError(workspaceError);
      throw err;
    } finally {
      setIsSaving(false);
    }
  }, []);

  // Duplicate workspace
  const duplicateWorkspace = useCallback(async (workspaceId: string, newName: string) => {
    try {
      setError(null);

      const response = await workspaceApi.duplicateWorkspace(workspaceId, newName);

      if (!response.success) {
        throw new Error(response.message || 'Failed to duplicate workspace');
      }

      // Refresh list
      await refreshWorkspaceList();
    } catch (err: any) {
      const workspaceError: WorkspaceError = {
        code: err.statusCode === 404 ? 'NOT_FOUND' :
              err.name === 'ApiError' ? 'NETWORK_ERROR' : 'SERVER_ERROR',
        message: err.message || 'Failed to duplicate workspace',
        details: err,
      };
      setError(workspaceError);
      throw err;
    }
  }, []);

  // Set default workspace
  const setDefaultWorkspace = useCallback(async (workspaceId: string) => {
    try {
      setError(null);

      const response = await workspaceApi.setDefaultWorkspace(workspaceId);

      if (!response.success) {
        throw new Error(response.message || 'Failed to set default workspace');
      }

      // Refresh list to show updated default
      await refreshWorkspaceList();
    } catch (err: any) {
      const workspaceError: WorkspaceError = {
        code: err.statusCode === 404 ? 'NOT_FOUND' :
              err.name === 'ApiError' ? 'NETWORK_ERROR' : 'SERVER_ERROR',
        message: err.message || 'Failed to set default workspace',
        details: err,
      };
      setError(workspaceError);
      throw err;
    }
  }, []);

  // Auto-save control
  const setAutoSaveEnabled = useCallback((enabled: boolean) => {
    workspaceManager.setAutoSaveEnabled(enabled);
    setAutoSaveState(workspaceManager.getAutoSaveState());
  }, []);

  const setAutoSaveInterval = useCallback((interval: number) => {
    workspaceManager.setAutoSaveInterval(interval);
    setAutoSaveState(workspaceManager.getAutoSaveState());
  }, []);

  // Clear error
  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    currentWorkspace,
    workspaceList,
    autoSaveState,
    isSaving,
    isLoading,
    isLoadingList,
    error,
    saveWorkspace,
    loadWorkspace,
    deleteWorkspace,
    refreshWorkspaceList,
    createNewWorkspace,
    duplicateWorkspace,
    setDefaultWorkspace,
    setAutoSaveEnabled,
    setAutoSaveInterval,
    hasUnsavedChanges: autoSaveState.hasUnsavedChanges,
    clearError,
  };
}

