/**
 * Candle Aggregation Service
 * Builds OHLC candles from FIX tick data
 * - Normalizes timestamps (seconds -> milliseconds)
 * - Builds M1 candles from ticks
 * - Builds higher timeframes from COMPLETED M1 candles only
 * - Handles live updates and historical data
 */

export interface Tick {
  symbol: string;
  bid: number;
  ask: number;
  timestamp: number;  // Can be seconds or milliseconds
  volume?: number;
}

export interface OHLCV {
  time: number;       // Unix timestamp in SECONDS (for charts)
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  isComplete?: boolean;
  isSynthetic?: boolean;
}

// Alias for compatibility
export type CandleData = OHLCV;

export type Timeframe = 'M1' | 'M5' | 'M15' | 'M30' | 'H1' | 'H4' | 'D1' | 'W1' | 'MN';

interface TimeframeConfig {
  seconds: number;
  name: Timeframe;
}

const TIMEFRAME_CONFIG: Record<Timeframe, TimeframeConfig> = {
  M1: { seconds: 60, name: 'M1' },
  M5: { seconds: 300, name: 'M5' },
  M15: { seconds: 900, name: 'M15' },
  M30: { seconds: 1800, name: 'M30' },
  H1: { seconds: 3600, name: 'H1' },
  H4: { seconds: 14400, name: 'H4' },
  D1: { seconds: 86400, name: 'D1' },
  W1: { seconds: 604800, name: 'W1' },
  MN: { seconds: 2592000, name: 'MN' },
};

/**
 * Normalize timestamp to milliseconds
 * Handles both seconds (from WebSocket) and milliseconds
 */
export function normalizeTimestamp(ts: number): number {
  // If timestamp is less than 1 trillion, it's in seconds
  // (Unix timestamp for 2024 is around 1.7 billion)
  return ts < 1_000_000_000_000 ? ts * 1000 : ts;
}

/**
 * Align timestamp to timeframe boundary
 */
export function alignToTimeframe(timestampMs: number, tf: Timeframe): number {
  const config = TIMEFRAME_CONFIG[tf];
  const tfMs = config.seconds * 1000;
  return Math.floor(timestampMs / tfMs) * tfMs;
}

/**
 * Single-symbol candle builder
 * Builds M1 from ticks, higher TFs from completed M1
 */
export class SymbolCandleBuilder {
  private symbol: string;
  private m1Completed: OHLCV[] = [];
  private m1Forming: OHLCV | null = null;
  private higherTFs: Map<Timeframe, {
    forming: OHLCV | null;
    completed: OHLCV[];
  }> = new Map();

  constructor(symbol: string) {
    this.symbol = symbol;
    // Initialize higher timeframe storage
    (Object.keys(TIMEFRAME_CONFIG) as Timeframe[]).forEach(tf => {
      if (tf !== 'M1') {
        this.higherTFs.set(tf, { forming: null, completed: [] });
      }
    });
  }

  /**
   * Process a tick and update candles
   * Returns updated candles for all timeframes
   */
  processTick(tick: Tick): Map<Timeframe, OHLCV> {
    const updates = new Map<Timeframe, OHLCV>();

    // Normalize timestamp to milliseconds
    const tsMs = normalizeTimestamp(tick.timestamp);
    const price = (tick.bid + tick.ask) / 2;
    const volume = tick.volume || 1;

    // Calculate M1 bucket
    const m1Ms = 60 * 1000;
    const m1Time = Math.floor(tsMs / m1Ms) * m1Ms;
    const m1TimeSeconds = Math.floor(m1Time / 1000);

    // Check if we moved to a new M1 period
    if (this.m1Forming && m1TimeSeconds > this.m1Forming.time) {
      // Finalize previous M1
      this.m1Forming.isComplete = true;
      this.m1Completed.push(this.m1Forming);
      this.trimM1History();

      // Propagate to higher timeframes
      this.processCompletedM1(this.m1Forming, updates);
    }

    // Create or update M1
    if (!this.m1Forming || m1TimeSeconds > this.m1Forming.time) {
      this.m1Forming = {
        time: m1TimeSeconds,
        open: price,
        high: price,
        low: price,
        close: price,
        volume: volume,
        isComplete: false,
      };
    } else {
      // Update forming M1
      this.m1Forming.high = Math.max(this.m1Forming.high, price);
      this.m1Forming.low = Math.min(this.m1Forming.low, price);
      this.m1Forming.close = price;
      this.m1Forming.volume += volume;
    }

    updates.set('M1', this.m1Forming);

    // Update forming higher timeframes with current tick
    this.updateHigherTimeframesWithTick(price, volume, tsMs, updates);

    return updates;
  }

  /**
   * Process a completed M1 candle into higher timeframes
   */
  private processCompletedM1(m1: OHLCV, updates: Map<Timeframe, OHLCV>): void {
    for (const [tf, data] of this.higherTFs) {
      const config = TIMEFRAME_CONFIG[tf];
      const tfTime = Math.floor(m1.time / config.seconds) * config.seconds;

      if (!data.forming || data.forming.time !== tfTime) {
        // Finalize previous forming candle
        if (data.forming) {
          data.forming.isComplete = true;
          data.completed.push(data.forming);
          this.trimHigherTFHistory(tf);
        }

        // Start new TF candle from this M1
        data.forming = {
          time: tfTime,
          open: m1.open,
          high: m1.high,
          low: m1.low,
          close: m1.close,
          volume: m1.volume,
          isComplete: false,
        };
      } else {
        // Aggregate M1 into existing TF candle
        data.forming.high = Math.max(data.forming.high, m1.high);
        data.forming.low = Math.min(data.forming.low, m1.low);
        data.forming.close = m1.close;
        data.forming.volume += m1.volume;
      }

      updates.set(tf, data.forming);
    }
  }

  /**
   * Update forming higher TFs with live tick data
   */
  private updateHigherTimeframesWithTick(
    price: number,
    volume: number,
    tsMs: number,
    updates: Map<Timeframe, OHLCV>
  ): void {
    for (const [tf, data] of this.higherTFs) {
      if (!data.forming) continue;

      const config = TIMEFRAME_CONFIG[tf];
      const tfTimeMs = Math.floor(tsMs / (config.seconds * 1000)) * (config.seconds * 1000);
      const tfTimeSeconds = Math.floor(tfTimeMs / 1000);

      // Only update if tick belongs to current forming period
      if (tfTimeSeconds === data.forming.time) {
        data.forming.high = Math.max(data.forming.high, price);
        data.forming.low = Math.min(data.forming.low, price);
        data.forming.close = price;
        data.forming.volume += volume;
        updates.set(tf, data.forming);
      }
    }
  }

  /**
   * Load historical candles (from API)
   * These are already aggregated, so we use them as completed candles
   */
  loadHistoricalCandles(timeframe: Timeframe, candles: OHLCV[]): void {
    if (candles.length === 0) return;

    // Sort ascending
    const sorted = [...candles].sort((a, b) => a.time - b.time);

    // The last candle from API is ALWAYS the currently forming one (or the most recent)
    // We treat it as forming so live ticks can append to it.
    const lastCandle = sorted.pop()!;
    lastCandle.isComplete = false;

    if (timeframe === 'M1') {
      // Sort by time and add to completed
      this.m1Completed = sorted.map(c => ({ ...c, isComplete: true }));
      this.trimM1History();

      this.m1Forming = lastCandle;

      // Rebuild higher TFs from M1 history
      this.rebuildHigherTimeframes();

      // Since rebuilding only populates data.forming up to the last completed M1,
      // we need to also aggregate our forming M1 into the higher TFs
      const updates = new Map<Timeframe, OHLCV>();
      this.updateHigherTimeframesWithM1(this.m1Forming, updates);
    } else {
      // For higher TFs, store completed and set the last one as forming
      const data = this.higherTFs.get(timeframe);
      if (data) {
        data.completed = sorted.map(c => ({ ...c, isComplete: true }));
        data.forming = lastCandle;
        this.trimHigherTFHistory(timeframe);
      }
    }
  }

  /**
   * Helper to update higher TFs with an M1 candle (forming or complete)
   */
  private updateHigherTimeframesWithM1(m1: OHLCV, updates: Map<Timeframe, OHLCV>): void {
    const m1TimeMs = m1.time * 1000;

    for (const [tf, data] of this.higherTFs) {
      const config = TIMEFRAME_CONFIG[tf];
      const tfTimeMs = Math.floor(m1TimeMs / (config.seconds * 1000)) * (config.seconds * 1000);
      const tfTimeSeconds = Math.floor(tfTimeMs / 1000);

      // Check if we moved to a new period for this TF
      if (data.forming && data.forming.time !== tfTimeSeconds) {
        data.forming.isComplete = true;
        data.completed.push(data.forming);
        this.trimHigherTFHistory(tf);
        data.forming = null;
      }

      // Initialize forming if null
      if (!data.forming) {
        data.forming = {
          time: tfTimeSeconds,
          open: m1.open,
          high: m1.high,
          low: m1.low,
          close: m1.close,
          volume: m1.volume,
          isComplete: false,
        };
      } else {
        // Aggregate
        data.forming.high = Math.max(data.forming.high, m1.high);
        data.forming.low = Math.min(data.forming.low, m1.low);
        data.forming.close = m1.close;
        data.forming.volume += m1.volume; // For forming M1, this might overestimate volume slightly if called repeatedly, but we only call it once on load
      }

      updates.set(tf, data.forming);
    }
  }

  /**
   * Rebuild all higher TFs from M1 completed candles
   */
  private rebuildHigherTimeframes(): void {
    // Clear existing higher TF data
    for (const [tf, data] of this.higherTFs) {
      data.completed = [];
      data.forming = null;
    }

    // Process each completed M1
    const updates = new Map<Timeframe, OHLCV>();
    for (const m1 of this.m1Completed) {
      this.processCompletedM1(m1, updates);
    }
  }

  /**
   * Get candles for a timeframe
   */
  getCandles(timeframe: Timeframe, includeForming: boolean = true): OHLCV[] {
    if (timeframe === 'M1') {
      const result = [...this.m1Completed];
      if (includeForming && this.m1Forming) {
        result.push(this.m1Forming);
      }
      return result;
    }

    const data = this.higherTFs.get(timeframe);
    if (!data) return [];

    const result = [...data.completed];
    if (includeForming && data.forming) {
      result.push(data.forming);
    }
    return result;
  }

  /**
   * Get the last closed candle for a timeframe
   */
  getLastClosedCandle(timeframe: Timeframe): OHLCV | null {
    if (timeframe === 'M1') {
      return this.m1Completed.length > 0
        ? this.m1Completed[this.m1Completed.length - 1]
        : null;
    }

    const data = this.higherTFs.get(timeframe);
    return data && data.completed.length > 0
      ? data.completed[data.completed.length - 1]
      : null;
  }

  /**
   * Trim M1 history to prevent memory bloat
   */
  private trimM1History(): void {
    const MAX_M1_CANDLES = 1440; // 24 hours of M1
    if (this.m1Completed.length > MAX_M1_CANDLES) {
      this.m1Completed = this.m1Completed.slice(-MAX_M1_CANDLES);
    }
  }

  /**
   * Trim higher TF history
   */
  private trimHigherTFHistory(tf: Timeframe): void {
    const data = this.higherTFs.get(tf);
    if (!data) return;

    const limits: Record<Timeframe, number> = {
      M1: 1440, M5: 288, M15: 96, M30: 48,
      H1: 24, H4: 10, D1: 30, W1: 12, MN: 12
    };

    const limit = limits[tf] || 100;
    if (data.completed.length > limit) {
      data.completed = data.completed.slice(-limit);
    }
  }

  /**
   * Clear all data (for symbol switch)
   */
  clear(): void {
    this.m1Completed = [];
    this.m1Forming = null;
    for (const [_, data] of this.higherTFs) {
      data.completed = [];
      data.forming = null;
    }
  }
}

/**
 * Multi-symbol candle aggregation service
 */
export class CandleAggregationService {
  private builders: Map<string, SymbolCandleBuilder> = new Map();

  /**
   * Process a tick for a symbol
   */
  processTick(tick: Tick): Map<Timeframe, OHLCV> {
    // Get or create builder for this symbol
    let builder = this.builders.get(tick.symbol);
    if (!builder) {
      builder = new SymbolCandleBuilder(tick.symbol);
      this.builders.set(tick.symbol, builder);
    }

    return builder.processTick(tick);
  }

  /**
   * Load historical candles for a symbol
   */
  loadHistoricalCandles(symbol: string, timeframe: Timeframe, candles: OHLCV[]): void {
    let builder = this.builders.get(symbol);
    if (!builder) {
      builder = new SymbolCandleBuilder(symbol);
      this.builders.set(symbol, builder);
    }

    builder.loadHistoricalCandles(timeframe, candles);
  }

  /**
   * Get candles for a symbol and timeframe
   */
  getCandles(symbol: string, timeframe: Timeframe, includeForming: boolean = true): OHLCV[] {
    const builder = this.builders.get(symbol);
    return builder ? builder.getCandles(timeframe, includeForming) : [];
  }

  /**
   * Get last closed candle
   */
  getLastClosedCandle(symbol: string, timeframe: Timeframe): OHLCV | null {
    const builder = this.builders.get(symbol);
    return builder ? builder.getLastClosedCandle(timeframe) : null;
  }

  /**
   * Clear data for a symbol
   */
  clearSymbol(symbol: string): void {
    const builder = this.builders.get(symbol);
    if (builder) {
      builder.clear();
    }
  }

  /**
   * Get all symbols being tracked
   */
  getSymbols(): string[] {
    return Array.from(this.builders.keys());
  }
}

