/**
 * Command Bus Implementation
 * Centralized pub/sub system for RTX Terminal toolbar commands
 * Features:
 * - Type-safe command dispatching
 * - Command history tracking (last 100 commands)
 * - Event replay capability for debugging
 * - No memory leaks (WeakMap for cleanup)
 */

import type {
  Command,
  CommandType,
  CommandHandler,
  CommandBus,
  Unsubscribe,
  PayloadFor,
} from '../types/commands';

/**
 * Max number of commands to keep in history
 */
const HISTORY_MAX_SIZE = 100;

/**
 * CommandBusImpl - Singleton instance of the command bus
 * Uses Map-based subscription system for efficient handler management
 */
class CommandBusImpl implements CommandBus {
  private handlers: Map<CommandType, Set<CommandHandler>> = new Map();
  private history: Command[] = [];
  private isReplaying = false;

  /**
   * Dispatch a command to all subscribed handlers
   */
  dispatch(command: Command): void {
    // Add to history
    this.history.push(command);
    if (this.history.length > HISTORY_MAX_SIZE) {
      this.history.shift();
    }

    // Log command in development
    if (process.env.NODE_ENV === 'development') {
      console.log(
        `[CommandBus] Dispatching: ${command.type}`,
        'payload:',
        command.payload
      );
    }

    // Get handlers for this command type
    const typeHandlers = this.handlers.get(command.type);
    // Also get wildcard handlers
    const wildcardHandlers = this.handlers.get('*' as CommandType);

    // Call type-specific handlers
    if (typeHandlers) {
      for (const handler of typeHandlers) {
        try {
          handler(command.payload);
        } catch (error) {
          console.error(
            `[CommandBus] Error in handler for ${command.type}:`,
            error
          );
        }
      }
    }

    // Call wildcard handlers with full command object
    if (wildcardHandlers) {
      for (const handler of wildcardHandlers) {
        try {
          (handler as any)(command);
        } catch (error) {
          console.error(
            `[CommandBus] Error in wildcard handler:`,
            error
          );
        }
      }
    }
  }

  /**
   * Subscribe to a specific command type
   * Returns an unsubscribe function for cleanup
   */
  subscribe<T extends CommandType>(
    type: T,
    handler: CommandHandler<T>
  ): Unsubscribe {
    // Get or create handler set for this type
    if (!this.handlers.has(type)) {
      this.handlers.set(type, new Set());
    }

    const typeHandlers = this.handlers.get(type)!;
    typeHandlers.add(handler as any);

    if (process.env.NODE_ENV === 'development') {
      console.log(
        `[CommandBus] Subscriber added for ${type} (total: ${typeHandlers.size})`
      );
    }

    // Return unsubscribe function
    return () => {
      const handlers = this.handlers.get(type);
      if (handlers) {
        handlers.delete(handler as any);

        if (process.env.NODE_ENV === 'development') {
          console.log(
            `[CommandBus] Subscriber removed for ${type} (remaining: ${handlers.size})`
          );
        }

        // Clean up empty handler sets
        if (handlers.size === 0) {
          this.handlers.delete(type);
        }
      }
    };
  }

  /**
   * Get command history
   */
  getHistory(): Command[] {
    return [...this.history]; // Return copy to prevent mutations
  }

  /**
   * Clear command history
   */
  clearHistory(): void {
    this.history = [];
    if (process.env.NODE_ENV === 'development') {
      console.log('[CommandBus] History cleared');
    }
  }

  /**
   * Replay a sequence of commands
   * Useful for debugging and testing
   */
  async replay(commands: Command[]): Promise<void> {
    if (this.isReplaying) {
      console.warn('[CommandBus] Replay already in progress');
      return;
    }

    this.isReplaying = true;

    try {
      if (process.env.NODE_ENV === 'development') {
        console.log(`[CommandBus] Starting replay of ${commands.length} commands`);
      }

      for (const command of commands) {
        this.dispatch(command);
        // Small delay to allow async handlers to complete
        await new Promise((resolve) => setTimeout(resolve, 0));
      }

      if (process.env.NODE_ENV === 'development') {
        console.log('[CommandBus] Replay completed');
      }
    } finally {
      this.isReplaying = false;
    }
  }

  /**
   * Get current number of subscribers for a command type
   * Useful for debugging
   */
  getSubscriberCount(type: CommandType): number {
    return this.handlers.get(type)?.size ?? 0;
  }

  /**
   * Get all subscribed command types
   * Useful for debugging
   */
  getSubscribedTypes(): CommandType[] {
    return Array.from(this.handlers.keys());
  }
}

/**
 * Singleton instance of the command bus
 * This is the central dispatcher for all commands
 */
export const commandBus = new CommandBusImpl();

/**
 * Helper function to dispatch a command
 * Shorthand for commandBus.dispatch()
 */
export function dispatchCommand(command: Command): void {
  commandBus.dispatch(command);
}

/**
 * Helper function to get command history
 * Shorthand for commandBus.getHistory()
 */
export function getCommandHistory(): Command[] {
  return commandBus.getHistory();
}

/**
 * Helper function to clear command history
 * Shorthand for commandBus.clearHistory()
 */
export function clearCommandHistory(): void {
  commandBus.clearHistory();
}

/**
 * Helper function to replay commands
 * Shorthand for commandBus.replay()
 */
export function replayCommands(commands: Command[]): Promise<void> {
  return commandBus.replay(commands);
}

/**
 * Data Folder Manager Service
 * Handles access to user data folder with platform detection (web/desktop/Electron)
 */

import { buildApiUrl } from '../config/api';

export interface DataFolderStructure {
  profiles: string;
  templates: string;
  logs: string;
  cache: string;
  indicators: string;
  drawings: string;
  workspaces: string;
}

export interface FileEntry {
  name: string;
  path: string;
  type: 'file' | 'directory';
  size?: number;
  modified?: Date;
}

export type Platform = 'web' | 'desktop' | 'electron';

class DataFolderManager {
  private platform: Platform = 'web';
  private dataFolderPath: string = '';

  constructor() {
    this.detectPlatform();
  }

  /**
   * Detect current platform (web browser, desktop PWA, or Electron)
   */
  private detectPlatform(): void {
    // Check if running in Electron
    if (typeof window !== 'undefined' && (window as any).electron) {
      this.platform = 'electron';
      return;
    }

    // Check if running as PWA/standalone
    if (typeof window !== 'undefined' && window.matchMedia('(display-mode: standalone)').matches) {
      this.platform = 'desktop';
      return;
    }

    // Default to web
    this.platform = 'web';
  }

  /**
   * Get current platform
   */
  getPlatform(): Platform {
    return this.platform;
  }

  /**
   * Get data folder path from backend
   */
  async getDataFolderPath(): Promise<string> {
    if (this.dataFolderPath) {
      return this.dataFolderPath;
    }

    try {
      const response = await fetch(buildApiUrl('/api/user/data-folder'), {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error('Failed to get data folder path');
      }

      const data = await response.json();
      this.dataFolderPath = data.path || './user-data';
      return this.dataFolderPath;
    } catch (error) {
      console.error('[DataFolderManager] Error getting data folder path:', error);
      // Fallback to default path
      this.dataFolderPath = './user-data';
      return this.dataFolderPath;
    }
  }

  /**
   * Open data folder in OS file explorer (Electron only)
   */
  async openInExplorer(): Promise<boolean> {
    if (this.platform !== 'electron') {
      console.warn('[DataFolderManager] openInExplorer only works in Electron');
      return false;
    }

    try {
      const path = await this.getDataFolderPath();

      // Call Electron API to open path
      if ((window as any).electron?.shell?.openPath) {
        const result = await (window as any).electron.shell.openPath(path);
        if (result) {
          console.error('[DataFolderManager] Failed to open path:', result);
          return false;
        }
        return true;
      }

      console.error('[DataFolderManager] Electron shell API not available');
      return false;
    } catch (error) {
      console.error('[DataFolderManager] Error opening folder:', error);
      return false;
    }
  }

  /**
   * List files in data folder (or subfolder)
   */
  async listFiles(subfolder?: keyof DataFolderStructure): Promise<FileEntry[]> {
    try {
      const basePath = await this.getDataFolderPath();
      const targetPath = subfolder ? `${basePath}/${subfolder}` : basePath;

      const response = await fetch(buildApiUrl(`/api/user/data-folder/list?path=${encodeURIComponent(targetPath)}`), {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error('Failed to list files');
      }

      const data = await response.json();
      return data.files || [];
    } catch (error) {
      console.error('[DataFolderManager] Error listing files:', error);
      return [];
    }
  }

  /**
   * Download a file from data folder
   */
  async downloadFile(filePath: string): Promise<Blob | null> {
    try {
      const response = await fetch(buildApiUrl(`/api/user/data-folder/download?path=${encodeURIComponent(filePath)}`), {
        method: 'GET',
      });

      if (!response.ok) {
        throw new Error('Failed to download file');
      }

      return await response.blob();
    } catch (error) {
      console.error('[DataFolderManager] Error downloading file:', error);
      return null;
    }
  }

  /**
   * Upload a file to data folder
   */
  async uploadFile(file: File, subfolder?: keyof DataFolderStructure): Promise<boolean> {
    try {
      const basePath = await this.getDataFolderPath();
      const targetPath = subfolder ? `${basePath}/${subfolder}` : basePath;

      const formData = new FormData();
      formData.append('file', file);
      formData.append('path', targetPath);

      const response = await fetch(buildApiUrl('/api/user/data-folder/upload'), {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        throw new Error('Failed to upload file');
      }

      return true;
    } catch (error) {
      console.error('[DataFolderManager] Error uploading file:', error);
      return false;
    }
  }

  /**
   * Delete a file from data folder
   */
  async deleteFile(filePath: string): Promise<boolean> {
    try {
      const response = await fetch(buildApiUrl('/api/user/data-folder/delete'), {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ path: filePath }),
      });

      if (!response.ok) {
        throw new Error('Failed to delete file');
      }

      return true;
    } catch (error) {
      console.error('[DataFolderManager] Error deleting file:', error);
      return false;
    }
  }

  /**
   * Create directory in data folder
   */
  async createDirectory(dirPath: string): Promise<boolean> {
    try {
      const response = await fetch(buildApiUrl('/api/user/data-folder/mkdir'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ path: dirPath }),
      });

      if (!response.ok) {
        throw new Error('Failed to create directory');
      }

      return true;
    } catch (error) {
      console.error('[DataFolderManager] Error creating directory:', error);
      return false;
    }
  }

  /**
   * Get folder structure
   */
  getFolderStructure(): DataFolderStructure {
    return {
      profiles: 'profiles',
      templates: 'templates',
      logs: 'logs',
      cache: 'cache',
      indicators: 'indicators',
      drawings: 'drawings',
      workspaces: 'workspaces',
    };
  }
}

