/**
 * Drawing Manager
 * Manages chart drawings (trendlines, horizontal/vertical lines, text annotations)
 */

import type { IChartApi, ISeriesApi } from 'lightweight-charts';
import { API_ENDPOINTS } from '../config/api';
import { drawingApi, ClientDrawing } from './drawingApi';

/**
 * Safe localStorage setter with quota exceeded handling
 * Trims to last 100 items if quota exceeded and retries
 * @param key - localStorage key
 * @param value - JSON string to store
 * @returns boolean indicating success
 */
function safeSetItem(key: string, value: string): boolean {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch (e) {
    if (e instanceof DOMException && e.name === 'QuotaExceededError') {
      console.error('localStorage quota exceeded for key:', key);
      try {
        const parsed = JSON.parse(value);
        if (Array.isArray(parsed) && parsed.length > 100) {
          const trimmed = parsed.slice(-100);
          localStorage.setItem(key, JSON.stringify(trimmed));
          alert('Storage limit reached. Older drawings trimmed to last 100.');
          return false;
        }
      } catch (parseError) {
        console.error('Failed to parse or trim storage data:', parseError);
      }
    }
    console.error('Failed to save to localStorage:', e);
    return false;
  }
}

export type DrawingType = 'trendline' | 'hline' | 'vline' | 'text' | 'channel' | 'fibonacci' | 'shapes' | 'rectangle' | 'ellipse' | 'fib_extension' | 'measure' | 'freehand' | 'callout';

export interface DrawingPoint {
  time: number;
  price: number;
}

export interface Drawing {
  id: string;
  type: DrawingType;
  subtype?: string;
  points: DrawingPoint[];
  text?: string;
  color?: string;
  lineWidth?: number;
  lineStyle?: 'solid' | 'dashed' | 'dotted';
  selected?: boolean;
  locked?: boolean;
}

export interface DrawingHistory {
  action: 'delete' | 'add' | 'modify';
  drawing?: Drawing;
  oldDrawing?: Drawing;
  newDrawing?: Drawing;
}

const VALID_DRAWING_TYPES: DrawingType[] = [
  'trendline', 'hline', 'vline', 'text', 'channel',
  'fibonacci', 'shapes', 'rectangle', 'ellipse',
  'fib_extension', 'measure', 'freehand', 'callout'
];

function isValidDrawingType(value: unknown): value is DrawingType {
  return typeof value === 'string' && VALID_DRAWING_TYPES.includes(value as DrawingType);
}

function isValidDrawingPoint(value: unknown): value is DrawingPoint {
  if (!value || typeof value !== 'object') return false;
  const point = value as DrawingPoint;
  return (
    typeof point.time === 'number' &&
    Number.isFinite(point.time) &&
    typeof point.price === 'number' &&
    Number.isFinite(point.price)
  );
}

function isValidDrawing(value: unknown): value is Drawing {
  if (!value || typeof value !== 'object') return false;
  const drawing = value as Drawing;
  return (
    typeof drawing.id === 'string' &&
    drawing.id.length > 0 &&
    isValidDrawingType(drawing.type) &&
    Array.isArray(drawing.points) &&
    drawing.points.every(isValidDrawingPoint)
  );
}

function sanitizeDrawings(value: unknown, sourceLabel: string): Drawing[] {
  if (!Array.isArray(value)) {
    return [];
  }

  const valid = value.filter(isValidDrawing);
  if (valid.length < value.length) {
    console.warn(
      `[DrawingManager] Filtered out ${value.length - valid.length} invalid drawing(s) from ${sourceLabel}`,
    );
  }
  return valid;
}

export class DrawingManager {
  private drawings: Drawing[] = [];
  private activeDrawing: Drawing | null = null;
  private chart: IChartApi | null = null;
  private series: ISeriesApi<any> | null = null;
  private container: HTMLElement | null = null;
  private overlayElements: Map<string, HTMLElement> = new Map();
  private currentSymbol: string | null = null;
  private currentAccountId: number = 1;
  private undoStack: DrawingHistory[] = [];
  private redoStack: DrawingHistory[] = [];
  private magnetEnabled: boolean = false;

  // Dragging state
  private draggingDrawingId: string | null = null;
  private draggingNodeIndex: number | null = null;
  private dragStartPos: { x: number; y: number } | null = null;
  private dragInitialPoints: DrawingPoint[] = [];

  constructor() {
    this.setupGlobalListeners();
  }

  private pushUndo(history: DrawingHistory): void {
    this.undoStack.push(history);
    this.redoStack = []; // Clear redo stack on new action
  }

  private persistToStorageIfAvailable(): void {
    if (!this.currentSymbol) return;
    this.saveToStorage(this.currentSymbol);
  }

  private setupGlobalListeners(): void {
    window.addEventListener('pointermove', this.handlePointerMove.bind(this));
    window.addEventListener('pointerup', this.handlePointerUp.bind(this));

    // Shortcut events
    window.addEventListener('chart-undo-drawing', () => this.undo());
    window.addEventListener('chart-redo-drawing', () => this.redo());
    window.addEventListener('chart-delete-drawing', () => this.deleteSelected());
  }

  /**
   * Set the chart and series references
   */
  setChart(chart: IChartApi | null, series: ISeriesApi<any> | null, symbol: string | null = null, accountId: number = 1, overlayContainer?: HTMLElement | null): void {
    this.chart = chart;
    this.series = series;
    this.currentAccountId = accountId;

    // Always update the container reference
    if (overlayContainer) {
      this.container = overlayContainer;
    }

    // Clear overlay immediately
    this.clearOverlay();

    if (symbol && symbol !== this.currentSymbol) {
      // Symbol changed: clear old drawings, then load new ones
      this.currentSymbol = symbol;
      this.drawings = [];
      this.overlayElements.clear();
      // loadFromBackend will call renderAllDrawings when data is ready
      this.loadFromBackend(symbol);
    } else if (this.chart && this.drawings.length > 0) {
      // Same symbol, just re-render existing drawings
      this.renderAllDrawings();
    }
  }

  /**
   * Clear all DOM elements from the overlay container
   */
  private clearOverlay(): void {
    const container = this.container || document.querySelector('.chart-drawing-overlay');
    if (container) {
      while (container.firstChild) {
        container.removeChild(container.firstChild);
      }
    }
    this.overlayElements.clear();
  }


  /**
   * Set magnet mode
   */
  setMagnetEnabled(enabled: boolean): void {
    this.magnetEnabled = enabled;
  }

  /**
   * Start a new drawing
   */
  startDrawing(type: DrawingType, color: string = '#3b82f6', subtype?: string): string {
    const id = `drawing-${Date.now()}`;

    this.activeDrawing = {
      id,
      type,
      subtype,
      points: [],
      color,
      lineWidth: 2
    };

    return id;
  }

  /**
   * Update the active drawing properties
   */
  updateActiveDrawing(props: Partial<Drawing>): void {
    if (this.activeDrawing) {
      this.activeDrawing = { ...this.activeDrawing, ...props };
    }
  }

  /**
   * Add a point to the active drawing
   */
  addPoint(time: number, price: number, seriesData?: { open?: number; high?: number; low?: number; close?: number }): boolean {
    if (!this.activeDrawing) return false;

    let finalPrice = price;
    if (this.magnetEnabled && seriesData) {
      const prices = [seriesData.open, seriesData.high, seriesData.low, seriesData.close].filter(p => p !== undefined) as number[];
      if (prices.length > 0) {
        finalPrice = prices.reduce((prev, curr) => Math.abs(curr - price) < Math.abs(prev - price) ? curr : prev);
      }
    }

    this.activeDrawing.points.push({ time, price: finalPrice });

    // Check if drawing is complete
    const isComplete = this.isDrawingComplete(this.activeDrawing);

    if (isComplete) {
      this.finishDrawing();
    }

    return isComplete;
  }

  /**
   * Check if a drawing is complete based on its type
   */
  private isDrawingComplete(drawing: Drawing): boolean {
    switch (drawing.type) {
      case 'hline':
      case 'vline':
      case 'shapes':
      case 'text':
        return drawing.points.length >= 1;
      case 'trendline':
      case 'channel':
      case 'fibonacci':
      case 'rectangle':
      case 'ellipse':
      case 'measure':
        return drawing.points.length >= 2;
      case 'fib_extension':
        return drawing.points.length >= 3;
      case 'callout':
        return drawing.points.length >= 2;
      case 'freehand':
        return false; // Handled specially on pointer/mouse up
      default:
        return false;
    }
  }

  /**
   * Finish the active drawing
   */
  finishDrawing(): Drawing | null {
    if (!this.activeDrawing) return null;

    const completedDrawing = { ...this.activeDrawing, selected: false };
    this.drawings.push(completedDrawing);
    this.activeDrawing = null;

    // Push to undo stack
    this.pushUndo({ action: 'add', drawing: JSON.parse(JSON.stringify(completedDrawing)) });

    // Re-render all drawings (clean render, no duplicates)
    this.renderAllDrawings();

    // Save to backend
    this.saveToBackend(completedDrawing);
    this.persistToStorageIfAvailable();

    // Dispatch event for saving
    window.dispatchEvent(new CustomEvent('drawing:saved', {
      detail: completedDrawing
    }));

    return completedDrawing;
  }

  /**
   * Cancel the active drawing
   */
  cancelDrawing(): void {
    this.activeDrawing = null;
  }

  /**
   * Selection Management
   */
  selectDrawing(id: string, multiple: boolean = false): void {
    if (!multiple) {
      this.drawings.forEach(d => d.selected = false);
    }
    const drawing = this.drawings.find(d => d.id === id);
    if (drawing) {
      drawing.selected = true;
      // Bring selected to front
      const index = this.drawings.indexOf(drawing);
      this.drawings.splice(index, 1);
      this.drawings.push(drawing);
    }
    this.renderAllDrawings();
  }

  unselectAll(): void {
    // Defensive: Ensure drawings is an array
    if (!Array.isArray(this.drawings)) {
      this.drawings = [];
      return;
    }
    this.drawings.forEach(d => d.selected = false);
    this.renderAllDrawings();
  }

  unselectDrawing(id: string): void {
    const drawing = this.drawings.find(d => d.id === id);
    if (drawing) {
      drawing.selected = false;
    }
    this.renderAllDrawings();
  }

  /**
   * Delete Operations
   */
  deleteDrawing(id: string): boolean {
    const index = this.drawings.findIndex(d => d.id === id);

    if (index === -1) return false;

    // CRITICAL: Extract serverId BEFORE removing from array
    const serverId = (this.drawings[index] as any)?.serverId;
    const removed = this.drawings.splice(index, 1)[0];
    this.pushUndo({ action: 'delete', drawing: JSON.parse(JSON.stringify(removed)) });

    // Remove backend record (pass serverId directly since drawing is already removed from array)
    this.deleteFromBackend(id, serverId);

    // Remove overlay element
    const element = this.overlayElements.get(id);
    if (element && element.parentNode) {
      element.parentNode.removeChild(element);
    }
    this.overlayElements.delete(id);

    // Dispatch event
    window.dispatchEvent(new CustomEvent('drawing:deleted', {
      detail: { id }
    }));

    this.renderAllDrawings(); // Re-render to clear nodes
    this.persistToStorageIfAvailable();
    return true;
  }

  /**
   * Drag & Drop Logic
   */
  private handlePointerDown(e: PointerEvent, id: string, nodeIndex: number | null = null): void {
    console.log('[DrawingManager] POINTER DOWN on drawing:', id, 'nodeIndex:', nodeIndex);
    e.stopPropagation();
    e.preventDefault();
    const drawing = this.drawings.find(d => d.id === id);
    if (!drawing || drawing.locked) {
      console.log('[DrawingManager] Drawing not found or locked:', id);
      return;
    }

    console.log('[DrawingManager] Selecting drawing:', id);
    this.selectDrawing(id, e.ctrlKey || e.metaKey);

    this.draggingDrawingId = id;
    this.draggingNodeIndex = nodeIndex;
    this.dragStartPos = { x: e.clientX, y: e.clientY };
    this.dragInitialPoints = JSON.parse(JSON.stringify(drawing.points));
    (this as any).dragInitialDrawing = JSON.parse(JSON.stringify(drawing));
  }

  private handlePointerMove(e: PointerEvent): void {
    if (!this.draggingDrawingId || !this.dragStartPos || !this.chart || !this.series) return;

    const drawing = this.drawings.find(d => d.id === this.draggingDrawingId);
    if (!drawing) return;

    const dx = e.clientX - this.dragStartPos.x;
    const dy = e.clientY - this.dragStartPos.y;

    if (this.draggingNodeIndex !== null) {
      // Move single node
      const point = drawing.points[this.draggingNodeIndex];
      const initialPoint = this.dragInitialPoints[this.draggingNodeIndex];

      const x = this.chart.timeScale().timeToCoordinate(initialPoint.time as any);
      const y = this.series.priceToCoordinate(initialPoint.price);

      if (x !== null && y !== null) {
        const newX = x + dx;
        const newY = y + dy;

        const newTime = this.chart.timeScale().coordinateToTime(newX);
        const newPrice = this.series.coordinateToPrice(newY);

        if (newTime !== null && newPrice !== null) {
          point.time = newTime as number;
          point.price = newPrice;
        }
      }
    } else {
      // Move entire drawing
      drawing.points = this.dragInitialPoints.map(p => {
        const x = this.chart!.timeScale().timeToCoordinate(p.time as any);
        const y = this.series!.priceToCoordinate(p.price);

        if (x !== null && y !== null) {
          const newX = x + dx;
          const newY = y + dy;
          const newTime = this.chart!.timeScale().coordinateToTime(newX);
          const newPrice = this.series!.coordinateToPrice(newY);

          if (newTime !== null && newPrice !== null) {
            return { time: newTime as number, price: newPrice };
          }
        }
        return p;
      });
    }

    this.renderAllDrawings();
  }

  private handlePointerUp(): void {
    if (this.draggingDrawingId) {
      const drawing = this.drawings.find(d => d.id === this.draggingDrawingId);
      if (drawing) {
        if (JSON.stringify(drawing.points) !== JSON.stringify(this.dragInitialPoints)) {
          this.pushUndo({
            action: 'modify',
            oldDrawing: (this as any).dragInitialDrawing,
            newDrawing: JSON.parse(JSON.stringify(drawing))
          });
        }
        this.saveToBackend(drawing);
        this.persistToStorageIfAvailable();
      }
    }
    this.draggingDrawingId = null;
    this.draggingNodeIndex = null;
    this.dragStartPos = null;
    this.dragInitialPoints = [];
    (this as any).dragInitialDrawing = null;
  }

  deleteSelected(): void {
    const toDelete = this.drawings.filter(d => d.selected);
    console.log(`[DrawingManager] deleteSelected: found ${toDelete.length} selected drawings out of ${this.drawings.length} total`);
    if (toDelete.length === 0) {
      console.warn('[DrawingManager] deleteSelected: No drawings are selected! Drawings:', this.drawings.map(d => ({ id: d.id, selected: d.selected })));
      return;
    }
    const deleteInfo = toDelete.map(d => ({ id: d.id, serverId: (d as any)?.serverId }));
    deleteInfo.forEach(info => {
      // Find index fresh each time since array shifts after each splice
      const idx = this.drawings.findIndex(d => d.id === info.id);
      if (idx !== -1) {
        const removed = this.drawings.splice(idx, 1)[0];
        this.pushUndo({ action: 'delete', drawing: JSON.parse(JSON.stringify(removed)) });
        this.deleteFromBackend(info.id, info.serverId);
        const element = this.overlayElements.get(info.id);
        if (element && element.parentNode) element.parentNode.removeChild(element);
        this.overlayElements.delete(info.id);
      }
    });
    this.renderAllDrawings();
    this.persistToStorageIfAvailable();
  }

  deleteByType(type: DrawingType): void {
    const toDelete = this.drawings.filter(d => d.type === type);
    toDelete.forEach(d => this.deleteDrawing(d.id));
  }

  undoDelete(): void {
    this.undo(); // Fallback for existing components
  }

  undo(): void {
    const last = this.undoStack.pop();
    if (!last) return;

    if (last.action === 'add' && last.drawing) {
      const idx = this.drawings.findIndex(d => d.id === last.drawing!.id);
      if (idx !== -1) {
        this.drawings.splice(idx, 1);
        this.deleteFromBackend(last.drawing.id);
      }
    } else if (last.action === 'delete' && last.drawing) {
      this.drawings.push(last.drawing);
      this.saveToBackend(last.drawing);
    } else if (last.action === 'modify' && last.oldDrawing) {
      const idx = this.drawings.findIndex(d => d.id === last.oldDrawing!.id);
      if (idx !== -1) {
        this.drawings[idx] = last.oldDrawing;
        this.saveToBackend(last.oldDrawing);
      }
    }

    this.redoStack.push(last);
    this.renderAllDrawings();
    this.persistToStorageIfAvailable();
  }

  redo(): void {
    const next = this.redoStack.pop();
    if (!next) return;

    if (next.action === 'add' && next.drawing) {
      this.drawings.push(next.drawing);
      this.saveToBackend(next.drawing);
    } else if (next.action === 'delete' && next.drawing) {
      const idx = this.drawings.findIndex(d => d.id === next.drawing!.id);
      if (idx !== -1) {
        this.drawings.splice(idx, 1);
        this.deleteFromBackend(next.drawing.id);
      }
    } else if (next.action === 'modify' && next.newDrawing) {
      const idx = this.drawings.findIndex(d => d.id === next.newDrawing!.id);
      if (idx !== -1) {
        this.drawings[idx] = next.newDrawing;
        this.saveToBackend(next.newDrawing);
      }
    }

    this.undoStack.push(next);
    this.renderAllDrawings();
    this.persistToStorageIfAvailable();
  }

  /**
   * Clear all drawings
   */
  clearAllDrawings(persist: boolean = true): void {
    // Capture serverIds BEFORE clearing the array
    const deleteInfo = this.drawings.map(d => ({ id: d.id, serverId: (d as any)?.serverId }));
    this.drawings = [];
    this.activeDrawing = null;

    // Remove all overlay elements
    this.overlayElements.forEach(element => {
      if (element.parentNode) {
        element.parentNode.removeChild(element);
      }
    });
    this.overlayElements.clear();

    if (persist) {
      this.persistToStorageIfAvailable();
      // Permanently delete from backend so they don't return on next login
      deleteInfo.forEach(info => {
        if (info.serverId) {
          this.deleteFromBackend(info.id, info.serverId);
        }
      });
    }

    // Dispatch event
    window.dispatchEvent(new CustomEvent('drawings:cleared'));
  }

  /**
   * Get all drawings
   */
  getDrawings(): Drawing[] {
    return [...this.drawings];
  }

  /**
   * Get active drawing
   */
  getActiveDrawing(): Drawing | null {
    return this.activeDrawing ? { ...this.activeDrawing } : null;
  }

  /**
   * Render all drawings
   */
  renderAllDrawings(): void {
    const container = this.container || document.querySelector('.chart-drawing-overlay');

    // Clear ALL children from the overlay container to prevent orphaned DOM elements
    if (container) {
      while (container.firstChild) {
        container.removeChild(container.firstChild);
      }
    }
    this.overlayElements.clear();

    // Render each completed drawing
    this.drawings.forEach(drawing => {
      this.renderDrawing(drawing);
    });

    // Render active drawing preview
    if (this.activeDrawing && this.activeDrawing.points.length > 0 && this.previewPoint) {
      const previewDrawing = {
        ...this.activeDrawing,
        id: this.activeDrawing.id + '-preview',
        points: [...this.activeDrawing.points, this.previewPoint],
        selected: false
      };
      this.renderDrawing(previewDrawing);
    }
  }

  /**
   * Render a single drawing
   */
  private renderDrawing(drawing: Drawing): void {
    if (!this.chart || !this.series) return;

    const container = this.container || document.querySelector('.chart-drawing-overlay');
    if (!container) {
      console.warn('[DrawingManager] renderDrawing: No container found!');
      return;
    }

    const element = this.createDrawingElement(drawing);
    if (element) {
      container.appendChild(element);
      this.overlayElements.set(drawing.id, element);
      console.log(`[DrawingManager] Rendered drawing: ${drawing.id} type=${drawing.type} selected=${drawing.selected} element=`, element.style.cssText);

      // Add nodes for path-based drawings (Red Squares if selected)
      // Ensure points array exists before iterating
      if (Array.isArray(drawing.points)) {
        drawing.points.forEach((point, index) => {
          const node = document.createElement('div');
          node.className = `drawing-node drawing-node-${drawing.id} ${drawing.selected ? 'drawing-node-selected' : ''}`;

          // Selection state from MT5 image: red squares on endpoints
          if (drawing.selected) {
            node.style.display = 'block';
          } else {
            node.style.display = 'none';
          }

          const x = this.chart!.timeScale().timeToCoordinate(point.time as any);
          const y = this.series!.priceToCoordinate(point.price);

          if (x !== null && y !== null) {
            node.style.left = `${x}px`;
            node.style.top = `${y}px`;

            if (drawing.selected) {
              node.style.backgroundColor = '#ff0000'; // MT5 Red Square
              node.style.border = '1px solid #ffffff';
              node.style.width = '7px';
              node.style.height = '7px';
              node.style.borderRadius = '0'; // Square
            }

            node.addEventListener('pointerdown', (e) => this.handlePointerDown(e, drawing.id, index));
            container.appendChild(node);
          }
        });
      } // End of Array.isArray check

      // Add pointer down to the element itself for dragging entire drawing
      element.addEventListener('pointerdown', (e) => {
        console.log('[DrawingManager] Drawing element pointerdown event fired:', drawing.id, 'type:', drawing.type);
        this.handlePointerDown(e, drawing.id);
      });

      // Context menu listener
      element.addEventListener('contextmenu', (e) => {
        console.log('[DrawingManager] Drawing context menu event fired:', drawing.id);
        e.preventDefault();
        // Select the drawing on right-click too
        this.selectDrawing(drawing.id);
        window.dispatchEvent(new CustomEvent('drawing:contextmenu', {
          detail: { x: e.clientX, y: e.clientY, drawingId: drawing.id }
        }));
      });
    }
  }

  /**
   * Create HTML element for drawing
   */
  private createDrawingElement(drawing: Drawing): HTMLElement | null {
    // Defensive: Ensure both chart and series exist
    if (!this.chart || !this.series) return null;

    const div = document.createElement('div');
    div.className = 'chart-drawing';
    div.setAttribute('data-drawing-id', drawing.id);
    div.style.position = 'absolute';
    div.style.pointerEvents = 'auto';

    switch (drawing.type) {
      case 'hline':
        if (drawing.points.length > 0) {
          const y = this.series.priceToCoordinate(drawing.points[0].price);
          if (y !== null) {
            div.style.left = '0';
            div.style.right = '0';
            // Expand hit zone: 10px padding above and below the line
            div.style.top = `${y - 10}px`;
            div.style.height = `${(drawing.lineWidth || 2) + 20}px`;
            div.style.borderTop = '10px solid transparent';
            div.style.borderBottom = '10px solid transparent';
            div.style.backgroundClip = 'padding-box';
            div.style.backgroundColor = drawing.color || '#3b82f6';
            if (drawing.lineStyle === 'dashed') {
              div.style.backgroundColor = 'transparent';
              div.style.backgroundImage = `linear-gradient(to right, ${drawing.color || '#3b82f6'} 50%, transparent 50%)`;
              div.style.backgroundSize = '10px 100%';
            } else if (drawing.lineStyle === 'dotted') {
              div.style.backgroundColor = 'transparent';
              div.style.backgroundImage = `radial-gradient(${drawing.color || '#3b82f6'} 1px, transparent 1px)`;
              div.style.backgroundSize = '4px 100%';
            }
            div.style.cursor = drawing.locked ? 'default' : 'ns-resize';
          }
        }
        break;

      case 'vline':
        if (drawing.points.length > 0 && this.chart) {
          const x = this.chart.timeScale().timeToCoordinate(drawing.points[0].time as any);
          if (x !== null) {
            // Expand hit zone: 10px padding left and right
            div.style.left = `${x - 10}px`;
            div.style.top = '0';
            div.style.bottom = '0';
            div.style.width = `${(drawing.lineWidth || 2) + 20}px`;
            div.style.borderLeft = '10px solid transparent';
            div.style.borderRight = '10px solid transparent';
            div.style.backgroundClip = 'padding-box';
            div.style.backgroundColor = drawing.color || '#3b82f6';
            div.style.cursor = 'ew-resize';
          }
        }
        break;

      case 'trendline':
      case 'channel':
      case 'fibonacci':
        if (drawing.points.length >= 2 && this.chart) {
          const x1 = this.chart.timeScale().timeToCoordinate(drawing.points[0].time as any);
          const x2 = this.chart.timeScale().timeToCoordinate(drawing.points[1].time as any);
          const y1 = this.series.priceToCoordinate(drawing.points[0].price);
          const y2 = this.series.priceToCoordinate(drawing.points[1].price);

          if (x1 !== null && x2 !== null && y1 !== null && y2 !== null) {
            if (drawing.type === 'trendline') {
              const length = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
              const angle = Math.atan2(y2 - y1, x2 - x1) * (180 / Math.PI);

              div.style.width = `${length}px`;
              // Expand hit zone: 10px padding above and below the thin line
              div.style.height = `${(drawing.lineWidth || 2) + 20}px`;
              div.style.borderTop = '10px solid transparent';
              div.style.borderBottom = '10px solid transparent';
              div.style.backgroundClip = 'padding-box';
              div.style.backgroundColor = drawing.color || '#3b82f6';
              div.style.transformOrigin = 'left center';
              div.style.transform = `rotate(${angle}deg)`;
              div.style.left = `${x1}px`;
              div.style.top = `${y1 - 10}px`;
            } else if (drawing.type === 'fibonacci') {
              div.style.left = `${Math.min(x1, x2)}px`;
              div.style.top = `${Math.min(y1, y2)}px`;
              div.style.width = `${Math.abs(x2 - x1)}px`;
              div.style.height = `${Math.abs(y2 - y1)}px`;
              div.style.border = `1px dashed ${drawing.color || '#3b82f6'}`;
              div.style.backgroundColor = 'rgba(59, 130, 246, 0.1)';
            } else {
              // Channel
              div.style.left = `${Math.min(x1, x2)}px`;
              div.style.top = `${Math.min(y1, y2)}px`;
              div.style.width = `${Math.abs(x2 - x1)}px`;
              div.style.height = `${Math.abs(y2 - y1)}px`;
              div.style.border = `${drawing.lineWidth || 2}px solid ${drawing.color || '#3b82f6'}`;
            }
          }
        }
        break;

      case 'rectangle':
      case 'ellipse':
        if (drawing.points.length >= 2 && this.chart) {
          const x1 = this.chart.timeScale().timeToCoordinate(drawing.points[0].time as any);
          const x2 = this.chart.timeScale().timeToCoordinate(drawing.points[1].time as any);
          const y1 = this.series.priceToCoordinate(drawing.points[0].price);
          const y2 = this.series.priceToCoordinate(drawing.points[1].price);

          if (x1 !== null && x2 !== null && y1 !== null && y2 !== null) {
            div.style.left = `${Math.min(x1, x2)}px`;
            div.style.top = `${Math.min(y1, y2)}px`;
            div.style.width = `${Math.abs(x2 - x1)}px`;
            div.style.height = `${Math.abs(y2 - y1)}px`;
            div.style.border = `${drawing.lineWidth || 2}px solid ${drawing.color || '#3b82f6'}`;
            div.style.backgroundColor = 'rgba(59, 130, 246, 0.1)';

            if (drawing.type === 'ellipse') {
              div.style.borderRadius = '50%';
            }
          }
        }
        break;

      case 'fib_extension':
        if (drawing.points.length >= 3 && this.chart) {
          const x1 = this.chart.timeScale().timeToCoordinate(drawing.points[0].time as any);
          const x2 = this.chart.timeScale().timeToCoordinate(drawing.points[1].time as any);
          const x3 = this.chart.timeScale().timeToCoordinate(drawing.points[2].time as any);
          const y1 = this.series.priceToCoordinate(drawing.points[0].price);
          const y2 = this.series.priceToCoordinate(drawing.points[1].price);
          const y3 = this.series.priceToCoordinate(drawing.points[2].price);

          if (x1 !== null && x2 !== null && x3 !== null && y1 !== null && y2 !== null && y3 !== null) {
            const minX = Math.min(x1, x2, x3);
            const maxX = Math.max(x1, x2, x3);
            const minY = Math.min(y1, y2, y3);
            const maxY = Math.max(y1, y2, y3);

            div.style.left = `${minX}px`;
            div.style.top = `${minY}px`;
            div.style.width = `${Math.abs(maxX - minX)}px`;
            div.style.height = `${Math.abs(maxY - minY)}px`;
            div.style.border = `1px dashed ${drawing.color || '#10b981'}`;
            div.innerHTML = `<svg width="100%" height="100%" style="position:absolute;top:0;left:0;overflow:visible;">
                <polyline points="${x1 - minX},${y1 - minY} ${x2 - minX},${y2 - minY} ${x3 - minX},${y3 - minY}" fill="none" stroke="${drawing.color || '#10b981'}" stroke-width="${drawing.lineWidth || 2}" stroke-dasharray="4 4" />
            </svg>`;
          }
        }
        break;

      case 'measure':
        if (drawing.points.length >= 2 && this.chart) {
          const x1 = this.chart.timeScale().timeToCoordinate(drawing.points[0].time as any);
          const x2 = this.chart.timeScale().timeToCoordinate(drawing.points[1].time as any);
          const y1 = this.series.priceToCoordinate(drawing.points[0].price);
          const y2 = this.series.priceToCoordinate(drawing.points[1].price);

          if (x1 !== null && x2 !== null && y1 !== null && y2 !== null) {
            const minX = Math.min(x1, x2);
            const maxX = Math.max(x1, x2);
            const minY = Math.min(y1, y2);
            const maxY = Math.max(y1, y2);

            div.style.left = `${minX}px`;
            div.style.top = `${minY}px`;
            div.style.width = `${Math.max(1, maxX - minX)}px`;
            div.style.height = `${Math.max(1, maxY - minY)}px`;

            const price1 = drawing.points[0].price;
            const price2 = drawing.points[1].price;

            // Calculate bars difference
            const timeScale = this.chart.timeScale();
            const logical1 = timeScale.coordinateToLogical(x1);
            const logical2 = timeScale.coordinateToLogical(x2);
            const bars = (logical1 !== null && logical2 !== null) ? Math.round(Math.abs(logical2 - logical1)) : 0;

            // Calculate points and percentage
            const priceStr = price1.toString();
            // Estimate precision based on the price format
            const decimals = priceStr.includes('.') ? priceStr.split('.')[1].length : 5;
            const precision = Math.max(3, decimals >= 3 ? decimals : 5);
            const multiplier = Math.pow(10, precision);

            const pointsDiff = Math.round(Math.abs(price2 - price1) * multiplier);
            const percentChange = price1 !== 0 ? ((price2 - price1) / price1 * 100) : 0;
            const sign = percentChange > 0 ? '+' : '';

            const endPriceFormat = price2.toFixed(precision);
            const labelText = `${endPriceFormat}: ${bars} bars, ${pointsDiff} points, ${sign}${percentChange.toFixed(2)}%`;

            // Create SVG line and text label
            div.innerHTML = `<svg width="100%" height="100%" style="position:absolute;top:0;left:0;pointer-events:none;overflow:visible;">
                <line x1="${x1 - minX}" y1="${y1 - minY}" x2="${x2 - minX}" y2="${y2 - minY}" stroke="${drawing.color || '#d1d5db'}" stroke-width="${drawing.lineWidth || 1}" />
            </svg>
            <div style="position:absolute; left:${x2 - minX}px; top:${y2 - minY}px; transform:translate(${x2 >= x1 ? '8px' : 'calc(-100% - 8px)'}, ${y2 >= y1 ? '8px' : 'calc(-100% - 8px)'}); color:${drawing.color || '#d1d5db'}; font-size:11px; font-family:sans-serif; white-space:nowrap; text-shadow:1px 1px 0 #000, -1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000; pointer-events:none;">
                ${labelText}
            </div>`;
          }
        }
        break;

      case 'callout':
        if (drawing.points.length >= 2 && this.chart) {
          const x1 = this.chart.timeScale().timeToCoordinate(drawing.points[0].time as any);
          const x2 = this.chart.timeScale().timeToCoordinate(drawing.points[1].time as any);
          const y1 = this.series.priceToCoordinate(drawing.points[0].price);
          const y2 = this.series.priceToCoordinate(drawing.points[1].price);

          if (x1 !== null && x2 !== null && y1 !== null && y2 !== null) {
            const minX = Math.min(x1, x2);
            const maxX = Math.max(x1, x2);
            const minY = Math.min(y1, y2);
            const maxY = Math.max(y1, y2);

            div.style.left = `${minX}px`;
            div.style.top = `${minY}px`;
            div.style.width = `${maxX - minX}px`;
            div.style.height = `${maxY - minY}px`;

            div.innerHTML = `<svg width="100%" height="100%" style="position:absolute;top:0;left:0;pointer-events:none;overflow:visible;">
                <line x1="${x1 - minX}" y1="${y1 - minY}" x2="${x2 - minX}" y2="${y2 - minY}" stroke="${drawing.color || '#3b82f6'}" stroke-width="${drawing.lineWidth || 2}" />
            </svg>
            <div style="position:absolute; left:${x2 - minX}px; top:${y2 - minY}px; transform:translate(-50%, -50%); background:#18181b; color:${drawing.color || '#3b82f6'}; border:1px solid #3f3f46; border-radius:4px; padding:4px 8px; font-size:12px; font-weight:500; white-space:nowrap;">
                ${drawing.text || 'Callout text'}
            </div>`;
          }
        }
        break;

      case 'freehand':
        if (drawing.points.length >= 2 && this.chart && this.series) {
          const xs = drawing.points.map(p => this.chart!.timeScale().timeToCoordinate(p.time as any));
          const ys = drawing.points.map(p => this.series!.priceToCoordinate(p.price));

          if (xs.every(x => x !== null) && ys.every(y => y !== null)) {
            const minX = Math.min(...(xs as number[]));
            const maxX = Math.max(...(xs as number[]));
            const minY = Math.min(...(ys as number[]));
            const maxY = Math.max(...(ys as number[]));

            div.style.left = `${minX}px`;
            div.style.top = `${minY}px`;
            div.style.width = `${Math.max(1, maxX - minX)}px`;
            div.style.height = `${Math.max(1, maxY - minY)}px`;

            const pointsStr = xs.map((x, i) => `${(x as number) - minX},${(ys[i] as number) - minY}`).join(' ');

            div.innerHTML = `<svg width="100%" height="100%" style="position:absolute;top:0;left:0;overflow:visible;">
                    <polyline points="${pointsStr}" fill="none" stroke="${drawing.color || '#3b82f6'}" stroke-width="${drawing.lineWidth || 2}" stroke-linejoin="round" stroke-linecap="round" />
                </svg>`;
          }
        }
        break;

      case 'text':
        if (drawing.points.length > 0 && drawing.text && this.chart) {
          const x = this.chart.timeScale().timeToCoordinate(drawing.points[0].time as any);
          const y = this.series.priceToCoordinate(drawing.points[0].price);
          if (x !== null && y !== null) {
            div.style.left = `${x}px`;
            div.style.top = `${y}px`;
            div.style.color = drawing.color || '#3b82f6';
            div.style.fontSize = '12px';
            div.style.fontWeight = 'bold';
            div.style.padding = '4px 8px';
            div.style.backgroundColor = 'rgba(24, 24, 27, 0.9)';
            div.style.borderRadius = '4px';
            div.style.border = '1px solid #3f3f46';
            div.style.whiteSpace = 'nowrap';
            div.textContent = drawing.text;
          }
        }
        break;

      case 'shapes':
        if (drawing.points.length > 0 && this.chart) {
          const x = this.chart.timeScale().timeToCoordinate(drawing.points[0].time as any);
          const y = this.series.priceToCoordinate(drawing.points[0].price);
          if (x !== null && y !== null) {
            div.style.left = `${x}px`;
            div.style.top = `${y}px`;
            div.style.color = drawing.color || '#3b82f6';
            div.style.transform = 'translate(-50%, -50%)';
            div.innerHTML = `<div style="font-size: 20px;">${this.getSymbolForSubtype(drawing.subtype)}</div>`;
          }
        }
        break;
    }

    return div;
  }

  private getSymbolForSubtype(subtype?: string): string {
    switch (subtype) {
      case 'thumbs_up': return '≡ƒæì';
      case 'thumbs_down': return '≡ƒæÄ';
      case 'arrow_up': return 'Γåæ';
      case 'arrow_down': return 'Γåô';
      case 'stop': return '≡ƒ¢æ';
      case 'check': return 'Γ£à';
      case 'buy': return 'Γû▓';
      case 'sell': return 'Γû╝';
      case 'arrow': return 'Γ₧ö';
      default: return 'ΓùÅ';
    }
  }

  private previewPoint: DrawingPoint | null = null;

  updatePreviewPoint(time: number, price: number): void {
    if (!this.activeDrawing || this.activeDrawing.points.length === 0) {
      this.previewPoint = null;
      return;
    }
    this.previewPoint = { time, price };
    this.renderAllDrawings();
  }



  /**
   * Update drawings on chart scroll/zoom
   */
  updateDrawingPositions(): void {
    // Defensive: Ensure chart and series exist before rendering
    if (!this.chart || !this.series) return;
    this.renderAllDrawings();
  }

  /**
   * Sync with backend
   */
  async saveToBackend(drawing: Drawing): Promise<void> {
    if (!this.currentSymbol) return;

    try {
      // Use the new API service
      const serverId = await drawingApi.saveDrawing(drawing as ClientDrawing, this.currentSymbol);

      // Store server ID on the drawing for future updates/deletes
      const index = this.drawings.findIndex(d => d.id === drawing.id);
      if (index !== -1) {
        (this.drawings[index] as any).serverId = serverId;
      }

      console.log('[DrawingManager] Saved to backend:', serverId);
    } catch (error) {
      console.error('[DrawingManager] Failed to save to backend:', error);
      this.saveToStorage(this.currentSymbol);
    }
  }

  async loadFromBackend(symbol: string): Promise<void> {
    try {
      // Use the new API service
      const drawings = await drawingApi.loadDrawings(symbol);

      if (drawings.length > 0) {
        // ONE-TIME PURGE: Delete all old backend drawings for a fresh start
        // Remove this block after confirming clean state
        const shouldPurge = !sessionStorage.getItem('drawings_purged_' + symbol);
        if (shouldPurge) {
          console.log(`[DrawingManager] PURGING ${drawings.length} old drawings from backend for ${symbol}`);
          for (const d of drawings) {
            if (d.serverId) {
              try {
                await drawingApi.deleteDrawing(d.serverId);
                console.log('[DrawingManager] Purged backend drawing:', d.serverId);
              } catch (e) {
                console.warn('[DrawingManager] Failed to purge:', d.serverId);
              }
            }
          }
          sessionStorage.setItem('drawings_purged_' + symbol, '1');
          this.drawings = [];
          this.renderAllDrawings();
          this.persistToStorageIfAvailable();
          console.log(`[DrawingManager] All drawings purged for ${symbol}, starting fresh`);
          return;
        }

        // Normal load: Transform to Drawing format
        this.drawings = drawings.map(d => ({
          id: d.id,
          type: d.type as DrawingType,
          points: d.points,
          text: d.text,
          color: d.color,
          lineWidth: d.lineWidth,
          lineStyle: d.lineStyle,
          selected: false,
          locked: d.locked,
          subtype: d.subtype,
          serverId: d.serverId,
        }));

        this.renderAllDrawings();
        this.persistToStorageIfAvailable();
        console.log(`[DrawingManager] Loaded ${drawings.length} drawings from backend`);
      } else {
        // No backend drawings ΓÇö try localStorage as fallback
        this.loadFromStorage(symbol);
      }
    } catch (error) {
      console.warn('[DrawingManager] Backend unavailable, trying localStorage');
      this.loadFromStorage(symbol);
    }
  }

  async deleteFromBackend(id: string, passedServerId?: string): Promise<void> {
    try {
      // Use passed serverId first, then try to find it in the drawings array as fallback
      let serverId = passedServerId;
      if (!serverId) {
        const drawing = this.drawings.find(d => d.id === id);
        serverId = (drawing as any)?.serverId;
      }

      if (serverId) {
        await drawingApi.deleteDrawing(serverId);
        console.log('[DrawingManager] Deleted from backend:', serverId);
      } else {
        console.warn('[DrawingManager] No serverId found for drawing:', id, 'ΓÇö clearing from localStorage only');
      }

      // Also clear from localStorage to prevent zombie drawings
      if (this.currentSymbol) {
        this.saveToStorage(this.currentSymbol);
      }
    } catch (error) {
      console.error('[DrawingManager] Failed to delete from backend:', error);
      // Still clear from localStorage even if backend fails
      if (this.currentSymbol) {
        this.saveToStorage(this.currentSymbol);
      }
    }
  }

  /**
   * Fallback Storage
   */
  saveToStorage(symbol: string): void {
    safeSetItem(`drawings-${symbol}`, JSON.stringify(this.drawings));
  }

  loadFromStorage(symbol: string): void {
    try {
      const data = localStorage.getItem(`drawings-${symbol}`);
      if (data) {
        const parsed = JSON.parse(data);
        this.drawings = sanitizeDrawings(parsed, `localStorage symbol ${symbol}`);
        this.renderAllDrawings();
      } else {
        this.drawings = [];
        this.renderAllDrawings();
      }
    } catch (e) {
      console.error('Failed to load from local storage', e);
      // Reset to empty array on error
      this.drawings = [];
    }
  }
}

