/**
 * Exit Handler Service
 * Manages graceful application shutdown with unsaved changes detection
 */

import { useAppStore } from '../store/useAppStore';

export interface UnsavedChanges {
  hasWorkspaceChanges: boolean;
  hasOpenTrades: boolean;
  hasDraftOrders: boolean;
  openTradesCount: number;
  draftOrdersCount: number;
  workspaceModified: boolean;
}

export interface ExitPreferences {
  dontAskAgain: boolean;
  autoSaveWorkspace: boolean;
}

class ExitHandler {
  private isExiting = false;
  private cleanupTasks: Array<() => Promise<void> | void> = [];
  private preferences: ExitPreferences = {
    dontAskAgain: false,
    autoSaveWorkspace: false,
  };

  constructor() {
    this.loadPreferences();
    this.setupEventListeners();
  }

  /**
   * Load exit preferences from localStorage
   */
  private loadPreferences(): void {
    try {
      const stored = localStorage.getItem('exitPreferences');
      if (stored) {
        this.preferences = JSON.parse(stored);
      }
    } catch (error) {
      console.error('[ExitHandler] Failed to load preferences:', error);
    }
  }

  /**
   * Save exit preferences to localStorage
   */
  savePreferences(preferences: Partial<ExitPreferences>): void {
    this.preferences = { ...this.preferences, ...preferences };
    try {
      localStorage.setItem('exitPreferences', JSON.stringify(this.preferences));
    } catch (error) {
      console.error('[ExitHandler] Failed to save preferences:', error);
    }
  }

  /**
   * Get current exit preferences
   */
  getPreferences(): ExitPreferences {
    return { ...this.preferences };
  }

  /**
   * Setup event listeners for browser/window close
   */
  private setupEventListeners(): void {
    // Browser beforeunload event
    if (typeof window !== 'undefined') {
      window.addEventListener('beforeunload', this.handleBeforeUnload.bind(this));
    }

    // Electron app 'before-quit' event (if available)
    if (typeof window !== 'undefined' && (window as any).electron?.on) {
      (window as any).electron.on('before-quit', this.handleElectronQuit.bind(this));
    }
  }

  /**
   * Handle browser/window beforeunload event
   */
  private handleBeforeUnload(event: BeforeUnloadEvent): void {
    if (this.isExiting) {
      return;
    }

    const unsavedChanges = this.detectUnsavedChanges();

    if (this.hasUnsavedChanges(unsavedChanges) && !this.preferences.dontAskAgain) {
      // Show browser's native confirmation dialog
      event.preventDefault();
      event.returnValue = ''; // Chrome requires returnValue to be set
    }
  }

  /**
   * Handle Electron before-quit event
   */
  private async handleElectronQuit(event: any): Promise<void> {
    if (this.isExiting) {
      return;
    }

    const unsavedChanges = this.detectUnsavedChanges();

    if (this.hasUnsavedChanges(unsavedChanges) && !this.preferences.dontAskAgain) {
      // Prevent quit to show dialog
      event.preventDefault();

      // Show custom dialog (would be implemented in Electron main process)
      const shouldQuit = await this.showExitDialog(unsavedChanges);

      if (shouldQuit) {
        await this.performCleanup();
        // Allow quit
        if ((window as any).electron?.app?.quit) {
          (window as any).electron.app.quit();
        }
      }
    } else {
      await this.performCleanup();
    }
  }

  /**
   * Detect unsaved changes in application
   */
  detectUnsavedChanges(): UnsavedChanges {
    const state = useAppStore.getState();

    // Check for open positions
    const openTrades = state.positions || [];
    const hasOpenTrades = openTrades.length > 0;

    // Check for pending orders
    const draftOrders = state.orders?.filter(o => o.status === 'PENDING') || [];
    const hasDraftOrders = draftOrders.length > 0;

    // Check workspace modifications (check if current layout differs from saved)
    const workspaceModified = this.isWorkspaceModified();

    return {
      hasWorkspaceChanges: workspaceModified,
      hasOpenTrades,
      hasDraftOrders,
      openTradesCount: openTrades.length,
      draftOrdersCount: draftOrders.length,
      workspaceModified,
    };
  }

  /**
   * Check if there are any unsaved changes
   */
  private hasUnsavedChanges(changes: UnsavedChanges): boolean {
    return changes.hasWorkspaceChanges || changes.hasOpenTrades || changes.hasDraftOrders;
  }

  /**
   * Check if workspace has been modified since last save
   */
  private isWorkspaceModified(): boolean {
    try {
      const lastSaved = localStorage.getItem('lastWorkspaceSave');
      const currentState = localStorage.getItem('trading-app-storage');

      if (!lastSaved) {
        // No saved workspace - consider modified if there's any state
        return !!currentState;
      }

      return lastSaved !== currentState;
    } catch (error) {
      console.error('[ExitHandler] Error checking workspace modifications:', error);
      return false;
    }
  }

  /**
   * Show exit confirmation dialog
   * Returns true if should exit, false if canceled
   */
  async showExitDialog(changes: UnsavedChanges): Promise<boolean> {
    // This would trigger a React dialog component
    // For now, return a promise that resolves when user makes choice
    return new Promise((resolve) => {
      // Dispatch custom event that dialog component listens for
      window.dispatchEvent(new CustomEvent('showExitDialog', {
        detail: {
          changes,
          onConfirm: (saveWorkspace: boolean) => {
            if (saveWorkspace) {
              this.saveWorkspace();
            }
            resolve(true);
          },
          onCancel: () => resolve(false),
        }
      }));
    });
  }

  /**
   * Register a cleanup task to run on exit
   */
  registerCleanupTask(task: () => Promise<void> | void): void {
    this.cleanupTasks.push(task);
  }

  /**
   * Perform cleanup operations
   */
  async performCleanup(): Promise<void> {
    if (this.isExiting) {
      return;
    }

    this.isExiting = true;
    console.log('[ExitHandler] Starting cleanup...');

    try {
      // Close WebSocket connections
      await this.closeWebSocketConnections();

      // Cancel pending requests
      await this.cancelPendingRequests();

      // Clear sensitive data
      this.clearSensitiveData();

      // Run registered cleanup tasks
      for (const task of this.cleanupTasks) {
        try {
          await task();
        } catch (error) {
          console.error('[ExitHandler] Cleanup task failed:', error);
        }
      }

      // Auto-save workspace if preference is set
      if (this.preferences.autoSaveWorkspace) {
        this.saveWorkspace();
      }

      console.log('[ExitHandler] Cleanup completed');
    } catch (error) {
      console.error('[ExitHandler] Cleanup failed:', error);
    }
  }

  /**
   * Close WebSocket connections gracefully
   */
  private async closeWebSocketConnections(): Promise<void> {
    try {
      // Access WebSocket instance from global scope or store
      const ws = (window as any).tradingWebSocket;
      if (ws && ws.readyState === WebSocket.OPEN) {
        ws.close(1000, 'Application closing');
      }
    } catch (error) {
      console.error('[ExitHandler] Failed to close WebSocket:', error);
    }
  }

  /**
   * Cancel pending HTTP requests
   */
  private async cancelPendingRequests(): Promise<void> {
    // If using AbortController for fetch requests, abort them
    if ((window as any).pendingRequests) {
      for (const controller of (window as any).pendingRequests) {
        controller.abort();
      }
    }
  }

  /**
   * Clear sensitive data from memory and storage
   */
  private clearSensitiveData(): void {
    try {
      // Clear auth token from store
      useAppStore.getState().clearAuth();

      // Clear sensitive items from sessionStorage
      sessionStorage.removeItem('tempAuthToken');
      sessionStorage.removeItem('apiKeys');

      // Note: We keep localStorage for workspace/settings persistence
    } catch (error) {
      console.error('[ExitHandler] Failed to clear sensitive data:', error);
    }
  }

  /**
   * Save current workspace
   */
  private saveWorkspace(): void {
    try {
      const currentState = localStorage.getItem('trading-app-storage');
      if (currentState) {
        localStorage.setItem('lastWorkspaceSave', currentState);
        console.log('[ExitHandler] Workspace saved');
      }
    } catch (error) {
      console.error('[ExitHandler] Failed to save workspace:', error);
    }
  }

  /**
   * Initiate exit sequence (call this from UI)
   */
  async initiateExit(): Promise<boolean> {
    const unsavedChanges = this.detectUnsavedChanges();

    // If no changes or user doesn't want to be asked, exit immediately
    if (!this.hasUnsavedChanges(unsavedChanges) || this.preferences.dontAskAgain) {
      await this.performCleanup();
      return true;
    }

    // Show confirmation dialog
    const shouldExit = await this.showExitDialog(unsavedChanges);

    if (shouldExit) {
      await this.performCleanup();
      return true;
    }

    return false;
  }

  /**
   * Force exit without confirmation (emergency shutdown)
   */
  async forceExit(): Promise<void> {
    await this.performCleanup();

    // For web, redirect to logout/login
    if (typeof window !== 'undefined') {
      window.location.href = '/';
    }
  }

  /**
   * Logout and clear session
   */
  async logout(): Promise<void> {
    await this.performCleanup();

    // Clear all application state
    useAppStore.getState().reset();

    // Redirect to login
    if (typeof window !== 'undefined') {
      window.location.href = '/';
    }
  }
}

// Singleton instance
export const exitHandler = new ExitHandler();
export default exitHandler;

/**
 * Fix Market Data WebSocket Service
 * Handles connection to fixapibackend.tradecopier.org/ws
 * Message formats:
 * - Subscribe: {"type":"subscribe","symbols":["BTCUSD"]}
 * - Tick: {"type":"tick","symbol":"BTCUSD","bid":63985.98,"ask":63997.43,"spread":11.45,"timestamp":1772261088,"high24h":65556.13,"low24h":63523.63,"dailyChange":-2.31,"lp":"YOFX"}
 * - Candle: {"type":"update","symbol":"BTCUSD","candle":{"time":1772261040,"open":63922.955,"high":63991.705,"low":63921.995,"close":63991.705,"volume":223}}
 */

import { useMarketDataStore } from '../store/useMarketDataStore';

export type FixSocketState = 'connecting' | 'connected' | 'disconnected' | 'reconnecting' | 'error';

export interface FixTickMessage {
  type: 'tick';
  symbol: string;
  bid: number;
  ask: number;
  spread: number;
  timestamp: number;
  high24h: number;
  low24h: number;
  dailyChange: number;
  lp?: string;
}

export interface FixCandleMessage {
  type: 'update';
  symbol: string;
  candle: {
    time: number;
    open: number;
    high: number;
    low: number;
    close: number;
    volume: number;
  };
}

export type FixSocketMessage = FixTickMessage | FixCandleMessage;

type MessageHandler = (data: FixSocketMessage) => void;
type StateHandler = (state: FixSocketState) => void;

export class FixMarketDataSocket {
  private ws: WebSocket | null = null;
  private url: string;
  private subscribedSymbols: Set<string> = new Set();
  private messageHandlers: Set<MessageHandler> = new Set();
  private stateHandlers: Set<StateHandler> = new Set();
  private state: FixSocketState = 'disconnected';

  private reconnectAttempts = 0;
  private maxReconnectAttempts = 10;
  private baseReconnectDelay = 1000;
  private maxReconnectDelay = 30000;
  private reconnectTimeout: ReturnType<typeof setTimeout> | null = null;
  private pingInterval: ReturnType<typeof setInterval> | null = null;

  constructor(url?: string) {
    this.url = url || import.meta.env.VITE_MARKET_WS_URL || 'wss://rtxbackend.tradecopier.org/fix-ws';
    this.url = url;
  }

  /**
   * Get current connection state
   */
  public getState(): FixSocketState {
    return this.state;
  }

  /**
   * Connect to WebSocket server
   */
  public connect(): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      console.log('[FixSocket] Already connected');
      return;
    }

    this.updateState('connecting');
    console.log(`[FixSocket] Connecting to ${this.url}...`);

    try {
      this.ws = new WebSocket(this.url);

      this.ws.onopen = () => {
        console.log('[FixSocket] Connected successfully');
        this.reconnectAttempts = 0;
        this.updateState('connected');
        this.startPingInterval();
        this.resubscribeSymbols();
      };

      this.ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data) as FixSocketMessage;
          this.handleMessage(data);
        } catch (error) {
          console.error('[FixSocket] Failed to parse message:', error);
        }
      };

      this.ws.onerror = (error) => {
        console.error('[FixSocket] Error:', error);
        this.updateState('error');
      };

      this.ws.onclose = (event) => {
        console.log(`[FixSocket] Connection closed (code: ${event.code})`);
        this.updateState('disconnected');
        this.stopPingInterval();
        this.attemptReconnect();
      };
    } catch (error) {
      console.error('[FixSocket] Connection failed:', error);
      this.updateState('error');
      this.attemptReconnect();
    }
  }

  /**
   * Disconnect from WebSocket server
   */
  public disconnect(): void {
    console.log('[FixSocket] Disconnecting...');

    if (this.reconnectTimeout) {
      clearTimeout(this.reconnectTimeout);
      this.reconnectTimeout = null;
    }

    this.stopPingInterval();

    if (this.ws) {
      this.ws.close(1000, 'Client initiated disconnect');
      this.ws = null;
    }

    this.reconnectAttempts = 0;
    this.updateState('disconnected');
  }

  /**
   * Subscribe to symbols
   */
  public subscribe(symbols: string[]): void {
    symbols.forEach(symbol => this.subscribedSymbols.add(symbol));

    if (this.ws?.readyState === WebSocket.OPEN) {
      this.sendSubscribeMessage(symbols);
    }
  }

  /**
   * Unsubscribe from symbols
   */
  public unsubscribe(symbols: string[]): void {
    symbols.forEach(symbol => this.subscribedSymbols.delete(symbol));

    // Note: Backend may not support unsubscribe, but we can stop tracking
    console.log(`[FixSocket] Unsubscribed from: ${symbols.join(', ')}`);
  }

  /**
   * Add message handler
   */
  public onMessage(handler: MessageHandler): () => void {
    this.messageHandlers.add(handler);
    return () => {
      this.messageHandlers.delete(handler);
    };
  }

  /**
   * Add state change handler
   */
  public onStateChange(handler: StateHandler): () => void {
    this.stateHandlers.add(handler);
    handler(this.state);
    return () => {
      this.stateHandlers.delete(handler);
    };
  }

  /**
   * Handle incoming messages
   */
  private handleMessage(data: FixSocketMessage): void {
    // Notify all registered handlers
    this.messageHandlers.forEach(handler => {
      try {
        handler(data);
      } catch (error) {
        console.error('[FixSocket] Handler error:', error);
      }
    });

    // Process tick messages
    if (data.type === 'tick') {
      this.processTick(data);
    }

    // Process candle update messages
    if (data.type === 'update' && data.candle) {
      this.processCandle(data);
    }
  }

  /**
   * Process tick message and update store
   */
  private processTick(tick: FixTickMessage): void {
    const { symbol, bid, ask, spread, timestamp, high24h, low24h, dailyChange, lp } = tick;

    // Convert timestamp to milliseconds if it's in seconds
    const ts = timestamp > 1000000000000 ? timestamp : timestamp * 1000;

    // Update MarketDataStore (OHLCV aggregation ΓÇö uses bid/ask/spread only)
    const store = useMarketDataStore.getState();
    store.updateTick(symbol, {
      symbol,
      bid,
      ask,
      spread,
      timestamp: ts,
      lp,
      volume: 1,
    });

    // Update AppStore with FULL tick including dailyChange, high24h, low24h
    // MarketWatchPanel reads from useAppStore.ticks for the Daily column
    import('../store/useAppStore').then(({ useAppStore }) => {
      useAppStore.getState().setTick(symbol, {
        symbol,
        bid,
        ask,
        spread,
        timestamp: ts,
        lp,
        volume: 1,
        dailyChange,   // already a % from broker (e.g. -2.31 = -2.31%)
        high24h,
        low24h,
      } as any);
    }).catch(err => {
      console.error('[FixSocket] Failed to update AppStore:', err);
    });
  }

  /**
   * Process candle message and update store
   */
  private processCandle(data: FixCandleMessage): void {
    const { symbol, candle } = data;

    // Update market data store with candle data
    const store = useMarketDataStore.getState();
    store.updateCandle({
      symbol,
      timeframe: 'M1', // Assuming 1-minute candles from backend
      open: candle.open,
      high: candle.high,
      low: candle.low,
      close: candle.close,
      volume: candle.volume,
      time: candle.time,
    });
  }

  /**
   * Send subscribe message to backend
   */
  private sendSubscribeMessage(symbols: string[]): void {
    if (this.ws?.readyState !== WebSocket.OPEN) return;

    const message = {
      type: 'subscribe',
      symbols: symbols,
    };

    console.log(`[FixSocket] Subscribing to: ${symbols.join(', ')}`);
    this.ws.send(JSON.stringify(message));
  }

  /**
   * Resubscribe to all symbols after reconnection
   */
  private resubscribeSymbols(): void {
    if (this.subscribedSymbols.size === 0) return;

    const symbols = Array.from(this.subscribedSymbols);
    console.log(`[FixSocket] Resubscribing to ${symbols.length} symbols`);
    this.sendSubscribeMessage(symbols);
  }

  /**
   * Start ping interval to keep connection alive
   */
  private startPingInterval(): void {
    if (this.pingInterval) return;

    // Send ping every 30 seconds
    this.pingInterval = setInterval(() => {
      if (this.ws?.readyState === WebSocket.OPEN) {
        // Send a ping message if backend supports it
        // Or rely on WebSocket native ping/pong
      }
    }, 30000);
  }

  /**
   * Stop ping interval
   */
  private stopPingInterval(): void {
    if (this.pingInterval) {
      clearInterval(this.pingInterval);
      this.pingInterval = null;
    }
  }

  /**
   * Attempt to reconnect with exponential backoff
   */
  private attemptReconnect(): void {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.error('[FixSocket] Max reconnect attempts reached');
      this.updateState('error');
      return;
    }

    this.reconnectAttempts++;
    this.updateState('reconnecting');

    const delay = Math.min(
      this.baseReconnectDelay * Math.pow(2, this.reconnectAttempts - 1),
      this.maxReconnectDelay
    );

    console.log(
      `[FixSocket] Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts}/${this.maxReconnectAttempts})`
    );

    this.reconnectTimeout = setTimeout(() => {
      this.connect();
    }, delay);
  }

  /**
   * Update connection state and notify listeners
   */
  private updateState(state: FixSocketState): void {
    if (this.state === state) return;

    console.log(`[FixSocket] State change: ${this.state} -> ${state}`);
    this.state = state;

    this.stateHandlers.forEach(handler => {
      try {
        handler(state);
      } catch (error) {
        console.error('[FixSocket] State handler error:', error);
      }
    });
  }

  /**
   * Cleanup resources
   */
  public destroy(): void {
    this.disconnect();
    this.messageHandlers.clear();
    this.stateHandlers.clear();
    this.subscribedSymbols.clear();
  }
}

