/**
 * MT5 Trade Service ΓÇö Axios-based direct trade execution
 * 
 * Connects to MT5 Sync C++ backend on port 8088.
 * No authentication required. All trades execute directly on MT5.
 */

import axios, { AxiosError } from 'axios';
import { useSystemJournalStore } from '../store/useSystemJournalStore';

// MT5 Sync backend base URL ΓÇö always call the real backend directly
const MT5_SYNC_BASE = import.meta.env.VITE_MT5_SYNC_URL || 'https://rtxbackend.tradecopier.org';

// ΓöÇΓöÇΓöÇ Request / Response Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export interface ExecuteTradeRequest {
    account_login: number;
    symbol: string;
    side: 'buy' | 'sell';
    volume_lots: number;
