/**
 * Enhanced WebSocket Service with Advanced Features
 * - Connection status monitoring
 * - Automatic reconnection with exponential backoff
 * - Message queue for offline mode
 * - Heartbeat/ping-pong mechanism
 * - Multi-symbol subscription management
 * - Performance metrics tracking
 */

export type SubscriptionCallback = (data: unknown) => void;
export type ConnectionStateCallback = (state: ConnectionState) => void;
export type MetricsCallback = (metrics: ConnectionMetrics) => void;

export type ConnectionState = 'connecting' | 'connected' | 'disconnected' | 'reconnecting' | 'error' | 'offline';

export interface WebSocketMessage {
  type: string;
  symbol?: string;
  channel?: string;
  data?: unknown;
  timestamp?: number;
  [key: string]: unknown;
}

export interface ConnectionMetrics {
  messagesSent: number;
  messagesReceived: number;
  reconnectAttempts: number;
  lastLatency: number;
  averageLatency: number;
  uptime: number;
  lastConnectedAt: number | null;
  lastDisconnectedAt: number | null;
}

interface QueuedMessage {
  message: WebSocketMessage;
  timestamp: number;
  retries: number;
}

export class EnhancedWebSocketService {
  private ws: WebSocket | null = null;
  private url: string;

  // Connection management
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 10;
  private baseReconnectDelay = 1000;
  private maxReconnectDelay = 30000;
  private reconnectTimeout: ReturnType<typeof setTimeout> | null = null;

  // Heartbeat/ping-pong
  private pingInterval: ReturnType<typeof setInterval> | null = null;
  private pongTimeout: ReturnType<typeof setTimeout> | null = null;
  private pingIntervalMs = 30000; // 30 seconds
  private pongTimeoutMs = 15000; // 15 seconds (generous for high-throughput tick broadcasting)
  private lastPongTime = 0;

  // Subscription management
  private subscribers: Map<string, Set<SubscriptionCallback>> = new Map();
  private stateListeners: Set<ConnectionStateCallback> = new Set();
  private metricsListeners: Set<MetricsCallback> = new Set();
  private connectionState: ConnectionState = 'disconnected';

  // Message buffering and throttling
  private tickBuffer: Map<string, WebSocketMessage> = new Map();
  private messageQueue: QueuedMessage[] = [];
  private maxQueueSize = 1000;
  private flushInterval: ReturnType<typeof setInterval> | null = null;
  // Keep flush loop effectively immediate for any buffered flows.
  private updateThrottleMs = 1;

  // Metrics tracking
  private metrics: ConnectionMetrics = {
    messagesSent: 0,
    messagesReceived: 0,
    reconnectAttempts: 0,
    lastLatency: 0,
    averageLatency: 0,
    uptime: 0,
    lastConnectedAt: null,
    lastDisconnectedAt: null,
  };
  private latencyMeasurements: number[] = [];
  private maxLatencyMeasurements = 100;
  private connectStartTime = 0;

  constructor(url: string) {
    this.url = this.normalizeWsUrl(url);

    // Listen to online/offline events
    if (typeof window !== 'undefined') {
      window.addEventListener('online', this.handleOnline);
      window.addEventListener('offline', this.handleOffline);
    }
  }

  /**
   * Connect to WebSocket server
   */
  public connect(): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      console.log('[WS] Already connected');
      return;
    }

    this.updateState('connecting');
    this.connectStartTime = Date.now();

    // Normalize URL at connect-time too (covers stale singleton/url overrides).
    this.url = this.normalizeWsUrl(this.url);

    // Get auth token and add to URL (only for rtxbackend, not fixapibackend)
    const token = localStorage.getItem('auth_token');
    const isFixApiBackend = this.url.includes('fixapibackend');
    const urlWithAuth = isFixApiBackend ? this.url : this.addTokenToUrl(this.url, token);

    console.log(`[WS] Connecting to ${this.url}...`);
    if (isFixApiBackend) {
      console.log('[WS] Using fixapibackend (no auth token)');
    }

    try {
      this.ws = new WebSocket(urlWithAuth);

      this.ws.onopen = () => {
        console.log('[WS] Connected successfully to', this.url);
        const latency = Date.now() - this.connectStartTime;
        this.recordLatency(latency);

        this.reconnectAttempts = 0;
        this.metrics.lastConnectedAt = Date.now();
        this.updateState('connected');
        this.startPingInterval();
        this.startFlushInterval();
        this.processMessageQueue();
        this.resubscribeChannels();
        this.notifyMetricsListeners();
      };

      this.ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data) as WebSocketMessage;
          // Log all incoming messages for debugging
          console.log(`[WS RAW] type=${data.type} symbol=${data.symbol || 'n/a'}`, data);
          this.handleMessage(data);
          this.metrics.messagesReceived++;
        } catch (error) {
          console.error('[WS] Failed to parse message:', error);
        }
      };

      this.ws.onerror = (error) => {
        console.error('[WS] Error:', error);
        this.updateState('error');
      };

      this.ws.onclose = (event) => {
        console.log(`[WS] Connection closed (code: ${event.code}, reason: ${event.reason})`);
        this.metrics.lastDisconnectedAt = Date.now();
        this.updateState('disconnected');
        this.stopPingInterval();
        this.stopFlushInterval();
        this.notifyMetricsListeners();

        // Check if close was due to authentication failure
        if (event.code === 1008 || event.code === 401) {
          console.error('[WS] Authentication failed - clearing token');
          localStorage.removeItem('auth_token');
          window.dispatchEvent(new CustomEvent('ws-auth-failed'));
          return;
        }

        this.attemptReconnect();
      };
    } catch (error) {
      console.error('[WS] Connection failed:', error);
      this.updateState('error');
      this.attemptReconnect();
    }
  }

  /**
   * Disconnect from WebSocket server
   */
  public disconnect(): void {
    console.log('[WS] Disconnecting...');

    if (this.reconnectTimeout) {
      clearTimeout(this.reconnectTimeout);
      this.reconnectTimeout = null;
    }

    this.stopPingInterval();
    this.stopFlushInterval();

    if (this.ws) {
      this.ws.close(1000, 'Client initiated disconnect');
      this.ws = null;
    }

    this.reconnectAttempts = 0;
    this.updateState('disconnected');
  }

  /**
   * Subscribe to a channel
   */
  public subscribe(channel: string, callback: SubscriptionCallback): () => void {
    if (!this.subscribers.has(channel)) {
      this.subscribers.set(channel, new Set());
    }

    this.subscribers.get(channel)!.add(callback);

    // Send subscription message if connected
    if (this.ws?.readyState === WebSocket.OPEN) {
      console.log(`[WS] Sending subscribe request for channel: ${channel}`);
      this.sendMessage({
        type: 'subscribe',
        channel,
      });
    } else {
      console.log(`[WS] Queued subscribe for ${channel} (not connected yet)`);
    }

    // Return unsubscribe function
    return () => {
      const callbacks = this.subscribers.get(channel);
      if (callbacks) {
        callbacks.delete(callback);
        if (callbacks.size === 0) {
          this.subscribers.delete(channel);
          this.sendMessage({
            type: 'unsubscribe',
            channel,
          });
        }
      }
    };
  }

  /**
   * Subscribe to market data symbols (fixapibackend format)
   * Format: {"type":"subscribe","symbols":["BTCUSD"]}
   */
  public subscribeSymbols(symbols: string[], callback: SubscriptionCallback): () => void {
    const channel = `symbols:${symbols.join(',')}`;

    if (!this.subscribers.has(channel)) {
      this.subscribers.set(channel, new Set());
    }

    this.subscribers.get(channel)!.add(callback);

    // Send subscription message if connected
    if (this.ws?.readyState === WebSocket.OPEN) {
      console.log(`[WS] Subscribing to symbols: ${symbols.join(', ')}`);
      this.sendMessage({
        type: 'subscribe',
        symbols,
      });
    } else {
      console.log(`[WS] Queued subscribe for symbols: ${symbols.join(', ')} (not connected yet)`);
    }

    // Return unsubscribe function
    return () => {
      const callbacks = this.subscribers.get(channel);
      if (callbacks) {
        callbacks.delete(callback);
        if (callbacks.size === 0) {
          this.subscribers.delete(channel);
          // Note: Backend may not support unsubscribe, but we stop tracking
        }
      }
    };
  }

  /**
   * Listen to connection state changes
   */
  public onStateChange(callback: ConnectionStateCallback): () => void {
    this.stateListeners.add(callback);
    callback(this.connectionState);

    return () => {
      this.stateListeners.delete(callback);
    };
  }

  /**
   * Listen to metrics updates
   */
  public onMetricsChange(callback: MetricsCallback): () => void {
    this.metricsListeners.add(callback);
    callback(this.metrics);

    return () => {
      this.metricsListeners.delete(callback);
    };
  }

  /**
   * Get current connection state
   */
  public getState(): ConnectionState {
    return this.connectionState;
  }

  /**
   * Get current metrics
   */
  public getMetrics(): ConnectionMetrics {
    return { ...this.metrics };
  }

  /**
   * Send message to WebSocket server (with offline queueing)
   */
  public sendMessage(message: WebSocketMessage): void {
    const messageStr = JSON.stringify(message);
    // Log ALL subscription messages with full details
    if (message.type === 'subscribe') {
      const symbols = (message as any).symbols;
      if (symbols && Array.isArray(symbols)) {
        console.log(`[WS] Sending subscribe for symbols: ${symbols.join(', ')}`);
      } else if (message.channel) {
        console.log(`[WS] Sending subscribe for channel: ${message.channel}`);
      }
    }
    if (this.ws?.readyState === WebSocket.OPEN) {
      try {
        this.ws.send(messageStr);
        this.metrics.messagesSent++;
      } catch (error) {
        console.error('[WS] Failed to send message:', error);
        this.queueMessage(message);
      }
    } else {
      if (message.type === 'subscribe' || message.type === 'unsubscribe') {
        console.log(`[WS] Queued ${message.type} (not connected)`);
      }
      this.queueMessage(message);
    }
  }

  /**
   * Queue message for later delivery
   */
  private queueMessage(message: WebSocketMessage): void {
    if (this.messageQueue.length >= this.maxQueueSize) {
      console.warn('[WS] Message queue full, dropping oldest message');
      this.messageQueue.shift();
    }

    this.messageQueue.push({
      message,
      timestamp: Date.now(),
      retries: 0,
    });
  }

  /**
   * Process queued messages when connection is restored
   */
  private processMessageQueue(): void {
    if (this.messageQueue.length === 0) return;

    console.log(`[WS] Processing ${this.messageQueue.length} queued messages`);

    const now = Date.now();
    const maxAge = 60000; // 1 minute

    this.messageQueue = this.messageQueue.filter((queued) => {
      // Drop messages older than maxAge
      if (now - queued.timestamp > maxAge) {
        console.warn('[WS] Dropping stale queued message');
        return false;
      }

      // Send message
      this.sendMessage(queued.message);
      return false; // Remove from queue
    });
  }

  /**
   * Handle incoming WebSocket messages
   */
  private handleMessage(data: WebSocketMessage): void {
    const { type } = data;

    // Handle pong responses
    if (type === 'pong') {
      this.handlePong();
      return;
    }

    // Process tick updates immediately for lowest-latency UI updates.
    // Supports fixapibackend format: {type: 'tick', symbol, bid, ask, ...}
    if (type === 'tick' && data.symbol) {
      this.handleFixTick(data);
      this.broadcastToSubscribers(data);
      return;
    }

    // Handle candle update messages from fixapibackend
    // Format: {type: 'update', symbol, candle: {time, open, high, low, close, volume}}
    if (type === 'update' && data.candle && data.symbol) {
      this.handleFixCandle(data);
      this.broadcastToSubscribers(data);
      return;
    }

    // Handle MT5 real-time updates - update store directly
    if (type === 'mt5_positions' || type === 'mt5_orders' || type === 'mt5_account') {
      this.handleMT5Update(data);
      // Also broadcast to subscribers for other components
      this.broadcastToSubscribers(data);
      return;
    }

    // Broadcast to subscribers
    if (type === 'channel_message') {
      try {
        const payload = data.data as any;
        if (data.channel?.startsWith('positions.') && payload?.positions) {
          import('../store/useAppStore').then(({ useAppStore }) => {
            const store = useAppStore.getState();
            const standardized = payload.positions.map((p: any) => ({
              id: p.position_id ?? p.ticket ?? 0,
              symbol: p.symbol || '',
              side: p.action === 1 ? 'SELL' : 'BUY',
              volume: p.volume_lots ?? p.volume ?? 0,
              openPrice: p.price_open ?? 0,
              currentPrice: p.price_current ?? 0,
              openTime: p.time_create ? new Date(p.time_create * 1000).toISOString() : new Date().toISOString(),
              sl: p.price_sl ?? 0,
              tp: p.price_tp ?? 0,
              swap: p.storage ?? p.swap ?? 0,
              commission: p.commission ?? 0,
              unrealizedPnL: p.profit ?? 0
            }));
            store.setPositions(standardized);
          });

          // Also update MT5 store
          const mt5Data = { ...data, type: 'mt5_positions', positions: payload.positions };
          this.handleMT5Update(mt5Data);
        } else if (data.channel?.startsWith('account.')) {
          const accRecord = payload?.account || payload;
          if (accRecord && accRecord.balance !== undefined) {
            import('../store/useAppStore').then(({ useAppStore }) => {
              const store = useAppStore.getState();
              // Filter: only accept data for the current account
              const channelAccountId = data.channel.split('.')[1];
              if (channelAccountId && store.accountId && channelAccountId !== store.accountId) return;

              const curAccount = store.account;
              store.setAccount({
                ...curAccount,
                balance: accRecord.balance ?? curAccount?.balance ?? 0,
                equity: accRecord.equity ?? curAccount?.equity ?? 0,
                margin: accRecord.margin ?? curAccount?.margin ?? 0,
                freeMargin: accRecord.margin_free ?? accRecord.freeMargin ?? curAccount?.freeMargin ?? 0,
                unrealizedPL: accRecord.profit ?? accRecord.unrealizedPL ?? curAccount?.unrealizedPL ?? 0,
                marginLevel: accRecord.margin_level ?? accRecord.marginLevel ?? curAccount?.marginLevel ?? 0,
                currency: accRecord.currency ?? curAccount?.currency ?? 'USD',
                leverage: accRecord.leverage ?? curAccount?.leverage ?? 100
              } as any);
            });

            // Also update MT5 store
            const mt5Data = { ...data, type: 'mt5_account', account: accRecord };
            this.handleMT5Update(mt5Data);
          }
        }
      } catch (err) {
        console.error('[WS] Failed to map channel_message to store:', err);
      }
    }
    this.broadcastToSubscribers(data);
  }

  /**
   * Handle tick message from fixapibackend
   * Format: {type: 'tick', symbol, bid, ask, spread, timestamp, high24h, low24h, dailyChange, lp}
   */
  private handleFixTick(data: WebSocketMessage): void {
    console.log(`[WS TICK] ${data.symbol} bid=${data.bid} ask=${data.ask} spread=${data.spread} daily=${data.dailyChange}`);
    const timestamp = typeof data.timestamp === 'number' ? data.timestamp : Date.now();
    const ts = timestamp > 1000000000000 ? timestamp : timestamp * 1000;

    // Update MarketDataStore (OHLCV aggregation)
    import('../store/useMarketDataStore').then(({ useMarketDataStore }) => {
      useMarketDataStore.getState().updateTick(data.symbol!, {
        symbol: data.symbol!,
        bid: Number(data.bid) || 0,
        ask: Number(data.ask) || 0,
        spread: Number(data.spread) || 0,
        timestamp: ts,
        lp: data.lp as string | undefined,
        volume: 1,
      });
    }).catch(err => {
      console.error('[WS] Failed to import useMarketDataStore:', err);
    });

    // Update AppStore directly with ALL broker fields (bid, ask, spread, dailyChange, high24h, low24h)
    // This is what MarketWatchPanel reads for the Daily column
    import('../store/useAppStore').then(({ useAppStore }) => {
      useAppStore.getState().setTick(data.symbol!, {
        symbol: data.symbol!,
        bid: Number(data.bid) || 0,
        ask: Number(data.ask) || 0,
        spread: Number(data.spread) || 0,
        timestamp: ts,
        lp: data.lp as string | undefined,
        volume: 1,
        // MT5-style daily data sent by the broker
        dailyChange: data.dailyChange !== undefined ? Number(data.dailyChange) : undefined,
        high24h: data.high24h !== undefined ? Number(data.high24h) : undefined,
        low24h: data.low24h !== undefined ? Number(data.low24h) : undefined,
      } as any);
    }).catch(err => {
      console.error('[WS] Failed to import useAppStore:', err);
    });
  }

  /**
   * Handle candle update from fixapibackend
   * Format: {type: 'update', symbol, candle: {time, open, high, low, close, volume}}
   */
  private handleFixCandle(data: WebSocketMessage): void {
    const candle = data.candle as Record<string, number> | undefined;
    if (candle) {
      console.log(`[WS CANDLE] ${data.symbol} O=${candle.open} H=${candle.high} L=${candle.low} C=${candle.close} V=${candle.volume}`);
    }
    import('../store/useMarketDataStore').then(({ useMarketDataStore }) => {
      const store = useMarketDataStore.getState();

      if (candle && data.symbol) {
        store.updateCandle({
          symbol: data.symbol,
          timeframe: 'M1',
          open: candle.open,
          high: candle.high,
          low: candle.low,
          close: candle.close,
          volume: candle.volume,
          time: candle.time,
        });
      }
    }).catch(err => {
      console.error('[WS] Failed to import useMarketDataStore:', err);
    });
  }

  /**
   * Handle MT5 WebSocket updates - update useMT5Store directly
   */
  private handleMT5Update(data: WebSocketMessage): void {
    // Dynamically import to avoid circular dependency
    import('../store/useMT5Store').then(({ useMT5Store }) => {
      const store = useMT5Store.getState();

      if (data.type === 'mt5_positions' && Array.isArray(data.positions)) {
        store.setPositionsFromWS(data.positions as any);
      } else if (data.type === 'mt5_account' && data.account) {
        store.setAccountFromWS(data.account as any);
      } else if (data.type === 'mt5_orders' && Array.isArray(data.orders)) {
        store.setOrdersFromWS(data.orders as any);
      }
    }).catch(err => {
      console.error('[WS] Failed to import useMT5Store:', err);
    });
  }

  /**
   * Broadcast message to relevant subscribers
   */
  private broadcastToSubscribers(data: WebSocketMessage): void {
    const channel = data.channel || data.symbol || data.type;
    const isAccountChannelMessage =
      data.type === 'channel_message' &&
      typeof data.channel === 'string' &&
      data.channel.startsWith('account.');

    const cloneDataPayload = (value: unknown): unknown => {
      if (value === null || value === undefined) return value;
      if (typeof structuredClone === 'function') {
        try {
          return structuredClone(value);
        } catch {
          // Fall through to JSON clone fallback.
        }
      }
      try {
        return JSON.parse(JSON.stringify(value));
      } catch {
        return value;
      }
    };

    const makeCallbackMessage = (): WebSocketMessage => {
      if (!isAccountChannelMessage) return data;
      return {
        ...data,
        data: cloneDataPayload(data.data),
      };
    };

    // Broadcast to channel-specific subscribers
    const callbacks = this.subscribers.get(channel);
    if (callbacks) {
      callbacks.forEach((callback) => {
        try {
          callback(makeCallbackMessage());
        } catch (error) {
          console.error('[WS] Callback error:', error);
        }
      });
    }

    // Broadcast to wildcard subscribers
    const wildcardCallbacks = this.subscribers.get('*');
    if (wildcardCallbacks) {
      wildcardCallbacks.forEach((callback) => {
        try {
          callback(makeCallbackMessage());
        } catch (error) {
          console.error('[WS] Wildcard callback error:', error);
        }
      });
    }
  }

  /**
   * Flush buffered tick updates
   */
  private flushTickBuffer(): void {
    if (this.tickBuffer.size === 0) return;

    this.tickBuffer.forEach((data) => {
      this.broadcastToSubscribers(data);
    });

    this.tickBuffer.clear();
  }

  /**
   * Start flush interval for throttled updates
   */
  private startFlushInterval(): void {
    if (this.flushInterval) return;

    this.flushInterval = setInterval(() => {
      this.flushTickBuffer();
    }, this.updateThrottleMs);
  }

  /**
   * Stop flush interval
   */
  private stopFlushInterval(): void {
    if (this.flushInterval) {
      clearInterval(this.flushInterval);
      this.flushInterval = null;
    }
  }

  /**
   * Start ping interval to keep connection alive
   */
  private startPingInterval(): void {
    if (this.pingInterval) return;

    this.pingInterval = setInterval(() => {
      this.sendPing();
    }, this.pingIntervalMs);
  }

  /**
   * Stop ping interval
   */
  private stopPingInterval(): void {
    if (this.pingInterval) {
      clearInterval(this.pingInterval);
      this.pingInterval = null;
    }

    if (this.pongTimeout) {
      clearTimeout(this.pongTimeout);
      this.pongTimeout = null;
    }
  }

  /**
   * Send ping message
   */
  private sendPing(): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      const pingTime = Date.now();
      this.sendMessage({ type: 'ping', timestamp: pingTime });

      // Set timeout for pong response (disabled - backend doesn't send pong)
      // this.pongTimeout = setTimeout(() => {
      //   console.warn('[WS] Pong timeout - connection may be dead');
      //   this.ws?.close();
      // }, this.pongTimeoutMs);
    }
  }

  /**
   * Handle pong response
   */
  private handlePong(): void {
    if (this.pongTimeout) {
      clearTimeout(this.pongTimeout);
      this.pongTimeout = null;
    }

    const now = Date.now();
    if (this.lastPongTime > 0) {
      const latency = now - this.lastPongTime;
      this.recordLatency(latency);
    }
    this.lastPongTime = now;
  }

  /**
   * Record latency measurement
   */
  private recordLatency(latency: number): void {
    this.latencyMeasurements.push(latency);
    if (this.latencyMeasurements.length > this.maxLatencyMeasurements) {
      this.latencyMeasurements.shift();
    }

    this.metrics.lastLatency = latency;
    this.metrics.averageLatency =
      this.latencyMeasurements.reduce((sum, l) => sum + l, 0) /
      this.latencyMeasurements.length;

    this.notifyMetricsListeners();
  }

  /**
   * Attempt to reconnect with exponential backoff
   */
  private attemptReconnect(): void {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.error('[WS] Max reconnect attempts reached');
      this.updateState('error');
      return;
    }

    this.reconnectAttempts++;
    this.metrics.reconnectAttempts++;

    const delay = Math.min(
      this.baseReconnectDelay * Math.pow(2, this.reconnectAttempts - 1),
      this.maxReconnectDelay
    );

    console.log(
      `[WS] Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts}/${this.maxReconnectAttempts})`
    );

    this.reconnectTimeout = setTimeout(() => {
      this.connect();
    }, delay);
  }

  /**
   * Resubscribe to all channels after reconnection
   */
  private resubscribeChannels(): void {
    console.log(`[WS] Resubscribing to ${this.subscribers.size} channels`);

    this.subscribers.forEach((_, channel) => {
      if (channel === '*') return;

      // Handle symbol subscriptions (format: symbols:BTCUSD,ETHUSD)
      if (channel.startsWith('symbols:')) {
        const symbolsStr = channel.replace('symbols:', '');
        const symbols = symbolsStr.split(',').filter(s => s.length > 0);
        if (symbols.length > 0) {
          this.sendMessage({
            type: 'subscribe',
            symbols,
          });
        }
      } else {
        // Regular channel subscription
        this.sendMessage({
          type: 'subscribe',
          channel,
        });
      }
    });
  }

  /**
   * Update connection state and notify listeners
   */
  private updateState(state: ConnectionState): void {
    if (this.connectionState === state) return;

    console.log(`[WS] State change: ${this.connectionState} -> ${state}`);
    this.connectionState = state;

    this.stateListeners.forEach((listener) => {
      try {
        listener(state);
      } catch (error) {
        console.error('[WS] State listener error:', error);
      }
    });
  }

  /**
   * Notify metrics listeners
   */
  private notifyMetricsListeners(): void {
    this.metricsListeners.forEach((listener) => {
      try {
        listener(this.metrics);
      } catch (error) {
        console.error('[WS] Metrics listener error:', error);
      }
    });
  }

  /**
   * Add auth token to WebSocket URL
   */
  private addTokenToUrl(url: string, token: string | null): string {
    if (!token) {
      console.warn('[WS] No auth token found');
      return url;
    }

    try {
      const urlObj = new URL(url, window.location.origin);
      urlObj.searchParams.set('token', token);
      return urlObj.toString();
    } catch (error) {
      console.error('[WS] Failed to add token to URL:', error);
      return url;
    }
  }

  /**
   * Handle online event
   */
  private handleOnline = (): void => {
    console.log('[WS] Network online - attempting reconnect');
    if (this.connectionState === 'offline' || this.connectionState === 'disconnected') {
      this.connect();
    }
  };

  /**
   * Handle offline event
   */
  private handleOffline = (): void => {
    console.log('[WS] Network offline');
    this.updateState('offline');
  };

  /**
   * Cleanup resources
   */
  public destroy(): void {
    this.disconnect();

    if (typeof window !== 'undefined') {
      window.removeEventListener('online', this.handleOnline);
      window.removeEventListener('offline', this.handleOffline);
    }

    this.subscribers.clear();
    this.stateListeners.clear();
    this.metricsListeners.clear();
    this.tickBuffer.clear();
    this.messageQueue = [];
  }

  /**
   * Normalize WebSocket URL to FIX stream endpoint where appropriate.
   * - Preserves fixapibackend URLs (wss://fixapibackend.tradecopier.org/ws)
   * - Migrates rtxbackend `/ws` path to `/fix-ws`
   * - Rewrites ONLY Vite dev proxy URLs (localhost:5173) to backend FIX URL
   * - Preserves explicit local FIX backends like ws://localhost:8081/ws
   */
  private normalizeWsUrl(input: string): string {
    // Preserve fixapibackend URL as-is (this is the new market data backend)
    if (input?.includes('fixapibackend.tradecopier.org')) {
      return input;
    }

    const fallback = import.meta.env.VITE_WS_URL || 'wss://rtxbackend.tradecopier.org/fix-ws';
    if (!input) return fallback;

    try {
      const url = new URL(input, window.location.origin);

      // If app is still pointing to Vite dev proxy ws URL, force backend FIX endpoint.
      if (
        (url.hostname === 'localhost' || url.hostname === '127.0.0.1') &&
        (url.port === '5173' || url.port === '') &&
        (url.pathname === '/ws' || url.pathname === '/fix-ws')
      ) {
        return fallback;
      }

      // Migrate rtxbackend `/ws` to `/fix-ws` (old backend only).
      // Do NOT change fixapibackend URLs.
      if (
        url.pathname === '/ws' &&
        url.hostname.includes('rtxbackend') &&
        !url.hostname.includes('fixapibackend')
      ) {
        url.pathname = '/fix-ws';
      }

      return url.toString();
    } catch {
      // If input contains fixapibackend, preserve it
      if (input.includes('fixapibackend')) return input;
      // Last-resort fallback
      return fallback;
    }
  }
}

// Singleton instance
let wsInstance: EnhancedWebSocketService | null = null;

export const getEnhancedWebSocketService = (url?: string): EnhancedWebSocketService => {
  const normalizedRequestedUrl = (() => {
    if (!url) return undefined;
    // Preserve fixapibackend URLs (new market data backend)
    if (url.includes('fixapibackend.tradecopier.org')) return url;
    // Only rewrite known production legacy endpoint, not explicit local FIX endpoints.
    if (url.includes('rtxbackend') && url.includes('/ws') && !url.includes('fixapi')) {
      return url.replace('/ws', '/fix-ws');
    }
    return url;
  })();

  if (!wsInstance && url) {
    wsInstance = new EnhancedWebSocketService(normalizedRequestedUrl || url);
  }

  // If singleton exists but caller requests a different URL, recreate instance.
  if (wsInstance && normalizedRequestedUrl) {
    const currentUrl = (wsInstance as any).url as string | undefined;
    if (currentUrl && currentUrl !== normalizedRequestedUrl) {
      wsInstance.destroy();
      wsInstance = new EnhancedWebSocketService(normalizedRequestedUrl);
    }
  }

  if (!wsInstance) {
    throw new Error('WebSocket service not initialized. Provide URL on first call.');
  }

  return wsInstance;
};

// Export for cleanup
export const destroyWebSocketService = (): void => {
  if (wsInstance) {
    wsInstance.destroy();
    wsInstance = null;
  }
};

/**
 * WebSocket Service with Auto-Reconnection and State Management
 * Handles real-time market data and account updates
 */

import { WS_URL } from '../config/api';

export type SubscriptionCallback = (data: any) => void;
export type ConnectionStateCallback = (state: ConnectionState) => void;

export type ConnectionState = 'connecting' | 'connected' | 'disconnected' | 'error';

interface WebSocketMessage {
  type: string;
  symbol?: string;
  bid?: number;
  ask?: number;
  spread?: number;
  timestamp?: number;
  lp?: string;
  digits?: number;
}

// MT5 WebSocket message types
export interface MT5TickMessage {
  type: 'tick';
  symbol: string;
  bid: number;
  ask: number;
  spread: number;
  timestamp: number;
  lp: string;
  digits: number;
}

export interface SymbolInfo {
  symbol: string;
  displayName: string;
  baseCurrency: string;
  quoteCurrency: string;
  minLotSize: number;
  maxLotSize: number;
  lotStep: number;
  type: string;
}

export interface MT5SymbolsMessage {
  type: 'symbols';
  symbols: SymbolInfo[];
}

export type MT5Message = MT5TickMessage | MT5SymbolsMessage;

export class WebSocketService {
  private ws: WebSocket | null = null;
  private url: string;
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 10;
  private reconnectDelay = 1000;
  private reconnectTimeout: ReturnType<typeof setTimeout> | null = null;
  private pingInterval: ReturnType<typeof setInterval> | null = null;

  private subscribers: Map<string, Set<SubscriptionCallback>> = new Map();
  private stateListeners: Set<ConnectionStateCallback> = new Set();
  private connectionState: ConnectionState = 'disconnected';

  private tickBuffer: Map<string, WebSocketMessage> = new Map();
  private flushInterval: ReturnType<typeof setInterval> | null = null;
  private updateThrottle = 0; // ms - PERFORMANCE FIX: Zero throttling for MT5 parity (<5ms tick latency)

  // MT5-specific state
  private availableSymbols: SymbolInfo[] = [];
  private subscribedSymbols: Set<string> = new Set();
  private symbolListeners: Set<(symbols: SymbolInfo[]) => void> = new Set();

  constructor() {
    this.url = WS_URL;
  }

  /**
   * Connect to WebSocket server
   */
  public connect(): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      console.log('[WS] Already connected');
      return;
    }

    this.updateState('connecting');

    // Get auth token and add to URL
    const token = localStorage.getItem('auth_token');
    const urlWithAuth = this.addTokenToUrl(this.url, token);

    console.log(`[WS] Connecting to ${this.url}...`);

    try {
      this.ws = new WebSocket(urlWithAuth);

      this.ws.onopen = () => {
        console.log('[WS] Connected successfully');
        this.reconnectAttempts = 0;
        this.reconnectDelay = 1000;
        this.updateState('connected');
        this.startPingInterval();
        this.startFlushInterval();
      };

      this.ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data) as WebSocketMessage;
          this.handleMessage(data);
        } catch (error) {
          console.error('[WS] Failed to parse message:', error);
        }
      };

      this.ws.onerror = (error) => {
        console.error('[WS] Error:', error);
        this.updateState('error');
      };

      this.ws.onclose = (event) => {
        console.log(`[WS] Connection closed (code: ${event.code}, reason: ${event.reason})`);
        this.updateState('disconnected');
        this.stopPingInterval();
        this.stopFlushInterval();

        // Check if close was due to authentication failure (1008 = policy violation)
        if (event.code === 1008 || event.code === 401) {
          console.error('[WS] Authentication failed - clearing token and attempting re-authentication');
          localStorage.removeItem('auth_token');
          // Dispatch auth failure event (let app handle login redirect)
          window.dispatchEvent(new CustomEvent('ws-auth-failed'));
          return;
        }

        this.attemptReconnect();
      };
    } catch (error) {
      console.error('[WS] Connection failed:', error);
      this.updateState('error');
      this.attemptReconnect();
    }
  }

  /**
   * Disconnect from WebSocket server
   */
  public disconnect(): void {
    console.log('[WS] Disconnecting...');

    if (this.reconnectTimeout) {
      clearTimeout(this.reconnectTimeout);
      this.reconnectTimeout = null;
    }

    this.stopPingInterval();
    this.stopFlushInterval();

    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }

    this.reconnectAttempts = 0;
    this.updateState('disconnected');
  }

  /**
   * Subscribe to market data for a specific symbol
   */
  public subscribe(channel: string, callback: SubscriptionCallback): () => void {
    if (!this.subscribers.has(channel)) {
      this.subscribers.set(channel, new Set());
    }

    this.subscribers.get(channel)!.add(callback);

    // Send subscription message if needed
    this.sendMessage({
      type: 'subscribe',
      channel
    });

    // Return unsubscribe function
    return () => {
      const callbacks = this.subscribers.get(channel);
      if (callbacks) {
        callbacks.delete(callback);
        if (callbacks.size === 0) {
          this.subscribers.delete(channel);
          this.sendMessage({
            type: 'unsubscribe',
            channel
          });
        }
      }
    };
  }

  /**
   * Listen to connection state changes
   */
  public onStateChange(callback: ConnectionStateCallback): () => void {
    this.stateListeners.add(callback);

    // Immediately call with current state
    callback(this.connectionState);

    // Return unsubscribe function
    return () => {
      this.stateListeners.delete(callback);
    };
  }

  /**
   * Get current connection state
   */
  public getState(): ConnectionState {
    return this.connectionState;
  }

  /**
   * Send message to WebSocket server
   */
  private sendMessage(message: any): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(message));
    }
  }

  /**
   * Handle incoming WebSocket messages
   */
  private handleMessage(data: WebSocketMessage): void {
    const { type, symbol } = data;

    // Handle MT5 symbols list
    if (type === 'symbols') {
      const symbolsData = data as unknown as MT5SymbolsMessage;
      this.availableSymbols = symbolsData.symbols;
      this.symbolListeners.forEach(listener => listener(this.availableSymbols));
      return;
    }

    // Buffer tick updates for throttling
    if (type === 'tick' && symbol) {
      this.tickBuffer.set(symbol, data);
      return;
    }

    // Broadcast to all subscribers of this channel
    const channel = symbol || type;
    const callbacks = this.subscribers.get(channel);
    if (callbacks) {
      callbacks.forEach(callback => callback(data));
    }

    // Broadcast to wildcard subscribers
    const wildcardCallbacks = this.subscribers.get('*');
    if (wildcardCallbacks) {
      wildcardCallbacks.forEach(callback => callback(data));
    }
  }

  /**
   * Subscribe to MT5 symbols for real-time ticks
   */
  public subscribeToSymbols(symbols: string[]): void {
    symbols.forEach(symbol => this.subscribedSymbols.add(symbol));
    this.sendMessage({
      action: 'subscribe',
      symbols
    });
  }

  /**
   * Unsubscribe from MT5 symbols
   */
  public unsubscribeFromSymbols(symbols: string[]): void {
    symbols.forEach(symbol => this.subscribedSymbols.delete(symbol));
    this.sendMessage({
      action: 'unsubscribe',
      symbols
    });
  }

  /**
   * Get available symbols from MT5
   */
  public getAvailableSymbols(): SymbolInfo[] {
    return this.availableSymbols;
  }

  /**
   * Listen for available symbols updates
   */
  public onSymbolsAvailable(callback: (symbols: SymbolInfo[]) => void): () => void {
    this.symbolListeners.add(callback);
    // Immediately call with current symbols if available
    if (this.availableSymbols.length > 0) {
      callback(this.availableSymbols);
    }
    return () => {
      this.symbolListeners.delete(callback);
    };
  }

  /**
   * Flush buffered tick updates
   */
  private flushTickBuffer(): void {
    if (this.tickBuffer.size === 0) return;

    this.tickBuffer.forEach((data, symbol) => {
      const callbacks = this.subscribers.get(symbol);
      if (callbacks) {
        callbacks.forEach(callback => callback(data));
      }

      // Broadcast to wildcard subscribers
      const wildcardCallbacks = this.subscribers.get('*');
      if (wildcardCallbacks) {
        wildcardCallbacks.forEach(callback => callback(data));
      }
    });

    this.tickBuffer.clear();
  }

  /**
   * Start flush interval for throttled tick updates
   */
  private startFlushInterval(): void {
    if (this.flushInterval) return;

    this.flushInterval = setInterval(() => {
      this.flushTickBuffer();
    }, this.updateThrottle);
  }

  /**
   * Stop flush interval
   */
  private stopFlushInterval(): void {
    if (this.flushInterval) {
      clearInterval(this.flushInterval);
      this.flushInterval = null;
    }
  }

  /**
   * Start ping interval to keep connection alive
   */
  private startPingInterval(): void {
    if (this.pingInterval) return;

    this.pingInterval = setInterval(() => {
      if (this.ws?.readyState === WebSocket.OPEN) {
        this.sendMessage({ type: 'ping' });
      }
    }, 30000); // 30 seconds
  }

  /**
   * Stop ping interval
   */
  private stopPingInterval(): void {
    if (this.pingInterval) {
      clearInterval(this.pingInterval);
      this.pingInterval = null;
    }
  }

  /**
   * Attempt to reconnect with exponential backoff
   */
  private attemptReconnect(): void {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.error('[WS] Max reconnect attempts reached');
      this.updateState('error');
      return;
    }

    this.reconnectAttempts++;
    const delay = Math.min(
      this.reconnectDelay * Math.pow(2, this.reconnectAttempts - 1),
      30000 // Max 30 seconds
    );

    console.log(`[WS] Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts}/${this.maxReconnectAttempts})`);

    this.reconnectTimeout = setTimeout(() => {
      this.connect();
    }, delay);
  }

  /**
   * Update connection state and notify listeners
   */
  private updateState(state: ConnectionState): void {
    if (this.connectionState === state) return;

    this.connectionState = state;
    this.stateListeners.forEach(listener => listener(state));
  }

  /**
   * Add auth token to WebSocket URL as query parameter
   */
  private addTokenToUrl(url: string, token: string | null): string {
    if (!token) {
      console.warn('[WS] No auth token found in localStorage');
      return url;
    }

    const urlObj = new URL(url, window.location.origin);
    urlObj.searchParams.set('token', token);
    return urlObj.toString();
  }
}

// Singleton instance
let wsInstance: WebSocketService | null = null;

export const getWebSocketService = (): WebSocketService => {
  if (!wsInstance) {
    wsInstance = new WebSocketService();
  }

  return wsInstance;
};

