export interface ToolbarState {
  activeTool: 'cursor' | 'trendline' | 'hline' | 'vline' | 'text' | 'channel' | 'fibonacci' | 'fib_extension' | 'measure' | 'freehand' | 'callout' | 'shapes' | 'rectangle' | 'ellipse' | null;
  chartType: 'candlestick' | 'bar' | 'line' | 'area';
  timeframe: string;
  crosshairEnabled: boolean;
  autoScrollEnabled: boolean;
  chartShiftEnabled: boolean;
  magnetEnabled: boolean;
  candleWidth: number; // for zoom
  indicators: Array<{ name: string; params: any }>;
  drawings: Array<{ id: string; type: string; points: any[] }>;
}

export type ToolbarAction =
  | { type: 'SELECT_TOOL'; tool: ToolbarState['activeTool']; subtype?: string }
  | { type: 'SET_CHART_TYPE'; chartType: ToolbarState['chartType'] }
  | { type: 'SET_TIMEFRAME'; timeframe: string }
  | { type: 'TOGGLE_CROSSHAIR' }
  | { type: 'TOGGLE_AUTO_SCROLL' }
  | { type: 'SET_AUTO_SCROLL'; enabled: boolean }
  | { type: 'TOGGLE_CHART_SHIFT' }
  | { type: 'SET_CHART_SHIFT'; enabled: boolean }
  | { type: 'TOGGLE_MAGNET' }
  | { type: 'EXPORT_CHART' }
  | { type: 'ZOOM'; delta: number }
  | { type: 'ADD_INDICATOR'; indicator: { name: string; params: any } }
  | { type: 'REMOVE_INDICATOR'; name: string }
  | { type: 'ADD_DRAWING'; drawing: { id: string; type: string; points: any[] } }
  | { type: 'DELETE_DRAWING'; id: string }
  | { type: 'CLEAR_DRAWINGS' };

export const initialToolbarState: ToolbarState = {
  activeTool: null,
  chartType: (typeof window !== 'undefined' ? localStorage.getItem('rtx5_chart_type') as ToolbarState['chartType'] : null) || 'candlestick',
  timeframe: 'm1',
  crosshairEnabled: true,
  autoScrollEnabled: true,
  chartShiftEnabled: true,
  magnetEnabled: false,
  candleWidth: 10,
  indicators: [],
  drawings: []
};

export function toolbarReducer(state: ToolbarState, action: ToolbarAction): ToolbarState {
  switch (action.type) {
    case 'SELECT_TOOL':
      // Only one drawing tool can be active at a time
      // Selecting 'cursor' deselects all drawing tools
      return {
        ...state,
        activeTool: action.tool === 'cursor' ? null : action.tool
      };

    case 'SET_CHART_TYPE':
      return {
        ...state,
        chartType: action.chartType
      };

    case 'SET_TIMEFRAME':
      return {
        ...state,
        timeframe: action.timeframe
      };

    case 'TOGGLE_CROSSHAIR':
      return {
        ...state,
        crosshairEnabled: !state.crosshairEnabled
      };

    case 'TOGGLE_AUTO_SCROLL':
      return {
        ...state,
        autoScrollEnabled: !state.autoScrollEnabled
      };

    case 'SET_AUTO_SCROLL':
      return {
        ...state,
        autoScrollEnabled: action.enabled
      };

    case 'TOGGLE_CHART_SHIFT':
      return {
        ...state,
        chartShiftEnabled: !state.chartShiftEnabled
      };

    case 'SET_CHART_SHIFT':
      return {
        ...state,
        chartShiftEnabled: action.enabled
      };

    case 'TOGGLE_MAGNET':
      return {
        ...state,
        magnetEnabled: !state.magnetEnabled
      };

    case 'ZOOM':
      // Zoom by adjusting candle width
      // Minimum: 2px, Maximum: 50px
      const newWidth = Math.max(2, Math.min(50, state.candleWidth + action.delta));
      return {
        ...state,
        candleWidth: newWidth
      };

    case 'ADD_INDICATOR':
      // Prevent duplicate indicators
      if (state.indicators.some(ind => ind.name === action.indicator.name)) {
        return state;
      }
      return {
        ...state,
        indicators: [...state.indicators, action.indicator]
      };

    case 'REMOVE_INDICATOR':
      return {
        ...state,
        indicators: state.indicators.filter(ind => ind.name !== action.name)
      };

    case 'ADD_DRAWING':
      return {
        ...state,
        drawings: [...state.drawings, action.drawing]
      };

    case 'DELETE_DRAWING':
      return {
        ...state,
        drawings: state.drawings.filter(d => d.id !== action.id)
      };

    case 'CLEAR_DRAWINGS':
      return {
        ...state,
        drawings: []
      };

    default:
      return state;
  }
}

/**
 * Alert Store with Zustand + Persist
 * Manages price alerts and alert checking logic
 */

import { create } from 'zustand';
import { devtools, persist } from 'zustand/middleware';

export type AlertCondition =
  | 'price_above'
  | 'price_below'
  | 'bid_above'
  | 'bid_below'
  | 'ask_above'
  | 'ask_below';

export type AlertStatus = 'active' | 'triggered' | 'expired' | 'disabled';

export type NotifyMethod = 'sound' | 'push' | 'both';

export interface Alert {
  id: string;
  symbol: string;
  condition: AlertCondition;
  price: number;
  status: AlertStatus;
  expiration: number | null; // timestamp or null for no expiration
  notifyMethod: NotifyMethod;
  title?: string;
  message?: string;
  createdAt: number;
  triggeredAt?: number;
  enabled: boolean;
}

interface AlertState {
  alerts: Alert[];

  // Actions
  addAlert: (alert: Omit<Alert, 'id' | 'status' | 'createdAt' | 'enabled'>) => string;
  removeAlert: (id: string) => void;
  updateAlert: (id: string, updates: Partial<Alert>) => void;
  toggleAlert: (id: string) => void;
  checkAlerts: (currentPrices: Record<string, { bid: number; ask: number; last?: number }>) => Alert[];
  clearTriggered: () => void;
  clearAll: () => void;
}

export const useAlertStore = create<AlertState>()(
  devtools(
    persist(
      (set, get) => ({
        alerts: [],

        addAlert: (alert) => {
          const newAlert: Alert = {
            ...alert,
            id: `alert-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            status: 'active',
            createdAt: Date.now(),
            enabled: true,
          };

          set((state) => ({
            alerts: [newAlert, ...state.alerts],
          }));

          return newAlert.id;
        },

        removeAlert: (id) => {
          set((state) => ({
            alerts: state.alerts.filter((a) => a.id !== id),
          }));
        },

        updateAlert: (id, updates) => {
          set((state) => ({
            alerts: state.alerts.map((a) => (a.id === id ? { ...a, ...updates } : a)),
          }));
        },

        toggleAlert: (id) => {
          set((state) => ({
            alerts: state.alerts.map((a) =>
              a.id === id
                ? { ...a, enabled: !a.enabled, status: a.enabled ? 'disabled' : 'active' }
                : a
            ),
          }));
        },

        checkAlerts: (currentPrices) => {
          const now = Date.now();
          const triggeredAlerts: Alert[] = [];

          set((state) => {
            const updatedAlerts = state.alerts.map((alert) => {
              // Skip if not active or disabled
              if (alert.status !== 'active' || !alert.enabled) {
                return alert;
              }

              // Check expiration
              if (alert.expiration && now > alert.expiration) {
                return { ...alert, status: 'expired' as AlertStatus };
              }

              // Get current price data for this symbol
              const priceData = currentPrices[alert.symbol];
              if (!priceData) return alert;

              const { bid, ask, last } = priceData;
              const currentPrice = last || (bid + ask) / 2;

              // Check if alert condition is met
              let conditionMet = false;

              switch (alert.condition) {
                case 'price_above':
                  conditionMet = currentPrice >= alert.price;
                  break;
                case 'price_below':
                  conditionMet = currentPrice <= alert.price;
                  break;
                case 'bid_above':
                  conditionMet = bid >= alert.price;
                  break;
                case 'bid_below':
                  conditionMet = bid <= alert.price;
                  break;
                case 'ask_above':
                  conditionMet = ask >= alert.price;
                  break;
                case 'ask_below':
                  conditionMet = ask <= alert.price;
                  break;
              }

              if (conditionMet) {
                const triggeredAlert = {
                  ...alert,
                  status: 'triggered' as AlertStatus,
                  triggeredAt: now,
                };
                triggeredAlerts.push(triggeredAlert);
                return triggeredAlert;
              }

              return alert;
            });

            return { alerts: updatedAlerts };
          });

          return triggeredAlerts;
        },

        clearTriggered: () => {
          set((state) => ({
            alerts: state.alerts.filter((a) => a.status !== 'triggered'),
          }));
        },

        clearAll: () => {
          set({ alerts: [] });
        },
      }),
      {
        name: 'rtx5-alerts',
        partialize: (state) => ({
          alerts: state.alerts,
        }),
      }
    )
  )
);

/**
 * Helper function to format alert condition for display
 */
export function formatCondition(condition: AlertCondition): string {
  const map: Record<AlertCondition, string> = {
    price_above: 'Price Above',
    price_below: 'Price Below',
    bid_above: 'Bid Above',
    bid_below: 'Bid Below',
    ask_above: 'Ask Above',
    ask_below: 'Ask Below',
  };
  return map[condition];
}

/**
 * Helper function to format expiration time
 */
export function formatExpiration(expiration: number | null): string {
  if (!expiration) return 'Never';

  const now = Date.now();
  const diff = expiration - now;

  if (diff < 0) return 'Expired';

  const hours = Math.floor(diff / (1000 * 60 * 60));
  const days = Math.floor(hours / 24);

  if (days > 0) return `${days}d`;
  if (hours > 0) return `${hours}h`;

  const minutes = Math.floor(diff / (1000 * 60));
  return `${minutes}m`;
}

/**
 * Chart Template Store
 * Zustand store with persist middleware for saving/loading chart configurations
 */

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export interface ChartTemplate {
  id: string;
  name: string;
  symbol: string;
  timeframe: 'M1' | 'M5' | 'M15' | 'M30' | 'H1' | 'H4' | 'D1' | 'W1' | 'MN';
  chartType: 'candlestick' | 'heikinAshi' | 'bar' | 'line' | 'area';
  showVolume: boolean;
  showGrid: boolean;
  indicators: any[]; // Indicator configurations
  drawingTools: any[]; // Drawing tool configurations
  colors?: {
    upColor?: string;
    downColor?: string;
    backgroundColor?: string;
    gridColor?: string;
  };
  createdAt: number;
  updatedAt: number;
}

interface ChartTemplateState {
  templates: ChartTemplate[];
  activeTemplateId: string | null;

  // Actions
  saveTemplate: (template: Omit<ChartTemplate, 'id' | 'createdAt' | 'updatedAt'>) => ChartTemplate;
  loadTemplate: (id: string) => ChartTemplate | null;
  deleteTemplate: (id: string) => void;
  renameTemplate: (id: string, newName: string) => void;
  duplicateTemplate: (id: string) => ChartTemplate | null;
  setActiveTemplate: (id: string | null) => void;
  getTemplateList: () => ChartTemplate[];
  importTemplates: (templates: ChartTemplate[]) => void;
  exportTemplates: () => { version: number; templates: ChartTemplate[] };
}

export const useChartTemplateStore = create<ChartTemplateState>()(
  persist(
    (set, get) => ({
      templates: [],
      activeTemplateId: null,

      saveTemplate: (template) => {
        const newTemplate: ChartTemplate = {
          ...template,
          id: `template_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          createdAt: Date.now(),
          updatedAt: Date.now(),
        };

        set((state) => ({
          templates: [...state.templates, newTemplate],
        }));

        return newTemplate;
      },

      loadTemplate: (id) => {
        const template = get().templates.find((t) => t.id === id);
        if (template) {
          set({ activeTemplateId: id });
          return template;
        }
        return null;
      },

      deleteTemplate: (id) => {
        set((state) => ({
          templates: state.templates.filter((t) => t.id !== id),
          activeTemplateId: state.activeTemplateId === id ? null : state.activeTemplateId,
        }));
      },

      renameTemplate: (id, newName) => {
        set((state) => ({
          templates: state.templates.map((t) =>
            t.id === id
              ? { ...t, name: newName, updatedAt: Date.now() }
              : t
          ),
        }));
      },

      duplicateTemplate: (id) => {
        const template = get().templates.find((t) => t.id === id);
        if (!template) return null;

        const duplicated: ChartTemplate = {
          ...template,
          id: `template_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          name: `${template.name} (Copy)`,
          createdAt: Date.now(),
          updatedAt: Date.now(),
        };

        set((state) => ({
          templates: [...state.templates, duplicated],
        }));

        return duplicated;
      },

      setActiveTemplate: (id) => {
        set({ activeTemplateId: id });
      },

      getTemplateList: () => {
        return get().templates;
      },

      importTemplates: (templates) => {
        set((state) => {
          // Merge with existing templates, avoiding ID conflicts
          const existingIds = new Set(state.templates.map((t) => t.id));
          const newTemplates = templates.map((t) => {
            if (existingIds.has(t.id)) {
              // Regenerate ID if conflict
              return {
                ...t,
                id: `template_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                updatedAt: Date.now(),
              };
            }
            return t;
          });

          return {
            templates: [...state.templates, ...newTemplates],
          };
        });
      },

      exportTemplates: () => {
        return {
          version: 1,
          templates: get().templates,
        };
      },
    }),
    {
      name: 'chart-templates-storage', // LocalStorage key
      version: 1,
    }
  )
);

/**
 * Dock Layout Store
 * Zustand store for managing docking layout state
 * Integrates with DockManager for layout operations
 */

import { create } from 'zustand';
import { devtools, persist } from 'zustand/middleware';
import { DockManager, dockManager, DockLayout, DockPanelConfig, DropZone, DockDirection } from '../services/dockManager';

export type DragState = 'idle' | 'dragging' | 'dropping';

export interface DragInfo {
  panelId: string;
  panelTitle: string;
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;
  offsetX: number;
  offsetY: number;
  isFloating: boolean;
}

export interface DockState {
  // Layout
  layout: DockLayout;

  // Drag State
  dragState: DragState;
  dragInfo: DragInfo | null;
  activeDropZone: DropZone | null;
  dropZones: DropZone[];

  // Hover State
  hoveredContainerId: string | null;

  // Resizing State
  resizingContainerId: string | null;
  resizeDirection: 'horizontal' | 'vertical' | null;

  // UI State
  showDropIndicators: boolean;
  ghostPreview: {
    visible: boolean;
    x: number;
    y: number;
    width: number;
    height: number;
  };

  // Actions
  setLayout: (layout: DockLayout) => void;

  // Drag Actions
  startDrag: (panelId: string, title: string, x: number, y: number, isFloating?: boolean) => void;
  updateDrag: (x: number, y: number) => void;
  updateDropZone: (zone: DropZone | null) => void;
  endDrag: (targetId?: string, direction?: DockDirection) => void;
  cancelDrag: () => void;

  // Container Actions
  setHoveredContainer: (id: string | null) => void;
  setActiveTab: (containerId: string, panelId: string) => void;

  // Resize Actions
  startResize: (containerId: string, direction: 'horizontal' | 'vertical') => void;
  endResize: () => void;

  // UI Actions
  setShowDropIndicators: (show: boolean) => void;
  setGhostPreview: (preview: DockState['ghostPreview']) => void;

  // Dock Actions
  addPanel: (panel: DockPanelConfig, targetId?: string, direction?: DockDirection) => void;
  removePanel: (panelId: string) => void;
  dockPanel: (panelId: string, targetId: string, direction: DockDirection) => void;
  floatPanel: (panelId: string, position?: { x: number; y: number }) => void;
  updateFloatingPosition: (panelId: string, position: { x: number; y: number }) => void;
  updateFloatingSize: (panelId: string, size: { width: number; height: number }) => void;
  moveToTab: (panelId: string, tabContainerId: string, insertIndex?: number) => void;
  updateContainerSize: (containerId: string, ratio: number) => void;
  updatePanelProps: (panelId: string, updates: { props?: Record<string, any>; title?: string }) => void;

  // History Actions
  undo: () => void;
  redo: () => void;
  canUndo: () => boolean;
  canRedo: () => boolean;

  // Persistence
  saveLayout: (userId?: string) => void;
  loadLayout: (userId?: string) => boolean;
  resetToDefaultLayout: () => void;

  // Magnetic Snap Actions
  snapToWorkspaceEdge: (panelId: string, edge: 'top' | 'bottom' | 'left' | 'right' | 'center') => void;
}

const useDockLayoutStore = create<DockState>()(
  devtools(
    persist(
      (set, get) => ({
        // Initial State
        layout: dockManager.getLayout(),
        dragState: 'idle',
        dragInfo: null,
        activeDropZone: null,
        dropZones: [],
        hoveredContainerId: null,
        resizingContainerId: null,
        resizeDirection: null,
        showDropIndicators: true,
        ghostPreview: { visible: false, x: 0, y: 0, width: 0, height: 0 },

        // Layout Actions
        setLayout: (layout) => {
          set({ layout });
          dockManager.setLayout(layout, true);
        },

        // Drag Actions
        startDrag: (panelId, panelTitle, x, y, isFloating = false) => {
          set({
            dragState: 'dragging',
            dragInfo: {
              panelId,
              panelTitle,
              startX: x,
              startY: y,
              currentX: x,
              currentY: y,
              offsetX: 0,
              offsetY: 0,
              isFloating,
            },
            activeDropZone: null,
            ghostPreview: { visible: true, x, y, width: 200, height: 150 },
          });
        },

        updateDrag: (x, y) => {
          const { dragInfo } = get();
          if (!dragInfo) return;

          set({
            dragInfo: {
              ...dragInfo,
              currentX: x,
              currentY: y,
              offsetX: x - dragInfo.startX,
              offsetY: y - dragInfo.startY,
            },
            ghostPreview: {
              ...get().ghostPreview,
              x: x - 100,
              y: y - 75,
            },
          });
        },

        updateDropZone: (zone) => {
          set({ activeDropZone: zone });
        },

        endDrag: (targetId, direction) => {
          const { dragInfo, activeDropZone } = get();
          if (!dragInfo) return;

          const finalTargetId = targetId || activeDropZone?.targetContainerId;
          const finalDirection = direction || activeDropZone?.direction || 'center';

          if (finalTargetId && dragInfo.isFloating) {
            // Dock floating panel
            dockManager.dockFloatingPanel(dragInfo.panelId, finalTargetId, finalDirection);
          } else if (finalTargetId) {
            // Move docked panel
            dockManager.dockPanel(dragInfo.panelId, finalTargetId, finalDirection);
          } else if (!dragInfo.isFloating) {
            // Float the panel if dropped in empty space
            dockManager.floatPanel(dragInfo.panelId, {
              x: dragInfo.currentX - 100,
              y: dragInfo.currentY - 75,
            });
          }

          set({
            dragState: 'idle',
            dragInfo: null,
            activeDropZone: null,
            dropZones: [],
            ghostPreview: { visible: false, x: 0, y: 0, width: 0, height: 0 },
          });

          // Update layout from manager
          set({ layout: dockManager.getLayout() });
        },

        cancelDrag: () => {
          set({
            dragState: 'idle',
            dragInfo: null,
            activeDropZone: null,
            dropZones: [],
            ghostPreview: { visible: false, x: 0, y: 0, width: 0, height: 0 },
          });
        },

        // Container Actions
        setHoveredContainer: (id) => set({ hoveredContainerId: id }),

        setActiveTab: (containerId, panelId) => {
          dockManager.setActiveTab(containerId, panelId);
          set({ layout: dockManager.getLayout() });
        },

        // Resize Actions
        startResize: (containerId, direction) => set({
          resizingContainerId: containerId,
          resizeDirection: direction,
        }),

        endResize: () => set({
          resizingContainerId: null,
          resizeDirection: null,
        }),

        // UI Actions
        setShowDropIndicators: (show) => set({ showDropIndicators: show }),
        setGhostPreview: (preview) => set({ ghostPreview: preview }),

        // Dock Actions
        addPanel: (panel, targetId, direction = 'center') => {
          dockManager.addPanel(panel, targetId, direction);
          set({ layout: dockManager.getLayout() });
        },

        removePanel: (panelId) => {
          dockManager.removePanel(panelId);
          set({ layout: dockManager.getLayout() });
        },

        dockPanel: (panelId, targetId, direction) => {
          dockManager.dockPanel(panelId, targetId, direction);
          set({ layout: dockManager.getLayout() });
        },

        floatPanel: (panelId, position) => {
          dockManager.floatPanel(panelId, position);
          set({ layout: dockManager.getLayout() });
        },

        updateFloatingPosition: (panelId, position) => {
          dockManager.updateFloatingPosition(panelId, position);
          set({ layout: dockManager.getLayout() });
        },

        updateFloatingSize: (panelId, size) => {
          dockManager.updateFloatingSize(panelId, size);
          set({ layout: dockManager.getLayout() });
        },

        moveToTab: (panelId, tabContainerId, insertIndex) => {
          dockManager.moveToTab(panelId, tabContainerId, insertIndex);
          set({ layout: dockManager.getLayout() });
        },

        updateContainerSize: (containerId, ratio) => {
          dockManager.updateContainerSize(containerId, ratio);
          set({ layout: dockManager.getLayout() });
        },

        updatePanelProps: (panelId, updates) => {
          dockManager.updatePanelProps(panelId, updates);
          set({ layout: dockManager.getLayout() });
        },

        // History Actions
        undo: () => {
          if (dockManager.undo()) {
            set({ layout: dockManager.getLayout() });
          }
        },

        redo: () => {
          if (dockManager.redo()) {
            set({ layout: dockManager.getLayout() });
          }
        },

        canUndo: () => dockManager.canUndo(),
        canRedo: () => dockManager.canRedo(),

        // Persistence
        saveLayout: (userId?: string) => dockManager.saveToStorage(userId ? `dock-layout-${userId}` : 'dock-layout'),
        loadLayout: (userId?: string) => {
          const loaded = dockManager.loadFromStorage(userId ? `dock-layout-${userId}` : 'dock-layout');
          if (loaded) {
            set({ layout: dockManager.getLayout() });
          }
          return loaded;
        },
        resetToDefaultLayout: () => {
          dockManager.resetToDefaultLayout();
          set({ layout: dockManager.getLayout() });
        },

        // Magnetic Snap - dock to workspace edge
        snapToWorkspaceEdge: (panelId, edge) => {
          // Use dockPanel to snap to root with specified direction
          if (edge === 'center') {
            dockManager.dockPanel(panelId, 'root', 'center');
          } else {
            dockManager.dockPanel(panelId, 'root', edge);
          }
          set({ layout: dockManager.getLayout() });
        },
      }),
      {
        name: 'dock-layout-storage',
        partialize: (state) => ({
          showDropIndicators: state.showDropIndicators,
        }),
      }
    ),
    { name: 'dock-layout-store' }
  )
);

// Subscribe to dock manager updates
let isUpdating = false;
dockManager.subscribe((layout) => {
  if (!isUpdating) {
    isUpdating = true;
    useDockLayoutStore.setState({ layout });
    isUpdating = false;
  }
});

export { useDockLayoutStore };
export default useDockLayoutStore;

/**
 * Drawing Store (Zustand)
 * Manages chart drawing tools and drawings state
 */

import { create } from "zustand";
import { debounce } from "lodash-es";

const DRAWINGS_STORAGE_KEY_PREFIX = "rtx5-drawings";
const LEGACY_DRAWINGS_STORAGE_KEY = "rtx5-drawings";
const TEMPLATES_STORAGE_KEY = "rtx5-drawing-templates";
const DEFAULT_DRAWING_SYMBOL = "default";

/**
 * Safe localStorage setter with quota exceeded handling
 * Trims to last 100 items if quota exceeded and retries
 * @param key - localStorage key
 * @param value - JSON string to store
 * @returns boolean indicating success
 */
function safeSetItem(key: string, value: string): boolean {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch (e) {
    if (e instanceof DOMException && e.name === "QuotaExceededError") {
      console.error("localStorage quota exceeded for key:", key);
      try {
        const parsed = JSON.parse(value);
        if (Array.isArray(parsed) && parsed.length > 100) {
          const trimmed = parsed.slice(-100);
          localStorage.setItem(key, JSON.stringify(trimmed));
          alert("Storage limit reached. Older drawings trimmed to last 100.");
          return false;
        }
      } catch (parseError) {
        console.error("Failed to parse or trim storage data:", parseError);
      }
    }
    console.error("Failed to save to localStorage:", e);
    return false;
  }
}

function resolveDrawingSymbol(symbol: string | null | undefined): string {
  if (!symbol || !symbol.trim()) return DEFAULT_DRAWING_SYMBOL;
  return symbol.trim().toUpperCase();
}

function getDrawingsStorageKey(symbol: string | null | undefined): string {
  return `${DRAWINGS_STORAGE_KEY_PREFIX}-${resolveDrawingSymbol(symbol)}`;
}

function getInitialDrawingSymbol(): string {
  try {
    return resolveDrawingSymbol(localStorage.getItem("rtx5_selected_symbol"));
  } catch {
    return DEFAULT_DRAWING_SYMBOL;
  }
}

const drawingSaveDebouncers = new Map<
  string,
  ReturnType<typeof debounce<(data: Drawing[]) => void>>
>();

function queueDrawingsSave(symbol: string | null | undefined, drawings: Drawing[]): void {
  const key = getDrawingsStorageKey(symbol);
  let debouncedSaver = drawingSaveDebouncers.get(key);

  if (!debouncedSaver) {
    debouncedSaver = debounce((data: Drawing[]) => {
      safeSetItem(key, JSON.stringify(data));
    }, 300);
    drawingSaveDebouncers.set(key, debouncedSaver);
  }

  debouncedSaver(drawings);
}

function commitDrawingsSave(symbol: string | null | undefined, drawings: Drawing[]): void {
  const key = getDrawingsStorageKey(symbol);
  const debouncedSaver = drawingSaveDebouncers.get(key);
  if (debouncedSaver) {
    debouncedSaver.cancel();
  }
  safeSetItem(key, JSON.stringify(drawings));
}

function clearDrawingsStorage(symbol: string | null | undefined): void {
  const key = getDrawingsStorageKey(symbol);
  drawingSaveDebouncers.get(key)?.cancel();
  localStorage.removeItem(key);
}

const debouncedSaveTemplates = debounce((data: any) => {
  safeSetItem(TEMPLATES_STORAGE_KEY, JSON.stringify(data));
}, 300);

export type DrawingType =
  | "cursor"
  | "crosshair"
  | "zoom-in"
  | "zoom-out"
  | "pan"
  | "trend-line"
  | "horizontal-line"
  | "vertical-line"
  | "ray"
  | "infinite-line"
  | "channel"
  | "parallel-channel"
  | "fib-retracement"
  | "fib-extension"
  | "rectangle"
  | "ellipse"
  | "polygon"
  | "freehand"
  | "pitchfork"
  | "text-label"
  | "callout"
  | "arrow"
  | "crosshair-ruler"
  | "label";

export type LineStyle = "solid" | "dashed" | "dotted";

export interface Point {
  x: number;
  y: number;
  price?: number;
  time?: string;
}

export interface Drawing {
  id: string;
  type: DrawingType;
  points: Point[];
  color: string;
  lineWidth: number;
  lineStyle: LineStyle;
  extendLeft: boolean;
  extendRight: boolean;
  showPriceLabels: boolean;
  visible: boolean;
  locked: boolean;
  rotation: number; // degrees
  zIndex: number;
  text?: string;
  label?: string;
}

export interface DrawingTemplate {
  id: string;
  name: string;
  drawings: Drawing[];
  createdAt: string;
}

interface DrawingState {
  drawings: Drawing[];
  selectedDrawingId: string | null;
  activeTool: DrawingType | null;
  templates: DrawingTemplate[];
  isDrawing: boolean;
  currentSymbol: string | null;

  // History for undo/redo
  undoStack: Drawing[][];
  redoStack: Drawing[][];

  // Actions
  addDrawing: (drawing: Omit<Drawing, "id" | "zIndex" | "locked" | "rotation">) => void;
  updateDrawing: (id: string, updates: Partial<Drawing>) => void;
  deleteDrawing: (id: string) => void;
  duplicateDrawing: (id: string) => void;
  setSelectedDrawing: (id: string | null) => void;
  setActiveTool: (tool: DrawingType | null) => void;
  setIsDrawing: (isDrawing: boolean) => void;
  toggleDrawingVisibility: (id: string) => void;
  toggleDrawingLock: (id: string) => void;
  bringToFront: (id: string) => void;
  sendToBack: (id: string) => void;
  clearAllDrawings: () => void;
  setSymbol: (symbol: string) => void;

  // Undo/Redo
  undo: () => void;
  redo: () => void;
  canUndo: () => boolean;
  canRedo: () => boolean;

  // Template actions
  saveTemplate: (name: string) => void;
  loadTemplate: (id: string) => void;
  deleteTemplate: (id: string) => void;
}

// Helper to get next z-index
const getNextZIndex = (drawings: Drawing[]): number => {
  if (drawings.length === 0) return 1;
  return Math.max(...drawings.map((d) => d.zIndex)) + 1;
};

// Type guard to validate Drawing objects
function isValidDrawing(obj: any): obj is Drawing {
  return (
    obj &&
    typeof obj.id === "string" &&
    typeof obj.type === "string" &&
    Array.isArray(obj.points) &&
    obj.points.every(
      (p: any) => typeof p.x === "number" && typeof p.y === "number",
    ) &&
    typeof obj.color === "string" &&
    typeof obj.lineWidth === "number" &&
    typeof obj.visible === "boolean" &&
    typeof obj.zIndex === "number"
  );
}

interface StorageLoadResult {
  found: boolean;
  drawings: Drawing[];
}

// Load from localStorage with JSON validation
const loadDrawingsFromKey = (key: string): StorageLoadResult => {
  try {
    const stored = localStorage.getItem(key);
    if (!stored) return { found: false, drawings: [] };

    const parsed = JSON.parse(stored);

    // Ensure parsed data is an array
    if (!Array.isArray(parsed)) {
      console.warn("Invalid drawings data: expected array, got", typeof parsed);
      return { found: true, drawings: [] };
    }

    // Filter with type guard and log invalid entries
    const validDrawings = parsed.filter((item: any, index: number) => {
      if (!isValidDrawing(item)) {
        console.warn(
          `Invalid drawing at index ${index}: missing or invalid required fields`,
          item,
        );
        return false;
      }
      return true;
    });

    // Warn if drawings were filtered out
    if (validDrawings.length < parsed.length) {
      console.warn(
        `Filtered out ${parsed.length - validDrawings.length} invalid drawing(s) from localStorage key: ${key}`,
      );
    }

    return { found: true, drawings: validDrawings };
  } catch (error) {
    console.error(`Failed to parse drawings from localStorage key: ${key}`, error);
    return { found: true, drawings: [] };
  }
};

const loadDrawingsForSymbol = (symbol: string | null | undefined): Drawing[] => {
  const symbolKey = getDrawingsStorageKey(symbol);
  const symbolDrawings = loadDrawingsFromKey(symbolKey);
  if (symbolDrawings.found) {
    return symbolDrawings.drawings;
  }

  // One-time migration from legacy global key to symbol-specific key
  const legacy = loadDrawingsFromKey(LEGACY_DRAWINGS_STORAGE_KEY);
  if (legacy.found) {
    if (legacy.drawings.length > 0) {
      safeSetItem(symbolKey, JSON.stringify(legacy.drawings));
    }
    localStorage.removeItem(LEGACY_DRAWINGS_STORAGE_KEY);
    return legacy.drawings;
  }

  return [];
};

const loadTemplatesFromStorage = () => {
  try {
    const stored = localStorage.getItem(TEMPLATES_STORAGE_KEY);
    return stored ? JSON.parse(stored) : [];
  } catch (error) {
    console.error("Failed to load templates from localStorage:", error);
    return [];
  }
};

export const useDrawingStore = create<DrawingState>((set, get) => ({
  drawings: loadDrawingsForSymbol(getInitialDrawingSymbol()),
  selectedDrawingId: null,
  activeTool: null,
  templates: loadTemplatesFromStorage(),
  isDrawing: false,
  currentSymbol: getInitialDrawingSymbol(),
  undoStack: [],
  redoStack: [],

  addDrawing: (drawing) => {
    const newDrawing: Drawing = {
      ...drawing,
      id: `drawing-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      zIndex: getNextZIndex(get().drawings),
      locked: false,
      rotation: 0,
    };

    set((state) => {
      const newDrawings = [...state.drawings, newDrawing];
      queueDrawingsSave(state.currentSymbol, newDrawings);
      return {
        drawings: newDrawings,
        undoStack: [...state.undoStack, state.drawings],
        redoStack: [],
      };
    });
  },

  updateDrawing: (id, updates) => {
    set((state) => {
      const newDrawings = state.drawings.map((d) =>
        d.id === id ? { ...d, ...updates } : d,
      );
      queueDrawingsSave(state.currentSymbol, newDrawings);
      return { drawings: newDrawings };
    });
  },

  deleteDrawing: (id) => {
    set((state) => {
      const newDrawings = state.drawings.filter((d) => d.id !== id);
      queueDrawingsSave(state.currentSymbol, newDrawings);
      return {
        drawings: newDrawings,
        selectedDrawingId:
          state.selectedDrawingId === id ? null : state.selectedDrawingId,
        undoStack: [...state.undoStack, state.drawings],
        redoStack: [],
      };
    });
  },

  duplicateDrawing: (id) => {
    const drawing = get().drawings.find((d) => d.id === id);
    if (!drawing) return;

    const duplicated: Drawing = {
      ...drawing,
      id: `drawing-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      zIndex: getNextZIndex(get().drawings),
      locked: false,
      points: drawing.points.map((p) => ({ ...p, x: p.x + 20, y: p.y + 20 })),
    };

    set((state) => {
      const newDrawings = [...state.drawings, duplicated];
      queueDrawingsSave(state.currentSymbol, newDrawings);
      return { drawings: newDrawings, selectedDrawingId: duplicated.id };
    });
  },

  setSelectedDrawing: (id) => set({ selectedDrawingId: id }),

  setActiveTool: (tool) => set({ activeTool: tool }),

  setIsDrawing: (isDrawing) => set({ isDrawing }),

  toggleDrawingVisibility: (id) => {
    set((state) => {
      const newDrawings = state.drawings.map((d) =>
        d.id === id ? { ...d, visible: !d.visible } : d,
      );
      queueDrawingsSave(state.currentSymbol, newDrawings);
      return { drawings: newDrawings };
    });
  },

  toggleDrawingLock: (id) => {
    set((state) => {
      const newDrawings = state.drawings.map((d) =>
        d.id === id ? { ...d, locked: !d.locked } : d,
      );
      queueDrawingsSave(state.currentSymbol, newDrawings);
      return { drawings: newDrawings };
    });
  },

  bringToFront: (id) => {
    const maxZ = Math.max(...get().drawings.map((d) => d.zIndex));
    get().updateDrawing(id, { zIndex: maxZ + 1 });
  },

  sendToBack: (id) => {
    get().updateDrawing(id, { zIndex: 0 });
    // Re-index all drawings
    set((state) => {
      const newDrawings = state.drawings
        .sort((a, b) => a.zIndex - b.zIndex)
        .map((d, idx) => ({ ...d, zIndex: idx + 1 }));
      queueDrawingsSave(state.currentSymbol, newDrawings);
      return { drawings: newDrawings };
    });
  },

  clearAllDrawings: () => {
    const state = get();
    set({
      drawings: [],
      selectedDrawingId: null,
      undoStack: [...state.undoStack, state.drawings],
      redoStack: [],
    });
    clearDrawingsStorage(state.currentSymbol);
  },

  setSymbol: (symbol) => {
    set((state) => {
      const normalizedSymbol = resolveDrawingSymbol(symbol);
      if (state.currentSymbol === normalizedSymbol) {
        return {};
      }

      commitDrawingsSave(state.currentSymbol, state.drawings);
      const nextDrawings = loadDrawingsForSymbol(normalizedSymbol);

      return {
        currentSymbol: normalizedSymbol,
        drawings: nextDrawings,
        selectedDrawingId: null,
        undoStack: [],
        redoStack: [],
      };
    });
  },

  // Undo / Redo
  undo: () => {
    set((state) => {
      if (state.undoStack.length === 0) return {};
      const previousDrawings = state.undoStack[state.undoStack.length - 1];
      const newUndoStack = state.undoStack.slice(0, -1);
      queueDrawingsSave(state.currentSymbol, previousDrawings);
      return {
        drawings: previousDrawings,
        undoStack: newUndoStack,
        redoStack: [...state.redoStack, state.drawings],
        selectedDrawingId: null,
      };
    });
  },

  redo: () => {
    set((state) => {
      if (state.redoStack.length === 0) return {};
      const nextDrawings = state.redoStack[state.redoStack.length - 1];
      const newRedoStack = state.redoStack.slice(0, -1);
      queueDrawingsSave(state.currentSymbol, nextDrawings);
      return {
        drawings: nextDrawings,
        undoStack: [...state.undoStack, state.drawings],
        redoStack: newRedoStack,
        selectedDrawingId: null,
      };
    });
  },

  canUndo: () => get().undoStack.length > 0,
  canRedo: () => get().redoStack.length > 0,

  saveTemplate: (name) => {
    const { drawings } = get();
    const template: DrawingTemplate = {
      id: `template-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      name,
      drawings: drawings.map((d) => ({ ...d })),
      createdAt: new Date().toISOString(),
    };

    set((state) => {
      const newTemplates = [...state.templates, template];
      debouncedSaveTemplates(newTemplates);
      return { templates: newTemplates };
    });
  },

  loadTemplate: (id) => {
    const template = get().templates.find((t) => t.id === id);
    if (!template) return;

    // Generate new IDs for loaded drawings
    const loadedDrawings: Drawing[] = template.drawings.map((d) => ({
      ...d,
      id: `drawing-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      zIndex: getNextZIndex(get().drawings) + (d.zIndex || 0),
    }));

    set((state) => {
      const newDrawings = [...state.drawings, ...loadedDrawings];
      queueDrawingsSave(state.currentSymbol, newDrawings);
      return { drawings: newDrawings };
    });
  },

  deleteTemplate: (id) => {
    set((state) => {
      const newTemplates = state.templates.filter((t) => t.id !== id);
      debouncedSaveTemplates(newTemplates);
      return { templates: newTemplates };
    });
  },
}));

/**
 * MT5 Direct Trading Store
 * Manages MT5 positions, account data, orders, and history
 * Auto-refreshes positions and account every 2 seconds
 */

import { create } from 'zustand';
import { devtools } from 'zustand/middleware';
import { api, MT5Position, MT5Account, MT5Order, MT5HistoryDeal, MT5Status } from '../services/api';

interface MT5Store {
  // Data
  positions: MT5Position[];
  account: MT5Account | null;
  orders: MT5Order[];
  history: MT5HistoryDeal[];
  status: MT5Status | null;

  // UI State
  connected: boolean;
  loading: boolean;
  error: string | null;
  autoRefresh: boolean;

  // Refresh interval reference
  _refreshInterval: NodeJS.Timeout | null;
  _wsUpdatesActive: boolean; // Track if WebSocket is delivering updates

  // Actions
  fetchPositions: (login?: number) => Promise<void>;
  fetchAccount: (login?: number) => Promise<void>;
  fetchOrders: (login?: number) => Promise<void>;

  // WebSocket setters (bypass HTTP polling)
  setPositionsFromWS: (positions: MT5Position[]) => void;
  setAccountFromWS: (account: MT5Account) => void;
  setOrdersFromWS: (orders: MT5Order[]) => void;
  fetchHistory: (params?: { login?: number; from?: number; to?: number; symbol?: string }) => Promise<void>;
  fetchStatus: () => Promise<void>;
  submitOrder: (order: {
    symbol: string;
    action: string;
    volume: number;
    price?: number;
    sl?: number;
    tp?: number;
    login?: number;
  }) => Promise<any>;
  closePosition: (ticket: number, volume?: number) => Promise<any>;
  modifyPosition: (ticket: number, sl: number, tp: number) => Promise<any>;

  // Control actions
  startAutoRefresh: (login?: number) => void;
  stopAutoRefresh: () => void;
  setAutoRefresh: (enabled: boolean) => void;
  clearError: () => void;
}

export const useMT5Store = create<MT5Store>()(
  devtools(
    (set, get) => ({
      // Initial state
      positions: [],
      account: null,
      orders: [],
      history: [],
      status: null,
      connected: false,
      loading: false,
      error: null,
      autoRefresh: false,
      _refreshInterval: null,
      _wsUpdatesActive: false,

      // Fetch positions
      fetchPositions: async (login?: number) => {
        set({ loading: true, error: null });
        try {
          const positions = await api.mt5.getPositions(login);
          set({ positions, loading: false });
        } catch (error: any) {
          set({
            error: error.message || 'Failed to fetch positions',
            loading: false,
            connected: false
          });
        }
      },

      // Fetch account info
      fetchAccount: async (login?: number) => {
        set({ loading: true, error: null });
        try {
          const account = await api.mt5.getAccount(login);
          set({ account, loading: false });
        } catch (error: any) {
          set({
            error: error.message || 'Failed to fetch account',
            loading: false,
            connected: false
          });
        }
      },

      // Fetch pending orders
      fetchOrders: async (login?: number) => {
        set({ loading: true, error: null });
        try {
          const orders = await api.mt5.getOrders(login);
          set({ orders, loading: false });
        } catch (error: any) {
          set({
            error: error.message || 'Failed to fetch orders',
            loading: false,
            connected: false
          });
        }
      },

      // Fetch trade history
      fetchHistory: async (params?: { login?: number; from?: number; to?: number; symbol?: string }) => {
        set({ loading: true, error: null });
        try {
          const history = await api.mt5.getHistory(params || {});
          set({ history, loading: false });
        } catch (error: any) {
          set({
            error: error.message || 'Failed to fetch history',
            loading: false,
            connected: false
          });
        }
      },

      // Fetch MT5 adapter status
      fetchStatus: async () => {
        try {
          const status = await api.mt5.getStatus();
          set({
            status,
            connected: status.connected,
            error: status.connected ? null : 'MT5 adapter not connected'
          });
        } catch (error: any) {
          set({
            status: null,
            connected: false,
            error: error.message || 'Failed to fetch status'
          });
        }
      },

      // Submit a new order
      submitOrder: async (order) => {
        set({ loading: true, error: null });
        try {
          const result = await api.mt5.submitOrder(order);
          set({ loading: false });

          // Refresh positions after order submission
          const { fetchPositions, fetchAccount } = get();
          await Promise.all([
            fetchPositions(order.login),
            fetchAccount(order.login)
          ]);

          return result;
        } catch (error: any) {
          set({
            error: error.message || 'Failed to submit order',
            loading: false
          });
          throw error;
        }
      },

      // Close a position
      closePosition: async (ticket: number, volume?: number) => {
        set({ loading: true, error: null });
        try {
          const result = await api.mt5.closePosition(ticket, volume);
          set({ loading: false });

          // Refresh positions after closing
          const { fetchPositions, fetchAccount } = get();
          await Promise.all([
            fetchPositions(),
            fetchAccount()
          ]);

          return result;
        } catch (error: any) {
          set({
            error: error.message || 'Failed to close position',
            loading: false
          });
          throw error;
        }
      },

      // Modify position SL/TP
      modifyPosition: async (ticket: number, sl: number, tp: number) => {
        set({ loading: true, error: null });
        try {
          const result = await api.mt5.modifyPosition(ticket, sl, tp);
          set({ loading: false });

          // Refresh positions after modification
          const { fetchPositions } = get();
          await fetchPositions();

          return result;
        } catch (error: any) {
          set({
            error: error.message || 'Failed to modify position',
            loading: false
          });
          throw error;
        }
      },

      // Start auto-refresh (poll every 2 seconds)
      startAutoRefresh: (login?: number) => {
        const { _refreshInterval } = get();

        // Clear existing interval if any
        if (_refreshInterval) {
          clearInterval(_refreshInterval);
        }

        // Initial fetch
        const { fetchPositions, fetchAccount, fetchOrders, fetchStatus } = get();
        Promise.all([
          fetchStatus(),
          fetchPositions(login),
          fetchAccount(login),
          fetchOrders(login)
        ]);

        // Start polling (only when WebSocket is not delivering updates)
        const interval = setInterval(() => {
          const state = get();
          // Skip HTTP polling if WebSocket is delivering real-time updates
          if (state._wsUpdatesActive) {
            console.log('[MT5Store] Skipping HTTP poll - WebSocket is active');
            return;
          }
          if (state.connected) {
            Promise.all([
              state.fetchPositions(login),
              state.fetchAccount(login)
            ]).catch(err => {
              console.error('[MT5Store] Auto-refresh error:', err);
            });
          }
        }, 2000);

        set({
          autoRefresh: true,
          _refreshInterval: interval
        });
      },

      // Stop auto-refresh
      stopAutoRefresh: () => {
        const { _refreshInterval } = get();
        if (_refreshInterval) {
          clearInterval(_refreshInterval);
        }
        set({
          autoRefresh: false,
          _refreshInterval: null
        });
      },

      // Toggle auto-refresh
      setAutoRefresh: (enabled: boolean) => {
        if (enabled) {
          get().startAutoRefresh();
        } else {
          get().stopAutoRefresh();
        }
      },

      // Clear error
      clearError: () => set({ error: null }),

      // WebSocket setters - update state directly from WebSocket data
      setPositionsFromWS: (positions: MT5Position[]) => {
        set({
          positions,
          _wsUpdatesActive: true,
          connected: true,
          error: null
        });
      },

      setAccountFromWS: (account: MT5Account) => {
        set({
          account,
          _wsUpdatesActive: true,
          connected: true,
          error: null
        });
      },

      setOrdersFromWS: (orders: MT5Order[]) => {
        set({
          orders,
          _wsUpdatesActive: true,
          connected: true,
          error: null
        });
      },
    }),
    { name: 'MT5Store' }
  )
);

export default useMT5Store;

/**
 * Optimized Market Data Store with Real-Time Aggregation
 * - Efficient selectors to prevent re-renders
 * - Real-time OHLCV calculation (Web Worker powered)
 * - VWAP and moving averages
 * - High/Low tracking
 * - Performance optimized with proper partitioning
 * PERFORMANCE FIX: OHLCV aggregation offloaded to Web Worker (50-100ms ΓåÆ <5ms main thread)
 */

import { create } from 'zustand';
import { devtools, subscribeWithSelector } from 'zustand/middleware';
import { getWorkerManager } from '../services/aggregationWorkerManager';

// ============================================
// Types
// ============================================

export interface Tick {
  symbol: string;
  bid: number;
  ask: number;
  spread: number;
  timestamp: number;
  lp?: string;
  volume?: number;
}

export interface OHLCV {
  timestamp: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

export interface SymbolStats {
  symbol: string;
  currentPrice: number;
  high24h: number;
  low24h: number;
  change24h: number;
  changePercent24h: number;
  volume24h: number;
  vwap: number;
  sma20: number;
  ema20: number;
  lastUpdate: number;
}

interface SymbolData {
  currentTick: Tick | null;
  previousTick: Tick | null;
  stats: SymbolStats | null;
  ohlcv1m: OHLCV[];
  ohlcv5m: OHLCV[];
  ohlcv15m: OHLCV[];
  ohlcv1h: OHLCV[];
  tickBuffer: Tick[];
  lastAggregation: number;
}

export interface CandleUpdate {
  symbol: string;
  timeframe: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  time: number;
}

interface MarketDataState {
  // Symbol data organized by symbol for efficient access
  symbolData: Record<string, SymbolData>;

  // Subscription tracking
  subscribedSymbols: Set<string>;

  // Actions
  updateTick: (symbol: string, tick: Tick) => void;
  updateCandle: (update: CandleUpdate) => void;
  updateBulkTicks: (ticks: Tick[]) => void;
  subscribeSymbol: (symbol: string) => void;
  unsubscribeSymbol: (symbol: string) => void;
  aggregateOHLCV: (symbol: string) => void;
  clearSymbolData: (symbol: string) => void;
  clearAllData: () => void;

  // Selectors (computed properties)
  getCurrentTick: (symbol: string) => Tick | null;
  getSymbolStats: (symbol: string) => SymbolStats | null;
  getOHLCV: (symbol: string, timeframe: '1m' | '5m' | '15m' | '1h') => OHLCV[];
}

// ============================================
// Helper Functions
// ============================================

function createEmptySymbolData(): SymbolData {
  return {
    currentTick: null,
    previousTick: null,
    stats: null,
    ohlcv1m: [],
    ohlcv5m: [],
    ohlcv15m: [],
    ohlcv1h: [],
    tickBuffer: [],
    lastAggregation: 0,
  };
}

function calculateVWAP(ticks: Tick[]): number {
  if (ticks.length === 0) return 0;

  let totalVolume = 0;
  let totalValue = 0;

  ticks.forEach((tick) => {
    const price = (tick.bid + tick.ask) / 2;
    const volume = tick.volume || 1;
    totalValue += price * volume;
    totalVolume += volume;
  });

  return totalVolume > 0 ? totalValue / totalVolume : 0;
}

function calculateSMA(prices: number[], period: number): number {
  if (prices.length < period) return prices[prices.length - 1] || 0;

  const slice = prices.slice(-period);
  const sum = slice.reduce((acc, price) => acc + price, 0);
  return sum / period;
}

function calculateEMA(prices: number[], period: number, prevEMA?: number): number {
  if (prices.length === 0) return 0;
  if (prices.length < period) return calculateSMA(prices, prices.length);

  const latestPrice = prices[prices.length - 1];
  if (!prevEMA) {
    return calculateSMA(prices, period);
  }

  const multiplier = 2 / (period + 1);
  return (latestPrice - prevEMA) * multiplier + prevEMA;
}

function aggregateTicksToOHLCV(ticks: Tick[], timeframeMs: number): OHLCV[] {
  if (ticks.length === 0) return [];

  const ohlcvMap = new Map<number, OHLCV>();

  ticks.forEach((tick) => {
    const bucketTime = Math.floor(tick.timestamp / timeframeMs) * timeframeMs;
    const midPrice = (tick.bid + tick.ask) / 2;
    const volume = tick.volume || 1;

    if (!ohlcvMap.has(bucketTime)) {
      ohlcvMap.set(bucketTime, {
        timestamp: bucketTime,
        open: midPrice,
        high: midPrice,
        low: midPrice,
        close: midPrice,
        volume: volume,
      });
    } else {
      const ohlcv = ohlcvMap.get(bucketTime)!;
      ohlcv.high = Math.max(ohlcv.high, midPrice);
      ohlcv.low = Math.min(ohlcv.low, midPrice);
      ohlcv.close = midPrice;
      ohlcv.volume += volume;
    }
  });

  return Array.from(ohlcvMap.values()).sort((a, b) => a.timestamp - b.timestamp);
}

function calculateStats(
  symbol: string,
  currentTick: Tick,
  previousTick: Tick | null,
  tickBuffer: Tick[],
  ohlcv1h: OHLCV[]
): SymbolStats {
  const now = Date.now();
  const twentyFourHoursAgo = now - 24 * 60 * 60 * 1000;

  // Get ticks from last 24 hours
  const ticks24h = tickBuffer.filter((t) => t.timestamp >= twentyFourHoursAgo);

  // Calculate high/low
  let high24h = currentTick.bid;
  let low24h = currentTick.ask;
  let volume24h = 0;

  ticks24h.forEach((tick) => {
    high24h = Math.max(high24h, tick.bid, tick.ask);
    low24h = Math.min(low24h, tick.bid, tick.ask);
    volume24h += tick.volume || 0;
  });

  // Calculate change
  const currentPrice = (currentTick.bid + currentTick.ask) / 2;
  const price24hAgo = ticks24h.length > 0 ? (ticks24h[0].bid + ticks24h[0].ask) / 2 : currentPrice;
  const change24h = currentPrice - price24hAgo;
  const changePercent24h = price24hAgo > 0 ? (change24h / price24hAgo) * 100 : 0;

  // Calculate VWAP
  const vwap = calculateVWAP(ticks24h);

  // Calculate moving averages from OHLCV data
  const closePrices = ohlcv1h.map((candle) => candle.close);
  const sma20 = calculateSMA(closePrices, 20);
  const ema20 = calculateEMA(closePrices, 20);

  return {
    symbol,
    currentPrice,
    high24h,
    low24h,
    change24h,
    changePercent24h,
    volume24h,
    vwap,
    sma20,
    ema20,
    lastUpdate: now,
  };
}

// ============================================
// Store
// ============================================

export const useMarketDataStore = create<MarketDataState>()(
  subscribeWithSelector(
    devtools(
      (set, get) => ({
        symbolData: {},
        subscribedSymbols: new Set(),

        updateTick: (symbol, tick) => {
          set((state) => {
            const data = state.symbolData[symbol] || createEmptySymbolData();

            // Update ticks
            const previousTick = data.currentTick;
            const currentTick = tick;

            // Add to tick buffer (keep last 10,000 ticks per symbol)
            const tickBuffer = [...data.tickBuffer, tick];
            if (tickBuffer.length > 10000) {
              tickBuffer.shift();
            }

            // PERFORMANCE FIX: Aggregate OHLCV in Web Worker (async, non-blocking)
            const now = Date.now();
            const shouldAggregate = now - data.lastAggregation > 60000;

            const ohlcv1m = data.ohlcv1m;
            const ohlcv5m = data.ohlcv5m;
            const ohlcv15m = data.ohlcv15m;
            const ohlcv1h = data.ohlcv1h;

            if (shouldAggregate && tickBuffer.length > 0) {
              // Offload to Web Worker (non-blocking)
              const worker = getWorkerManager();
              worker.aggregateMultipleTimeframes(
                tickBuffer,
                [
                  { name: '1m', ms: 60 * 1000 },
                  { name: '5m', ms: 5 * 60 * 1000 },
                  { name: '15m', ms: 15 * 60 * 1000 },
                  { name: '1h', ms: 60 * 60 * 1000 },
                ],
                (results) => {
                  // Update store with worker results (async)
                  set((state) => {
                    const currentData = state.symbolData[symbol];
                    if (!currentData) return state;

                    return {
                      symbolData: {
                        ...state.symbolData,
                        [symbol]: {
                          ...currentData,
                          ohlcv1m: [...currentData.ohlcv1m, ...results['1m']].slice(-1000),
                          ohlcv5m: [...currentData.ohlcv5m, ...results['5m']].slice(-500),
                          ohlcv15m: [...currentData.ohlcv15m, ...results['15m']].slice(-300),
                          ohlcv1h: [...currentData.ohlcv1h, ...results['1h']].slice(-200),
                        },
                      },
                    };
                  });
                }
              );
            }

            // Calculate stats
            const stats = calculateStats(symbol, currentTick, previousTick, tickBuffer, ohlcv1h);

            return {
              symbolData: {
                ...state.symbolData,
                [symbol]: {
                  ...data,
                  currentTick,
                  previousTick,
                  stats,
                  tickBuffer,
                  lastAggregation: shouldAggregate ? now : data.lastAggregation,
                },
              },
            };
          });

          // ΓöÇΓöÇΓöÇ Cross-store sync: TradingChart polls useAppStore.ticks ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
          // Dynamically import to avoid circular dep. Fire-and-forget.
          import('../store/useAppStore').then(({ useAppStore }) => {
            useAppStore.getState().setTick(symbol, tick as any);
          }).catch(() => {/* ignore */});
        },


        updateCandle: (update) => {
          console.log(`[Store updateCandle] ${update.symbol} ${update.timeframe} O=${update.open} H=${update.high} L=${update.low} C=${update.close} time=${update.time}`);
          set((state) => {
            const data = state.symbolData[update.symbol] || createEmptySymbolData();

            // Only handling 1m for now as per backend
            if (update.timeframe === 'M1') {
              const ohlcv = data.ohlcv1m;
              const lastCandle = ohlcv[ohlcv.length - 1];

              const newOHLCV = [...ohlcv];
              if (lastCandle && lastCandle.timestamp === update.time * 1000) {
                // Update existing
                newOHLCV[newOHLCV.length - 1] = {
                  timestamp: update.time * 1000,
                  open: update.open,
                  high: update.high,
                  low: update.low,
                  close: update.close,
                  volume: update.volume
                };
              } else {
                // New candle
                newOHLCV.push({
                  timestamp: update.time * 1000,
                  open: update.open,
                  high: update.high,
                  low: update.low,
                  close: update.close,
                  volume: update.volume
                });
                if (newOHLCV.length > 1000) newOHLCV.shift();
              }

              console.log(`[Store updateCandle] ${update.symbol} now has ${newOHLCV.length} candles`);

              return {
                symbolData: {
                  ...state.symbolData,
                  [update.symbol]: {
                    ...data,
                    ohlcv1m: newOHLCV,
                    // Note: We don't update lastAggregation here as this is from server
                  }
                }
              };
            }
            return state;
          });
        },

        updateBulkTicks: (ticks) => {
          // Group ticks by symbol for efficient processing
          const ticksBySymbol = ticks.reduce((acc, tick) => {
            if (!acc[tick.symbol]) {
              acc[tick.symbol] = [];
            }
            acc[tick.symbol].push(tick);
            return acc;
          }, {} as Record<string, Tick[]>);

          // Update each symbol
          Object.entries(ticksBySymbol).forEach(([symbol, symbolTicks]) => {
            // Process only the latest tick for each symbol
            const latestTick = symbolTicks[symbolTicks.length - 1];
            get().updateTick(symbol, latestTick);
          });
        },

        subscribeSymbol: (symbol) => {
          set((state) => ({
            subscribedSymbols: new Set([...state.subscribedSymbols, symbol]),
            symbolData: {
              ...state.symbolData,
              [symbol]: state.symbolData[symbol] || createEmptySymbolData(),
            },
          }));
        },

        unsubscribeSymbol: (symbol) => {
          set((state) => {
            const newSubscribed = new Set(state.subscribedSymbols);
            newSubscribed.delete(symbol);
            return { subscribedSymbols: newSubscribed };
          });
        },

        aggregateOHLCV: (symbol) => {
          set((state) => {
            const data = state.symbolData[symbol];
            if (!data || data.tickBuffer.length === 0) return state;

            const ohlcv1m = aggregateTicksToOHLCV(data.tickBuffer, 60 * 1000);
            const ohlcv5m = aggregateTicksToOHLCV(data.tickBuffer, 5 * 60 * 1000);
            const ohlcv15m = aggregateTicksToOHLCV(data.tickBuffer, 15 * 60 * 1000);
            const ohlcv1h = aggregateTicksToOHLCV(data.tickBuffer, 60 * 60 * 1000);

            return {
              symbolData: {
                ...state.symbolData,
                [symbol]: {
                  ...data,
                  ohlcv1m,
                  ohlcv5m,
                  ohlcv15m,
                  ohlcv1h,
                  lastAggregation: Date.now(),
                },
              },
            };
          });
        },

        clearSymbolData: (symbol) => {
          set((state) => {
            const newData = { ...state.symbolData };
            delete newData[symbol];
            return { symbolData: newData };
          });
        },

        clearAllData: () => {
          set({
            symbolData: {},
            subscribedSymbols: new Set(),
          });
        },

        // Selector functions
        getCurrentTick: (symbol) => {
          const data = get().symbolData[symbol];
          return data?.currentTick || null;
        },

        getSymbolStats: (symbol) => {
          const data = get().symbolData[symbol];
          return data?.stats || null;
        },

        getOHLCV: (symbol, timeframe) => {
          const data = get().symbolData[symbol];
          if (!data) return [];

          switch (timeframe) {
            case '1m':
              return data.ohlcv1m;
            case '5m':
              return data.ohlcv5m;
            case '15m':
              return data.ohlcv15m;
            case '1h':
              return data.ohlcv1h;
            default:
              return [];
          }
        },
      }),
      { name: 'MarketDataStore' }
    )
  )
);

// ============================================
