            ...template,
            id: `template-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            createdAt: Date.now(),
            isDefault: false,
          };

          set((state) => ({
            templates: [...state.templates, newTemplate],
          }));

          return newTemplate;
        },

        loadTemplate: (id) => {
          const state = get();
          return state.templates.find((t) => t.id === id) || null;
