      expect(history).toHaveLength(100);
    });
  });

  describe('subscribe', () => {
    it('should return an unsubscribe function', () => {
      const handler = vi.fn();
      const unsubscribe = commandBus.subscribe('ZOOM_IN', handler);

      expect(typeof unsubscribe).toBe('function');
    });

